	\subsection{Proofs in Section~\ref{section: Preliminaries}} \label{appendix: technical proofs in Preliminaries}





	\begin{proof}[Proof of Theorem~\ref{theorem: Compounding Effect Derivation}]
		We begin by noting that the ETF’s daily return is  
		$
		X_t^{\rm ETF} =  X_t
		$
		and LETF’s daily return is to include fees and tracking error:
		$
		X_t^{\rm LETF} =  \beta X_t - f + e_t,
		$
		where \(\beta \in \mathbb{Z} \setminus \{0\}\) is the leverage ratio, \(f\) is a daily fee (incorporating expense and transaction costs), and \(e_t\) is a tracking error with \(|e_t| \le M\) and \(\mathbb{E}[e_t] = \mathbb{E}[e_t X_s] = \mathbb{E}[e_t e_s] = 0\) for \(t \ne s\). Assume also \(|X_t|, |f| \le M\), for some \(M \ll 1\).
		Define:
		\[
		A_t := \beta X_t - f + e_t, \quad B_t := X_t.
		\]
		Hence, the compounding effect is:
		$
		\mathtt{CE}_n := R_n^{{\rm LETF}} - \beta R_n^{{\rm ETF}}
		$ 
		where the cumulative returns over $n$ days are:
		\[
		R_n^{\mathrm{LETF}} = \prod_{t=1}^n (1 + A_t) - 1 \; \text{ and } \; R_n^{\mathrm{ETF}} = \prod_{t=1}^n (1 + B_t) - 1.
		\]
		Using the fact that 
		$
		\prod_{t=1}^n (1 + Z_t) = 1 + \sum_{t=1}^n Z_t + \sum_{1 \le t < s \le n} Z_t Z_s + \mathfrak{R}_n$ with $ \mathbb{E}[| \mathfrak{R}_n| ] \le C^\prime n^3 M^3
		$ for some $C^\prime >0$,
		it follows that $R_n^{\mathrm{LETF}}$ and $R_n^{\mathrm{ETF}}$ satisfies
		\begin{align*}
			R_n^{\rm LETF} &= \sum_{t=1}^n A_t + \sum_{1 \le t < s \le n} A_t A_s + \mathfrak{R}_n^{(A)}, \\
			R_n^{\rm ETF}  &= \sum_{t=1}^n B_t + \sum_{1 \le t < s \le n} B_t B_s + \mathfrak{R}_n^{(B)},
		\end{align*}
		and therefore
		\begin{align} \label{eq: CE_n formula}
			\mathtt{CE}_n = R_n^{\rm LETF} - \beta R_n^{\rm ETF} =   \sum_{t=1}^n (A_t - \beta B_t) + \sum_{1 \le t < s \le n} (A_t A_s - \beta B_t B_s) + \mathfrak{R}_n,
		\end{align}
		where $ \mathfrak{R}_n := \mathfrak{R}_n^{(A)} - \beta \mathfrak{R}_n^{(B)} $, and \(\mathbb{E}[|\mathfrak{R}_n|] \le C n^3 M^3 \) for some constant $C >0$ by triangle inequality.
		Note that the first-order term in Equation~\eqref{eq: CE_n formula} can be computed as follows:
		\[
		\sum_{t=1}^n (A_t - \beta B_t) = \sum_{t=1}^n (\beta X_t - f + e_t - \beta X_t) = -nf + \sum_{t=1}^n e_t.
		\]
		Taking expectations and using \(\mathbb{E}[e_t] = 0\), we obtain:
		$
		\mathbb{E}\left[ \sum_{t=1}^n (A_t - \beta B_t) \right] = -nf.
		$
		Next, for $t\neq s$, we expand:
		\begin{align*}
			A_t A_s 
			&= (\beta X_t - f + e_t)(\beta X_s - f + e_s)\\
			&= \beta^2 X_t X_s - \beta f (X_t + X_s) + f^2 + \beta X_t e_s + \beta X_s e_t - f(e_t + e_s) + e_t e_s.
		\end{align*}
		Thus,
		$
		A_t A_s - \beta B_t B_s 
		= \beta(\beta - 1) X_t X_s - \beta f (X_t + X_s) + f^2 + \beta (X_t e_s + X_s e_t) - f (e_t + e_s) + e_t e_s.
		$
		Taking the expectation yields
		\[
		\mathbb{E}[A_t A_s - \beta B_t B_s] = \beta(\beta - 1) \gamma_{|t-s|} - 2\beta f \mu + f^2.
		\]
		where the equality holds by using the facts that \(\mathbb{E}[X_t X_s] = \gamma_{|t-s|}\) from strict stationarity,  \(\mathbb{E}[e_t] = \mathbb{E}[e_t X_s] = \mathbb{E}[e_t e_s] = 0\) for \(t \ne s\), and \(\mu := \mathbb{E}[X_t]\).
		Summing over all \(1 \le t < s \le n\), we group terms by lag \(k = s - t\), which contributes \((n-k)\) terms per lag. This gives:
		\[
		\mathbb{E} \left[	\sum_{1 \le t < s \le n}A_t A_s - \beta B_t B_s \right]
		= \sum_{1 \le t < s \le n} \mathbb{E}[A_t A_s - \beta B_t B_s]
		= \sum_{k=1}^{n-1} (n-k) \left[ \beta(\beta - 1) \gamma_k - 2\beta f \mu + f^2 \right].
		\]
		Putting everything together:
		\[
		\mathbb{E}[\mathtt{CE}_n]
		= -nf + \sum_{k=1}^{n-1} (n-k) \left[ \beta(\beta - 1) \gamma_k - 2\beta f \mu \right]+ \binom{n}{2} f^2 + O(n^3 M^3). \qedhere
		\]
	\end{proof}


	\begin{proof}[Proof of Lemma~\ref{lemma: Positive Expected Compounding Effect}] 
		To prove the desired positivity, we proceed with a proof by induction. 
		Firstly, for $n=1$, note that
		$
		\mathbb{E}[\mathtt{CE}_1] = 	\mathbb{E}\left[ R_{1}^{\rm LETF, \beta} - \beta R_{1}^{\rm ETF} \right] = [(1 + \beta \mu)^{1} - 1] - \beta[(1+ \mu)^{1} - 1 ] =0.
		%=  \beta\mu  -\beta \mu = 0 \geq 0.
		$
		%	This, the claim holds for~$n=1.$
		Now, assume the statement holds for~$n = k \geq 1$. That is,
		$
		[(1 + \beta \mu)^{k}-1]-\beta[(1+\mu)^{k}-1] \geq 0, 
		$
		which is equivalent to
		$
		(1 + \beta\mu)^{k} + \beta - 1 \geq \beta(1+\mu)^{k}.
		$
		We must show that the statement holds for $n = k+1$. Indeed, observe that
		\begin{align}
			(1 + \beta\mu)^{k+1}-1 
			=&(1+\beta\mu)(1+\beta\mu)^{k}-1\nonumber\\
			=&(1+\beta\mu)[(1+\beta\mu)^{k}+\beta-1]-\beta-\beta^{2}\mu+\beta\mu\nonumber\\
			\geq&(1+\beta\mu)[\beta(1+\mu)^{k}]-\beta-\beta^{2}\mu+\beta\mu\nonumber
		\end{align}
		where inequality is held by invoking the inductive hypotheses. Hence, it follows that
		\begin{align}
			(1 + \beta\mu)^{k+1}-1 
			\geq&(1+\beta\mu)[\beta(1+\mu)^{k}]-\beta-\beta^{2}\mu+\beta\mu\nonumber\\
			=&(1+ \mu +(\beta-1)\mu)[\beta(1+\mu)^{k}]-\beta-\beta^{2}\mu+\beta\mu\nonumber\\
			=&\beta(1+\mu)^{k+1}+\beta(\beta-1)\mu(1+\mu)^{k}-\beta-\beta^{2}\mu+\beta\mu\nonumber\\
			=&\beta[(1+\mu)^{k+1}-1]+\beta(\beta-1)\mu(1+\mu)^{k}+\beta\mu(1-\beta)\nonumber\\
			=&\beta[(1+\mu)^{k+1}-1]+\beta\mu(\beta-1)[(1+\mu)^{k}-1].
			% =&R.H.S+\beta\mu(\beta-1)[(1+\mu)^{k}-1]\nonumber.
		\end{align}
		Note that if $\beta \mu (\beta-1)[(1+\mu)^{k}-1] \geq 0$, then we are done. 
		Therefore, to complete the proof, it remains to prove $\beta \mu( \beta-1)[(1+\mu)^{k}-1] \geq 0$. Set an auxiliary function 
		$
		f(\beta, \mu) := \beta\mu(\beta-1)[(1+\mu)^{k}-1],
		$
		then, we consider the following four cases:

		\emph{Case 1.} When $\beta > 1$ and $\mu \geq 0$, it follows that $\beta \mu \geq 0$, $\beta - 1 > 0$, and $[(1 + \mu)^{k+1} - 1] \geq 0$, leading to $f(\beta, \mu) \geq 0$.

		\emph{Case 2.} When $\beta > 1$ and $\mu < 0$, we have $\beta \mu < 0$, $\beta - 1 > 0$, and $[(1 + \mu)^{k+1} - 1] < 0$, resulting in $f(\beta, \mu) > 0$.

		\emph{Case 3.} When $\beta \leq -1$ and $\mu \geq 0$, it follows that $\beta \mu \leq 0$, $\beta - 1 < 0$, and $[(1 + \mu)^{k+1} - 1] \geq 0$, which implies $f(\beta, \mu) \geq 0$.

		\emph{Case 4.} When $\beta \leq -1$ and $\mu < 0$, we obtain $\beta \mu > 0$, $\beta - 1 < 0$, and $[(1 + \mu)^{k+1} - 1] < 0$, leading to $f(\beta, \mu) \geq 0$ again.

		Combined with the four cases above, we conclude that $f(\beta, \mu) \geq 0$ for all cases. Thus, the given statement holds for any $n \in \mathbb{N}$ and $\beta \in \mathbb{Z} \setminus \{0,1\}$, which proves that the expected compounding effect is always positive.
	\end{proof}




