	\subsection{Compounding Effect for Serially Correlated AR(1) Returns} \label{appendix: compounding effect for serially correlated returns}
	Below, we shall work with the AR(1) model for $\{X_t: t \geq 1\}$.
	Let $\beta \in \mathbb{Z} \setminus \{0,1\}.$ For the two-period case, we have that:  $(i)$ If $\phi >0$, then  $\mathbb{E}[ \mathtt{CE}_2 ] >0$ and
	$(ii)$ If $\phi <0$, then $ \mathbb{E}[ \mathtt{CE}_2] < 0$.
	To see this, we begin by noting that
	\begin{align*}
		\mathtt{CE}_2 
		&= [(1+\beta X_1)(1+\beta X_2) - 1] - \beta [ (1+X_1)(1+X_2)-1] \\
		%	&= [ \beta X_1 + \beta X_2 + \beta^2 X_1 X_2] - \beta [ X_1 + X_2 + X_1X_2]\\
		&=\beta( \beta - 1) X_1 X_2 .
	\end{align*}
	Taking the expectation on both sides yields:
	$
	\mathbb{E}[ \mathtt{CE}_2  ]
	= \beta( \beta - 1) \mathbb{E}[ X_1 X_2]
	= \beta (\beta - 1) \phi \frac{\sigma}{1-\phi^2}.  
	$
	Note that $\sigma > 0$, and for $\beta \in \mathbb{Z} \setminus \{0, 1\}$, the product $\beta (\beta - 1) >0$.  Therefore, to determine the sign of the expected difference, it suffices to check the sign of the $\phi$. Specifically, for $\phi >0$, then  $\mathbb{E}[  \mathtt{CE}_2  ] > 0$.
	On the other hand, for $\phi < 0$, then $\mathbb{E}[  \mathtt{CE}_2 ] < 0$. The following proof extends this result to the multi-period case.




	\begin{proof}[Proof of Lemma~\ref{lemma: n-period case for serially correlated AR(1) returns}]   

		Given that $\beta \in \mathbb{Z}\setminus\{0, 1\}$, we observe that
		\begin{align*}
			\mathbb{E} [\mathtt{CE}_n ] 
			&= \mathbb{E} \left[\left(\prod_{i=1}^n (1+\beta X_i) - 1\right) - \beta \left( \prod_{i=1}^n (1+X_i) - 1\right)\right] \\
			&= \mathbb{E}  \left[(\beta^2 - \beta)\sum_{i \neq j} X_i X_j + (\beta^3 - \beta)\sum_{i \neq j \neq k} X_i X_j X_k + \cdots + (\beta^n - \beta)\sum_{i \neq j \neq \cdots \neq n} X_i X_j X_k \cdots X_n \right]\\
			&= \mathbb{E}  \left[(\beta^2 - \beta)\sum_{i \neq j} X_i X_j + \text{higher-order terms in $X_i$} \right].
		\end{align*}
		Since $ |X_i| < m$ for some $m \in (0,1)$, the first quantity dominates, and the higher-order product term is of smaller order compared to the second-order term for sufficiently small returns. Therefore, we~obtain
		% $X_i \rightarrow 0 \text{ for } n \geq 3 $$
		\begin{align}
			\mathbb{E} [ \mathtt{CE}_n] 
			&\approx \mathbb{E} \left[ (\beta^2 - \beta)\sum_{i \neq j} X_i X_j\right] \notag \\
			&= (\beta^2 - \beta)\left( \sum_{i=1}^{n-1} \mathbb{E}[X_i X_{i+1}] + \sum_{i=1}^{n-2} \mathbb{E}[X_i X_{i+2}] + \cdots + \sum_{i=1}^{1} \mathbb{E} [X_i X_{i+(n-1)}]\right), \notag \\
			&= (\beta^2 - \beta)\frac{\sigma^2}{1-\phi^2}\left( \sum_{i=1}^{n-1} \phi + \sum_{i=1}^{n-2} \phi^2 + \cdots + \sum_{i=1}^{1} \phi^{n-1}\right), \notag \\
			&= (\beta^2 - \beta)\frac{\sigma^2}{1-\phi^2}\phi\left[(n-1) + (n-2)\phi + \cdots + \phi^{n-2}\right] \gtrless 0 \text{ if } \phi \gtrless 0  \label{ineq: proof of lemma 3}
		\end{align}
		where $|\phi| < 1$. Note that since $\beta \in \mathbb{Z} \setminus \{0,1\}$, it follows that $(\beta^2 - \beta) = \beta (\beta - 1) >0$.
		To see inequality~\eqref{ineq: proof of lemma 3}, let $Q:=(n-1)+(n-2)\phi+\cdots+\phi^{n-2}$.
		% and $\phi Q=(n-1)\phi+(n-2)\phi^2+\cdots+\phi^{n-1}$.
		Then, for sufficiently large $n$, $\mathbb{E} [ \mathtt{CE}_n ] = (\beta^2 - \beta)\frac{\sigma^2}{1-\phi^2}\phi Q$,  it is readily verified that
		$
		\phi Q - Q = \phi + \phi^2 + \cdots + \phi^{n-2} + \phi^{n-1} - (n-1).
		$
		Therefore, for all $|\phi| < 1$,
		\begin{align*}
			Q &=  \frac{n -1+\phi+\phi^2+\cdots+\phi^{n-2}+\phi^{n-1}}{1-\phi} \\
			&= \frac{(1-1)+(1-\phi)+(1-\phi^2)+\cdots+(1-\phi^{n-2})+(1-\phi^{n-1})}{1-\phi} > 0.
		\end{align*}
		Therefore, $\mathbb{E} [ \mathtt{CE}_n ] \gtrless 0$ if $\phi \gtrless 0$.
	\end{proof}



	\subsection{Compounding Effect for Continuous-Time Model} \label{appendix: Compounding Effect for Continuous-Time Return Model}



	\begin{proof}[Proof of Equation~\eqref{eq: LETF L_t_regime_switching}] 
		Begin by observing that
		\begin{align*}
			\frac{d L_t }{L_t} 
			&= \beta \frac{dS_t}{S_t}   - fdt
			%		&= \beta[ \mu_t dt + \sigma_t  dW_t ]  - fdt\\
			= (\beta \mu_{Z_t}  - f)dt + \beta \sigma_{Z_t} dW_t.
		\end{align*}
		Given that $ f(L_t) := \log L_t $, It\^o's Lemma states:
		\begin{align*}
			d \log(L_t )
			& = \left( \frac{1}{ L_t} L_t( \beta \mu_{Z_t} - f) - \frac{1}{2} \frac{1}{ L_t^2} (L_t^2 \beta^2 \sigma_{Z_t}^2) \right) dt + \frac{1}{ L_t} L_t \beta \sigma_{Z_t} dW_t\\
			& = \left( (\beta \mu_{Z_t}-f) - \frac{1}{2}  \beta^2 \sigma_{Z_t}^2 \right) dt +  \beta \sigma_{Z_t}dW_t.
		\end{align*}
		Hence, it has a solution
		\begin{align*}
			L_t 
			&= L_0 \exp\left( \int_0^t \left(  \beta \mu_{Z_s} - \frac{1}{2}  \beta^2 \sigma_{Z_s}^2 \right) ds - ft +  \beta \int_0^t \sigma_{Z_s} dW_s \right)
			%		&= L_0 \exp\left( \int_0^t   (\beta \mu_s  - \tfrac{\beta}{2}\sigma_s^2) ds  +  \beta \int_0^t \sigma_s dW_s \right)	\exp\left( \int_0^t \left(   \tfrac{\beta}{2}\sigma_s^2- \frac{1}{2}  \beta^2 \sigma_s^2 \right) ds - ft  \right)\\
			%		&= L_0 \left( \frac{S_t}{S_0} \right)^\beta \exp\left( \frac{\beta - \beta^2}{2}\int_0^t    \sigma_s^2 ds - ft  \right)
		\end{align*}
		and the proof is complete.
	\end{proof}




	\begin{proof}[Proof of Theorem~\ref{theorem: expected compounding effect for diffusion prices_regime}]   
		Note that 
		$$
		\mathbb{E}[\mathtt{CE}_t] = \mathbb{E}[\exp(Y_t)] - \beta \mathbb{E}[\exp(X_t)] + (\beta - 1),
		$$
		where $Y_t  = \int_0^t \left(  \beta \mu_{Z_s} - \frac{1}{2}  \beta^2 \sigma_{Z_s}^2 \right) ds - ft +  \beta \int_0^t \sigma_{Z_s} dW_s$ and $X_t = \int_0^t \left( \mu_{Z_s}  - \frac{1}{2}   \sigma_{Z_s}^2 \right) ds + \int_0^t \sigma_{Z_s} dW_s.$
		We approximate the expectation using a regime-mixture approximation based on the occupation measure:
		Let $\pi_j(t) := \mathbb{E}\left[ \frac{1}{t} \int_0^t \mathbb{1}_{\{Z_s = j\}} ds \right]$ for each $j=1,\dots,M$. This is the expected proportion of time the process spends in regime $j$ over $[0,t]$.
		If $Z_t = j$, then
		\begin{align*}
			X_t^{(j)} 
			&=\int_0^t \left( \mu_j  - \frac{1}{2}   \sigma_j^2 \right) ds + \int_0^t \sigma_j dW_s\\
			& =  \left( \mu_j  - \frac{1}{2}   \sigma_j^2 \right)t + \sigma_j W_t \sim \mathcal{N}\left(\left( \mu_j  - \frac{1}{2}   \sigma_j^2 \right)t, \sigma_j^2 t \right)
		\end{align*}
		and
		\begin{align*}
			Y_t^{(j)} 
			&= \int_0^t \left(  \beta \mu_{j} - \frac{1}{2}  \beta^2 \sigma_{j}^2 \right) ds - ft +  \beta \int_0^t \sigma_{j} dW_s \\
			&= (\beta \mu_j -\frac{1}{2}  \beta^2 \sigma_{j}^2 - f )t + \beta \sigma_j W_t \sim \mathcal{N}\left( (\beta \mu_j -\frac{1}{2}  \beta^2 \sigma_{j}^2 - f )t, \,  \beta^2 \sigma_j^2 t  \right).
		\end{align*}
		Hence, using the moment generating function technique, it follows that
		\begin{align*}
			\mathbb{E}[ \exp({X_t}^{(j)}) ] = \exp\left(  \mu_j   t\right) 
			\text{ and }
			\mathbb{E}[ \exp({Y_t}^{(j)} )] = \exp\left( (\beta \mu_j  - f )t \right)
		\end{align*}
		Because $Z_t$ switches between regimes over time, the full $Y_t$ is a weighted combination of regime-specific dynamics. The exact expectation $\mathbb{E}[\exp(X_t)]$ and $\mathbb{E}[\exp(Y_t)]$ can be  approximated\footnote{In principle, one can compute $\mathbb{E}[\exp(X_t)]$ and $\mathbb{E}[\exp(Y_t)]$ condition on given $Z_s = j$. Then invoke the Feynman-Kac theorem to solve the resulting PDEs, e.g., see \cite{cvitanic2004introduction}. However, solving the PDEs can be complex. } as follows:
		\begin{align*}
			\mathbb{E}[\exp(X_t)] 
			&\approx \sum_{j=1}^{M} \pi_j(t) \cdot \mathbb{E}[\exp ( X_t^{ (j) })] = \sum_{j=1}^{M} \pi_j(t) \cdot \exp\left( \mu_j  t \right)\\
			\mathbb{E}[\exp(Y_t)] 
			& \approx \sum_{j=1}^{M} \pi_j(t) \cdot \mathbb{E}[\exp ( Y_t^{ (j) })] = \sum_{j=1}^{M} \pi_j(t) \cdot \exp\left( (\beta \mu_j  - f )t \right).
		\end{align*}
		Therefore, the expected compounding effect is obtained:
		\[
		\mathbb{E}[\mathtt{CE}_t] \approx \sum_{j=1}^{M} \pi_j(t) \left[  \exp\left( (\beta \mu_j  - f )t \right) - \beta \exp\left(  \mu_j t \right) \right] + (\beta - 1). \qedhere
		\]
	\end{proof}



	\begin{lemma}[Expected Occupation Measure] \label{lemma: expected occupation measure}
		The expected occupation measure
		$\sum_{i=1}^M \pi_j(t) = 1$ for all $ t \geq 0$.
	\end{lemma}

	\begin{proof}[Proof of Lemma~\ref{lemma: expected occupation measure}]
		For every fixed sample point $\omega \in \Omega$ and any time $s$, the Markov chain is exactly one of the $M$ states. Hence, for all $s \geq 0$ and $\omega \in \Omega$,
		$
		\sum_{j=1}^M \mathbb{1}_{\{Z_s(\omega) = j\}} = 1 .
		$
		Hence, with the aid of the Fubini-Tonelli theorem, we have
		\begin{align*}
			\sum_{j=1}^M \pi_j(t) 
			&= \sum_{j=1}^M  \mathbb{E}\left[ \frac{1}{t} \int_0^t \mathbb{1}_{\{Z_s = j\}} ds \right]\\ 
			&= \mathbb{E}\left[  \sum_{j=1}^M \frac{1}{t} \int_0^t \mathbb{1}_{\{Z_s = j\}} ds \right]\\
			&= \mathbb{E}\left[   \frac{1}{t} \int_0^t \sum_{j=1}^M \mathbb{1}_{\{Z_s = j\}} ds \right]\\
			&= \mathbb{E}\left[   \frac{1}{t} \int_0^t 1 ds \right]
			= \mathbb{E}\left[   1 \right] = 1. \qedhere
		\end{align*}
	\end{proof}


	\begin{proof}[Proof of Theorem~\ref{theorem: Sign of Expected CE under Regime Switching}]
		This is an immediate consequence of the approximation:
		\[
		\mathbb{E}[\mathtt{CE}_t] \approx \sum_j \pi_j(t) \Phi_j(t; \beta, f) + (\beta - 1)
		\]
		where $\Phi_j(t; \beta, f)$ depends on both $\beta$ and $\mu_j$. The sign of the convex combination $\sum_j \pi_j(t) \Phi_j(t; \beta, f)$ determines the sign of CE, relative to the offset $(1 - \beta)$.
	\end{proof}


	\begin{proof}[Proof of Corollary~\ref{corollary: Nonnegative CE in Single Regime}]
		This follows directly from Theorem~\ref{theorem: Sign of Expected CE under Regime Switching}. 
		Fix $f=0$.	Note that for $t=0$, $	\mathbb{E}[\mathtt{CE}_t] =0$. Next, for $t >0$, 
		Take $x := \mu_j t \in \mathbb{R}$ where $x \geq 0$ if $\mu_j >0$ and $x \leq 0$ if $\mu_j <0$, and $x=0$ if $\mu = 0$. Hence, it suffices to show that
		$
		h_\beta(x):= \exp\left( \beta x  \right)  - \beta \exp(x) + (\beta - 1) \geq 0
		$ for all $x \in \mathbb{R}$.
		We now consider two cases:

		\textit{Case 1}. For $\beta > 1$, set the weights
		$
		\lambda_1 := \frac{1}{\beta}, \lambda_2 := 1 - \frac{1}{\beta}
		$
		then $\lambda_1 + \lambda_2 =1$ and $\lambda_1, \lambda_2 > 0.$ Since the exponential function $\exp(\cdot)$ is convex, applying the Jensen's inequality yields
		$
		\lambda_1 e^{\beta x } + \lambda_2 e^0 \geq e^{\lambda_1 \beta x + \lambda_2 \cdot 0} = e^x.
		$
		Multiplying~$\beta$ we obtain
		$
		e^{\beta x}-\beta e^{x}+(\beta-1) \geq 0
		$ for all $x \in \mathbb{R}$, 
		which shows that $\mathbb{E}[\mathtt{CE}_t] \geq 0$ for all $ t \geq 0$ when~$\beta >1.$

		\textit{Case 2}. For $\beta <0$, Take $\beta := -k$ with $k \in \mathbb{N}$. Then, we obtain
		$
		h_k(x) := e^{-k x} + k e^{x}-(k+1).
		$
		Note that the first derivative: $h_k'(x) = -ke^{-kx} + k e^x$, which vanishes at $x=0.$ Moreover, its second-order derivative: $
		h_k''(x) = k^2 e^{-kx} + k e^x >0.
		$
		Hence, $h_k$ is strictly convex and $x=0$ is the unique global minimizer of $h_k$. Value at the minimum is
		$
		h_k(0) = 1+ k - (k+1) = 0.
		$
		Since the minimum value is $0$, we have $h_k(x)\geq 0$ for every~$x \in \mathbb{R}$. Hence, it also implies that $\mathbb{E}[\mathtt{CE}_t] \geq 0$ for all $t$.

		Lastly, we consider the degenerate case $\mu = 0$. It implies that
		$
		\mathbb{E}[\mathtt{CE}_t] = e^0 - \beta e^0 + (\beta -1) = 0,
		$
		which is desired. Therefore, in all cases, $\mathbb{E}[\mathtt{CE}_t]  \geq 0$ for all $t \geq 0$ and equality holds when $t=0$, or when~$\mu = 0.$
	\end{proof}


