	\section{Notations, default time framework and preliminary results}
	\label{Notations}
	This section provides the general notation, assumptions, and preliminaries that will be used throughout the paper.

	Let $\mathbb{C}:=\left(\mathcal{C}_t\right)_{t \geq 0}$ be a generic filtration that satisfies the usual conditions of completeness and right continuity defined on a complete probability space $(\Omega,\mathcal{F},\mathsf{P})$. \\
	Recall that if $\mathcal{C}\left(\mathbb{C}\right)$ is a class of processes that are adapted to $\mathbb{C}$, then $\mathcal{C}_{loc}\left(\mathbb{C}\right)$ is the localized class of $\mathcal{C}\left(\mathbb{C}\right)$, i.e., the set of processes $(X_t)_{t \geq 0}$ for which there exists a sequence of $\mathbb{C}$-stopping times $\left\lbrace \sigma_n\right\rbrace_{n \in \mathbb{N}}$ such that $\sigma_n \nearrow +\infty$, $\mathsf{P}$-a.s., and the stopped process $X^{\sigma_n}:=\left( X_{t \wedge \sigma_n}\right)_{t \geq 0}$ belongs to $\mathcal{C}\left(\mathbb{C}\right)$ for each $n \in \mathbb{N}$. In this context, $\mathcal{M}_{loc} \left(\mathbb{C},\mathsf{P}\right)$ (respectively, $\mathcal{M} \left(\mathbb{C},\mathsf{P}\right)$) denotes the set of all $\mathbb{C}$-local martingales (respectively, martingales) under $\mathsf{P}$. Let $(X_t)_{t \geq 0} \in \mathcal{C}\left(\mathbb{C}\right)$, if $(X_t)_{t \geq 0}$ is an RCLL process, then we define $X_{s-}=\lim\limits_{u \nearrow s} X_u$ as the left limit of $X$ at $s \in (0,T]$, and $\Delta X_{s}=X_{s}-X_{s-}$ as the size of the jump at time $s$, with the convention $\Delta X_{0}=0$ (equivalently $X_{0-}=X_0$). For an $\mathcal{F} \otimes \mathcal{B}\left(\mathbb{R}_{+}\right)$-measurable process $V:=(V_t)_{t \geq 0}$ with finite variation, by $V^{o,\mathbb{C},\mathsf{P}}$ (resp. $V^{p,\mathbb{C},\mathsf{P}}$), we mean the $\mathbb{C}$-dual optional (resp. predictable) projection of $V$ when it exists under the probability measure $\mathsf{P}$. Next, for a given two $(0,+\infty)$-valued $\mathbb{C}$-stopping times $\sigma_1$ and $\sigma_2$,  $\mathfrak{T}_{\sigma_1,\sigma_2}(\mathbb{C})$ (respectively, $\mathfrak{T}(\mathbb{C})$) denotes the set of all $\mathbb{C}$-stopping times $\sigma$ such that $\mathsf{P}\left(\sigma_1 \leq \sigma \leq\sigma_2\right)=1$  (respectively, $\mathsf{P}\left(\sigma \in (0,+\infty) \right)=1$).\\
	For a given $\mathbb{C}$-adapted semimartingale $(X_t)_{t \geq 0}$, the set $\mathcal{I}(\mathbb{C}, \mathsf{P}, X)$ represents the collection of $\mathbb{C}$-predictable processes that are integrable with respect to the semimartingale $X$ under the probability measure $\mathsf{P}$. If we have two stopping times, $\sigma_{1}$ and $\sigma_{2}$, both belonging to $\mathfrak{T}(\mathbb{C})$ and satisfying $\sigma_{1} \leq \sigma_{2}$ almost surely under $\mathsf{P}$, we use the notation $\llbracket \sigma_1 , \sigma_{2}\rrbracket$ to represent the stochastic interval defined as $\llbracket \sigma_1 , \sigma_{2}\rrbracket=\{(\omega,t)\in \Omega \times [0,+\infty): \sigma_{1}(\omega)\leq t \leq \sigma_{2}(\omega)\}$. The same definition applies to other types of stochastic intervals \cite[Definition 3.14]{bookHe}. The equality $X=Y$ between any two processes $(X_t)_{t \geq 0}$ and $(Y_t)_{t \geq 0}$ must be understood in the indistinguishable sense, meaning that $\mathsf{P}\left(\omega:X_t(\omega)=Y_t(\omega), \forall t \geq 0\right)=1$. The same interpretation applies to $X \leq Y$ and $X < Y$. Finally, $\mathbb{E}_{\mathsf{P}}\left[\cdot\right]$ denotes the expectation operator under the probability measure $\mathsf{P}$. For a vector $x := (x_1, \ldots, x_d) \in \mathbb{R}^{d}$ ($d \geq 1$), the Euclidean norm is denoted by $\left\|x\right\|^2=\sum_{i=1}^d \left|x_i\right|^2$, and $\left\|x\right\|=\left|x\right|$ for $d=1$. Additionally, for $x \in \mathbb{R}$, we remember that $x^{+}=\max(x,0)$ and $x^{-}=\max(-x,0)=-\min(x,0)$.

	Consider a complete probability space $(\Omega, \mathcal{F}, \mathbb{P})$ on which we define a $d$-dimensional standard Brownian motion $(B_t)_{t \geq 0}$. Let $\mathbb{F} = (\mathcal{F}_t)_{t \geq 0}$ denote its completed natural filtration.
	Consider an arbitrary random time $\tau$, which need not be an $\mathbb{F}$-stopping time. This random time $\tau$ is characterized as an $\mathcal{F}$-measurable random variable with values in the interval $(0,+\infty)$ such that $\mathbb{P}\left(\{\tau=0\}\cup \{\tau=+\infty\}\right)=0$. This random variable $\tau$ models a \textit{default time}. We associate with $\tau$ the default indicator process $(D_t)_{t \geq 0}$ and introduce a new filtration $\mathbb{G} = (\mathcal{G}_t)_{t \geq 0}$ defined as follows
	\begin{equation}
		D_t = \mathds{1}_{\{\tau \leq t\}}, \quad \mathcal{G}_t^0 := \mathcal{F}_t \vee \sigma\left(D_s, s \leq t\right) \quad\mbox{and}\quad \mathcal{G}_t = \bigcap_{\epsilon > 0} \mathcal{G}^0_{t+\epsilon}.
		\label{Filtration}
	\end{equation}
	We adopt the convention $\mathcal{G}_{\infty} := \bigvee_{t \geq 0} \mathcal{G}_t=\mathcal{F}$. The filtration $\mathbb{G}$ is the smallest right-continuous complete filtration that contains $\mathbb{F}$ and makes $\tau$ a stopping time. This choice is motivated by the fact that the information related to the occurrence of the random time $\tau$ may not be entirely contained in $\mathbb{F}$ but rather in $\mathbb{G}$.\\
	In addition to $\mathbb{G}$ and $D$, the random time $\tau$ needs to be parameterized through $\mathbb{F}$ by the important pair $(G,\tilde{G})=(G_t,\tilde{G}_t)_{t \geq 0}$ of survival probabilities. These probabilities are defined by the following two $\mathbb{F}$-optional processes
	\begin{equation*}
		G_t:=\mathbb{P}\left(\tau>t \mid \mathcal{F}_t\right),\quad\mbox{and}\quad \tilde{G}_t:= \mathbb{P}\left(\tau \geq t \mid \mathcal{F}_t\right),\quad t \geq 0.
		\label{Azemas}
	\end{equation*}
	The process $G$, known as the \textit{Azéma supermartingale} of $\tau$ with respect to $\mathbb{F}$, exhibits right-continuous trajectories with left limits  (see Theorem 9 in \cite{bookProtter}, pp. 8). It serves as the $\mathbb{F}$-optional projection of $\mathds{1}_{\llbracket 0,\tau \llbracket}$. The process $\tilde{G}$, referred to as the \textit{Azéma optional supermartingale}, possesses finite right and left limits only and it is the $\mathbb{F}$-optional projection of $\mathds{1}_{\llbracket 0,\tau \rrbracket}$ (for more comprehensive details, please refer to \cite{azema1972quelques}).
	These processes $G$ and $\tilde{G}$ play a fundamental role in characterizing the behavior of the random time $\tau$ within the context of the filtration $\mathbb{F}$.

	For technical reasons, throughout the paper, we assume the following condition:
	\begin{center}
		\textbf{[P] } \text{ For }$\mathbb{P}$-almost all $\omega \in \Omega$, for all $t \geq 0$, 
		$G_t(\omega) > 0$.
	\end{center}
	Note that under the assumption \textbf{[P]}, we have (see Lemma 2.4 in \cite{choulli2022explicit}, pp. 234):
	\begin{itemize}
		\item $G_{-}$ and $\tilde{G}$ are positive processes.
		\item $G=G_0 \mathcal{E}\left(\Gamma^G \right)\mathcal{E}\left(\Gamma^{\tilde{G}} \right)=\mathcal{E}\left(\Gamma^G \right)\mathcal{E}\left(\Gamma^{\tilde{G}} \right)$, where $G_0=\mathbb{P}\left(\tau>0 \mid \mathcal{F}_0\right)=\mathbb{P}\left(\tau>0 \right)=1$. Here, the operator $\mathcal{E}\left(\mathcal{X}\right)$ represents the Doléans-Dade exponential, defined on the set of $\mathbb{G}$-semimartingales $(\mathcal{X}_t)_{t \geq 0}$ \cite[Theorem II.8.37]{bookProtter}. Additionally, 
		$\Gamma^G:=\int_{0}^{\cdot} G^{-1}_{s-} d m_s$, $\Gamma^{\tilde{G}}:=-\int_{0}^{\cdot} \tilde{G}^{-1}_{s} d D^{o,\mathbb{F},\mathbb{P}}_s$, 
		and $m:=D^{o,\mathbb{F},\mathbb{P}}+G$ is a BMO $\mathbb{F}$-martingale (see Proposition 1.46 in \cite{aksamit2017enlargement}, pp. 21), with $\Delta m=\tilde{G}-G_{-}$. For simplicity, we adopt the following notations throughout the paper: 
		\begin{equation}
			\mathcal{E}:=\mathcal{E}\left(\Gamma^G \right)~ \text{ and }~ \tilde{\mathcal{E}}:=\mathcal{E}\left(\Gamma^{\tilde{G}} \right).
			\label{Definition of E and E tilde}
		\end{equation}
	\end{itemize}

	On the one hand, it should be noted that the stability of the semimartingale property between $\mathbb{F}$ and $\mathbb{G}$, known as the $(\mathcal{H}^{\prime})$-Hypothesis, does not always hold. This legitimate question was first raised by P.A. Meyer and subsequently addressed by M. Yor in \cite[Theorem 1, pp. 62]{JeulinDecom}, where the author proved that the $(\mathcal{H}^{\prime})$-Hypothesis holds for all $\left(\mathbb{F},\mathbb{P}\right)$-semimartingales stopped at $\tau$. More precisely, we recall the following result:
	\begin{theorem}
		For any $\left(\mathbb{F},\mathbb{P}\right)$-semimartingale $\left(X_t\right)_{t \geq 0}$, the process $X^{\tau}:=\left(X_{t \wedge \tau}\right)_{t \geq 0}$ is a $\left(\mathbb{G},\mathbb{P}\right)$-semimartingale.
	\end{theorem}

	A fundamental question arises when considering the $\left(\mathbb{G},\mathbb{P}\right)$-semimartingale $B^{\tau}$ within the filtration $\mathbb{G}$:\\ 
	\textbf{(Q)}~ Under which probability measure $B^{\tau}$ remains a $\mathbb{G}$-Brownian motion?

	This question has been addressed in a recent work  \cite[Proposition 2.3, pp.5]{alsheyab2023optimal}, building upon an important result by Choulli and Yansori \cite[Proposition 4.3, pp. 248]{choulli2022explicit}, which we revisit below:
	\begin{proposition}
		The process $1 /\mathcal{E}^{\tau}$ belongs to  $\mathcal{M}\left( \mathbb{G},\mathbb{P}\right)$, and for any fixed $T \in (0,+\infty)$,
		\begin{equation}
			d\mathbb{Q}^{}_T:=\Psi_{T} d \mathbb{P},\text{ where } \Psi:=\dfrac{1}{\mathcal{E}^{\tau}} 
			\label{local continuity of Q}
		\end{equation}
		is a well-defined probability measure on $\left(\Omega,\mathcal{G}_T\right)$.
	\end{proposition}
	Additionally, under \textbf{[P]} and using Yor's formula \cite[Theorem II.38, pp. 86]{bookProtter}, the density process $\Psi$ may be expressed in the following form:  $\Psi^{}=\mathcal{E}\left(\Gamma^{\mathcal{T}(m)}\right)$,  where  $\Gamma^{\mathcal{T}(m)}:=-\int_{0}^{\cdot}G^{-1}_{s-} d\mathcal{T}(m)_s$, and $\mathcal{T}(\cdot)$ defined by (\ref{Theorem of the operator}). In particular, from \cite[Remark 2.5, pp. 235]{choulli2022explicit} and under \textbf{[P]}, we can see that $1+\Delta\Gamma^{\mathcal{T}(m)}>0$, which implies that the process $\left(\Psi_t\right)_{t\geq 0}$ is a strictly positive $\left(\mathbb{G},\mathbb{P}\right)$-martingale.

	%Throughout the paper, we make the following assumption:
	%\begin{center}
	%	\textbf{[U] } The $(\mathbb{G},\mathbb{P})$-martingale $(\Psi_t)_{t \geq 0}$ is uniformly integrable. 
	%\end{center}
	%
	%Recall that, under \textbf{[U]}, $\mathbb{Q}^{}$ is a well-defined probability measure on $(\Omega,\mathcal{F})$. In particular, the probability measure $\mathbb{Q}$ is given by $d\mathbb{Q}=\Psi_{\infty} d \mathbb{P}$ on $(\Omega, \mathcal{F})$, with $\Psi_{\infty}:=\lim\limits_{t\rightarrow\infty}\Psi_{t}$ and the restriction of $\mathbb{Q}$ to $\mathcal{G}_T$ defined by (\ref{local continuity of Q}). However, without assumptions \textbf{[P]} and \textbf{[U]}, the probability measure $\mathbb{Q}^{}$ cannot be defined for $T=+\infty$ due to the lack of uniform integrability for the $\mathbb{G}$-martingale $\Psi$ (see Remark 1 in  \cite{choulli2024optimal} and Proposition 4.3 in \cite{choulli2022explicit} for more details). This illustrates the necessity of assumptions \textbf{[P]} and \textbf{[U]}.
	\begin{remark}
		In the infinite-horizon case ($T = +\infty$), defining a probability measure via $d\mathbb{Q} := \Psi_{\infty} d\mathbb{P}$, where $\Psi_{\infty} := \lim_{t \to \infty} \Psi_t$, requires the $(\mathbb{G}, \mathbb{P})$-martingale $(\Psi_t)_{t \geq 0}$ to be uniformly integrable; see Remark 1 in \cite{choulli2024optimal} and Proposition 4.3 in \cite{choulli2022explicit}. Without this assumption, the measure $\mathbb{Q}$ may not be well defined on $(\Omega, \mathcal{F})$. In the present finite-horizon framework, however, such uniform integrability is not needed. For each finite $T \in (0,+\infty)$, the probability measure $\mathbb{Q}_T$ defined on $(\Omega, \mathcal{G}_T)$ by (\ref{local continuity of Q}) is well defined.
	\end{remark}

	Now we state an important result that provides an answer to the question \textbf{(Q)}, with the proof provided in the Appendix \ref{Appendix A}.
	\begin{lemma}
		Under assumption \textbf{[P]}, it follows that, for any fixed horizon time $T \in (0,+\infty)$, the stopped process $B^{\tau \wedge T}$ is a $\left(\mathbb{G},\mathbb{Q}^{}\right)$-Brownian motion.
		\label{Lemma of the Brownian motion}
	\end{lemma}
	%
	%
	\begin{remark}
		\begin{itemize}
			\item Lemma \ref{Lemma of the Brownian motion} plays an important role in our work. 
			In the literature on progressive enlargement of Brownian filtrations in the field of  BSDEs, the classical assumption is to suppose that $B \in \mathcal{M}(\mathbb{F},\mathbb{P})$ remains a $\mathbb{G}$-Brownian motion under the original probability measure $\mathbb{P}$ (i.e. $B \in \mathcal{M}(\mathbb{G},\mathbb{P})$), known as the $(\mathcal{H})$-Hypothesis or {\it Immersion property} in credit risk modeling. However, since this is not the case in our setting, and given that the $(\mathcal{H})$-Hypothesis is considered a very strong and restrictive condition, Lemma \ref{Lemma of the Brownian motion} provides an alternative result under weaker assumptions, allowing us to retain the martingale characterization of $B^{T \wedge \tau}$ in $\mathbb{G}$ under $\mathbb{Q}$ for each $T \in (0,+\infty)$.

			\item General enlargement formulas in the progressive enlargement of a Brownian filtration framework are available in Mansuy and Yor \cite{mansuy2006random}. See also Jeanblanc at al.  \cite{jeanblanc2009progressive} for the particular case where the random time $\tau$ is an {\it initial time} and Barlow  \cite{barlow1978study} for the case where $\tau$ is an {\it honest time}.
		\end{itemize}
	\end{remark}
	%

	Throughout the paper, we maintain the assumption \textbf{[P]}.
	%

	\section{Doubly reflected BSDEs in the defaultable setup $(\Omega,\mathcal{F},\mathbb{G},\mathbb{Q})$}
	\label{DRBSDE Problem section}
	\subsection{Problem formulation}
	%We begin by introducing a set of spaces.\\
	Let $\mathbb{C}:=\left(\mathcal{C}_t\right)_{t \geq 0}$ be an arbitrary filtration on $(\Omega,\mathcal{F})$ that satisfies the usual conditions and let $\mathsf{Q}$ be a probability measure defined on $(\Omega,\mathcal{F})$ equivalent to the survival one $\mathbb{P}$. \\
	Consider a non-negative $\mathbb{C}$-adapted process $\left(\alpha_t\right)_{t \geq 0}$, a parameter $\beta > 0$, and a giving random time $\theta \in \mathfrak{T}\left(\mathbb{C}\right)$. We define the increasing $\mathbb{C}$-adapted continuous process $\mathcal{A}_t := \int_{0}^{t} \alpha_s^2 ds$ for all $t \geq 0$. \\
	We now introduce the following spaces:
	\begin{itemize}
		\item $ \mathcal{S}^2_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$: The space of $\mathbb{R}$-valued and $\mathbb{C}$-adapted RCLL  processes $\left(Y_t\right)_{t \geq 0}$ such that $Y^{\theta}=Y$ and
		$$
		\left\|Y\right\|^2_{\mathcal{S}^2_{\theta}(\beta,\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[\sup_{t \geq 0} e^{\beta \mathcal{A}_{t \wedge \theta}} \left|Y_{t \wedge \theta}\right|^2 \right]<+\infty,
		$$
		with the convention $ \mathcal{D}^2_{\theta}\left( \mathbb{C},\mathsf{Q}\right):=\mathcal{S}^2_{\theta}(0,\mathbb{C},\mathsf{Q})$
		%	\item $ \mathcal{D}^2_{\theta}\left( \mathbb{C},\mathbb{Q}\right)$: The space of $\mathbb{R}$-valued and $\mathbb{C}$-adapted RCLL  processes $\left(Y_t\right)_{t \geq 0}$ such that $Y^{\theta}=Y$ and
		%	$$
		%	\left\|Y\right\|^2_{\mathcal{D}^2_{\theta}(\mathbb{C},\mathbb{Q})}=\mathbb{E}_{\mathbb{Q}}\left[\sup_{t \geq 0}  \left|Y_{t \wedge \theta}\right|^2 \right]<+\infty;
		%	$$
		\item $ \mathcal{S}^{2,\alpha}_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$: The space of $\mathbb{R}$-valued and $\mathbb{C}$-adapted RCLL  processes $\left(Y_t\right)_{t \geq 0}$ such that $Y^{\theta}=Y$ and
		$$
		\left\|Y\right\|^2_{\mathcal{S}^{2,\alpha}_{\theta}(\beta,\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[\int_{0}^{\theta}e^{\beta \mathcal{A}_{s}} \left|Y_{s} \alpha_s\right|^2  ds \right]<+\infty.
		$$
		\item $ \mathcal{H}^2_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$: The space of $\mathbb{R}^d$-valued and $\mathbb{C}$-predictable processes $\left(Z_t\right)_{t \geq 0}$ such that $Z=Z \mathds{1}_{\llbracket 0,\theta \rrbracket}$ and
		$$
		\left\|Z\right\|^2_{\mathcal{H}^2_{\theta}(\beta,\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[\int_{0}^{\theta} e^{\beta \mathcal{A}_s} \left\|Z_s\right\|^2 ds\right]<+\infty,
		$$
		with the convention $\mathcal{H}^2_{\theta}(\mathbb{C},\mathsf{Q}):=\mathcal{H}^2_{\theta}(0,\mathbb{C},\mathsf{Q})$.
		\item $ \mathcal{S}^2_{\theta}\left( \mathbb{C},\mathsf{Q}\right)$: The space of  $\mathbb{C}$-adapted continuous increasing processes $\left(K_t\right)_{t \geq 0}$ such that $K=K^{\theta}$ and
		$$
		\left\|K\right\|^2_{\mathcal{S}^2_{\theta}(\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[  \left|K_{ \theta}\right|^2 \right] <+\infty.
		$$
		\item $ \mathcal{M}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$: The space of $\mathbb{R}$-valued martingales $M \in \mathcal{M}(\mathbb{C},\mathsf{Q})$ orthogonal to $B^{\theta}$ such that $M=M^{\theta}$ and
		$$
		\left\|M\right\|^2_{\mathcal{M}^2_{\theta}(\beta,\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[\int_{0}^{\theta} e^{\beta \mathcal{A}_s} d\left[M,M\right]_s\right]<+\infty.
		$$
		\item $\mathcal{L}^p_{\theta}(\beta,\mathbb{C},\mathsf{Q})$: The set of $\mathcal{C}_{\theta}$-measurable random variables $\chi$ such that 
		$$
		\left\|\chi\right\|^p_{\mathcal{L}^p_{\theta}(\beta,\mathbb{C},\mathsf{Q})}=\mathbb{E}_{\mathsf{Q}}\left[ e^{\beta \mathcal{A}_{\theta}} \left|\chi\right|^p \right]<+\infty,\quad \text{with }~p \in \{1,2\},
		$$
		with the convention $\mathcal{L}^p_{\theta}(\mathbb{C},\mathsf{Q})=\mathcal{L}^p_{\theta}(0,\mathbb{C},\mathsf{Q})$.
		\item $\mathfrak{C}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right):=\mathcal{S}^2_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right) \cap  \mathcal{S}^{2,\alpha}_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$.
		\item $\mathfrak{U}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right):=\mathfrak{C}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right) \times \mathcal{H}^2_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)  \times \mathcal{M}^2_{ \theta}\left(\beta,\mathbb{C},\mathsf{Q}\right)$.
		\item $\mathfrak{B}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right):=\mathfrak{C}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right) \times \mathcal{H}^2_{ \theta}\left( \beta,\mathbb{C},\mathsf{Q}\right) \times \mathcal{S}^2_{\theta}\left( \mathbb{C},\mathsf{Q}\right) \times \mathcal{S}^2_{\theta}\left( \mathbb{C},\mathsf{Q}\right) \times \mathcal{M}^2_{\theta}\left( \beta,\mathbb{C},\mathsf{Q}\right)$.
	\end{itemize}
	Now, we present the setup carrying our DRBSDE. We operate within the framework of the complete filtered space $(\Omega, \mathcal{F}, \mathbb{G})$, under the probability measure $\mathbb{Q}$. The filtration $\mathbb{G}$ is defined as per (\ref{Filtration}), and $\mathbb{Q}$ is established in accordance with (\ref{local continuity of Q}). \\
	In the first part of this paper, we are looking for a quintuplet of $\mathbb{G}$-adapted processes $(Y_t,Z_t,K^{+}_t,K^{-}_t,M_t)_{t \geq 0}$ such that for any deterministic horizon $T \in (0,+\infty)$, we have:
	\begin{equation}
		\left\{
		\begin{split}
			\text{(i)} &~ \mathbb{Q}\text{-a.s. for all } t \in [0,T]\\
			& Y_{t \wedge \tau}=\xi+\int_{t \wedge \tau }^{T \wedge \tau} f(s,Y_s,Z_s)ds+\left( K^{+}_{ T \wedge \tau}-K^{+}_{t \wedge \tau}\right)-\left( K^{-}_{ T \wedge \tau}-K^{-}_{t \wedge \tau}\right)\\
			&\qquad\qquad -\int_{t \wedge \tau }^{T \wedge \tau} Z_s d B_s-\int_{t \wedge \tau }^{T \wedge \tau}dM_s;\\
			\text{(ii)} &~  L_t \leq Y_t \leq U_t,~  \forall t \in [0,T \wedge \tau[,~\mathbb{Q}\text{-a.s.};\\
			\text{(iii)} &~ L_{T \wedge \tau} \leq \xi \leq U_{T \wedge \tau},~\mathbb{Q}\text{-a.s.};\\
			\text{(iv)} &~   Y_t=\xi,~Z_t=dK^{+}_t=dK^{-}_t=dM_t=0,\text{ on the set }\{t \geq T \wedge\tau\},~\mathbb{Q}\text{-a.s.};\\
			\text{(v)} &~ \text{Skorokhod condition:}  \int_0^{T \wedge \tau}(Y_{t}-L_{t})dK^{+}_t=\int_0^{T \wedge \tau}(U_{t}-Y_{t})dK^{-}_t=0,~\mathbb{Q}\text{-a.s.}\\
		\end{split}
		\right.
		\label{basic equation}
	\end{equation}
	%

	\textbf{Note:} For simplicity, we fix a deterministic horizon time $T \in (0, +\infty)$ throughout the rest of the paper.\\
	%
	%

	We now present the definition of a solution for the DRBSDE (\ref{basic equation}) in our setting. 
	\begin{definition}
		Let $\beta>0$ and $(\alpha_t)_{t \geq 0}$ a non negative $\mathbb{F}$-adapted process. A solution to DRBSDE (\ref{basic equation}) with jumps associated with parameters $(\xi,f,L,U)$ is a quintuple of $\mathbb{G}$-adapted processes $(Y_t,Z_t,K^{+}_t,K^{-}_t,M_t)_{t \geq 0}$ which satisfy (\ref{basic equation}) and belongs to $\mathfrak{B}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$.
		\label{definition}
	\end{definition}
	%
	\begin{remark}
		\begin{itemize}
			\item[(a)] Let $(Y_t,Z_t,K^{+}_t,K^{-}_t,M_t)_{t \geq 0}$ be a solution of the DRBSDE (\ref{basic equation}) in the sense of Definition \ref{definition}. Then, 
			$$
			Y_t=\xi,\quad Z_t=dK^{+}_t=dK^{-}_t=dM_t=0 ~ \text{ on the set } \{t \geq T \wedge  \tau\}~~\mathbb{Q}\text{-a.s.,}
			$$
			and we can express (\ref{basic equation})-(i) as follows (see also \cite[Lemma 3.3]{topolewski2018reflected}): $\mathbb{Q}$-a.s. $\forall t \in [0,T]$,
			\begin{equation}
				Y_{t}=\xi+\int_{t }^{T} \mathds{1}_{\{s \leq \tau\}} f(s,Y_s,Z_s)ds+\left( K^{+}_{T}-K^{+}_{t}\right)-\left( K^{-}_{ T }-K^{-}_{t}\right)-\int_{t }^{T } Z_s d B_s-\int_{t}^{T}dM_s.
				\label{Writing BSDE forwadrdly}
			\end{equation}
			\item[(b)] 
			We point out that, according to a classical result in the general theory of stochastic processes  \cite[Theorem IV.84]{dellacherie1975probabilites}, a quintuplet $(Y,Z,K^{+},K^{-},M)$ satisfies (\ref{basic equation})-(i) or (\ref{Writing BSDE forwadrdly}) equivalently if and only  
			$$Y_{\sigma_1}=Y_{\sigma_2}+\int_{\sigma_1}^{\sigma_2}  f(s,Y_s,Z_s) ds +\left(K^{+}_{\sigma_2}-K^{+}_{\sigma_1}\right)-\left(K^{-}_{\sigma_2}-K^{-}_{\sigma_1}\right)-\int_{\sigma_1}^{\sigma_2} Z_s dB_s-\int_{\sigma_1}^{\sigma_2} dM_s$$  $\mathbb{Q}$-a.s. for all $\sigma_1,\sigma_2 \in \mathfrak{T}_{0,T \wedge \tau}\left(\mathbb{G}\right)$ such that $\sigma_1 \leq \sigma_2$, $\mathbb{Q}$-a.s.
		\end{itemize}
		\label{Remark on the construction of the BSDE}
	\end{remark}
	%
	%
	Now, we provide a brief literature review to highlight the key differences between our framework and those explored in previous studies.\\
	Due to its close connection to semi-linear elliptic partial differential equations (PDEs) and its role in providing a probabilistic formula for the viscosity solution of such PDEs, a significant part of the literature on BSDEs without reflection (i.e., when $L\equiv-\infty$ and $U\equiv\infty$) has focused on the case where the terminal  time $\tau$ is a $\mathbb{F}$ stopping time. For a comprehensive discussion of this topic, see \cite{darling1997backwards,pardoux1998backward,StoppingPeng,royer2004bsdes} among others.\\
	In the same context, the study of reflected BSDEs (i.e. when $L\equiv-\infty$ or $U=\infty$) and doubly reflected BSDEs in the case where $\tau$ is a not necessarily finite $\mathbb{F}$-stopping time has been extensively explored in the framework of Brownian motion, as presented in our primary setting $(\Omega,\mathcal{F}, \mathbb{F},\mathbb{P})$ (see, e.g., \cite{Akdim}). More precisely, consider the case when $\tau \in \mathfrak{T}(\mathbb{F})$. Then, in this scenario, the data triplet $(f, L, U)$ is $\mathbb{F}$-progressively measurable, the terminal value $\xi$ belongs to $\mathcal{F}_{\tau}$, and the DRBSDE (\ref{basic equation}) simplifies to:
	\begin{equation}
		\left\{
		\begin{split}
			\text{(i)} &~ \mathbb{P}\text{-a.s. for all } t \geq 0\\
			&~~ Y_{t}=\xi+\int_{t \wedge \tau }^{\tau} f(s,Y_s,Z_s)ds+\left( K^{+}_{\tau}-K^{+}_{t \wedge \tau}\right)-\left( K^{-}_{\tau}-K^{-}_{t \wedge \tau}\right) -\int_{t \wedge \tau }^{\tau} Z_s d B_s;\\
			\text{(ii)} &~  L_t \leq Y_t \leq U_t,~  \forall t \geq 0,~\mathbb{P}\text{-a.s.};\\
			\text{(iii)} &~  Y_t=\xi,~Z_t=dK^{+}_t=dK^{-}_t=0,\text{ on the set }\{t \geq \tau\},~\mathbb{P}\text{-a.s.};\\
			\text{(iv)} &~ \text{ Skorokhod condition:}  \int_0^{ \tau}(Y_{t}-L_{t})dK^{+}_t=\int_0^{ \tau}(U_{t}-Y_{t})dK^{-}_t=0,~\mathbb{P}\text{-a.s.}
		\end{split}
		\right.
		\label{basic equation in F}
	\end{equation}
	In this scenario, the data $(f, L, U)$ are $\mathbb{F}$-progressively measurable and $\xi$ belongs to $\mathcal{F}_{\tau}$. Compared to previous works, it is clear from the DRBSDEs  (\ref{basic equation}) and (\ref{basic equation in F}) that:
	\begin{enumerate}
		\item The solution's definition does not include an orthogonal martingale term, indicating that $M \equiv 0$. This is because $(B_t)_{t \geq 0}$ is an $(\mathbb{F},\mathbb{P})$-Brownian motion, and the data $(\xi, f, L, U)$ are defined in the filtration $\mathbb{F}$. Consequently, on one hand, $B$ possesses the martingale representation property with respect to the historical probability measure $\mathbb{P}$, and, on the other hand, this fact enables us to construct the solution using the stochastic integral solely with respect to $B$.
		\item There is no need to change the probability measure from $\mathbb{P}$ to the new probability $\mathbb{Q}$ for DRBSDE \eqref{basic equation in F}. This is because the problem is well-defined within the $(\mathbb{F},\mathbb{P})$ setting. However, in our setup, as $\tau$ is not an $\mathbb{F}$-stopping time, and $\mathbb{F}$ only represents a partial flow of information generated by $(B_t)_{t \geq 0}$ under $\mathbb{P}$, we emphasize the importance of constructing a new framework, $\left(\mathbb{G},\mathbb{Q}\right)$, from the initial setup $\left(\mathbb{F},\mathbb{P}\right)$ where $\mathbb{G}$ represents the global flow of information. This is done to ensure the following:
		\begin{enumerate}
			\item The default terminal time $\tau$ becomes a stopping time through the progressive enlargement of the filtration, enabling the applications of classical results from stochastic analysis.
			\item The stopped process $(B^{\tau}_t)_{t \geq 0}$ retains its status as a Brownian motion in $\mathbb{G}$ under the probability measure $\mathbb{Q}$, rather than being a $\mathbb{G}$-semi-martingale under $\mathbb{P}$.
			\item $(B^{\tau}_t)_{t \geq 0}$ satisfies a form of the martingale representation property for all local martingales in $\mathcal{M}_{loc}(\mathbb{G},\mathbb{Q})$. This feature allows us to address various classical BSDEs and reflected BSDEs with default times, all originating from the broader framework $\mathbb{F}$.
		\end{enumerate}
	\end{enumerate}
	%
	We note that the enlarged filtration $\mathbb{G}$ defined by (\ref{Filtration}) can be regarded as a general filtration for the $(\mathbb{F},\mathbb{P})$-Brownian motion $(B_t)_{t \geq 0}$. Most studies in the literature focus on various types of BSDEs starting from an initial setup $(\mathbb{F},\mathbb{P})$ that \textit{supports} the process $(B_t)_{t \geq 0}$, or even a setup $(\mathbb{F},\mathbb{P})$ that \textit{supports} a general RCLL martingale \cite[among others]{elmansourielotmani24,CRBN,BDEM,karoui1997general}. In such scenarios, the problem is well-posed within the $(\mathbb{F},\mathbb{P})$ framework due to the predictable representation properties with an additional orthogonal martingale term. These properties are discussed in Section III.4 of \cite{bookJacod} (Lemma 4.24, pp. 185) and also in \cite{Tianyang} (Remark 2.1, pp. 323).\\
	However, problem (\ref{basic equation}) lacks well-posedness in both $\mathbb{F}$ generated by $(B_t)_{t \geq 0}$ and in $\mathbb{G}$ under $\mathbb{P}$. This is because $\tau$ may not be a stopping time, and the Immersion property is not assumed to hold. To address this issue, we introduce an additional probability measure, $\mathbb{Q}$, defined by (\ref{local continuity of Q}), which serves two main purposes:
	\begin{enumerate}
		\item Preserving the desired properties of the Brownian motion for $B^{\tau}$ in $\mathbb{G}$.
		\item Enabling the application of the martingale representation property over the time interval $\llbracket 0, \tau \rrbracket$ in $\mathbb{G}$, which provides additional knowledge concerning the link between the representation property's parameters, $B^{\tau}$, and the default time $\tau$.
	\end{enumerate}
	%
	\subsection{Existence and uniqueness results of (\ref{basic equation})}
	%\subsubsection{Data presentation and assumptions}
	We provide a comprehensive representation of the data $(\xi, f, L, U)$ involved in our DRBSDE (\ref{basic equation}), along with their measurability and integrability properties:\\
	\textbf{Assumption} ($\mathbf{H_1}$)\textbf{.} We assume that:
	\begin{itemize}
		\item $\xi$ is an $\mathcal{F}_{T \wedge \tau}$-measurable random variable, where the definition of  $\mathcal{F}_{T \wedge \tau}$ is borrowed from  \cite{Chung}:
		$$
		\mathcal{F}_{T \wedge \tau}=\sigma\left\{\zeta_{T \wedge \tau}, \left(\zeta_t\right)_{t \geq 0} \text{ any } \mathbb{F}\text{-optional process}\right\}.
		$$
		Therefore, we may choose an $\mathbb{F}$-adapted RCLL process $\left(\zeta_t\right)_{t \geq 0}$ such that 
		\begin{equation*}
			\xi=\zeta_{T \wedge \tau},\quad \mathbb{P}\text{-a.s.}
			\label{terminal variables}
		\end{equation*}
		%
		\item $\xi$ belongs to $\mathcal{L}^2_{T \wedge \tau}\left(\beta,\mathbb{G},\mathbb{Q}^{}\right)$.
	\end{itemize}
	%
	As the terminal variable $\xi$ is represented using the $\mathbb{F}$-optional processes $(\zeta_t)_{t \geq 0}$, we can establish a characterization of $\xi$'s integrability within $(\mathcal{G}_{T\wedge \tau},\mathbb{Q}^{})$ in terms of $\zeta$ within $(\mathcal{F}_{T},\mathbb{P})$. This characterization is provided in the following lemma:
	\begin{lemma}
		Let $V^{\mathbb{F}}:=1-\tilde{\mathcal{E}}$ and $V^{\ast \mathbb{F}}:=\int_{0}^{\cdot} \left| \zeta_s \right|^2 d V^{\mathbb{F}}_s$. Then, $\xi \in \mathcal{L}^2_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q}^{})$ whenever $\left( V^{\ast \mathbb{F}}_T,\zeta_T \right) \in \mathcal{L}^1_T(\beta,\mathbb{F},\mathbb{P}) \times \mathcal{L}^2_T(\beta,\mathbb{F},\mathbb{P})$.
		\label{Lemma Merties}
	\end{lemma}
	\begin{proof}
		First, let's define the non-negative $\mathbb{F}$-adapted RCLL process $\zeta^{\ast}_t := e^{\beta \mathcal{A}_t} \left| \zeta_t \right|^2$. Therefore, using the fact that $\mathbb{P}\left(\tau=0\right)=0$, we have 
		\begin{equation}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[\zeta^{\ast}_{T \wedge \tau}\right]=\mathbb{E}\left[\zeta^{\ast}_{T \wedge \tau}\Psi_{T \wedge \tau}\right]&=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\Psi_T \mathds{1}_{\{T <\tau\}}+\zeta^{\ast}_{\tau }\Psi_{\tau}\mathds{1}_{\{0<\tau \leq T\}}+\zeta^{\ast}_{0}\Psi_{0}\mathds{1}_{\{\tau=0 \}} \right]\\
				&=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\Psi_T \mathds{1}_{\{T <\tau\}}+\zeta^{\ast}_{\tau }\Psi_{\tau}\mathds{1}_{\{0<\tau \leq T\}} \right].
				\label{im lost}
			\end{split}
		\end{equation}
		Next, using the definition of the density process $\Psi$ as given by (\ref{local continuity of Q}), we derive that $\Psi_T \mathds{1}_{\{T<\tau\}}=\mathcal{E}^{-1}_T \mathds{1}_{\{T<\tau\}}$ and $\Psi_{\tau}=\mathcal{E}^{-1}_{\tau}$. Inserting these expressions into (\ref{im lost}), we obtain
		\begin{equation}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[\zeta^{\ast}_{T \wedge \tau}\right]&=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\mathcal{E}^{-1}_T \mathds{1}_{\{T <\tau\}}+\zeta^{\ast}_{\tau } \mathcal{E}^{-1}_{\tau} \mathds{1}_{\{0<\tau \leq T\}} \right]
				=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\mathcal{E}^{-1}_T \mathds{1}_{\{T <\tau\}}+\int_{0}^{T}\zeta^{\ast}_{s }\mathcal{E}^{-1}_s dD_s \right]
				\label{AAA}
			\end{split}
		\end{equation}
		Next, since $\mathcal{E}$ is an $\mathbb{F}$-optional process, by passing to the $\mathbb{F}$-optional projection for $\mathds{1}_{\{T <\tau\}}$ and the $\mathbb{F}$-dual optional projection of the defaultable process $D$ in (\ref{AAA}), we get
		\begin{equation}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[\zeta^{\ast}_{T \wedge \tau}\right]&=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\mathcal{E}^{-1}_T G_T+\int_{0}^{T}\zeta^{\ast}_{s }\mathcal{E}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s \right]\\
				&=\mathbb{E}^{}\left[\zeta^{\ast}_{T }\mathcal{E}^{-1}_T G_T+\int_{0}^{T}e^{\beta \mathcal{A}_s}\left|\zeta_s \right|^2 \mathcal{E}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s \right]
				\label{im lost hey}
			\end{split}
		\end{equation}
		Moreover, from the equalities $\tilde{\mathcal{E}}_{s-}=\frac{\tilde{G}_s}{G_s} \tilde{\mathcal{E}}_s$ and $G_s=\mathcal{E}_s\tilde{\mathcal{E}}_s$, along with the definition $dV^{\mathbb{F}}_s=\tilde{G}^{-1}_s\tilde{\mathcal{E}}_{s-}dD^{o,\mathbb{F},\mathbb{P}}_s$, we deduce that $dV^{\mathbb{F}}_s=\mathcal{E}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s$ and $ \mathcal{E}^{-1}_T G_T=\tilde{\mathcal{E}}_T$.\\ 
		Since $V^{\ast \mathbb{F}}_t$ is an $\mathbb{F}$-optional non-negative increasing process, employing an integration by part formula, we can write $\mathbb{P}\text{-a.s.,}$
		\begin{equation}
			\begin{split}
				\int_{0}^{T}e^{\beta \mathcal{A}_s}\left|\zeta_s \right|^2 \mathcal{E}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s=\int_{0}^{T} e^{\beta \mathcal{A}_s} \left| \zeta_s \right|^2 d V^{\mathbb{F}}_s
				&=e^{\beta \mathcal{A}_T} V^{\ast \mathbb{F}}_T-\beta \int_{0}^{T} e^{\beta \mathcal{A}_s} \alpha_s^2 V^{\ast \mathbb{F}}_s ds\\
				&\leq e^{\beta \mathcal{A}_T} V^{\ast \mathbb{F}}_T,
				\label{Classico asser}
			\end{split}
		\end{equation}
		where the first equality arises from the definition of the process $\zeta^{\ast}$, while the last inequality is derived from the positivity of the process $V^{\ast \mathbb{F}}$.\\
		On the other hand, we are aware that the process $\tilde{\mathcal{E}}$ satisfies the following forward stochastic differential equation: $\tilde{\mathcal{E}}_t=1-\int_{0}^{t}\tilde{\mathcal{E}}_{s-}\tilde{G}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s$. Then, since $1+\Delta \Gamma^{\tilde{G}}=G_s \tilde{G}^{-1}_s>0$ under \textbf{[P]}, we deduce that $\tilde{\mathcal{E}}>0$, and thus $\tilde{\mathcal{E}} \leq 1$. By plugging this result and (\ref{Classico asser}) into (\ref{im lost hey}), we derive
		\begin{equation*}
			\mathbb{E}_{\mathbb{Q}}\left[e^{\beta \mathcal{A}_{T \wedge \tau}} \left|\xi \right|^2\right]=\mathbb{E}_{\mathbb{Q}}\left[\zeta^{\ast}_{T \wedge \tau}\right]\leq \mathbb{E}\left[e^{\beta \mathcal{A}_T} \left( V^{\ast \mathbb{F}}_T + \left| \zeta_T \right|^2  \right)  \right].
		\end{equation*}
		This completes the proof.
	\end{proof}
	%
	\textbf{Assumption} ($\mathbf{H_2}$)\textbf{.} We assume that:
	\begin{itemize}
		\item The mapping $f:\Omega \times [0,T] \times \mathbb{R} \times \mathbb{R}^d \rightarrow \mathbb{R}$ is such that
		\begin{itemize}
			\item[(i)] For all $(y,z)$, the stochastic process $f(\cdot,y,z)$ is $\mathbb{F}$-progressively measurable.
			\item[(ii)] There exist two non-negative $\mathbb{F}$-adapted processes $(\kappa_t)_{t \leq T}$ and $(\gamma_t)_{t \leq T}$ such that
			\begin{itemize}
				\item[(a)] for all $t \in [0,T]$, $y$, $y^{\prime} \in \mathbb{R}$ and $z$, $z^{\prime} \in \mathbb{R}^d$, 
				$$
				\left| f(t,y,z)-f(t,y^{\prime},z^{\prime}) \right| \leq \kappa_t  \left|y-y^{\prime} \right|+\gamma_t  \left\|z-z^{\prime} \right\|,\quad d\mathbb{Q} \otimes dt\text{-a.e.}
				$$
				\item[(b)] There exists $\epsilon >0$ such that $\alpha^2:=\kappa+\gamma^2\geq \epsilon$. 
			\end{itemize}
		\end{itemize}
		%
		\item $\frac{f(\cdot,0,0)}{\alpha_{\cdot}}$ is in $\mathcal{H}^2_{T}(\beta,\mathbb{F},\mathbb{P})$.
	\end{itemize}
	%

	The following example is presented in order to illustrate the practical relevance of stochastic Lipschitz conditions in financial modeling. The example is drawn from the pricing of European options in a Black–Scholes framework with stochastic parameters.
	\begin{example}[Stochastic Lipschitz driver]
		Let $T > 0$. Within the flow of information $\mathbb{F}=\left(\mathcal{F}_t\right)_{t \leq T}$ generated by a Brownian motion $B$, consider a complete financial market in which asset prices evolve according to a Black–Scholes model with stochastic coefficients. The market consists of a risk-free asset $(S^0_t)_{t \leq T}$ and a risky asset $(S_t)_{t \leq T}$ governed by the system:
		\begin{equation}\label{BS}
			\left\lbrace
			\begin{split}
				dS^0_t &= r_t S^0_t\, dt, \qquad\qquad\qquad S^0_0 = 1, \\
				dS_t &= S_t \left( \mu_t\, dt + \sigma_t\, dB_t \right), \quad S_0 = x > 0,
			\end{split}
			\right.
		\end{equation}
		where $(r_t, \mu_t, \sigma_t)$ are $\mathbb{F}$-predictable processes satisfying
		$$
		\int_0^T \left(r_s + |\mu_s| + |\sigma_s|^2 \right)\, ds < +\infty, \quad \mathbb{P}\text{-a.s.}
		$$

		We consider the pricing of a European call option with strike $K$ and maturity $T$. Its payoff is given by $\xi = (S_T - K)^+$. A financial strategy is represented by a pair of processes $\varPi = (\pi^0_t, \pi_t)_{t \in [0,T]}$, where $\pi^0$ is an $\mathbb{F}$-adapted process representing the amount invested in the risk-free asset $S^0$, and $\pi$ is an $\mathbb{F}$-predictable process representing the amount invested in the risky asset $S$. The corresponding portfolio value process is given by:
		$$
		\mathbf{V}^{\varPi}_t := \pi^0_t S^0_t + \pi_t S_t, \quad t \in [0,T].
		$$
		If the strategy $\varPi = (\pi^0, \pi)$\footnote{Provided that the stochastic integrals appearing in the dynamics are well defined.} is self-financing, then
		\begin{equation*}
			\begin{split}
				d\mathbf{V}^{\varPi}_t &= \pi^0_t\,dS^0_t + \pi_t\,dS_t
				= r_t \mathbf{V}^{\varPi}_t\, dt + \sigma_t \pi_t\, S_t \left(\theta_t\, dt + dB_t\right),
			\end{split}
		\end{equation*}
		where $\theta_t := \frac{\mu_t - r_t}{\sigma_t}$. Setting $Z^{\varPi}_t := \sigma_t \pi_t S_t$, we obtain:
		$$
		d\mathbf{V}^{\varPi}_t = \left(r_t \mathbf{V}^{\varPi}_t + \theta_t Z^{\varPi}_t \right)\, dt + Z^{\varPi}_t\, dB_t.
		$$
		Thus, the value process under a replicating self-financing strategy satisfies the following BSDE:
		\begin{equation*}\label{EDSR lin}
			\left\lbrace 
			\begin{split}
				d \mathbf{V}^{\varPi}_t &= -f(t,\mathbf{V}^{\varPi}_t,Z^{\varPi}_t)\, dt + Z^{\varPi}_t\, dB_t, \quad t \in [0,T], \\
				\mathbf{V}^{\varPi}_T &= \xi,
			\end{split}
			\right. 
		\end{equation*}
		with driver $f(t,y,z) = -r_t y - \theta_t z$, which is clearly a stochastic Lipschitz driver. This illustrates how such drivers naturally arise in financial applications involving stochastic market parameters, including time-varying interest rates and volatilities. 

		Additionally, under the Immersion property, the use of stochastic Lipschitz drivers for valuing contingent claims in a complete market model with default and stochastic parameters using the theory of DRBSDEs has been recently presented in \cite{EM2025}.
	\end{example}



	Now, following the spirit of Lemma \ref{Lemma Merties}, we establish a characterization of the integrability of the driver for our DRBSDE \eqref{basic equation} within the frameworks $(\mathcal{G}_{T \wedge \tau}, \mathbb{Q})$ and $(\mathcal{F}_T, \mathbb{P})$.
	\begin{lemma}
		If $\left( \frac{f(t,0,0)}{\alpha_{t}}\right)_{t \geq 0} \in \mathcal{H}^2_T(\beta,\mathbb{F},\mathbb{P})$, then $\left( \frac{f(t,0,0)}{\alpha_{t}}\right)_{t \geq 0}\in \mathcal{H}^2_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q})$.
		\label{proof of lemma integrable}
	\end{lemma}
	%
	\begin{proof}
		Let $\Phi$ be the continuous increasing  process defined by $\Phi_t:=\int_{0}^{t} e^{\beta \mathcal{A}_s} \left| \frac{f(s,0,0)}{\alpha_{s}}\right|^2  ds$ and
		consider  a $\mathbb{G}$-stopping time $\sigma \in \mathfrak{T}_{0,T}(\mathbb{G})$. The Bayes rule implies that
		\begin{equation}
			\mathbb{E}_{\mathbb{Q}}\left[\Phi_{\sigma \wedge \tau}\right]
			=\mathbb{E}^{}\left[\int_{0}^{\sigma \wedge \tau}  e^{\beta \mathcal{A}_s}\left|  \frac{f(s,0,0)}{\alpha_{s}}\right|^2  \Psi_s ds\right]=\mathbb{E}\left[\int_{0}^{\sigma \wedge \tau}   \Psi_s d\Phi_s\right].
			\label{Bayes Rule}
		\end{equation}
		Since $\Phi$ is an $\mathbb{F}$-adapted process with continuous paths, we can apply an integration by parts formula, leading to
		\begin{equation}
			\Phi_{\sigma \wedge \tau} \Psi_{\sigma \wedge \tau}=\int_{0}^{\sigma \wedge \tau} \Phi_s d \Psi_s +\int_{0}^{\sigma \wedge \tau}   \Psi_s d\Phi_s,\quad \mathbb{P}^{}\text{-a.s.}
			\label{taking the expectation with fundame}
		\end{equation}
		Now, following a similar calculation to the one used in the proof of Lemma \ref{Lemma Merties}, we obtain
		\begin{equation}
			\mathbb{E}\left[\Phi_{\sigma \wedge \tau} \Psi_{\sigma \wedge \tau}\right]= \mathbb{E}\left[\tilde{\mathcal{E}}_{\sigma} \Phi_{\sigma}+\int_{0}^{\sigma} \Phi_s d V^{\mathbb{F}}_s\right],
			\label{equation we use this}
		\end{equation}
		where the process $V^{\mathbb{F}}$ is defined in the statement of Lemma \ref{Lemma Merties}. Additionally, 
		recall that $\tilde{\mathcal{E}} \leq 1$, which implies that $V^{\mathbb{F}} \leq 1$. Consequently, since $dV^{\mathbb{F}}$ is a positive measure, from (\ref{equation we use this}), we obtain
		\begin{equation}
			\mathbb{E}\left[\Phi_{\sigma \wedge \tau} \Psi_{\sigma \wedge \tau}\right]
			\leq 2  \mathbb{E}\left[ \sup_{t \geq 0}\left| \Phi_{t \wedge \sigma}\right|  \right] 
			\leq 2 \mathbb{E}\left[ \int_{0}^{T} e^{\beta \mathcal{A}_s} \left| \frac{f(s,0,0)}{\alpha_{s}}\right|^2  ds \right].
			\label{lebesgue}
		\end{equation}
		Now, let  $\{\sigma_k\}_{k\in \mathbb{N}}$ be a fundamental sequence for the $\mathbb{G}$-local martingale $\int_{0}^{\cdot} \Phi_s d \Psi_s$. Since $\sigma \in \mathfrak{T}_{0,T}(\mathbb{G})$ in (\ref{lebesgue}) is arbitrary, we can choose $\sigma=\sigma_k \wedge T$ in (\ref{taking the expectation with fundame}). Then, by taking the expectation with respect to  $\mathbb{P}$ along with (\ref{Bayes Rule}), we deduce:
		\begin{equation}
			\mathbb{E}\left[\Phi_{\sigma_k \wedge T \wedge \tau} \Psi_{\sigma_k \wedge T \wedge \tau}\right]=\mathbb{E}\left[\int_{0}^{\sigma_k \wedge T \wedge \tau} \Psi_s d \Phi_s \right]=\mathbb{E}_{\mathbb{Q}}\left[\Phi_{\sigma_k \wedge T \wedge \tau}\right].
			\label{Resume}
		\end{equation}
		Finally, by combining the continuity of the processes $(\Phi_t)_{t \geq 0}$ and $\left(\int_{0}^{t} \Psi_s d \Phi_s\right)_{t \geq 0}$ with Fatou's Lemma, the Lebesgue dominated convergence theorem, (\ref{lebesgue}), and (\ref{Resume}), we derive the desired result.
	\end{proof}
	%
	\textbf{Assumption} ($\mathbf{H_3}$)\textbf{.} We assume that: 
	\begin{itemize}
		\item The obstacles $L:=(L_t)_{t \leq T}$ and  $U:=(U_t)_{t \leq T}$ are RCLL $\mathbb{F}$-adapted processes with jumps occurring only at $\tau$, such that 
		\begin{equation}
			\left\{
			\begin{split}
				&	L_t < U_t,~\forall t \in [0,T\wedge \tau[ \text{ and } L_{t-} < U_{t-},~\forall t \in [0,T\wedge \tau],~\mathbb{Q}\text{-a.s.}\\
				&L_{T \wedge \tau} \leq \xi \leq U_{T \wedge \tau},~
				L_t=L_{T \wedge \tau} \text{ and } U_t=U_{T \wedge \tau} \text{ on the set } \{ t \geq T \wedge \tau\}.
			\end{split}
			\right.
			\label{Barriers Definition}
		\end{equation}
		\item $L^{+} \in \mathcal{S}^2_{T}(2\beta,\mathbb{F},\mathbb{P})$ and $U^{-} \in \mathcal{S}^2_{T}(2\beta,\mathbb{F},\mathbb{P})$.
	\end{itemize}
	%
	\begin{remark}
		The RCLL property of the reflection barriers $L$ and $U$ comes from the RCLL property of the orthogonal martingale $M$ in the filtration $\mathbb{G}$, which explains the continuity of the reflection processes $K^{\pm}$ in the Skorokhod condition of DRBSDE (\ref{basic equation}).
	\end{remark}
	%
	Now, by applying the same reasoning used in the proof of Lemmas \ref{Lemma Merties} and \ref{proof of lemma integrable}, we can establish the following result:
	\begin{lemma}
		If $(L_t,U_t)_{t \leq T}$ satisfies (\ref{Barriers Definition}), and $(L^{+},U^{-}) \in \left( \mathcal{S}^2_T(2\beta,\mathbb{F},\mathbb{P})\right)^2$, then $(L^{+},U^{-}) \in \left( \mathcal{S}^2_{T \wedge \tau}(2\beta,\mathbb{G},\mathbb{Q})\right)^2$.
		\label{proof of measurability L,U}
	\end{lemma}
	%
	\textbf{Assumption} ($\mathbf{H_4}$)\textbf{.} The strictly separated hypothesis on the barriers (\ref{Barriers Definition}) can be strengthened by assuming the existence of a semimartingale $(\mathcal{J}_t)_{t \geq 0}$ of the form: 
	\begin{equation*}
		\left\{
		\begin{split}
			\text{(i)} &~ \mathbb{Q}\text{-a.s. for all } t \in [0,T]\\
			&~~ \mathcal{J}_{t \wedge \tau}=\xi+\left( \mathcal{K}^{+}_{ T \wedge \tau}-\mathcal{K}^{+}_{t \wedge \tau}\right)-\left( \mathcal{K}^{-}_{ T \wedge \tau}-\mathcal{K}^{-}_{t \wedge \tau}\right) -\int_{t \wedge \tau }^{T \wedge \tau} \mathcal{Z}_s d B_s-\int_{t \wedge \tau }^{T \wedge \tau}d\mathcal{N}_s;\\
			\text{(ii)} &~  L_t \leq \mathcal{J}_t \leq U_t,~  \forall t \in [0,T \wedge \tau],~\mathbb{Q}\text{-a.s.};\\
			\text{(iii)} &~   \mathcal{J}_t=\xi,~\mathcal{Z}_t=d\mathcal{K}^{+}_t=d\mathcal{K}^{-}_t=d\mathcal{N}_t=0,\text{ on the set }\{t \geq T \wedge\tau\},~\mathbb{Q}\text{-a.s.}
		\end{split}
		\right.
	\end{equation*}
	Moreover, we assume that $\mathcal{Z} \in \mathcal{H}^2_{T \wedge \tau}(\mathbb{G},\mathbb{Q})$, $\mathcal{N} \in \mathcal{M}^2_{T \wedge \tau}(\mathbb{G},\mathbb{Q})$, and that $\mathcal{K}^{+}$, $\mathcal{K}^{-}$ are two non decreasing continuous processes satisfying $\mathbb{E}\left| \mathcal{K}^{\pm}_{T \wedge \tau}\right|^2<+\infty$.\\
	%
	The four conditions ($\mathbf{H_1}$)-($\mathbf{H_4}$) on the data $(\xi, f, L, U)$ mentioned above are denoted collectively as \textbf{(H)}.

	Let $(\xi^i,f^i,L^i,U^i)_{i=1,2}$ be two sets of data satisfying assumption \textbf{(H)}. Let $(Y^i,Z^i,K^{i,+},K^{i,-},M^i)$ denote a solution of the DRBSDE (\ref{basic equation})  with data $(\xi^i,f^i,L^i,U^i)$. Set $\bar{\mathfrak{R}}=\mathfrak{R}^1-\mathfrak{R}^2$ for $\mathfrak{R}=Y, Z, K^{\pm}, M, \xi, f, L$ and $U$.\\
	By using a similar line of reasoning as in the proof of Proposition 3.1 in \cite{BDEM}, we can prov the following result:
	\begin{proposition}
		For $\beta>3$, there exists a constant $\mathfrak{c}_{\beta}>0$ such that 
		\begin{equation*}
			\begin{split}
				&\left\|\bar{Y}\right\|^2_{\mathcal{S}^{2}_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q})}+\left\|\bar{Y}\right\|^2_{\mathcal{S}^{2,\alpha}_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q})}+\left\|\bar{Z}\right\|^2_{\mathcal{H}^2_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q})}+\left\|\bar{M}\right\|^2_{\mathcal{M}^2_{T \wedge \tau}(\beta,\mathbb{G},\mathbb{Q})}\\
				&\leq \mathfrak{c}_{\beta}\mathbb{E}_{\mathbb{Q}}\left[ e^{\beta \mathcal{A}_{T \wedge \tau}} \left|\bar{\xi} \right|^2
				+\int_{0}^{T \wedge \tau}  e^{\beta \mathcal{A}_{s}} \left|\dfrac{\bar{f}(s,Y^2_s,Z^2_s)}{\alpha_{s}} \right|^2 ds +\int_{0}^{T \wedge \tau}e^{\beta \mathcal{A}_s}\left(\bar{L}_sd\bar{K}^+_s+\bar{U}_sd\bar{K}^-_s\right) \right].
			\end{split}
		\end{equation*}
		\label{basic Estimastion for BSDE} 
	\end{proposition}
	%
	A direct consequence of Proposition \ref{basic Estimastion for BSDE} is the uniqueness result of the solution for the DRBSDE (\ref{basic equation}), stated as follows:
	\begin{corollary}
		Under assumption \textbf{(H)}, there exists at most one $\mathbb{G}$-adapted process $\left(Y_t, Z_t ,K^{+}_t,K^{-}_t, M_t  \right)_{t \geq 0}$ which belongs to $\mathfrak{B}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$ and solves equation (\ref{basic equation}).
		\label{uniqueness}
	\end{corollary}
	%
	Now, let's state the main result of this section:
	\begin{theorem}
		Assume that \textbf{(H)} holds for a sufficiently large $\beta >0$. Then the DRBSDE (\ref{basic equation}) has a unique solution $(Y_t,Z_t,K^{+}_t,K^{-}_t,M_t)_{t \geq 0}$.
		\label{Existence and Uniqueness Theorem}
	\end{theorem}
	%
	\begin{proof}
		For the existence, as usual, the proof is divided into two stages:
		\begin{itemize}
			\item[(i)] \textit{Step 1:  The case when $f$ does not depend on $(y,z)$.}\\
			We first consider the case when the driver $f$ does not depend on the solution, i.e. $f$ satisfies the following $f(\omega,t,y,z)=:g(\omega,t)$ for all $(\omega,t,y,z) \in \Omega \times [0,T] \times \mathbb{R} \times \mathbb{R}^d$. 
			By using Theorems \ref{Existence and uniquess theorem BSDE}, \ref{Comparison theorem BSDE}, Lemmas \ref{proof of lemma integrable}, \ref{proof of measurability L,U}, and Remark \ref{Remark on the construction of the BSDE}, one can show, proceeding as in \cite[Theorem 4.1]{BDEM}, that there exists a solution $(Y_t,Z_t,K^+_t,K^-_t,M_t)_{t \geq 0}$ of the DRBSDE (\ref{basic equation}) associated with $(\xi,g,L,U)$ in the sense of Definition \ref{definition}.
			\item[(ii)] \textit{Step 2:  Case of a driver $f$ depending on $(y,z)$.}\\
			The proof in the case of a general stochastic Lipschitz driver is similar to the proof of Theorem 4.2 in \cite{BDEM}, relying on a usual fixed-point argument and a priori estimates for DRBSDE (\ref{basic equation}) provided in Proposition \ref{basic Estimastion for BSDE}.
		\end{itemize}
	\end{proof}
