	\subsection{Explicit connections between DRBSDE solutions in $\mathbb{F}$ and $\mathbb{G}$ filtrations}
	We aim to establish an explicit relationship between the state solutions of DRBSDEs in the global flow of information $\mathbb{G}$ and the partial flow $\mathbb{F}$, particularly when the generator does not depend on the variables $(y,z)$, i.e., $g(\omega,t):=f(\omega,t,y,z)$ for all $(\omega,t,y,z) \in \Omega \times [0,T] \times \mathbb{R} \times \mathbb{R}^d$. 

	Two distinct linkages are employed to do this:
	\begin{enumerate}
		\item The first one gives the connection between DRBSDE solutions in the  $\left(\mathbb{G},\mathbb{Q}\right)$ and $\left(\mathbb{F},\mathbb{P}\right)$ frameworks.

		\item The second link connects the DRBSDE solutions in the  $\left(\mathbb{G},\mathbb{Q}\right)$ and $\left(\mathbb{F},\mathbb{Q}\right)$ frameworks. Furthermore, we provide the general result when the diver $f$ is linear with respect to the $y$-variable.
	\end{enumerate}
	These findings include the important relationships between the stated filtrations $\mathbb{F}$ and $\mathbb{G}$ for both the newly introduced probability $\mathbb{Q}$ and the reference probability $\mathbb{P}$. 
	\subsubsection{First Link} 
	Our goal is to connect the solutions of DRBSDEs in the defaultable framework $\left(\mathbb{G},\mathbb{Q}\right)$ and the initial setting $\left(\mathbb{F},\mathbb{P}\right)$. This approach is inspired by the work of Alsheyab and Choulli \cite{alsheyab2023optimal}.
	\begin{theorem}
		Let's define:
		\begin{equation*}
			g^{\mathbb{F}}(s):=\tilde{\mathcal{E}}_sg(s),~U^{\mathbb{F}}_s=\tilde{\mathcal{E}}_s U_s,~L^{\mathbb{F}}_s:= \tilde{\mathcal{E}}_s L_{s},~ \xi^{\mathbb{F}}=\tilde{\mathcal{E}}_T\zeta_{T} \text{ and } V^{\mathbb{F}}=1-\tilde{\mathcal{E}}.
			\label{Definition of parametrs}
		\end{equation*} 
		Assume that conditions \textbf{(H)} hold, and that there exist a special semimartingale $\left( \mathcal{J}_t^{\mathbb{F}}\right)_{t \leq T}$ of the following form:
		\begin{equation*}
			\begin{split}
				\mathcal{J}^{\mathbb{F}}_{t}=\xi^{\mathbb{F}}+\left( \mathcal{K}^{\mathbb{F},+}_{T}-\mathcal{K}^{\mathbb{F},,+}_{t}\right)-\left( \mathcal{K}^{\mathbb{F},-}_{ T}-\mathcal{K}^{\mathbb{F},-}_{t}\right) -\int_{t }^{T} \mathcal{Z}^{\mathbb{F}}_s d B_s,\quad t\in[0,T],
			\end{split}
		\end{equation*}
		with $L^{\mathbb{F}}_t \leq \mathcal{J}^{\mathbb{F}}_t \leq U^{\mathbb{F}}_t$,  $\forall t \in [0,T]$, $\mathbb{P}\text{-a.s.}$, $\left(\mathcal{K}^{\mathbb{F},\pm}_t\right)_{t \leq T} \in \mathcal{S}^2_T(\mathbb{F},\mathbb{P})$ and $\left( \int_{0}^{t}\mathcal{Z}^{\mathbb{F}}_s dB_s\right)_{t \leq T} \in \mathcal{H}^2_{T}(\mathbb{F},\mathbb{P})$. Moreover, we assume:
		\begin{equation*}
			\mathbb{E}\left[e^{\beta \mathcal{A}_T}|\zeta_T|^2 + \int_{0}^{T} e^{\beta \mathcal{A}_s}|\zeta_s|^2 d V^{\mathbb{F}}_s \right] < +\infty.
			\label{H}
		\end{equation*}

		Let $(Y^{\mathbb{F}}_t,Z^{\mathbb{F}}_t,K^{\mathbb{F},+}_t,K^{\mathbb{F},-}_t)_{t \leq T}$ be the   $(\mathbb{F},\mathbb{P})$-solution of the following DRBSDE:
		\begin{equation}
			\left\{
			\begin{split}
				\text{(i)} &~ \mathbb{P}\text{-a.s. for all } t \in [0,T]\\
				& Y^{\mathbb{F}}_{t}=\xi^{\mathbb{F}}+\int_{t}^{T} g^{\mathbb{F}}(s)ds+\int_{t}^{T}\zeta_s d V^{\mathbb{F}}_s+\left( K^{\mathbb{F,}+}_{ T }-K^{\mathbb{F},+}_{t}\right)\\
				&\qquad\qquad\qquad-\left( K^{\mathbb{F},-}_{T}-K^{\mathbb{F},-}_{t}\right) -\int_{t }^{T} Z^{\mathbb{F}}_s d B_s;\\
				\text{(ii)} &~  L^{\mathbb{F}}_t \leq Y^{\mathbb{F}}_t \leq U^{\mathbb{F}}_t,~  \forall t \in [0,T ],~\mathbb{P}\text{-a.s.};\\
				\text{(iii)} &~ \int_0^{T }(Y^{\mathbb{F}}_{t}-L^{\mathbb{F}}_{t})dK^{\mathbb{F},+}_t=\int_0^{T \wedge \tau}(U^{\mathbb{F}}_{t}-Y^{\mathbb{F}}_{t})dK^{\mathbb{F},-}_t=0,~\mathbb{P}\text{-a.s.},
			\end{split}
			\right.
			\label{basic equation comparison}
		\end{equation}
		associated with data $\left(\xi^{\mathbb{F}},g^{\mathbb{F}},L^{\mathbb{F}},U^{\mathbb{F}}\right)$.

		Let $(Y_t, Z_t, K^{+}_t, K^{-}_t, M_t)_{t \geq 0}$ be the $(\mathbb{G},\mathbb{Q})$-solution of the DRBSDE (\ref{basic equation}) associated with $(\xi,g,L,U)$. 
		Then, we have 
		\begin{equation*}
			\left\{
			\begin{split}
				&Y_t= \dfrac{Y^{\mathbb{F}}_t}{\tilde{\mathcal{E}}_t} \mathds{1}_{\{t<T \wedge\tau \}}+\xi \mathds{1}_{\{ t \geq T \wedge \tau \}},\quad K^{\pm}_t=\int_{0}^{t} \mathds{1}_{\{s \leq \tau\}} \dfrac{1}{\tilde{\mathcal{E}}_{s-}} dK^{\mathbb{F},\pm}_{s},\\
				&Z_t=\mathds{1}_{\{t \leq T\wedge \tau\}}\dfrac{Z^{\mathbb{F}}_t}{\tilde{\mathcal{E}}_{t-}},\quad \text{ and }\quad M_t=\int_{0}^{t}\mathds{1}_{\{s \leq T\}} \left(\zeta_s-\dfrac{Y^{\mathbb{F}}_{s}}{\tilde{\mathcal{E}}_{s}}\right) dN^{\mathbb{G}}_s
				,\quad\forall t \geq 0,~\mathbb{P}\text{-a.s.},
			\end{split}
			\right.
		\end{equation*}
		where $(N^{\mathbb{G}}_t)_{t \geq 0}$ is a $(\mathbb{G},\mathbb{P})$-martingale with integrable variation (see \cite{choulli2020martingale}) defined by:
		$$
		N^{\mathbb{G}}_t:=D_t-\int_{0}^{t} \mathds{1}_{\{s \leq \tau\}} \tilde{G}^{-1}_s dD^{o,\mathbb{F},\mathbb{P}}_s,\quad t \geq 0.
		$$
		\label{Delicate thm}
	\end{theorem}
	%

	%
	\begin{proof}
		In this proof, $\mathfrak{c}>0$ indicates a constant that remains independent of the index of any stochastic process sequences and may vary from line to line.

		The proof of Theorem \ref{Delicate thm} relies on some auxiliary results from the theory of reflected BSDEs and generalized reflected BSDEs, as well as some new results concerning the optimal control problems across $(\mathbb{F},\mathbb{P})$ and $(\mathbb{G},\mathbb{Q})$, which will be addressed briefly.

		First, it's worth noting that the existence and uniqueness of the solution for the DRBSDE (\ref{basic equation comparison}) are established in \cite[Theorem 3.3]{klimsiak2015reflected}. Further, the $\mathbb{L}^2$-integrability property for the $(\mathbb{F},\mathbb{P})$-solution can be classically obtained as in \cite{BDEM} under our hypothesis. Meanwhile, the existence and uniqueness result for the DRBSDE (\ref{basic equation}) is provided in Theorem \ref{Existence and Uniqueness Theorem}.

		The rest of the proof is divided into four main steps.
		\paragraph*{Step 1: Construction of the RBSDE penalization schemes in $(\mathbb{G},\mathbb{Q})$.}\emph{}\\
		Let $(Y^n_t,Z^n_t,K^{n,+}_t,M^n_t)_{t \geq 0}$ be the unique solution of the RBSDE associated with parameters $(\xi,g(t \wedge \tau)d(t \wedge \tau)-n(y-U_t)^{+},L)$. This means that for each $n \in \mathbb{N}$, we have
		\begin{equation}
			\left\{
			\begin{split}
				\text{(i)} &~ \mathbb{Q}\text{-a.s., for all } t \in [0,T],\\
				&~ Y^n_{t}=\xi+\int_{t}^{T} \mathds{1}_{\{s \leq \tau\}} g(s)ds-n\int_{t}^{T}(Y^n_s-U_s)^{+}ds+\left(  K^{n,+}_{T}-K^{n,+}_{t}\right) \\ &\qquad\qquad-\int_{t}^{T} Z^n_s d B_s-\int_{t }^{T }dM^n_s;\\
				\text{(ii)} &~  L_t \leq Y^n_t,~  \forall t \in [0,T \wedge \tau[,~\mathbb{Q}\text{-a.s.};\\
				\text{(iii)} &~ L_{T \wedge \tau} \leq Y_{T \wedge \tau},~\mathbb{Q}\text{-a.s.};\\
				\text{(iv)} &~   Y^n_t=\xi,~Z^n_t=dK^{n,+}_t=dM^n_t=0,\text{ on the set }\{t \geq T \wedge\tau\},~\mathbb{Q}\text{-a.s.};\\
				\text{(v)} &~ \text{Skorokhod condition:}  \int_0^{T \wedge \tau}(Y^n_{t}-L_{t})dK^{n,+}_t=0,~\mathbb{Q}\text{-a.s.}
			\end{split}
			\right.
			\label{basic equation RBSDE}
		\end{equation}
		The existence and uniqueness of the DRBSDE (\ref{basic equation RBSDE}) in the space $\mathfrak{B}^2_{T \wedge \tau}\left(\beta,\mathbb{G},\mathbb{Q}\right)$ can once again derived from Theorem \ref{Existence and Uniqueness Theorem}.\\
		We denote $K^{n,-}_t=n\int_{0}^{t}(Y^n_s-U_s)^{+}ds$. It is easy to see that $K^{n,-}_0=0$  and $K^{n,-}_t=K^{n,-}_{t \wedge T \wedge \tau}$ for any $t \geq 0$. Next, by employing a similar argument to the one used in Step 4 of the proof of Theorem 4.1 in \cite{el2022bsdes}, we can prove that the sequence $\left\{Y^n,Z^n,K^{n,+},K^{n,-},M^n\right\}_{n \in \mathbb{N}}$ forms a Cauchy sequence in $\mathfrak{B}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$. Consequently, there exists a process $(Y,Z,K^{+},K^{-},M)$ that belongs to $\mathfrak{B}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$ and serves as the limit of the sequence $\left\{Y^n,Z^n,K^{n,+},K^{n,-},M^n\right\}_{n \in \mathbb{N}}$ in the relevant spaces. This limit process  also satisfies the DRBSDE (\ref{basic equation}).
		\paragraph*{Step 2: RBSDE (\ref{basic equation RBSDE}) and related optimal stopping problems across $(\mathbb{G},\mathbb{Q})$ and $(\mathbb{F},\mathbb{P})$.}\emph{}\\
		Using a classical result of the theory of one reflected BSDE related to optimal stopping problems, we can express the process $\left(Y^n_t\right)_{t \geq 0}$ as follows:
		\begin{equation*}
			\begin{split}
				Y^n_t+\int_{0}^{t \wedge \tau}g(s)ds-\int_{0}^{t \wedge \tau}d K^{n,-}_s=\esssup_{\theta \in \mathfrak{T}_{t \wedge \tau}^{T \wedge \tau}\left(\mathbb{G}\right)}\mathbb{E}_{\mathbb{Q}}\left[X^{\mathbb{G},n}_{\theta} \mid \mathcal{G}_t\right]=:S^{\mathbb{G},\mathbb{Q},n}_t,
			\end{split}
			\label{Mocci oujda}
		\end{equation*}
		where  $(X^{\mathbb{G},n}_{t})_{t \geq 0}$ is the RCLL $\mathbb{G}$-adapted process stopped at $T \wedge \tau$, defined by:
		\begin{equation}
			X^{\mathbb{G},n}=\int_{0}^{\cdot \wedge T \wedge \tau} g(s)ds-\int_{0}^{\cdot \wedge T \wedge \tau}dK^{n,-}_s+L_{}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\zeta_{T \wedge \tau} \mathds{1}_{\llbracket T \wedge \tau,+\infty \llbracket}.
			\label{reward process}
		\end{equation}

		It's clear that
		$
		\int_{0}^{\cdot \wedge T \wedge \tau}dK^{n,-}_s=n\int_{0}^{\cdot \wedge T} \left(Y^n_s \mathds{1}_{\{s <\tau\}}-U_s \mathds{1}_{\{s <\tau\}}\right)^{+} ds
		$. Additionally, since $Y^n=(Y^n)^{\tau}$, using Theorem 2 in \cite{choulli2024optimal}, we derive the existence of a unique RCLL $\mathbb{F}$-progressively measurable process $Y^{n,\mathbb{F}}$ such that  $
		Y^n_s \mathds{1}_{\{s <\tau\}}=Y^{n,\mathbb{F}}_s \mathds{1}_{\{s <\tau\}}
		$. This transformation switches the process $(K^{n,-}_t)_{t \geq 0}$ into $
		K^{n,-}=n\int_{0}^{\cdot \wedge T \wedge \tau}  \left(Y^{n,\mathbb{F}}_s-U_s\right)^{+} ds
		$. Furthermore, Theorem 2 in \cite{choulli2024optimal} implies that the process $\left(Y^{n,\mathbb{F}}_t\right)_{t \leq T}$ can be expressed as: $Y^{n,\mathbb{F}}_t=G^{-1}_t\mathbb{E}\left[Y^n_s \mathds{1}_{\{s <\tau\}} \mid \mathcal{F}_t\right]$ for any $t \in [0,T]$.\\ 
		Let $\beta>0$. Using Jensen's inequality, the fact that $Y^n=\xi$ on $\llbracket T \wedge \tau,+\infty\llbracket$, that the process $(\mathcal{A}_t)_{t \leq T}$ is $\mathbb{F}$-adapted, Lemma \ref{Lemma of integrability}, Remark \ref{Remark of epsilon} and Lemma 4.1 in \cite{BDEM}, we conclude that $Y^{n,\mathbb{F}} \in \mathcal{S}^2_{T}\left(\beta,\mathbb{F},\mathbb{P}\right)$ with $\left\|Y^{n,\mathbb{F}}\right\|^2_{\mathfrak{B}^2_T(\beta,\mathbb{F},\mathbb{P})} \leq \mathfrak{c}$ for any $n \in \mathbb{N}$.

		The idea is to find a suitable way to apply Theorem 3 in  \cite{choulli2024optimal}. To do so, we first  need to identify the unique pair $(X^{\mathbb{F},n},k^{(pr),n})$ associated with the process $X^{\mathbb{G},n}$ defined in (\ref{reward process}). This requires finding an $\mathbb{F}$-optional process $X^{\mathbb{F},n}$ and an $\mathbb{F}$-progressively measurable process $k^{(pr),n}$ such that  $X^{\mathbb{G},n}=X^{\mathbb{F},n}\mathds{1}_{\llbracket 0,\tau \llbracket}+\int_{0}^{\cdot} k^{(pr),n}_s dD_s$. However, by performing simple computations, we get:
		\begin{equation*}
			\left\{
			\begin{split}
				X^{\mathbb{F},n}&=\int_{0}^{\cdot \wedge T} g(s)ds-n\int_{0}^{\cdot \wedge T } \left(Y^{n,\mathbb{F}}_s-U_s \right)^{+} ds+L_{}\mathds{1}_{\llbracket 0,T   \llbracket}+\zeta_{T} \mathds{1}_{\llbracket T ,+\infty \llbracket},\\
				k^{(pr),n}&=\int_{0}^{\cdot \wedge T} g(s)ds-n\int_{0}^{\cdot \wedge T } \left(Y^{n,\mathbb{F}}_s-U_s \right)^{+} ds+\zeta_{T \wedge \cdot}.
			\end{split}
			\right.
			\label{Associated process}
		\end{equation*}
		Let $\mathcal{X}^{\mathbb{F},n}:=\left(\tilde{\mathcal{E}}X^{\mathbb{F},n} -\int_{0}^{\cdot}k^{(op),n}_s d\tilde{\mathcal{E}}_s\right)^T$. Using  integration by part formula in the $(\Omega,\mathcal{F},\mathbb{F},\mathbb{P})$-setup and the fact that $d V^{\mathbb{F}}=-d\tilde{\mathcal{E}}$, we derive
		\begin{equation}
			\begin{split}
				\mathcal{X}^{\mathbb{F},n}&=\int_{0}^{\cdot \wedge T} g^{\mathbb{F}}(s)ds-n\int_{0}^{\cdot \wedge T }  \left(\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s \right)^{+} ds+\int_{0}^{\cdot \wedge T}\zeta_s dV^{\mathbb{F}}_s+L^{\mathbb{F}}\mathds{1}_{\llbracket 0,T   \llbracket}+\xi^{\mathbb{F}} \mathds{1}_{\llbracket T ,+\infty \llbracket},
			\end{split}
			\label{Chef de la vie}
		\end{equation}
		with $	\hat{Y}^{n,\mathbb{F}}:=\tilde{\mathcal{E}}Y^{n,\mathbb{F}}$ in $[0,T]$. As $0<\tilde{\mathcal{E}}\leq 1$, $\tilde{\mathcal{E}}$ is an RCLL $\mathbb{F}$-adapted process, and $Y^{n,\mathbb{F}} \in \mathcal{S}^2_{T}\left(\beta,\mathbb{F},\mathbb{P}\right)$, we can derive $\hat{Y}^{n,\mathbb{F}} \in \mathcal{S}^2_{T}\left(\beta,\mathbb{F},\mathbb{P}\right)$ with $\left\|\hat{Y}^{n,\mathbb{F}}\right\|^2_{\mathfrak{B}^2_T(\beta,\mathbb{F},\mathbb{P})} \leq \mathfrak{c}$ for all $n \in \mathbb{N}$.\\
		By applying Theorem 3 in \cite{choulli2024optimal}, we have:
		\begin{equation}
			\begin{split}
				&Y^n+\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{\cdot \wedge T \wedge \tau}d K^{n,-}_s\\
				&=\dfrac{\mathcal{\hat{S}}^{\mathbb{F},n}}{\tilde{\mathcal{E}}^T}\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T+\int_{0}^{\cdot \wedge T}\left(k^{(pr),n}_s-\dfrac{\int_{0}^{s}k^{(pr),n}_u d\tilde{\mathcal{E}}_u}{\tilde{\mathcal{E}}_s}\right) dN^{\mathbb{G}}_s,
			\end{split}
			\label{Stable 2}
		\end{equation}
		where $\mathcal{\hat{S}}^{\mathbb{F},n}_t=\esssup_{\theta \in \mathfrak{T}_{t}^{T}(\mathbb{F})}\mathbb{E}\left[\mathcal{X}^{\mathbb{F},n}_{\theta} \mid \mathcal{F}_t\right]$ for $t \in [0,T]$, with $\left( \mathcal{X}^{\mathbb{F},n}_t\right)_{t \geq 0}$ giving by (\ref{Chef de la vie}).
		\paragraph*{Step 3: Optimal stopping problem and related generalized RBSDE in $(\mathbb{F},\mathbb{P})$}
		The optimal stopping problem $\left(\mathcal{\hat{S}}^{\mathbb{F},n}_t\right)_{t \leq T}$ with wealth process (\ref{Chef de la vie}) lead us to consider the following generalized reflected BSDE (GRBSDE, for short): 
		\begin{equation}
			\left\{
			\begin{split}
				\text{(i)}&~ \mathbb{P}\text{-a.s., for all } t \in [0,T],\\ 
				& \hat{Y}^{n,\mathbb{F},\ast}_t=\xi^{\mathbb{F}}+\int_{t}^{T}dV^{n,\mathbb{F},\ast}_s+(K^{n,\mathbb{F},+}_T-K^{n,\mathbb{F},\ast}_t)-\int_{t  }^{T} \hat{Z}^{n,\mathbb{F},\ast}_s d B_s;\\
				\text{(ii)} &~  L^{\mathbb{F}}_t \leq \hat{Y}^{n,\mathbb{F},\ast}_t,~  \forall t \in [0,T],~\mathbb{P}\text{-a.s.};\\
				\text{(iii)} &~ \text{Skorokhod condition:}  \int_0^{T }(\hat{Y}^{n,\mathbb{F},\ast}_{t}-L^{\mathbb{F}}_{t})dK^{n,\mathbb{F},+}_t=0,~\mathbb{P}\text{-a.s.},
			\end{split}
			\right.
			\label{basic equation RBSDE in F,P}
		\end{equation}
		where the generator is giving in the following form  $V^{n,\mathbb{F},\ast}_t=\int_{0}^{t}\big\{g^{\mathbb{F}}(s)-n (\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}\big\}ds+\int_{0}^{t}\zeta_s dV^{\mathbb{F}}_s$, $t \in [0,T]$. 
		%

		Note that in the GRBSDE (\ref{basic equation RBSDE in F,P}), the process $K^{n,\mathbb{F},+}$ is continuous due to the fact that $L^{\mathbb{F}}=\tilde{\mathcal{E}}L$ could have a jump only at $\tau$. However, the jumps arising from the process $\tilde{\mathcal{E}}$ are equal to those of $\hat{Y}^{n,\mathbb{F},\ast}$ since $\Delta V^{\mathbb{F}}=-\Delta\tilde{\mathcal{E}}$, and this latter jumps when $\Delta D^{o,\mathbb{F},\mathbb{P}}$ does from (\ref{Definition of E and E tilde}), or equivalently when the defaultable $(D_t)_{t \geq 0}$ does at the default time $\tau$ due to the optional duality relation for jump processes (see Theorem 5.27 in \cite{bookHe}, pp. 150). This fact will be used implicitly toward the rest of the proof while considering the reflection processes of other GRBSDEs.

		Here we will gives a brief study of the GRBSDE (\ref{basic equation RBSDE in F,P}) concerning the existence, uniqueness, and its convergence results toward the solution of a special form of GRBSDE in the $\left(\mathbb{F},\mathbb{P}\right)$-framework. This will be used to provide the main result described in the four step. 

		The GRBSDE (\ref{basic equation RBSDE in F,P}) is a particular case of the GRBSDE considered in \cite{fakhouri20192} or in \cite{klimsiak2015reflected} with an associated coefficient $f\equiv 0$. We will use of the results from \cite{fakhouri20192} to obtain a strong $\mathbb{L}^2$-integrability result for the associated solution of (\ref{basic equation RBSDE in F,P}) as we have $\mathbb{L}^2$-integrable data. To begin, noting that $\tilde{\mathcal{E}} \leq 1$, we can infer $L^{\mathbb{F}} \leq \mathbb{E}\left[\sup_{0 \leq t \leq T} (L_s)^{+} \mid \mathcal{F}_t\right]$. Then, under assumption \textbf{(H3)}, we conclude that the last term is a square integrable $(\mathbb{F},\mathbb{P})$-martingale. Our goal now is to show that  $\left|V^{n,\mathbb{F},\ast}\right|^2_T \in \mathbb{L}^2\left(\Omega,\mathcal{F}_T,\mathbb{P}\right)$, where $\left|V^{n,\mathbb{F},\ast}\right|$ denotes the total variation of the process $\left(V^{n,\mathbb{F},\ast}_t\right)_{t \leq T}$. Since $dV^{\mathbb{F}}$ is a positive measure, we have
		\begin{equation*}
			\begin{split}
				\mathbb{E}\left[\left|V^{n,\mathbb{F},\ast}\right|^2_T\right]
				& \leq \dfrac{3}{\beta} \mathbb{E}\left[\int_{0}^{T} e^{\beta \mathcal{A}_s} \left| g(s)\right|^2 ds \right]+3\mathbb{E}\left[\left( \int_{0}^{T}e^{-\beta \mathcal{A}_s}dV^{\mathbb{F}}_s\right)\left( e^{\beta \mathcal{A}_s} \left|\zeta_{s}\right|^2dV^{\mathbb{F}}_s\right) \right]\\
				&\qquad\qquad+3T^2n^2 \mathbb{E}\left[\sup_{0 \leq t \leq T}e^{\beta \mathcal{A}_t} \left\{\left|\hat{Y}^{n,\mathbb{F}}_t\right|^2+\left| U^{-}_t\right|^2\right\}\right]^{\frac{1}{2}}.
			\end{split}
		\end{equation*}
		From Remark \ref{Remark of epsilon}, we derive that $V^{\mathbb{F}} \leq 1$, then $\int_{0}^{T}e^{-\beta \mathcal{A}_s}dV^{\mathbb{F}}_s \leq 1$. Consequently, $\mathbb{E}\left[\left|V^{n,\mathbb{F},\ast}\right|^2_T\right]<+\infty$. Theorem 3 in \cite{fakhouri20192} guarantees the existence of a unique triplet of $\mathbb{F}$-progressively measurable processes $\left(\hat{Y}^{n,\mathbb{F},\ast}_t,K^{n,\mathbb{F},+}_t,\hat{Z}^{n,\mathbb{F},\ast}_t\right)_{t \leq T}$ satisfying GRBSDE (\ref{basic equation RBSDE in F,P}) with  $\left(\hat{Y}^{n,\mathbb{F},\ast},\hat{Z}^{n,\mathbb{F},\ast},K^{n,\mathbb{F},+}_T\right) \in \mathcal{D}^2_T\left(\mathbb{F},\mathbb{P}\right) \times \mathcal{H}^2_T(\mathbb{F},\mathbb{P}) \times \mathcal{S}^2_T\left(\mathbb{F},\mathbb{P}\right)$.\\
		Considering the construction of the process $\left(\hat{Y}^{n,\mathbb{F}}_t\right)_{t \leq T}$ and the fact that $Y=\xi$ on $\llbracket T \wedge \tau,+\infty \llbracket$, we obtain $\hat{Y}^{n,\mathbb{F}}_t=\tilde{\mathcal{E}}_tY^{n,\mathbb{F}}_t=\frac{\tilde{\mathcal{E}}_t}{G_t} \mathbb{E}\left[Y^n_t \mathds{1}_{\{t < \tau\}}\mid \mathcal{F}_t\right]= \mathbb{E}\left[Y^n_t + \xi \mathds{1}_{\{t \geq \tau\}}\mid \mathcal{F}_t\right]$. Subsequently, using Remark \ref{Remark of epsilon}, $G_t=G_0\tilde{\mathcal{E}}_t \mathcal{E}_t=\tilde{\mathcal{E}}_t \mathcal{E}_t$, the $\mathbb{F}$-adeptness of the barrier $U$, the definition of the Azéma supermartingale $G$, $U^{\mathbb{F}}=\tilde{\mathcal{E}} U$, the assumption $U^{T \wedge \tau}=U$, and Jensen's inequality, we deuce that $\left(\hat{Y}^{n,\mathbb{F}}_t-U^{\mathbb{F}}_t\right)^{+} \leq  \frac{1}{\epsilon}\mathbb{E}\left[  \left(\left(Y^n_t-U_t\right)- \left(\xi-U_{\tau}\right)\mathds{1}_{\{t\geq \tau\}}\right)^{+}\mid \mathcal{F}_t\right]$. Consequently, using Fubini's theorem, the continuity of the Lebesgue measure, and $ U_{\tau} \geq \xi $, we have $n\int_{t \wedge \tau}^{t}(\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}ds=0$. Lemma \ref{Lemma of integrability}, the definition of the Radon derivative $\frac{d \mathbb{Q}}{d \mathbb{P}}$ giving by (\ref{local continuity of Q}) together with Remark \ref{Remark of epsilon}, yields for all $t \in [0,T]$,
		\begin{equation*}
			\begin{split}
				\mathbb{E}\left(n\int_{0}^{t}(\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}ds\right)^2 \leq \frac{1}{\epsilon} \mathbb{E}_{\mathbb{Q}}\left(n\int_{0}^{t \wedge \tau}(Y^{n}_s-U_s)^{+}ds\right)^2  
			\end{split}
		\end{equation*}
		Now, employing a similar uniform estimation result from the paper by El Otmani et al. \cite{el2022bsdes} (see estimation (18) on page 14) which holds under our conditions with respect to the probability measure $\mathbb{Q}$, we derive the existence of a constant $\mathfrak{c}>0$ such that
		\begin{equation*}
			\sup_{n \in \mathbb{N}}\mathbb{E}\left(n\int_{0}^{T}(\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}ds\right)^2 \leq  \mathfrak{c}.
		\end{equation*}
		Using this with a standard localization procedure via the sequence of $\mathbb{F}$-stopping times $\{\sigma_k\}_{k \in \mathbb{N}}$ defined by $\sigma_k=\inf\left\{t>0: \mathcal{A}_t>k\right\} \wedge T$ following the same techniques of Proposition \ref{basic Estimastion for BSDE}, we can establish the following uniform a priori estimates:
		\begin{equation}
			\begin{split}
				&\mathbb{E}\sup_{s \in [0, T]} e^{\beta \mathcal{A}_s} \left|\hat{Y}^{n,\mathbb{F},\ast}_{s}\right|^2+\mathbb{E}\int_{0}^{T}e^{\beta \mathcal{A}_s} \left|\hat{Y}^{n,\mathbb{F},\ast}_s \alpha_s\right|^2ds+\mathbb{E}\int_{0}^{T}e^{\beta \mathcal{A}_s}\left|\hat{Z}^{n,\mathbb{F},\ast}_s\right|^2 ds+\mathbb{E}\left| K^{n,\mathbb{F},+}_{T}\right|^2\\
				& \leq \mathfrak{c}\left(  \mathbb{E}\int_{0}^{T}e^{\beta \mathcal{A}_s}\left|\dfrac{g^{\mathbb{F}}(s)}{\alpha_s}\right|^2 ds  + \mathbb{E} \sup_{s \in  [0,T]} e^{2\beta \mathcal{A}_s}\left| \left( L^{\mathbb{F}}_s\right)^{+}\right|^2  +\mathbb{E}\int_{0}^{T}e^{\beta \mathcal{A}_s} \left| \zeta_s\right|^2  dV^{\mathbb{F}}_s \right).
			\end{split}
			\label{EST 2}
		\end{equation}
		From the uniform estimate (\ref{EST 2}) of the sequence $\left\{\hat{Z}^{n,\mathbb{F},\ast}, K^{n,\mathbb{F},+}\right\}_{n \in \mathbb{N}}$ and the Hilbert structure of the associated $\mathbb{L}^2$-spaces, we can extract further subsequences, still denoted by the sequence index $n$, which exhibit a weak convergence in the pertinent topological spaces to a given pair process $\left(\hat{Z}^{\mathbb{F},\ast}, K^{\mathbb{F},+}\right) \in \mathcal{H}^2_T\left(\beta,\mathbb{F},\mathbb{P}\right) \times \mathcal{S}^2_T(\mathbb{F},\mathbb{P})$ with $K^{\mathbb{F},+}$ $\mathbb{F}$-predictable. On the other hand, using Remark \ref{Remark of epsilon} and (\ref{EST 2}), and the Step 4 of the proof of Theorem 4.1 in \cite{el2022bsdes} , we conclude that, the increasing sequence of $\mathbb{F}$-adapted continuous processes $\left\lbrace K^{n,\mathbb{F},-}:=n\int_{0}^{\cdot}(\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}ds\right\rbrace_{n \in \mathbb{N}}$ is a Cauchy sequence which respect to the $\mathcal{S}^2_T(\mathbb{F},\mathbb{P})$-norm. Thus, there exists an $\mathbb{F}$-adapted continuous increasing process $K^{\mathbb{F},-} \in \mathcal{S}^2_T(\mathbb{F},\mathbb{P})$ serving as the strong limit in the $\mathcal{S}^2_T(\mathbb{F},\mathbb{P})$-norm of $\{K^{n,\mathbb{F},-}\}_{n \in \mathbb{N}}$. \\
		Now, for $n>p\geq 0$,  applying once again It\^{o}'s from to the process $e^{\frac{\beta}{2} \mathcal{A}_t}\left|\hat{Y}^{n,\mathbb{F},\ast}_{t}-\hat{Y}^{p,\mathbb{F},\ast}_{t}\right|^2$, the Skorokhod condition, Cauchy–Schwarz inequality, and assumption $(\mathbf{H_2})$-(b), we get
		\begin{equation}
			\begin{split}
				&\mathbb{E}\int_{0}^{T}e^{\frac{\beta}{2} \mathcal{A}_s} \left|\hat{Y}^{n,\mathbb{F},\ast}_s-\hat{Y}^{p,\mathbb{F},\ast}_{s} \right|^2 \alpha_s^2ds+\mathbb{E}\int_{0}^{T}e^{\frac{\beta}{2} \mathcal{A}_s}\left|\hat{Z}^{n,\mathbb{F},\ast}_s-\hat{Z}^{p,\mathbb{F},\ast}_s\right|^2 ds\\
				& \leq  2 \left( \mathbb{E}\int_{0}^{T}e^{\beta \mathcal{A}_s} \left|\hat{Y}^{n,\mathbb{F},\ast}_{s}-\hat{Y}^{p,\mathbb{F},\ast}_{s}\right|^2 \alpha_s^2 ds\right)^{\frac{1}{2}}  \left(\frac{1}{\epsilon} \mathbb{E} \left|K^{p,\mathbb{F},-}_T-K^{n,\mathbb{F},-}_T\right|^2\right)^{\frac{1}{2}} \\
				&\leq \mathfrak{c}\left(\mathbb{E} \left|K^{p,\mathbb{F},-}_T-K^{n,\mathbb{F},-}_T\right|^2\right)^{\frac{1}{2}} .
			\end{split}
			\label{Real}
		\end{equation}
		The $\mathbb{L}^2$-strong convergence of the sequence $\{K^{n,\mathbb{F},-}\}_{n \in \mathbb{N}}$ implies: for any $\beta>0$
		$$
		\lim\limits_{n,p\rightarrow+\infty} 
		\left\{\mathbb{E}\int_{0}^{T}e^{\frac{\beta}{2} \mathcal{A}_s} \left|\hat{Y}^{n,\mathbb{F},\ast}_s-\hat{Y}^{p,\mathbb{F},\ast}_{s} \right|^2 \alpha_s^2ds+\mathbb{E}\int_{0}^{T}e^{\frac{\beta}{2} \mathcal{A}_s}\left|\hat{Z}^{n,\mathbb{F},\ast}_s-\hat{Z}^{p,\mathbb{F},\ast}_s\right|^2 ds\right\} =0.
		$$
		Applying the Burkholder-Davis-Gundy inequality (B-D-G) \cite[Theorem IV.48, pp. 193]{bookProtter} with (\ref{Real}), allows us to conclude that, for any $\beta>0$
		$$
		\lim\limits_{n,p\rightarrow+\infty} \mathbb{E}\left[\sup_{s \in [0, T]}e^{\frac{\beta}{2} \mathcal{A}_{s}} \left|\hat{Y}^{n,\mathbb{F},\ast}_{s}-\hat{Y}^{p,\mathbb{F},\ast}_{s}\right|^2\right]=0, 
		$$
		Then there exists a unique RCLL $\mathbb{F}$-adapted process $\left(\hat{Y}^{\mathbb{F},\ast}_{t}\right)_{t \leq T}$ such that the constructed pair $\left(\hat{Y}^{\mathbb{F},\ast},\hat{Z}^{\mathbb{F},\ast}\right)$ satisfies
		$$
		\lim\limits_{n\rightarrow+\infty} \left\{\left\|\hat{Y}^{n,\mathbb{F},\ast}-\hat{Y}^{\mathbb{F},\ast}\right\|^2_{\mathcal{S}^2_T\left( \frac{\beta}{2},\mathbb{F},\mathbb{P}\right)}+\left\|\hat{Z}^{n,\mathbb{F},\ast}-\hat{Z}^{\mathbb{F},\ast}\right\|^2_{\mathcal{H}^2_T\left( \frac{\beta}{2},\mathbb{F},\mathbb{P}\right) } \right\}=0.
		$$ 
		%Moreover, we have 
		%$$\lim\limits_{n \rightarrow+\infty}\left\|\hat{Z}^{n,\mathbb{F},\ast}-\hat{Z}^{\mathbb{F},\ast}\right\|^2_{\mathcal{H}^2_T\left( \frac{\beta}{2},\mathbb{F},\mathbb{P}\right) }=0.$$
		From (\ref{basic equation RBSDE in F,P}), we can also obtain that $\{K^{n,\mathbb{F},+}\}_{n \in \mathbb{N}}$ is a Cauchy sequence in $\mathcal{D}^2_T(\mathbb{F},\mathbb{P})$,
		therefore 
		$$
		\lim\limits_{n\rightarrow+\infty}  \left\|K^{n,\mathbb{F},+}_T-K^{\mathbb{F},+}_T\right\|^2_{\mathcal{D}^2_T(\mathbb{F},\mathbb{P})}=0,$$ 
		and the process $K^{\mathbb{F},+}$ exhibits continuous paths.\\ 
		Passing to the limit element by element in (\ref{basic equation RBSDE in F,P}), we derive that the quadruplet $\left(\hat{Y}^{\mathbb{F},\ast}_{t},\hat{Z}^{\mathbb{F},\ast}_{t},K^{\mathbb{F},+}_{t},K^{\mathbb{F},-}_{t}\right)_{t \leq T}$ satisfies the following BSDE, for any $t \in [0,T]$,  
		$$
		\hat{Y}^{\mathbb{F},\ast}_t=\xi^{\mathbb{F}}+\int_{t}^{T}g^{\mathbb{F}}(s)ds+\int_{t}^{T}\zeta_s dV^{\mathbb{F}}_s+\left( K^{\mathbb{F},+}_T-K^{\mathbb{F},+}_t\right) -\left( K^{\mathbb{F},-}_T-K^{\mathbb{F},-}_t\right) -\int_{t}^{T} \hat{Z}^{\mathbb{F},\ast}_s d B_s,
		$$
		and $\left(\hat{Y}^{\mathbb{F},\ast}_{t},\hat{Z}^{\mathbb{F},\ast}_{t},K^{\mathbb{F},+}_{t},K^{\mathbb{F},-}_{t}\right)_{t \leq T} \in \mathfrak{C}^2_{T}\left( \beta,\mathbb{F},\mathbb{P}\right) \times \mathcal{H}^2_{T}\left( \beta,\mathbb{F},\mathbb{P}\right) \times \mathcal{S}^2_T\left( \mathbb{F},\mathbb{P}\right)\times \mathcal{S}^2_T\left( \mathbb{F},\mathbb{P}\right)$.\\
		Additionally, it is clear that $\hat{Y}^{\mathbb{F},\ast}_t \geq L_t$ $\forall t \in [0,T]$.\\
		We have just seen that the sequence $\left(\hat{Y}^{n,\mathbb{F},\ast},\hat{K}^{n,\mathbb{F},+}\right)$ tends to $(\hat{Y}^{\mathbb{F},\ast}, K^{\mathbb{F},+})$ uniformly in $t$ in probability. Then the measure $dK^{n,\mathbb{F},+}$ tends to $dK^{\mathbb{F},+}$  weakly in probability, hence
		$$
		\int_{0}^{T}\left(\hat{Y}^{n,\mathbb{F},\ast}_s-L^{\mathbb{F}}_s\right)d\hat{K}^{n,\mathbb{F},+}_s \xrightarrow[n \rightarrow+\infty]{\mathbb{P}} \int_{0}^{T}\left(\hat{Y}^{\mathbb{F},\ast}_s-L^{\mathbb{F}}_s\right)dK^{\mathbb{F},+}_s.
		$$
		Thus, from (\ref{basic equation RBSDE in F,P})-(iii) we have $\int_{0}^{T}\left(\hat{Y}^{\mathbb{F},\ast}_s-L^{\mathbb{F}}_s\right)dK^{\mathbb{F},+}_s=0$.\\
		Putting together the argument presented above, we deduce that the limiting process $\left(\hat{Y}^{\mathbb{F},\ast}_{t},\hat{Z}^{\mathbb{F},\ast}_{t},K^{\mathbb{F},+}_{t},K^{\mathbb{F},-}_{t}\right)_{t \leq T} $ satisfies the following GRBSDE
		\begin{equation}
			\left\{
			\begin{split}
				\text{(i)} &~ \mathbb{P}\text{-a.s., for all } t \in [0,T],\\
				& \hat{Y}^{\mathbb{F},\ast}_t=\xi^{\mathbb{F}}+\int_{t}^{T}g^{\mathbb{F}}(s)ds+\int_{t}^{T}\zeta_s dV^{\mathbb{F}}_s+\left( K^{\mathbb{F},+}_T-K^{\mathbb{F},+}_t\right)\\\ &\qquad\qquad-\left(K^{\mathbb{F},-}_T-K^{\mathbb{F},-}_t\right) -\int_{t}^{T} \hat{Z}^{\mathbb{F},\ast}_s d B_s;\\
				\text{(ii)} &~  L^{\mathbb{F}}_t \leq \hat{Y}^{\mathbb{F},\ast}_t,~  \forall t \in [0,T],~\mathbb{P}\text{-a.s.};\\
				\text{(iii)} &~ \text{Skorokhod condition:}  \int_0^{T }(\hat{Y}^{\mathbb{F},\ast}_{t}-L^{\mathbb{F}}_{t})dK^{\mathbb{F},+}_t=0,~\mathbb{P}\text{-a.s.},
			\end{split}
			\right.
			\label{What wa got}
		\end{equation}
		\paragraph*{Step 4: Connection between solutions of DRBSDE in $(\mathbb{G},\mathbb{Q})$ and in $(\mathbb{F},\mathbb{P})$}
		The main result will be obtained by combining the optimal stopping problems satisfied by the sequence $\{\hat{Y}^{n,\mathbb{F},\ast}\}_{n \in \mathbb{N}}$ in $\left(\mathbb{F},\mathbb{P}\right)$ and the one satisfied by $\{Y^n\}_{n \in \mathbb{N}}$ in  $\left(\mathbb{G},\mathbb{Q}\right)$, the relationships between this two problems described by (\ref{Stable 2}) in \textbf{Step 2}, and the convergence results of these sequences giving in \textbf{Steps 1} and \textbf{3}. Finally, applying the same idea and procedure to the RBSDE penalization schemes (\ref{basic equation RBSDE}) in $\left(\mathbb{G},\mathbb{Q}\right)$ but this times with respect to the lower barrier $L$ and data $(\xi,f,U)$ allows us to derive the equality for values processes of DRBSDEs on $\llbracket0,T\wedge\tau\llbracket$, and then for other solution component by a simple integration by parts formula.\\
		To begin, using the GRBSDE (\ref{basic equation RBSDE in F,P}) and Corollary 2.9 in \cite{klimsiak2015reflected}, we have
		$$
		\hat{Y}^{n,\mathbb{F},\ast}_t=\esssup_{\theta \in \mathfrak{T}_{t}^{T}(\mathbb{F})}\mathbb{E}\left[\int_{t}^{\theta} dV^{n,\mathbb{F},\ast}_s+L^{\mathbb{F}}_{\theta} \mathds{1}_{\{\theta<T\}}+\xi^{\mathbb{F}}\mathds{1}_{\{\theta=T\}}  \mid \mathcal{F}_t\right]
		$$
		Therefore
		$$
		\hat{Y}^{n,\mathbb{F},\ast}+\int_{0}^{\cdot \wedge T}g^{\mathbb{F}}(s)ds+\int_{0}^{\cdot \wedge T}\zeta_s dV^{\mathbb{F}}_s-n\int_{0}^{\cdot \wedge T} (\hat{Y}^{n,\mathbb{F}}_s-U^{\mathbb{F}}_s)^{+}ds=\mathcal{\hat{S}}^{\mathbb{F},n}.
		$$
		Then, from (\ref{Stable 2}), we drive that:
		\begin{equation}
			\begin{split}
				&Y^n+\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{\cdot \wedge T \wedge \tau}d K^{n,-}_s\\
				&=\dfrac{\hat{Y}^{n,\mathbb{F},\ast}+V^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}^T}\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T+\int_{0}^{\cdot \wedge T}\left(\dfrac{k^{(pr),n}_s\tilde{\mathcal{E}}_s-\int_{0}^{s}k^{(pr),n}_u d\tilde{\mathcal{E}}_u}{\tilde{\mathcal{E}}_s}\right) dN^{\mathbb{G}}_s.
			\end{split}
			\label{Stable 2,2}
		\end{equation}
		Let us consider the term on the right hand side of the second line of (\ref{Stable 2,2}). Using an integration by part formula, we get
		\begin{equation*}
			k^{(pr),n}_s\tilde{\mathcal{E}}_s-\int_{0}^{s}k^{(pr),n}_u d\tilde{\mathcal{E}}_u= V^{n,\mathbb{F},\ast}_s+\zeta_{ s}\tilde{\mathcal{E}}_s \mathds{1}_{\{s<T\}}+\xi^{\mathbb{F}}\mathds{1}_{\{s \geq T\}}
			\label{MN6}
		\end{equation*}
		Plugging this into (\ref{Stable 2,2}), we get
		\begin{equation}
			\begin{split}
				&Y^n+\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{t \wedge T \wedge \tau}d K^{n,-}_s\\
				&=\dfrac{\hat{Y}^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}^T}\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T+\dfrac{V^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}^T}\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T+\int_{0}^{\cdot \wedge T}\left(\dfrac{V^{n,\mathbb{F},\ast}_s}{\tilde{\mathcal{E}}_s}\right) dN^{\mathbb{G}}_s\\
				&\qquad+\int_{0}^{\cdot \wedge T}\zeta_{s}\mathds{1}_{\{s<T\}}dN^{\mathbb{G}}_s+\int_{0}^{\cdot \wedge T} \frac{\zeta_{T}\tilde{\mathcal{E}}_T}{\tilde{\mathcal{E}}_s} \mathds{1}_{\{s\geq T\}}dN^{\mathbb{G}}_s.
			\end{split}
			\label{Stable 2,2,1}
		\end{equation}
		Using $\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T=\mathds{1}_{\{T < \tau\}}+\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}\mathds{1}_{\{\tau \leq T\}}$ and $\xi \mathds{1}_{\{T < \tau\}}=\zeta_{T \wedge \tau}\mathds{1}_{\{T < \tau\}}=\zeta_{T}\mathds{1}_{\{T < \tau\}}$, we have
		\begin{equation}
			\begin{split}
				\dfrac{\hat{Y}^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}^T}\left(\mathds{1}_{\llbracket 0, \tau\llbracket}\right)^T
				=\dfrac{\hat{Y}^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\xi\mathds{1}_{\{T < \tau\}}\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket},
			\end{split}
			\label{MN9}
		\end{equation}
		After doing a few simple calculations, we establish:
		\begin{equation}
			\int_{0}^{\cdot \wedge T}\zeta_{s}\mathds{1}_{\{s<T\}}dN^{\mathbb{G}}_s+\int_{0}^{\cdot \wedge T} \frac{\zeta_{T}\tilde{\mathcal{E}}_T}{\tilde{\mathcal{E}}_s} \mathds{1}_{\{s\geq T\}}dN^{\mathbb{G}}_s=\xi \mathds{1}_{\{\tau \leq T\}}\mathds{1}_{\llbracket T \wedge \tau,+\infty \llbracket}-\int_{0}^{\cdot \wedge T \wedge \tau}\frac{\zeta_{s}}{\tilde{G}_s} dD^{o,\mathbb{F},\mathbb{P}}_s.
			\label{MN7}
		\end{equation}
		Furthermore, by applying Lemma 4 in \cite{choulli2024optimal}, we get:
		\begin{equation}
			\begin{split}
				\int_{0}^{\cdot \wedge T}\frac{ V^{n,\mathbb{F},\ast}_s}{\tilde{\mathcal{E}}_s}dN^{\mathbb{G}}_s
				=\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{t \wedge T \wedge \tau}d K^{n,-}_s+\int_{0}^{\cdot \wedge T \wedge \tau}\frac{\zeta_{ s}}{\tilde{G}_s} dD^{o,\mathbb{F},\mathbb{P}}.
			\end{split}
			\label{MN8}
		\end{equation}
		Plugging (\ref{MN9}), (\ref{MN7}) (\ref{MN8}) in (\ref{Stable 2,2,1}), we derive 
		\begin{equation*}
			\begin{split}
				&Y^n+\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{t \wedge T \wedge \tau}d K^{n,-}_s\\
				&=\dfrac{\hat{Y}^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\int_{0}^{\cdot \wedge T \wedge \tau}g(s)ds-\int_{0}^{t \wedge T \wedge \tau}d K^{n,-}_s+\xi\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket}.
			\end{split}
		\end{equation*}   
		Thus
		\begin{equation}
			\begin{split}
				Y^n=\dfrac{\hat{Y}^{n,\mathbb{F},\ast}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\xi\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket}.
			\end{split}
			\label{Stable 2,2,1,1}
		\end{equation}
		Taking the limit as $n \rightarrow+\infty$ in (\ref{Stable 2,2,1,1}), and using the above convergence results for the sequences $\{Y^n\}_{n \in \mathbb{N}}$ and $\{\hat{Y}^{n,\mathbb{F},\ast}\}_{n \in \mathbb{N}}$ along an almost sure sequence, we deduce, by using the results from \textbf{Steps 1-3}, that 
		\begin{equation}
			Y=\dfrac{\hat{Y}^{\mathbb{F},\ast}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\xi\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket}.
			\label{MN10}
		\end{equation}
		Following a similar procedure, we can prove the existence of a unique quadruplet of processes $\left(\bar{Y}^{\mathbb{F},\ast}_t,\bar{Z}^{\mathbb{F},\ast}_t,\bar{K}^{\mathbb{F},+}_t,\bar{K}^{\mathbb{F},-}_t\right)_{t \leq T}$ satisfying the following GRBSDE:
		\begin{equation}
			\left\{
			\begin{split}
				\text{(i)} &~ \mathbb{P}\text{-a.s., for all } t \in [0,T],\\
				&~  \bar{Y}^{\mathbb{F},\ast}_t=\xi^{\mathbb{F}}+\int_{t}^{T}g^{\mathbb{F}}(s)ds+\int_{t}^{T}\zeta_s dV^{\mathbb{F}}_s+\left( \bar{K}^{\mathbb{F},+}_T-\bar{K}^{\mathbb{F},+}_t\right)\\ &\qquad\qquad-\left(\bar{K}^{\mathbb{F},-}_T-\bar{K}^{\mathbb{F},-}_t\right) -\int_{t}^{T} \bar{Z}^{\mathbb{F},\ast}_s d B_s;\\
				\text{(ii)} &~  \bar{Y}^{\mathbb{F},\ast}_t \leq U^{\mathbb{F}}_t,~  \forall t \in [0,T],~\mathbb{P}\text{-a.s.};\\
				\text{(iii)} &~ \text{Skorokhod condition:}  \int_0^{T }(U^{\mathbb{F}}_{t}-\bar{Y}^{\mathbb{F},\ast}_{t})d\bar{K}^{\mathbb{F},-}_t=0,~\mathbb{P}\text{-a.s.},
			\end{split}
			\right.
			\label{What wa got again}
		\end{equation}
		such that
		\begin{equation}
			Y=\dfrac{\bar{Y}^{\mathbb{F},\ast}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\xi\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket}.
			\label{MN11}
		\end{equation}
		From BSDEs (\ref{What wa got}), (\ref{What wa got again}), equalities (\ref{MN10}), (\ref{MN11}) and the uniqueness of the solution, we may derive 
		\begin{equation*}
			Y=\dfrac{Y^{\mathbb{F}}}{\tilde{\mathcal{E}}}\mathds{1}_{\llbracket 0,T \wedge \tau \llbracket}+\xi\mathds{1}_{\llbracket T \wedge \tau, +\infty  \llbracket},
		\end{equation*}
		where $Y^{\mathbb{F}}$ is the state process of the DRBSDE (\ref{basic equation comparison}).\\
		Now, to completes the proof, it suffices to apply an integration by parts formula to the process $\left(\frac{Y^{\mathbb{F}}_t}{\tilde{\mathcal{E}}_t} \mathds{1}_{\{t<T \wedge\tau \}}+\xi \mathds{1}_{\{ t \geq T \wedge \tau \}}\right)_{t\geq 0}$, which yields to the following dynamic:
		\begin{equation*}
			\begin{split}
				-dY_t&=-d\left(\frac{Y^{\mathbb{F}}_t}{\tilde{\mathcal{E}}_t} \mathds{1}_{\{t<T \wedge\tau \}}+\xi \mathds{1}_{\{ t \geq T \wedge \tau \}}\right)\\
				&=\mathds{1}_{\{t \leq T\wedge \tau\}} g(t)dt+\dfrac{\mathds{1}_{\{t \leq T\wedge \tau\}}}{\tilde{\mathcal{E}}_{t-}} dK^{\mathbb{F},+}_{t }-\dfrac{\mathds{1}_{\{t \leq T\wedge \tau\}}}{\tilde{\mathcal{E}}_{t-}}dK^{\mathbb{F},-}_{t } +\mathds{1}_{\{t \leq T\wedge \tau\}}\dfrac{Z^{\mathbb{F}}_t}{\tilde{\mathcal{E}}_{t-}}dB_t,
			\end{split}
		\end{equation*}
		and $Y_t=\xi$  on the set $\{t \geq T \wedge \tau\} $ by construction. Then the proof is complete, using the DRBSDE (\ref{basic equation}) and the uniqueness of the solution stated in Proposition \ref{basic Estimastion for BSDE}.
	\end{proof}
	%%%%%%%%%%%%%%%
	\subsubsection{Second link} 
	Here, for each  we will observe that the behavior of the state process of the DRBSDE (\ref{basic equation}) with a generator $f$ independent of the solution, i.e., $f(t,y,z)=g(t)$ for all $(t,y,z) \in [0,T] \times \mathbb{R}^{1+d}$, under the information provided by $\mathbb{F}$ under $\mathbb{Q}$, resembles that of a solution to a special form of DRBSDE in the $(\mathbb{F},\mathbb{Q})$-setup with a linear generator in the $z$-variable. To put it simply, we're interested in understanding the relationship between the $\mathbb{F}$ conditional expectation of the state process of the DRBSDE (\ref{basic equation}) under $\mathbb{Q}$ and a solution of another special DRBSDE in $\mathbb{F}$ with linear generator in the $z$-variable. Additionally, we generalize this to include a linear generator depending on the $y$-variable. To begin with, let's first introduce the following lemma:
	\begin{lemma}
		Let $(Z_t)_{t \geq 0}$ be a $\mathbb{G}$-predictable process that belong to $\mathcal{H}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$. Assume that $\tau$ and $\mathcal{F}_T$ are independent under $\mathbb{Q}$. Then, we have:
		$$
		\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{t} Z_s dB_s \mid \mathcal{F}_t \right]=\int_{0}^{t} \mathbb{E}_{\mathbb{Q}}\left[ Z_s \mid \mathcal{F}_s \right]  dB_s ,\quad t \in [0,T].
		$$
		\label{result of interchanging the conditional expectation}
	\end{lemma}
	The proof of this lemma can be found in Appendix \ref{Appendix B}.
	%
	\begin{remark}
		Since $Z=Z \mathds{1}_{\rrbracket 0,T \wedge \tau \rrbracket}$ for $Z \in \mathcal{H}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$, we can  write
		$$
		\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{t \wedge \tau} Z_s dB_s \mid \mathcal{F}_t \right]=\int_{0}^{t} \mathbb{E}_{\mathbb{Q}}\left[ Z_s \mathds{1}_{\left\lbrace s < \tau\right\rbrace } \mid \mathcal{F}_s \right]  dB_s=\int_{0}^{t} \mathbb{E}_{\mathbb{Q}}\left[ Z_s  \mid \mathcal{F}_s \right]  dB_s ,~ t \in [0,T].
		$$ 
	\end{remark}
	%

	\begin{remark}
		We recall that, since the process $(\rho_t)_{t \leq T}$ defined in Proposition \ref{equiality of measures} is a uniformly integrable positive $(\mathbb{F},\mathbb{P})$-martingale, and $(B_t)_{t \leq T}$ has the martingale representation property in the $\left(\mathbb{F},\mathbb{P}\right)$-framework, we deduce the existence of an $\mathbb{F}$-predictable process $(\theta^{\ast}_t)_{t \leq T}$ such that $\int_{0}^{T}\left|\theta^{\ast}_s \right|^2 ds<+\infty$, $\mathbb{P}$-a.s., and
		\begin{equation}
			\rho_t=\rho_0+\int_{0}^{t} \theta^{\ast}_s dB_s,\quad t \in [0,T] ,~\mathbb{P}\text{-a.s.,}
			\label{RP}
		\end{equation}
		and that the process 
		$B^{[\rho]}_.=B_.-\displaystyle\int_{0}^{.}\dfrac{1}{\rho_{s}}d\left\langle \rho,B \right\rangle_s$
		is an $(\mathbb{F},\mathbb{Q})$-Brownian motion possessing the martingale representation property in $\left(\mathbb{F},\mathbb{Q}\right)$ (see Lemma \ref{lemma of new Brownian in F}).
	\end{remark}

	%
	%
	The following proposition constitutes the main result of the second approach, which allows us to comprehend the evolution of the state process of DRBSDE (\ref{basic equation}) within the $(\mathbb{F},\mathbb{Q})$-framework through conditioning with respect to $\mathbb{E}_{\mathbb{Q}}\left[\cdot \mid \mathcal{F}_t\right]$ for $t \in [0,T]$.  
	\begin{theorem}
		Let  $\Theta^{\rho,\ast}:=(\Theta^{\rho,\ast}_t)_{t \leq T}$ be the positive $\mathbb{F}$-predictable process defined by $\Theta^{\rho,\ast}_t:=\dfrac{\theta^{\ast}_t}{\rho_{t}}$. 
		Let $(Y_t,Z_t,K^{+}_t,K^{-}_t,M_t)_{t \geq 0}$ be the unique solution of the DRBSDE (\ref{basic equation}) associated with $(\xi,g,L,U)$ satisfying \textbf{(H)}.\\
		Assume that $\tau$ and $\mathcal{F}_T$ are independent under $\mathbb{Q}$, that $\xi \in \mathcal{L}^2_{T}(\beta,\mathbb{G},\mathbb{Q})$, that $
		\Theta^{\rho,\ast} \in \mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$, and that $(L_t)_{t \leq T}$, $(U_t)_{t \leq T} \in \mathcal{D}^2_{T}\left( \mathbb{F},\mathbb{Q}\right)$. \\
		Then, there exists a unique $\mathbb{F}$-predictable process $(\Theta^{\mathbb{F}}_t)_{t \leq T} \in \mathcal{H}^2_T(\mathbb{F},\mathbb{Q})$ and a unique $\mathbb{F}$-predictable continuous increasing processes $\left(K^{\mathbb{F},+},K^{\mathbb{F},-}\right):=(K^{\mathbb{F},+}_t,K^{\mathbb{F},-}_t)_{t \leq T}$ such that the $\mathbb{F}$-adapted process  $\left(\hat{Y}^{\mathbb{F}},\hat{Z}^{\mathbb{F}},K^{\mathbb{F},+},K^{\mathbb{F},-},\Theta^{\mathbb{F}}\right):=\left(\mathbb{E}_{\mathbb{Q}}\left[Y_t  \mid \mathcal{F}_t\right],\mathbb{E}_{\mathbb{Q}}\left[Z_t \mid \mathcal{F}_t\right],K^{\mathbb{F},+}_t,K^{\mathbb{F},-}_t,\Theta^{\mathbb{F}}_t\right)_{t \leq T}$ satisfies
		\begin{equation*}
			\left\{
			\begin{split}
				&\text{(i)}~\hat{Y}^{\mathbb{F}}_t= 	\hat{\xi}^{\mathbb{F}}+\int_t^T \left\lbrace \hat{g}^{\mathbb{F}}(s)+\Theta^{\rho,\ast}_s \hat{Z}^{\mathbb{F}}_s \right\rbrace  ds+\left( K^{\mathbb{F},+}_T-K^{\mathbb{F},+}_t\right)-\left( K^{\mathbb{F},-}_T-K^{\mathbb{F},-}_t\right)\\
				&\qquad\qquad\qquad-\int_t^T \hat{Z}^{\mathbb{F}}_s  d B^{[\rho]}_s-\int_{t}^{T} \Theta^{\mathbb{F}}_s  d B^{[\rho]}_s,\quad \text{for all }t \in [0,T],~\mathbb{Q}\text{-a.s.}\\
				&\text{(ii)}~L_t \leq \hat{Y}^{\mathbb{F}}_t \leq U_t,~ \forall t \in [0,T],  \mathbb{Q}\text{-a.s.} \\
				&\text{(iii)}~\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)dK^{\mathbb{F},+}_s=\int_{0}^{T}(U_s-\hat{Y}^{\mathbb{F}}_s)dK^{\mathbb{F},-}_s =0,~ \mathbb{Q}\text{-a.s.}
			\end{split}
			\right.
		\end{equation*}
		With $\hat{\xi}^{\mathbb{F}}=\mathbb{E}_{\mathbb{Q}}\left[\xi\mid \mathcal{F}_T\right]$, $\hat{g}^{\mathbb{F}}(t)=\mathbb{Q}\left(t \leq \tau \mid \mathcal{F}_t\right) g(t)$ and $\mathbb{E}_{\mathbb{Q}}\left[M_t \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M_{T}  \right]+\int_{0}^{t} \Theta^{\mathbb{F}}_s dB^{[\rho]}_s$, for $t \in [0,T]$. Moreover, we have  $\left(\hat{Y}^{\mathbb{F}},\hat{Z}^{\mathbb{F}},K^{\mathbb{F},+},K^{\mathbb{F},-},\Theta^{\mathbb{F}}\right)\in \mathfrak{B}^2_{T}\left( \beta,\mathbb{F},\mathbb{Q}\right)$.
		\label{Proposition of comparison}
	\end{theorem}
	%
	\begin{proof}   
		In this proof, $\mathfrak{c}>0$ indicates a constant that remains independent of the index of any stochastic process sequences and may vary from line to line. Additionally, note that every $\mathbb{F}$-optional process is $\mathbb{F}$-predictable due to the Brownian filtration $\mathbb{F}$ \cite[Corollary V.3.3]{revuz1999continuous}.\\	
		The proof is performed in eight parts.
		\paragraph*{Part 1: Penalized equations}
		\emph{}\\
		To begin, let us consider the following initial penalized BSDE in the defaultable setup $(\Omega,\mathcal{F},\mathbb{G},\mathbb{Q})$:
		\begin{equation}
			\left\{
			\begin{split}
				&\text{(i)}~Y^{n}_t= \xi+\int_0^t g(s)\mathds{1}_{\{s \leq \tau\}}ds+n\int_0^t (L_s-Y^{n}_s)^{+}\mathds{1}_{\{s \leq \tau\}}ds  \\
				&\qquad\quad -n \int_0^t (Y^{n}_s-U_s)^{+}\mathds{1}_{\{s \leq \tau\}}ds -\int_0^{t} Z^{n}_s d B_s-\int_0^{t}  dM^{n}_s, \quad t \in [0,T],~\mathbb{Q}\text{-a.s.}\\
				&\text{(ii)}~Y^n_t=\xi,~Z_t^n=dM^n_t=0 \text{ on the set } \{t \geq T \wedge \tau\},~\mathbb{Q}\text{-a.s.}
			\end{split}
			\right.
			\label{penalization equations with respect to the two reflection barriers}
		\end{equation}
		Rewriting (\ref{penalization equations with respect to the two reflection barriers}) forwards, using Remark \ref{strssfull remark}-(a), Lemma 3.9 in \cite{BDEM}, and taking the conditional expectation on both sides of (\ref{penalization equations with respect to the two reflection barriers}) together with Fubini's Theorem, we obtain, for all $t \in [0,T]$, 
		\begin{equation}
			\begin{split}
				\hat{Y}^n_t
				&=	Y_0-\int_0^t g(s)\mathbb{Q}\left(s \leq \tau \mid \mathcal{F}_s\right)ds-	K^{n,\mathbb{F},+}_t+	K^{n,\mathbb{F},-}_t \\ 
				&\qquad+\int_0^t \mathbb{E}_{\mathbb{Q}}\left[Z^{n}_s \mid \mathcal{F}_s \right] d B_s+\mathbb{E}_{\mathbb{Q}}\left[M^{n}_t \mid \mathcal{F}_t \right]. 
			\end{split}
			\label{WE just trying}
		\end{equation}
		with $\hat{Y}^{n, \mathbb{F}}_t=\mathbb{E}_{\mathbb{Q}}\left[Y^n_t \mid \mathcal{F}_t\right]$, $K^{n,\mathbb{F},+}_t=n\int_0^t \mathbb{E}_{\mathbb{Q}} \left[ (L_s-Y^{n}_s)^{+}\mathds{1}_{\{s \leq \tau\}} \mid \mathcal{F}_s \right] ds$, and $	K^{n,\mathbb{F},-}_t:=n\int_0^t\mathbb{E}_{\mathbb{Q}}\left[  (Y^{n}_s-U_s)^{+}\mathds{1}_{\{s \leq \tau\}} \mid \mathcal{F}_s \right]ds$ for $t \in [0,T]$. Additionally, from Remark \ref{RMQ of Well defined Steiltjes integrals}, we derive that the processes $\left(K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ and $\left( K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ are well-defined, finite-valued Stieltjes integrals, which are increasing $\mathbb{F}$-adapted and continuous.	  	
		%
		\paragraph*{Part 2: Decomposition of the processes $(Z^n,M^n)$ in $\mathbb{F}$ with respect to $\mathbb{Q}$}
		\emph{}\\ 
		First, note that, $\left\langle \rho,B \right\rangle_t=[\rho,B]^{p,\mathbb{F},\mathbb{Q}}_t=\int_{0}^{t}\frac{1}{\rho_{s-}}d\left(\int_{0}^{s}\rho_u d[\rho,B]_u \right)^{p,\mathbb{F},\mathbb{P}} $ (see Section I-3 in \cite{JeulinDecom}). Then, from the fact that $d[\rho,B]_u=\theta^{\ast}_u du$, $\mathbb{P}$-a.s., where $\theta^{\ast}$ is defined in (\ref{RP}), we derive $\left\langle \rho,B \right\rangle_t=\int_{0}^{t} \theta^{\ast}_s ds$, $\mathbb{Q}$-a.s. Then, from Lemma \ref{lemma of new Brownian in F}, we deduce that
		$$
		B^{[\rho]}_t=B_t-\int_{0}^{t} \Theta^{\rho,\ast}_sds,\quad t \in  [0,T].
		$$
		is an $(\mathbb{F},\mathbb{Q})$-Brownian motion having the representation property. \\
		From Theorem \ref{Existence and uniquess theorem BSDE} and the B-D-G inequality, we know that the orthogonal martingale $M^n$ satisfies $M^n_{\tau}=M^n_T$ (from (\ref{penalization equations with respect to the two reflection barriers}-(ii))) and the following  integrability property:
		\begin{equation}
			\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T \wedge \tau} e^{\beta \mathcal{A}_t}\left| M^n_t\right|^2 \right]<+\infty.
			\label{square integrability}
		\end{equation}
		On the other hand, using the martingale representation property for the $\mathbb{F}$-Brownian motion $B^{[\rho]}$ under $\mathbb{Q}$ (see Section 3 in \cite[Chapter IV]{bookProtter} for more details), we get: For any $t \in [0,T]$
		\begin{itemize}
			\item On the set $\{t<T \wedge \tau\}$, we have
			$$
			\mathbb{E}_{\mathbb{Q}}\left[M^n_t \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M^n_T \right]+\int_{0}^{t} \Theta^{n,1}_s dB^{[\rho]}_s.
			$$
			\item On the set $\{t \geq T \wedge \tau\}$, we get
			$$
			\mathbb{E}_{\mathbb{Q}}\left[M^n_t \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M^n_{\tau} \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M^n_{\tau} \right]+\int_{0}^{t} \Theta^{n,2}_s dB^{[\rho]}_s,\quad t \geq 0.
			$$
		\end{itemize}
		Further, from (\ref{square integrability}), we deduce that the  two $\mathbb{F}$-predictable processes $(\Theta^{n,1})_{t \geq 0}$ and $(\Theta^{n,2})_{t \geq 0}$ are uniquely defined and belongs to $\mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$. Using the fact that  $\mathbb{E}_{\mathbb{Q}}\left[M^n_{\tau} \right]=\mathbb{E}_{\mathbb{Q}}\left[M^n_{T} \right]$, and Itô's Isometric formula, we obtain
		$$
		\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{t}\left|\Theta^{n,1}_s-\Theta^{n,2}_s \right|^2ds   \right]=0,\quad \forall t \in [0,T].
		$$
		Henceforth, $\Theta^{n,1}=\Theta^{n,2}$, and then the process $\left(\mathbb{E}_{\mathbb{Q}}\left[M^n_t \mid \mathcal{F}_t\right]\right)_{t \leq T}$ can be uniquely represented as:
		\begin{equation}
			\mathbb{E}_{\mathbb{Q}}\left[ M^n_t \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M^n_{\tau}  \right]+\int_{0}^{t} \Theta^{n,\mathbb{F}}_s dB^{[\rho]}_s,\quad t \in [0,T],
			\label{some explication}
		\end{equation}
		where $(\Theta^{n,\mathbb{F}}_t)_{t \leq T}$ is a uniquely defined $\mathbb{F}$-predictable process that belongs to $\mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$.\\	
		Now, let's address the $\mathbb{G}$-predictable process $Z^n$. Using Lemma 4.4 in \cite{book:63874} for $\mathbb{G}$-predictable process $Z^n$, and considering the fact that $Z^n=Z^n \mathds{1}_{\llbracket0,\tau\rrbracket}$, we deduce the existence of a unique $\mathbb{F}$-predictable process $Z^{n,\mathbb{F}}$ such that $ Z^{n,\mathbb{F}} \in \mathcal{H}^2_{T \wedge \tau}(\mathbb{F},\mathbb{Q})$, and
		\begin{equation}
			Z^{n}_s=Z^{n,\mathbb{F}}_s \mathds{1}_{\{s \leq \tau\}} \text{ thus }  \mathbb{E}_{\mathbb{Q}}\left[Z^{n}_s \mid \mathcal{F}_s \right]=Z^{n,\mathbb{F}}_s \mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_{\{s \leq \tau\}} \mid \mathcal{F}_s \right],\quad s \in [0,T].
			\label{SML}
		\end{equation}
		%
		Define $\hat{Z}^{n,\mathbb{F}}_s:=\mathbb{Q}\left(s \leq \tau \mid \mathcal{F}_s\right) Z^{n,\mathbb{F}}_s$. Then, we have $ \hat{Z}^{n,\mathbb{F}} \in  \mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$, and the BSDE (\ref{WE just trying}) becomes
		\begin{equation}
			\begin{split}
				&\hat{Y}^{n,\mathbb{F}}_t=
				\hat{Y}^{n,\mathbb{F}}_0-\int_0^t\left( \hat{g}(s)+\hat{Z}^{n,\mathbb{F}}_s \Theta^{\rho,\ast}_s\right) ds-K^{n,\mathbb{F},+}_t +K^{n,\mathbb{F},-}_t \\
				&\qquad\qquad\quad +\int_0^t \hat{Z}^{n,\mathbb{F}}_s d B^{[\rho]}_s+\int_0^t \Theta^{n,\mathbb{F}}_s d B^{[\rho]}_s, \quad t \in [0,T],~\mathbb{Q} \text{-a.s.}
			\end{split}
			\label{New penalization approximation}
		\end{equation}	
		\paragraph*{Part 3: Estimation of the processes $\left(\hat{Y}^{n,\mathbb{F}}_t,\hat{Z}^{n,\mathbb{F}}_t,K^{n,\mathbb{F},+}_t,K^{n,\mathbb{F},-}_t,\Theta^{n,\mathbb{F}}_t\right)_{t \leq T}$}	
		\emph{}\\
		Set $K^{n,+}_t:=n\int_0^t (L_s-Y^{n}_s)^{+}\mathds{1}_{\{s \leq \tau\}}ds$ and  $K^{n,-}_t:=n\int_0^t (Y^{n}_s-U_s)^{+}\mathds{1}_{\{s \leq \tau\}}ds$, for $t \in [0,T]$. 
		From \cite[Lemma 4.1]{BDEM} concerning the BSDE (\ref{penalization equations with respect to the two reflection barriers}), we have: For any $\beta >0$, there exists a constant $\mathfrak{c}$ such that
		\begin{equation}
			\begin{split}
				\sup_{n \in \mathbb{N}}&\left\lbrace \mathbb{E}_{\mathbb{Q}}\sup_{0 \leq t \leq T \wedge \tau}e^{\beta A_t}\left| Y^n_t\right|^2 + \mathbb{E}_{\mathbb{Q}}\int_{0}^{T \wedge \tau}e^{\beta A_s} \left| Y^n_s \alpha_s\right|^2 ds \right.\\
				&\left. \qquad+	\mathbb{E}_{\mathbb{Q}}\left[ \left| K^{n,+}_{T \wedge \tau} \right|^2\right]+
				\mathbb{E}_{\mathbb{Q}}\left[ \left| K^{n,-}_{T \wedge \tau} \right|^2\right]  \right\rbrace  \leq \mathfrak{c}.
			\end{split}
			\label{un Y}
		\end{equation}
		Using Jensen, Doob's Meyer quadratic inequality \cite[Theorem I.1.43]{bookJacod}, we obtain
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[ \sup_{0 \leq t \leq T}e^{\beta A_t}\left| \hat{Y}^{n,\mathbb{F}}_t\right|^2\right] &\leq  	\mathbb{E}\sup_{0 \leq t \leq T}\mathbb{E}_{\mathbb{Q}}\left[e^{\beta A_t}\left| Y^n_t\right|^2 \mid \mathcal{F}_t\right] \\
				&\leq 	\mathbb{E}\sup_{0 \leq t \leq T}\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T} e^{\beta A_t}\left| Y^n_t\right|^2 \mid \mathcal{F}_t\right]\\
				&\leq 4 \mathbb{E}_{\mathbb{Q}}\left[ \sup_{0 \leq t \leq T}e^{\beta A_t}\left| Y^n_t\right|^2\right] \\
				&\leq 4 \mathbb{E}_{\mathbb{Q}}\left[ \sup_{0 \leq t \leq T \wedge \tau}e^{\beta A_t}\left| Y^n_t\right|^2\right] +4\mathbb{E}_{\mathbb{Q}}\left[ e^{\beta A_T}\left| \xi\right|^2\right] .
			\end{split}
			\label{n tends to infty}
		\end{equation*}
		On the other hand, the positive Fubini-Tonelli's theorem, Jensen's inequality allows us to conclude that
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}e^{\beta A_s} \left| \hat{Y}^{n,\mathbb{F}}_s \alpha_s\right|^2 ds\right] &\leq \int_{0}^{T} \mathbb{E}_{\mathbb{Q}}\left[e^{\beta A_s} \alpha_s^2 \mathbb{E}_{\mathbb{Q}}\left[ \left| Y^n_s\right|^2 \mid \mathcal{F}_s  \right] \right]ds
				=\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}e^{\beta A_s} \left| Y^n_s \alpha_s\right|^2 ds\right] \\
				& \leq 	\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T \wedge \tau }e^{\beta A_s} \left| Y^n_s \alpha_s\right|^2 ds\right] +\mathbb{E}_{\mathbb{Q}}\left[ e^{\beta A_T}\left| \xi\right|^2\right] .
			\end{split}
		\end{equation*}	
		From the uniform estimation satisfied by the sequence $\{K^{n,\pm}\}_{n \in \mathbb{N}}$, given by (\ref{un Y}) and Jensen inequality, we deduce that 
		\begin{equation}
			\begin{split}
				\sup_{n \in \mathbb{N}}\left\lbrace	\mathbb{E}_{\mathbb{Q}}\left[ \left| K^{n,\mathbb{F},+}_{T} \right|^2\right]+
				\mathbb{E}_{\mathbb{Q}}\left[ \left| K^{n,\mathbb{F},-}_{T } \right|^2\right] \right\rbrace \leq \mathfrak{c}.
				\label{KnF+-}
			\end{split}
		\end{equation}
		Thanks to Lemma 4.1 in \cite{BDEM}, for any $\beta >0$, we can write
		\begin{equation}
			\begin{split}
				\sup_{n \in \mathbb{N}}\left\lbrace\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{T \wedge \tau} e^{\beta A_s}\left|Z^n_s \right|^2 ds+\int_{0}^{T \wedge \tau}e^{\beta A_s} d\left[M^n\right]_s  \right]\right\rbrace 
				\leq \mathfrak{c}.
			\end{split}
			\label{with}
		\end{equation}	
		Using positive Fubini-Tonelli's theorem, we have
		$$
		\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}e^{\beta A_s}\left| \hat{Z}^{n,\mathbb{F}}_s \right|^2\right]  ds\leq  \mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}e^{\beta A_s}\left| Z^n_s \right|^2 ds\right] =\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T \wedge \tau}e^{\beta A_s}\left| Z^n_s \right|^2 ds\right] \leq \mathfrak{c}.
		$$
		From the martingale representation property (\ref{some explication}), Itô's isometric formula, Jensen's and the B-D-G inequalities with (\ref{with}), we deduce that
		$$
		\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}\left| \Theta^{n,\mathbb{F}}_s \right|^2 ds\right] =\mathbb{E}_{\mathbb{Q}}\left[ \left(\int_{0}^{T} \Theta^{n,\mathbb{F}}_s dB^{[\rho]}_s\right)^2\right]\leq 2 \mathbb{E}_{\mathbb{Q}}\left[ \sup_{0 \leq t \leq T \wedge \tau} e^{\beta A_t}\left| M^n_t\right|^2\right]\leq \mathfrak{c} .
		$$
		%%%%%%%%%%%%%%%%%%%%%%%%%%%	
		\paragraph*{Part 4: Convergence result}	
		\emph{}\\
		From Step 4 of the proof of Theorem 4.1 in \cite{BDEM},  we know that there exists a unique triplet of $\mathbb{G}$-adapted processes $(Y_t,Z_t,M_t)_{t \geq 0}$ such that
		\begin{itemize}
			\item $(Y_t)_{t \geq 0}$ is $\mathbb{G}$-adapted RCLL with $Y=\xi$ on $\llbracket T \wedge \tau,+\infty\llbracket$;
			\item $(Z_t)_{t \geq 0}$ is $\mathbb{G}$-predictable with $Z=Z\mathds{1}_{\llbracket0,T \wedge \tau \rrbracket}=Z\mathds{1}_{\llbracket0, \tau \rrbracket}$ on $[0,T]$;
			\item $(M_t)_{t \geq 0}$ is an RCLL $\mathbb{G}$-square integrable martingale orthogonal to $(B_t)_{t \geq 0}$ with $dM_{t}=dM_{t \wedge \tau}$ for all $t \in [0,T]$;
		\end{itemize}
		and
		\begin{equation}
			\lim\limits_{n \to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T \wedge \tau}\left| Y^n_t-Y_t\right|^2+\int_{0}^{T \wedge \tau} \left|Z^n_s-Z_s \right|^2 ds+\int_{0}^{T \wedge \tau} d\left[M^n-M\right]_s  \right]=0.
			\label{CV}
		\end{equation}
		This together with (\ref{un Y}), (\ref{with}) and the conditional dominated convergence theorem, we derive the following convergences (in $\mathbb{L}^2$-space), for any  $t \in [0,T]$,
		\begin{equation}
			\left\{
			\begin{split}
				&\text{(i)}~\hat{Y}^{n,\mathbb{F}}_t= \mathbb{E}_{\mathbb{Q}}\left[Y^n_t \mid \mathcal{F}_t\right]\xrightarrow[n \to +\infty]{\mathcal{L}^2_{t}(\mathbb{F},\mathbb{Q})} \mathbb{E}_{\mathbb{Q}}\left[Y_t \mid \mathcal{F}_t\right]=:\hat{Y}^{\mathbb{F}}_t.\\			&\text{(ii)}~\hat{Z}^{n,\mathbb{F}}=\mathbb{E}_{\mathbb{Q}}\left[Z^n \mid \mathcal{F}_{\cdot}\right]\xrightarrow[n \to +\infty]{\mathcal{H}^2_t(\mathbb{F},\mathbb{Q})} \mathbb{E}_{\mathbb{Q}}\left[Z \mid \mathcal{F}_{\cdot}\right]. \\
				&\text{(iii)}~\mathbb{E}_{\mathbb{Q}}\left[M^n_T \right]+\int_{0}^{t} \Theta^{n,\mathbb{F}}_s dB^{[\rho]}_s\xrightarrow[n \to +\infty]{\mathcal{L}^2_{t}(\mathbb{F},\mathbb{Q})} \mathbb{E}_{\mathbb{Q}}\left[M_t \mid \mathcal{F}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[M_{T}  \right]+\int_{0}^{t} \Theta^{\mathbb{F}}_s dB^{[\rho]}_s.
			\end{split}
			\right.
			\label{System}
		\end{equation}
		Using a similar argument as the one employed in  (\ref{SML}), we establish that, for any $t \in [0,T]$, we can express 
		$\mathbb{E}_{\mathbb{Q}}\left[Z_t \mid \mathcal{F}_{t}\right]=Z^{\mathbb{F}}_t \mathbb{Q}\left(t \leq \tau \mid \mathcal{F}_{t}\right)=$ for a unique $\mathbb{F}$ predictable process $\left( Z^{\mathbb{F}}_t\right)_{t \leq T}$. Similarly, the process $\left(\Theta^{\mathbb{F}}_t\right)_{t \leq T}$ is obtained following a similar approach as in (\ref{some explication}). We define $\hat{Z}^{\mathbb{F}}_t=Z^{\mathbb{F}}_t \mathbb{Q}\left(t \leq \tau \mid \mathcal{F}_{t}\right)$ for $t \in [0,T]$.\\
		As $(\hat{Z}^{n,\mathbb{F}},\Theta^{n,\mathbb{F}},\hat{Z}^{\mathbb{F}},\Theta^{\mathbb{F}})$ are uniquely defined as well as the processes $(Z^n,M^n,Z,M)$, and from the convergences given in (\ref{CV}) and (\ref{System}), the definition of the processes  $(\hat{Z}^{n,\mathbb{F}},\hat{Z}^{\mathbb{F}})$, using Remark  \ref{strssfull remark} for the processes $(\hat{Z}^{n,\mathbb{F}},\hat{Z}^{\mathbb{F}})$, and Jensen's inequality, we can easily deduce that for any $t \in [0,T]$,
		$$
		\lim\limits_{n\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\left(\int_{0}^{t}\hat{Z}^{n,\mathbb{F}}_s dB^{[\rho]}_s-\int_{0}^{t}\hat{Z}^{\mathbb{F}}_s dB^{[\rho]}_s\right)^2+\left(\int_{0}^{t}\Theta^{n,\mathbb{F}}_s dB^{[\rho]}_s-\int_{0}^{t}\Theta^{\mathbb{F}}_s dB^{[\rho]}_s\right)^2\right] =0,
		$$
		Moreover, since  the process $(\Theta^{\rho,\ast}_t)_{t \leq T}$ is square integrable, i.e., $\Theta^{\rho,\ast} \in \mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$, then using the Lebesgue dominate convergence theorem, we get
		$$\int_{0}^{t} \hat{Z}^{n,\mathbb{F}}_s \Theta^{\rho,\ast}_s ds\xrightarrow[n \to +\infty]{\mathcal{L}^1_t(\mathbb{F},\mathbb{Q})} \int_{0}^{t} \hat{Z}^{\mathbb{F}}_s \Theta^{\rho,\ast}_s ds,\quad t \in [0,T].$$
		%%%%%%%%%%%%%%%%%%%%%%%%%	
		\paragraph*{Part 5: Cauchy property}
		\emph{}\\
		Following this convergence results and using the fact that $\left\{Y^n,Z^n,M^n\right\}_{n \in \mathbb{N}}$ are Cauchy sequences, along with Remark \ref{strssfull remark} and Jensen's inequality, we can deduce that $\left\{\hat{Y}^{n,\mathbb{F}},\hat{Z}^{n,\mathbb{F}},\Theta^{n,\mathbb{F}}\right\}_{n \in \mathbb{N}}$ are also Cauchy sequences. More precisely, we can derive
		\begin{equation}
			\left\{
			\begin{split}
				&\bullet \lim\limits_{n,p\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T}\left| \hat{Y}^{n,\mathbb{F}}_t-\hat{Y}^{p,\mathbb{F}}_t\right|^2 \right]=0.\\
				&\bullet \text{ For any } t \in [0,T],\\
				&\lim\limits_{n,p\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\left(\int_{0}^{t}\left( \hat{Z}^{n,\mathbb{F}}_s -\hat{Z}^{p,\mathbb{F}}_s\right)  dB^{[\rho]}_s\right)^2+\left(\int_{0}^{t}\left( \Theta^{n,\mathbb{F}}_s -\Theta^{p,\mathbb{F}}_s\right)  dB^{[\rho]}_s\right)^2\right] =0.\\
			\end{split}
			\right.
			\label{CV SYS}
		\end{equation}
		%	
		Furthermore, since $\Theta^{\rho,\ast} \in \mathcal{H}^2_{T}(\mathbb{F},\mathbb{Q})$, we can show using the second line of (\ref{CV SYS}), that
		\begin{equation}
			\lim\limits_{n,p\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\left|  \int_{0}^{t}\left( \hat{Z}^{n,\mathbb{F}}_s  -\hat{Z}^{p,\mathbb{F}}_s\right) \Theta^{\rho,\ast}_s ds \right| \right] =0
			,\quad  t \in [0,T].
			\label{CV SYST ADD}
		\end{equation}
		Now, we set $K^{n,\mathbb{F}}_t:=K^{n,\mathbb{F},+}_t-K^{n,\mathbb{F},-}_t$ for $t \in [0,T]$. From the BSDE (\ref{New penalization approximation}), we obtain using (\ref{CV SYS}) and (\ref{CV SYST ADD}), that
		$$
		\lim\limits_{n,p\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T}\left|  K^{n,\mathbb{F}}_t-K^{p,\mathbb{F}}_t \right| \right] =0.
		$$
		Thus, $\left\{K^{n,\mathbb{F}}\right\}_{n \in \mathbb{N}}$ is a Cauchy sequence in the complete space $\mathcal{L}^1_T(\mathbb{F},\mathbb{Q})$. Therefore, there exists an $\mathbb{F}$-predictable  process $K^{\mathbb{F}}$ such that $\mathbb{E}_{\mathbb{Q}}\left|  K^{\mathbb{F}}_T\right| <+\infty$. Additionally, from the uniform estimation (\ref{KnF+-}) satisfied by $\left\{K^{n,\mathbb{F},\pm}\right\}_{n \in \mathbb{N}}$ and Fatou's lemma, we get 
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left|  K^{\mathbb{F}}_T\right|^2 & \leq  \liminf_{n \to +\infty} \mathbb{E}_{\mathbb{Q}}\left|  K^{n,\mathbb{F}}_T\right|^2 
				\leq 2 \left\{  \limsup_{n \to +\infty} \mathbb{E}_{\mathbb{Q}}\left|  K^{n,\mathbb{F},+}_T\right|^2+  \limsup_{n \to +\infty} \mathbb{E}_{\mathbb{Q}}\left|  K^{n,\mathbb{F},-}_T\right|^2\right\} \leq 4 \mathfrak{c}.
			\end{split}
		\end{equation*}
		Then, we may obtain, at least for a subsequence, that	
		\begin{equation}
			\lim\limits_{n\to +\infty}\mathbb{E}_{\mathbb{Q}}\left[\sup_{0 \leq t \leq T}\left|  K^{n,\mathbb{F}}_t-K^{\mathbb{F}}_t \right|^2\right] =0.
			\label{Convergence of Kn}
		\end{equation}
		\paragraph*{Part 6: BSDE satisfied by the limiting process $\left( \hat{Y}^{\mathbb{F}}_t,\hat{Z}^{\mathbb{F}}_t,K^{\mathbb{F}}_t,\Theta^{\mathbb{F}}_t \right)_{t \leq T}$}
		\emph{}\\
		Passing to the limit term by term in $\mathcal{L}^1_T(\mathbb{F},\mathbb{Q})$ as $n \to+\infty$ in (\ref{New penalization approximation}), we obtain that the quadruplet $(\hat{Y}^{\mathbb{F}}_t,\hat{Z}^{\mathbb{F}}_t,\Theta^{\mathbb{F}}_t,K^{\mathbb{F}}_t)_{t \leq T}$ is the unique quadruplet satisfying the following BSDE:
		\begin{equation}
			\begin{split}
				\hat{Y}^{\mathbb{F}}_t= 	\hat{\xi}^{\mathbb{F}}+\int_t^T \left\lbrace \hat{g}^{\mathbb{F}}(s)+\hat{Z}^{\mathbb{F}}_s \Theta^{\rho,\ast}_s \right\rbrace  ds+\left( K^{\mathbb{F}}_T-K^{\mathbb{F}}_t\right) -\int_t^T \hat{Z}^{\mathbb{F}}_s  d B^{[\rho]}_s-\int_{t}^{T} \Theta^{\mathbb{F}}_s  d B^{[\rho]}_s,
			\end{split}
			\label{Dyn in F}
		\end{equation}
		for all $t \in [0,T]$, $\mathbb{Q}$-a.s., with terminal value $
		\hat{\xi}^{\mathbb{F}}=\mathbb{E}_{\mathbb{Q}}\left[\xi \mid \mathcal{F}_T\right]$.\\	
		Observe that the sequence of processes $\left\{\hat{Y}^{n,\mathbb{F}}\right\}_{n \in \mathbb{N}}$, defined by the BSDEs in (\ref{New penalization approximation}), possesses continuous paths due to the fact that the process $B^{[\rho]}$ is an $(\mathbb{F},\mathbb{Q})$-Brownian motion. Consequently, considering the paths of the limiting process $\hat{Y}^{\mathbb{F}}$ as a uniform limit of continuous functions, we conclude that $\hat{Y}^{\mathbb{F}}$ is also continuous, exhibiting continuous trajectories on the interval $[0,T]$. Furthermore, we deduce that, the limit of the sequence $\left\{K^{n,\mathbb{F}}\right\}_{n \in \mathbb{N}}$ given by $K^{\mathbb{F}}$ also has continuous paths on $[0,T]$.

		Let us now show $L_t \leq \hat{Y}^{\mathbb{F}}_t \leq U_t$, for all $t \in [0,T]$. On one hand, we know that $L=L^{T \wedge \tau}$, $U=U^{T \wedge \tau}$, and $L_{T \wedge \tau} \leq \xi \leq U_{T \wedge \tau}$, by assumption. Therefore, $L_{\tau}=L_T=\mathbb{E}_{\mathbb{Q}}\left[L_T \mid \mathcal{F}_T\right]$ and $U_{\tau}=U_T=\mathbb{E}_{\mathbb{Q}}\left[U_T \mid \mathcal{F}_T\right]$, as $L$ and $U$ are $\mathbb{F}$-adapted by assumption. \\	
		On the other hand, since $L_t \leq Y_t \leq U_t$ $\mathbb{Q}$-a.s. for all $t \in [0,T \wedge \tau[$ and $Y_t=\xi$, $\mathbb{Q}$-a.s. on the set $\{t \geq T \wedge \tau\}$ since $Y=Y^{T \wedge \tau}$, we deduce that $L_t \leq \hat{Y}^{\mathbb{F}}_t \leq U_t$, $\forall t \in [0,T]$,  $\mathbb{Q}$-a.s. 
		%
		%	
		\paragraph*{Part 7: Skorokhod condition}
		\emph{}\\
		Using the expressions $\mathsf{k}^{n,\mathbb{F},+}:=\left(n\mathbb{E}_{\mathbb{Q}} \left[ (L_t-Y^{n}_t)^{+}\mathds{1}_{\{t < \tau\}} \mid \mathcal{F}_s \right]\right)_{t \leq T}$ and $\mathsf{k}^{n,\mathbb{F},-}=\left(n\mathbb{E}_{\mathbb{Q}} \left[ (Y^{n}_t-U_t)^{+}\mathds{1}_{\{s < \tau\}} \mid \mathcal{F}_t \right]\right)_{t \leq T}$, we point out  that $\mathsf{k}^{n,\mathbb{F},+}_t=n\mathbb{E}_{\mathbb{Q}} \left[ (L_t-Y^{n}_t)^{+}\mathds{1}_{\{t \leq \tau\}} \mid \mathcal{F}_s \right]$ and $\mathsf{k}^{n,\mathbb{F},-}_t=n\mathbb{E}_{\mathbb{Q}} \left[ (Y^{n}_t-U_t)^{+}\mathds{1}_{\{s \leq  \tau\}} \mid \mathcal{F}_t \right]$ for $\mathbb{P} \otimes dt$ almost every $(\omega,t)$. Now, from the previous part concerning the sequence $\left\{K^{n,\mathbb{F},\pm}\right\}_{n \in \mathbb{N}}$, we have that $\mathsf{k}^{n,\mathbb{F},\pm}$ is a sequence of non-negative, $\mathbb{F}$-adapted processes, which is bounded in $\mathbb{L}^2(\Omega \times [0,T],\mathbb{P} \otimes dt)$. Consequently, there exist a non-negative $\mathbb{F}$-adapted measurable processes $\mathsf{k}^{\mathbb{F},\pm}$ such that 
		\begin{equation}
			\mathsf{k}^{n,\mathbb{F},\pm} \to \mathsf{k}^{\mathbb{F},\pm} ~\text{ as } n \to +\infty, ~\text{ weakly in } \mathbb{L}^2(\Omega \times [0,T],\mathbb{P} \otimes dt).
			\label{Weak convergence}
		\end{equation}
		On the other hand, note that
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)dK^{n,\mathbb{F},+}_s 
				&= \mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{n,\mathbb{F}}_s-\hat{Y}^{\mathbb{F}}_s\right)\mathsf{k}^{n,\mathbb{F},+}_s ds+\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{\mathbb{F}}_s-L_s\right)\mathsf{k}^{\mathbb{F},+}_s ds\\
				&\quad+\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{\mathbb{F}}_s-L_s\right)\left( \mathsf{k}^{n,\mathbb{F},+}_s-\mathsf{k}^{\mathbb{F},+}_s \right) ds
			\end{split}
		\end{equation*}
		Using (\ref{KnF+-}), (\ref{System}), (\ref{CV SYS}), (\ref{Weak convergence}), and the fact that $\hat{Y}^{\mathbb{F}}-L \in \mathcal{D}^2_{T}\left( \mathbb{F},\mathbb{Q}\right)$, we deduce that
		\begin{equation*}
			\begin{split}
				&\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)dK^{n,\mathbb{F},+}_s \xrightarrow[n \to+ \infty]{} \mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(\hat{Y}^{\mathbb{F}}_s-L_s\right)\mathsf{k}^{\mathbb{F},+}_s ds.
			\end{split}
		\end{equation*}
		Following a similar argument, we get
		\begin{equation*}
			\begin{split}
				&\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(U_s-\hat{Y}^{n,\mathbb{F}}_s\right)dK^{n,\mathbb{F},-}_s \xrightarrow[n \to+ \infty]{}\mathbb{E}_{\mathbb{Q}}\int_{0}^{T}\left(U_s-\hat{Y}^{\mathbb{F}}_s\right)\mathsf{k}^{\mathbb{F},-}_s ds .
			\end{split}
		\end{equation*}
		On the other hand, from Remark \ref{strssfull remark}, Fubini's Theorem, and the $\mathbb{F}$-adaptation of the lower barrier $L$, we have for every $n \in \mathbb{N}$:
		\begin{equation*}
			\begin{split}
				\int_{0}^{T} \left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)\mathsf{k}^{n,\mathbb{F},+}_s ds&=n\int_{0}^{T}\mathbb{E}_{\mathbb{Q}}\left[\left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)\left(Y^n_s-L_s\right)^{-}\mathds{1}_{\{s \leq \tau\}} \mid \mathcal{F}_s\right]ds \\
				&=n\int_{0}^{T}\mathbb{E}_{\mathbb{Q}}\left[\left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)\left(Y^n_s-L_s\right)^{-}\mathds{1}_{\{s \leq \tau\}} \mid \mathcal{F}_T\right]ds \\
				&=n\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{T}\left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)\left(Y^n_s-L_s\right)^{-}\mathds{1}_{\{s \leq \tau\}}ds \mid \mathcal{F}_T\right]\\
				&=n\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{T}\left(\mathbb{E}_{\mathbb{Q}}\left[Y^n_s \mid \mathcal{F}_s\right]-L_s\right)\left(Y^n_s-L_s\right)^{-}\mathds{1}_{\{s \leq \tau\}}ds \mid \mathcal{F}_T\right]\\
				& \leq n\mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{T}\left(\mathbb{E}_{\mathbb{Q}}\left[\left( Y^n_s-L_s\right)^{+} \mid \mathcal{F}_s\right]\right)\left(Y^n_s-L_s\right)^{-}\mathds{1}_{\{s \leq \tau\}}ds \mid \mathcal{F}_T\right]\\
				&=0.
			\end{split}
		\end{equation*}
		Clearly, the last statement stems from the monotonicity of the conditional expectation, and the following observation: if $Y^n_s \leq L_s$, then $\left( Y^n_s-L_s \right)^{+}= 0$ a.s. Otherwise, if $Y^n >L$, then $\left(Y^n_s-L_s\right)^{-} = 0$.\\ 
		Therefore, using this with the fact that  $\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)\mathsf{k}^{\mathbb{F},+}_s ds \geq 0$ and $\hat{Y}^{\mathbb{F}} \geq L$, we get
		$$
		\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)\mathsf{k}^{\mathbb{F},+}_s ds \geq 0 \geq \int_{0}^{T} \left(\hat{Y}^{n,\mathbb{F}}_s-L_s\right)\mathsf{k}^{n,\mathbb{F},+}_s ds,\quad\forall n \in \mathbb{N},
		$$
		and then, we derive that $\mathbb{E}_{\mathbb{Q}}\left[ \int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)\mathsf{k}^{\mathbb{F},+}_s ds\right]=0$, which implies
		\begin{equation}
			\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)dK^{\mathbb{F},+}_s ,\quad \mathbb{Q}\text{-a.s.}
			\label{Eq1}
		\end{equation}
		A similar argument gives
		\begin{equation}
			\int_{0}^{T}(U_s-\hat{Y}^{\mathbb{F}}_s)d{K}^{\mathbb{F},-}_s=0,\quad \mathbb{Q}\text{-a.s.}
			\label{Eq2}
		\end{equation}
		%
		It remain to show that the limiting process  $K^{\mathbb{F}}$ obtained in \textbf{Part 5} is equal to the difference process $K^{\mathbb{F},+}-K^{\mathbb{F},-}$. To this end, let us set
		\begin{equation}
			\bar{K}^{\mathbb{F}}_t:=K^{\mathbb{F},+}_t-K^{\mathbb{F},-}_t=\int_{0}^{t} \mathsf{k}^{\mathbb{F},+}_s ds-\int_{0}^{t} \mathsf{k}^{\mathbb{F},-}_s ds,\quad t \in [0,T].
			\label{Definition}
		\end{equation}
		Let $\sigma \in \mathcal{T}_{0,T}$. By Mazur's Theorem \cite[Theorem 2, pp. 120]{yosida2012functional}, for any $n \in \mathbb{N}$, there exists an integer $q(n) \geq n$, weights $(\gamma^{(\tau,n)}_j)_{j\in \{n,\cdots,q(n)\}} \subset \mathbb{R}^{+}$ and a convex combination $\sum_{j=n}^{q(n)} \gamma^{(\tau,n)}_j K^{j ,\pm}_{\tau}$ such that $\sum_{j=n}^q \gamma^{(\tau,n)}_j =1$ and
		\begin{equation}
			\bar{K}^{n,\mathbb{F},\pm}_{\sigma}:=\sum_{j=n}^{q(n)} \gamma^{(\sigma,n)}_j K^{j,\mathbb{F} ,\pm}_{\sigma} \xrightarrow[n \rightarrow +\infty]{} K^{\mathbb{F},\pm}_{\sigma} \text{ in } \mathcal{L}^2_{\sigma}(\mathbb{F},\mathbb{Q}).
			\label{Mazur's Lemmma that--Sk condition--T}
		\end{equation}
		Denoting $\bar{K}_{\sigma}^{n,\mathbb{F}}:=\bar{K}_{\sigma}^{n,\mathbb{F},+}-\bar{K}_{\sigma}^{n,\mathbb{F},-}$, it follows from (\ref{Mazur's Lemmma that--Sk condition--T}), that
		\begin{equation}
			\lim\limits_{n \rightarrow+\infty}\mathbb{E}_{\mathbb{Q}}\left[ \left| \bar{K}_{\sigma}^{n,\mathbb{F}}-\bar{K}^{\mathbb{F}}_{\sigma}  \right|^2 \right] =0.
			\label{Combining 1--Skorokhod Condition--T}
		\end{equation}
		From the convergence (\ref{Convergence of Kn}), we deduce that the inequality $\left\| K^{n,\mathbb{F}}_{\sigma}-K^{\mathbb{F}}_{\sigma} \right\|_{\mathcal{L}^2_{\sigma}(\mathbb{F},\mathbb{Q})}<\epsilon$ holds for arbitrary $\epsilon > 0$ and all sufficiently large $n\in \mathbb{N}$. Therefore, we also have as 
		\begin{equation*}
			\begin{split}
				\left\|\bar{K}^{n,\mathbb{F}}_{\sigma}-K^{\mathbb{F}}_{\sigma}  \right\|_{\mathcal{L}^2_{\sigma}(\mathbb{F},\mathbb{Q})}
				&=\left\| \sum_{j=n}^{q(n)} \gamma^{(\sigma,n)}_j \left( K^{j,\mathbb{F}}_{\sigma} -K^{\mathbb{F}}_{\sigma}\right)  \right\|_{\mathcal{L}^2_{\sigma}(\mathbb{F},\mathbb{Q})}\\
				&\leq \sum_{j=n}^{q(n)} \gamma^{(\sigma,n)}_j \left\|  K^{j,\mathbb{F}}_{\sigma} -K^\mathbb{F}_{\sigma} \right\|_{\mathcal{L}^2_{\sigma}(\mathbb{F},\mathbb{Q})} <\epsilon.
			\end{split}
		\end{equation*}
		So that
		\begin{equation}
			\lim\limits_{n \rightarrow +\infty} \mathbb{E}_{\mathbb{Q}}\left[ \left|\bar{K}^{n,\mathbb{F}}_{\sigma}-K^{\mathbb{F}}_{\sigma}   \right|^2  \right]=0.
			\label{Combining 2--Skorokhod condition--T}
		\end{equation}
		Combining (\ref{Combining 1--Skorokhod Condition--T}) and (\ref{Combining 2--Skorokhod condition--T}), we obtain $\bar{K}^{\mathbb{F}}_{\sigma}=K^{\mathbb{F}}_{\sigma}$ $\mathbb{P}$-a.s. Hence, by the section theorem \cite[Theorem 4.7]{bookHe}, we have $\bar{K}^{\mathbb{F}}_t=K^{\mathbb{F}}_t$ for all $t \in  [0,T]$, $\mathbb{Q}$-a.s.\\
		From the Definition (\ref{Definition}), we deduce that $K^{\mathbb{F}}=K^{\mathbb{F},+}-K^{\mathbb{F},-}$, and using (\ref{Eq1}) and (\ref{Eq2}), we obtain
		$$
		\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)dK^{\mathbb{F},+}_s=\int_{0}^{T}(U_s-\hat{Y}^{\mathbb{F}}_s)dK^{\mathbb{F},-}_s =0,\quad \mathbb{Q}\text{-a.s.}
		$$
		Now, going back to (\ref{Dyn in F}), we derive
		\begin{equation*}
			\begin{split}
				\hat{Y}^{\mathbb{F}}_t= 	\hat{\xi}^{\mathbb{F}}&+\int_t^T \left\lbrace \hat{g}^{\mathbb{F}}(s)+\hat{Z}^{\mathbb{F}}_s \Theta^{\rho,\ast}_s \right\rbrace  ds+\left( K^{\mathbb{F},+}_T-K^{\mathbb{F},+}_t\right)-\left( K^{\mathbb{F},-}_T-K^{\mathbb{F},-}_t\right)\\
				&\qquad-\int_t^T \hat{Z}^{\mathbb{F}}_s  d B^{[\rho]}_s-\int_{t}^{T} \Theta^{\mathbb{F}}_s  d B^{[\rho]}_s,\quad t \in [0,T].
			\end{split}
		\end{equation*}
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\paragraph*{Part 8: Integrability property}
		\emph{}\\
		The integrability condition satisfied by $(\hat{Y}^{\mathbb{F}}_t,\hat{Z}^{\mathbb{F}}_t,\Theta^{\mathbb{F}}_t,K^{\mathbb{F},+}_t,K^{\mathbb{F},-}_t)_{t \leq T}$ is obtained from the construction of these processes, by applying Fatou's lemma for the corresponding sequences and the already obtained estimations. With this, the proof is complete.
	\end{proof}
	%
	\begin{remark}
		Following the same argument as the one used in the proof of Theorem \ref{Proposition of comparison}, we can obtain a more general result in the case where the driver $f$ of the DRBSDE (\ref{basic equation}) is linear with respect to the $y$-variable. More precisely, let $T \in (0,+\infty)$ and assume that the coefficient $f$ is linear of the form
		\begin{equation*}
			f(t,y,z)=g(t)+\kappa_t y, \quad t \in [0,T],
			\label{Linear generator}
		\end{equation*} 
		where the process $(\kappa_t)_{t \leq T}$ is the same as the one presented in assumption ($\mathbf{H_2}$).\\ 
		Assume that conditions of Theorem \ref{Proposition of comparison} hold and that the increasing $\mathbb{F}$-adapted continuous process $\left(\varpi_t\right)_{t \leq T}:=\left(\int_{0}^{t}\kappa_s ds\right)_{t \leq T}$ is bounded. Then, there exists a unique quintuplet $(\hat{Y}^{\mathbb{F}}_t,\hat{Z}^{\mathbb{F}}_t,\Theta^{\mathbb{F}}_t,K^{\mathbb{F},+}_t,K^{\mathbb{F},-}_t)_{t \leq T}$ that belongs to  $\mathfrak{B}^2_{T}\left( \beta,\mathbb{F},\mathbb{Q}\right)$ and satisfies of the following special form of linear generalized doubly reflected BSDE :
		\begin{equation*}
			\left\{
			\begin{split}
				&\text{(i)}~\hat{Y}^{\mathbb{F}}_t= 	\hat{\xi}+\int_t^T \left\lbrace \hat{g}^{\mathbb{F}}(s)+\kappa_s\hat{Y}^{\mathbb{F}}_s+\Theta^{\rho,\ast}_s \hat{Z}^{\mathbb{F}}_s \right\rbrace  ds-\int_{t}^{T}\int_{s}^{\infty} \zeta_u dD^{o,\mathbb{F},\mathbb{Q}}_u ds+\left( K^{\mathbb{F},+}_T-K^{\mathbb{F},+}_t\right)\\
				&\qquad\qquad-\left( K^{\mathbb{F},-}_T-K^{\mathbb{F},-}_t\right)-\int_t^T \hat{Z}^{\mathbb{F}}_s  d B^{[\rho]}_s-\int_{t}^{T} \Theta^{\mathbb{F}}_s  d B^{[\rho]}_s,\quad t \in [0,T].\\
				&\text{(ii)}~L_t \leq \hat{Y}^{\mathbb{F}}_t \leq U_t,~ \forall t \in [0,T], ~ \mathbb{Q}\text{-a.s.} \\
				&\text{(iii)}~\int_{0}^{T}(\hat{Y}^{\mathbb{F}}_s-L_s)dK^{\mathbb{F},+}_s=\int_{0}^{T}(U_s-\hat{Y}^{\mathbb{F}}_s)dK^{\mathbb{F},-}_s =0,~ \mathbb{Q}\text{-a.s.}
			\end{split}
			\right.
		\end{equation*}
		%
	\end{remark}
	%
	Throughout the rest of the paper, we define the $\mathbb{G}$-stopping time $\tau^{T}$ as $\tau^{T}(\omega) := T \wedge \tau(\omega)$ for the sake of notational simplicity. 
