	\section{Martingale representation property}
	\label{Appendix A}
	In this section, we aims to establish a predictable representation property for all local martingales $M \in \mathcal{M}_{loc}\left(\mathbb{G},\mathbb{Q}\right)$ defined on the random time interval $\llbracket 0, T \wedge \tau\rrbracket$. This representation characterizes these martingales as stochastic integrals with respect to $B^{T \wedge\tau}$ and an additional orthogonal local martingale $M \in \mathcal{M}_{loc}\left(\mathbb{G},\mathbb{Q}\right)$ stopped at $T \wedge \tau$ (i.e. $M=M^{T \wedge \tau}$). To achieve this, we will first present some auxiliary results.
	\begin{theorem}
		Under \textbf{[P]}, for any local martingale $M \in \mathcal{M}_{loc} \left(\mathbb{F},\mathbb{P}\right)$, the process
		\begin{equation}
			\mathcal{T}\left(M\right)_t:=M^{\tau}-\int_{0}^{ t}\tilde{G}^{-1}_s \mathds{1}_{\{s \leq \tau\}} d \left[M,m\right]_s,\quad t \geq 0
			\label{operator T}
		\end{equation}
		is a local martingale in $\mathcal{M}_{loc} \left(\mathbb{G},\mathbb{P}\right)$.
		\label{Theorem of the operator}
	\end{theorem}
	\begin{proof}
		See \cite[Theorem 3, pp. 195]{aksamit2015optional}.
	\end{proof}
	%
	Now, we are able to prove that the process $B^{\tau}$ is a $\left(\mathbb{G},\mathbb{Q}^{}\right)$-Brownian motion, as stated in Lemma \ref{Lemma of the Brownian motion}.
	\begin{proof}[Proof of Lemma \ref{Lemma of the Brownian motion} ]
		Let $(M_t)_{t \geq 0}$ be an arbitrary element in $ \mathcal{M}_{loc}\left(\mathbb{F},\mathbb{P}\right)$. By utilizing Remark 2.5 in  \cite{choulli2022explicit}, we deduce that $\dfrac{\mathcal{E}_{s-}\left(\Gamma^{\mathcal{T}(m)}\right)}{\mathcal{E}_{s}\left(\Gamma^{\mathcal{T}(m)}\right)}=\dfrac{\tilde{G}_s}{G_{s-}}$ and 
		\begin{equation}
			\begin{split}
				\left[\Psi,\mathcal{T}(M)\right]_t&=\left[\mathcal{E}^{-1},\mathcal{T}(M)\right]_t
				\\
				&=\dfrac{G_{t-}}{\tilde{G}_t}\left[\mathcal{E}^{-1},M\right]^{\tau}_t=\dfrac{G_{t-}}{\tilde{G}_t}\left[\mathcal{E}\left(\Gamma^{\mathcal{T}(m)}\right),M\right]_t\\
				&=-\int_{0}^{t}\dfrac{G_{s-}}{\tilde{G}^2_s}\mathcal{E}_{s-}\left(\Gamma^{\mathcal{T}(m)}\right)d\left[m,M\right]^{\tau}_s=-\int_{0}^{t}\dfrac{\Psi_s}{\tilde{G}_s}\mathds{1}_{\{s \leq \tau\}}d\left[m,M\right]_s.
			\end{split}
			\label{explicit calculation}
		\end{equation}
		Now, from Theorem \ref{Theorem of the operator} and the Girsanov-Meyer theorem, we can deduce that the stopped process
		$$
		\mathcal{T}\left(M\right)+\int_{0}^{\cdot} \dfrac{1}{\Psi_s} d\left[\Psi, \mathcal{T}\left(M\right)\right]_s=M^{\tau}
		$$
		is a local martingale in $\mathcal{M}_{loc} \left(\mathbb{G},\mathbb{Q}\right)$. Therefore, since $B \in \mathcal{M}\left(\mathbb{F},\mathbb{P}\right)$ then $B^{\tau} \in \mathcal{M}\left(\mathbb{G},\mathbb{Q}^{}\right)$ and $B^{\tau \wedge T}$ is a $\left(\mathbb{G},\mathbb{Q}^{}\right)$-Brownian motion.
	\end{proof}
	%
	Subsequently, we point out that, under condition \textbf{[P]}, for the integrable $\mathcal{G}_{T \wedge \tau}$-measurable random variable $\Psi_{T}$, we can consider  $\Psi_{\sigma}=\mathbb{E}\left[\Psi_{T}\mid \mathcal{G}_{\sigma}\right]$ for all $\sigma \in \mathfrak{T}_{0,T}(\mathbb{G})$. Therefore the process $\left(\mathbb{E}\left[\Psi_{T} \mid \mathcal{F}_t \right]\right)_{t \leq T}$ belongs to $\mathcal{M}\left(\mathbb{F},\mathbb{P}\right)$, and we can consider it's RCLL version denoted by $(\rho_t)_{t \leq T}$. 
	\begin{proposition}
		Let $\mathbb{Q}^{\ast}$ be a martingale measure defined by $\dfrac{d \mathbb{Q}^{\ast}}{d \mathbb{P}}\Big|_{\mathcal{F}_t}:=\rho_t$,
		for all $t \in [0,T]$. Then $\mathbb{Q}=\mathbb{Q}^{\ast}$ on $\left(\Omega,\left( \mathcal{F}_t\right)_{t \leq T}\right)$.
		\label{equiality of measures}
	\end{proposition}
	%
	\begin{remark}
		A particular conclusion that can be deduced from Proposition \ref{equiality of measures} is that, the probability measure $\mathbb{Q}$ is well-defined in $(\Omega, \mathbb{F}, \mathcal{F}_T)$ and is also locally equivalent to the real life measure $\mathbb{P}$ in $\mathbb{F}$ via the density $(\rho_t)_{t \leq T}$.
	\end{remark}
	%
	Using the result from Proposition \ref{equiality of measures}, predictable version of the Girsanov theorem \cite[Theorem III.8.36]{bookProtter} and  Lemma 2.5 presented in \cite{jeanblanc2015martingale}, we can derive the following result:
	\begin{lemma}
		If the angel brackets $\left\langle \rho,B \right\rangle$ exists in $\mathbb{F}$ for the $\mathbb{Q}$ probability, i.e. $[\rho,B]^{p,\mathbb{F},\mathbb{Q}}=\left\langle \rho,B \right\rangle$ exists, then the process
		$$
		B^{[\rho]}_t=B_t-\int_{0}^{t}\dfrac{1}{\rho_{s-}}d\left\langle \rho,B \right\rangle_s,\quad t \in  [0,T]
		$$
		is an $(\mathbb{F},\mathbb{Q})$-Brownian motion and possesses the martingale representation property in the filtration $\mathbb{F}$ under the probability measure $\mathbb{Q}$.
		\label{lemma of new Brownian in F}
	\end{lemma} 
	%

	Now, we can state the main result of the following subsection :
	\begin{theorem}
		For any bounded $\mathcal{G}_{T \wedge \tau}$-measurable random variable $\xi$, there exists a $\mathbb{G}$-predictable process $(Z_t)_{t \geq 0}$ and a local martingale $M \in \mathcal{M}_{loc}\left(\mathbb{G},\mathbb{Q}\right)$ with finite variation and a default jump such that
		\begin{equation*}
			\left\{
			\begin{split}
				& Z=Z \mathds{1}_{\llbracket0, T \wedge \tau\rrbracket}, \quad Z \in \mathcal{I}(\mathbb{G},\mathbb{Q},B);\\
				& M_0=0,~ dM_{\cdot}=dM_{\cdot \wedge \tau},~ [M,B]=[M^{\tau},B^{\tau}]=0 \text{ on } [0,T];\\
				& \mathbb{E}_{\mathbb{Q}}\left[\xi\mid \mathcal{G}_t\right]=\mathbb{E}_{\mathbb{Q}}\left[\xi\mid \mathcal{G}_0\right]+\int_{0}^{t}Z_s d B^{\tau}_s+\int_{0}^{t} dM_s,\quad t \in [0,T].
			\end{split}
			\right.
		\end{equation*}
		Note that $Z \in \mathcal{I}(\mathbb{G},\mathbb{Q},B)$ is equivalent to $Z \in \mathcal{I}(\mathbb{G},\mathbb{Q},B^{\tau})$.
		\label{Theorem of representation in G,Q} 
	\end{theorem}


	\begin{proof}
		The proof of Theorem \ref{Theorem of representation in G,Q} draws inspiration from an analogous theorem found in \cite{jeanblanc2015martingale} combined with results from Lemma 2.9 in \cite{aksamit2017enlargement} pp. 34, Proposition \ref{equiality of measures}, Lemma 2.2 in \cite{jeanblanc2015martingale}, and Lemmas \ref{lemma of new Brownian in F} and  \ref{Lemma of the Brownian motion}.
	\end{proof}
	%
	\begin{remark}
		%	\begin{itemize}
			%		\item 
			Note that the assumption of boundedness of the $\mathcal{G}_{T \wedge\tau}$-measurable random variable $\xi$ in the representation Theorem \ref{Theorem of representation in G,Q} is equivalent to the property that all
			$(\mathbb{G},\mathbb{Q})$-local martingales defined on $\llbracket 0, T \wedge \tau \rrbracket$ can be written as stochastic integrals with respect to $B^{\tau}$ and an orthogonal martingale $M$ on $[0,T]$ (see
			Theorem 13.4 in \cite{bookHe}).	Additionally, it is important to remark that, since we are dealing with default events and a progressive enlargement of the Brownian filtration, we cannot directly apply the representation property outlined in \cite[Lemma III.4.24, pp. 185]{bookJacod}. Instead, Theorem \ref{Theorem of representation in G,Q} provides a key formula that explicitly describes each component of the decomposition of processes within $\mathcal{M}_{loc}(\mathbb{G},\mathbb{Q})$ in terms of the default time $\tau$. 
			%		This formula aids in defining the solution space for our problem and in explaining why the stochastic integrals are well-defined within the $\mathbb{G}$ filtration under the new probability measure $\mathbb{Q}$, subject to conditions \textbf{[P]} and \textbf{[U]}.		
			%		\item[(c)] Following the construction outlined in Theorem \ref{Theorem of representation in G,Q}, the orthogonal martingale $(M_t)_{t \geq 0}$ is uniquely determined. 
			%	\end{itemize}
		\label{Remark explaining how a probability measure is taking}
	\end{remark}
