	\subsection*{A look at $\mathbb{G}$-predictable processes integrability}
	In this part, we aim to provide a connection between the integrability of predictable processes within the filtration $\mathbb{G}$ in relation to Brownian motion, especially when transitioning from the probability measure $\mathbb{P}$ to $\mathbb{Q}$. To this end, we first introduce the following lemma:
	\begin{lemma}
		Let $\left\{\sigma_n\right\}_{n \in \mathbb{N}}$ be an increasing sequence of stopping times in $\mathfrak{T}(\mathbb{G})$. Then, $\sigma_n \nearrow +\infty$ $\mathbb{P}$-a.s. if and only if $\sigma_n \nearrow +\infty$ $\mathbb{Q}$-a.s.
		\label{stopping times and measure changing}
	\end{lemma}
	%
	\begin{remark}
		\begin{itemize}
			\item[(a)] Let $(Z_{t})_{t \geq 0}$ be a $\mathbb{G}$-predictable process such that $Z=Z\mathds{1}_{\llbracket 0,\tau \rrbracket}$ and $Z \in \mathcal{I}(\mathbb{G},\mathbb{P},B^{\tau})$, then from \eqref{operator T}, we deduce that $\int_{0}^{\cdot} Z_s dB_s$ is a $(\mathbb{G},\mathbb{P})$-semimartingale. Then, applying Lemma 2.2 in \cite{jeanblanc2015martingale}, we deduce that $$\mathcal{I}(\mathbb{G},\mathbb{P},B^{\tau})=\mathcal{I}(\mathbb{G},\mathbb{P},\mathcal{T}(B))\cap \mathcal{I}(\mathbb{G},\mathbb{P},V^{B}),$$
			where $V^B$ is the $\mathbb{G}$-adapted co,continuous processes defined by $V^B:=\int_{0}^{\cdot} \tilde{G}^{-1}_s \mathds{1}_{\{s \leq \tau\}} d[B,m]_s$ and $B^{\tau}=\mathcal{T}(M)+V^{B}$ is a special $(\mathbb{G},\mathbb{P})$-semimartingale.		
			\item[(b)] Note that since for $\mathbb{P}$-almost all $\omega \in \Omega$, $t \mapsto B_t(\omega)$ is a continuous function. Therefor, using the absolute continuity of $\mathbb{Q}$ with respect to $\mathbb{P}$, we get $\mathbb{Q}\big(\omega: t \mapsto B_t(\omega) \text{ is not continuous}\big)=0$. Hence, the process $(B^{\tau}_t)_{t \geq 0}$ has continuous paths in $\mathbb{R}_{+}$ for $\mathbb{Q}$-almost all $\omega \in \Omega$ and we get
			$$
			[B^{\tau},B^{\tau}]=\left[\mathcal{T}(B),\mathcal{T}(B)\right]+2\left[\mathcal{T}(B),V^B\right]+\left[\mathcal{T}(B),V^B\right]=\left[\mathcal{T}(B),\mathcal{T}(B)\right],
			$$
			since
			$$
			\left[\mathcal{T}(B),V^B\right]=\sum \tilde{G}^{-1}\mathds{1}_{\rrbracket0,\tau\rrbracket} \Delta \mathcal{T}(B)\Delta m \Delta B=0,
			$$
			and 
			$$
			\left[V^B,V^B\right]=\sum \tilde{G}^{-2}\mathds{1}_{\rrbracket0,\tau\rrbracket} \left( \Delta m \Delta B\right)^2 =0,
			$$
			where the quadratic variation is computed in the filtration $\mathbb{G}$ with respect to the probability measure $\mathbb{P}$. 		
			\item[(c)] Since  $\mathds{1}_{\llbracket 0,\tau \rrbracket}$ is a $\mathbb{G}$-predictable bounded process and using Theorem I.12 in \cite{bookProtter} and Theorem 1.11-(d) in \cite{book:63874}, we can write 
			$
			[B,B]^{\tau}_t=\int_{0}^{t} \mathds{1}_{\{s \leq \tau\}}d[B,B]_s
			$, $t \geq 0$, under the two equivalent probabilities $\mathbb{P}$ and $\mathbb{Q}$. Moreover, using Theorem  I.14 in \cite{bookProtter}, the process  $\int_{0}^{\cdot} \mathds{1}_{\{s \leq \tau\}}d[B,B]_s$ calculated under $\mathbb{P}$ is indistinguishable from $\int_{0}^{\cdot} \mathds{1}_{\{s \leq \tau\}}ds$ with respect to $\mathbb{Q}$. In other word, the stochastic integral $\int_{0}^{\cdot} \mathds{1}_{\{s \leq \tau\}}d[B,B]_s$ defined in the two senses gives the same $\mathbb{G}$-adapted continuous process with finite variation (see also Lemma 2.1 in  \cite{jeanblanc2015martingale}).
		\end{itemize}
		\label{Remarks for the brownian and quadratic variation}
	\end{remark}
	%
	\begin{proposition}
		Let $(Z_t)_{t \geq 0}$ be a $\mathbb{G}$-predictable process such that $Z=Z\mathds{1}_{\llbracket0,\tau\rrbracket}$. Then, whenever  $Z \in  \mathcal{I}\left(\mathbb{G},\mathbb{P},\mathcal{T}(B)\right)$, we have $Z \in \mathcal{I}\left(\mathbb{G},\mathbb{Q},B^{\tau}\right)$.
		\label{integrability of Z}
	\end{proposition}
	%
	\begin{proof}
		Let $Z \in \mathcal{I}\left(\mathbb{G},\mathbb{P},B^{\tau}\right)$ and let $\left\{\sigma_n\right\}_{n \in \mathbb{N}}$ be an increasing sequence of stopping times in $\mathfrak{T}\left(\mathbb{G}\right)$ such that $\sigma_n \nearrow +\infty$ $\mathbb{P}$-a.s., $\mathbb{E} \int_{0}^{\sigma_n} \left|Z_s \right|^2 \mathds{1}_{\{s \leq \tau\}} d\left[\mathcal{T}(B),\mathcal{T}(B)\right]^{\tau}_s<\infty $, for each $n \in \mathbb{N}$.\\	
		Consider the following sequence of stopping times :
		$$
		\theta_n:=\inf\{t \geq 0:  \Psi_t >n\} \wedge \sigma_n.
		$$
		Then $\left\{\theta\right\}_{n \in \mathbb{N}}$ belongs to $\mathfrak{T}\left(\mathbb{G}\right)$ such that $\theta_n \nearrow +\infty$ $\mathbb{P}$-a.s. as $\Psi$ is a $\mathbb{G}$-adapted RCLL process. Moreover, from Lemma \ref{stopping times and measure changing} and Remark \ref{Remarks for the brownian and quadratic variation}-(b)-(c), we have
		\begin{equation*}
			\begin{split}
				\mathbb{E}^{\ast}\int_{0}^{\theta_n} \left|Z_s \right|^2 \mathds{1}_{\{s \leq \tau\}} ds&=\mathbb{E}^{}\int_{0}^{\theta_n} \Psi_s\left|Z_s \right|^2  d\left[B^{\tau},B^{\tau}\right]_s\\
				&=\mathbb{E}^{}\int_{0}^{\theta_n} \Psi_s\left|Z_s \right|^2 \mathds{1}_{\{s \leq \tau\}} ds\leq n \mathbb{E}^{}\int_{0}^{\sigma_n} \left|Z_s \right|^2 d\left[\mathcal{T}(B),\mathcal{T}(B)\right]^{\tau}_s<\infty,
			\end{split}
		\end{equation*}
		for every $n \in \mathbb{N}$. Hence $Z \in \mathcal{I}\left(\mathbb{G},\mathbb{Q},B^{\tau}\right)$ and this completes the proof. 
	\end{proof}
	\begin{remark} For the reverse property of Proposition \ref{integrability of Z}, we require the condition that the quadratic variation $[m, m]$ of the BMO martingale $(m_t)_{t \geq 0}$ is locally integrable with respect to $\mathbb{Q}$. In this case, by following an argument similar to the fact that $\frac{d\mathbb{P}}{d\mathbb{Q}} = \left(\frac{d\mathbb{Q}}{d\mathbb{P}}\right)^{-1}$ and using an appropriate sequence of stopping times, we can establish the desired result for the $(\mathbb{G},\mathbb{P})$-martingale part and the $(\mathbb{G},\mathbb{P})$-local integrability for the finite variation part from Kunita-Watanabe inequality.
	\end{remark}
