	\section{A classical BSDE and comparison theorems}
	\label{Appendix C}
	In this section, we give an existence and uniqueness result for BSDEs without reflection with stochastic Lipschitz coefficient. 
	More precisely, we consider the following BSDE with default jump: 
	\begin{equation}
		\left\{
		\begin{split}
			& \mathbb{Q}\text{-a.s. for all } t \in [0,T]\\
			&~ Y_{t \wedge \tau}=\xi+\int_{t \wedge \tau }^{T \wedge \tau} f(s,Y_s,Z_s)ds-\int_{t \wedge \tau }^{T \wedge \tau} Z_s d B_s-\int_{t \wedge \tau }^{T \wedge \tau}dM_s;\quad t \in [0,T].\\
			&~  Y_t=\xi,~Z_t=dM_t=0,\text{ on the set }\{t \geq T \wedge\tau\},~\mathbb{Q}\text{-a.s.},\\
		\end{split}
		\right.
		\label{basic classical BSDE}
	\end{equation}
	%
	\begin{theorem}
		Assume that $\xi \in \mathcal{G}_{T \wedge \tau}$ and $f$ satisfies $(\mathbf{H}_2)$ with $\left( \frac{f(t,0,0)}{\alpha_{t}}\right)_{t \geq 0} \in \mathcal{H}^2_T(\beta,\mathbb{F},\mathbb{P})$. Then, the BSDE (\ref{basic classical BSDE}) admits a unique solution $(Y,Z,M) \in \mathfrak{U}^2_{T \wedge \tau}\left( \beta,\mathbb{G},\mathbb{Q}\right)$.
		\label{Existence and uniquess theorem BSDE}
	\end{theorem}
	%
	%
	\begin{theorem}[Comparison theorem]
		et $(Y^i_t,Z^i_t,M^i_t)_{t \geq 0}$ be a solution to BSDE \eqref{basic classical BSDE} associated with parameters $(\xi^i,f^i)$ for $i=1, 2$. If $\xi_1 \leq \xi_2$ and $f^1(s,Y^1_s,Z^1_s)\leq f^2(s,Y^1_s,Z^1_s)$ for all $t \in [0,T\wedge \tau]$. Then $Y^1_t \leq Y^2_t$, $\forall t \geq 0$, $\mathbb{Q}$-almost surely.
		\label{Comparison theorem BSDE}
	\end{theorem}
	%
	\begin{remark}
		By the comparison theorem, we deduce that $\mathcal{E}^f$ is a non-decreasing operator, i.e. for any $\sigma \in \mathfrak{T}_{0\tau^T}(\mathbb{G})$ and any $\xi_1,\xi_2 \in \mathcal{L}^2_{\sigma}\left(\beta,\mathbb{G},\mathbb{Q}^{}\right)$, 
		if $\xi_1 \geq \xi_2$, $\mathbb{Q}$-a.s. then $\mathcal{E}^f_{\cdot,\sigma}(\xi_1) \geq \mathcal{E}^f_{\cdot,\sigma}(\xi_2)$, $\mathbb{Q}$-a.s.
		\label{Monotonicity if the f-evaluation}
	\end{remark}
	%
	\begin{theorem}[Special comparison theorem]
		Suppose that $f^1(s, y, z)$ and $f^2(s, y,z)$ are two drivers such that $f^1(s, \cdot, \cdot)$ and $f^2(s, \cdot, \cdot)$ are $\mathbb{F}$-progressively measurable and $f^2$ satisfies condition ($\mathbf{H}_2$), that $\xi_1$, $\xi_2$ two $\mathcal{G}_{T \wedge \tau}$-measurable random variables and that $K^1$ and $K^2$ are two RCLL, increasing processes.\\	
		If there exist a quadruplet $(Y^i_t,Z^i_t,M^i_t)_{t \geq 0}^{i=1;2}$ satisfying the equations :
		\begin{equation*}
			\left\{
			\begin{split}
				\text{(i)} &~ \mathbb{Q}\text{-a.s. for all } t \in [0,T]\\
				&~ Y^i_{t}=\xi^i+\int_{t }^{T} \mathds{1}_{\{s \leq \tau\}} f^i(s,Y^i_s,Z^i_s)ds+\left( K^{i}_{T}-K^{i}_{t}\right)-\int_{t }^{T } Z^i_s d B_s-\int_{t}^{T}dM^i_s.\\
				\text{(ii)}&~  Y^i_t=\xi^i,~Z^i_t=dK^{i}_t=dM^i_t=0,\text{ on the set }\{t \geq T \wedge\tau\},~\mathbb{Q}\text{-a.s.}
			\end{split}
			\right.
		\end{equation*}
		Moreover, if $f^1(s,Y^1_s,Z^1_s)-f^2(s,Y^1_s,Z^1_s)\leq 0$ for any $s \in [0,T \wedge \tau[$, $\xi_1 \leq \xi_2$  and  $K^2-K^1$ is increasing, then $Y^1_t \leq Y^2_t$, $\forall t \geq 0$, $\mathbb{Q}$-almost surely.
		\label{Theorem de comparison: General result}
	\end{theorem}
