	\section{Conditional expectations and integrable random variables on $\left(\mathbb{G}, \llbracket 0,\tau\llbracket,\mathbb{Q}\right) $}
	\label{Appendix B}
	\begin{lemma}
		\begin{itemize}
			\item[(a)] Let $\left( \mathfrak{X}_t\right)_{t \geq 0}$ be an RCLL $\mathbb{G}$-adapted process and  $\left( \mathfrak{Y}_t\right)_{t \geq 0}$ be an RCLL $\mathbb{G}$-semimartingale such that $\int_{0}^{\cdot}\mathfrak{X}_s d\mathfrak{Y}_s$ is well defined. Assume that $\int_{0}^{\cdot}\mathfrak{X}_s d\mathfrak{Y}_s$ is positive or $\sup_{0 \leq s \leq \cdot} \left( \int_{0}^{s}\mathfrak{X}_s d\mathfrak{Y}_s\right)^{+}$ is integrable. Then we have
			$$
			\mathbb{E}\left[\int_{0}^{\sigma}\mathfrak{X}_s d\mathfrak{Y}_s \mid \mathcal{G}_t \right]=\Psi^{-1}_t \mathbb{E}_{\mathbb{Q}}\left[\int_{0}^{\sigma}\mathcal{E}_s^{-1}\mathfrak{X}_s d\mathfrak{Y}_s \mid \mathcal{G}_t\right],\quad \forall \sigma \in \mathfrak{T}_{t,+\infty}(\mathbb{G})
			$$
			and
			$$
			\mathbb{E}\left[\mathfrak{X}_{\sigma}\right]=	\mathbb{E}_{\mathbb{Q}}\left[\mathfrak{X}_{\sigma}\Psi_{\sigma}^{-1}\right],\quad \forall \sigma \in \mathfrak{T}(\mathbb{G}).
			$$
			\item[(b)] For any integrable or positive process $\left( \mathfrak{X}_t\right)_{t \leq T}$, using the definition of the $\mathbb{P}$-conditional expectation and the equivalent measure $\mathbb{Q}$, we have for any $t \in [0,T]$ and each $\sigma \in \mathfrak{T}_{t,T}(\mathbb{F})$;
			$$
			\mathbb{E}_{\mathbb{Q}}\left[\mathfrak{X}_{\sigma} \mid \mathcal{F}_t\right]=\dfrac{1}{\rho_t}\mathbb{E}\left[\mathfrak{X}_{\sigma} \rho_{\sigma} \mid \mathcal{F}_t\right],~~\text{ with }~ \dfrac{d \mathbb{Q}}{d \mathbb{P}} \mid_{\mathcal{F}_t}=\rho_t.
			$$
			In particular, we have $\mathbb{Q}\left(\tau>t \mid \mathcal{F}_t\right)=G_t>0$.
		\end{itemize}
		\label{Lemma of integrability}
	\end{lemma}
	%
	%
	The two standard observations that follows has been used in the proof of Theorems \ref{Delicate thm} and \ref{Proposition of comparison}.
	\begin{remark}
		For any given RCLL process $(\mathfrak{X}_t)_{t\geq 0}$ such that $\mathfrak{X}_t > 0$ and $\mathfrak{X}_{t-} > 0$, we can assume that $\mathfrak{X}_t \geq \epsilon$ for $d\mathbb{P} \otimes dt$-almost every $(t,\omega) \in [0,+\infty) \times \Omega$ for a sufficiently small chosen $\epsilon > 0$. In particular, we have
		\begin{itemize}
			\item under \textbf{[P]} assumption, we have $G \geq \epsilon$
			\item as $\Psi=\mathcal{E}\left(-\int_{0}^{\cdot} G^{-1}_{s-}d \mathcal{T}(m)_s\right)$ and $\Delta \mathcal{T}(m)=\frac{G_{-}}{\tilde{G}}\Delta m \mathds{1}_{\rrbracket 0,\tau \rrbracket}$, we derive that 
			$$1-G^{-1}_{-}\Delta \mathcal{T}(m)=\frac{G_{-}}{\tilde{G}}\mathds{1}_{\rrbracket 0, \tau\rrbracket}+\mathds{1}_{\rrbracket \tau,+\infty\llbracket}.$$ Then, under \textbf{[P]}, we derive that $G_{-}, \tilde{G}>0$, then $\Psi >0$. Additionally, by calculating $\Delta \Psi$, we get $ \Psi=\Psi_{-}\dfrac{G_{-}}{\tilde{G}}\mathds{1}_{\rrbracket 0,\tau\rrbracket}+\Psi_{-} \mathds{1}_{\rrbracket \tau,+\infty\llbracket}$, then under \textbf{[P]}, we derive $\Psi_{-}>0$ and we can also assume that $\Psi \geq \epsilon$.

			\item From (\ref{Definition of E and E tilde}), we have $\tilde{\mathcal{E}} >0$. Indeed, under assumption \textbf{[P]}, we have $1-\tilde{G}^{-1}\Delta D^{o,\mathbb{F},\mathbb{P}}=1-\tilde{G}^{-1}\left(\tilde{G}-G\right)=\tilde{G}^{-1}G>0$. Moreover, note that the left-limited process $\left(\tilde{\mathcal{E}}_{t-}\right)_{t \geq 0}$ with the convention $\tilde{\mathcal{E}}_{0-}=\tilde{\mathcal{E}}_{0}$ satisfies $\tilde{\mathcal{E}}_{-}=\frac{\tilde{G}}{G}\tilde{\mathcal{E}}$, from which we also derive that $\tilde{\mathcal{E}}_{-}>0$ and we might also suppose that $\tilde{\mathcal{E}} \geq \epsilon$.
		\end{itemize}
		\label{Remark of epsilon}
	\end{remark}
	%
	%
	%
	\begin{remark}
		Note that the processes $\left(K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ and $\left( K^{n,\mathbb{F},-}_t\right)_{t \leq T}$ defined in the proof of Theorem \ref{Proposition of comparison} are well-defined Stieltjes integrals.\\
		To see this, we first examine the properties satisfied by the processes $\mathsf{k}^{n,\mathbb{F},+}:=\left(n\mathbb{E}_{\mathbb{Q}} \left[ (L_t-Y^{n}_t)^{+}\mathds{1}_{\{t < \tau\}} \mid \mathcal{F}_t \right]\right)_{t \leq T}$ and $\mathsf{k}^{n,\mathbb{F},-}:=\left(n\mathbb{E}_{\mathbb{Q}} \left[ (L_t-Y^{n}_t)^{+}\mathds{1}_{\{s < \tau\}} \mid \mathcal{F}_t \right]\right)_{t \leq T}$. These will ensure that the Lebesgue integrals $\left(K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ and $\left( K^{n,\mathbb{F},-}_t\right)_{t \leq T}$ are increasing continuous $\mathbb{F}$-adapted Stieltjes integrals.\\
		To address this, we utilize the classical $\mathbb{F}$-decomposition of $\mathbb{G}$-optional processes on the time interval $\llbracket 0,\tau\llbracket$. Since $Y^n$, $L$, and $U$ are $\mathbb{G}$-optional processes on $[0,T]$, and since condition \textbf{[P]} is satisfied, we can deduce from \cite[Lemma 4.4]{book:63874} the existence of unique $\mathbb{F}$-optional processes $\mathcal{K}^{n,\mathbb{F},+}$ and $\mathcal{K}^{n,\mathbb{F},-}$ such that: 
		$$
		(L_t-Y^{n}_t)^{+}\mathds{1}_{\{t < \tau\}}=\mathcal{K}^{n,\mathbb{F},+}_t\mathds{1}_{\{t < \tau\}},\text{ and } (Y^{n}_t-U_t)^{+}\mathds{1}_{\{t < \tau\}}=\mathcal{K}^{n,\mathbb{F},-}_t\mathds{1}_{\{t < \tau\}}
		$$	 
		Since $Y^n$, $L$, and $U$ are RCLL processes, we deduce that $\mathcal{K}^{n,\pm}$ are also RCLL processes. Moreover, from \cite[Lemma B.1]{AksamitChoulli2017}, we may choose $\mathcal{K}^{n,\mathbb{F},\pm}$ to be non-negative.\\
		Taking the conditional expectation (which is well defined due to the integrability property satisfied by $Y^n$, $L$ and $U$), we get
		$$
		\mathsf{k}^{n,\mathbb{F},+}_t=n\mathcal{K}^{n,+}_t\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_t \right],\text{ and } \mathsf{k}^{n,\mathbb{F},-}_t=n\mathcal{K}^{n,\mathbb{F},-}_t\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_t \right].
		$$
		As $\left( \mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_t \right]\right)_{t \leq T}$ is an RCLL $\mathbb{F}$-supermartingale (there exists a unique modification which is RCLL form \cite[Theorem I.9]{bookProtter}), we deduce that $\mathsf{k}^{n,\mathbb{F},\pm}$ is an RCLL $\mathbb{F}$-adapted process. Hence $\mathbb{F}$-optional. Then, using \cite[Proposition I.3.5]{bookJacod}, we deduce that $\left(K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ and $\left( K^{n,\mathbb{F},+}_t\right)_{t \leq T}$ are well-defined, finite-valued Stieltjes integrals, which are increasing $\mathbb{F}$-adapted and continuous.	  	
		\label{RMQ of Well defined Steiltjes integrals}
	\end{remark}
	%
	%
	%
	\begin{lemma}
		Let $F$ be an integrable $\mathcal{G}_s$-measurable random variable ($s \in [0,T]$) and $\mathcal{F}_{s,t}:=\sigma\big(B_u-B_s;s \leq u \leq t,~t \in [0,T]\big)$. Assume that $\tau$ and $\mathcal{F}_{T}$ are independent under $\mathbb{Q}$. Then, we have:
		$$
		\mathbb{E}_{\mathbb{Q}}\left[F \mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_s \vee \mathcal{F}_{s,t}\right]=\mathbb{E}_{\mathbb{Q}}\left[F \mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_s \right],~ \forall t \in [s,T].
		$$
		\label{Lemma of conditional expectation}
	\end{lemma}
	%
	\begin{proof}
		The proof of this result is akin to the proof of Lemma 5.3 in \cite{AkdimDiakhabyOuknine} (and also Lemma 5 in \cite{el2009bsdes}) with some modifications, which we clarify for the reader's convenience. Now, when we consider $A \in \mathcal{F}_t$ and $C \in \mathcal{F}_{s,t}$, then
		\begin{equation}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mathds{1}_C \mathbb{E}\left[F \mid \mathcal{F}_s\right]\right]&=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A  \mathbb{E}\left[F \mid \mathcal{F}_s\right]\right] \mathbb{E}_{\mathbb{Q}}\left[ \mathds{1}_C\right]. 
			\end{split}
			\label{equality becomes}
		\end{equation}
		Since $\mathds{1}_C$ is independent of $\mathcal{F}_s$, we can proceed. Now, consider that the $\sigma$-algebra $\mathcal{G}_s$ is generated by random variables of the form $F_s h(s \wedge \tau)$, where $F_s$ is an $\mathcal{F}_s$-measurable random variable, and $h$ is a  deterministic Borel function on $\mathbb{R}_{+}$. Therefore, by a monotone class argument, it is enough to prove the property of Lemma \ref{Lemma of conditional expectation} for $\mathcal{G}_s$-measurable random variables of the form $F_s  h(s)\mathds{1}_{\{s<\tau \}}$, where $F_s$ is an integrable random variable. By using again the independence property of $\mathds{1}_A$ with respect to $\mathcal{F}_s$ together with the $\mathbb{F}$-optionality of the Azéma's supermartingale $G^{\mathbb{Q}}_s:=\mathbb{Q}\left(\tau >s \mid \mathcal{F}_s\right)$ , the equality \eqref{equality becomes} can be expressed as
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mathds{1}_C \mathbb{E}\left[F \mid \mathcal{F}_s\right]\right]=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mathds{1}_CF_s h(s) G^{\mathbb{Q}}_s\right]&=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A F_s h(s)G^{\mathbb{Q}}_s\right]\mathbb{E}_{\mathbb{Q}}\left[ \mathds{1}_C\right]\\
				&=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mathbb{E}\left[F \mathds{1}_{\{s<\tau\}} \mid \mathcal{F}_s\right] \right]\mathbb{E}\left[ \mathds{1}_C\right]\\
				&=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mathds{1}_C F\mathds{1}_{\{s<\tau\}}\right],  
			\end{split}
		\end{equation*}
		where in the last equality, we have used the independence of $\tau$ and $\mathcal{F}_{T}$. This completes the proof.
	\end{proof}
	%
	\begin{remark}
		In general, the assumption of $\tau$ and $\mathcal{F}_{T}$ being independent is satisfied, for example, in the particular case where $\tau$ is an initial time, subject to certain additional specific conditions. For further details, we direct readers to \cite[Proposition 2.3]{jeanblanc2009progressive} and the references therein. 
	\end{remark}
	%
	\begin{remark} 
		\begin{itemize}
			\item[(a)] If $\tau$ and $\mathcal{F}_{T}$ are independent under $\mathbb{Q}$, Lemma \ref{Lemma of conditional expectation} enables us to express:
			$$
			\mathbb{E}_{\mathbb{Q}}\left[F  \mathds{1}_{\{s <\tau\}} \mid \mathcal{F}_t\right] = \mathbb{E}_{\mathbb{Q}}\left[F \mathds{1}_{\{s <\tau\}} \mid \mathcal{F}_s\right],~ \forall t \in [s,T]
			$$
			for any  bounded $\mathcal{G}_s$-measurable ($s \in [0,T]$) random variable.
			\item[(b)] Let $(Z_t)_{t \geq 0}$  a $\mathbb{G}$-predictable process such that $Z \in \mathcal{I}(\mathbb{G},\mathbb{Q},B)$ and $Z=Z \mathds{1}_{\llbracket 0,\tau \rrbracket}$, then using the continuity of the Brownian motion $(B^{\tau}_t)_{t \geq 0},$ we obtain
			$$
			\int_{0}^{t}Z_s dB_s=\int_{0}^{t}(1-D_{s-})Z_s dB_s=\int_{0}^{t} \mathds{1}_{\{s <\tau\}} Z_s dB_s,~ \forall t \in [0,T],~\mathbb{Q}\text{-a.s.}
			$$
		\end{itemize}
		\label{strssfull remark}
	\end{remark}
	%
	%
	We are now prepared to provide the proof for Lemma \ref{result of interchanging the conditional expectation}.
	\begin{proof}[Proof of Lemma \ref{result of interchanging the conditional expectation}]
		First, note that under condition \textbf{[P]}, the $(\mathbb{G},\mathbb{P})$-martingale density $\left(\varPsi_t\right)_{t \geq 0}$ can be expressed as $\varPsi_t=\mathbb{E}\left[\varPsi_{T} \mid \mathcal{G}_t\right]$, $t \in [0,T]$. Then, taking the conditional expectation in both sides, we obtain $\mathbb{E}\left[\varPsi_t \mid \mathcal{F}_t\right]=\rho_t$ for all $t \in [0,T]$. \\	
		Now, let $D_t$ denotes the derivative operator and $\mathbb{D}^{1,2}$ it's domain in $\mathbb{L}^2$, defined as the space of the random variables that are differentiable in the Malliavin sense, more precisely $\mathbb{D}^{1,2}$ is the closure of the class of smooth random variables with respect to a given norm under which $\mathbb{D}^{1,2}$ is an Hilbert space (see \cite{Malliavin, oksendal1997introduction} for more details). Thus, to show the result of Lemma \ref{result of interchanging the conditional expectation}, it suffices to prove that for $F \in \mathds{D}^{1,2}$ be bounded $\mathcal{F}_t$-measurable then $
		\mathbb{E}_{\mathbb{Q}}\left[F\int_{0}^{t} \left| Z_s\right|^2 ds  \right]<\infty
		$, for all $t \in [0,T]$. Therefore, using the duality relation (see \cite{Malliavin} for example) in the setting $\left(\mathbb{F},\mathbb{P}\right)$ and Proposition \ref{equiality of measures}, we get
		\begin{equation}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[F\int_{0}^{t} Z_s dB_s  \right]&=\mathbb{E}\left[F\int_{0}^{t} \rho_{s} Z_s dB_s  \right]
				=\mathbb{E}\left[\int_{0}^{t}\left(D_s F\right) \rho_{s} Z_s ds  \right]\\
				&=\int_{0}^{t}\mathbb{E}\left[\left(D_s F\right) \rho_{s} Z_s \right] ds 
				=\int_{0}^{t}\mathbb{E}\left[ \mathbb{E}\left[\left\lbrace \left(D_s F\right) \rho_{s} Z_s\right\rbrace  \mid \mathcal{F}_s \right] \right]  ds.
			\end{split}
			\label{Comming back in Malliavin}
		\end{equation} 
		From Lemma \eqref{Lemma of conditional expectation} (see also Remark \ref{strssfull remark}-(a)) and the $\mathcal{F}_t$-measurability of $F$, we obtain $F=\mathbb{E}\left[F \mid \mathcal{F}_t\right]=\mathbb{E}\left[F \mid \mathcal{F}_s\right]$ on the set $\{s<\tau\}$, next applying Proposition 1.2.8 in \cite{Malliavin}, we have $D_s F =\mathbb{E}\left[D_s F \mid \mathcal{F}_s\right]$, hence $D_s F \in \mathcal{F}_s$ on the set $\{s<\tau\}$. Returning to \eqref{Comming back in Malliavin} and substituting these relations with the statement of Remark \ref{strssfull remark}-(b), we derive
		\begin{equation*}
			\begin{split}
				\mathbb{E}_{\mathbb{Q}}\left[F\int_{0}^{t} Z_s dB_s  \right]
				&=\int_{0}^{t}\mathbb{E}\left[\left(D_s F\right) \rho_{s} \mathbb{E}\left[ Z_s \mid \mathcal{F}_s \right] \right]  ds
				=\mathbb{E}\left[\int_{0}^{t} \left(D_s F\right) \rho_{s} \mathbb{E}\left[ Z_s  \mid \mathcal{F}_s \right] ds\right]\\
				&=\mathbb{E}\left[F\int_{0}^{t}  \rho_{s} \mathbb{E}\left[ Z_s  \mid \mathcal{F}_s \right] dB_s\right]
				=\mathbb{E}_{\mathbb{Q}}\left[F\int_{0}^{t}  \mathbb{E}\left[ Z_s  \mid \mathcal{F}_s \right] dB_s\right]\\
				&=\mathbb{E}_{\mathbb{Q}}\left[F\int_{0}^{t}  \mathbb{E}_{\mathbb{Q}}\left[ Z_s  \mid \mathcal{F}_s \right] dB_s\right].
			\end{split}
		\end{equation*} 
		In the last equality we have used Proposition \ref{equiality of measures}, and the $(\mathbb{F},\mathbb{P})$-martingale property of $(\rho_t)_{t \leq T}$ which yields to the fact that $\mathbb{E}_{\mathbb{Q}}\left[ Z_s  \mid \mathcal{F}_s \right] =\mathbb{E}\left[ \rho_{s} Z_s  \mid \mathcal{F}_s \right]\frac{1}{\rho_s}=\mathbb{E}\left[ Z_s  \mid \mathcal{F}_s \right]$. The proof is then complete.

		%	 This result can be generalized to any $\mathcal{G}_s$-measurable random variable $Z_s$ using it's simple function representation and $$\mathbb{Q}\left(A \mid \mathcal{F}_s\right)=\mathbb{E}_{\mathbb{Q}}\left[\mathds{1}_A \mid \mathcal{F}_s\right]=\frac{1}{\rho_s}\mathbb{E}\left[\rho_s\mathds{1}_A \mid \mathcal{F}_s\right]=\mathbb{E}\left[\mathds{1}_A \mid \mathcal{F}_s\right]=\mathbb{P}\left(A \mid \mathcal{F}_s\right),\quad A \in \mathcal{G}_s$$ 
		%	The proof is then complete.
	\end{proof}





