%Section 0
\section{Introduction}

%0.1
\subsection{}\label{SS:CharacteristicK}
Let ${\mathbf k}$ be an algebraically closed field of characteristic $p \geq 0$. In the case where $p > 0$, we will assume that $p$ is a large prime number so that our operations with Lie algebras are as in the characteristic 0 case.  In the following,  $G$ will denote a classical connected reductive algebraic group over ${\mathbf k}$, $\mathfrak g$ will denote the Lie algebra of $G$ and $\iota:{\mathbf k}^{\times} \longrightarrow G$ will be a homomorphism of algebraic groups. 

%0.2
\subsection{} 
It is known that the centralizer 
\[
G^{\iota} = \{g \in G \mid g \iota(t) = \iota(t) g \text{ for all $t \in {\mathbf k}^{\times}$}\}
\]
of $\iota$ is a connected reductive subgroup of $G$ and it acts  on the eigenspace 
\[
{\mathfrak g}_m = \{X \in {\mathfrak g} \mid Ad(\iota(t)) X = t^m X \text{  for all $t \in {\mathbf k}^{\times}$}\},
\]
 where $m \in {\mathbb Z}$, by restriction of the adjoint action of $G$.  For $m \ne 0$, the elements in ${\mathfrak g}_m$ are nilpotent elements.

%0.3
\subsection{} 
We will study the $G^{\iota}$-orbits on the eigenspace ${\frak g}_2$ in the case of symplectic and special orthogonal groups.
The orbits of $G^{\iota}$ on these eigenspaces have already been studied by Vinberg in \cite{V1979}, by Kawanaka in \cite{K1987}, as well as by Derksen and Weyman in \cite{DW2002}. Lusztig has also given such a parametrization in \cite{L2010} and with Yun in  \cite{LY2018}.  We will use the approach of Derksen and Weyman  in \cite{DW2002}  to parametrize these orbits. We will recall their approach in the next section.  In paragraph 3.2 in \cite{C2008}, Ciubotaru gave a different approach for enumerating these $G^{\iota}$-orbits. It is a general algorithm for which the computations are proportional to the rank of the Lie algebra ${\frak g}$.  

%0.4
\subsection{}
The example 5.5 in Lusztig's paper \cite{ L2010} was our starting point for our study.  To be more precise,  we will  have a finite dimensional vector space $V$ over ${\mathbf k}$ with a non-degenerate  bilinear form $\langle\ , \ \rangle:V \times V \rightarrow {\mathbf k}$ which is either symmetric or skew-symmetric and an ${\mathcal I}$-grading $V = \oplus_{i \in {\mathcal I}} V_i$ such that $\langle u, v \rangle = 0$ whenever $u \in V_i$, $v \in V_j$ and $i + j \ne 0$.  Here ${\mathcal I}$ will be a subset of integers with  the same parity (either they are all even or all odd) such that if $i \in {\mathcal I}$, then $-i \in {\mathcal I}$. ${\mathfrak g}$ will be the Lie algebra of $V$ relative to this bilinear form. In other words, ${\mathfrak g}$  will be the set of endomorphisms $X:V \rightarrow V$ of $V$ such that $\langle X(u), v\rangle + \langle v, X(v)\rangle = 0$ whenever $u, v \in V$,   $G$ will be the connected reductive  subgroup of $GL(V)$ such that  $\langle gu, gv\rangle = \langle u, v \rangle$ for all $u, v \in V$ and $g \in G$ and  whose Lie algebra is ${\mathfrak g}$ and $\iota:{\mathbf k}^{\times} \rightarrow G$ is the unique algebraic homomorphism such that $\iota(t) u = t^i u$ for all $t \in {\mathbf k}^{\times}$ whenever $u \in V_i$ and $i \in {\mathcal I}$.  

As above we have that $G^{\iota}$ acts by restriction of the adjoint action of $G$ on the eigenspace ${\mathfrak g}_m$. We will give a combinatorial object: ${\mathcal I}$-tableau  such that we have a bijection between a subset of such tableaux and the $G^{\iota}$-orbits in ${\mathfrak g}_2$. For each $G^{\iota}$-orbit in ${\mathfrak g}_2$, we will give using the corresponding ${\mathcal I}$-tableau:
\begin{itemize}
\item a Jacobson-Morozov triple $(E, H, F)$;
\item an equation of the dimension of the orbit;
\item the partition corresponding of the Jordan blocs for any element in this orbit;
\item when two $G^{\iota}$-orbits are in the same $G$-orbit;
\item the parabolic subalgebra of $G$ and the Levi subalgebra  as defined in section 5 of \cite{L1995} corresponding to this $G^{\iota}$-orbit;
\item the number of irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on this orbit;
\item the set of symbols as in sections 11 to 13 of \cite{L1984}  corresponding to the irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on this orbit.
\end{itemize}

In \cite{BI2021},  M. Boos and G. Cerulli Irelli, were able to describe the partial order on the $G^{\iota}$-orbits in ${\frak g}_2$, that is when a $G^{\iota}$-orbit ${\mathcal O}$ is in the Zariski closure $\overline{\mathcal O'}$ of the $G^{\iota}$-orbit ${\mathcal O'}$. We will  state their result to be complete using the ${\mathcal I}$-tableaux. 

%0.5
\subsection{}
In section 1, we will recall the results of Derksen and Weyman on orthogonal and symplectic representations of symmetric quivers.  In section 2, we will construct for each indecomposable such representation: a Jacobson-Morozov triple. In section 3 (respectively section 4), we will study the $G^{\iota}$-orbits in ${\mathfrak g}_2$ when $\vert {\mathcal I} \vert$ is even (respectively odd).  

In the case where $\vert {\mathcal I} \vert$ is odd and the bilinear form $\langle \  , \  \rangle$ is symmetric, we have to be careful. Derksen and Weyman restrict their study to orthogonal isomorphism, but we can also ask what happens if we  consider special orthogonal isomorphism. We look at this in section 5.  In section 6, we study the parabolic subalgebra  (respectively subgroup) of $G$ and the Levi subalgebra   (respectively subgroup) as defined in section 5 of \cite{L1995}. Finally in section 7, we express the number  of irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on each orbit. We also present examples where we use Lusztig's symbols as in sections 11 to 13 of \cite{L1984} to enumerate these $G^{\iota}$-equivariant irreducible local systems.


%section 1
\section{Symmetric quivers}

In this section, we will recall some of the results on symmetric quivers and their  orthogonal (resp. symplectic) representations as presented in the article \cite{DW2002} of Derksen and Weyman

%definition 1.1
\begin{definition}
A {\it quiver} $\Omega = ({\mathcal I}, {\mathcal A}, h: {\mathcal A} \rightarrow {\mathcal I},  t: {\mathcal A} \rightarrow {\mathcal I})$ consists of a finite set ${\mathcal I}$ of vertices, a finite set  ${\mathcal A}$ of arrows and two functions such that, for an arrow $(i \rightarrow j)$ in ${\mathcal A}$, then  $h(i \rightarrow j) = j$ is the head of the arrow and  $t(i \rightarrow j) = i$ is the tail of the arrow.
\end{definition}

%definition 1.2
\begin{definition} A {\it representation} $(V, \phi)$ of the quiver $\Omega = ({\mathcal I}, {\mathcal A}, h: {\mathcal A} \rightarrow {\mathcal I},  t: {\mathcal A} \rightarrow {\mathcal I})$ consists of a collection of finite-dimensional ${\mathbf k}$-vector spaces $(V_i)_{i \in {\mathcal I}}$ and a collection of linear transformations $\phi_{a}: V_{t(a)} \rightarrow V_{h(a)}$, one for each arrow $a \in  {\mathcal A}$.  
\end{definition}

%definition 1.3
\begin{definition} \label{Def1.3} A {\it morphism} between two quiver representations 
\[
\psi: (V, \phi) \rightarrow (V', \phi')
\]
 of  $\Omega = ({\mathcal I}, {\mathcal A}, h: {\mathcal A} \rightarrow {\mathcal I},  t: {\mathcal A} \rightarrow {\mathcal I})$
is a collection of linear transformations $\psi_i: V_i \rightarrow V'_i$, one for each $i \in {\mathcal I}$
such that $\phi'_a \circ \psi_{t(a)} = \psi_{h(a)} \circ \phi_a$ for each arrow $a \in {\mathcal A}$. 
We will denote by $V_{\Sigma}$: the {\it direct sum} $\oplus_{i \in {\mathcal I}} V_i$ and by $\psi_{\Sigma}: V_{\Sigma} \rightarrow V'_{\Sigma}$: the unique linear map such that $\psi_{\Sigma}(v) = \psi_i(v)$ for all $i \in {\mathcal I}$ and all $v \in V_i$.

The {\it identity morphism} $Id_{(V, \phi)}: (V, \phi) \rightarrow (V, \phi)$  and the composition of morphisms are defined as expected. 

Two quiver representations $(V, \phi)$ and $(V', \phi')$ are said to be {\it isomorphic} if there exist morphisms $\psi:(V, \phi) \rightarrow (V', \phi')$ and $\psi':(V', \phi') \rightarrow (V, \phi)$ such that $\psi' \circ \psi = Id_{(V, \phi)}$ and $\psi \circ \psi' = Id_{(V', \phi')}$.
\end{definition}

%definition 1.4
\begin{definition}
The representations of a quiver $\Omega$ form an abelian category with the morphisms as defined above. If $(V, \phi)$ and $(V', \phi')$ are representations of $\Omega$, then their {\it direct sum} $(V, \phi) \oplus (V', \phi')$ is the representation:  $(V \oplus V')_{i \in {\mathcal I}} = (V_i \oplus V'_i)_{i \in {\mathcal I}}$ and 
\[
(\phi \oplus \phi')_a = \phi_a \oplus \phi'_a: V_{t(a)} \oplus V'_{t(a)} \rightarrow V_{h(a)} \oplus V'_{h(a)}
\]
defined by
\[
(v_{t(a)}, v'_{t(a)}) \mapsto  (\phi_a(v_{t(a)}), \phi'_a(v'_{t(a)}))
\]
for each arrow $a \in {\mathcal A}$. A representation $(V, \phi)$ is said to be {\it indecomposable} if it is non-trivial and it is not the direct sum of two non-trivial representations. 
\end{definition}

%definition 1.5
\begin{definition}
A quiver $\Omega = ({\mathcal I}, {\mathcal A}, h: {\mathcal A} \rightarrow {\mathcal I},  t: {\mathcal A} \rightarrow {\mathcal I})$ with an involution $\sigma$ of the set ${\mathcal I}$ of vertices and of the set ${\mathcal A}$ of arrows such that the orientation of  all the arrows is reversed by $\sigma$ is said to be a {\it symmetric quiver} $(\Omega, \sigma)$.
\end{definition}

%definition 1.6
\begin{definition}\label{D:IsoDual}
An {\it orthogonal} (respectively {\it symplectic}) {\it representation} $(V, \phi, \langle\  , \  \rangle)$ of a symmetric quiver $(\Omega, \sigma)$ is a representation $(V, \phi)$  of the quiver $\Omega$ with a non-degenerate symmetric (respectively skew-symmetric) bilinear form  $\langle \  ,  \   \rangle$ on $V_{\Sigma}$ such that the restriction of $\langle\  , \  \rangle$ to $V_i \times V_j$ is $0$ if $j \ne \sigma(i)$ and $\langle\phi_a(v), v'\rangle + \langle v, \phi_{\sigma(a)}(v')\rangle = 0$ for all arrows $a \in {\mathcal A}$ and for all  vectors $v \in V_{t(a)}$,  $v' \in V_{\sigma(h(a))}$. 

Using the non-degenerate bilinear form $\langle\ , \  \rangle$ and the map $V_{\Sigma} \rightarrow V^*_{\Sigma}$ given by $v \mapsto \langle v, \  \rangle$, we can identify $V_{\Sigma}$ with  its dual $V^*_{\Sigma}$. 
\end{definition}

%definition 1.7
\begin{definition}
Given a symmetric quiver $(\Omega, \sigma)$ and a representation $(V, \phi)$ of the quiver $\Omega$, then the {\it dual representation} $(V, \phi)^* =  (V^*, \phi^*)$ is defined as the representation of $\Omega$ where $V^*$ is the collection of finite-dimensional vector spaces $(V^*)_{i} = (V_{\sigma(i)})^*$ for all vertices $i \in {\mathcal I}$ and $(\phi^*)_a = -(\phi_{\sigma(a)})^*$ for all arrows $a \in {\mathcal A}$. 

If $\psi:(V, \phi) \rightarrow (V', \phi')$ is a morphism of representations of the quiver $\Omega$, then its dual is $\psi^*:(V', \phi')^* \rightarrow (V, \phi)^*$ is defined by 
\[
(\psi^*)_i = (\psi_{\sigma(i)})^* :((V')^*)_{i} = (V'_{\sigma(i)})^* \rightarrow (V^*)_i = (V_{\sigma(i)})^* 
\]
for all vertices $i \in {\mathcal I}$.
\end{definition}

%remarque 1.8
\begin{remark}
If $(V, \phi, \langle\  , \  \rangle)$ is an orthogonal (respectively symplectic) representation of the symmetric quiver $(\Omega, \sigma)$, then $(V, \phi)$ and $(V, \phi)^*$ can be identified using the non-degenerate bilinear form $\langle\ , \  \rangle$. Under this identification of $V_{\Sigma}$ with $V_{\Sigma}^*$ given in \ref{D:IsoDual} above, we get $(V^*)_i = (V_{\sigma(i)})^* =V_i$ and also that $(\phi^*)_a = - (\phi_{\sigma(a)})^* = \phi_a$.  This last equation follows from  $\langle\phi_a(v), v'\rangle = -  \langle v, \phi_{\sigma(a)}(v')\rangle$ for all arrows $a \in {\mathcal A}$ and for all vectors $v \in V_{t(a)}$,  $v' \in V_{\sigma(h(a))}$. In other words, an orthogonal (respectively symplectic) representation of a symmetric quiver is always {\it self-dual}.
\end{remark}

%definition 1.9
\begin{definition}
 Two orthogonal (resp.  symplectic) representations $(V, \phi, \langle\  , \   \rangle)$ and $(V', \phi', \langle\  , \   \rangle')$ of the symmetric quiver $(\Omega, \sigma)$ are {\it isomorphic} if there exists a morphism $\psi: (V, \phi) \rightarrow (V', \phi')$ of representations of the quiver $\Omega$ such that $\psi^* \circ \psi = Id_{(V, \phi)}$ and $\psi \circ \psi^* = Id_{(V', \phi')}$
\end{definition}

%definition 1.10
\begin{definition}
 If $(V, \phi, \langle\  , \   \rangle)$ and $(V', \phi', \langle\  , \   \rangle')$ are two orthogonal (respectively  symplectic) representations  of the symmetric quiver $(\Omega, \sigma)$, then their {\it direct sum} $(V, \phi, \langle\  , \   \rangle) \oplus (V', \phi', \langle\  , \   \rangle')$ is the orthogonal (resp. symplectic) representation $ = (V'', \phi'', \langle\  , \   \rangle'')$  of the symmetric quiver $(\Omega, \sigma)$, where  $(V'', \phi'')$ is the direct sum $(V, \phi) \oplus (V', \phi')$ as defined in \ref{Def1.3} and  the bilinear form $\langle\  , \   \rangle''$ on $V''_{\Sigma} = V_{\Sigma} \oplus V'_{\Sigma}$ is the direct sum of  $\langle\  , \   \rangle$ and $\langle\  , \   \rangle'$. 
\end{definition}

%definition 1.11
\begin{definition}
A orthogonal (respectively  symplectic) representation $(V, \phi, \langle\  , \   \rangle)$ is said to be {\it indecomposable} if it is non-trivial and it is not the direct sum of two non-trivial orthogonal (resp. symplectic) representations. 

Note that an indecomposable orthogonal (respectively symplectic) representation of the symmetric quiver $(\Omega, \sigma)$ need not be indecomposable as a representation of the quiver $\Omega$.
\end{definition}

%theorem 1.12
\begin{theorem}\label{T:CaracterisationRepresentation}
Let   $(\Omega, \sigma)$ be a symmetric quiver  and  two orthogonal (resp. symplectic) representations  $(V, \phi, \langle\  , \   \rangle)$, $(V', \phi', \langle\  , \   \rangle')$ of $(\Omega, \sigma)$. Then $(V, \phi, \langle\  , \   \rangle)$ and $(V', \phi', \langle\  , \   \rangle')$ are isomorphic as  orthogonal (resp. symplectic) representations of the symmetric quiver $(\Omega, \sigma)$ if and only if $(V, \phi)$ and $(V', \phi')$ are isomorphic as   representations of the quiver $\Omega$.
\end{theorem}
\begin{proof}
This is theorem 2.6 in \cite{DW2002}. See also theorem 2.6 in \cite{BI2021} for another proof.
\end{proof}

Now to get a hold on the indecomposable orthogonal (resp. symplectic) representations of the symmetric quiver $(\Omega, \sigma)$,  the following proposition also proved in \cite{DW2002} is useful.

%proposition 1.13
\begin{proposition}\label{PropDecomposition}
If $(V, \phi, \langle\  , \   \rangle)$ is an indecomposable orthogonal (respectively  symplectic) representation of the symmetric quiver $(\Omega, \sigma)$, then, as a representation of the quiver $\Omega$, $(V, \phi)$ is either indecomposable or is isomorphic to the direct sum of $(V', \phi')$ and $(V', \phi')^*$, where $(V', \phi')$ is an indecomposable representation of $\Omega$.
\end{proposition}
\begin{proof}
This is proposition 2.7 in \cite{DW2002}.
\end{proof}

%definition 1.14
\begin{definition}
If $(\Omega, \sigma)$ and $(\Omega', \sigma')$ are two symmetric quivers, where $\Omega = ({\mathcal I}, {\mathcal A}, h: {\mathcal A} \rightarrow {\mathcal I},  t: {\mathcal A} \rightarrow {\mathcal I})$ and $\Omega' = ({\mathcal I}', {\mathcal A}', h': {\mathcal A}' \rightarrow {\mathcal I}',  t': {\mathcal A}' \rightarrow {\mathcal I}')$, then we define the {\it disjoint union} $(\Omega, \sigma) \coprod (\Omega', \sigma')$ of $(\Omega, \sigma)$ and $(\Omega', \sigma')$ as the symmetric quiver $(\Omega'',\sigma'')$ where 
$
\Omega'' = ({\mathcal I} \coprod {\mathcal I}', {\mathcal A} \coprod {\mathcal A}', h \coprod h': {\mathcal A} \coprod {\mathcal A}' \rightarrow {\mathcal I} \coprod {\mathcal I}', t \coprod t': {\mathcal A} \coprod {\mathcal A}' \rightarrow {\mathcal I} \coprod {\mathcal I}')
$
and  the restrictions  of  $\sigma''$ to ${\mathcal I} \coprod {\mathcal I}'$ and ${\mathcal A} \coprod {\mathcal A}'$ are $\sigma$ and $\sigma'$  respectively.

A symmetric quiver is said to be {\it irreducible} if it is not the disjoint union of two non-trivial symmetric quivers.
\end{definition} 

%definition 1.15
\begin{definition}
A symmetric quiver is said to be of {\it finite type} if it has only finitely many indecomposable orthogonal (respectively symplectic) representations up to isomorphism.
\end{definition}


%Proposition 1.16
\begin{proposition}
\begin{enumerate}[\upshape (a)]
\item A symmetric quiver $(\Omega, \sigma)$ is of finite type if and only if the quiver $\Omega$ is of finite type.
\item If $(\Omega, \sigma)$ is an irreducible symmetric quiver, then there are two possibilities: either the quiver $\Omega$ is connected, or $\Omega$ has two connected components which are interchanged by $\sigma$
\item If $(\Omega, \sigma)$ is an irreducible symmetric quiver such that the quiver $\Omega$ has two connected components, then $\Omega$ is isomorphic to the disjoint union of two quivers $\Omega' = ({\mathcal I}', {\mathcal A}', h': {\mathcal A}' \rightarrow {\mathcal I}',  t': {\mathcal A}' \rightarrow {\mathcal I}')$ and $\Omega''= ({\mathcal I}'', {\mathcal A}'', t'': {\mathcal A}'' \rightarrow {\mathcal I}'',  h'': {\mathcal A}'' \rightarrow {\mathcal I}'')$ which  is the dual of $\Omega'$ obtained by reversing all the arrows of $\Omega'$. $\sigma$ is obtained by interchanging the vertices and arrows of $\Omega'$ with the vertices and arrows of $\Omega''$.  Moreover there is a correspondence between quiver representations of $\Omega'$ and orthogonal (respectively  symplectic) representations of the symmetric quiver $(\Omega, \sigma)$.
\item If $(\Omega, \sigma)$ is a symmetric quiver of finite type  such that the quiver $\Omega$ is connected, then $\Omega$ is a quiver of Dynkin type $A_n$.
\end{enumerate}
\end{proposition}
\begin{proof}
(a) is proved in theorem 3.1 in  \cite{DW2002}. (b) follows easily from the action of $\sigma$ of the sets of vertices and arrows.  (c) is proved in proposition 3.2 in  \cite{DW2002}. (d) is proved in proposition 3.3 in  \cite{DW2002}.
\end{proof}

