%proof prop 1.30
\begin{proof}
(a) In the orthogonal case, (i) follows easily by considering just the dimension vector. 

For (ii), we must consider the maps $\phi_{(-2 \rightarrow 0)}:V_{-2} \rightarrow V_0$ and $\phi_{(0 \rightarrow 2)}:V_{0} \rightarrow V_{2}$. We can pick bases $\{v_2\}$, $\{v_0\}$ and $\{v_{-2}\}$ of $V_2$,  $V_0$ and $V_{-2}$ respectively and we can assume that our choice is such that $\langle v_2, v_{-2}\rangle = \langle v_{-2}, v_{2}\rangle = 1$ and $\langle v_0, v_{0}\rangle = 1$ and $\langle v_2, v_{0}\rangle = \langle v_{0}, v_{2}\rangle = \langle v_{-2}, v_{0}\rangle = \langle v_{0}, v_{-2}\rangle  =   \langle v_{2}, v_{2}\rangle  =  \langle v_{-2}, v_{-2}\rangle = 0$. Write $\phi_{(-2\rightarrow 0)}(v_{-2}) = xv_0$ and $\phi_{(0\rightarrow 2)}(v_{0}) = yv_2$, where $x, y \in {\mathbf k}$. Because $(V, \phi, \langle\  , \  \rangle)$ is an orthogonal representation, we have
\[
\langle \phi_{-2\rightarrow 0}(v_{-2}), v_{0}\rangle + \langle v_{-2}, \phi_{0\rightarrow 2}(v_{0})\rangle = 0 \Rightarrow x + y = 0.
\]
If $x = 0$, then $y = 0$ and both $\phi_{(-2 \rightarrow 0)}:V_{-2} \rightarrow V_0$ and $\phi_{(0 \rightarrow 2)}:V_{0} \rightarrow V_{2}$ are $0$. But this is impossible because it contradicts the fact that 
$(V, \phi, \langle\ , \ \rangle)$ is indecomposable. 
So $x \ne 0$, $y \ne 0$ and $\phi_{(-2 \rightarrow 0)}:V_{-2} \rightarrow V_0$ and $\phi_{(0 \rightarrow 2)}:V_{0} \rightarrow V_{2}$ are $\ne 0$. From this observation, we get that  (ii) follows.

As for (iii), there are two possibilities: either
\[
\beta_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-a \leq i \leq a$;}\\ 0, &\text{otherwise;} \end{cases}
\quad \text{ and } \quad
\beta'_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-b \leq i \leq  b$;}\\ 0, &\text{otherwise;} \end{cases}
\]
or 
\[
\beta_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-a \leq i \leq b$;}\\ 0, &\text{otherwise;} \end{cases}
\quad \text{ and } \quad
\beta'_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-b \leq i \leq  a$;}\\ 0, &\text{otherwise.} \end{cases}
\]
The first of these possibilities has to be excluded. Otherwise $(V, \phi, \langle\ , \ \rangle)$ would be isomorphic by theorem~\ref{T:CaracterisationRepresentation} as an orthogonal representation to the direct sum of an indecomposable orthogonal representation with dimension $\beta = (\beta_i)_{i \in {\mathcal I}_+}$ and an indecomposable orthogonal representation with dimension $\beta' = (\beta'_i)_{i \in {\mathcal I}_+}$. But this means that $(V, \phi, \langle\ , \ \rangle)$  is not an indecomposable representation of the symmetric quiver $A_m^{odd}$. This prove (iii).

(b) In the symplectic case,  (i) and (ii) follow easily by considering just the dimension vectors. 

As for (iii), because $a < b$, there are two distinct possibilities: either
\[
\beta_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-a \leq i \leq a$;}\\ 0, &\text{otherwise;} \end{cases}
\quad \text{ and } \quad
\beta'_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-b \leq i \leq  b$;}\\ 0, &\text{otherwise;} \end{cases}
\]
or 
\[
\beta_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-a \leq i \leq b$;}\\ 0, &\text{otherwise;} \end{cases}
\quad \text{ and } \quad
\beta'_i = \begin{cases} 1, &\text{if $i \in {\mathcal I}$ and $-b \leq i \leq  a$;}\\ 0, &\text{otherwise.} \end{cases}
\]
The first possibility has to be excluded because $a < b$, the proposition~\ref{PropDecomposition} and the fact that $\sigma(\beta_i)_{i \in {\mathcal I}} = (\beta_i)_{i \in {\mathcal I}}$ and $\sigma(\beta'_i)_{i \in {\mathcal I}} = (\beta'_i)_{i \in {\mathcal I}}$. 
This proves the claim.
\end{proof}

%lemma 1.31
\begin{lemma}\label{L:DetThetaAOdd} 
Let $(V, \phi, \langle\ , \ \rangle)$ and $(V', \phi', \langle\ , \ \rangle')$ be two   isomorphic  orthogonal  representations of the symmetric quiver $A_m^{odd}$, where $V = V'$ as ${\mathcal I}$-graded vector space and let $\theta: V \rightarrow V'$ be an ${\mathcal I}$-graded isomorphism of orthogonal representations of the symmetric quiver $A_m^{odd}$.  
If $i \in {\mathcal I}$ is such that $V_i \ne \{0\}$ and consider  the induced isomorphism $\theta_i: V_i \rightarrow V'_i$, then $\det(\theta_{-i}) = \det(\theta_i)^{-1}$. If $V_0 \ne \{0\}$, $\theta_0$ is an orthogonal linear transformation of $V_0$ and $\det(\theta_0) = \pm1$. 
\end{lemma}
\begin{proof}
Because  we  have $\langle \theta_i(u), \theta_{\sigma(i)}(v)\rangle' = \langle u, v \rangle$ for all $u \in V_i$, $v \in V_{\sigma(i)}$ and $i \in {\mathcal I}$. A consequence of this is that $\det(\theta_{\sigma(i)}) = \det(\theta_{-i}) = \det(\theta_i)^{-1}$ for all $i \in {\mathcal I}$. Another consequence is that  $\langle \theta_0(u), \theta_0(v)\rangle' = \langle u, v \rangle$ for all $u, v \in V_0$ From this, we get that $\theta_0$ is an orthogonal linear transformation and $\det(\theta_0) = \pm 1$. 
\end{proof}

%definition 1.32
\begin{definition}
Let $(V, \phi, \langle\ , \ \rangle)$ and $(V', \phi', \langle\ , \ \rangle')$ be two   isomorphic  orthogonal  representations of the symmetric quiver $A_m^{odd}$, where $V = V'$ as ${\mathcal I}$-graded vector space. We say they are {\it isomorphic relative to the  special orthogonal group} if and only if $V_0 \ne \{0\}$ and there exists an ${\mathcal I}$-graded isomorphism $\theta: V \rightarrow V'$  as orthogonal representations of the symmetric quiver $A_m^{odd}$ such that $\det(\theta_0) = 1$. 
\end{definition}

%notation 1.33
\begin{notation}\label{N:EpsilonValue}
Denote by
\[
\epsilon = \begin{cases} \phantom{ - }1, &\text{ if we are in the orthogonal case;} \\ -1, &\text{ if we are in the symplectic case;} \end{cases}
\]
and, for an orthogonal (respectively symplectic) representation $(V, \phi, \langle\ , \ \rangle)$  of the symmetric quiver $(\Omega, \sigma)$, we will say that $(V, \phi, \langle\ , \ \rangle)$ is an {\it $\epsilon$-representation} when $\epsilon = 1$ (respectively $\epsilon = -1$). Note that with this notation,  we have for the bilinear form $\langle v, u \rangle = \epsilon \langle u, v \rangle$ for all $u, v \in V$.

\end{notation}

%section 2
\section{Jacobson-Morozov triple for  indecomposable representations}

%2.1
\subsection{}\label{SS:Iset}

Fix $m \in {\mathbb N}$ such that  $m \geq 1$,  $\epsilon \in \{1, -1\}$ as in notation~\ref{N:EpsilonValue}  and the symmetric quiver $(\Omega, \sigma)$ which  is either $A_m^{even}$ or $A_m^{odd}$. Thus  ${\mathcal I}$, as in \ref{SymmQuiver}, is 
\[
{\mathcal I} = \begin{cases} \{i \in {\mathbb Z} \mid i \equiv 1 \pmod 2, -2m < i < 2m\}, &\text{ in the case $A_m^{even}$;}\\ \\
\{i \in {\mathbb Z} \mid i \equiv 0 \pmod 2, -2m < i < 2m\}, &\text{ in the case $A_m^{odd}$;} \end{cases}
\]
and $\sigma:{\mathcal I} \rightarrow {\mathcal I}$ is $\sigma(i) = -i$ for all $i \in {\mathcal I}$.

The case where $\vert {\mathcal I} \vert = 1$ is easy to deal in our study. Thus from now on, we will always assume that $\vert {\mathcal I} \vert > 1$. 

Fix also the integer 
\[
\mu_{\max} = \begin{cases} 1, &\text{if  $\vert {\mathcal I}\vert \equiv 0 \pmod 2$ and $\epsilon = 1$;}\\ 0, &\text{if  $\vert {\mathcal I}\vert \equiv 0 \pmod 2$ and $\epsilon = -1$;}\\ 0, &\text{if $\vert {\mathcal I}\vert \equiv 1 \pmod 2$ and $\epsilon = 1$;}\\ 1, &\text{if  $\vert {\mathcal I}\vert \equiv 1 \pmod 2$ and $\epsilon = -1$.}\\
\end{cases}
\]


%definition 2.2
\begin{definition}\label{D:IBoxSet}
An {\it ${\mathcal I}$-diagram } is the Young diagram corresponding to the partition
\[
\vert{\mathcal I}\vert > (\vert{\mathcal I}\vert - 1) > \dots > 3 > 2 > 1
\]
where the $r^{th}$ part is $(\vert{\mathcal I}\vert - r + 1)$ for $r = 1, 2, \dots, \vert{\mathcal I}\vert$.

The rows are indexed by the elements of ${\mathcal I}$ in decreasing order from the first row to the last row and the columns are indexed by the elements of ${\mathcal I}$ in increasing order from the first column to the last column. Consequently we have a box at the intersection of the $i^{th}$ row and the $j^{th}$ column with $i, j \in {\mathcal I}$ if and only if $i \geq j$. 

The {\it principal diagonal} of the ${\mathcal I}$-diagram will correspond to the set of boxes on the row $i$ and the column $-i$ for $i \in \{i \in {\mathcal I} \mid i \geq 0\}$ and the {\it dimension diagonal} of the ${\mathcal I}$-diagram will correspond to the set of boxes on the row $i$ and the column $i$ for $i \in  {\mathcal I}$.

The ${\mathcal I}$-diagram come with a {\it box multiplicity function}
\[
\mu:\{(i, j) \in {\mathcal I} \times {\mathcal I} \mid i \geq j\} \rightarrow \{0, 1\}
\]
where 
\[
\mu(i, j) = \begin{cases} 0, &\text{if $i + j \ne 0$;}\\ \mu_{\max}, &\text{if $i + j = 0$.}\\
\end{cases}
\]


We define the set of {\it ${\mathcal I}$-boxes} of the ${\mathcal I}$-diagram to be the set
\[
{\mathbf B} = \{b(i, j, k) \mid i, j \in {\mathcal I}, i \geq j, 0 \leq k \leq \mu(i, j)\}.
\]
\end{definition}

%example 2.3
\begin{example} 
For the symmetric quiver $A_3^{even}$, then   ${\mathcal I} = \{5, 3, 1, -1, -3, -5\}$  and the  ${\mathcal I}$-diagram is 

\begin{center}
\ytableausetup{centertableaux}
\begin{ytableau}
\none & \none [-5] & \none [-3] & \none [-1] & \none [1] & \none [3] & \none [5]\\ \none [{\phantom -}5] & & &  &  &  &  \\ \none [{\phantom -}3] &  &  &  &  & \\  \none [{\phantom -}1] &  &  & &  \\ \none [-1] & & & \\ \none [-3] & & \\ \none [-5] & \\
\end{ytableau}
\end{center}
where the indices for the rows and columns are inscribed.  

For the ${\mathcal I}$-boxes, the boxes in the picture of the ${\mathcal I}$-diagram are counted once if $i + j  \ne 0$ (i.e. not on the principal diagonal)  and counted $\mu_{max} + 1$ times if $i + j = 0$ (i.e. on the principal diagonal), that is once in the symplectic case and twice in the orthogonal case.
\end{example}


%example 2.4
\begin{example} 
For the symmetric quiver $A_3^{odd}$, then  ${\mathcal I} = \{4, 2, 0, -2, -4\}$  and the  ${\mathcal I}$-diagram is 

\begin{center}
\ytableausetup{centertableaux}
\begin{ytableau}
\none & \none [-4] & \none [-2] & \none [0] & \none [2] & \none [4]  \\ \none [{\phantom -}4] & & &  &  &   \\ \none [{\phantom -}2] &  &  &  &  \\  \none [{\phantom -}0] &  &  &  \\ \none [-2] & & \\ \none [-4] &  \\ 
\end{ytableau}
\end{center}
where the indices for the rows and columns are inscribed.

For the ${\mathcal I}$-boxes, the boxes in the picture of the ${\mathcal I}$-diagram are counted once if $i + j  \ne 0$ (i.e. not on the principal diagonal)  and counted $\mu_{max} + 1$ times if $i + j = 0$ (i.e. on the principal diagonal), that is once in the orthogonal case and twice in the symplectic case.

\end{example}

%notation 2.5
\begin{notation}\label{N:TauDefinition}
Let $\tau$  denotes  the involution $\tau:{\mathbf B} \rightarrow {\mathbf B}$ on the set ${\mathbf B}$ of ${\mathcal I}$-boxes given by 
\[
\tau(b(i, j, k)) = \begin{cases} b(-j, -i, k), &\text{ if $i + j \ne 0$;}\\ b(i, j, k), &\text{ if $i + j = 0$ and $\mu_{max} = 0$;} \\ b(i, j, 1 - k), &\text{ if $i + j = 0$ and $\mu_{max} = 1$} \end{cases}
\]
for $i, j \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$. 

Because $\vert{\mathcal I}\vert > 1$, then $\tau \ne Id_{\mathcal B}$.  Denote by $\langle \tau \rangle$: the group generated by $\tau$ and,  by our hypothesis, $\langle \tau \rangle$ is isomorphic to ${\mathbb Z}/2{\mathbb Z}$. 
\end{notation}

%remark 2.6
\begin{remark}\label{R:CardinalityIndecomposable}
We can count the number of $\langle \tau \rangle$-orbits in ${\mathbf B}$. If we are in the case of $A_m^{even}$, then $\vert {\mathcal I}\vert = 2m$ is even,  it is easy to see that this number  of $\langle \tau \rangle$-orbits is 
\[
2m + 2(m - 1) + \dots + 4 + 2 = 2\left( \frac{m(m + 1)}{2}\right) = m(m + 1); 
\]
while if we are in the case of $A_m^{odd}$, then $\vert {\mathcal I} \vert = 2m - 1$ is odd, it is also easy to see that this number is
\[
(2m - 1) + (2m - 3) + \dots + 3 + 1 = 2\left(\frac{m(m + 1)}{2}\right) - m = m^2.
\]
We see that this number of $\langle \tau \rangle$-orbits in ${\mathbf B}$ is the same as the number of isomorphism classes  of indecomposable orthogonal or symplectic representations. 
\end{remark}

%2.7
\subsection{} \label{SS:JMTriple}
In this section,  we will construct for each  $\langle \tau \rangle$-orbit ${\mathcal O}$ in ${\mathbf B}$:
\begin{itemize}
\item a ${\mathcal I}$-graded vector space $V({\mathcal O}) = \oplus_{i \in {\mathcal I}} V_i({\mathcal O})$ over ${\mathbf k}$ with an ${\mathcal I}$-graded basis $B_{\mathcal O} = \coprod_{i \in {\mathcal I}} B_i$;
\item a non-degenerate   $\epsilon$-bilinear form $\langle\  , \  \rangle_{\mathcal O}$ on  $V({\mathcal O})$  such that the restriction of $\langle\  , \  \rangle_{\mathcal O}$ to $V_i({\mathcal O}) \times V_{j}({\mathcal O})$ is $0$ if $j \ne \sigma(i)$ for all $i, j \in {\mathcal I}$;
\item  three ${\mathcal I}$-graded  linear transformations  $E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$,  $H_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$ and $F_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$ such that 
\begin{itemize}
\item $E_{\mathcal O}$ is of degree 2, $H_{\mathcal O}$ is of degree 0 and $F_{\mathcal O}$ is of degree -2;
\item $\langle Xu, v\rangle_{\mathcal O} + \langle u, Xv\rangle_{\mathcal O} = 0$ for all $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$;
\item $[H_{\mathcal O}, E_{\mathcal O}] = 2E_{\mathcal O}$, $[H_{\mathcal O}, F_{\mathcal O}] = -2F_{\mathcal O}$ and $[E_{\mathcal O}, F_{\mathcal O}] = H_{\mathcal O}$. In other words,  $(E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O})$ is an ${\mathcal I}$-graded Jacobson-Morozov triple for the Lie algebra corresponding to $(V({\mathcal O}), \langle\   ,  \   \rangle_{\mathcal O})$;
\end{itemize}
\item the ${\mathcal I}$-graded linear transformation $\phi_{\mathcal O}: V({\mathcal O}) \rightarrow V({\mathcal O})$ given by 
\[
\phi_{{\mathcal O}, i} = {E_{\mathcal O}}\vert_{V_i({\mathcal O})}: V_{i}({\mathcal O}) \rightarrow V_{i + 2}({\mathcal O}) \quad \text{for all $i \in {\mathcal I}$  such that $(i + 2) \in {\mathcal I}$},
\]
is  such that $(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle)$ is an $\epsilon$-representation.
\end{itemize}
Moreover $\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle) \mid \text{ ${\mathcal O}$  belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}$   is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-representations of $(\Omega, \sigma)$.

%definition 2.8
\begin{definition}
An ${\mathcal I}$-box $b = b(i, j, k) \in {\mathbf B}$ with $i, j \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$,  is said to be {\it strictly above the principal diagonal} (respectively {\it on the principal diagonal}, {\it strictly below the principal diagonal} ) if $i + j > 0$ (respectively $i + j = 0$, $i + j < 0$). 
\end{definition}

%definition 2.9
\begin{definition}
Given an ${\mathcal I}$-box $b = b(i, j, k) \in {\mathbf B}$, the {\it support of $b$} denoted $Supp(b)$ is defined to be the subset $Supp(b) = \{i' \in {\mathcal I} \mid j \leq i' \leq i\}$ of ${\mathcal I}$. 
\end{definition}


%lemma 2.10
\begin{lemma}\label{L:TauBox}
Let $b = b(i, j, k) \in {\mathbf B}$ be an ${\mathcal I}$-box with $i, j \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$.
\begin{enumerate}[\upshape (a)] 
\item $Supp(\tau(b)) = \sigma(Supp(b))$.
\item If $b$ is strictly above (respectively below) the principal diagonal, then $\tau(b)$ is strictly below (respectively above) the principal diagonal.
\item If $b$ is not on the principal diagonal, then $\tau(b) \ne b$.
\item If $b$ is on the principal diagonal and $\tau(b) \ne b$, then $\mu_{\max} = 1$ and $\tau(b) = b(i, j, 1 - k)$.
\item If  $b$ is on the principal diagonal , $\tau(b) = b$ and $\vert {\mathcal I}\vert$ is even, then  $\mu_{\max} = 0$,  $0 \not\in {\mathcal I}$ and $\epsilon = -1$.
\item If  $b$ is on the principal diagonal , $\tau(b) = b$ and $\vert {\mathcal I}\vert$ is odd, then $\mu_{\max} = 0$, $0 \in {\mathcal I}$ and $\epsilon = 1$.
\end{enumerate}
\end{lemma}
\begin{proof}
This lemma follows easily from the definitions.
\end{proof}

%notation 2.11
\begin{notation}\label{N:BasisVOrbit}
For the ${\mathcal I}$-box $b \in {\mathbf B}$, $V(b)$ denotes the ${\mathcal I}$-graded  finite dimensional ${\bf k}$-vector space 
\[
V(b) = \bigoplus_{i \in Supp(b)} V_i(b)
\]
with the ${\mathcal I}$-graded basis ${\mathcal B}_b = \{v_i(b) \mid i \in Supp(b)\}$ such that  $v_i(b) \in V_i(b)$.  For the $\langle \tau \rangle$-orbit ${\mathcal O}$, $V({\mathcal O})$ denotes  the ${\mathcal I}$-graded  finite dimensional ${\bf k}$-vector space 
\[
V({\mathcal O}) = \bigoplus_{b \in {\mathcal O}} V(b) 
\]
with  the ${\mathcal I}$-graded basis ${\mathcal B}_{\mathcal O} =\coprod_{b \in {\mathcal O}} {\mathcal B}_b$.  

We will denote the $i$-component of $V({\mathcal O})$ by 
\[
V_i({\mathcal O}) =  \bigoplus_{\substack{b \in {\mathcal O}\\ i \in Supp(b)}} V_i(b). 
\]

Consider the unique bilinear form $\langle\ , \  \rangle_{\mathcal O}: V({\mathcal O}) \times V({\mathcal O})  \rightarrow {\mathbf k}$ such that, for $b = b(i_1, j_1, k_1)  \in {\mathcal O}, b' = b(i_2,  j_2, k_2) \in {\mathcal O}$, $i \in Supp(b)$ and $i' \in Supp(b')$, we have

\[
\langle v_i(b), v_{i'}(b')\rangle_{\mathcal O} 
= \begin{cases} 1, &\text{if $b' = \tau(b)$, $i > 0$ and $i + i' = 0$; } \\
\epsilon, &\text{if $b' = \tau(b)$, $i < 0$ and $i + i' = 0$; }\\ 
1, &\text{if $b$ is above  the principal diagonal, $b' = \tau(b)$}\\  &\text{and $i = i' = 0$; } \\ 
\epsilon, &\text{if $b$ is below  the principal diagonal, $b' = \tau(b)$}\\  &\text{and $i = i' = 0$; } \\ 
\epsilon^{k_1}, &\text{if $b$ is on the principal diagonal, $b \ne \tau(b)$, }\\  &\text{$b' = \tau(b)$ and $i = i' = 0$; }\\ 
1, &\text{if $b$ is on the principal diagonal, $b = \tau(b) = b'$}\\  &\text{and $i = i' = 0$; }\\ 
0, &\text{otherwise.}
\end{cases}
\]
\end{notation}

%lemma 2.12
\begin{lemma}
$\langle \  , \  \rangle_{\mathcal O}$ is a non-degenerate $\epsilon$-bilinear form on $V({\mathcal O})$  such that the restriction of $\langle\  , \  \rangle_{\mathcal O}$ to $V_i({\mathcal O}) \times V_j({\mathcal O})$ is $0$ if $j \ne \sigma(i)$ for all $i, j \in {\mathcal I}$. 
\end{lemma}
%proof
\begin{proof}
To show that the bilinear form $\langle\ , \  \rangle_{\mathcal O}$ is an $\epsilon$-bilinear form, it is enough to show it on the basis ${\mathcal B}_{\mathcal O}$ of $V({\mathcal O})$. We will consider separately the cases when  $\vert {\mathcal I}\vert$ is even and when it is odd.  

First assume $\vert {\mathcal I} \vert$ is even then $0 \not \in {\mathcal I}$. Assume that the orbit ${\mathcal O}$ has two elements: $\{b, \tau(b)\}$ with $b \ne \tau(b)$. If $b$ is not on the principal diagonal, then $\tau(b)$ is also not on the principal diagonal. Note that $\langle v_i(b), v_j(\tau(b))\rangle_{\mathcal O}$ and $\langle v_i(\tau(b)), v_j(b)\rangle_{\mathcal O}$ are $\ne 0$ if and only if $i + j = 0$. Thus it is enough to consider
\[
\langle v_i(b), v_{-i}(\tau(b))\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i > 0$;} \\ \epsilon, &\text{if $i < 0$;} \end{cases} \quad \text{ and } \quad \langle v_{-i}(\tau(b)), v_{i}(b)\rangle_{\mathcal O} = \begin{cases} \epsilon, &\text{if $i > 0$;} \\ 1, &\text{if $i < 0$.} \end{cases}
\] 
A similar argument works if $b$ is on the principal diagonal  and  $\tau(b) \ne b$. This is left to the reader.  Assume now that the orbit ${\mathcal O}$ has exactly one element: $\{b\}$ with $b = \tau(b)$. This happens only when $b$ is on the principal diagonal. Note that in this case $\langle v_i(b), v_j(b)\rangle_{\mathcal O}$ is  $\ne 0$ if and only if $i + j = 0$. Thus it is enough to consider
\[
\langle v_i(b), v_{-i}(b)\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i > 0$;} \\ \epsilon, &\text{if $i < 0$;} \end{cases} \quad \text{ and } \quad \langle v_{-i}(b), v_{i}(b)\rangle_{\mathcal O} = \begin{cases} \epsilon, &\text{if $i > 0$;} \\ 1, &\text{if $i < 0$.} \end{cases}
\] 
So if $\vert {\mathcal I} \vert$ is even, then we have $\langle u, v \rangle_{\mathcal O} = \epsilon \langle v, u \rangle_{\mathcal O}$ for all $u, v \in {\mathcal B}_{\mathcal O}$. 

Secondly assume $\vert {\mathcal I} \vert$ is odd,  then $0 \in {\mathcal I}$. Assume that the orbit ${\mathcal O}$ has two elements: $\{b, \tau(b)\}$ with $b \ne \tau(b)$. If $b$ is not on the principal diagonal, then $\tau(b)$ is also not on the principal diagonal. More precisely, if $b$ is above (respectively below) the principal diagonal, then $\tau(b)$ is below (respectively above) the principal diagonal. Note that $\langle v_i(b), v_j(\tau(b))\rangle_{\mathcal O}$ and $\langle v_i(\tau(b)), v_j(b)\rangle_{\mathcal O}$ are $\ne 0$ if and only if $i + j = 0$.  Assume that $b$ is above the principal diagonal, then 
\[
\langle v_i(b), v_{-i}(\tau(b))\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i \geq 0$;} \\ \epsilon, &\text{if $i < 0$;} \end{cases} \quad \text{ and } \quad \langle v_{-i}(\tau(b)), v_{i}(b)\rangle_{\mathcal O} = \begin{cases} \epsilon, &\text{if $i \geq 0$;} \\ 1, &\text{if $i < 0$.} \end{cases}
\] 
A similar argument works if $b$ is below the principal diagonal.  Assume now that $b$ is on the principal diagonal and $\tau(b) \ne b$, then,  as seen in lemma~\ref{L:TauBox} (d), $\mu_{\max} = 1$ and if $b = b(i_1, j_1, k_1)$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k_1 \leq \mu(i_1, j_1)$, then $\tau(b) = b(i_1, j_1, 1 - k_1)$. Note that $\langle v_i(b), v_j(\tau(b))\rangle_{\mathcal O}$ and $\langle v_i(\tau(b)), v_j(b)\rangle_{\mathcal O}$ are $\ne 0$ if and only if $i + j = 0$. Thus it is enough to consider
\[
\langle v_i(b), v_{-i}(\tau(b))\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i > 0$;} \\ \epsilon^{k_1}, &\text{if $i = 0$;} \\ \epsilon, &\text{if $i < 0$;} \end{cases} \  \text{ and } \  \langle v_{-i}(\tau(b)), v_{i}(b)\rangle_{\mathcal O} = \begin{cases} \epsilon, &\text{if $i > 0$;} \\ \epsilon^{1 - k_1}, &\text{if $i = 0$;}\\ 1, &\text{if $i < 0$.} \end{cases}
\] 
Assume now that the orbit ${\mathcal O}$ has exactly one element: $\{b\}$ with $b = \tau(b)$. This  happens only when $b$ is on the principal diagonal. By lemma~\ref{L:TauBox} (f), $\epsilon = 1$. Note that in this case $\langle v_i(b), v_j(b)\rangle_{\mathcal O}$ is  $\ne 0$ if and only if $i + j = 0$.  Thus we consider 
\[
\langle v_i(b), v_{-i}(b)\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i \geq 0$;} \\ 1, &\text{if $i < 0$;} \end{cases} \quad \text{ and } \quad \langle v_{-i}(b), v_{i}(b)\rangle_{\mathcal O} = \begin{cases} 1, &\text{if $i \geq 0$;} \\ 1, &\text{if $i < 0$.} \end{cases}
\] 
So if $\vert {\mathcal I} \vert$ is odd, then we have $\langle u, v \rangle_{\mathcal O} = \epsilon \langle v, u \rangle_{\mathcal O}$ for all $u, v \in {\mathcal B}_{\mathcal O}$. 


To show that $\langle\  ,\   \rangle_{\mathcal O}$ is non-degenerate, consider $v \in V({\mathcal O})$ such that $\langle v, v' \rangle_{\mathcal O} = 0$ for all $v' \in V({\mathcal O})$. Write $v = \sum_{b \in {\mathcal O}} \sum_{i \in Supp(b)} c_{i, b} v_i(b)$ with $c_{i, b} \in {\mathbf k}$.  For any $b' \in {\mathcal O}$ and $i' \in Supp(b')$, we have $\tau(b') \in {\mathcal O}$, $-i' = \sigma(i') \in Supp(\tau(b'))$ by lemma~\ref{L:TauBox} (a) and $v_{-i'}(\tau(b')) \in V({\mathcal O})$.  We get that 
\[
\begin{aligned}
0 &= \langle v, v_{-i'}(\tau(b'))\rangle_{\mathcal O} =   \sum_{b \in {\mathcal O}} \sum_{i \in Supp(b)} c_{i, b} \langle v_i(b), v_{-i'}(\tau(b'))\rangle_{\mathcal O}\\  &= c_{i', b'} \langle v_{i'}(b'), v_{-i'}(\tau(b'))\rangle_{\mathcal O}
\end{aligned}
\]
and $ \langle v_{i'}(b'), v_{-i'}(\tau(b'))\rangle_{\mathcal O} \ne 0$, from our definition of $\langle\  , \  \rangle_{\mathcal O}$. Thus  we get that $c_{i', b'} = 0$ for all $b' \in {\mathcal O}$ and $i' \in Supp(b')$ and $v = 0$. So $\langle\  , \  \rangle_{\mathcal O}$ is non-degenerate. 

Let $v \in V_i({\mathcal O})$ and $v' \in V_{i'}({\mathcal O})$ with $i' \ne \sigma(i) = -i$.  Write 
\[
v = \sum_{\substack{b \in {\mathcal O}  \\ i \in Supp(b)}} c_{i, b} v_i(b) \quad \text{ and } \quad v' = \sum_{\substack{b' \in {\mathcal O}, \\ i' \in Supp(b')}} c_{i', b'} v_{i'}(b').
\]
Then 
\[
\langle v, v' \rangle_{\mathcal O} = \sum_{\substack{b, b' \in {\mathcal O}\\ i \in Supp(b)\\ i' \in Supp(b')}} c_{i, b} c_{i', b'} \langle v_i(b), v_{i'}(b')\rangle_{\mathcal O} = 0 
\]
from our definition of $\langle\  , \  \rangle_{\mathcal O}$ and because $i' \ne -i$. 
\end{proof}


%definition 2.13
\begin{definition}
For the ${\mathcal I}$-box $b = b(i, j, k) \in  {\mathbf B}$ with $i, j, \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$  and for $i' \in Supp(b)$, then we define
\[
h_{i'}(b) = \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq i'\}  - \#\{i'' \in {\mathcal I} \mid i' \leq i'' \leq i\}
\]
and 
\[
f_{i'}(b) = \#\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   i' \leq i'' \leq i,\    j < j'' \leq i'\}.
\]
\end{definition}

%lemma 2.14
\begin{lemma}\label{L:RelationCoefficientsHandF}
Let $b \in  {\mathbf B}$ be the ${\mathcal I}$-box $b = b(i, j, k)$  with $i, j, \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$  and  let $i' \in Supp(b)$. Then we have
\begin{enumerate}[\upshape (a)] 
\item $h_{-i'}(\tau(b)) = - h_{i'}(b)$;
\item If $i' \ne \min(Supp(b))$, then $(-i' + 2) \in Supp(\tau(b))$, $(-i' + 2) \ne \min(Supp(\tau(b))$ and $f_{-i' + 2}(\tau(b)) = f_{i'}(b)$;
\item If $i' \ne \max(Supp(b))$, then $(i' + 2) \in Supp(b)$ and $(h_{i' + 2}(b) - h_{i'}(b)) = 2$. 
\item If $i' \ne \min(Supp(b))$, then $(i' - 2) \in Supp(b)$ and $(h_{i' - 2}(b) - h_{i'}(b)) = -2$. 
\item If $i' = \min(Supp(b)) < \max(Supp(b))$, then $(i' - 2) \not\in Supp(b)$, $(i' + 2) \in Supp(b)$,  $f_{i'}(b) = 0$ and $f_{i' + 2}(b) = -h_{i'}(b)$;
\item If $\min(Supp(b)) < i' =  \max(Supp(b))$, then $(i' - 2) \in Supp(b)$, $(i' + 2) \not\in Supp(b)$ and $f_{i'}(b) = h_{i'}(b)$;
\item If $\min(Supp(b)) < i' <  \max(Supp(b))$, then $(i' - 2), (i' + 2)  \in Supp(b)$ and $(f_{i'}(b) - f_{i' + 2}(b)) = h_{i'}(b)$.
\end{enumerate}
\end{lemma}
\begin{proof}
(a) We have that $\tau(b) = b(-j, -i, k')$ where $k' \in \{k, (1 - k)\}$. Note also that $-i' \in Supp(\tau(b))$.  We have 
\[
h_{i'}(b) = \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq i'\}  - \#\{i'' \in {\mathcal I} \mid i' \leq i'' \leq i\}
\]
and 
\[
\begin{aligned}
h_{-i'}(\tau(b)) &= \#\{j'' \in {\mathcal I} \mid -i \leq j'' \leq -i'\}  - \#\{i'' \in {\mathcal I} \mid -i' \leq i'' \leq -j\}\\
&=  \#\{j'' \in {\mathcal I} \mid i \geq -j'' \geq i'\}  - \#\{i'' \in {\mathcal I} \mid i' \geq -i'' \geq j\} = -h_{i'}(b)
\end{aligned}
\]


(b) So we have $j < i' \leq i$, because $i' \ne \min(Supp(b))$. Thus $(-j + 2) > (-i' + 2) \geq (-i + 2)$. Note that $Supp(\tau(b)) = \{i'' \in {\mathcal I} \mid -j \geq i'' \geq -i\}$. Clearly $(-i' + 2) \in Supp(\tau(b))$, $(-i' + 2) \ne \min(Supp(\tau(b))$.  Now we have 
that 
\[
f_{i'}(b) = \#\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   i' \leq i'' \leq i,\    j < j'' \leq i'\}
\]
and $f_{-i' + 2}(\tau(b))$ is equal to 
\[
\begin{aligned}
 &\#\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\  (- i' + 2) \leq i'' \leq -j,\    -i < j'' \leq (-i' + 2)\}\\
 &=\#\left\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \left \vert  \begin{aligned} &(- j'' + 2) \leq (-i'' + 2),\   i'  \geq (-i'' + 2) > j,\\   & \quad i \geq (- j'' + 2)  \geq i' \end{aligned}\right. \right\}\\
 &= f_{i'}(b).
 \end{aligned}
\]

(c) Clearly $(i' + 2) \in Supp(b)$. Now we have
\[
\begin{aligned}
h_{i' + 2}(b) - h_{i'}(b) &= (\#\{j'' \in {\mathcal I} \mid j \leq j'' \leq (i' + 2)\}  - \#\{i'' \in {\mathcal I} \mid (i' + 2) \leq i'' \leq i\})\\ &\quad - (\#\{j'' \in {\mathcal I} \mid j \leq j'' \leq i'\}  - \#\{i'' \in {\mathcal I} \mid i' \leq i'' \leq i\})\\ &= 2.
\end{aligned}
\]

(d) The proof is similar to the proof of $(c)$ and is left to the reader.

(e) If $i' = \min(Supp(b)) < \max(Supp(b))$, then clearly $i' = j$, $(i' - 2) \not \in Supp(b)$, $(i' + 2) \in Supp(b)$  and 
\[
 \{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   j \leq i'' \leq i,\    j < j'' \leq j\} = \emptyset. 
\]
So 
\[
f_{i'}(b) = \#\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   j \leq i'' \leq i,\    j < j'' \leq j\} = 0.
\]

If we now consider
\[
\begin{aligned}
f_{i' + 2}(b) &= \{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   (i' + 2) \leq i'' \leq i,\    j < j'' \leq (i' + 2)\}\\
&=  \{ (i'', (i' + 2)) \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   (i' + 2) \leq i'' \leq i\} = - h_{i'}(b),
\end{aligned}
\]
because 
\[
\begin{aligned}
h_{i'}(b) &= \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq  i'\}  - \#\{i'' \in {\mathcal I} \mid i' \leq i'' \leq i\}\\ 
&=  - \#\{i'' \in {\mathcal I} \mid i'< i'' \leq i\}.
\end{aligned}
\]

(f)  If $\min(Supp(b)) < i' =  \max(Supp(b))$, then clearly $i' = i$, $(i' - 2) \in Supp(b)$, $(i' + 2)\not  \in Supp(b)$  and 
\[
\begin{aligned}
f_{i'}(b) &= \#\{ (i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'',\   i' \leq i'' \leq i,\    j < j'' \leq i'\}\\
&= \#\{ (i, j'') \in {\mathcal I} \times {\mathcal I} \mid   j < j'' \leq i'\} = h_{i'}(b).
\end{aligned}
\]

(g) If $\min(Supp(b)) < i' <  \max(Supp(b))$, then clearly  $(i' - 2), (i' + 2) \in Supp(b)$  and 
\[
\begin{aligned}
f_{i'}(b) - f_{i' + 2}(b) &= \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'', i' \leq i'' \leq i,\   j < j'' \leq i'\}\\  & - \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'', (i' + 2) \leq i'' \leq i, j < j'' \leq (i' + 2)\} \\ &= \#\{(i', j'') \in {\mathcal I} \times {\mathcal I} \mid \   j < j'' \leq i'\} \\ &\quad +  \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'', (i' + 2) \leq i'' \leq i, j < j'' \leq i'\}\\ &\quad - \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I} \mid i'' \geq j'', (i' + 2) \leq i'' \leq i, j < j'' \leq i'\}\\ &\quad - \#\{(i'', (i' + 2)) \in {\mathcal I} \times {\mathcal I} \mid (i' + 2) \leq i'' \leq i\}\\ &= \#\{(i', j'') \in {\mathcal I} \times {\mathcal I} \mid  j < j'' \leq i'\} \\ & \quad -\#\{(i'', (i' + 2)) \in {\mathcal I} \times {\mathcal I} \mid  (i' + 2) \leq i'' \leq i\} \\&= \#\{(i', j'') \in {\mathcal I} \times {\mathcal I} \mid  j \leq j'' \leq i'\} \\ & \quad -\#\{(i'', (i' + 2)) \in {\mathcal I} \times {\mathcal I} \mid i' \leq i'' \leq i\}
\\& = h_{i'}(b).
\end{aligned}
\]


\end{proof}


%2.15
\subsection{}\label{SS:EHFDefinition}
To construct the Jacobson-Morozov triple $(E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O})$ as in \ref{SS:JMTriple}, we will need to consider separately the two cases:  when $\vert {\mathcal I} \vert$ is even and when  $\vert {\mathcal I} \vert$ is odd.

%Even Case
{\bf Even case:} $\vert {\mathcal I} \vert$ is even; more precisely the symmetric quiver $(\Omega, \sigma)$ is $A_m^{even}$ and ${\mathcal I} =  \{i \in {\mathbb Z} \mid i \equiv 1 \pmod 2, -2m < i < 2m\}$.   We will also have to distinguish two situations for our  $\langle \tau\rangle$-orbit ${\mathcal O}$. If  $b$ is an ${\mathcal I}$-box in ${\mathcal O}$ then either $Supp(b) \cap Supp(\tau(b)) = \emptyset$ or $Supp(b) \cap Supp(\tau(b)) \ne \emptyset$. This condition of being empty or not empty is independant of the choice of the ${\mathcal I}$-box $b$ in ${\mathcal O}$. 

If $Supp(b) \cap Supp(\tau(b)) = \emptyset$, then we will say that the orbit ${\mathcal O}$ has {\it no overlapping ${\mathcal I}$-box supports}; while if $Supp(b) \cap Supp(\tau(b)) \ne \emptyset$, then we will say that the orbit ${\mathcal O}$ has {\it overlapping ${\mathcal I}$-box supports} 

Note that   the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports  if and only if $\{1, -1\} \subset Supp(b) \cap Supp(\tau(b))$. One direction is obvious. If $b = b(i, j, k)$ with $i, j, \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$, then $Supp(b) = \{i' \in {\mathcal I} \mid i \geq i' \geq j\}$ and $Supp(\tau(b)) = \{i' \in {\mathcal I} \mid -j \geq i' \geq -i\}$.   If $Supp(b) \cap Supp(\tau(b)) \ne \emptyset$, say $i' \in Supp(b) \cap Supp(\tau(b))$, then $ i \geq i' \geq j$ and $ i \geq -i' \geq j$. From which,  we get that $\{1, -1\} \subset Supp(b)$.  Similarly we get that $\{1, -1\} \subset Supp(\tau(b))$. From this, we get also that $\max(Supp(b)) \geq 1$ and $\min(Supp(b)) \leq -1$ when  the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports. 

We can now define the ${\mathcal I}$-graded linear transformations 
\[
E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}), \quad   H_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}) \quad  \text{ and } \quad F_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}).
\] 

If the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then for $b \in {\mathcal O}$ and $i \in Supp(b)$, we define
\[
E_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i < 0$;} \end{cases}
\]

\[
H_{\mathcal O}(v_i(b)) = h_i(b) v_i(b)
\]

and 

\[
F_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \min(Supp(b))$;}\\ {\phantom -} f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i > 0$;}\\  -f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i < 0$.} \end{cases}
\]

If the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports, then for $b = b(i_1, j_1, k_1) \in {\mathcal O}$ and $i \in Supp(b)$, we define
\[
E_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i \geq 1$;}\\  -v_{i + 2}(b), &\text{ if  $i < -1$;}\\ {\phantom -} v_1(b), &\text{ if  $i = -1$ and $b$ is below  the principal diagonal;}\\ - \epsilon v_1(b), &\text{ if $i = -1$ and $b$ is above  the principal diagonal;}\\  (- \epsilon)^{k_1} v_1(b), &\text{ if $i = -1$ and $b$ is on  the principal diagonal;}
\end{cases}
\]

\[
H_{\mathcal O}(v_i(b)) = h_i(b) v_i(b)
\]

and

\[
F_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \min(Supp(b))$;}\\ {\phantom -} f_i(b)v_{i - 2}(b), &\text{ if $i > 1$;}\\  -f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i \leq -1$.}\\ {\phantom -} f_1(b)v_{-1}(b), &\text{ if  $i = 1$ and $b$ is below  the principal diagonal;} \\ -\epsilon f_1(b)v_{-1}(b), &\text{ if  $i = 1$ and $b$ is above  the principal diagonal;}\\  (- \epsilon)^{k_1} f_1(b)v_{-1}(b), &\text{ if  $i = 1$ and $b$ is on the principal diagonal;}  \end{cases}
\]

%Odd case
{\bf Odd case:} $\vert {\mathcal I} \vert$ is odd, more precisely the symmetric quiver $(\Omega, \sigma)$ is $A_m^{odd}$ and ${\mathcal I} =  \{i \in {\mathbb Z} \mid i \equiv 0 \pmod 2, -2m  <  i < 2m\}$. We will also have to distinguish two situations for our  $\langle \tau\rangle$-orbit ${\mathcal O}$. If  $b$ is an ${\mathcal I}$-box in ${\mathcal O}$ then either $Supp(b) \cap Supp(\tau(b)) = \emptyset$ or $Supp(b) \cap Supp(\tau(b)) \ne \emptyset$. This condition of being empty or not empty is independant of the choice of the ${\mathcal I}$-box $b$ in ${\mathcal O}$.  

If $Supp(b) \cap Supp(\tau(b)) = \emptyset$, then we will say that the orbit ${\mathcal O}$ has {\it no overlapping ${\mathcal I}$-box supports} and if $Supp(b) \cap Supp(\tau(b)) \ne \emptyset$, then we will say that the orbit ${\mathcal O}$ has {\it overlapping ${\mathcal I}$-box supports} 

Note that   the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports  if and only if $0 \in Supp(b)$. If $0 \in Supp(b)$, then $\sigma(0) = 0 \in Supp(\tau(b))$ and  one direction of the equivalence follows. If $b = b(i, j, k)$ with $i, j, \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$, then $Supp(b) = \{i' \in {\mathcal I} \mid i \geq i' \geq j\}$ and $Supp(\tau(b)) = \{i' \in {\mathcal I} \mid -j \geq i' \geq -i\}$.   If  $i' \in Supp(b) \cap Supp(\tau(b))$, then $ i \geq i' \geq j$ and $ i \geq -i' \geq j$. From which,  we get that $0 \in Supp(b)$, because the elements of ${\mathcal I}$ consists of even integers.  From this, we also get  that $\max(Supp(b)) \geq 0$ and $\min(Supp(b)) \leq 0$, when  the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports. 

If the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then for $b \in {\mathcal O}$ and $i \in Supp(b)$, we define
\[
E_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i < 0$;} \end{cases}
\]

\[
H_{\mathcal O}(v_i(b)) = h_i(b) v_i(b)
\]

and 

\[
F_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \min(Supp(b))$;}\\ {\phantom -} f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i > 0$;}\\  -f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i < 0$.} \end{cases}
\]

If the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports, then for $b = b(i_1, j_1, k_1) \in {\mathcal O}$ and $i \in Supp(b)$, we define
\[
E_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}(b), &\text{if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}(b), &\text{if  $i < 0$;}\\   {\phantom -} \epsilon v_2(b), &\text{if $i = 0$, $ \max(Supp(b)) > 0$ and $b$ is below the}\\ &\text{principal diagonal;}\\ {\phantom -}  v_2(b), &\text{if $i = 0$, $ \max(Supp(b)) > 0$ and $b$ is above the}\\ &\text{principal diagonal;} \\ {\phantom -} \epsilon^{k_1}v_{2}(b), &\text{if $i = 0$, $ \max(Supp(b)) > 0$ and $b$ is on the principal}\\&\text{diagonal;}  \end{cases}
\]

\[
H_{\mathcal O}(v_i(b)) = h_i(b) v_i(b)
\]

and 

\[
F_{\mathcal O}(v_i(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \min(Supp(b))$;}\\ {\phantom -} f_i(b)v_{i - 2}(b), &\text{ if  $i > 2$;}\\  -f_i(b)v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i \leq 0$.}\\  {\phantom -}\epsilon  f_2(b)v_{0}(b), &\text{ if $i = 2$ and and $b$ is below the principal diagonal;}\\ {\phantom -} f_2(b)v_{0}(b), &\text{ if $i = 2$ and and $b$ is above the principal diagonal;}\\ {\phantom -} \epsilon^{k_1} f_2(b)v_{0}(b), &\text{ if $i = 2$ and and $b$ is on the principal diagonal;} \end{cases}
\]


%proposition 2.16
\begin{proposition}\label{P:JMTripleProof}
 With the above definition, we have that the three ${\mathcal I}$-graded  linear transformations  
 \[
 E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}), \quad  H_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}) \quad \text{ and } \quad F_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})
 \]
are such that 
\begin{itemize}
\item $E_{\mathcal O}$ is of degree $2$, $H_{\mathcal O}$ is of degree $0$ and $F_{\mathcal O}$ is of degree $-2$;
\item $\langle Xu, v\rangle_{\mathcal O} + \langle u, Xv\rangle_{\mathcal O} = 0$ for all $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$;
\item $[H_{\mathcal O}, E_{\mathcal O}] = 2E_{\mathcal O}$, $[H_{\mathcal O}, F_{\mathcal O}] = -2F_{\mathcal O}$ and $[E_{\mathcal O}, F_{\mathcal O}] = H_{\mathcal O}$, in other words,  $(E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O})$ is an ${\mathcal I}$-graded  Jacobson-Morozov triple for the Lie algebra corresponding to $(V({\mathcal O}), \langle \  , \   \rangle_{\mathcal O})$;
\item  the ${\mathcal I}$-graded linear transformation $\phi_{\mathcal O}: V({\mathcal O}) \rightarrow V({\mathcal O})$ given by 
\[
\phi_{{\mathcal O}, i} = {E_{\mathcal O}}\vert_{V_i({\mathcal O})}: V_{i}({\mathcal O}) \rightarrow V_{i + 2}({\mathcal O})  \quad \text{for all $i \in {\mathcal I}$  such that $(i + 2) \in {\mathcal I}$},
\]
is  such that $(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ is an $\epsilon$-representation.
\end{itemize}
Moreover $\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \mid \text{ ${\mathcal O}$  belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}$   is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-representations of $(\Omega, \sigma)$.
\end{proposition}
%proof
\begin{proof}
This proof is not difficult, but there are many cases to consider. To be complete all the details are provided. 

The first statement about the degrees of $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ is obvious. To check that $\langle Xu, v\rangle_{\mathcal O} + \langle u, Xv\rangle_{\mathcal O} = 0$ for all $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$, it is enough to verify this on the ${\mathcal I}$-graded basis  ${\mathcal B}_{\mathcal O}$ of $V({\mathcal O})$. Thus we can assume that $u = v_{i_1}(b_1)$, $v = v_{i_2}(b_2)$ with $b_1, b_2 \in {\mathcal O}$, $i_1 \in Supp(b_1)$ and $i_2 \in Supp(b_2)$,

%%%Even part of proof%%%%
{\bf Even case:}

Consider first the proof of the proposition when $\vert {\mathcal I} \vert$  is even. In this case,  $0 \not\in {\mathcal I}$ and we will start with $X = E_{\mathcal O}$.

If  the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, we have 
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} = \begin{cases} {\phantom -} 0, &\text{ if $i_1 = \max(Supp(b_1))$;}\\ {\phantom -} \langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} , &\text{ if $i_1 \ne \max(Supp(b_1))$}\\ &\text{ and $i_1 > 0$;}\\  -\langle v_{i_1+ 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} ,  &\text{ if $i_1 \ne \max(Supp(b_1))$}\\ &\text{and $i_1 < 0$;} \end{cases}
\] 
and 
\[
\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}  = \begin{cases} {\phantom -} 0, &\text{ if $i_2 = \max(Supp(b_2))$;}\\ {\phantom -} \langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O} , &\text{ if $i_2 \ne \max(Supp(b_2))$}\\ &\text{and $i_2 > 0$;}\\  -\langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O} ,  &\text{ if $i_2 \ne \max(Supp(b_2))$}\\ &\text{and $i_2 < 0$.} \end{cases}
\]

If $i_1 = \max(Supp(b_1))$, then $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}  = 0$,  by the definition of $E_{\mathcal O}$ and we have $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}  = 0$,  otherwise if  $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}  \ne 0$, then  $i_2 \ne \max(Supp(b_2))$, $b_2 = \tau(b_1)$ and  $i_1 + 2 + i_2 = 0$. This is impossible,  because $Supp(b_2) = Supp(\tau(b_1)) = \sigma(Supp(b_1))$ and $\min(Supp(b_2)) = -i_1$, but from $i_1 + 2 + i_2 = 0$, we get the contradiction because  $i_2 = -(i_1 + 2) \in Supp(b_2)$. Thus 
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}  + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}  = 0
\]
if $i_1 = \max(Supp(b_1)$. By symmetry, we also have this equality if $i_2 = \max(Supp(b_2))$. Thus we can now assume that $i_1 \ne \max(Supp(b_1))$ and  $i_2 \ne \max(Supp(b_2))$.

So we can now assume that $i_1 \ne \max(Supp(b_1))$ and $i_2 \ne \max(Supp(b_2))$. Moreover if either $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 + 2 = 0$  from our definition of the bilinear form $\langle\  , \  \rangle_{\mathcal O}$. From our hypothesis on the orbit ${\mathcal O}$, we have that $\tau(b_1) \ne b_1$ and $\tau(b_2) \ne b_2$.  If $b_1$ is not on the principal diagonal, then $b_2 = \tau(b_1)$ is also not on the principal diagonal. If $i_1 > 0$, then $i_2 = -i_1 - 2 < 0$ because $i_1 + i_2 + 2 = 0$. Thus we get that 
\begin{multline*}
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = \\ \langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), - v_{i_2 + 2}(b_2)\rangle_{\mathcal O} = 1 - 1 = 0.
\end{multline*}
If $i_1 < 0$ and $i_1 \ne -1$, then $i_1 + 2 < 0$ and $i_2 > 0$. Thus we get that
\begin{multline*}
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = \\ \langle -v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1),  v_{i_2 + 2}(b_2)\rangle_{\mathcal O} = -\epsilon   + \epsilon = 0.
\end{multline*}
To conclude this case, we can observe that $i_1 \ne -1$. Otherwise $i_2 = -i_1 - 2 = -1$ implies that $1 \in Supp(b_1)$. So $\{1, -1\} \subset Supp(b_1)$ and similarly $\{1, -1\} \subset Supp(\tau(b_1))$. But by  \ref{SS:EHFDefinition}, this is equivalent to the orbit ${\mathcal O}$ has overlapping  ${\mathcal I}$-box supports contradicting our hypothesis. 

Note that $b_1$ cannot be on the principal diagonal, otherwise  $b_2 = \tau(b_1)$ is also on the principal diagonal and  $Supp(b_1) = Supp(b_2)$. So we are in the overlapping ${\mathcal I}$-box supports case contradicting our hypothesis on the orbit ${\mathcal O}$. 

We now consider the case where  the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports.  If $i_1 = \max(Supp(b_1))$, the proof is the same as when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and is left to the reader. As above we only have to consider the case where $i_1 \ne \max(Supp(b_1))$ and $i_2 \ne \max(Supp(b_2))$. Moreover if either $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 + 2 = 0$  from our definition of the bilinear form $\langle\  , \  \rangle_{\mathcal O}$.  So we will assume that $b_2 = \tau(b_1)$ and $i_1 + i_2 + 2 = 0$.  Clearly if $b_1$ is below (respectively above, on)  the principal diagonal, then $b_2$ is above (respectively below, on) the principal diagonal. In the case where the ${\mathcal I}$-boxes $b_1$ and $b_2$ are on the principal diagonal, then  we will write $b_1 = b(i'_1, j'_1, k'_1)$ and $b_2 = \tau(b_1) = b(i'_1, j'_1, k''_1)$ where $i'_1, j'_1 \in {\mathcal I}, i'_1 \geq j'_1$ and $k''_1 \in \{k'_1, (1 - k'_1)\}$. More precisely,  if $\mu_{\max} = 0$, then $k'_1 = k''_1 = 0$ and if $\mu_{\max} = 1$, then $k''_1 = (1 - k'_1)$. 


We have that $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases} {\phantom -} 0, &\text{ if $i_1 = \max(Supp(b_1))$;}\\ {\phantom -} \langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 \ne \max(Supp(b_1))$ and $i_1 > 0$;}\\  -\langle v_{i_1+ 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_1 < -1$;}\\ {\phantom -} \langle v_{1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = -1$ and $b_1$ is below the principal diagonal;}\\ -\epsilon \langle v_{1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = -1$ and $b_1$ is above the principal diagonal;}\\ (-\epsilon)^{k'_1} \langle v_{1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = -1$ and $b_1$ is on the principal diagonal;}\end{cases}
\] 
and $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases} {\phantom -} 0, &\text{ if $i_2 = \max(Supp(b_2))$;}\\ {\phantom -} \langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_2 \ne \max(Supp(b_2))$ and $i_2 > 0$;}\\  -\langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 < -1$;}\\ {\phantom - } \langle v_{i_1}(b_1), v_{1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = -1$ and $b_2$ is below the principal diagonal;}\\  - \epsilon \langle v_{i_1}(b_1), v_{1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = -1$ and $b_2$ is above the principal diagonal;} \\ (- \epsilon)^{ k''_1} \langle v_{i_1}(b_1), v_{1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = -1$ and $b_2$ is on  the principal diagonal.} \end{cases}
\]

The proofs when $i_1 > 0$ and also when $i_1 < 0$, $i_1 \ne -1$ are similar to the proofs when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and are left to the reader. We will just consider the case where $i_1 = -1$ and consequently $i_2 = -1$. 

We have that  $\langle E_{\mathcal O}(v_{-1}(b_1)), v_{-1}(b_2)\rangle_{\mathcal O}$ is equal to 
\[
 \begin{cases} \langle v_1(b_1), v_{-1}(b_2) \rangle_{\mathcal O} = 1, &\text{ if $b_1$ is below the principal diagonal;}\\ -\epsilon \langle  v_1(b_1), v_{-1}(b_2)\rangle_{\mathcal O} = -\epsilon , &\text{ if $b_1$ is above the principal diagonal;}\\  (-\epsilon)^{k'_1} \langle v_1(b_1), v_{-1}(b_2)\rangle_{\mathcal O} = (-\epsilon)^{k'_1}, &\text{ if $b_1$ is on the principal diagonal;}\end{cases}
\]
and   $\langle v_{-1}(b_1), E_{\mathcal O}(v_{-1}(b_2))\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases} -\epsilon \langle v_{-1}(b_1),  v_{1}(b_2) \rangle_{\mathcal O} = -\epsilon^2 , &\text{ if $b_1$ is below the principal diagonal;}\\  \langle  v_{-1}(b_1), v_{1}(b_2)\rangle_{\mathcal O} = \epsilon, &\text{ if $b_1$ is above the principal diagonal;}\\ (-\epsilon)^{k''_1} \langle v_{-1}(b_1), v_{1}(b_2)\rangle_{\mathcal O} = (-\epsilon)^{k''_1} \epsilon&\text{ if $b_1$ is on the principal diagonal.} \end{cases}
\]
From this, we get easily if $b_1$ is below or above the principal diagonal that 
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0.
\]


In the case that the ${\mathcal I}$-box $b_1$ is on the principal diagonal, we have to consider two cases: either $\tau(b_1) \ne b_1$  or $\tau(b_1) = b_1$. By lemma~\ref{L:TauBox} (d), if $\tau(b_1) \ne b_1$, then  $\mu_{\max} = 1$ and $k''_1 = 1 - k'_1$. Moreover because of \ref{SS:Iset} and ${\mathcal I}$ is even, then $\epsilon = 1$. So in this case, 
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = (-\epsilon)^{k'_1} + (-\epsilon)^{1 - k'_1} \epsilon = 0.
\]
By lemma~\ref{L:TauBox} (e), if $\tau(b_1) = b_1$, then $\mu_{\max} = 0$, $k''_1 = k'_1$ and $\epsilon = -1$. 
So in this case, 
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = (-\epsilon)^{k'_1} + (-\epsilon)^{k'_1} \epsilon = 0.
\]


If $X = H_{\mathcal O}$, then for either $\langle H_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} =  h_{i_1}(b_1) \langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or  $\langle v_{i_1}(b_1), H_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}  = h_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$, we must have that $b_2 = \tau(b_1)$ and $i_1 + i_2 = 0$. Note that in that case, both are $\ne 0$. So we can assume that $b_2 = \tau(b_1)$ and $i_2 = -i_1$. By lemma \ref{L:RelationCoefficientsHandF} (a),  we get that
\begin{multline*}
\langle H_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), H_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}\\  = (h_{i_1}(b_1) + h_{i_2}(b_2)) \langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} = 0
\end{multline*}

Now consider  $X = F_{\mathcal O}$. The proof is similar with small modification with the one of $E_{\mathcal O}$. If  the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then we have that $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases} {\phantom -} 0, &\text{ if $i_1 = \min(Supp(b_1))$;}\\ {\phantom -}  f_{i_1}(b_1) \langle v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 \ne \min(Supp(b_1))$ and $i_1 > 0$;}\\  - f_{i_1}(b_1) \langle v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_1 \ne \min(Supp(b_1))$ and $i_1 < 0$;} \end{cases}
\] 
and $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to 
\[
= \begin{cases} {\phantom -} 0, &\text{ if $i_2 = \min(Supp(b_2))$;}\\ {\phantom -} f_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_2 \ne \min(Supp(b_2))$ and $i_2 > 0$;}\\  - f_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 \ne \min(Supp(b_2))$ and $i_2 < 0$.} \end{cases}
\]

If $i_1 = \min(Supp(b_1))$, then $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} = 0$,  by the definition of $F_{\mathcal O}$ and we have $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0$,  otherwise if  $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then  $i_2 \ne \min(Supp(b_2))$, $b_2 = \tau(b_1)$ and  $i_1 - 2 + i_2 = 0$. This is impossible,  because $Supp(b_2) = Supp(\tau(b_1)) = \sigma(Supp(b_1))$ and $\max(Supp(b_2)) = -i_1$, but from $i_1 - 2 + i_2 = 0$, we get the contradiction because  $i_2 = -i_1 + 2 \in Supp(b_2)$. Thus 
\[
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0
\]
if $i_1 = \min(Supp(b_1)$. By symmetry, we also have this equality if $i_2 = \min(Supp(b_2))$. 

So we can now assume that $i_1 \ne \min(Supp(b_1))$ and $i_2 \ne \min(Supp(b_2))$. Moreover if either $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$  from our definition of the bilinear form $\langle\  , \  \rangle_{\mathcal O}$. From our hypothesis on the orbit ${\mathcal O}$, we have that $\tau(b_1) \ne b_1$ and $\tau(b_2) \ne b_2$.  If $b_1$ is not on the principal diagonal, then $b_2 = \tau(b_1)$ is also not on the principal diagonal. If $i_1 > 0$ and $i_1 \ne 1$, then $i_2 = -i_1 + 2 < 0$ because $i_1 + i_2 - 2 = 0$. Thus we get that 
\begin{multline*}
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = \\ f_{i_1}(b_1) \langle v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} - f_{i_2}(b_2) \langle v_{i_1}(b_1),  v_{i_2 - 2}(b_2)\rangle_{\mathcal O} =\\ (f_{i_1}(b_1) - f_{-i_1 + 2}(\tau(b_1)) = 0
\end{multline*}
because of  lemma~\ref{L:RelationCoefficientsHandF} (b) and our definition of the bilinear form.

If $i_1 < 0$, then $i_2 = -i_1 + 2 > 0$. Thus we get that
\begin{multline*}
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = \\ -f_{i_1}(b_1) \langle v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} + f_{i_2}(b_2) \langle v_{i_1}(b_1),  v_{i_2 - 2}(b_2)\rangle_{\mathcal O} = \\ ( -\epsilon f_{i_1}(b_1)  + \epsilon f_{i_2}(b_2)) = 0
\end{multline*}
because of  lemma~\ref{L:RelationCoefficientsHandF} (b) and our definition of the bilinear form.
To conclude this case, we can observe that $i_1 \ne 1$. Otherwise $i_2 = -i_1 + 2 = 1$ implies that $-1 \in Supp(b_1)$. So $\{1, -1\} \subset Supp(b_1)$ and similarly $\{1, -1\} \subset Supp(\tau(b_1))$. But by  \ref{SS:EHFDefinition}, this is equivalent to the orbit ${\mathcal O}$ has overlapping  ${\mathcal I}$-box supports contradicting our hypothesis. 

Note that $b_1$ cannot be on the principal diagonal, otherwise  $b_2 = \tau(b_1)$ is also on the principal diagonal and  $Supp(b_1) = Supp(b_2)$. So we are in the overlapping ${\mathcal I}$-box supports case contradicting our hypothesis on the orbit ${\mathcal O}$. 


We now consider the case where  the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports.  If $i_1 = \min(Supp(b_1))$, the proof is the same as when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and is left to the reader. As above we only have to consider the case where $i_1 \ne \min(Supp(b_1))$ and $i_2 \ne \min(Supp(b_2))$. Moreover if either $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$  from our definition of the bilinear form $\langle\  , \  \rangle_{\mathcal O}$.  So we will assume that $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$.  Clearly if $b_1$ is below (respectively above, on)  the principal diagonal, then $b_2$ is above (respectively below, on) the principal diagonal. In the case where the ${\mathcal I}$-boxes $b_1$ and $b_2$ are on the principal diagonal, then  we will write $b_1 = b(i'_1, j'_1, k'_1)$ and $b_2 = \tau(b_1) = b(i'_1, j'_1,  k''_1)$ where $i'_1, j'_1 \in {\mathcal I}, i'_1 \geq j'_1$ and $k''_1 \in \{k'_1, (1 - k'_1)\}$. 


We have that $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases} {\phantom -} 0, &\text{ if $i_1 = \min(Supp(b_1))$;}\\ {\phantom -} f_{i_1}(b_1)\langle v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 > 1$;}\\  -f_{i_1}(b_1)\langle v_{i_1- 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_1 \ne \min(Supp(b_1))$ and $i_1 \leq -1$;}\\ {\phantom -} f_1(b_1)\langle v_{-1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = 1$ and $b_1$ is below the principal diagonal;}\\ -\epsilon f_1(b_1) \langle v_{-1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = 1$ and $b_1$ is above the principal diagonal;}\\ (-\epsilon)^{k'_1}f_1(b_1) \langle v_{-1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_1 = 1$ and $b_1$ is on the principal diagonal;}\end{cases}
\] 
and $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases} {\phantom -} 0, &\text{ if $i_2 = \min(Supp(b_2))$;}\\ {\phantom -} f_{i_2}(b_2)\langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{ if $i_2 > 1$;}\\  -f_{i_2}(b_2)\langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 \ne \min(Supp(b_2)$ and $i_2 \leq -1$;}\\ {\phantom - } f_1(b_2)\langle v_{i_1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = 1$ and $b_2$ is below the principal diagonal;}\\  - \epsilon f_1(b_2) \langle v_{i_1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = 1$ and $b_2$ is above the principal diagonal;} \\ (- \epsilon)^{ k''_1}f_1(b_2) \langle v_{i_1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if $i_2 = 1$ and $b_2$ is on  the principal diagonal.} \end{cases}
\]

The proofs when $i_1 > 0$  and $i_1 \ne 1$ or when $i_1 < 0$  are similar to the proofs when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and are left to the reader. We will just consider the case where $i_1 = 1$ and consequently $i_2 = 1$. 
We have that $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases}  {\phantom -} f_1(b_1)\langle v_{-1}(b_1), v_{1}(b_2)\rangle_{\mathcal O}, &\text{ if  $b_1$ is below the principal diagonal;}\\ -\epsilon f_1(b_1) \langle v_{-1}(b_1), v_{1}(b_2)\rangle_{\mathcal O}, &\text{ if  $b_1$ is above the principal diagonal;}\\ (-\epsilon)^{k'_1}f_1(b_1) \langle v_{-1}(b_1), v_{1}(b_2)\rangle_{\mathcal O}, &\text{ if  $b_1$ is on the principal diagonal;}\end{cases}
\] 
and $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to
\[
 \begin{cases}  - \epsilon f_1(b_2) \langle v_{1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if  $b_1$ is below the principal diagonal;} \\  {\phantom - } f_1(b_2)\langle v_{1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if $b_1$ is above the principal diagonal;}\\  (- \epsilon)^{ k''_1}f_1(b_2) \langle v_{1}(b_1), v_{-1}(b_2)\rangle_{\mathcal O},  &\text{ if  $b_1$ is on  the principal diagonal.} \end{cases}
\]

 From this and lemma~\ref{L:RelationCoefficientsHandF} (b), we get easily if $b_1$ is below or above the principal diagonal that 
\[
\langle F_{\mathcal O}(v_{1}(b_1)), v_{1}(b_2)\rangle_{\mathcal O} + \langle v_{1}(b_1), F_{\mathcal O}(v_{1}(b_2))\rangle_{\mathcal O} = 0.
\]


In the case that the ${\mathcal I}$-box $b_1$ is on the principal diagonal, we have to consider two cases: either $\tau(b_1) \ne b_1$  or $\tau(b_1) = b_1$. By lemma~\ref{L:TauBox} (d), if $\tau(b_1) \ne b_1$, then  $\mu_{\max} = 1$ and $k''_1 = 1 - k'_1$. Moreover because of \ref{SS:Iset} and ${\mathcal I}$ is even, then $\epsilon = 1$. So in this case, 
\[
\langle F_{\mathcal O}(v_{1}(b_1)), v_{1}(b_2)\rangle_{\mathcal O} + \langle v_{-1}(b_1), F_{\mathcal O}(v_{1}(b_2))\rangle_{\mathcal O} = (-\epsilon)^{k'_1}f_1(b_1)\epsilon + (-\epsilon)^{1 - k'_1}f_1(b_2) \epsilon = 0.
\]
by lemma~\ref{L:RelationCoefficientsHandF} (b).
By lemma~\ref{L:TauBox} (e), if $\tau(b_1) = b_1$, then $\mu_{\max} = 0$, $k''_1 = k'_1$ and $\epsilon = -1$. 
So in this case, 
\[
\langle F_{\mathcal O}(v_{1}(b_1)), v_{1}(b_2)\rangle_{\mathcal O} + \langle v_{1}(b_1), F_{\mathcal O}(v_{1}(b_2))\rangle_{\mathcal O} = (-\epsilon)^{k'_1} f_1(b_1) \epsilon+ (-\epsilon)^{k'_1} f_1(b_2) = 0.
\]
again by lemma~\ref{L:RelationCoefficientsHandF} (b).

We have now proved that $\langle X(u), v\rangle_{\mathcal O} + \langle u, X(v)\rangle_{\mathcal O} = 0$ for all $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$ when $\vert {\mathcal I} \vert$ is even.

We want to prove now the Jacobson-Morozov triple relations in the case where $\vert {\mathcal I} \vert$ is even. In other words, $[H_{\mathcal O}, E_{\mathcal O}] = 2E_{\mathcal O}$, $[H_{\mathcal O}, F_{\mathcal O}] = -2F_{\mathcal O}$ and $[E_{\mathcal O}, F_{\mathcal O}] = H_{\mathcal O}$. It is enough to verify these only on the ${\mathcal I}$-graded basis ${\mathcal B}_{\mathcal O}$ of $V({\mathcal O})$. 

If the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then we have already computed  above our expressions  for $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ on ${\mathcal B}_{\mathcal O}$. Let $b$ be the ${\mathcal I}$-box in ${\mathcal O}$ and $i \in Supp(b)$. Then $[H_{\mathcal O}, E_{\mathcal O}](v_i(b)) =  (H_{\mathcal O} E_{\mathcal O} - E_{\mathcal O} H_{\mathcal O}) (v_i(b))$ is equal to
\[
\begin{aligned}
&=\begin{cases} 0 - 0, &\text{ if $i = \max(Supp(b))$;}\\ h_{i + 2}(b) v_{i + 2}(b) - h_i(b) v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -h_{i + 2}(b) v_{i + 2}(b) + h_i(b) v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i <  0$;}
\end{cases}\\
& =  \quad (h_{i + 2}(b) - h_i(b))E_{\mathcal O}(v_i(b)) = 2 E_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (c).

Secondly we have  $[H_{\mathcal O}, F_{\mathcal O}](v_i(b)) =  (H_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} H_{\mathcal O}) (v_i(b))$ is equal to
\[
\begin{aligned}
&=\begin{cases} 0 - 0, &\text{ if $i = \min(Supp(b))$;}\\ h_{i - 2}(b) f_i(b) v_{i - 2}(b) - h_i(b) f_i(b) v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i > 0$;}\\  -h_{i - 2}(b) f_i(b) v_{i - 2}(b) + h_i(b) f_i(b) v_{i - 2}(b), &\text{ if $i \ne \min(Supp(b))$ and $i <  0$;}
\end{cases}\\
& =  \quad (h_{i - 2}(b) - h_i(b))F_{\mathcal O}(v_i(b)) = -2 F_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (d).

Thirdly we have to compute $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) =  (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O}) (v_i(b))$. Write $b = b(i_1, j_1, k_1)$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k \leq \mu(i_1, j_1)$  and for $i \in Supp(b)$. Thus $i_1 \geq i \geq j_1$. We have different cases to consider. Because ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then either $j_1 \geq 1$ or $i_1 \leq -1$. If $i_1 = j_1 = i$, then easily we have $h_i(b) = 0$ and  $(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O}) (v_i(b)) = 0 = H_{\mathcal O} (v_i(b))$. If $i_1 > j_1$ and $i = i_1 = \max(Supp(b))$, then 
\[
\begin{aligned}
f_i(b) &= \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I}  \mid i'' \geq j'', i \leq i'' \leq i_1, j_1 < j'' \leq i\}\\
&= \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I}  \mid i'' \geq j'', i = i'' = i_1, j_1 < j'' \leq i\} = h_i(b),
\end{aligned}
\]
because of lemma~\ref{L:RelationCoefficientsHandF} (f).

So
\[
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O}) (v_i(b)) = f_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\]
If $i_1 > j_1$ and $i = j_1 = \min(Supp(b))$, then 
\[
\begin{aligned}
f_{i + 2}(b) &= \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I}  \mid i'' \geq j'', (i + 2) \leq i'' \leq i_1, j_1 < j'' \leq (i + 2)\}\\ 
&=   \#\{(i'', j'') \in {\mathcal I} \times {\mathcal I}  \mid i'' \geq j'', (i + 2) \leq i'' \leq i_1,  j'' = (i + 2)\} = -h_i(b),
\end{aligned}
\]
because of lemma~\ref{L:RelationCoefficientsHandF} (e).

So
\[
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O}) (v_i(b)) = 0 - f_{i + 2}(b) v_i(b) = H_{\mathcal O}(v_i(b))
\]
If $i_1 > i > j_1$, then both $(i - 2)$, $(i + 2)$ belongs to $Supp(b)$. Consequently they are both either simultanously $> 0$ or simultanously $< 0$.  So
\[
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O}) (v_i(b)) = (f_i(b) - f_{i + 2}(b)) v_i(b) = H_{\mathcal O}(v_i(b))
\]
because of lemma~\ref{L:RelationCoefficientsHandF} (g).

If the orbit ${\mathcal O}$ has  overlapping ${\mathcal I}$-box supports, then we have already computed  above our expressions  for $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ on ${\mathcal B}_{\mathcal O}$. Let $b = b(i_1, j_1, k_1)$ be the ${\mathcal I}$-box in ${\mathcal O}$ and $i \in Supp(b)$. We have  $[H_{\mathcal O}, E_{\mathcal O}](v_i(b)) =  (H_{\mathcal O} E_{\mathcal O} - E_{\mathcal O} H_{\mathcal O}) (v_i(b))$ is equal to
\[
\begin{cases}
0, &\text{ if $i = \max(Supp(b))$;}\\  (h_{i + 2}(b) - h_i(b))v_{i + 2}(b) = 2v_{i + 2}(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -(h_{i + 2}(b) - h_i(b)) v_{i + 2}(b)=  - 2v_{i + 2}(b), &\text{ if  $i < -1$;}\\ (h_{1}(b) - h_{-1}(b)) v_{1}(b)=  2v_{1}(b), &\text{ if  $i = -1$ and $b$ is below the }\\ &\text{principal  diagonal;}\\ -\epsilon(h_{1}(b) - h_{-1}(b)) v_{1}(b)=  -\epsilon 2v_{1}(b), &\text{ if  $i = -1$ and $b$ is above the }\\ &\text{principal  diagonal;}\\ (-\epsilon)^{k_1} (h_{1}(b) - h_{-1}(b)) v_{1}(b)=  (-\epsilon)^{k_1} 2v_{1}(b), &\text{ if  $i = -1$ and $b$ is on the }\\ &\text{principal  diagonal;}\\ 
\end{cases}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (c). Clearly we get that $[H_{\mathcal O}, E_{\mathcal O}](v_i(b)) = 2E_{\mathcal O}(v_i(b))$.  

Similarly we have 
$[H_{\mathcal O}, F_{\mathcal O}](v_i(b)) =  (H_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} H_{\mathcal O}) (v_i(b))$ is equal to
\[
\begin{cases}
0, &\text{ if $i = \min(Supp(b))$;}\\  (h_{i - 2}(b) - h_i(b))f_i(b)v_{i - 2}(b) = -2f_i(b)v_{i - 2}(b), &\text{ if $i > 1$;}\\  -(h_{i - 2}(b) - h_i(b)) f_i(b)v_{i - 2}(b)=  2f_i(b)v_{i - 2}(b), &\text{ if  $i \ne \min(Supp(b))$}\\ &\text{ and $i \leq -1$;}\\ (h_{-1}(b) - h_{1}(b))f_1(b) v_{-1}(b)=  -2f_1(b)v_{-1}(b), &\text{ if  $i = 1$ and $b$ is below the }\\ &\text{principal  diagonal;}\\ -\epsilon(h_{-1}(b) - h_{1}(b)) f_1(b) v_{-1}(b)=   -2(-\epsilon)f_1(b)v_{-1}(b), &\text{ if  $i = 1$ and $b$ is above the }\\ &\text{principal  diagonal;}\\ (-\epsilon)^{k_1} (h_{-1}(b) - h_{1}(b)) f_1(b)v_{-1}(b) &\text{ if  $i = 1$ and $b$ is on the }\\ \quad\quad =  (-2) (-\epsilon)^{k_1} f_1(b) v_{-1}(b) &\text{principal  diagonal;}\\ 
\end{cases}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (d). Clearly we get that $[H_{\mathcal O}, F_{\mathcal O}](v_i(b)) = -2F_{\mathcal O}(v_i(b))$. 

Finally we have to prove $[E_{\mathcal O}, F_{\mathcal O}] = H_{\mathcal O}$. Assume $b = b(i_1, j_1, k_1)$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k_1 \leq \mu(i_1, j_1)$ and let $i \in Supp(b)$. By our hypothesis, we get that $i_1 \geq 1 > -1 \geq j_1$. Note that $i_1 \geq i \geq j_1$.  

If $i = i_1 = \max(Supp(b))$, then $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases} f_i(b) v_i(b), &\text{if $i \ne 1$;}\\ f_1(b) v_1(b), &\text{if $i = 1$ and $b$ is below the principal diagonal;}\\  (-\epsilon)^2 f_1(b) v_1(b), &\text{if $i = 1$ and $b$ is above the principal diagonal;}\\ (-\epsilon)^{2k_1} f_1(b) v_1(b), &\text{if $i = 1$ and $b$ is on the principal diagonal;}
\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (f).

If $i = j_1 = \min(Supp(b))$, then $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases} - f_{i + 2}(b) v_i(b), &\text{if $i < -1$;}\\ -f_1(b) v_{-1}(b), &\text{if $i = -1$ and $b$ is below the principal diagonal;}\\  -(-\epsilon)^2 f_1(b) v_{-1}(b), &\text{if $i = -1$ and $b$ is above the principal diagonal;}\\ -(-\epsilon)^{2k_1} f_1(b) v_{-1}(b), &\text{if $i = -1$ and $b$ is on the principal diagonal;}
\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (e).

If $i_1 > i > j_1$, then $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases} (f_i(b) - f_{i + 2}(b)) v_i(b), &\text{if $i >1$;}\\ (f_i(b) - f_{i + 2}(b)) v_{i}(b), &\text{if $i < -1$;}\\  (f_1(b)  - f_3(b))v_{1}(b), &\text{if $i = 1$ and $b$ is below the principal diagonal;}\\ ((-\epsilon)^2f_1(b)  - f_3(b))v_{1}(b), &\text{if $i = 1$ and $b$ is above the principal diagonal;}\\ ((-\epsilon)^{2k_1} f_1(b) - f_3(b)) v_{1}(b), &\text{if $i = 1$ and $b$ is on the principal diagonal;}\\ (f_{-1}(b)  - f_1(b))v_{-1}(b), &\text{if $i = -1$ and $b$ is below the principal diagonal;}\\ (f_{-1}(b)  - (-\epsilon)^2 f_1(b))v_{-1}(b), &\text{if $i = -1$ and $b$ is above the principal diagonal;}\\ ( f_{-1}(b) - (-\epsilon)^{2k_1}f_1(b)) v_{-1}(b), &\text{if $i = -1$ and $b$ is on the principal diagonal;}
\end{cases}\\
&= (f_i(b) - f_{i + 2}(b))v_i(b) = h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (g).

Thus we have proved that the triple $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ is an ${\mathcal I}$-graded Jacobson-Morozov triple when $\vert {\mathcal I} \vert$ is even. 

We now want to prove that 
\[
\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle) \mid \text{ ${\mathcal O}$
belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}
\]
is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-representa~- tions of $(\Omega, \sigma)$ when $\vert {\mathcal I} \vert$ is even.

Let the ${\mathcal I}$-box $b = b(i_1, j_1, k_1) \in {\mathbf B}$ be an element of the $\langle \tau \rangle$-orbit ${\mathcal O}$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k_1 \leq \mu(i_1, j_1)$. If we consider the restriction of $E_{\mathcal O}$ to $V_i(b)$: $\phi_{b, i} = E_{\mathcal O}\vert_{V_i(b)}:V_i(b) \rightarrow V_{i + 2}(b)$ for each $i \in Supp(b)$, $i \ne \max(Supp(b))$, we get a representation $\phi_b:V(b) \rightarrow V(b)$ of the quiver $\Omega$ of type $A_{2m}$. Here $\vert {\mathcal I} \vert = 2m$. From our definition of $E_{\mathcal O}$, we get easily that 
\begin{itemize}
\item $\phi_b$ is an indecomposable representation of $A_{2m}$ of dimension $\dim(\phi_b) = (\beta_i)_{i \in {\mathcal I}}$ where 
\[
\beta_i = \begin{cases} 1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise.}\end{cases}
\]
\item $\phi_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$ is the direct sum $\oplus_{b \in {\mathcal O}} \phi_b$ as a representation of $A_{2m}$.
\end{itemize}
Because $\langle E_{\mathcal O}(u), v\rangle_{\mathcal O} + \langle u, E_{\mathcal O}(v)\rangle_{\mathcal O} = 0$ for all $u, v \in V({\mathcal O})$, we get that the representation $(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ is an $\epsilon$-representation. To show that $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$ is  indecomposable, we can use theorem~\ref{T:CaracterisationRepresentation}.

Each $\langle \tau \rangle$-orbit ${\mathcal O}$ contains at least one ${\mathcal I}$-box $b = b(i_1, j_1, k_1) \in {\mathbf B}$ such that $(i_1 + j_1) \geq 0$. If $(i_1 + j_1) > 0$, this ${\mathcal I}$-box is unique in the orbit, while if $(i_1 + j_1) = 0$, then there are $\mu_{\max}$ ${\mathcal I}$-boxes in the orbit. If $(i_1 + j_1) > 0$, then $\tau(b) \ne b$ and ${\mathcal O} = \{b, \tau(b)\}$. We have $i_1 \geq j_1$ and $i_1 \geq \vert j_1 \vert$ because  $(i_1 + j_1) > 0$.  As in the definition~\ref{DefDim}, we will write the dimension vector of $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ as representation of the symmetric quiver $({\Omega}, \sigma)$ by
\[
\dim(V({\mathcal O}))  = (\dim(V_i({\mathcal O}))_{i \in {\mathcal I}_+} = (\alpha_i)_{i \in {\mathcal I}_+} = \alpha.
\]
We will write also the dimensions of $\dim(\phi_b)$ and $\dim(\phi_{\tau(b)})$ as representation of the quiver $A_{2m}$ by 
\[
\dim(\phi_b) = \beta' = (\beta'_i)_{i \in {\mathcal I}} \quad \text{ and } \quad  \dim(\phi_{\tau(b)}) = \beta = (\beta_i)_{i \in {\mathcal I}}.
\]  

If $j_1 > 0$, then 
\[
\beta'_i = \begin{cases}1, &\text{if $-j_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases} \quad  \quad 
\beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;} \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  1,&\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$.  Using proposition~\ref{Decomposition_even} (a) (i) and (b)(i) when $j_1 > 1$, proposition~\ref{Decomposition_even} (a) (ii) and (b) (ii) for $\alpha^0$ when $j_1 = 1$ and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$.

If $0 > j_1$, then 
\[
\beta'_i = \begin{cases}1, &\text{if $-j_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases} \quad  \quad 
\beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;} \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  2,&\text{if $i_1 \geq i > 0$;}\\ 1,&\text{if $i_1 \geq i > \vert j_1 \vert$;}\\ 0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$.  Using proposition~\ref{Decomposition_even} (a) (iii) and (b)(iii)  and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$.

If $(i_1 + j_1) = 0$, then the ${\mathcal I}$-box $b(i_1, j_1, k_1)$ is on the principal diagonal and $i_1 > 0$, because $i_1 \geq j_1$. There are two cases to consider: either $\tau(b) \ne b$ or $\tau(b) = b$. When $\tau(b) \ne b$, then ${\mathcal O} = \{b, \tau(b)\}$ and by lemma~\ref{L:TauBox} (d), $\mu_{\max} = 1$, $\epsilon = 1$, $\tau(b) = b(i_1, j_1, (1 - k_1))$. So 
\[
\beta'_i = \beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  2,&\text{if $i_1 \geq i > 0$;}\\  0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$. Using proposition~\ref{Decomposition_even} (a) (iv) and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$. 

When $\tau(b) = b$, then ${\mathcal O} = \{b \}$ and by lemma~\ref{L:TauBox} (e), $\mu_{\max} = 0$, $\epsilon = -1$, $V({\mathcal O}) = V_b$. We will write $\dim(\phi_b) = \beta = (\beta_i)_{i \in {\mathcal I}}$. So 
\[
\beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  1,&\text{if $i_1 \geq i > 0$;}\\  0, &\text{otherwise.}\end{cases}
\]
for $i \in {\mathcal I}_+$. Using proposition~\ref{Decomposition_even} (b) (ii) for $\alpha^1$ and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha^1$. 

To finish the proof when $\vert {\mathcal I} \vert$ is even, it suffices to notice by inspection of the dimension vectors of $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$,  the direct sum decomposition $\phi_{\mathcal O} = \oplus_{b \in {\mathcal O}} \phi_b$ and theorem~\ref{T:CaracterisationRepresentation}, that $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ and $(V({\mathcal O'}), \phi_{\mathcal O'}, \langle\  , \  \rangle_{{\mathcal O}'})$ are not isomorphic for two distinct $\langle \tau \rangle$-orbits ${\mathcal O}$ and ${\mathcal O}'$. By remark~\ref{R:CardinalityIndecomposable}, we get the result that $\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \mid \text{ ${\mathcal O}$  belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}$   is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-representations of $(\Omega, \sigma)$.

%%%%Odd part of proof

{\bf Odd case:}


Consider secondly the proof of the proposition when $\vert {\mathcal I} \vert$ is odd. In this case, $0 \in {\mathcal I}$. We want to prove that $\langle X(u), v\rangle_{\mathcal O} + \langle u, X(v)\rangle_{\mathcal O} = 0$ for all basis vectors $u, v \in {\mathcal B}_{\mathcal O}$ and $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$. We will start with $X = E_{\mathcal O}$.

If the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then we saw in \ref{SS:EHFDefinition} that this is equivalent to $0 \not\in Supp(b)$ or equivalently $0 \not \in Supp(\tau(b))$,  when $b \in {\mathcal O}$. We have that $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases} {\phantom -}0, &\text{if $i_1 = \max(Supp(b_1))$;} \\  {\phantom -}\langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$ and $i_1 > 0$;}\\  -\langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$ and $i_1 < 0$;}\end{cases}
\]
and that $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases}  {\phantom -}0, &\text{if $i_2 = \max(Supp(b_2))$;} \\  {\phantom -}\langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_1))$ and $i_2 > 0$;}\\  -\langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_2))$ and $i_2 < 0$.}\end{cases}
\]

If $i_1 = \max(Supp(b_1))$, then $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} = 0$ by the definition of $E_{\mathcal O}$ and we have $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0$, otherwise if $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $i_2 \ne \max(Supp(b_2))$, $b_2 = \tau(b_1)$ and $i_1 + i_2 +2 = 0$. This is impossible, because $Supp(b_2) = \sigma(Supp(b_1))$ and $\min(Supp(b_2))= -i_1$, but from $i_1 + i_2 + 2 = 0$, we get a contradiction because $i_2 = (-i_1 - 2) \in Supp(b_2)$.  Thus
\[
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0
\]
if $i_1 = \max(Supp(b_1))$. By symmetry, we also have this equality if $i_2 = \max(Supp(b_2))$.

So we can now assume that $i_1 \ne \max(Supp(b_1))$ and $i_2 \ne \max(Supp(b_2))$. Moreover if either $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 + 2 = 0$ from our definition of the bilinear form $\langle\  , \  \rangle$. From our hypothesis on the orbit ${\mathcal O}$, we have that $\tau(b_1) \ne b_1$ and $\tau(b_2) \ne b_2$. If $b_1$ is not on the principal diagonal, then $b_2 = \tau(b_1)$ is also not on the principal diagonal. If $i_1 > 0$, then $i_2 = -i_1 -2 < 0$, because $i_1 + i_2 + 2 = 0$. Thus we get 
\begin{multline*}
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}\\ =\langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle + \langle v_{i_1}(b_1), -v_{i_2 + 2}(b_2)\rangle = 1 - 1 = 0.
\end{multline*}
If $i_1 < 0$ and $i_1 \ne -2$, then $i_2 = -(i_1 + 2) > 0$. Thus we get that 
\begin{multline*}
\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}\\ =\langle -v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O} = -\epsilon + \epsilon = 0.
\end{multline*}
Note that  we cannot have $i_1 = -2$, otherwise we get that $i_2 = 0 \in Supp(\tau(b_2))$, but this contradicts our hypothesis on the orbit. 

Note that $b_1$ cannot be on the principal diagonal, otherwise $b_2 = \tau(b_1)$ is also on the principal diagonal  and $Supp(b_2) = Supp(b_1)$. This contradicts the fact that ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports.

We will now consider the case where the orbit has overlapping  ${\mathcal I}$-box supports. If $i_1 = \max(Supp(b_1))$, the proof is the same as when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports  and is left to the reader. As above we only have to consider the case where $i_1 \ne \max(Supp(b_1))$ and $i_2 \ne \max(Supp(b_2))$. Moreover if either $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 + 2 = 0$ from our definition of $\langle\  , \  \rangle_{\mathcal O}$. Clearly if $b_1$ is below (respectively above, on) the principal diagonal, then $b_2$ is above (respectively below, on) the principal diagonal. In the case where the ${\mathcal I}$-boxes $b_1$ and $b_2$ are on the principal diagonal, then we will write $b_1 = b_1(i'_1, j'_1, k'_1)$ and $b_2 = \tau(b_1) = b(i'_1, j'_1, k''_1)$ where $i'_1, j'_1 \in {\mathcal I}$, $i'_1 \geq j'_1$ and $k''_1 \in \{k'_1, (1 - k'_1)\}$. More precisely, if $\mu_{\max} = 0$, then $k''_1 = k'_1$  and if $\mu_{\max} = 1$, then $k''_1 = (1 - k'_1)$.

We have that $\langle E_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases} 0, &\text{if $i_1 = \max(Supp(b_1))$;}\\ \langle v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$ and $i_1 > 0$;}\\ \langle -v_{i_1 + 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 < 0$;}\\ \langle \epsilon v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$,  $i_1 = 0$ and $b_1$ is below the}\\ &\text{principal diagonal;}\\ \langle  v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$,  $i_1 = 0$ and $b_1$ is above the}\\ &\text{principal diagonal;}\\ \langle \epsilon^{k'_1} v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \max(Supp(b_1))$,  $i_1 = 0$ and $b_1$ is on the}\\ &\text{principal diagonal;}
\end{cases}
\]
and $\langle v_{i_1}(b_1), E_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases} 0, &\text{if $i_2 = \max(Supp(b_2))$;}\\ \langle v_{i_1}(b_1), v_{i_2 + 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_2))$ and $i_2 > 0$;}\\ \langle v_{i_1}(b_1), -v_{i_2 + 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 < 0$;}\\ \langle v_{-2}(b_1),  \epsilon v_{2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_2))$,  $i_2 = 0$ and $b_2$ is below the}\\ &\text{principal diagonal;}\\ \langle  v_{-2}(b_1), v_{2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_2))$,  $i_2 = 0$ and $b_2$ is above the}\\ &\text{principal diagonal;}\\ \langle  v_{-2}(b_1), \epsilon^{k''_1} v_{2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \max(Supp(b_2))$,  $i_2 = 0$ and $b_2$ is on the}\\ &\text{principal diagonal.}
\end{cases}
\]
The proofs when $i_1 > 0$ and  when $i_1 < -2$ are similar to the proofs when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and are left to the reader. We will only consider the cases where $i_1 = 0$ and $i_1 = -2$.

If $i_1 = 0$, then $i_2 = -2$ and consequently $2 \in Supp(b_1)$, because $-2 \in Supp(\tau(b_1))$. So $i_1 \ne \max(Supp(b_1))$.  We have that $\langle E_{\mathcal O}(v_{0}(b_1)), v_{-2}(b_2)\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases}  \langle \epsilon v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O} = \epsilon, &\text{if  $b_1$ is below the principal diagonal;}\\ \langle  v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O} = 1, &\text{if $b_1$ is above the principal diagonal;}\\ \langle \epsilon^{k'_1} v_{2}(b_1), v_{-2}(b_2)\rangle_{\mathcal O} = \epsilon^{k'_1}, &\text{if  $b_1$ is on the principal diagonal;}
\end{cases}
\]
and $\langle v_{0}(b_1), E_{\mathcal O}(v_{-2}(b_2))\rangle_{\mathcal O} = \langle v_0(b_1), - v_0(b_2)\rangle_{\mathcal O}$  is equal to 
\[
\begin{cases} -\epsilon, &\text{if $b_1$ is below the principal diagonal;}\\ -1, &\text{if  $b_1$ is above the principal diagonal;}\\ -\epsilon^{k'_1}, &\text{if $b_1$ is on the principal diagonal and $\tau(b_1) \ne b_1$;} \\ -1, &\text{if $b_1$ is on the principal diagonal and $\tau(b_1) = b_1$;}
\end{cases}
\]

From this, we get easily if $b_1$ is below or above the principal diagonal that
\[
\langle E_{\mathcal O}(v_{0}(b_1)), v_{-2}(b_2)\rangle_{\mathcal O} + \langle v_{0}(b_1), E_{\mathcal O}(v_{-2}(b_2))\rangle_{\mathcal O} = 0. \quad\quad (*)
\]
In the case that the ${\mathcal I}$-box $b_1$ is on the principal diagonal, we have to consider two cases: either $\tau(b_1) \ne b_1$ or $\tau(b_1) = b_1$. If $\tau(b_1) \ne b_1$, we easily get the equation (*). If $\tau(b_1) = b_1$, then, by lemma~\ref{L:TauBox} (f), $\epsilon = 1$ and $(*)$ is also verified.

If $i_1 = -2$, then $i_2 = 0$ and by symmetry we also get $(*)$. 

If $X = H_{\mathcal O}$, then for either  $\langle H_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} =  h_{i_1}(b_1) \langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or for $\langle v_{i_1}(b_1), H_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} =  h_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$, we must have $b_2 = \tau(b_1)$ and $i_1 + i_2 = 0$. Note that in both cases, $\langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$. So we can assume that $b_2 = \tau(b_1)$ and $i_2 = -i_1$. By lemma~\ref{L:RelationCoefficientsHandF} (a), we get that 
\begin{multline*}
\langle H_{\mathcal O}(v_{0}(b_1)), v_{-2}(b_2)\rangle_{\mathcal O} + \langle v_{0}(b_1), H_{\mathcal O}(v_{-2}(b_2))\rangle_{\mathcal O} \\ =(h_{i_1}(b_1) + h_{i_2}(b_2))\langle v_{i_1}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} = 0.
\end{multline*}

Now we consider $X = F_{\mathcal O}$. If the orbit has no overlapping ${\mathcal I}$-box supports, then we have that $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases} {\phantom -}0, &\text{if $i_1 = \min(Supp(b_1))$;}\\  {\phantom -} \langle f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne\min(Supp(b_1))$ and $i_1 > 0$;}\\ - \langle f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \min(Supp(b_1))$ and $i_1 < 0$;} \end{cases}
\]
and 
$\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases} {\phantom -}0, &\text{if $i_2 = \min(Supp(b_2))$;}\\  {\phantom -} \langle  v_{i_1}(b_1), f_{i_2}(b_2)(v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne\min(Supp(b_2))$ and $i_2 > 0$;}\\ - \langle  v_{i_1}(b_1), f_{i_2}(b_2) v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \min(Supp(b_2))$ and $i_2 < 0$;} \end{cases}
\]

If $i_1 = \min(Supp(b_1))$, then $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} = 0$ by definition of $F_{\mathcal O}$ and we have $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0$, otherwise if  $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle \ne 0$, then $i_2 \ne \min(Supp(b_2))$, $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$. This is impossible, because $Supp(b_2) = \sigma(Supp(b_1))$ and $\max(Supp(b_2)) = -i_1$, but from $i_2 = (-i_1 + 2) \in Supp(b_2)$ we get the contradiction. Thus   
\[
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} = 0
\]
if $i_1 = \min(Supp(b_1))$. By symmetry, we also have this last equality if $i_2 = \min(Supp(b_2))$. From now on, we will assume that $i_1 \ne \min(Supp(b_1))$ and $i_2 \ne \min(Supp(b_2))$.  

If either $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or  $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne  0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$ from our definition of the bilinear form $\langle\  , \  \rangle_{\mathcal O}$. From our hypothesis on the orbit ${\mathcal O}$, we have that $\tau(b_1) \ne b_1$ and $\tau(b_2) \ne b_2$. If $b_1$ is not on the principal diagonal, then $b_2 = \tau(b_1)$ is also not on the principal diagonal. If $i_1 > 0$ and $i_1 \ne 2$, then $i_2 = -i_1 + 2 < 0$. Thus we get that 
\begin{multline*}
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \\ =\langle f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} - f_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O} \\ (f_{i_1}(b_1) - f_{i_2}(b_2)) = 0
\end{multline*}
by lemma~\ref{L:RelationCoefficientsHandF} (b) and our definition of $\langle\  , \  \rangle_{\mathcal O}$.

If $i_1 < 0$, then $i_2 = - i_1 + 2 > 2$ and we get that 
\begin{multline*}
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \\ = -\langle f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O} + f_{i_2}(b_2) \langle v_{i_1}(b_1), v_{i_2 - 2}(b_2)\rangle_{\mathcal O} \\ (-f_{i_1}(b_1) + f_{i_2}(b_2))\epsilon = 0
\end{multline*}
by lemma~\ref{L:RelationCoefficientsHandF} (b) and our definition of $\langle\  , \  \rangle_{\mathcal O}$.

To conclude this case, we can observe that $i_1 \ne 2$. Otherwise $i_2 = 0$ and, by \ref{SS:EHFDefinition}, this means that $0 \in Supp(b_1) \cap Supp(b_2)$ and ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports contradicting our hypothesis on ${\mathcal O}$. 

Note that $b_1$ cannot be on the principal diagonal, otherwise $b_2 = \tau(b_1)$ is also on the principal diagonal and $Supp(b_2) = Supp(b_1)$. So ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports contradicting our hypothesis on ${\mathcal O}$. We also have $i_1 \ne 0$, otherwise ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports contradicting our hypothesis.

Consider now the case where the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports. If $i_1 = \min(Supp(b_1))$, then the proof is the same as when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and is left to the reader. As above we only have to consider the case where $i_1 \ne \min(Supp(b_1))$ and $i_2 \ne \min(Supp(b_2))$. Moreover if either $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} \ne 0$ or $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O} \ne 0$, then $b_2 = \tau(b_1)$ and $i_1 + i_2 - 2 = 0$.  Clearly if $b_1$ is below (respectively above, on) the principal diagonal, then $b_2$ is above (respectively below, on) the principal diagonal. In the case where the ${\mathcal I}$-boxes $b_1$ and $b_2$ are on the principal diagonal, then we will write $b_1 = b(i'_1, j'_1, k'_1)$ and $b_2 = \tau(b_1) = b(i'_1, j'_1, k''_1)$ where $i'_1, j'_1 \in {\mathcal I}$, $i'_1 \geq j'_1$ and $k''_1 \in \{k'_1, (1 - k'_1)\}$. More precisely, if $\mu_{\max} = 0$, then $k''_1 = k'_1$  and if $\mu_{\max} = 1$, then $k''_1 = (1 - k'_1)$.

We have that $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases}0, &\text{if $i_1 = \min(Supp(b_1))$;} \\ \langle f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 > 2$;}\\ \langle -f_{i_1}(b_1) v_{i_1 - 2}(b_1), v_{i_2}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 \ne \min(Supp(b_1))$ and $i_1 \leq 0$;}\\ \langle \epsilon f_{2}(b_1) v_{0}(b_1), v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 = 2$ and $b_1$ is below the principal diagonal;}\\ \langle f_{2}(b_1) v_{0}(b_1), v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 = 2$ and $b_1$ is above the principal diagonal;}\\ \langle \epsilon^{k'_1} f_{2}(b_1) v_{0}(b_1), v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_1 = 2$ and $b_1$ is on the principal diagonal;}\\
\end{cases}
\]
and $\langle v_{i_1}(b_1), F_{\mathcal O}(v_{i_2}(b_2))\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases}0, &\text{if $i_2 = \min(Supp(b_2))$;} \\ \langle v_{i_1}(b_1),  f_{i_2}(b_2) v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 > 2$;}\\ \langle  v_{i_1}(b_1), -f_{i_2}(b_2)v_{i_2 - 2}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 \ne \min(Supp(b_2))$ and $i_2 \leq 0$;}\\ \langle v_{0}(b_1),  \epsilon f_{2}(b_2) v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 = 2$ and $b_2$ is below the principal diagonal;}\\ \langle v_{0}(b_1),  f_{2}(b_2) v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 = 2$ and $b_2$ is above the principal diagonal;}\\ \langle  v_{0}(b_1), \epsilon^{k''_1} f_{2}(b_2) v_{0}(b_2)\rangle_{\mathcal O}, &\text{if $i_2 = 2$ and $b_2$ is on the principal diagonal.}\\
\end{cases}
\]

The proofs when $i_1 > 2$ and when $i_1 < 0$ are similar  to the proofs when the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports and are left to the reader. We will just consider the cases where $i_1 = 0$ and $i_1 = 2$.  

If $i_1 = 0$, then $i_2 = 2$. We have that  $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O}$ 
is equal to 
\[
-\langle f_0(b_1) v_{-2}(b_1), v_2(b_2)\rangle = -\epsilon f_0(b_1)
\]
when $b_1$ is either not on the principal diagonal or on the principal diagonal and  $\langle v_0(b_1), F_{\mathcal O}(v_2(b_2))\rangle_{\mathcal O}$ is equal to
\[
\begin{cases}
\langle v_0(b_1), \epsilon f_2(b_2) v_0(b_2)\rangle_{\mathcal O}, &\text{if $b_2$ is below the principal diagonal;}\\ \langle v_0(b_1),  f_2(b_2) v_0(b_2)\rangle_{\mathcal O}, &\text{if $b_2$ is above the principal diagonal;}\\ \langle v_0(b_1), \epsilon^{k''_1} f_2(b_2) v_0(b_2)\rangle_{\mathcal O}, &\text{if $b_2$ is on the principal diagonal.}\\
\end{cases}
\]

Thus $\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_0(b_1), F_{\mathcal O}(v_2(b_2))\rangle_{\mathcal O}$ is equal to 
\[
\begin{cases} (-\epsilon f_0(b_1) + \epsilon f_2(b_2))&\text{if $b_1$ is above the principal diagonal;}\\ (-\epsilon f_0(b_1) + \epsilon f_2(b_2))&\text{if $b_1$ is below the principal diagonal;}\\ (-\epsilon f_0(b_1) + \epsilon^{k''_1 + k'_1} f_2(b_2))&\text{if $b_1$ is on the principal diagonal and $\tau(b_1) \ne b_1$;}\\  (-\epsilon f_0(b_1) + \epsilon^{k''_1} f_2(b_2))&\text{if $b_1$ is on the principal diagonal and $\tau(b_1) =  b_1$.}\end{cases}
\]
If $b_1$ is not on the principal diagonal, then, by lemma~\ref{L:RelationCoefficientsHandF} (b), we get that 
\[
\langle F_{\mathcal O}(v_{i_1}(b_1)), v_{i_2}(b_2)\rangle_{\mathcal O} + \langle v_0(b_1), F_{\mathcal O}(v_2(b_2))\rangle_{\mathcal O} = 0. \quad\quad (**)
\]
If $b_1$ is on the principal diagonal and $\tau(b_1) = b_1$, then $\epsilon = 1$  by lemma~\ref{L:TauBox} (f). If $b_1$ is on the principal diagonal and $\tau(b_1) \ne b_1$, then $k''_1 = (1 - k'_1)$ and $\epsilon^{k''_1 + k'_1} = \epsilon$ by lemma~\ref{L:TauBox} (d).  In all cases, the equation $(**)$ is verified.

If $i_1 = 2$, then $i_2 = 0$ and we also get that $(**)$ is verified by symmetry. We have now prove that $\langle X(u), v\rangle_{\mathcal O} + \langle u, X(v)\rangle_{\mathcal O} = 0$ for all $X \in \{E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$ when $\vert {\mathcal I} \vert$ is odd.

We want to prove the Jacobson-Morozov triple relations in the case where $\vert {\mathcal I}\vert$ is odd. In other words, $[H_{\mathcal O}, E_{\mathcal O}] = 2E_{\mathcal O}$, $[H_{\mathcal O}, F_{\mathcal O}] = -2F_{\mathcal O}$ and $[E_{\mathcal O}, F_{\mathcal O}] = H_{\mathcal O}$. It is enough to verify these only on the ${\mathcal I}$-graded basis ${\mathcal B}_{\mathcal O}$ of $V({\mathcal O})$.

If the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then we have already computed above our expressions for $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$. Let $b \in {\mathbf B}$, an ${\mathcal I}$-box in the orbit ${\mathcal O}$ and $i \in Supp(b)$. Then $[H_{\mathcal O}, E_{\mathcal O}](v_i(b)) = (H_{\mathcal O} E_{\mathcal O} - E_{\mathcal O} H_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}&
\begin{cases}
0, &\text{if $i = \max(Supp(b))$;}\\ (h_{i + 2}(b) - h_i(b))v_{i + 2}(b), &\text{if $i \ne \max(Supp(b))$ and $i > 0$;}\\  (-h_{i + 2}(b) + h_i(b))v_{i + 2}(b), &\text{if $i \ne \max(Supp(b))$ and $i  < 0$;}\\
\end{cases}\\ &=(h_{i + 2}(b) - h_i(b)) E_{\mathcal O}(v_i(b)) = 2 E_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (c). We have also $[H_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (H_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} H_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}&
\begin{cases}
0, &\text{if $i = \min(Supp(b))$;}\\ (h_{i - 2}(b) - h_i(b))f_i(b)v_{i - 2}(b), &\text{if $i \ne \min(Supp(b))$ and $i > 0$;}\\  (-h_{i - 2}(b) + h_i(b))f_i(b)v_{i - 2}(b), &\text{if $i \ne \min(Supp(b))$ and $i  < 0$;}\\
\end{cases}\\ &=(h_{i - 2}(b) - h_i(b)) F_{\mathcal O}(v_i(b)) = -2 F_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (d).

We now need to compute $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b))$. Write $b = b(i_1, j_1, k_1)$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k_1 \leq \mu(i_1, j_1)$ and $i \in Supp(b)$.  Thus $i_1 \geq i \geq j_1$. We have different cases to consider. Because ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports, then either $j_1 > 0$ or $0 > i_1$.

If $i_1 = j_1 = i$, then we get easily that $i = \max(Supp(b)) = \min(Supp(b))$, $h_i(b) = 0$ and $(E_{\mathcal O}F_{\mathcal O} - F_{\mathcal O}E_{\mathcal O})(v_i(b)) = 0 = H_{\mathcal O}(v_i(b))$. 

If $i_1 > j_1$ and $i = i_1 = \max(Supp(b))$, then $f_i(b) = h_i(b)$ by lemma~\ref{L:RelationCoefficientsHandF} (f) and 
\[
\begin{aligned}
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O}E_{\mathcal O})(v_i(b)) &= \begin{cases} f_i(b) v_i(b),&\text{if $j_1 > 0$;}\\ f_i(b) v_i(b),&\text{if $i_1 < 0$;}\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b)).
\end{aligned}
\]

If $i_1 > j_1$ and $i = j_1 = \min(Supp(b))$, then $f_{i + 2}(b) = -h_i(b)$ by lemma~\ref{L:RelationCoefficientsHandF} (e) and 
\[
\begin{aligned}
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O}E_{\mathcal O})(v_i(b)) &= \begin{cases} -f_{i + 2}(b) v_i(b),&\text{if $j_1 > 0$;}\\ -f_{i + 2}(b) v_i(b),&\text{if $i_1 < 0$;}\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b)).
\end{aligned}
\]

If $i_1 > i > j_1$, then both $(i - 2), (i + 2) \in Supp(b)$. Thus they are both either simultanously $> 0$ or simultanously $< 0$. So $f_i(b) - f_{i + 2}(b) = h_i(b)$ by lemma~\ref{L:RelationCoefficientsHandF} (g) and 
\[
\begin{aligned}
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O}E_{\mathcal O})(v_i(b)) &= \begin{cases} (f_i(b) -f_{i + 2}(b)) v_i(b),&\text{if $j_1 > 0$;}\\ (f_i(b) - f_{i + 2}(b)) v_i(b),&\text{if $i_1 < 0$;}\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b)).
\end{aligned}
\]

If the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports, then we have already expressed above our expressions for $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ on ${\mathcal B}_{\mathcal O}$. Let $b = b(i_1, j_1, k_1)$ be an ${\mathcal I}$-box in ${\mathcal O}$ and $i \in Supp(b)$. We have that $[H_{\mathcal O}, E_{\mathcal O}](v_i(b)) = (H_{\mathcal O} E_{\mathcal O} - E_{\mathcal O} H_{\mathcal O})(v_i(b))$ is equal to
\[
\begin{aligned}
&\begin{cases}
0, &\text{if $i = \max(Supp(b))$;}\\ (h_{i + 2}(b) - h_i(b)) v_{i + 2}(b), &\text{if $i \ne \max(Supp(b))$ and $i > 0$;}\\ -(h_{i + 2}(b) - h_i(b)) v_{i + 2}(b), &\text{if $i  < 0$;}\\ \epsilon(h_{2}(b) - h_0(b)) v_{2}(b), &\text{if $i = 0$ and $b$ is below the principal diagonal;}\\(h_{2}(b) - h_0(b)) v_{2}(b), &\text{if $i = 0$ and $b$ is above the principal diagonal;}\\ \epsilon^{k_1}(h_{2}(b) - h_0(b)) v_{2}(b), &\text{if $i = 0$ and $b$ is on  the principal diagonal;;}
\end{cases}\\
&= 2 E_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (c). So $[H_{\mathcal O}, E_{\mathcal O}] = 2E_{\mathcal O}$.

Similarly we have $[H_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (H_{\mathcal O} F_{\mathcal O} - F_{\mathcal O}H_{\mathcal O})(v_i(b))$ is equal to  
\[
\begin{aligned}
&\begin{cases}
0, &\text{if $i = \min(Supp(b))$;}\\ (h_{i - 2}(b) - h_i(b)) f_i(b)v_{i - 2}(b), &\text{if $i > 2$;}\\ -(h_{i - 2}(b) - h_i(b))f_i(b) v_{i - 2}(b), &\text{if $i  \ne \min(Supp(b))$ and $i \leq 0$;}\\ \epsilon(h_{0}(b) - h_2(b)) f_2(b) v_{0}(b), &\text{if $i = 2$ and $b$ is below the principal diagonal;}\\(h_{0}(b) - h_2(b)) v_{0}(b), &\text{if $i = 2$ and $b$ is above the principal diagonal;}\\ \epsilon^{k_1}(h_{0}(b) - h_2(b)) f_2(b)v_{0}(b), &\text{if $i = 2$ and $b$ is on  the principal diagonal;;}
\end{cases}\\
&= -2 F_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (d). So $[H_{\mathcal O}, F_{\mathcal O}] = -2F_{\mathcal O}$.

Finally we want to compute $[E_{\mathcal O}, F_{\mathcal O}](v_i(b)) = (E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O}E_{\mathcal O})(v_i(b))$. We have $i_1 \geq i \geq j_1$. Because ${\mathcal O}$ has overlapping ${\mathcal I}$-support, then we have $i_1 \geq 0 \geq j_1$. We have different cases to consider.

If $i_1 = j_1 = i$, we have $i = \max(Supp(b)) = \min(Supp(b)) = 0$, $h_i(b) = 0$ and 
\[
(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b)) = 0 = H_{\mathcal O}(v_i(b)).
\]

We now consider $i_1 > j_1$.  There are three cases to study: $i_1 = i$, $j_1 = i$ and $i_1 > i > j_1$.  If $i_1 = i > j_1$, then $i = \max(Supp(b))$ and $(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b)) = E_{\mathcal O} F_{\mathcal O}(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases} f_i(b) v_i(b), &\text{if $i > 2$;}\\ \epsilon^2 f_2(b)v_2(b), &\text{if $i = 2$ and $b$ is below the principal diagonal;}\\ f_2(b)v_2(b), &\text{if $i = 2$ and $b$ is above the principal diagonal;}\\ (\epsilon)^{2k_1} f_2(b)v_2(b), &\text{if $i = 2$ and $b$ is on the principal diagonal;}\\ f_0(b) v_0(b), &\text{if $i = 0$;}
\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (f).

If $i_1 > i = j_1$, then $i = \min(Supp(b))$ and $(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b)) = -F_{\mathcal O} E_{\mathcal O}(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases} - \epsilon^2 f_2(b) v_0(b), &\text{if $i = 0$ and $b$ is below the principal diagonal;}\\  - f_2(b) v_0(b), &\text{if $i = 0$ and $b$ is above the principal diagonal;}\\ - (\epsilon)^{2k_1} f_2(b) v_0(b), &\text{if $i = 0$ and $b$ is on the principal diagonal;}\\ - f_{i + 2}(b)v_i(b), &\text{if $i < 0$;}
\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (e).

Finally if $i_1 > i > j_1$, then $(i + 2), (i - 2) \in Supp(b)$ and $(E_{\mathcal O} F_{\mathcal O} - F_{\mathcal O} E_{\mathcal O})(v_i(b))$ is equal to 
\[
\begin{aligned}
&\begin{cases}
(f_i(b) - f_{i + 2}(b))v_i(b), &\text{if $i > 2$;}\\
(\epsilon^2 f_2(b) - f_4(b)) v_2(b), &\text{$i = 2$ and $b$ is below the principal diagonal;}\\
(f_2(b) - f_4(b)) v_2(b), &\text{$i = 2$ and $b$ is above the principal diagonal;}\\
((\epsilon)^{2k_1} f_2(b) - f_4(b)) v_2(b), &\text{$i = 2$ and $b$ is on the principal diagonal;}\\
(f_0(b) - \epsilon^2 f_2(b)) v_0(b), &\text{$i = 0$ and $b$ is below the principal diagonal;}\\
(f_0(b) - f_2(b)) v_0(b), &\text{$i = 0$ and $b$ is above the principal diagonal;}\\
(f_0(b) - (\epsilon)^{2k_1}f_2(b)) v_0(b), &\text{$i = 0$ and $b$ is on the principal diagonal;}\\
(f_i(b) - f_{i + 2}(b))v_i(b), &\text{if $i \leq -2$;}
\end{cases}\\
&= h_i(b) v_i(b) = H_{\mathcal O}(v_i(b))
\end{aligned}
\]
by lemma~\ref{L:RelationCoefficientsHandF} (g).

Thus we have proved that the triple $E_{\mathcal O}$, $H_{\mathcal O}$ and $F_{\mathcal O}$ is an ${\mathcal I}$-graded  Jacobson-Morozov triple when $\vert {\mathcal I} \vert$ is odd.

We now want to prove that 
\[
\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \mid \text{ ${\mathcal O}$
belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}
\]
is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-represen~- tations of $(\Omega, \sigma)$ when $\vert {\mathcal I} \vert$ is odd.

Let the ${\mathcal I}$-box $b = b(i_1, j_1, k_1) \in {\mathbf B}$ be an element of the $\langle \tau \rangle$-orbit ${\mathcal O}$ with $i_1, j_1 \in {\mathcal I}$, $i_1 \geq j_1$ and $0 \leq k_1 \leq \mu(i_1, j_1)$. If we consider the restriction of $E_{\mathcal O}$ to $V_i(b)$: $\phi_{b, i} = E_{\mathcal O}\vert_{V_i(b)}:V_i(b) \rightarrow V_{i + 2}(b)$ for each $i \in Supp(b)$, $i \ne \max(Supp(b))$, we get a representation $\phi_b:V(b) \rightarrow V(b)$ of the quiver $\Omega$ of type $A_{2m-1}$. Here $\vert {\mathcal I} \vert = (2m - 1)$. From our definition of $E_{\mathcal O}$, we get easily that 
\begin{itemize}
\item $\phi_b$ is an indecomposable representation of $A_{2m-1}$ of dimension $\dim(\phi_b) = (\beta_i)_{i \in {\mathcal I}}$ where 
\[
\beta_i = \begin{cases} 1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise.}\end{cases}
\]
\item $\phi_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$ is the direct sum $\oplus_{b \in {\mathcal O}} \phi_b$ as a representation of $A_{2m-1}$.
\end{itemize}
Because $\langle E_{\mathcal O}(u), v\rangle_{\mathcal O} + \langle u, E_{\mathcal O}(v)\rangle_{\mathcal O} = 0$ for all $u, v \in V({\mathcal O})$, then $(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ is an $\epsilon$-representation. To show that $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$ is  indecomposable, we can use theorem~\ref{T:CaracterisationRepresentation}.

Each $\langle \tau \rangle$-orbit ${\mathcal O}$ contains at least one ${\mathcal I}$-box $b = b(i_1, j_1, k_1) \in {\mathbf B}$ such that $(i_1 + j_1) \geq 0$. If $(i_1 + j_1) > 0$, this ${\mathcal I}$-box is unique in the orbit, while if $(i_1 + j_1) = 0$, then there are $\mu_{\max}$ ${\mathcal I}$-boxes in the orbit. If $(i_1 + j_1) > 0$, then $\tau(b) \ne b$ and ${\mathcal O} = \{b, \tau(b)\}$. We have $i_1 \geq j_1$ and $i_1 \geq \vert j_1 \vert$ because  $(i_1 + j_1) > 0$.  As in the definition~\ref{DefDim}, we will write the dimension vector of $(V_{\mathcal O}, \phi_{\mathcal O}, \langle\  , \  \rangle)$ as representation of the symmetric quiver $(\Omega, \sigma)$ by
\[
\dim(V_{\mathcal O})  = (\dim(V_{{\mathcal O}, i}))_{i \in {\mathcal I}_+} = (\alpha_i)_{i \in {\mathcal I}_+} = \alpha.
\]
We will write also the dimension of $\dim(\phi_b)$ and $\dim(\phi_{\tau(b)})$ as
\[
\dim(\phi_b) = \beta' = (\beta'_i)_{i \in {\mathcal I}} \quad \text{ and } \quad  \dim(\phi_{\tau(b)}) = \beta = (\beta_i)_{i \in {\mathcal I}}.
\]  

If $j_1 > 0$, then 
\[
\beta_i = \begin{cases}1, &\text{if $-j_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases} \quad  \quad 
\beta'_i = \begin{cases}1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;} \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  1,&\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$.  Using proposition~\ref{Decomposition_odd} (a) (i) and (b)(i)  and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$.

If $0 > j_1$, then 
\[
\beta_i = \begin{cases}1, &\text{if $-j_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases} \quad  \quad 
\beta'_i = \begin{cases}1, &\text{if $i_1 \geq i \geq j_1$;}\\ 0, &\text{otherwise;} \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  2,&\text{if $\vert j_1\vert  \geq i \geq 0$;}\\ 1,&\text{if $i_1 \geq i > \vert j_1 \vert$;}\\ 0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$.  Using proposition~\ref{Decomposition_odd} (a) (iii) and (b)(iii)  and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$.

If $(i_1 + j_1) = 0$, then the ${\mathcal I}$-box $b(i_1, j_1, k_1)$ is on the principal diagonal and $i_1 \geq 0$, because $i_1 \geq j_1$. There are two cases to consider: either $\tau(b) \ne b$ or $\tau(b) = b$. When $\tau(b) \ne b$, then ${\mathcal O} = \{b, \tau(b)\}$ and by lemma~\ref{L:TauBox} (d) and \ref{SS:Iset}, we have that $\mu_{\max} = 1$, $\epsilon = -1$, $\tau(b) = b(i_1, j_1, (1 - k_1))$. So 
\[
\beta'_i = \beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  2,&\text{if $i_1 \geq i \geq 0$;}\\  0, &\text{otherwise;}\end{cases}
\]
for $i \in {\mathcal I}_+$. Using proposition~\ref{Decomposition_odd} (b) (ii) and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha$. 

When $\tau(b) = b$, then ${\mathcal O} = \{b \}$ and by lemma~\ref{L:TauBox} (e), $\mu_{\max} = 0$, $\epsilon = 1$, $V({\mathcal O}) = V_b$. We will write $\dim(\phi_b) = \beta = (\beta_i)_{i \in {\mathcal I}}$. So 
\[
\beta_i = \begin{cases}1, &\text{if $i_1 \geq i \geq -i_1$;}\\ 0, &\text{otherwise; } \end{cases}
\]
for $i \in {\mathcal I}$ and 
\[
\alpha_i =\begin{cases}  1,&\text{if $i_1 \geq i \geq 0$;}\\  0, &\text{otherwise.}\end{cases}
\]
for $i \in {\mathcal I}_+$. Using proposition~\ref{Decomposition_odd} (a) (ii)  and theorem~\ref{T:CaracterisationRepresentation}, this shows that $\phi_{\mathcal O}$ is indecomposable and isomorphic to the indecomposable representation of dimension $\alpha^1$. 

To finish the proof when $\vert {\mathcal I} \vert$ is odd, it suffices to notice by inspection of the dimension vectors of $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$,  the direct sum decomposition $\phi_{\mathcal O} = \oplus_{b \in {\mathcal O}} \phi_b$ and theorem~\ref{T:CaracterisationRepresentation}, that $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ and $(V({\mathcal O'}), \phi_{\mathcal O'}, \langle\  , \  \rangle_{\mathcal O'})$ are not isomorphic for two distinct $\langle \tau \rangle$-orbits ${\mathcal O}$ and ${\mathcal O}'$. By remark~\ref{R:CardinalityIndecomposable}, we get the result that $\{(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \mid \text{ ${\mathcal O}$  belongs to the set of $\langle \tau \rangle$-orbits  in ${\mathbf B}$}\}$   is a set of representatives of the isomorphism classes of indecomposable $\epsilon$-representations of $(\Omega, \sigma)$.
\end{proof}

We will need the following lemma and notation in statements, formulas and propositions for the next sections.

% lemma  2.17
\begin{lemma}
Let $b = b(i, j, k) \in{\mathbf B}$, where $i, j \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$,  and $i_1, i_2 \in Supp(b) \subseteq {\mathcal I}$. Then $i_1 - h_{i_1}(b) = i_2 - h_{i_2}(b) = (i + j)/2$.
\end{lemma} 
\begin{proof}
We can assume that $i_1 > i_2$. Note that $i_1$ and $i_2$ have the same parity by definition of ${\mathcal I}$. So $i_1 = i_2 + 2s$ where $s \in {\mathbb N}$. We have
\[
\begin{aligned}
i_1 - h_{i_1}(b) &= (i_1) - \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq  i_1\}  + \#\{i'' \in {\mathcal I}  \mid i_1 \leq i'' \leq i \}\\
&= (i_2 + 2s) - ( \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq  i_2 \}  + s) + (\#\{ i'' \in {\mathcal I}  \mid i_2 \leq i'' \leq i\} - s)\\ &= i_2 - h_{i_2}(b).
\end{aligned}
\]
If we now consider $i_1 = i$, then 
\[
i - h_i(b) = i - \#\{j'' \in {\mathcal I} \mid j \leq j'' \leq  i\}  + \#\{i'' \in {\mathcal I}  \mid i \leq i'' \leq i \} = \frac{(i + j)}{2}
\]
\end{proof}

% notation 2.18
\begin{notation}\label{N:LambdaValue}
We will denote the above constant value by $\lambda(b)$.  So for $b = b(i, j, k)$ as above, we have $\lambda(b) = (i + j)/2$. 
\end{notation}

%2.19
\subsection{} In the case where $\vert {\mathcal I} \vert$ is odd and $\epsilon = 1$, more precisely in the orthogonal case for the symmetric quiver $A_m^{odd}$, we have associated to each $\langle \tau \rangle$-orbit ${\mathcal O}$: an orthogonal isomorphism class of indecomposable orthogonal representations $( V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$. Two such indecomposable orthogonal representations in the same orthogonal isomorphism class of representations are not necessarily isomorphic relative to the special orthogonal group.  With the notation of lemma~\ref{L:DetThetaAOdd}, we have $\det(\theta_0) = \pm 1$, but not necessarily $\det(\theta_0) = 1$.  

To conclude this section, we will now discuss  how an orthogonal isomorphism class of indecomposable orthogonal representations splits into isomorphism classes relative to the special orthogonal group.  We will also give an ${\mathcal I}$-graded  Jacobson-Morozov triple for each isomorphism class relative to the special orthogonal group. 


%2.20
\subsection {}\label{SS:SpecialOrthoRepresentationsInSameOrthoClass}
Let $(\Omega, \sigma)$ be the symmetric quiver $A_m^{odd}$ and $\epsilon = 1$. Recall that 
\[
{\mathcal I} = \{i \in {\mathbb Z} \mid i \equiv 0 \pmod 2 \text{ and } -2m <  i  < 2m\}.
\]
Let $b = b(i_1, j_1, 0)$ be an ${\mathcal I}$-box such that $i_1, j_1 \in {\mathcal I}$, $i_1 \geq 0 \geq j_1$ and $i_1 + j_1 \ne 0$. Then we have easily  that  
\begin{itemize}
\item $\tau(b) = b(-j_1, -i_1, 0) \ne b$;
\item the orbit ${\mathcal O}$ of $b$ is $\{b, \tau(b)\}$ and has overlapping ${\mathcal I}$-box supports;
\item $Supp(b) = \{ i \in {\mathcal I} \mid i_1 \geq i \geq j_1\}$ and $Supp(\tau(b)) = \{ i \in {\mathcal I} \mid -j_1 \geq i \geq -i_1\}$;
\end{itemize} 
In the following, we will assume that $b$ is such that $i_1 + j_1 > 0$. Otherwise we just need to interchange $b$ and $\tau(b)$. By this hypothesis, we get that $i_1 > \vert j_1 \vert \geq j_1$. 

In this case, 
\[
V({\mathcal O}) = \oplus_{i \in {\mathcal I}} V_i({\mathcal O}), \quad \text{where} \quad \dim(V_i({\mathcal O})) = \begin{cases}2, &\text{if $j_1 \leq \vert i \vert  \leq \vert j_1 \vert$;}\\ 1, &\text{if $\vert j_1\vert  < \vert i \vert \leq i_1$;}\\ 0, &\text{otherwise.}
\end{cases}
\]
We have constructed a basis ${\mathcal B}_{\mathcal O}$ for $V({\mathcal O})$ in \ref{N:BasisVOrbit}.  From this, we get that $V_i({\mathcal O})$ has basis
\[
\begin{cases} \{v_i(b), v_i(\tau(b))\}, &\text{if $j_1 \leq i \leq \vert j_1\vert$;} \\ \{v_i(b) \} &\text{if $\vert j_1\vert  < i \leq i_1$;}\\  \{v_i(\tau(b)) \} &\text{if $-i _1  \leq i < j_1$;} \end{cases}
\]
and we have also expressed the values of the bilinear form $\langle \ , \ \rangle_{\mathcal O}$  and  the action of $E_{\mathcal O}$ on these basis vectors.

We have constructed the ${\mathcal I}$-graded Jacobson-Morozov triple $(E_{\mathcal O}, H_{\mathcal O}, F_{\mathcal O})$ and an orthogonal representation $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ in \ref{SS:EHFDefinition} and in the proposition~\ref{P:JMTripleProof}.

Consider now the  linear transformation $S:V({\mathcal O}) \rightarrow V({\mathcal O})$ defined on the basis ${\mathcal B}_{\mathcal O}$ as follows: 
\[
S(u) = \begin{cases} u, &\text{if $u \in V_i({\mathcal O})$ with $i \ne 0$;}\\ v_0(\tau(b)), &\text{if $i = 0$ and $u = v_0(b)$;}\\ v_0(b), &\text{if $i = 0$ and $u = v_0(\tau(b))$.} \end{cases}
\]
It is obviously a ${\mathcal I}$-graded  linear transformation of degree $0$ and it is an involution.

From our definition of $\langle\  , \  \rangle_{\mathcal O}$, we get easily  that $\langle S(u), S(v) \rangle_{\mathcal O} = \langle u, v \rangle_{\mathcal O}$ for all $u, v \in V({\mathcal O})$. Set $E'_{\mathcal O} = S E_{\mathcal O} S$, $H'_{\mathcal O} = S H_{\mathcal O} S$ and $F'_{\mathcal O} = S F_{\mathcal O} S$. We also get easily that 
\begin{itemize}
\item $E'_{\mathcal O}$ is of degree 2, $H'_{\mathcal O}$ is of degree 0 and $F'_{\mathcal O}$ is of degree -2;
\item $\langle Xu, v\rangle + \langle u, Xv\rangle = 0$ for all $X \in \{E'_{\mathcal O}, H'_{\mathcal O}, F'_{\mathcal O}\}$ and all $u, v \in V({\mathcal O})$;
\item $[H'_{\mathcal O}, E'_{\mathcal O}] = 2E'_{\mathcal O}$, $[H'_{\mathcal O}, F'_{\mathcal O}] = -2F'_{\mathcal O}$ and $[E'_{\mathcal O}, F'_{\mathcal O}] = H'_{\mathcal O}$, in other words,  $(E'_{\mathcal O}, H'_{\mathcal O}, F'_{\mathcal O})$ is an ${\mathcal I}$-graded  Jacobson-Morozov triple;
\item  the ${\mathcal I}$-graded linear transformation $\phi'_{\mathcal O}: V({\mathcal O}) \rightarrow V({\mathcal O})$ given by 
\[
\phi'_{{\mathcal O}, i} = {E'_{\mathcal O}}\vert_{V_i({\mathcal O})}: V_{i}({\mathcal O}) \rightarrow V_{i + 2}({\mathcal O}) \quad \text{for all $i \in {\mathcal I}$  such that $(i + 2) \in {\mathcal I}$},
\]
is  such that $(V({\mathcal O}), \phi'_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ is an  orthogonal representation.
\end{itemize}

From our construction, we get that $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ and $(V({\mathcal O}), \phi'_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ are isomorphic relative to the orthogonal group with the isomorphism  given by 
\[
S:(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O}) \rightarrow (V({\mathcal O}), \phi'_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O}).
\]

We will now show that these two orthogonal representations  $(V_{\mathcal O}, \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ and $(V_{\mathcal O}, \phi'_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ are not isomorphic relatively to the special orthogonal group.

Assume that $\theta:(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \rightarrow (V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$, $\theta':(V({\mathcal O}), \phi'_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \rightarrow (V({\mathcal O}), \phi'_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ and $\theta'':(V({\mathcal O}), \phi_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O}) \rightarrow (V({\mathcal O}), \phi'_{\mathcal O}, \langle\ , \ \rangle_{\mathcal O})$ are orthogonal isomorphisms for these orthogonal representations. In other words, there are isomorphisms $\theta_i:V_i({\mathcal O}) \rightarrow V_i({\mathcal O})$ (respectively  $\theta'_i:V_i({\mathcal O}) \rightarrow V_i({\mathcal O})$,  $\theta''_i:V_i({\mathcal O}) \rightarrow V_i({\mathcal O})$) for each $i \in {\mathcal I}$, $\vert i \vert \leq i_1$ such that 
\begin{itemize}
\item $\langle \theta_i(u), \theta_{-i}(v)\rangle_{\mathcal O} = \langle u, v\rangle_{\mathcal O}$  (resp.  $\langle \theta'_i(u), \theta'_{-i}(v)\rangle_{\mathcal O} = \langle u, v\rangle_{\mathcal O}$ , $\langle \theta''_i(u), \theta''_{-i}(v)\rangle_{\mathcal O} = \langle u, v\rangle_{\mathcal O}$ ) for all $u \in V_i({\mathcal O})$ and $v \in V_{-i}({\mathcal O})$;
\item $\theta_{i + 2}\circ  \phi_{{\mathcal O}, i} = \phi_{{\mathcal O}, i} \circ \theta_i$ (respectively $\theta'_{i + 2}\circ  \phi'_{{\mathcal O}, i} = \phi'_{{\mathcal O}, i} \circ \theta'_i$ , $\theta''_{i + 2}\circ  \phi_{{\mathcal O}, i} = \phi'_{{\mathcal O}, i} \circ \theta''_i$) 
for all $i \in {\mathcal I}$ and $\vert i \vert < i_1$;
\item $\det(\theta_i) \ne 0$ and $\det(\theta_{-i}) = (\det(\theta_i))^{-1}$  (respectively  $\det(\theta'_i) \ne 0$ and $\det(\theta'_{-i}) = (\det(\theta'_i))^{-1}$ ,  $\det(\theta''_i) \ne 0$ and $\det(\theta''_{-i}) = (\det(\theta''_i))^{-1}$ ) for all $i \in {\mathcal I}$, $\vert i \vert \leq i_1$.
\end{itemize}

%lemma 2.21
\begin{lemma}\label{L:DeterminantTheta0} With the above notation, we have that
\begin{enumerate}[\upshape (a)]
\item $\det(\theta_0) = 1$;
\item $\det(\theta'_0) = 1$;
\item $\det(\theta''_0) = -1$.
\end{enumerate}
\end{lemma}
%Proof
\begin{proof}
From our hypothesis, we have $i_1 > \vert j_1 \vert$.  $V_0({\mathcal O})$ has $\{v_0(b), v_0(\tau(b))\}$ and we know how the elements $E_{\mathcal O}$ and $E'_{\mathcal O}$ act on these vectors.  Write 
\[
\left\{
\begin{aligned}
\theta_0(v_0(b)) &= \alpha v_0(b) + \gamma v_0(\tau(b))\\ \theta_0(v_0(\tau(b))) &= \beta v_0(b) + \xi v_0(\tau(b))
\end{aligned}
\right.
\]
\[
\left\{
\begin{aligned}
\theta'_0(v_0(b)) &= \alpha' v_0(b) + \gamma' v_0(\tau(b))\\ \theta'_0(v_0(\tau(b))) &= \beta' v_0(b) + \xi' v_0(\tau(b))
\end{aligned}
\right. 
\] 
and 
\[
\left\{
\begin{aligned}
\theta''_0(v_0(b)) &= \alpha'' v_0(b) + \gamma'' v_0(\tau(b))\\ \theta''_0(v_0(\tau(b))) &= \beta'' v_0(b) + \xi'' v_0(\tau(b))
\end{aligned}
\right. 
\] 
where $\alpha, \beta, \gamma, \xi, \alpha', \beta', \gamma', \xi', \alpha'', \beta'', \gamma'', \xi'' \in {\mathbf k}$.  
Because 
\[
\langle \theta_0(u), \theta_{0}(v)\rangle_{\mathcal O} = \langle u, v\rangle_{\mathcal O}, \     \langle \theta'_0(u), \theta'_{0}(v)\rangle_{\mathcal O}  = \langle u, v\rangle_{\mathcal O} \text{ and  }  \langle \theta''_0(u), \theta''_{0}(v)\rangle_{\mathcal O}  = \langle u, v\rangle_{\mathcal O} 
\]
for all $u, v \in V_0({\mathcal O})$, we get by considering the following  pairs: $(u, v) = (v_0(b), v_0(b))$, $(v_0(\tau(b)), v_0(\tau(b)))$ and $(v_0(b), v_0(\tau(b)))$, we will get easily that 
\begin{itemize}
\item $2\alpha \gamma = 0$, \quad  $2\alpha' \gamma' = 0$, \quad  $2\alpha'' \gamma'' = 0$; 
\item $2\beta \xi = 0$,\quad  $2\beta' \xi' = 0$, \quad $2\beta'' \xi'' = 0$; 
\item $\alpha\xi + \gamma \beta = 1$,\quad  $\alpha'\xi' + \gamma' \beta' = 1$ \quad and \quad $\alpha'' \xi'' + \gamma'' \beta'' = 1$.
\end{itemize}

Note that $V_{(\vert j_1 \vert +2)}({\mathcal O})$ has dimension $1$ and $\{v_{(\vert j_1 \vert + 2)}(b)\}$ is a basis of  $V_{(\vert j_1 \vert +2)}({\mathcal O})$. Also we have that  $\theta_{(\vert j_1 \vert + 2)}:V_{(\vert j_1 \vert +2)}({\mathcal O}) \rightarrow V_{(\vert j_1 \vert +2)}({\mathcal O})$,  $\theta'_{(\vert j_1 \vert + 2)}:V_{(\vert j_1 \vert +2)}({\mathcal O}) \rightarrow V_{(\vert j_1 \vert +2)}({\mathcal O})$ and $\theta''_{(\vert j_1 \vert + 2)}:V_{(\vert j_1 \vert +2)}({\mathcal O}) \rightarrow V_{(\vert j_1 \vert +2)}({\mathcal O})$ are isomorphisms. Thus $\theta(v_{(\vert j_1 \vert + 2)}(b)) = \chi v_{(\vert j_1 \vert + 2)}(b)$, $\theta'(v_{(\vert j_1 \vert + 2)}) = \chi' v_{(\vert j_1 \vert + 2)}(b)$ and $\theta''(v_{(\vert j_1 \vert + 2)}(b)) = \chi'' v_{(\vert j_1 \vert + 2)}(b)$ with $\chi, \chi', \chi'' \in {\mathbf k}$, $\chi \ne 0$, $\chi' \ne 0$ and $\chi'' \ne 0$.

(a) We have 
\[
\phi_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi_{{\mathcal O}, 2} \circ \phi_{{\mathcal O}, 0} \circ \theta_0 = \theta_{(\vert j_1 \vert + 2)} \circ \phi_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi_{{\mathcal O}, 2} \circ \phi_{{\mathcal O}, 0}
\]
If we evaluate this expression on each of the basis vectors of $V_0({\mathcal O})$, we get
\[
\begin{cases} v_0(b) \mapsto \alpha v_{(\vert j_1\vert + 2)}(b)\\ v_0(\tau(b)) \mapsto \beta v_{(\vert j_1 \vert + 2)}(b)\end{cases} \quad \text{ for the left side map }
\]
and
\[
\begin{cases} v_0(b) \mapsto \chi v_{(\vert j_1\vert + 2)}(b)\\ v_0(\tau(b)) \mapsto 0\end{cases} \quad  \text{ for the right side map.}
\]
Thus $\beta = 0$ and we get that $\alpha \xi = 1$ and $\det(\theta_0) = 1$.

(b) We have 
\[
\phi'_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi'_{{\mathcal O}, 2} \circ \phi'_{{\mathcal O}, 0} \circ \theta'_0 = \theta'_{(\vert j_1 \vert + 2)} \circ \phi'_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi'_{{\mathcal O}, 2} \circ \phi'_{{\mathcal O}, 0}
\]
If we evaluate this expression on each of the basis vectors of $V_0({\mathcal O})$, we get
\[
\begin{cases} v_0(b) \mapsto \gamma' v_{(\vert j_1\vert + 2)}(b)\\ v_0(\tau(b)) \mapsto \xi' v_{(\vert j_1 \vert + 2)}(b)\end{cases} \quad \text{ for the left side map }
\]
and
\[
\begin{cases} v_0(b) \mapsto 0\\ v_0(\tau(b)) \mapsto \chi' v_{(\vert j_1\vert + 2)}(b)\end{cases} \quad  \text{ for the right side map.}
\]
Thus $\gamma' = 0$ and we get that $\alpha' \xi' = 1$ and $\det(\theta'_0) = 1$.

(c) We have 
\[
\phi'_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi'_{{\mathcal O}, 2} \circ \phi'_{{\mathcal O}, 0} \circ \theta''_0 = \theta''_{(\vert j_1 \vert + 2)} \circ \phi_{{\mathcal O}, \vert j_1 \vert} \circ \dots \circ \phi_{{\mathcal O}, 2} \circ \phi_{{\mathcal O}, 0}
\]
If we evaluate this expression on each of the basis vectors of $V_0({\mathcal O})$, we get
\[
\begin{cases} v_0(b) \mapsto \gamma'' v_{(\vert j_1\vert + 2)}(b)\\ v_0(\tau(b)) \mapsto \xi'' v_{(\vert j_1 \vert + 2)}(b)\end{cases} \quad \text{ for the left side map }
\]
and
\[
\begin{cases} v_0(b) \mapsto \chi'' v_{(\vert j_1\vert + 2)}(b)\\ v_0(\tau(b)) \mapsto 0\end{cases} \quad  \text{ for the right side map.}
\]
Thus $\xi'' = 0$ and we get that $\gamma'' \beta'' = 1$ and $\det(\theta''_0) = -1$.
\end{proof}

%remark 2.22
\begin{remark}\label{SS:ExampleIsomorphismSpecialOrtho}
So $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ and $(V({\mathcal O}), \phi'_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ are isomorphic relative to the orthogonal group, but not isomorphic relative to the special orthogonal group. Because the index of the special orthogonal subgroup in the orthogonal group is 2, we get that any representation $(V_{\mathcal O}, \phi''_{\mathcal O}, \langle\  ,  \  \rangle_{\mathcal O})$ isomorphic relative to the orthogonal group to either isomorphic to $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ or $(V({\mathcal O}), \phi'_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ relative to the special orthogonal group. In other words, the orthogonal isomorphism class of $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ splits into two isomorphism classes relatively to the special orthogonal group.

Note it is easy to see that if ${\mathcal O}$ is the $\langle \tau \rangle$-orbit of the ${\mathcal I}$-box $b = b(i_1, j_1, 0) \in {\mathbf B}$ such that either $i_1 + j_1 = 0$ or $i_1 \geq j_1 > 0$ or $0 > i_1 \geq j_1$, then the orthogonal isomorphism class of $(V({\mathcal O}), \phi_{\mathcal O}, \langle\  , \  \rangle_{\mathcal O})$ does not split and is a unique special orthogonal group isomorphism class.  
\end{remark}


%section 3
\section{$G^{\iota}$-orbits in ${\mathfrak g}_2$ when $\vert {\mathcal I}\vert$ is even.}

%3.1
\subsection{}\label{S:SetUpAeven}
In this section,  
\begin{itemize}
\item $m$ is an integer $> 0$;
\item $G$ is the connected component of the identity element of the group of automorphisms of a finite dimensional vector space $V$ over ${\mathbf k}$ preserving a fixed non-degenerate symmetric (respectively skew-symmetric) bilinear form $\langle\ , \  \rangle: V \times V \rightarrow {\mathbf k}$, in other words  $G = SO(V)$ (respectively $G = Sp(V)$); 
\item $\mathfrak g$ is the Lie algebra of $G$, more precisely $X \in {\mathfrak g}$ if and only if $X:V \rightarrow V$ is an endomorphism of $V$ such that $\langle X(v_1), v_2\rangle + \langle v_1 , X(v_2) \rangle = 0$ for all $v_1, v_2 \in V$;
\item $V$ is identified to its dual $V^*$ by the isomorphism $\phi: V \rightarrow V^*$ defined by $v \mapsto \phi_v$, where $\phi_v: V \rightarrow {\mathbf k}$ is $\phi_v(x) = \langle v, x\rangle$ for all $x \in V$;  
\item ${\mathcal I} = \{n \in {\mathbb Z} \mid n \equiv 1 \pmod 2, -2m <  n < 2m \}$;
\item $\oplus_{i \in {\mathcal I}} V_i$ is a direct sum decomposition of $V$ by  vector subspaces $V_i \ne 0$ for all $i \in {\mathcal I}$ such that 
\begin{itemize} \item $\langle v, v'\rangle = 0$ whenever $v \in V_i$, $v' \in V_j$ and $i + j \ne 0$;
			\item $V_{-i} = V_i^*$ for all $i \in {\mathcal I}$ under the identification given by $\phi$ above;
\end{itemize} 
\item ${\mathcal B} = \coprod_{i\in {\mathcal I}} {\mathcal B}_i$ is a basis of $V$ such that each ${\mathcal B}_i = \{u_{i, j} \mid 1 \leq j \leq \delta_i \}$  is a basis of $V_i$ for each $i \in {\mathcal I}$, where $\delta_i$ is the dimension of $V_i$. Moreover these bases are such that, for $i, j \in {\mathcal I}$, $1 \leq r \leq \delta_i$, $1 \leq s \leq \delta_j$, we have
\[
\langle u_{i, r}, u_{j, s}\rangle = \begin{cases} 1, &\text{if $i + j = 0$, $r = s$ and $i > 0$;}\\ \epsilon, &\text{if $i + j = 0$, $r = s$ and $i < 0$;}\\ 0, &\text{otherwise.} \end{cases}
\]
\item $\iota: {\mathbf k}^{\times} \rightarrow G$ is the homomorphism defined by $\iota(t) v = t^i v$ for all $i \in {\mathcal I}$, $v \in V_i$ and $t \in {\mathbf k}^{\times}$;
\item ${\mathbf B}$ is the set of ${\mathcal I}$-boxes;
\item ${\mathbf B}/\tau$ denote the set of $\langle \tau \rangle$-orbits ${\mathcal O}$ in ${\mathbf B}$; 
\item $\nu = \vert {\mathbf B}/\tau \vert = m(m + 1)$;
\end{itemize}

%lemme 3.2
\begin{lemma}\label{G2AsRepresEven}
\begin{enumerate}[\upshape (a)]
% (a)
\item $g \in G^{\iota}$ if and only if all the following conditions are verified:
\begin{itemize}
\item $g(V_i) \subseteq V_i$   for all $i  \in {\mathcal I}$;
\item the restriction $g_{\vert_{V_i}} = g_i$ of $g$ to $V_i$  belongs to $GL(V_i)$ for all $i \in {\mathcal I}$;
\item $g_{-i}^* g_{i} = Id_{V_i}$ for all $i \in {\mathcal I}$.
\end{itemize}
Here $g_{-i}^*: V_{i} \rightarrow V_{i}$ is defined using the identification of $V_{i}$ with $V_{-i}^*$ given by $\phi$.  So $\langle g_{-i}^* (u), v \rangle = \langle u, g_{-i}(v) \rangle$ for all $u \in V_{i}$ and $v \in V_{-i}$. 


% (b)
\item $X \in {\mathfrak g}_2$  if and only if all the following conditions are verified:
\begin{itemize}
\item $X(V_i) \subseteq V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 1)$;
\item $X_{-i} = -X_{i - 2}^T$ for all $i \in {\mathcal I}$  and $i \geq 3$;
\item $X_{-1} = -\epsilon X_{-1}^T$;
\end{itemize}
where $X_i$ is the matrix of the linear transformation $X\vert_{V_i}: V_i \rightarrow V_{i + 2}$ of the restriction of $X$ to $V_i$ relative to the bases ${\mathcal B}_i$ and ${\mathcal B}_{i + 2}$ and $X_i^T$ is its transpose for all $i \in {\mathcal I}$ with $i \ne (2m - 1)$. Moreover the subset of elements 
\[
(X_i)_{\begin{subarray}{l} i \in {\mathcal I} \\ i \ne (2m - 1)\end{subarray}} \in \left(\bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ i \ne (2m - 1)\end{subarray}} Hom(V_i, V_{i + 2})\right),
\]
  such that the above conditions for the $X_i$ are satisfied,  is a subspace of 
  \[
  \bigoplus_{\begin{subarray}{c} i \in {\mathcal I} \\ i \ne (2m - 1)\end{subarray}} Hom(V_i, V_{i + 2})
  \]
   isomorphic to ${\mathfrak g}_2$.

% (c)
 \item $Z \in {\mathfrak g}_0$ if and only if all the following conditions are verified:
\begin{itemize}
\item $Z(V_i) \subseteq V_{i}$ for all $i \in {\mathcal I}$;
\item $Z_{-i} = -Z_{i}^T$ for all $i \in {\mathcal I}$;
\end{itemize}
where we denote  $Z_i$ is the matrix of the linear transformation $Z\vert_{V_i}: V_{i} \rightarrow V_{i}$ the restriction of $Z$ to $V_i$ relative to the bases ${\mathcal B}_i$ and ${\mathcal B}_{i}$  and $Z_i^T$ is its transpose for all $i \in {\mathcal I}$. Moreover the subset of elements 
\[
(Z_i)_{i \in {\mathcal I}} \in \left(\bigoplus_{ i \in {\mathcal I}} Hom(V_i, V_{i})\right),
\]
 such that the above conditions for the $Z_i$ are satisfied,  is a subspace of 
 \[
 \bigoplus_{ i \in {\mathcal I}} Hom(V_i, V_{i})
 \]
  isomorphic to ${\mathfrak g}_{0}$.

% (d)
\item $\{(g_i)_{i \in {\mathcal I}} \in \prod_{i \in {\mathcal I}} GL(V_i) \mid g_{-i} = (g_i^*)^{-1} \text{ for all $i > 0$}\}$ is a closed subgroup of  $\prod_{i \in {\mathcal I}} GL(V_i)$ and is isomorphic to $\prod_{i \in {\mathcal I}, i > 0} GL(V_i)$. Moreover the function 
\[
\Phi: G^{\iota} \rightarrow \left. \left\{(g_i)_{i \in {\mathcal I}} \in \prod_{i \in {\mathcal I}} GL(V_i)\   \right\vert g_{-i} = (g_i^*)^{-1} \text{ for all $i > 0$} \right\}
\]
defined by $\Phi(g) = (g_{i})_{i \in {\mathcal I}}$  is a well-defined  isomorphism of algebraic groups. 

% (e)
\item The restriction of the adjoint action of $G$ to $G^{\iota}$ acts on ${\mathfrak g}_2$ and,  under the description of ${\mathfrak g}_2$ as a subspace of $\oplus_{i \in {\mathcal I}, i \ne (2m - 1)} Hom(V_i, V_{i + 2})$ in (b), this action  is given by 
\[
Ad(g)(X) \mapsto (g_{i + 2}X_{i}g_{i}^{-1})_{i \in {\mathcal I}, i \ne (2m - 1)}
\]
for all $g \in G^{\iota}$ and where $\Phi(g) = (g_{i})_{i \in {\mathcal I}}$. 
\end{enumerate}
\end{lemma}
\begin{proof}

% proof (a)
(a) $\Rightarrow$) For  $i \in {\mathcal I}$, $V_i$ is the eigenspace of $\iota(t)$ with eigenvalue $t^i$ for all $t \in {\mathbf k}^{\times}$. Moreover  when $i, j \in {\mathcal I}$ and $i \ne j$,  these eigenvalues $t^i$ and $t^j$ are distinct.  Because $g \iota(t) = \iota(t) g$ for all $t \in {\mathbf k}^{\times}$ when $g \in G^{\iota}$, then $g$ preserves these eigenspaces and we get $g(V_i) \subseteq V_i$ for all $i \in I$. $g_i \in GL(V_i)$ follows easily  because $g \in GL(V)$ and $g(V_i) \subseteq V_i$.

Because we have $\langle g(v), g(v') \rangle = \langle v, v' \rangle$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for all $v \in V_i$ and $v' \in V_{-i}$ that 
\[
\langle g_i(v), g_{-i}(v')\rangle = \langle g_{-i}^* g_i(v), v'\rangle = \langle v, v'\rangle \quad \Rightarrow \quad (g_{-i}^*) g_i = Id_{V_i} 
 \]
 for all $i \in I$. 

 $\Leftarrow$) If $g(V_i) \subseteq V_i$, $g_i \in GL(V_i)$ and $(g_{-i})^* g_i = Id_{V_i}$ for all $i \in {\mathcal I}$, then $g$ is an automorphism and, because of the condition on our direct sum decomposition of $V$ and the fact that $(g_{-i})^* g_i = Id_{V_i}$ for all $i \in {\mathcal I}$, we get that $g$ preserves the non-degenerate form $\langle\ , \ \rangle$, in other words $g \in G$. Because $g(V_i) \subseteq V_i$, we get that $g$ commutes with $\iota(t)$ for all $t \in {\mathbf k}^{\times}$ and $g \in G^{\iota}$.  (a) is proved.

% proof (b)
(b) $\Rightarrow$)  Because $Ad(\iota(t)) X = t^2 X$ for all $t \in {\mathbf k}^{\times}$ when $X \in {\mathfrak g}_2$, we have $\iota(t) X = t^2 X \iota(t)$ for all $t \in {\mathbf k}^{\times}$.  So if $v \in V_i$, then $\iota(t) X(v) =  t^2 X \iota(t) (v) = t^{i + 2} X(v)$ and consequently $X(V_i) \in V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 1)$. Note that this last equation means also that $X(V_{2m - 1}) = 0$

Note that if $i \geq 1$, then $-i = i - 2$ if and only if $i = 1$.  Because $\langle X(v), v' \rangle + \langle v, X(v')\rangle = 0$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for $i \in {\mathcal I}$, $i \geq 1$ and for all $v \in V_{-i}$,  $v' \in V_{i - 2}$ that  
\[
\langle X_{-i}(v), v'\rangle + \langle v, X_{i - 2} (v')\rangle = 0.
\]
In this last equation, if we substitute 
\[
X_{-i}(u_{-i, s}) = \sum_{q' = 1}^{{\delta}_{i - 2}} \xi_{q',s}^{(-i)} u_{(-i + 2), q'} \quad \text{ and } \quad X_{(i - 2)}(u_{(i - 2), r}) = \sum_{q = 1}^{{\delta}_{i}} \xi_{q, r}^{(i - 2)} u_{i,q},
\]
we get for $i \geq 3$ that $\epsilon \xi_{r,s}^{(-i)} + \epsilon \xi_{s,r}^{(i - 2)} = 0$ for all $1 \leq s \leq {\delta}_i$ and $1 \leq r \leq {\delta}_{i - 2}$ and thus $X_{-i} = -X_{i - 2}^T $. While if $i = 1$, then we get that  $\xi_{r,s}^{(-1)} + \epsilon \xi_{s,r}^{(-1)} = 0$ for all $1 \leq r, s \leq {\delta}_1$ and thus $X_{-1} = -\epsilon X_{-1}^T$.

$\Leftarrow$)  If $X_{-i} = -X_{i  - 2}^T$ for all $i \in {\mathcal I}$ and $i \geq 3$, and $X_{-1} = -\epsilon X_{-1}^T$, then we get that $\langle X(v), v' \rangle + \langle v, X(v')\rangle = 0$ for all $v, v' \in V$ by only checking it on the basis ${\mathcal B}$  and this means that $X \in {\mathfrak g}$. If we add the condition  $X(V_i) \subseteq V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 1)$, we have  that $X \in {\mathfrak g}_2$. The rest of the statements in (b) are easily proved. 

% proof (c)
(c) $\Rightarrow$)  Because $Ad(\iota(t)) Z = Z$ for all $t \in {\mathbf k}^{\times}$ when $Z \in {\mathfrak g}_0$, we have $\iota(t) Z =  Z \iota(t)$ for all $t \in {\mathbf k}^{\times}$.  So if $v \in V_i$, then $\iota(t) Z(v) = Z \iota(t) (v) = t^{i} Z(v)$ and consequently $Z(V_i) \in V_{i}$ for all $i \in {\mathcal I}$. 

Because $\langle Z(v), v' \rangle + \langle v, Z(v')\rangle = 0$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for $i \in {\mathcal I}$ and for all $v \in V_{i}$,  $v' \in V_{-i}$ that  
\[
\langle Z_{i}(v), v'\rangle + \langle v, Z_{-i} (v')\rangle = 0.
\]
In this last equation, if we substitute 
\[
Z_{i}(u_{i, s}) = \sum_{q' = 1}^{{\delta}_{i}} \zeta_{q', s}^{(i)} u_{i, q'} \quad \text{ and } \quad Z_{-i}(u_{-i, r}) = \sum_{q = 1}^{{\delta}_{i}} \zeta_{q, r}^{(-i)} u_{-i, q},
\]
we get for $i \geq 1$ that $ \zeta_{r, s}^{(i)} +  \zeta_{s, r}^{(-i)} = 0$ for all $1 \leq s, r \leq {\delta}_i$ and for $i \leq -1$ that $ \epsilon\zeta_{r, s}^{(i)} +  \epsilon\zeta_{s, r}^{(-i)} = 0$ for all $1 \leq s, r \leq {\delta}_i$.
 Thus $Z_{-i} = -Z_{i}^T $ for all $i \in {\mathcal I}$.

$\Leftarrow$)  If $Z_{-i} = -Z_{i}^T$ for all $i \in {\mathcal I}$, then we get that $\langle Z(v), v' \rangle + \langle v, Z(v')\rangle = 0$ for all $v, v' \in V$ by only checking it on the basis ${\mathcal B}$  and this means that $Z \in {\mathfrak g}$. If we add the condition  $Z(V_i) \subseteq V_i$ for all $i \in {\mathcal I}$, we have  that $Z \in {\mathfrak g}_0$. The rest of the statements in (d) are easily proved. 

