We will now present the combinatorics needed to enumerate the $G^{\iota}$-orbits in  ${\mathfrak g}_2$. 

% Definition 3.4
\begin{definition}\label{D:CoefficientFunction}
A function $c:{\mathbf B} \rightarrow {\mathbb N}$ is said to be {\it symmetric} if and only if $c(\tau(b)) = c(b)$ for all $b \in {\mathbf B}$.  Given such a symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$, we can associated to it a unique well-defined {\it coefficient function} ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$ as follows: ${\mathbf c}({\mathcal O}) = c(b)$ where $b$ is any ${\mathcal I}$-box $b \in {\mathcal O}$.  Reciprocally given a  coefficient function ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$, we can associated to it a unique well-defined symmetric function $c:{\mathbf B} \rightarrow {\mathbf N}$ as follows: $c(b) = {\mathbf c}({\mathcal O})$, where ${\mathcal O}$ is the unique $\langle \tau \rangle$-orbit containing $b$.

Clearly the set of symmetric functions $c:{\mathbf B} \rightarrow {\mathbb N}$ is in bijection with the set of coefficient function ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$. 

Given a symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$ and its associated coefficient function ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$, we can associated to them their {\it dimension vector} $\delta({\mathbf c}) = \delta(c) = (\delta_i({\mathbf c}))_{i \in {\mathcal I}} = (\delta_i(c))_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ as follows: 
\[
\delta_i(c) = \delta_i({\mathbf c}) = \sum_{\substack{b \in {\mathbf B}\\ i \in Supp(b)}} c(b).
\]
It is easy to verify that $\delta_{-i}(c) = \delta_i(c)$ for all $i \in {\mathcal I}$. 
\end{definition}



% Notation 3.5
\begin{notation}\label{N:CoefficientFunctionSet}
Denote by ${\mathfrak C}$: the set of coefficient functions ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$. If $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ is an ${\mathcal I}$-tuple  such that $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$. We will denote by  ${\mathfrak C}_{\delta}$: the set of coefficient functions ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$ such that $\delta({\mathbf c}) = \delta$.
\end{notation}

% Notation 3.6
\begin{notation}\label{N:CCorrespondance}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ be an ${\mathcal I}$-tuple such that $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and let  ${\mathbf c} \in  {\mathfrak C}_{\delta}$ be a coefficient function of dimension $\delta$.  Denote by $V({\mathbf c})$: the direct sum as ${\mathcal I}$-graded vector space and  as $\epsilon$-representations of ${\mathbf c}({\mathcal O})$ copies of $V({\mathcal O})$ defined in \ref{SS:EHFDefinition} with a ${\mathcal I}$-basis 
\[
{\mathcal B}_{\mathbf c} = \coprod_{{\mathcal O} \in {\mathbf B}/\tau} \coprod_{b \in {\mathcal O}} \{v_i^j(b) \mid i \in Supp(b), 1 \leq j \leq {\mathbf c}({\mathcal O})\}
\]
such that, for $i, i' \in {\mathcal I}$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, we have 
\[
\langle v_i^j(b), v_{i'}^{j'}(b')\rangle_{\mathbf c} 
= \begin{cases} 1, &\text{if $j' = j$, $b' = \tau(b)$, $i > 0$ and $i + i' = 0$; } \\
\epsilon, &\text{if $j' = j$,  $b' = \tau(b)$, $i < 0$ and $i + i' = 0$; }\\ 
0, &\text{otherwise.}
\end{cases}
\]
This is just from the formulae of \ref{N:BasisVOrbit} adapted to our situation. Here $0 \not\in {\mathcal I}$

We will denote by ${\mathfrak g}(V({\mathbf c}))$:  the Lie algebra corresponding to $(V({\mathbf c}),  \langle\  , \   \rangle_{\mathbf c})$. In other words, ${\mathfrak g}(V({\mathbf c}))$ is the vector space of linear transformations $X:V({\mathbf c}) \rightarrow V({\mathbf c})$ such that $\langle X(u), v\rangle_{\mathbf c} + \langle u, X(v)\rangle_{\mathbf c} = 0$ for all  $u, v \in V({\mathbf c})$.

From our construction, we have that $V({\mathbf c}) = \oplus_{i \in {\mathcal I}} V_i({\mathbf c})$, where 
$V_i({\mathbf c})$ is ${\mathbf c}({\mathcal O})$ copies of $V_i({\mathcal O})$. We get that  $\dim(V_i({\mathbf c})) = \delta_i$ for all $i \in {\mathcal I}$.  We get this last equation from
\[
\begin{aligned}
\dim(V_i({\mathbf c})) &= \sum_{{\mathcal O} \in {\mathbf B}/\tau} {\mathbf c}({\mathcal O}) \dim(V_i({\mathcal O})) =  \sum_{{\mathcal O} \in {\mathbf B}/\tau} \sum_{b \in {\mathcal O}} c(b) \dim(V_{i}(b))\\ &= \sum_{\substack{b \in {\mathbf B}\\ i \in Supp(b)}} c(b) = \delta_i({\mathbf c}), 
\end{aligned}
\]
because $\dim(V_i(b)) = 1$ when $i \in Supp(b)$. 

Let the three ${\mathcal I}$-graded  linear transformations  
\[
E_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c}), \quad   H_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c}) \quad \text{ and } \quad F_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c})
\]
denote the direct sum as ${\mathcal I}$-graded linear transformation of ${\mathbf c}({\mathcal O})$ copies of the linear transformations 
\[
E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}), \quad  H_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}) \quad \text{ and } \quad F_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}).
\]
By applying proposition~\ref{P:JMTripleProof} on each summand, we get that these three linear transformations are such that 
\begin{itemize}
\item $E_{\mathbf c}$ is of degree $2$, $H_{\mathbf c}$ is of degree $0$ and $F_{\mathbf c}$ is of degree $-2$;
\item $E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c}$ belong to the Lie algebra  ${\mathfrak g}(V({\mathbf c}))$;
\item $[H_{\mathbf c}, E_{\mathbf c}] = 2E_{\mathbf c}$, $[H_{\mathbf c}, F_{\mathbf c}] = -2F_{\mathbf c}$ and $[E_{\mathbf c}, F_{\mathbf c}] = H_{\mathbf c}$; in other words,  the triple $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ is an ${\mathcal I}$-graded Jacobson-Morozov triple for the Lie algebra of $(V({\mathbf c}),  \langle\  , \   \rangle_{\mathbf c})$;
\item  the ${\mathcal I}$-graded linear transformation $\phi_{\mathbf c}: V({\mathbf c}) \rightarrow V({\mathbf c})$ given by 
\[
\phi_{{\mathbf c}, i} = {E_{\mathbf c}}\vert_{V_i({\mathbf c})}: V_i({\mathbf c}) \rightarrow V_{i + 2}({\mathbf c}) \quad \text{for all $i \in {\mathcal I}$  such that $(i + 2) \in {\mathcal I}$},
\]
is  such that $(V({\mathbf c}), \phi_{\mathbf c}, \langle\ , \ \rangle_{\mathbf c})$ is an $\epsilon$-representation.
\end{itemize}


As such we can express these linear transformations on the elements of the basis ${\mathcal B}_{\mathbf c}$ using the expressions in \ref{SS:EHFDefinition}. For example, let ${\mathcal O}$ denote the $\langle \tau \rangle$-orbit of $b$, then,  if the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports,  $1 \leq j \leq {\mathbf c}({\mathcal O})$ and $i \in Supp(b)$, we have
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i < 0$;} \end{cases}
\]
while if the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports,  $b = b(i_1, j_1, k_1) \in {\mathcal O}$, $1 \leq j \leq {\mathbf c}({\mathcal O})$  and $i \in Supp(b)$, then we have 
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i \geq 1$;}\\  -v_{i + 2}^j(b), &\text{ if  $i < -1$;}\\ {\phantom -} v_1^j(b), &\text{ if  $i = -1$ and $b$ is below  the principal diagonal;}\\ - \epsilon v_1^j(b), &\text{ if $i = -1$ and $b$ is above  the principal diagonal;}\\  (- \epsilon)^{k_1} v_1^j(b), &\text{ if $i = -1$ and $b$ is on  the principal diagonal;}
\end{cases}
\]
\end{notation}

%3.7
\subsection{}\label{SS:coefficientOrbit}
Given an element $X \in {\mathfrak g}_2$, we will now associate to it a coefficient function ${\mathbf c}_X:{\mathbf B}/\tau \rightarrow {\mathbb N}$ as follows. By lemma~\ref{G2AsRepresEven} (b) and with the notation of this lemma, $X \in {\mathfrak g}_2$ is equivalent to giving the $\epsilon$-representation  $(V, \phi_V, \langle\  ,\  \rangle)$,where 
\[
\phi_{V, i} = X\vert_{V_i} : V_i \rightarrow  V_{i + 2} \quad v \mapsto X(v) \quad  \text{ for all $v \in V_i$}
\]
is the restriction of $X$ on $V_i$ for all $i \in {\mathcal I}$ such that  $(i + 2) \in {\mathcal I}$. By the theorem of Krull-Remak-Schmidt, this $\epsilon$-representation can be written in essentially unique way as a direct sum of indecomposable $\epsilon$-representations (up to isomorphism). We saw in proposition~\ref{P:JMTripleProof} that the set of indecomposable $\epsilon$-representations is in bijection with the set ${\mathbf B}/\tau$. More precisely, for each orbit ${\mathcal O} \in {\mathbf B}/\tau$, we have constructed a representative $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$ of the isomorphism class of the indecomposable $\epsilon$-representation. Denote by ${\mathbf c}_X({\mathcal O})$: the multiplicity  of the indecomposable $\epsilon$-representation $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$ (up to isomorphism). So the coefficient function ${\mathbf c}_X:{\mathbf B}/\tau \rightarrow {\mathbb N}$ is defined by ${\mathcal O} \mapsto {\mathbf c}_X({\mathcal O})$.

%3.8
\subsection{}\label{SS:IsomorphismV(c)andV}
We will now constructed an ${\mathcal I}$-graded isomorphism $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$. We will define this isomorphism on the bases ${\mathcal B}_{\mathbf c}$ of $V({\mathbf c})$ and ${\mathcal B}$ of $V$. 

Let $i \in {\mathcal I}$, $i > 0$. We get easily that 
\[
\{b \in {\mathbf B} \mid i \in Supp(b)\} \rightarrow \{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\} \text{ defined by } b \mapsto \tau(b)
\]
is a bijection.  Let $c:{\mathbf B} \rightarrow {\mathbb N}$ be the unique symmetric function corresponding to the coefficient function ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$.  Fix a total order $b_1 > b_2 > \dots > b_n$ on the set $\{b \in {\mathbf B} \mid i \in Supp(b)\}$ such that $c(b_r) \geq c(b_s)$ whenever $r < s$ for $1 \leq r, s \leq n$ and let $b'_1 > b'_2 > \dots > b'_n$ be the total order on the set $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\}$ such that     $b'_r = \tau(b_r)$ for $1 \leq r \leq n$. 
Consider the Young diagram corresponding to the partition $c(b_1) \geq c(b_2) \geq \dots \geq c(b_n)$. So the row indexed by $b_r$ will have $c(b_r)$ columns.  We would get the same Young diagram $c(b'_1) \geq c(b'_2) \geq \dots \geq c(b'_n)$ if we had started with the total order  $b'_1 > b'_2 > \dots > b'_n$  on the set $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\}$. This follows from the fact that $c$ is symmetric.  This partition is a partition of the integer $\delta_i$ from~\ref{N:CCorrespondance}.  In this Young diagram, we fill the boxes with the integers from 1 to $\delta_i$ in strictly increasing order from left to right and top to bottom.   We define $T_{{\mathbf c}, i}: V_i({\mathbf c}) \rightarrow V_i$ (respectively $T_{{\mathbf c}, -i}: V_{-i}({\mathbf c}) \rightarrow V_{-i}$)  to be the unique linear transformation such that if the entry in the box at row $r$ and column $s$ is $j$, then 
$T_{{\mathbf c}, i}(v_i^s(b_r)) = u_{i, j}$ (respectively $T_{{\mathbf c}, -i}(v_{-i}^s(b'_r)) = T_{{\mathbf c}, -i}(v_{-i}^s(\tau(b_r))) = u_{-i, j}$).  

Finally $T_{\mathbf c}:V_{\mathbf c} \rightarrow V$ is the direct sum of the linear transformations $T_{{\mathbf c}, i}: V_i({\mathbf c}) \rightarrow V_i$ and $T_{{\mathbf c}, -i}: V_{-i}({\mathbf c}) \rightarrow V_{-i}$ for all $i \in {\mathcal I}$, $i > 0$.  Note that  the dimension vector  $\delta({\mathbf c}) $ of ${\mathbf c}$ is  $\delta({\mathbf c}) = (\delta_i)_{i \in {\mathcal I}}$, where $\delta_i = \dim(V_i)$ for all $i \in {\mathcal I}$.

%lemma 3.9
\begin{lemma}\label{L:TcIsomorphism}
With the above definition, we have that $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is an ${\mathcal I}$-graded isomorphism such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$.
\end{lemma}
%proof
\begin{proof}
From our construction, it is clear that $T_{\mathbf c}$ is an ${\mathcal I}$-graded isomorphism.  We use the fact that $T_{\mathbf c}$ restricted to ${\mathcal B}_{\mathbf c}$ is a bijection with the basis ${\mathcal B}$ of $V$. To check that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$, it is enough to check it on the basis ${\mathcal B}_{\mathbf c}$. We want to consider $\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{i'}^{s'}(b'))\rangle$ where $i, i' \in {\mathcal I}$, $i \in Supp(b)$, $1 \leq s \leq c(b)$, $i' \in Supp(b')$ and $1 \leq s' \leq c(b')$. Because $T_{\mathbf c}$ is ${\mathcal I}$-graded, our hypothesis in~\ref{S:SetUpAeven} on the basis ${\mathcal B}$ of $V$ and our construction in~\ref{N:CCorrespondance}, we get if $i + i' \ne 0$, that 
\[
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{i'}^{s'}(b'))\rangle = 0 = \langle v_i^s(b), v_{i'}^{s'}(b')\rangle_{\mathbf c}.
\]

Now let $i' = -i$ and  assume first that $i > 0$. Consider the same total orders on the sets $\{b \in {\mathbf B} \mid i \in Supp(b)\}$  and $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\}$ as in \ref{SS:IsomorphismV(c)andV}. Proceeding as above with the Young diagram, assume that   $b = b_r$ in the total order $b_1 > b_2 > \dots > b_n$ on the set $\{b \in {\mathbf B} \mid i \in Supp(b)\}$ and   $b' = b'_{r'} = \tau(b_{r'})$ in the total order $b'_1 > b'_2 > \dots > b'_n$ on the set $\{b' \in {\mathbf B} \mid -i = \sigma(b') \in Supp(b')\}$ , the entry in the box at row $r$ and column $s$ is $j$ and the entry in the box at row $r'$ and column $s'$ is $j'$, then 
\[
\begin{aligned}
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle &= \langle T_{\mathbf c}(v_i^s(b_r)), T_{\mathbf c}(v_{-i}^{s'}(b'_{r'}))\rangle = \langle u_{i, j}, u_{-i, j'}\rangle\\ &= \begin{cases} 1, &\text{if $j = j'$;} \\ 0, &\text{otherwise;}\end{cases} = \begin{cases} 1, &\text{if $r= r'$ and $s = s'$;} \\ 0, &\text{otherwise.}\end{cases} 
\end{aligned}
\]
If we now consider the bilinear form $\langle  \  ,  \  \rangle_{\mathbf c}$  in $V({\mathbf c})$, we have
\[
\begin{aligned}
\langle v_i^s(b), v_{-i}^{s'}(b')\rangle_{\mathbf c} &= \langle v_i^s(b_r), v_{-i}^{s'}(b'_{r'})\rangle_{\mathbf c} = \langle v_i^s(b_r), v_{-i}^{s'}(\tau(b_{r'}))\rangle_{\mathbf c}\\ &= \begin{cases} 1, &\text{if $r= r'$ and $s = s'$;} \\ 0, &\text{otherwise.}\end{cases} 
\end{aligned}
\]
So if $i > 0$, then $\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle = \langle v_i^s(b), v_{-i}^{s'}(b')\rangle_{\mathbf c}$.

If $i \in {\mathcal I}$, $i < 0$, then 
\[
\begin{aligned}
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle &= \epsilon \langle T_{\mathbf c}(v_{-i}^{s'}(b')), T_{\mathbf c}(v_{i}^{s}(b))\rangle\\ &=  \epsilon  \langle v_{-i}^{s'}(b'), v_{i}^{s}(b)\rangle_{\mathbf c} =  \langle v_{i}^{s}(b), v_{-i}^{s'}(b')\rangle_{\mathbf c}.
\end{aligned}
\]
We have proved that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle$ for all $u, v \in V$.

\end{proof}

%% proposition 3.10
\begin{proposition} \label{Prop_Indexation_Orbits_Even}
Let $\delta = (\delta_i)_{i \in {\mathcal I}}$ be as in \ref{S:SetUpAeven}  and ${\mathfrak g}_2/G^{\iota}$ denotes the set of  $G^{\iota}$-orbits  in ${\mathfrak g}_2$. Then the map 
\[
\Upsilon:{\mathfrak g}_2/G^{\iota} \rightarrow  {\mathfrak C}_{\delta} \quad \text{ defined by } \quad G^{\iota} \cdot X \mapsto {\mathbf c}_X,
\]
is a well-defined bijection.
\end{proposition}
\begin{proof}

By our last observation in \ref{SS:coefficientOrbit}, if $G^{\iota} \cdot X = G^{\iota} \cdot X'$, then  the corresponding $\epsilon$-representations for $X$ and $X'$ are isomorphic, we get  that ${\mathbf c}_X = {\mathbf c}_{X'}$. So the  function $\Upsilon$ is well-defined. 

To show that $\Upsilon$ is an injective function,  assume that ${\mathbf c}_X = {\mathbf c}_{X'}$, then this means that, by the Krull-Remak-Schmidt theorem, the $\epsilon$-representations for $X$ and $X'$ are isomorphic. Note that in the case of the orthogonal representation (i.e. $\epsilon = 1$), the group $G$ is not $SO(V)$, but rather the group ${\widehat G} = O(V)$, but it is easy to see that  $G^{\iota} = {\widehat G}^{\iota}$ as seen in lemma~\ref{G2AsRepresEven} and the isomorphism is the same for the case of $SO(V)$ and $O(V)$. So $X$ and $X'$ are in the same $G^{\iota}$-orbit and $G^{\iota} \cdot X = G^{\iota} \cdot X'$ 

To prove that $\Upsilon$ is surjective, we need to show that there is an element $X \in {\mathfrak g}_2$ such that ${\mathbf c}_X = {\mathbf c} \in {\mathfrak C}_{\delta}$.  Consider $X = T_{\mathbf c} E_{\mathbf c} T_{\mathbf c}^{-1}:V \rightarrow V$, where $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is the ${\mathcal I}$-graded isomorphism defined in \ref{SS:IsomorphismV(c)andV}.  Because $E_{\mathbf c} \in {\mathfrak g}_2(V({\mathbf c}))$ and lemma~\ref{L:TcIsomorphism}, $X \in {\mathfrak g}_2$. From our construction of $E_{\mathbf c}: V({\mathbf c}) \rightarrow V({\mathbf c})$, it is isomorphic as ${\mathcal I}$-graded and $\epsilon$-representation  to the direct sum of ${\mathbf c}({\mathcal O})$ copies of the linear transformation $E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$. By carrying this direct sum using $T_{\mathbf c}$ to $V$, we do get that ${\mathbf c}_X = {\mathbf c}$ and the proof is complete. 
\end{proof}


%notation 3.11
\begin{notation}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ be such that $\delta_i = \dim(V_i)$ for all $i \in {\mathcal I}$ as in \ref{S:SetUpAeven}. If ${\mathbf c} \in {\mathfrak C}_{\delta}$, we will denote by ${\mathcal O}_{\mathbf c}$: the unique $G^{\iota}$-orbit in ${\mathfrak g}_2$ such that $\Upsilon({\mathcal O}_{\mathbf c}) = {\mathbf c}$.
\end{notation}

%remark 3.12
\begin{remark}\label{R:IsomoVVc}
Using the isomorphism $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$, we can transfer results about the orbit ${\mathcal O}_{\mathbf c}$ in the Lie algebra ${\mathfrak g}$ to the orbit of $E_{\mathbf c}$ in the Lie algebra 
${\mathfrak g}(V({\mathbf c}))$.
\end{remark}


% 3.13
\subsection{}
 To compute the dimension of the orbit ${\mathcal O}_{\mathbf c}$ corresponding to the coefficient function ${\mathbf c} \in  {\mathfrak C}_{\delta}$, we need to recall Lusztig's construction of a parabolic subalgebra ${\mathfrak p}_X$ in ${\mathfrak g}$ associated to an element $X \in {\mathfrak g}_2$ and the formula  for the dimension of ${\mathcal O}_{\mathbf c}$ involving the Lie algebra ${\mathfrak p}_X$,  where $X \in {\mathcal O}_{\mathbf c}$.

%definition 3.14
\begin{definition}\label{D:LieHomo}
Let $X \in {\mathfrak g}_2$. It is known that we can find a Lie algebra homomorphism $\phi: {\mathfrak sl}_2({\mathbf k}) \rightarrow {\mathfrak g}$ such that 
\[
\phi\begin{pmatrix}0 & 1\\ 0 & 0\end{pmatrix} = X \in {\mathfrak g}_2, \qquad \phi\begin{pmatrix}1 & \phantom{-}0\\ 0 & -1\end{pmatrix} \in {\mathfrak g}_0, \qquad \phi\begin{pmatrix}0 & 0\\ 1 & 0\end{pmatrix} \in {\mathfrak g}_{-2}.
\]
Denote by $\widetilde{\phi}: SL_2({\mathbf k}) \rightarrow G$: the homomorphism of algebraic groups whose differential is $\phi$ and by $\iota':{\mathbf k}^{\times} \rightarrow G$: the homomorphism defined by 
\[
\iota'(t) = \widetilde{\phi}\begin{pmatrix}t & 0\phantom{-} \\ 0 & t^{-1}\end{pmatrix} \qquad  \text{ for all $t \in {\mathbf k}^{\times}$}.
\]
This gives us  a second grading for the Lie algebra ${\mathfrak g} = \oplus_r  ({ }_r {\mathfrak g})$ where 
\[
({ }_r {\mathfrak g}) = \{ X \in {\mathfrak g} \mid Ad(\iota'(t))(X) = t^r X \quad \text{ for all $t \in {\mathbf k}^{\times}$}\}
\]
and,  because $\iota'({\mathbf k}^{\times}) \subset G^{\iota}$, we have the direct sum decomposition 
\[
{\mathfrak g} = \bigoplus_{r, r'}  ({ }_r{\mathfrak g}_{r'}).
\]
In  5.2 of \cite{L1995}, Lusztig defines the {\it parabolic subalgebra ${\mathfrak p}_X$} as 
\[
{\mathfrak p}_X = \bigoplus_{\begin{subarray}{c} r, r' \\ r' \leq r \end{subarray}}  ({ }_r{\mathfrak g}_{r'})
\]
\end{definition}

%proposition 3.15
\begin{proposition}[Lusztig]
If $X \in {\mathcal O}_{\mathbf c}$ where ${\mathbf c} \in  {\mathfrak C}_{\delta}$,  then 
\[
\dim({\mathcal O}_{\mathbf c}) = \dim({\mathfrak g}_0) - \dim({\mathfrak p}_0) + \dim({\mathfrak p}_2),
\]
where ${\mathfrak p}$ is the parabolic subalgebra ${\mathfrak p}_X$  associated above to $X$. 
\end{proposition}
\begin{proof}
See 4.1 in \cite{L2010}.
\end{proof}

We now want to use this formula to compute the dimension $\dim({\mathcal O}_{\mathbf c})$ of the orbit ${\mathcal O}_{\mathbf c} \in {\mathfrak g}_2/G^{\iota}$ in term of the coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta} $. This is done in the next proposition.

%proposition 3.16
\begin{proposition}\label{DimensionFormulaEven}
Let ${\mathbf c}  \in  {\mathfrak C}_{\delta}$  and consider the symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$ corresponding to ${\mathbf c}$.  Then the dimension $\dim({\mathcal O}_{\mathbf c})$ of the orbit ${\mathcal O}_{\mathbf c}$ is equal to
\[
\left[
\begin{aligned}
&\sum_{\begin{subarray}{c} i \in {\mathcal I}\\ i > 0\end{subarray}} \delta_i^2 - \sum_{\begin{subarray}{c}i \in {\mathcal I}\\ i > 0\\ (b, b') \in{\mathbf B} \times {\mathbf B}\\ i \in Supp(b) \cap Supp(b')\\ \lambda(b) \geq\lambda(b') \end{subarray}} c(b) c(b') + \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 < i < (2m - 1)\\ (b, b')\in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b)\\ (i + 2) \in Supp(b')\\\lambda(b) \geq \lambda(b') \end{subarray}} c(b) c(b') \\ \\ & + \frac {1}{2}\sum_{\begin{subarray}{c}(b, b')\in {\mathbf B} \times {\mathbf B} \\ \tau(b) \ne b' \\ 1 \in Supp(b')\\ -1 \in   Supp(b) \\ \lambda(b') \leq \lambda(b)\end{subarray}} c(b) c(b') +  \frac {1}{2}\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ -1 \in Supp(b)\\ \lambda(b) \geq 0 \end{subarray}} c(b) (c(b) - 1) \\ \\  & + \frac{(1 - \epsilon)}{2} \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ -1 \in Supp(b)\\\lambda(b) \geq 0 \end{subarray}} c(b)
\end{aligned}
\right]
\]
Recall that the value $\lambda(b)$ for $b \in {\mathbf B}$ has been defined in notation~\ref{N:LambdaValue}. 
\end{proposition}
%proof
\begin{proof}Taking into account our remark~\ref{R:IsomoVVc}, we will  assume that $V = V({\mathbf c})$.  We have that $\dim(V_i) = \delta_i$ for all $i \in {\mathcal I}$ from the fact that $\delta({\mathbf c}) = \delta$.
We have constructed in~\ref{N:CCorrespondance}  a Jacobson-Morozov triple  $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ with $E_{\mathbf c} \in {\mathcal O}_{\mathbf c}$; in other words,  we have 
\[
[H_{\mathbf c}, E_{\mathbf c}] = 2 E_{\mathbf c}, \qquad [H_{\mathbf c}, F_{\mathbf c}] = -2 F_{\mathbf c}, \qquad [E_{\mathbf c}, F_{\mathbf c}] = H_{\mathbf c},
\]
where $E_{\mathbf c} \in {\mathfrak g}_2$, $H_{\mathbf c} \in {\mathfrak g}_0$ and $F_{\mathbf c} \in {\mathfrak g}_{-2}$, and such that $E_{\mathbf c} \in {\mathcal O}_{\mathbf c}$.   Thus we have a Lie algebra homomorphism $\phi: {\mathfrak sl}_2({\mathbf k}) \rightarrow {\mathfrak g}$ such that 
\[
\phi\begin{pmatrix}0 & 1\\ 0 & 0\end{pmatrix} = E_{\mathbf c}, \qquad \phi\begin{pmatrix}1 & \phantom{-}0\\ 0 & -1\end{pmatrix} = H_{\mathbf c}, \qquad \phi\begin{pmatrix}0 & 0\\ 1 & 0\end{pmatrix} = F_{\mathbf c}. 
\]
As in definition~\ref{D:LieHomo}, let $\widetilde{\phi}: SL_2({\mathbf k}) \rightarrow G$ be the homomorphism of algebraic groups whose differential is $\phi$ and by $\iota':{\mathbf k}^{\times} \rightarrow G$: the homomorphism defined by 
\[
\iota'(t) = \widetilde{\phi}\begin{pmatrix}t & 0\phantom{-} \\ 0 & t^{-1}\end{pmatrix} \qquad  \text{ for all $t \in {\mathbf k}^{\times}$.}
\]
We have the grading for the Lie algebra ${\mathfrak g} = \oplus_r  ({ }_r {\mathfrak g})$ where 
\[
({ }_r {\mathfrak g}) = \{ X \in {\mathfrak g} \mid Ad(\iota'(t))(X) = t^r X \quad \text{ for all $t \in {\mathbf k}^{\times}$}\}
\]
By taking the derivative, we get that 
\[
({ }_r {\mathfrak g}) = \{ X \in {\mathfrak g} \mid ad(H_{\mathbf c})(X) =r X \}.
\]
By lemma~\ref{G2AsRepresEven} (c), we have that 
\[
\dim({\mathfrak g}_0) = \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ i > 0\end{subarray}} \delta_i^2.
\]
Let ${\mathfrak p}$ be the parabolic subalgebra associated to the nilpotent element $E_{\mathbf c}$ as in the definition~\ref{D:LieHomo} . From the definition of ${\mathfrak p}$, we get that 
\[
{\mathfrak p}_0 = \bigoplus_{r \geq 0}  ({ }_r{\mathfrak g}_0) \qquad \text{ and } \qquad {\mathfrak p}_2 = \bigoplus_{r \geq 2}  ({ }_r{\mathfrak g}_2).
\]
By our description of ${\mathfrak g}_0$ and ${\mathfrak g}_2$ in lemma~\ref{G2AsRepresEven}, we get that 
\[
 {\mathfrak p}_0 = \bigoplus_{r \geq 0}\bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 < i  \end{subarray}} \{(Z_i : V_i \rightarrow V_i) \in Hom(V_i, V_i) \mid ad(H_{\mathbf c}\vert_{V_i}) Z_i = r Z_i \}
\]
and ${\mathfrak p}_2 = {\mathfrak p}'_2 \oplus {\mathfrak p}''_2$ where 
\[
{\mathfrak p}'_2 = 
\bigoplus_{r \geq 2}\bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 < i < (2m - 1)\end{subarray}} \{(X_i : V_i \rightarrow V_{i + 2}) \in Hom(V_i, V_{i + 2}) \mid ad(H_{\mathbf c}\vert_{V_i}) X_i = r X_i \}
\]
and 
\[
{\mathfrak p}''_2 = 
\bigoplus_{r \geq 2}\left\{(X_{-1}:V_{-1} \rightarrow V_1) \in Hom(V_{-1}, V_1) \left\vert \begin{aligned} &X_{-1} = -\epsilon X_{-1}^*  \text{ and } \\  &ad(H_{\mathbf c}\vert_{V_{-1}}) X_{-1}  = r X_{-1} \end{aligned}\right.\right\}
\]
We can give  bases for the spaces $Hom(V_i, V_i)$ and $Hom(V_i, V_{i + 2})$ that are eigenvectors for $ad(H_{\mathbf c}\vert_{V_i})$.  From our construction of the Jacobson-Morozov triple $\{E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c}\}$ and notation~\ref{N:CCorrespondance},  we have for each $i \in {\mathcal I}$ a basis  
\[
{\mathcal B}_i = \{v_{i}^{j}(b) \in V_i  \mid b \in {\mathbf B}, i \in Supp(b), 1 \leq j \leq c(b)\}
\]
of $V_i$ such that $H_{\mathbf c}(v_{i}^{j}(b)) = h_{i}(b) v_{i}^{j}(b)$ for all $b \in {\mathbf B}$, $i \in Supp(b)$ and $1 \leq j \leq c(b)$. For each $b, b' \in {\mathbf B}$ with $i \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, let $Z_{(b, j)}^{(b', j')} \in Hom(V_i, V_i)$ be defined on the basis ${\mathcal B}_i $ by 
\[
Z_{(b, j)}^{(b', j')}(v_i^{j''}(b'')) = \begin{cases} v_i^{j'}(b'), &\text{if $b'' = b$ and $j'' = j$;}\\ 0, &\text{otherwise.}\end{cases}
\]

Clearly these linear transformations $Z_{(b, j)}^{(b', j')}$ with  $b, b' \in {\mathbf B}$,  $i \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ form a basis of $Hom(V_i, V_i)$ and $Z_{(b, j)}^{(b', j')}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_i})$ with
\[
ad(H_{\mathbf c}) (Z_{(b, j)}^{(b', j')}) = (h_{i}(b') - h_{i}(b)) Z_{(b, j)}^{(b', j')}
\]
by computing both sides  on the basis vector $v_{i}^{j''}(b'')$. Consequently
\[
\dim({\mathfrak p}_0) = 
\sum_{\begin{subarray}{c}i \in {\mathcal I}\\ i > 0\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b) \cap Supp(b')\\ (h_{i}(b') - h_{i}(b)) \geq 0\end{subarray}} c(b) c(b') = \sum_{\begin{subarray}{c}i \in {\mathcal I}\\ i > 0\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b) \cap Supp(b')\\ \lambda(b) \geq  \lambda(b') \end{subarray}} c(b) c(b')
\]
because $(h_i(b') - h_i(b)) \geq 0$ is equivalent to $(i - h_i(b)) - (i - h_i(b')) \geq 0$.  This is simply $\lambda(b) \geq \lambda(b')$.

Let now $i \in {\mathcal I}$ and $0 < i  < (2m - 1)$.  For each $b, b' \in {\mathbf B}$ with $i \in Supp(b)$, $(i + 2) \in Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, let $X_{(b, j)}^{(b', j')} \in Hom(V_i, V_{i + 2})$ be defined on the basis ${\mathcal B}_i $ by 
\[
X_{(b, j)}^{(b', j')}(v_i^{j''}(b'')) = \begin{cases} v_{(i + 2)}^{j'}(b'), &\text{if $b'' = b$ and $j'' = j$;}\\ 0, &\text{otherwise.}\end{cases}
\]
Clearly these linear transformations $X_{(b, j)}^{(b', j')}$ with  $b, b' \in {\mathbf B}$ with $i \in Supp(b)$,  $(i + 2) \in Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ form a basis of $Hom(V_i, V_{i + 2})$ and $X_{(b, j)}^{(b', j')}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_i})$ with 
\[
ad(H_{\mathbf c}\vert_{V_i}) (X_{(b, j)}^{(b', j')}) = (h_{(i + 2)}(b') - h_{i}(b)) X_{(b, j)}^{(b', j')}
\]
by computing both sides  on the basis vector $v_{i}^{j''}(b'')$. Consequently
\[
\dim({\mathfrak p}'_2) = 
\sum_{\begin{subarray}{c}i \in {\mathcal I}\\0 < i < (2m - 1)\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b)\\ (i + 2) \in  Supp(b')\\ (h_{(i + 2)}(b') - h_i(b)) \geq 2\end{subarray}} c(b) c(b') = \sum_{\begin{subarray}{c}i \in {\mathcal I}\\0 < i < (2m - 1)\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b)\\ (i + 2) \in  Supp(b')\\ \lambda(b) \geq  \lambda(b') \end{subarray}} c(b) c(b')
\]
because $(h_{(i + 2)}(b') - h_i(b)) \geq 2$ is equivalent to $(i - h_i(b)) - ((i + 2) - h_{(i + 2)}(b')) \geq 0$.  This is simply $\lambda(b) \geq \lambda(b')$.


Finally we need to compute the dimension of  ${\mathfrak p}''_2$.  If we  use the basis as in notation~\ref{N:CCorrespondance} appearing in $V_{-1}$, then we get the basis   
\[
\{v_{-1}^j(b) \mid b \in {\mathbf B}, -1 \in Supp(b), 1 \leq j \leq c(b)\}.
\]
of $V_{-1}$. 


The involution $\tau$ restricted to $\{b \in {\mathbf B}\mid -1 \in Supp(b)\}$ gives a bijection between  $\{b \in {\mathbf B}\mid -1 \in Supp(b)\}$ and  $\{b \in {\mathbf B}\mid 1 \in Supp(b)\}$. We can use this bijection to index the basis used  in notation~\ref{N:CCorrespondance} for $V_{1}$ and also the fact that the function $c$ is symmetric. Thus we get the basis   
 \[
 \{v_1^j(\tau(b)) \mid b \in{\mathbf B}, -1 \in Supp(b), 1 \leq j \leq c(b)\}.
 \]
 of $V_1$. 


For these bases, we have 
\[
\langle v_1^{j'}(\tau(b')), v_{-1}^j(b)\rangle_{\mathbf c} = \epsilon \langle v_{-1}^j(b), v_1^{j'}(\tau(b'))\rangle_{\mathbf c} = \begin{cases} 1, &\text{$b = b', j' = j$;}\\ 0, &\text{ otherwise;} \end{cases}
\]
where $b, b' \in{\mathbf B}$, $-1 \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ . 

For each homomorphism $X_{-1}:V_{-1} \rightarrow V_1$, we can write
\[
X_{-1}(v_{-1}^j(b)) = \sum_{(b'', j'')} \xi_{(b, j)}^{(b'', j'')} v_1^{j''}(\tau(b'')) 
\]
and 
\[
X_{-1}(v_{-1}^{j'}(b')) = \sum_{(b''', j''')} \xi_{(b', j')}^{(b''', j''')} v_1^{j'''}(\tau(b'''))
\]
where the sums run over  the set of pairs $(b'', j'')$, $(b''', j''')$ such that $b'', b''' \in {\mathbf B}$,  $-1 \in Supp(b'') \cap Supp(b''')$,   $1 \leq j'' \leq c(b'')$ and $1 \leq j''' \leq c(b''')$. 


If we add the condition of being in the $Hom(V_{-1}, V_1)$-component  of ${\mathfrak g}_2$,  that is
\[
\langle X_{-1}(v), v'\rangle + \langle v, X_{-1}(v')\rangle = 0 \quad \text{ for all $v, v' \in V_{-1}$,}
\]
this means that when $v = v_{-1}^j(b)$ and $v' = v_{-1}^{j'}(b')$, we get 
\begin{equation}
\xi_{(b, j)}^{(b', j')} + \epsilon \xi_{(b', j')}^{(b, j)} = 0
\end{equation}
for all $b, b' \in {\mathbf B}$, $-1 \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$. The converse is also true. More precisely,  if we impose the conditions above for all these coefficients $\xi$, then the corresponding linear transformation $X_{-1}$ belongs to the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$.  


We will use this to give a basis of the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$.  For $b, b' \in {\mathbf B}$, $-1 \in Supp(b) \cap Supp(b')$,  $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$.  First we assume that $(b', j') \ne (b, j)$, then we define the linear transformation $X_{(b, j)}^{(b', j')}:V_{-1} \rightarrow V_1$ as follows:
\[
X_{(b, j)}^{(b', j')}(v_{-1}^{j''}(b'')) = \begin{cases} {\phantom -}v_1^{j'}(\tau(b')), &\text{ if $(b'', j'') = (b, j)$}; \\ \\ -\epsilon v_1^j(\tau(b)), &\text{ if $(b'', j'') = (b', j')$;}\\ \\ 0, &\text{ otherwise.}
\end{cases}
\]
In other words, we have 
\[
\xi_{(b, j)}^{(b'', j'')} = \begin{cases}1, &\text{if $(b'', j'') = (b', j')$;}\\ 0, &\text{otherwise;}\end{cases}
\]
\[
\xi_{(b', j')}^{(b''', j''')} = \begin{cases}-\epsilon, &\text{if $(b''', j''') = (b, j)$;}\\ {\phantom -}0, &\text{otherwise}\end{cases}
\]
and equation (1) is satisfied. Thus $X_{(b, j)}^{(b', j')}$ belongs to the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$. By computing on all of the basis vector $v_{-1}^{j''}(b'')$, we get that 
\[
X_{(b, j)}^{(b', j')} = -\epsilon X_{(b', j')}^{(b, j)}.
\]

$X_{(b, j)}^{(b', j')}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_{-1}})$ with
\[
ad(H_{\mathbf c}\vert_{V_{-1}})X_{(b, j)}^{(b', j')} = (h_1(\tau(b)) - h_{-1}(b')) X_{(b, j)}^{(b', j')}
\]
by computing both sides  on the basis vector $v_{-1}^{j''}(b'')$. Note that we have used here  lemma~\ref{L:RelationCoefficientsHandF} (a). 

Note that $(b', j') \ne (b, j)$ is equivalent to either $b' \ne b$ or ($b' = b$ and $j' \ne j$).

If we are in the orthogonal case, in other words when $\epsilon = 1$, then we get from equation (1) that $\xi_{(b, j)}^{(b, j)} = 0$ for all $b \in{\mathbf B}$, $-1 \in Supp(b)$ and $1 \leq j \leq c(b)$. We can totally order the finite set $\{(b, j)\mid b \in {\mathbf B}, -1 \in Supp(b)\}$. We will write $<$ for this total order.  With this,  we get easily that the linear transformations  $X_{(b, j)}^{(b', j')}$ where $(b, j) < (b', j')$ is a basis of the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$ and, because of our computation of $ad(H_{\mathbf c}\vert_{V_{-1}})$ on these basis elements, we get that
\[
\dim({\mathfrak p}''_2) = \frac {1}{2}\sum_{\begin{subarray}{c}(b, b')\in {\mathbf B} \times {\mathbf B}\\ b' \ne b\\ -1 \in Supp(b) \cap Supp(b')\\ (h_1(\tau(b)) -  h_{-1}(b') \geq 2\end{subarray}} c(b) c(b')  + \frac {1}{2}\sum_{\begin{subarray}{c} b \in {\mathbf B} \\ -1 \in Supp(b)\\ -h_{-1}(b) \geq 1\end{subarray}} c(b) (c(b) - 1)
\]
Note that $h_1(\tau(b)) - h_{-1}(b') \geq 2$ is equivalent to $-1 - h_{-1}(b) \geq 1 - h_1(\tau(b'))$ by lemma~\ref{L:RelationCoefficientsHandF} (a).  This is simply $\lambda(b) \geq \lambda(\tau(b'))$. Similarly $-h_{-1}(b) \geq 1$ is equivalent to $-1 - h_{-1}(b) \geq 0$. This is $\lambda(b) \geq 0$. In the first sum, we can use $\tau(b')$ rather than $b'$. Finally we get that 
\[
\dim({\mathfrak p}''_2) = \frac {1}{2}\sum_{\begin{subarray}{c}(b, b')\in {\mathbf B} \times {\mathbf B}\\ \tau(b') \ne b\\ -1 \in Supp(b)\\ 1 \in Supp(b')\\ \lambda(b) \geq \lambda(b')\end{subarray}} c(b) c(b')  + \frac {1}{2}\sum_{\begin{subarray}{c} b \in {\mathbf B} \\ -1 \in Supp(b)\\ \lambda(b) \geq 0\end{subarray}} c(b) (c(b) - 1)
\]

If we are in the symplectic case, in other words when $\epsilon = -1$, then we don't necessarily have that $\xi_{(b, j)}^{(b, j)} = 0$. For $b \in {\mathbf B}$, $-1 \in Supp(b)$ and $1 \leq j \leq c(b)$.  Then we can define the linear transformation $X_{(b, j)}^{(b, j)}:V_{-1} \rightarrow V_1$ as follows:
\[
X_{(b, j)}^{(b,  j)}(v_{-1}^{j''}(b'')) = \begin{cases} v_1^j(\tau(b)), &\text{ if $(b'', j'') = (b, j)$}; \\ \\ 0, &\text{ otherwise.}
\end{cases}
\]
In other words, we have 
\[
\xi_{(b, j)}^{(b'', j'')} = \begin{cases}1, &\text{if $(b'', j'') = (b, j)$;}\\ 0, &\text{otherwise;}\end{cases}
\]
and equation (1) is satisfied. Consequently $X_{(b, j)}^{(b, j)}$ belongs to the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$. 

$X_{(b, j)}^{(b, j)}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_{-1}})$ with 
\[
ad(H_{\mathbf c}\vert_{V_{-1}})X_{(b, j)}^{(b, j)} = (h_1(\tau(b)) - h_{-1}(b)) X_{(b, j)}^{(b, j)}. 
\]
As above we can totally order the finite set $\{(b, j)\mid b \in {\mathbf B}, -1 \in Supp(b)\}$. We will write $<$ for this total order.  With this,  we get easily that the linear transformations  $X_{(b, j)}^{(b', j')}$ where $(b, j) < (b', j')$ with the linear transformations $X_{(b, j)}^{(b, j)}$ form a basis of the $Hom(V_{-1}, V_1)$-component  of  ${\mathfrak g}_2$ and, because of our computation of $ad(H_{\mathbf c}\vert_{V_{-1}})$ on these basis elements, we get that

\[
\dim({\mathfrak p}''_2) = \frac {1}{2}\sum_{\begin{subarray}{c}(b, b')\in {\mathbf B} \times {\mathbf B}\\ \tau(b') \ne b\\ -1 \in Supp(b)\\ 1 \in Supp(b')\\ \lambda(b) \geq \lambda(b')\end{subarray}} c(b) c(b')  + \frac {1}{2}\sum_{\begin{subarray}{c} b \in {\mathbf B} \\ -1 \in Supp(b)\\ \lambda(b) \geq 0\end{subarray}} c(b) (c(b) - 1) +  \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ -1 \in Supp(b)\\ h_{\beta}(1) \geq 1\end{subarray}} c(b)
\]
For the first two sums above, it is similar to the orthogonal  case. For the third sum above, we have to noted that $h_1(\tau(b)) - h_{-1}(b) \geq 2$ is equivalent to $-1 - h_{-1}(b) - 1 - h_{-1}(b) \geq 0$. This is simply $\lambda(b) \geq 0$. 

From all the previous computation, the proposition follows.
\end{proof}

We will now describe the  partition  of $\dim(V)$ corresponding to the Jordan type for any element in an orbit ${\mathcal O}_{\mathbf c}$. 

%proposition 3.17
\begin{proposition}\label{P:Height_Jordan_Type}
Let $X$ be an element of the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ where ${\mathbf c}  \in  {\mathfrak C}_{\delta}$ and let $c:{\mathbf B} \rightarrow {\mathbb N}$ the symmetric function corresponding to ${\mathbf c}$.  Then the partition corresponding to the Jordan type of $X$ is 
\[
\prod_{b \in {\mathbf B}} \vert Supp(b) \vert^{c(b)}.
\]
Here we have described the partition in multiplicative form.
\end{proposition}
%proof
\begin{proof}
Taking into account our remark~\ref{R:IsomoVVc}, we can assume that $V = V({\mathbf c})$. If $(E_{\bf c}, H_{\bf c}, F_{\bf c})$ is the Jacobson-Morozov triple corresponding to the orbit ${\mathcal O}_{\mathbf c}$ as in~\ref{N:CCorrespondance}, then we can take $E_{\bf c}$ as a representative for the orbit ${\mathcal O}_{\mathbf c}$. As a representation of the quiver $A_{2m}$, we know that  $E_{\bf c}$ is  a direct sum over $b \in {\mathbf B}$  of $c(b)$ copies of an  indecomposable representation $V(b)$ as in notation~\ref{N:BasisVOrbit} and with the formulae in \ref{SS:EHFDefinition}. Thus from these, we get that there is a unique Jordan bloc for the restriction of $E_{\mathbf c}$ on $V(b)$. In other words, $V(b)$ is a cyclic subspace and the partition of the restriction of $E_{\mathbf c}$ on $V(b)$ is $\vert Supp(b) \vert$. From this, we get that the Jordan type of $E_{\mathbf c}$ is as stated in the proposition. 
\end{proof}

