%lemma 3.23
\begin{lemma}\label{L:RankComponentTableau}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$. Denote by ${\mathfrak T}_{\delta}$: the set of symplectic (respectively  orthogonal ) symmetric ${\mathcal I}$-tableaux ${\mathcal T}$ of dimension $\delta({\mathcal T}) = \delta = (\delta_i)_{i \in {\mathcal I}}$ and by ${\mathfrak R}_{\delta}$: the set of symplectic (respectively orthogonal )  symmetric ${\mathcal I}$-tableaux ${\mathcal R} = (r_{i, j})_{i, j \in I, i \geq j}$ such that 
\[
r_{i, i} = \delta_i \quad \text{ and } \quad (r_{i, j} - r_{i + 2, j} - r_{i , j - 2} + r_{i + 2, j - 2}) \geq 0 \quad \text{ for all $i, j \in {\mathcal I}$ and $i \geq j$}
\]
where we set $r_{i, j} = 0$ if either $i \not\in {\mathcal I}$ or $j \not\in {\mathcal I}$ or both. Then the map $\varTheta:{\mathfrak T}_{\delta} \longrightarrow {\mathfrak R}_{\delta}$
\[
\varTheta({\mathcal T}) = \varTheta((c_{i, j})_{i, j \in {\mathcal I}, i \geq j}) = (r_{i, j})_{i, j \in I, i \geq j} \quad \text{where $r_{i, j} = \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq j \geq v\end{subarray}} c_{u, v}$}  
\]
for all $i , j \in {\mathcal I}$, $i \geq j$. is a well-defined bijection.
\end{lemma}
%proof
\begin{proof}
This is a known result. See for example section 2 in \cite{AD1982}. In fact in \cite{AD1982}, the  ${\mathcal I}$-tableaux are not necessarily symmetric, but it is easy to check that $\varTheta$ sends symmetric  ${\mathcal I}$-tableaux to symmetric ${\mathcal I}$-tableaux. 

In the orthogonal case, we also have to see that the entries $r_{i, -i}$ are even for all $i \in {\mathcal I}$, $i > 0$. But this follows from the fact that 
\[
\begin{aligned}
r_{i, -i} &= \sum_{\begin{subarray}{c}u, v \in {\mathcal I}\\ u \geq i  \geq -i \geq v \end{subarray}} c_{u, v} = \sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \end{subarray}} c_{u, -u} + \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq -i \geq v\\ (u + v) > 0\end{subarray}} c_{u, v} + \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq -i \geq v\\ 0 > (u + v)\end{subarray}} c_{u, v}\\ &= \sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \end{subarray}} c_{u, -u} + \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq -i \geq v\\ (u + v) > 0 \end{subarray}} c_{u, v} + \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq -i \geq v\\ 0 > (u + v)\end{subarray}} c_{-v, -u}\\ &=  \sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \end{subarray}} c_{u, -u} + 2 \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq -i \geq v\\ (u + v) > 0\end{subarray}} c_{u, v}  
\end{aligned}
\]
and the fact that the $c_{u, -u}$ are even.  

The inverse map of $\varTheta$ is  $\varTheta^{-1}:{\mathfrak R}_{\delta} \longrightarrow {\mathfrak T}_{\delta}$ is 
\[
 \varTheta^{-1}((r_{i, j})_{i, j \in {\mathcal I}, i \geq j}) = (c_{i, j})_{i, j \in I, i \geq j} \quad \text{where $c_{i, j} =  (r_{i, j} - r_{i + 2, j} - r_{i , j - 2} + r_{i + 2, j - 2})$}
\]
We have also to prove that the entries $c_{i, -i}$ are even for all $i \in {\mathcal I}$, $i > 0$ in the orthogonal case.  This follows from
\[
c_{i, -i} = r_{i, -i} - r_{i+2, -i} - r_{i, -i - 2} + r_{i + 2, -i - 2} = r_{i, -i} - 2r_{i + 2, -i}  + r_{i + 2, -i - 2}
\]
and the fact that both $r_{i, -i}$  and $r_{(i + 2), -(i + 2)}$ are even.
\end{proof}

