%definition 3.25
\begin{definition}\label{D:SymmetricTableauIevenOrtho}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and  the coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta}$.  To ${\mathbf c}$, denote the corresponding symmetric function by $c: {\mathbf B} \rightarrow {\mathbb N}$. We define the symmetric ${\mathcal I}$-tableau ${\mathcal T}({\mathbf c})$ as follows: if $c_{i, j}$ is the entry at the row $i$ and column $j$ with $i, j \in {\mathcal I}$ and $i \geq j$, then 
\[
c_{i, j} = \begin{cases} c(b(i, j, 0)), &\text{ if $i + j \ne 0$;}\\ c(b(i, j, 0)), &\text{ if $i + j = 0$ in the symplectic case;} \\  c(b(i, j, 0)) + c(b(i, j, 1)), &\text{ if $i + j = 0$ in the orthogonal case.} \end{cases}
\]

Because $c: {\mathbf B} \rightarrow {\mathbb N}$ is symmetric,  ${\mathcal T}({\mathbf c})$ is clearly a symmetric ${\mathcal I}$-tableau. In the orthogonal case,   we have that $c(b(i, j, 0)) = c(b(i, j, 1))$ when $i + j = 0$ and consequently $c_{i, -i}$ is even. Thus ${\mathcal T}({\mathbf c})$ is an  orthogonal symmetric ${\mathcal I}$-tableau.  

We have 
\[
\begin{aligned}
 \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq v \end{subarray}} c_{u, v} &=  \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq v \\ u + v \ne 0 \end{subarray}} c(b(u, v, 0)) \\ & \quad + \begin{cases} \displaystyle \sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \geq -u \end{subarray}} c(b(u, -u, 0)), &\text{in the symplectic case;}\\ \\ \displaystyle \sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \geq -u \end{subarray}} c(b(u, -u, 0)) + c(b(u, -u, 1)), &\text{in the orthogonal case;} \end{cases} \\
 &= \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ i \in Supp(b) \end{subarray}} c(b) = \delta_i.
 \end{aligned}
 \] 
Consequently $\delta({\mathcal T}({\mathbf c})) = \delta$ and ${\mathcal T}({\mathbf c}) \in {\mathfrak T}_{\delta}$. 
\end{definition}

%lemma 3.26
\begin{lemma}\label{L:TableauOrbitEven}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and let ${\mathfrak g}_2/G^{\iota}$ denotes the set of  $G^{\iota}$-orbits  in ${\mathfrak g}_2$. Then
\begin{enumerate}[\upshape (a)]
\item the map ${\mathcal T}: {\mathfrak C}_{\delta} \rightarrow {\mathfrak T}_{\delta}$, where   ${\mathbf c} \mapsto {\mathcal T}({\mathbf c})$ is a bijection;
\item the map ${\mathfrak g}_2/G^{\iota} \rightarrow  {\mathfrak T}_{\delta} \quad \text{ defined by } \quad G^{\iota} \cdot X \mapsto {\mathcal T}({\mathbf c}_X)$ is a well-defined bijection. 
\end{enumerate}
\end{lemma}
\begin{proof}
(a) is obvious from the definition of ${\mathcal T}$ above and (b) is a corollary of proposition~\ref{Prop_Indexation_Orbits_Even}.
\end{proof}

%notation 3.27
\begin{notation}
We will denote the $G^{\iota}$-orbit  in ${\mathfrak g}_2$ corresponding to the ${\mathcal I}$-tableau ${\mathcal T}  \in {\mathfrak T}_{\delta}$ as defined in the bijection of lemma~\ref{L:TableauOrbitEven} (b)  by ${\mathcal O}_{\mathcal T}$
\end{notation}

In \cite{BI2021},  M. Boos and G. Cerulli Irelli, were able to describe the partial order on the $G^{\iota}$-orbits in ${\frak g}_2$ for symmetric quivers in the orthogonal and symplectic cases for  symmetric quivers of type $A_m^{even}$ and $A_m^{odd}$. We will now describe their result in our case (i.e. $\vert {\mathcal I} \vert$ even).


%proposition 3.28
\begin{proposition}[Boos and Cerulli Irelli]\label{P:PartialOrderIEven}
(In the situation of \ref{S:SetUpAeven}) Let  ${\mathcal I}$-tableaux ${\mathcal T}$, ${\mathcal T}' \in  {\mathfrak T}_{\delta}$ and  the corresponding $G^{\iota}$-orbits ${\mathcal O}_{\mathcal T}$ , ${\mathcal O}_{{\mathcal T}'}$ in ${\frak g}_2$. Then the  $G^{\iota}$-orbit  ${\mathcal O}_{\mathcal T}$ is contained in the Zariski closure of the   $G^{\iota}$-orbit ${\mathcal O}_{{\mathcal T}'}$ if and only if
\[
(r_{i, j})_{i, j \in {\mathcal I}, i \geq j} = {\mathcal R} = \varTheta({\mathcal T}) \leq \varTheta({\mathcal T}') = {\mathcal R}' = (r'_{i, j})_{i, j \in {\mathcal I}, i \geq j}
\]
where the inequality here between the tableaux ${\mathcal R}$ and ${\mathcal R}'$ means $r_{i, j} \leq r'_{i, j}$ for all $i, j \in {\mathcal I}$, $i \geq j$. 
\end{proposition}
%proof
\begin{proof}
First we need to observe that if we consider an element $X$ in the $G^{\iota}$-orbit ${\mathcal O}_{{\mathcal T}''}$ in ${\mathfrak g}_2$, where ${\mathcal T}'' \in {\mathfrak T}_{\delta}$, and, as in part (b) of lemma~\ref{G2AsRepresEven}, we write the linear transformations $X_i:V_i \rightarrow V_{i + 2}$ for $i \in {\mathcal I}$, $i \ne (2m - 1)$ associated to $X$ and that gives us a representation of the quiver $A_{2m}$, then the rank of the composition
\[
X_{i - 2} \circ X_{i- 4} \circ \dots \circ X_{j + 2} \circ X_j:V_j \longrightarrow  V_i \quad \text{for $i, j \in {\mathcal I}$, $i >  j$}
\]
is ${r}_{i, j}''$, where $(r_{i, j}'')_{i, j \in {\mathcal I}, i \geq j} = {\mathcal R}'' = \varTheta({\mathcal T}'')$. This is proved in section 2   in \cite{AD1982} for example.  Note also that ${r}_{i, i}'' = \dim(V_i)$ for all $i \in {\mathcal I}$. 

If we apply this observation for the two orbits  ${\mathcal O}_{\mathcal T}$ and ${\mathcal O}_{{\mathcal T}'}$,  where ${\mathcal O}_{\mathcal T}$ is contained in the Zariski closure $ \overline{{\mathcal O}_{{\mathcal T}'}}$  of the orbit ${\mathcal O}_{{\mathcal T}'}$, then by proposition 2.8 in \cite{AD1982}, it follows that 
\[
(r_{i, j})_{i, j \in {\mathcal I}, i \geq j} = {\mathcal R} = \varTheta({\mathcal T}) \leq \varTheta({\mathcal T}') = {\mathcal R}' = (r'_{i, j})_{i, j \in {\mathcal I}, i \geq j}. 
\]
Proposition 2.8 in \cite{AD1982} states that these ranks cannot increase in a degeneration. 

As for the reciprocal, we must use theorem 7.1 in  \cite{BI2021}.  In our case, this theorem means that the partial order  of symplectic (respectively orthogonal) representations is the same as the partial order induced by forgetting  the symplectic (respectively special orthogonal)  condition and just looking at the representation of the quiver $A_{2m}$. But for the equioriented quiver of type $A_{2m}$, from theorem 5.2 in  \cite{AD1982},  we get that  
\[
{\mathcal R} = \varTheta({\mathcal T}) \leq \varTheta({\mathcal T}') = {\mathcal R}' \quad \Rightarrow \quad {\mathcal O}_{\mathcal T} \subseteq \overline{{\mathcal O}_{{\mathcal T}'}}.
\]
Note that in the article  \cite{BI2021} of M. Boos and G. Cerulli Irelli for orthogonal representations, the isomorphism is the orthogonal isomorphism that is used in the article, but the orthogonal isomorphism is equivalent to special orthogonal isomorphism in the case $A_m^{even}$ as we saw in the proof of proposition~ \ref{Prop_Indexation_Orbits_Even}. For this reason, we can use theorem 7.1 of  \cite{BI2021}.
\end{proof}

