%section 4
\section{$G^{\iota}$-orbits in ${\mathfrak g}_2$ when $\vert {\mathcal I} \vert$ is odd.}

%4.1
\subsection{}
In this section, we will restrict ourself to the symplectic and orthogonal cases when $\vert {\mathcal I} \vert$ is odd. It is simpler and more similar to what we did in the previous section. The special orthogonal case will be treated in the next section. The reason for this is that special orthogonal isomorphism is more restricted that orthogonal isomorphism as we saw in \ref{SS:ExampleIsomorphismSpecialOrtho}.

%4.2
\subsection{}\label{S:SetUpOdd}
In this section,  
\begin{itemize}
\item $m$ is an integer $> 0$;
\item $G$ is the group of automorphisms of a finite dimensional vector space $V$ over ${\mathbf k}$ preserving a fixed non-degenerate  symmetric (respectively skew-symmetric) form $\langle\ , \  \rangle: V \times V \rightarrow {\mathbf k}$, in other words $G = O(V)$ (respectively $G = Sp(V)$); 
\item $\mathfrak g$ is the Lie algebra of $G$, more precisely $X \in {\mathfrak g}$ if and only if $X:V \rightarrow V$ is an endomorphism of $V$ such that $\langle X(v_1), v_2\rangle + \langle v_1 , X(v_2) \rangle = 0$ for all $v_1, v_2 \in V$;
\item $V$ is identified to its dual $V^*$ by the isomorphism $\phi: V \rightarrow V^*$ defined by $v \mapsto \phi_v$, where $\phi_v: V \rightarrow {\mathbf k}$ is $\phi_v(x) = \langle v, x\rangle$ for all $x \in V$;  
\item ${\mathcal I} = \{n \in {\mathbb Z} \mid n \equiv 0 \pmod 2, -2m <  n  < 2m \}$;
\item $\oplus_{i \in {\mathcal I}} V_i$ is a direct sum decomposition of $V$ by  vector subspaces $V_i \ne 0$ such that 
\begin{itemize} \item $\langle v, v'\rangle = 0$ whenever $v \in V_i$, $v' \in V_j$ and $i + j \ne 0$;
			\item $V_{-i} = V_i^*$ for all $i \in {\mathcal I}$ under the identification given by $\phi$ above.
\end{itemize} 
Note that the restriction of the non-degenerate symmetric (respectively skew-symmetric) form bilinear $\langle\ , \ \rangle$ to $V_0 \times V_0$ is a non-degenerate symmetric (respectively skew-symmetric)  form.
\item ${\mathcal B} = \coprod_{i\in {\mathcal I}} {\mathcal B}_i$ is a basis of $V$ such that each ${\mathcal B}_i = \{u_{i, j}  \mid 1 \leq j \leq \delta_i\}$  is a basis of $V_i$ for each $i \in {\mathcal I}$ and $i \ne 0$, where $\delta_i$ is the dimension of $V_i$, and ${\mathcal B}_0 = \{u_{0, j}\mid 1 \leq j \leq \delta_0\}$ (respectively ${\mathcal B}_0 = \{u_{0, j}, u_{0, -j} \mid 1 \leq j \leq \delta'_0\}$) is a basis of $V_0$, where $\delta_0$ (respectively $\delta_0 = 2\delta'_0$) is the dimension of $V_0$  and these bases are such that, for $i, j \in {\mathcal I}$, $i \ne 0$, $j \ne 0$, $1 \leq r \leq \delta_i$ and $1 \leq s \leq \delta_j$, we have
\[
\langle u_{i, r}, u_{j, s}\rangle = \begin{cases}  1, &\text{if $i + j = 0$, $r = s$ and $i > 0$;}\\ \epsilon, &\text{if $i + j = 0$, $r = s$ and $i< 0$;} \\ 0, &\text{otherwise;} \end{cases}
\]
while for $1 \leq r, s \leq \delta_0$, we have 
\[
\langle u_{0, r}, u_{0, s}\rangle = \begin{cases} 1, &\text{if $r + s = \delta_0 + 1$;}\\ 0, &\text{otherwise;}\end{cases}
\]
(respectively for $1 \leq \vert r \vert \leq \delta'_0$ and $1 \leq \vert s \vert \leq \delta'_0$, we have
\[
\langle u_{0, r}, u_{0, s}\rangle = \begin{cases} 1, &\text{if $r + s = 0$ and $r> 0$;}\\ \epsilon, &\text{if $r + s = 0$ and $r < 0$;} \\ 0, &\text{otherwise;)}\end{cases}
\]
and, if $i \ne 0$, $1 \leq s \leq \delta_i$, $1 \leq r \leq \delta_0$(respectively $1 \leq \vert r \vert \leq \delta'_0$), we have 
\[
\langle u_{0, r}, u_{i, s}\rangle = \langle  u_{i, s},  u_{0, r}\rangle = 0.
\]
\item $\iota: {\mathbf k}^{\times} \rightarrow G$ is the homomorphism defined by $\iota(t) v = t^i v$ for all $i \in {\mathcal I}$, $v \in V_i$ and $t \in {\mathbf k}^{\times}$;
\item ${\mathbf B}$ is the set of ${\mathcal I}$-boxes;
\item ${\mathbf B}/\tau$ denote the set of $\langle \tau \rangle$-orbits ${\mathcal O}$ in ${\mathbf B}$; 
\item $\nu = \vert {\mathbf B}/\tau \vert = m^2$;
\item In the symplectic case, $V_0^+$ denotes the subspace of $V_0$ generated  by  ${\mathcal B}_0^+ = \{u_{0, j} \mid 1 \leq j \leq \delta'_0 \}$ and $V_0^-$ denotes the subspace of $V_0$ generated by  ${\mathcal B}_0^- = \{u_{0, -j} \mid 1 \leq j \leq \delta'_0 \}$. Obviously ${\mathcal B}_0^+ $ and ${\mathcal B}_0^- $ are respectively bases of $V_0^+$ and  $V_0^-$
\end{itemize}

%lemme 4.3
\begin{lemma}\label{G2AsRepresOdd}
\begin{enumerate}[\upshape (a)]

% (a)
\item $g \in G^{\iota}$ if and only if all the following conditions are verified:
\begin{itemize}
\item $g(V_i) \subseteq V_i$   for all $i  \in {\mathcal I}$;
\item the restriction $g_{\vert_{V_i}} = g_i$ of $g$ to $V_i$  belongs to $GL(V_i)$ for all $i \in {\mathcal I}$;
\item $(g_{-i})^* g_i = Id_{V_i}$ for all $i \in {\mathcal I}$, $i \ne 0$;
\item $g_0 \in O(V_0)$ (respectively $g_0 \in Sp(V_0)$) relative to the non-degenerate bilinear form $\langle\  , \  \rangle$ restricted to $V_0 \times V_0$.
\end{itemize}
Here $g_{-i}^*: V_i \rightarrow V_i$ is defined using the identification of $V_i$ with $V_{-i}^*$ given by $\phi$. So $\langle g_{-i}^*(u), v \rangle = \langle u, g_{-i}(v)\rangle$ for all $u \in V_i$ and $v \in V_{-i}$.

% (b)
\item $X \in {\mathfrak g}_2$  if and only if all the following conditions are verified:
\begin{itemize}
\item $X(V_i) \subseteq V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 2)$;
\item $X_{-i} = -X_{i - 2}^T$ for all $i \in {\mathcal I}$  and $i \geq 4$;
\item $X_{-2} = - JX^T_0$ where $J$ is the $\delta_0 \times \delta_0$-matrix equal to 
\[
J = \begin{pmatrix} 0 & 0 & \dots & 0 & 1\\ 0 & 0 & \dots & 1 & 0 \\ \vdots & \vdots & \udots & \vdots & \vdots\\ 0 & 1 &\dots & 0 & 0\\ 1 & 0 & \dots & 0 & 0 \end{pmatrix};
\] 
\[
\left(\text{respectively  }
X_0 = (X_0^+ ,  X_0^-) \text{  and   } X_{-2} = \begin{pmatrix} X_{-2}^+ \\ X_{-2}^- \end{pmatrix} = \begin{pmatrix}{\phantom -} (X_0^-)^T \\  -(X_0^+)^T \end{pmatrix} \right),
\]
\end{itemize}
where $X_i$ is the matrix of the linear transformation $X\vert_{V_i}: V_i \rightarrow V_{i + 2}$ of the restriction of $X$ to $V_i$ relative to the bases ${\mathcal B}_i$ and ${\mathcal B}_{i + 2}$ for all $i \in {\mathcal I}$ and $i \ne (2m - 2)$,  $X_0^+$ is the matrix of the restriction of $X_0$ to $V_0^+$ relative to the bases ${\mathcal B}_0^+$ and ${\mathcal B}_{2}$ , $X_0^-$ is the matrix of the restriction of $X_0$ to $V_0^-$  relative to the bases ${\mathcal B}_0^-$ and ${\mathcal B}_{2}$, $X_{-2}^+$ is the matrix of the linear transformation obtained from $X_{-2}$ followed by the projection of $V_0^+ \oplus V_0^-$ to $V_0^+$  relative to the bases ${\mathcal B}_{-2}$ and ${\mathcal B}_{0}^+$ and $X_{-2}^-$ is the matrix of the linear transformation obtained from $X_{-2}$ followed by the projection of $V_0^+ \oplus V_0^-$ to $V_0^-$  relative to the bases ${\mathcal B}_{-2}$ and ${\mathcal B}_{0}^-$. Above $M^T$ denotes the transpose of the matrix $M$. 

Moreover the subset of elements 
\[
(X_i)_{\begin{subarray}{l} i \in {\mathcal I}\\ i \ne (2m - 2)\end{subarray}} \in \left(\bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ i \ne (2m - 2)\end{subarray}} Hom(V_i, V_{i + 2})\right),
\]
  such that the above conditions for the $X_i$ are satisfied,  is a subspace of 
  \[
  \bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ i \ne (2m - 2)\end{subarray}} Hom(V_i, V_{i + 2})
  \]
   isomorphic to ${\mathfrak g}_2$.

% (c)
\item $Z \in {\mathfrak g}_0$ if and only if all the following conditions are verified
\begin{itemize}
\item $Z(V_i) \subseteq V_{i}$ for all $i \in {\mathcal I}$;
\item $Z_{-i} = -Z_{i}^T$ for all $i \in {\mathcal I}$ and $i \geq 2$;
\item  $Z_0$ is such that $\langle Z_0(v), v'\rangle + \langle v, Z_0(v') \rangle = 0$ for all $v, v' \in V_0$; in other words,  $Z_0$ is in the Lie algebra corresponding to $V_0$ and the bilinear form $\langle\ , \  \rangle$;
\end{itemize}
where we denote  $Z_i$ is the matrix of the linear transformation $Z\vert_{V_i}: V_{i} \rightarrow V_{i}$ the restriction of $Z$ to $V_i$ relative to the bases ${\mathcal B}_i$ and ${\mathcal B}_{i}$ for all $i \in {\mathcal I}$. 

Moreover the subset of elements 
\[
(Z_i)_{i \in {\mathcal I}} \in \left(\bigoplus_{ i \in {\mathcal I}} Hom(V_i, V_{i})\right),
\]
 such that the above conditions for the $Z_i$ are satisfied,  is a subspace of 
 \[
 \bigoplus_{ i \in {\mathcal I}} Hom(V_i, V_{i})
 \]
  isomorphic to ${\mathfrak g}_{0}$.

  % (d)

\item $\{(g_i)_{i \in {\mathcal I}} \in \prod_{i \in {\mathcal I}} GL(V_i) \mid g_{-i} = (g_i^*)^{-1} \text{ for all $i > 0$ and } g_0 \in G_0\}$ is a closed subgroup of  $\prod_{i \in {\mathcal I}} GL(V_i)$ and is isomorphic to $\prod_{i \in {\mathcal I}, i > 0} GL(V_i) \times G_0$,  where $G_0$  is the orthogonal group $O(V_0)$ (respectively the symplectic group $Sp(V_0)$). 

Moreover the function 
\[
\Phi: G^{\iota} \rightarrow \left. \left\{(g_i)_{i \in {\mathcal I}} \in \prod_{i \in {\mathcal I}} GL(V_i)\   \right\vert g_{-i} = (g_i^*)^{-1} \text{ for all $i > 0$ and } g_0 \in G_0 \right\}
\]
defined by $\Phi(g) = (g_{i})_{i \in {\mathcal I}}$  is a well-defined  isomorphism of groups.

% (e)

\item The restriction of the adjoint action of $G$ to $G^{\iota}$ acts on ${\mathfrak g}_2$ and,  under the description of ${\mathfrak g}_2$ as a subspace of $\oplus_{i \in {\mathcal I}, i \ne (2m - 2)} Hom(V_i, V_{i + 2})$ in (b), this action  is given by 
\[
Ad(g)(X) \mapsto (g_{i + 2}X_{i}g_{i}^{-1})_{i \in {\mathcal I}, i \ne (2m - 2)}
\]
for all $g \in G^{\iota}$ and where $\Phi(g) = (g_{i})_{i \in {\mathcal I}}$. 
\end{enumerate}
\end{lemma}

%proof of lemma 4.3
\begin{proof}
% (a)
(a) $\Rightarrow$) For  $i \in {\mathcal I}$, $V_i$ is the eigenspace of $\iota(t)$ with eigenvalue $t^i$ for all $t \in {\mathbf k}^{\times}$. Moreover  when $i, j \in {\mathcal I}$ and $i \ne j$,  these eigenvalues $t^i$ and $t^j$ are distinct.  Because $g \iota(t) = \iota(t) g$ for all $t \in {\mathbf k}^{\times}$ when $g \in G^{\iota}$, then $g$ preserves these eigenspaces and we get $g(V_i) \subseteq V_i$ for all $i \in I$. $g_i \in GL(V_i)$ follows easily  because $g \in GL(V)$ and $g(V_i) \subseteq V_i$.

Because we have $\langle g(v), g(v') \rangle = \langle v, v' \rangle$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for all $v \in V_i$ and $v' \in V_{-i}$ that 
\[
\langle g_i(v), g_{-i}(v')\rangle = \langle g_{-i}^* g_i(v), v'\rangle = \langle v, v'\rangle  \Rightarrow  (g_{-i}^*) g_i = Id_{V_i} 
\]
 for all $i \in I$, $ i \ne 0$.  For $i = 0$, we get that $\langle g_{0}(v), g_{0}(v')\rangle = \langle v, v'\rangle$ for all $v, v' \in V_0$.
 Consequently  $g_0 \in O(V_0)$ in the orthogonal case (respectively $g_0 \in Sp(V_0)$ in the symplectic case) relative to the non-degenerate bilinear form $\langle\  , \  \rangle$ restricted to $V_0 \times V_0$.

 $\Leftarrow$) If $g(V_i) \subseteq V_i$, $g_i \in GL(V_i)$, $(g_{-i})^* g_i = Id_{V_i}$ for all $i \in {\mathcal I}$, $i \ne 0$ and $g_0 \in O(V_0)$ in the orthogonal case  (respectively $g_0 \in Sp(V_0)$ in the symplectic case), then $g$ is an automorphism. Because of the condition on our direct sum decomposition of $V$,  we get easily that $g$ preserves the non-degenerate bilinear form $\langle\ , \ \rangle$, in other words $g \in G$. Because $g(V_i) \subseteq V_i$, we get that $g$ commutes with $\iota(t)$ for all $t \in {\mathbf k}^{\times}$ and $g \in G^{\iota}$.  (a) is proved.

% (b)
(b) $\Rightarrow$)  Because $Ad(\iota(t)) X = t^2 X$ for all $t \in {\mathbf k}^{\times}$ when $X \in {\mathfrak g}_2$, we have $\iota(t) X = t^2 X \iota(t)$ for all $t \in {\mathbf k}^{\times}$.  So if $v \in V_i$, then $\iota(t) X(v) =  t^2 X \iota(t) (v) = t^{i + 2} X(v)$ and consequently $X(V_i) \in V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 2)$. Note that this last equation means also that $X(V_{2m - 2}) = 0$

Note that if $i \in {\mathcal I}$, then $-i \ne i - 2$, because $-i = i -2$ we would have $i = 1$ and the elements of ${\mathcal I}$ are even numbers.  Because $\langle X(v), v' \rangle + \langle v, X(v')\rangle = 0$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for $i \in {\mathcal I}$, $i \geq 2$ and for all $v \in V_{-i}$,  $v' \in V_{i - 2}$ that  
\[
\langle X_{-i}(v), v'\rangle + \langle v, X_{i - 2} (v')\rangle = 0.
\]
In this last equation, if we substitute 
\[
X_{-i}(u_{-i, s}) = \sum_{q' = 1}^{\delta_{i - 2}} \xi_{q', s}^{(-i)} u_{(-i + 2), q'} \quad \text{ and } \quad X_{(i - 2)}(u_{(i - 2), r}) = \sum_{q = 1}^{\delta_{i}} \xi_{q, r}^{(i - 2)} u_{i, q},
\]
we get for $i \geq 4$ that $\epsilon \xi_{rs}^{(-i)} + \epsilon \xi_{sr}^{(i - 2)} = 0$ for all $1 \leq s \leq \delta_i$ and $1 \leq r \leq \delta_{i - 2}$ and thus $X_{-i} = -X_{i - 2}^T $. 

If $i = 2$ and we are in the orthogonal case, from $\langle X_{-2}(v), v'\rangle + \langle v, X_0(v')\rangle = 0$ for all $v \in V_{-2}$, $v' \in V_0$ and writing 
\[
X_{-2}(u_{-2, s}) = \sum_{q' = 1}^{\delta_{0}} \xi_{q',s}^{(-2)} u_{0, q'}  \quad \text{ and } \quad X_{0}(u_{0, r}) = \sum_{q = 1}^{\delta_{2}} \xi_{q, r}^{(0)} u_{2, q},
\]
we get that $\xi_{(\delta_0 + 1 - r), s}^{(-2)} + \xi_{s, r}^{(0)} = 0$ for all $1 \leq r \leq \delta_0$, $1 \leq s \leq \delta_2$ and $X_{-2} = -J X_0^T$.

If $i = 2$ and we are in the symplectic case,  from $\langle X_{-2}(v), v'\rangle + \langle v, X_{0} (v')\rangle = 0$ for all $v \in V_{-2}$,  $v' \in V_{0}$ and writing
\[
X_{-2}(u_{-2, s}) = \sum_{q' = 1}^{\delta'_{0}} \xi_{-q',s}^{(-2)} u_{0, -q'}  +  \sum_{q'' = 1}^{\delta'_{0}} \xi_{q'', s}^{(-2)} u_{0, q''} \quad \text{ and } \quad X_{0}(u_{0, r}) = \sum_{q = 1}^{\delta_{2}} \xi_{q, r}^{(0)} u_{2, q},
\]
for $s = 1, 2, \dots, \delta_2$ and $r = -\delta'_0, \dots, -2, -1, 1, 2, \dots, \delta'_0$, we get that  
\[
\begin{cases} \xi_{-r, s}^{(-2)} -  \xi_{s, r}^{(0)} = 0 &\text{if  $r < 0$;}\\ \\ -\xi_{-r, s}^{(-2)} -  \xi_{s, r}^{(0)} = 0 &\text{if  $r > 0$.}  \end{cases}
\] 

Consequently
\[
X_{-2} =  \begin{pmatrix} X_{-2}^+\\ X_{-2}^- \end{pmatrix} = \begin{pmatrix} \phantom -(X_0^-)^T\\ -(X_0^+)^T \end{pmatrix} \text{ where }  X_0 = (X_0^+ ,  X_0^-).
\]

$\Leftarrow$)  If $X_{-i} = -X_{i  - 2}^T$ for all $i \in {\mathcal I}$, $i \geq 4$,  and in the orthogonal case, we have $X_{-2} = -X_0^T$; while in the symplectic case, we have 
\[
X_0 = (X_0^+ ,  X_0^-) \quad \text{  and } X_{-2} =  \begin{pmatrix} X_{-2}^+\\ X_{-2}^- \end{pmatrix} = \begin{pmatrix} \phantom -(X_0^-)^T\\ -(X_0^+)^T \end{pmatrix},
\]
with the above notation,  then we get that $\langle X(v), v' \rangle + \langle v, X(v')\rangle = 0$ for all $v, v' \in V$ by only checking it on the basis ${\mathcal B}$  and this means that $X \in {\mathfrak g}$. If we add the condition  $X(V_i) \subseteq V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne (2m - 2)$, we have  that $X \in {\mathfrak g}_2$. The rest of the statements in (b) are easily proved. 

(c) $\Rightarrow$)  Because $Ad(\iota(t)) Z = Z$ for all $t \in {\mathbf k}^{\times}$ when $Z \in {\mathfrak g}_0$, we have $\iota(t) Z =  Z \iota(t)$ for all $t \in {\mathbf k}^{\times}$.  So if $v \in V_i$, then $\iota(t) Z(v) = Z \iota(t) (v) = t^{i} Z(v)$ and consequently $Z(V_i) \in V_{i}$ for all $i \in {\mathcal I}$. 

Because $\langle Z(v), v' \rangle + \langle v, Z(v')\rangle = 0$ for all $v, v' \in V$ and our conditions on the direct sum decomposition, we get for $i \in {\mathcal I}$ and for all $v \in V_{i}$,  $v' \in V_{-i}$ that  
\[
\langle Z_{i}(v), v'\rangle + \langle v, Z_{-i} (v')\rangle = 0.
\]
In this last equation, if we substitute 
\[
Z_{i}(u_{i, s}) = \sum_{q' = 1}^{\delta_{i}} \zeta_{q', s}^{(i)} u_{i, q'} \quad \text{ and } \quad Z_{-i}(u_{-i, r}) = \sum_{q = 1}^{\delta_{i}} \zeta_{q, r}^{(-i)} u_{-i, q},
\]
we get for $i \geq 2$ that $ \zeta_{r,s}^{(i)} +  \zeta_{s,r}^{(-i)} = 0$ for all $1 \leq s, r \leq \delta_i$. Thus $Z_{-i} = -Z_{i}^T $ for all $i \in {\mathcal I}$ and $i \geq 2$.

For $i = 0$, we get that 
\[
\langle Z_{0}(v), v'\rangle + \langle v, Z_{0} (v')\rangle = 0 \quad \text{ for all $v, v' \in V_0$,}
\]
in other words, $Z_0$  is in the Lie algebra corresponding to $V_0$ and the bilinear form $\langle \  , \  \rangle$.

$\Leftarrow$)  If $Z_{-i} = -Z_{i}^T$ for all $i \in {\mathcal I}$,  $i \geq 2$ and if $Z_0$  is in the Lie algebra corresponding to $V_0$ and the bilinear form $\langle \  , \  \rangle$, then we get that $\langle Z(v), v' \rangle + \langle v, Z(v')\rangle = 0$ for all $v, v' \in V$ by only checking it on the basis ${\mathcal B}$  and this means that $Z \in {\mathfrak g}$. If we add the condition  $Z(V_i) \subseteq V_{i}$ for all $i \in {\mathcal I}$, we have  that $Z \in {\mathfrak g}_0$. The rest of the statements in (c) are easily proved. 

(d) follows easily from (a).

(e) follows easily from (b) and the fact that $Ad(g)(X) = gXg^{-1}$ for all $g \in G^{\iota}$. 
\end{proof}

%corollary 4.4
\begin{corollary} The dimension $\dim({\mathfrak g}_2)$ of ${\mathfrak g}_2$  is equal to
\[
 \sum_{i \in {\mathcal I}, 0 \leq i < (2m - 2)} \delta_i \delta_{i + 2}
\]
\end{corollary}
\begin{proof}
This follows easily from proposition~\ref{G2AsRepresOdd} (b).
\end{proof}

% 4.5
\subsection{}
In (b) and (e) above, we have shown that ${\mathfrak g}_2$ with the action of the restriction of the adjoint action of $G$ to $G^{\iota}$ is isomorphic to the space of orthogonal (respectively symplectic) representations of the symmetric quiver of type $A_{m}^{odd}$. 

% 4.6
\subsection{}
The notions of symmetric function $c : {\mathbf B} \rightarrow {\mathbb N}$, of associated coefficient function ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ and dimension vector $\delta({\mathbf c}) = \delta(c)$ for ${\mathbf c}$ and $c$ are identical to the ones when ${\mathcal I}$ is even as in definition~\ref{D:CoefficientFunction}.

${\mathfrak C}$ and ${\mathfrak C}_{\delta}$ for $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ such that $\delta_i = \delta_{-i}$ for all $i \in {\mathcal I}$ denote respectively sets of coefficient functions as in notation~\ref{N:CoefficientFunctionSet}. 

% Notation 4.7
\begin{notation}\label{N:CCorrespondanceOdd}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ be a vector such that $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and let  ${\mathbf c} \in  {\mathfrak C}_{\delta}$ be a coefficient function.  Denote by $V({\mathbf c})$: the direct sum as ${\mathcal I}$-graded vector space and  as  $\epsilon$-representations of ${\mathbf c}({\mathcal O})$ copies of $V({\mathcal O})$ with a ${\mathcal I}$-basis 
\[
{\mathcal B}_{\mathbf c} = \coprod_{{\mathcal O} \in {\mathbf B}/\tau} \coprod_{b \in {\mathcal O}} \{v_i^j(b) \mid i \in Supp(b), 1 \leq j \leq {\mathbf c}({\mathcal O})\}
\]
such that, for  $b = b(i_1, j_1, k_1)$, $b' = b(i_2, j_2, k_2)$, $i, i' \in {\mathcal I}$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, we have 
\[
\langle v_i^j(b), v_{i'}^{j'}(b')\rangle_{\mathbf c} 
= \begin{cases} 1, &\text{if $j' = j$, $b' = \tau(b)$, $i > 0$ and $i + i' = 0$; } \\
\epsilon, &\text{if $j' = j$,  $b' = \tau(b)$, $i < 0$ and $i + i' = 0$; }\\ 
1, &\text{if $j' = j$,  $b' = \tau(b)$, $i = i' = 0$ and $b$ is above}\\ &\text{the principal diagonal; }\\ 
\epsilon, &\text{if $j' = j$,  $b' = \tau(b)$, $i = i' = 0$ and $b$ is below}\\ &\text{the principal diagonal; }\\ 
\epsilon^{k_1}, &\text{if $j' = j$,  $b' = \tau(b)$,  $\tau(b) \ne b$,  $i = i' = 0$ and $b$ is on}\\ &\text{the principal diagonal; }\\ 
1, &\text{if $j' = j$,  $b' = \tau(b) = b$,  $i = i' = 0$ and $b$ is on}\\ &\text{the principal diagonal; }\\
0, &\text{otherwise.}
\end{cases}
\]
This is just from the formulae of \ref{N:BasisVOrbit} adapted to our situation.

We will denote by ${\mathfrak g}(V({\mathbf c}))$:  the Lie algebra corresponding to $(V({\mathbf c}),  \langle\  , \   \rangle_{\mathbf c})$. In other words, ${\mathfrak g}(V({\mathbf c}))$ is the vector space of linear transformations $X:V({\mathbf c}) \rightarrow V({\mathbf c})$ such that $\langle X(u), v\rangle_{\mathbf c} + \langle u, X(v)\rangle_{\mathbf c} = 0$ for all  $u, v \in V({\mathbf c})$.

From our construction and proved similarly as in notation~\ref{N:CCorrespondance}, we have that $V({\mathbf c}) = \oplus_{i \in {\mathcal I}} V_i({\mathbf c})$ and $\dim(V_i({\mathbf c})) = \delta_i$ for all $i \in {\mathcal I}$.  

Let the three ${\mathcal I}$-graded  linear transformations  
\[
E_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c}), \quad   H_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c}) \quad \text{ and } \quad F_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c})
\]
denote the direct sum as ${\mathcal I}$-graded linear transformation of ${\mathbf c}({\mathcal O})$ copies of the linear transformations 
\[
E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}), \quad  H_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}) \quad \text{ and } \quad F_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O}).
\]
By applying proposition~\ref{P:JMTripleProof} on each summand, we get that these three linear transformations are such that 
\begin{itemize}
\item $E_{\mathbf c}$ is of degree $2$, $H_{\mathbf c}$ is of degree $0$ and $F_{\mathbf c}$ is of degree $-2$;
\item $E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c}$ belong to the Lie algebra  ${\mathfrak g}(V({\mathbf c}))$;
\item $[H_{\mathbf c}, E_{\mathbf c}] = 2E_{\mathbf c}$, $[H_{\mathbf c}, F_{\mathbf c}] = -2F_{\mathbf c}$ and $[E_{\mathbf c}, F_{\mathbf c}] = H_{\mathbf c}$, in other words,  the triple $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ is an ${\mathcal I}$-graded Jacobson-Morozov triple for the Lie algebra of $(V({\mathbf c}),  \langle\  , \   \rangle_{\mathbf c})$;
\item  the ${\mathcal I}$-graded linear transformation $\phi_{\mathbf c}: V({\mathbf c}) \rightarrow V({\mathbf c})$ given by 
\[
\phi_{{\mathbf c}, i} = {E_{\mathbf c}}\vert_{V_i({\mathbf c})}: V_i({\mathbf c}) \rightarrow V_{i + 2}({\mathbf c}) \quad \text{for all $i \in {\mathcal I}$  such that $(i + 2) \in {\mathcal I}$},
\]
is  such that $(V({\mathbf c}), \phi_{\mathbf c}, \langle\ , \ \rangle_{\mathbf c})$ is an $\epsilon$-representation.
\end{itemize}

As such we can express these linear transformations on the elements of the basis ${\mathcal B}_{\mathbf c}$ using the expressions in \ref{SS:EHFDefinition}. For example, let ${\mathcal O}$ denote the $\langle \tau \rangle$-orbit of $b$, then,  if the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports,  $1 \leq j \leq {\mathbf c}({\mathcal O})$ and $i \in Supp(b)$, we have
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i < 0$;} \end{cases}
\]
while if the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports,  $b = b(i_1, j_1, k_1) \in {\mathcal O}$, $1 \leq j \leq {\mathbf c}({\mathcal O})$  and $i \in Supp(b)$, then we have 
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}^j(b), &\text{if  $i < 0$;}\\   {\phantom -} \epsilon v_2^j(b), &\text{if $i = 0$, $\max(Supp(b)) > 0$ and $b$ is below the principal}\\ &\text{diagonal;}\\ {\phantom -}  v_2^j(b), &\text{if $i = 0$, $\max(Supp(b)) > 0$ and $b$ is above the principal}\\ &\text{diagonal;} \\ {\phantom -} \epsilon^{k_1}v_{2}^j(b), &\text{if $i = 0$, $\max(Supp(b)) > 0$ and $b$ is on the principal}\\ &\text{diagonal;}  \end{cases}
\]
\end{notation}

%4.8
\subsection{}\label{SS:coefficientOrbitOdd}
Given an element $X \in {\mathfrak g}_2$, we will now associate to it a coefficient function ${\mathbf c}_X:{\mathbf B}/\tau \rightarrow {\mathbb N}$ as follows. By lemma~\ref{G2AsRepresOdd}  (b) and with the notation of this lemma, $X \in {\mathfrak g}_2$ is equivalent to giving the $\epsilon$-representation  $(V, \phi_V, \langle\  ,\  \rangle)$, where 
\[
\phi_{V, i} = X\vert_{V_i} : V_i \rightarrow  V_{i + 2} \quad v \mapsto X(v) \quad  \text{ for all $v \in V_i$}
\]
is the restriction of $X$ on $V_i$ for all $i \in {\mathcal I}$, $i \ne (2m - 1)$. By the theorem of Krull-Remak-Schmidt, this $\epsilon$-representation can be written in essentially unique way as a direct sum of indecomposable  $\epsilon$-representations (up to isomorphism). We saw in proposition~\ref{P:JMTripleProof} that the set of indecomposable $\epsilon$-representations is in bijection with the set ${\mathbf B}/\tau$. More precisely, for each orbit ${\mathcal O} \in {\mathbf B}/\tau$, we have constructed a representative $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$ of the isomorphism class of the indecomposable $\epsilon$-representation. Denote by ${\mathbf c}_X({\mathcal O})$: the multiplicity (up to isomorphism) of the indecomposable  $\epsilon$-representation $(V({\mathcal O}), \phi_{\mathcal O}, \langle \  , \  \rangle_{\mathcal O})$. So the coefficient function ${\mathbf c}_X:{\mathbf B}/\tau \rightarrow {\mathbb N}$ is defined by ${\mathcal O} \mapsto {\mathbf c}_X({\mathcal O})$.

%Remark 4.9
\begin{remark}
Above in the case of  $\epsilon = 1$, i.e. the orthogonal case, we are in the  situation where $G = O(V)$  as in the article \cite{DW2002} of Derksen and Weyman. We will treat the case of $SO(V)$ in the next section. Because we are in the orthogonal case, the coefficient function ${\mathbf c}_X:{\mathbf B}/\tau \rightarrow {\mathbb N}$  is well-defined.
\end{remark}

%4.10
\subsection{}\label{SS:IsomorphismV(c)andVOddCase}
We will now constructed an ${\mathcal I}$-graded isomorphism $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$. We will define this isomorphism on the bases ${\mathcal B}_{\mathbf c}$ of $V({\mathbf c})$ and ${\mathcal B}$ of $V$. 

Let $i \in {\mathcal I}$. We will first define the function if $i > 0$ and secondly if $i = 0$.  In the following, let $c:{\mathbf B} \rightarrow {\mathbb N}$ be the unique symmetric function corresponding to the coefficient function ${\mathbf c}: {\mathbf B}/\tau \rightarrow {\mathbb N}$.  

Start with $i > 0$. The proof is similar to the one when $\vert {\mathcal I} \vert$ is even in proposition~\ref{Prop_Indexation_Orbits_Even}.   We get easily that 
\[
\{b \in {\mathbf B} \mid i \in Supp(b)\} \rightarrow \{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\} \text{ defined by } b \mapsto \tau(b)
\]
is a bijection.  Fix a total order $b_1 > b_2 > \dots > b_n$ on the set $\{b \in {\mathbf B} \mid i \in Supp(b)\}$ such that $c(b_r) \geq c(b_s)$ whenever $r < s$ for $1 \leq r, s \leq n$ and let $b'_1 > b'_2 > \dots > b'_n$ be the total order on the set $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\}$ such that     $b'_r = \tau(b_r)$ for $1 \leq r \leq n$. 
Consider the Young diagram corresponding to the partition $c(b_1) \geq c(b_2) \geq \dots \geq c(b_n)$. So the row indexed by $b_r$ will have $c(b_r)$ columns.  We would get the same Young diagram $c(b'_1) \geq c(b'_2) \geq \dots \geq c(b'_n)$ if we had started with the total order  $b'_1 > b'_2 > \dots > b'_n$  on the set $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b')\}$. This follows from the fact that $c$ is symmetric.  This partition is a partition of $\delta_i$ from~\ref{N:CCorrespondanceOdd}.  In this Young diagram, we fill the boxes with the integers from 1 to $\delta_i$ in strictly increasing order from left to right and top to bottom.   We define $T_{{\mathbf c}, i}: V_i({\mathbf c}) \rightarrow V_i$ (respectively $T_{{\mathbf c}, -i}: V_{-i}({\mathbf c}) \rightarrow V_{-i}$)  to be the unique linear transformation such that if the entry in the box at row $r$ and column $s$ is $j$, then 
$T_{{\mathbf c}, i}(v_i^s(b_r)) = u_{i, j}$ (respectively $T_{{\mathbf c}, -i}(v_{-i}^s(b'_r)) = T_{{\mathbf c}, -i}(v_{-i}^s(\tau(b_r))) = u_{-i, j}$). 


Secondly we consider the case $i = 0$.  In \ref{SS:EHFDefinition} (second case), we have noted that  the orbit ${\mathcal O} \in {\mathbf B}/\tau$ has overlapping ${\mathcal I}$-box supports if and only if  $0 \in Supp(b)$ for any ${\mathcal I}$-box $b \in {\mathcal O}$. 

In the symplectic case and when $\vert {\mathcal I} \vert$ is odd, all the orbits ${\mathcal O} \in {\mathbf B}/\tau$ are such that ${\mathcal O} = \{b, \tau(b)\}$ with $\tau(b) \ne b$ for some $b \in {\mathbf B}$, in other words, $\vert {\mathcal O} \vert = 2$. From this observation, we get that $c(b) = c(\tau(b)) = {\mathbf c}({\mathcal O})$. we have that
\[
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b)\end{subarray}} c(b) = 2 \sum_{\mathcal O} {\mathbf c}({\mathcal O}) = \delta_0 = 2\delta'_0 \quad \Rightarrow \quad \sum_{\mathcal O} {\mathbf c}({\mathcal O}) = \delta'_0,
\]
where the second sum over ${\mathcal O}$ is over the set of orbits ${\mathcal O}$ having overlapping ${\mathcal I}$-box supports. Fix a total order ${\mathcal O}_1 > {\mathcal O}_2 > \dots > {\mathcal O}_{n'}$ on the set 
\[
\{{\mathcal O} \in {\mathbf B}/\tau \mid {\mathcal O} \text{ has overlapping ${\mathcal I}$-box supports}\} 
\]
such that  ${\mathbf c}({\mathcal O}_r) \geq {\mathbf c}({\mathcal O}_s)$ whenever $r < s$ for $1 \leq r, s \leq n'$. Consider the Young diagram corresponding to the partition ${\mathbf c}({\mathcal O}_1) \geq {\mathbf c}({\mathcal O}_2) \geq \dots \geq {\mathbf c}({\mathcal O}_{n'})$. So the row indexed by ${\mathcal O}_r$ will have ${\mathbf c}({\mathcal O}_r)$ columns. This partition is a partition of $\delta'_0$ from our observation above.  In this Young diagram, we fill the boxes with the integers from 1 to $\delta'_0$ in strictly increasing order from left to right and top to bottom.   We define $T_{{\mathbf c}, 0}: V_0({\mathbf c}) \rightarrow V_0$  to be the unique linear transformation such that if the entry in the box at row $r$ corresponding to the orbit ${\mathcal O}_r$ and column $s$, where $1 \leq s \leq {\mathbf c}({\mathcal O}_r)$ is $j$,   then  we define
\[
T_{{\mathbf c}, 0}(v_0^s(b)) = \begin{cases} u_{0, j}, &\text{if $b$ is above the principal diagonal;}\\ u_{0, -j}, &\text{if $b$ is below the principal diagonal;}\\ u_{0, \epsilon^{k_1} j}, &\text{if $b$ is on the principal diagonal and $b = b(i_1, j_1, k_1)$;} \end{cases} 
\]
for $b \in {\mathcal O}_r$. 

In the orthogonal case and when $\vert {\mathcal I}\vert$ is odd,  the $\langle \tau \rangle$-orbits are of two types: either the $\langle \tau \rangle$-orbit ${\mathcal O} = \{ b \}$, where $b \in {\mathbf B}$, $\tau(b) = b$ and $b$ is on the principal diagonal, or the $\langle \tau \rangle$-orbit ${\mathcal O} = \{ b, \tau(b) \}$, where $b \in {\mathbf B}$, $\tau(b) \ne b$ and $b$ is not on the principal diagonal. Denote by ${\mathbf B}^+$: the set of ${\mathcal I}$-boxes strictly above the principal diagonal and by ${\mathbf B}^-$: the set of ${\mathcal I}$-boxes strictly below the principal diagonal.  Write 
\[
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b)\\ \tau(b) = b \end{subarray}} c(b) = \delta''_0 \quad \text{ et } \quad \sum_{\begin{subarray}{c} b \in {\mathbf B}^+\\ 0 \in Supp(b) \end{subarray}} c(b) = \delta'''_0 
\]
Note that $\delta''_0$ has the same parity than $\delta_0$ because
\[
\delta_0 = \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b) \end{subarray}} c(b) = \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b)\\ \tau(b) = b \end{subarray}} c(b) + 2 \sum_{\begin{subarray}{c} b \in {\mathbf B}^+\\ 0 \in Supp(b) \end{subarray}} c(b) = \delta''_0 + 2 \delta'''_0.
\]
Here we have used the fact that the function $c: {\mathbf B} \rightarrow {\mathbb N}$ is symmetric. 

We get easily that $\{b \in {\mathbf B}^+ \mid 0 \in Supp(b) \} \rightarrow \{b \in {\mathbf B}^- \mid 0 \in Supp(b) \}$ defined by $b \mapsto \tau(b)$ is a bijection. Fix a total order $b_1 > b_2 > \dots > b_n$ on the set $\{ b \in {\mathbf B}^+ \mid  0 \in Supp(b)\}$ such that $c(b_r) \geq c(b_s)$ whenever $r < s$ for $1 \leq r, s \leq n$ and let $b'_1 > b'_2 > \dots > b'_n$ be the total order on the set $\{ b' \in {\mathbf B}^- \mid  0 \in Supp(b')\}$ such that $b'_r = \tau(b_r)$ for $1 \leq r \leq n$. Consider the Young diagram ${\mathcal Y}_1$ corresponding to the partition $c(b_1) \geq c(b_2) \geq \dots \geq c(b_n)$. So the row indexed by $b_r$ will have $c(b_r)$ columns. We would get the same Young diagram $c(b'_1) \geq c(b'_2) \geq \dots \geq c(b'_n)$ if we had started with the total order $b'_1 > b'_2 > \dots > b'_n$, because $c$ is symmetric. This partition is a partition of $\delta'''_0$. In the Young diagram ${\mathcal Y}_1$, fill the boxes with the integers from $1$ to $\delta'''_0$ with strictly increasing order from left to right and top to bottom.

Consider also $\{ b'' \in {\mathbf B} \mid 0 \in Supp(b''), \tau(b'') = b''\}$. Fix a total order $b''_1 > b''_2 > \dots > b''_{n'}$ on this last set such that $c(b''_r) \geq c(b''_s)$ whenever $1 \leq r < s \leq n'$. Consider the Young diagram ${\mathcal Y}_2$ corresponding to the partition $c(b''_1) \geq c(b''_2) \geq \dots \geq c(b''_{n'})$. So the row indexed by $b''_r$ will have $c(b''_r)$ columns. This partition is a partition of $\delta''_0$.  In the Young diagram ${\mathcal Y}_2$, fill the boxes with the integers from $(\delta'''_0 + 1)$ to $(\delta'''_0 + \delta''_0)$ with strictly increasing order from left to right and top to bottom.

To define $T_{{\mathbf c}, 0}:V_0({\mathbf c}) \rightarrow V_0$, we need to consider two situations:  $\delta_0$ is either even or odd. Fix  a square root $\sqrt 2$  of $2$ and a square root $\sqrt{-2}$ of $-2$ in the field ${\mathbf k}$.  Recall our hypothesis about the characteristic $p$ of the field ${\mathbf k}$ in \ref{SS:CharacteristicK}. 

 First we start with $\delta_0$ being even and consequently $\delta''_0$ is even. Define with the same notation as above and for $b \in {\mathbf B}$, $0 \in Supp(b)$
\[
T_{{\mathbf c}, 0}(v_0^s(b)) = \begin{cases} 
u_{0, j}, &\text{if $b \in {\mathbf B}^+$ and $b = b_r$;}\\ \\
u_{0, (\delta_0 + 1 - j)}, &\text{if $b \in {\mathbf B}^-$ and $b = \tau(b_r) = b'_r$;}\\ \\
\frac{1}{\sqrt 2}\left(u_{0, j'} + u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + 1) \leq j' \leq (\delta'''_0 + (\delta''_0 /2))$; }\\ \\
\frac{1}{\sqrt {-2}}\left(u_{0, j'} - u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + (\delta''_0/2) + 1) \leq j' \leq (\delta'''_0 + \delta''_0)$; }
\end{cases}
\]
where the entry in the filled Young diagram ${\mathcal Y}_1$ in the box at row $r$ and column $s$ is $j$ and the entry in the filled Young diagram  ${\mathcal Y}_2$ in the box at row $r$ and column $s$ is $j'$.

Secondly consider the case where $\delta_0$ being odd and consequently $\delta''_0$ is also odd. Define with the same notation as above and for $b \in {\mathbf B}$, $0 \in Supp(b)$
\[
T_{{\mathbf c}, 0}(v_0^s(b)) = \begin{cases} 
u_{0, j}, &\text{if $b \in {\mathbf B}^+$ and $b = b_r$;}\\ \\
u_{0, (\delta_0 + 1 - j)}, &\text{if $b' \in {\mathbf B}^-$ and $b = \tau(b_r) = b'_r$;}\\ \\
\frac{1}{\sqrt 2}\left(u_{0, j'} + u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + 1) \leq j' < (\delta'''_0 + ((\delta''_0 + 1)/2))$; }\\ \\
u_{0, j'} &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$j' = (\delta'''_0 + (\delta''_0 + 1)/2)$; }\\ \\
\frac{1}{\sqrt {-2}}\left(u_{0, j'} - u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + (\delta''_0 + 1)/2) < j' \leq (\delta'''_0 + \delta''_0)$; }
\end{cases}
\]
where the entry in the filled Young diagram ${\mathcal Y}_1$ in the box at row $r$ and column $s$ is $j$ and the entry in the filled Young diagram  ${\mathcal Y}_2$ in the box at row $r$ and column $s$ is $j'$.

Finally $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is the direct sum of the linear transformations $T_{{\mathbf c}, i}: V_i({\mathbf c}) \rightarrow V_i$ and $T_{{\mathbf c}, -i}: V_{-i}({\mathbf c}) \rightarrow V_{-i}$ for all $i \in {\mathcal I}$, $i > 0$ and of the linear transformation $T_{{\mathbf c}, 0}: V_0({\mathbf c}) \rightarrow V_0$.   Note that  the dimension vector  $\delta({\mathbf c}) $ of ${\mathbf c}$ is  $\delta({\mathbf c}) = (\delta_i)_{i \in {\mathcal I}}$, where $\delta_i = \dim(V_i)$ for all $i \in {\mathcal I}$.


%lemma 4.11
\begin{lemma}\label{L:TcIsomorphismIodd}
With the above definition, we have that $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is an ${\mathcal I}$-graded isomorphism such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$.
\end{lemma}
%proof
\begin{proof}
This proof is similar to the one in lemma~\ref{L:TcIsomorphism}. There are just  more cases to consider. To be complete , we have included the proof.

From our construction, it is clear that $T_{\mathbf c}$ is an ${\mathcal I}$-graded isomorphism.
To check that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$, it is enough to check it on the basis ${\mathcal B}_{\mathbf c}$. We want to consider $\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{i'}^{s'}(b'))\rangle$ where $i, i' \in {\mathcal I}$, $i \in Supp(b)$, $1 \leq s \leq c(b)$, $i' \in Supp(b')$ and $1 \leq s' \leq c(b')$. Because $T_{\mathbf c}$ is ${\mathcal I}$-graded, our hypothesis in~\ref{S:SetUpOdd} on the basis ${\mathcal B}$ of $V$ and our construction in~\ref{N:CCorrespondanceOdd}, we get if $i + i' \ne 0$, that 
\[
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{i'}^{s'}(b'))\rangle = 0 = \langle v_i^s(b), v_{i'}^{s'}(b')\rangle_{\mathbf c}.
\]

Now let $i' = -i$ and  assume first that $i > 0$.  Consider the same total orders as above on the sets $\{b \in {\mathbf B} \mid i \in Supp(b)\}$  and $\{b' \in {\mathbf B} \mid -i = \sigma(i) \in Supp(b)\}$. Proceeding as above with the Young diagram, assume that   $b = b_r$ in the total order $b_1 > b_2 > \dots > b_n$ on the set $\{b \in {\mathbf B} \mid i \in Supp(b)\}$ and   $b' = b'_{r'}$ in the total order $b'_1 > b'_2 > \dots > b'_n$ on the set $\{b' \in {\mathbf B} \mid -i = \sigma(b) \in Supp(b')\}$, the entry in the box at row $r$ and column $s$ is $j$ and the entry in the box at row $r'$ and column $s'$ is $j'$, then 
\[
\begin{aligned}
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle &= \langle T_{\mathbf c}(v_i^s(b_r)), T_{\mathbf c}(v_{-i}^{s'}(b'_{r'}))\rangle = \langle u_{i, j}, u_{-i, j'}\rangle\\ &= \begin{cases} 1, &\text{if $j = j'$;} \\ 0, &\text{otherwise;}\end{cases} = \begin{cases} 1, &\text{if $r= r'$ and $s = s'$;} \\ 0, &\text{otherwise.}\end{cases} 
\end{aligned}
\]
If we now consider the bilinear form on $V({\mathbf c})$, we have
\[
\begin{aligned}
\langle v_i^s(b), v_{-i}^{s'}(b')\rangle_{\mathbf c} &= \langle v_i^s(b_r), v_{-i}^{s'}(b'_{r'})\rangle_{\mathbf c} = \langle v_i^s(b_r), v_{-i}^{s'}(\tau(b_{r'}))\rangle_{\mathbf c}\\ &= \begin{cases} 1, &\text{if $r= r'$ and $s = s'$;} \\ 0, &\text{otherwise.}\end{cases} 
\end{aligned}
\]
So if $i > 0$, then $\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle = \langle v_i^s(b), v_{-i}^{s'}(b')\rangle_{\mathbf c}$.

If $i \in {\mathcal I}$, $i < 0$, then 
\[
\begin{aligned}
\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{-i}^{s'}(b'))\rangle &= \epsilon \langle T_{\mathbf c}(v_{-i}^{s'}(b')), T_{\mathbf c}(v_{i}^{s}(b))\rangle\\ &=  \epsilon  \langle v_{-i}^{s'}(b'), v_{i}^{s}(b)\rangle_{\mathbf c} =  \langle v_{-i}^{s}(b), v_{i}^{s'}(b')\rangle_{\mathbf c}.
\end{aligned}
\]

Assume now that $i = 0$ and we are in the symplectic case.  Consider the same total order as above on the set 
\[
\{{\mathcal O} \in {\mathbf B}/\tau \mid {\mathcal O} \text{ has overlapping ${\mathcal I}$-box supports}\}. 
\]
Proceeding as above with the Young diagram, assume that $0 \in Supp(b) \cap Supp(b')$, $b \in {\mathcal O}_r$, $b' \in {\mathcal O}_{r'}$, the entry in the box at row $r$ and column $s$ is $j$ and the entry in the box at row $r'$ and column $s'$ is $j'$. From our definition, we have that
\[
T_{\mathbf c}(v_0^s(b)) = \begin{cases} u_{0, j}, &\text{if $b$ is above the principal diagonal;}\\ u_{0, -j}, &\text{if $b$ is below the principal diagonal;}\\ u_{0, \epsilon^{k_1} j}, &\text{if $b$ is on the principal diagonal and $b = b(i_1, j_1, k_1)$;} \end{cases} 
\]
and 
\[
T_{\mathbf c}(v_0^{s'}(b')) = \begin{cases} u_{0, j'}, &\text{if $b'$ is above the principal diagonal;}\\ u_{0, -j'}, &\text{if $b'$ is below the principal diagonal;}\\ u_{0, \epsilon^{k'_1} j'}, &\text{if $b'$ is on the principal diagonal and $b' = b(i'_1, j'_1, k'_1)$.} \end{cases} 
\]

If $s' \ne s$, then $\langle T_{\mathbf c}(v_0^s(b)), T_{\mathbf c}(v_0^{s'}(b'))\rangle = 0$, because  $j \ne \pm j'$ from our construction above. 

If $s' = s$ and $b' \not \in {\mathcal O}_r$, then  $\langle T_{\mathbf c}(v_0^s(b)), T_{\mathbf c}(v_0^{s}(b'))\rangle = 0$,  because  $r' \ne r$ and again $j \ne \pm j'$. 

If $s' = s$ and $b' \in {\mathcal O}_r$, then either $b' = b$ or $b' = \tau(b)$. Recall that in the symplectic case, we never have $\tau(b) = b$, in other words the orbit ${\mathcal O}_r = \{b, \tau(b)\}$ has cardinality 2.  Now in the first case:  $b' = b$, we get that 
$\langle T_{\mathbf c}(v_0^s(b)), T_{\mathbf c}(v_0^{s}(b))\rangle = 0$ because $\langle\  , \  \rangle$ is a symplectic bilinear form.
In the second case, $b' = \tau(b)$, we get that  $\langle T_{\mathbf c}(v_0^s(b)), T_{\mathbf c}(v_0^{s}(\tau(b)))\rangle$ is equal to
\[
\begin{cases} \langle u_{0, j}, u_{0, -j}\rangle = 1&\text{if $b$ is above the principal diagonal;}\\  \langle u_{0, -j}, u_{0, j}\rangle = \epsilon &\text{if $b$ is below the principal diagonal;}\\  \langle u_{0, \epsilon^{k_1} j}, u_{0, \epsilon^{(1 - k_1)}j}\rangle = \epsilon^{k_1}, &\text{if $b = b(i_1, j_1, k_1)$ is on the principal diagonal.}
\end{cases}
\]
In this last case when the ${\mathcal I}$-box $b$ is on the principal diagonal, there are two situations: either $b = b(i_1, j_1, 0)$ or $b = b(i_1, j_1, 1)$. We have respectively $\tau(b) = b(i_1, j_1, 1)$ and $\tau(b) = b(i_1, j_1, 0)$. So we get 
\[
\begin{cases} \langle u_{0, j}, u_{0, -j}\rangle = 1,  &\text{if $b = b(i_1, j_1, 0)$ is on the principal diagonal.}\\  \langle u_{0, -j}, u_{0, j}\rangle = \epsilon,  &\text{if $b = b(i_1, j_1, 1)$ is on the principal diagonal.}
\end{cases}
\]

Note that we have 
\[
\langle v_0^s(b), v_{0}^{s'}(b')\rangle_{\mathbf c} 
= \begin{cases} 1, &\text{if $s' = s$,  $b' = \tau(b)$ and $b$ is above the principal diagonal;}\\ 
\epsilon, &\text{if $s' = s$,  $b' = \tau(b)$ and $b$ is below the principal diagonal;}\\ 
\epsilon^{k_1}, &\text{if $s' = s$,  $b' = \tau(b)$ and $b = b(i_1, j_1, k_1)$ is on the}\\ &\text{principal diagonal; }\\ 
0, &\text{otherwise.}
\end{cases}
\]

So we have $\langle T_{\mathbf c}(v_i^s(b)), T_{\mathbf c}(v_{i'}^{s'}(b'))\rangle = \langle v_i^s(b), v_{i'}^{s'}(b')\rangle_{\mathbf c}$ in the symplectic case,   where $i, i' \in {\mathcal I}$, $i \in Supp(b)$, $1 \leq s \leq c(b)$, $i' \in Supp(b')$ and $1 \leq s' \leq c(b')$. 

Assume now that $i = 0$ and we are in the orthogonal case. Consider the same total order: $b_1 > b_2 > \dots > b_n$ on the set $\{b \in {\mathbf B}^+ \mid 0 \in Supp(b)\}$ as above, the corresponding total order: $b'_1 > b'_2 > \dots > b'_n$ on the set $\{b' \in {\mathbf B}^- \mid 0 \in Supp(b')\}$ where $b'_r = \tau(b_r)$ for $1 \leq r \leq n$ as above and the same total order: $b''_1 > b''_2 > \dots > b''_{n'}$ on the set $\{b'' \in {\mathbf B} \mid 0 \in Supp(b''), \tau(b'') = b''\}$ as above.  By our definition, we have 
\[
\begin{cases}
T_{{\mathbf c}, 0}(v_0^s(b)) = u_{0, j}, &\text{if $b \in {\mathbf B}^+$ and $b = b_r$;}\\ \\
T_{{\mathbf c}, 0}(v_0^s(b')) = u_{0, (\delta_0 + 1 -  j)}, &\text{if $b \in {\mathbf B}^-$ and $b' = b'_r = \tau(b_r)$;}
\end{cases}
\]
where $j$ is the entry in the Young diagram ${\mathcal Y}_1$ in the box at row $r$ and column $s$.  In this case, we have that $1 \leq j \leq \delta'''_0$ and $(\delta''_0 + \delta'''_0 + 1) \leq (\delta_0 + 1 - j) \leq \delta_0$.

We also have that 
\[
T_{{\mathbf c}, 0}(v_0^s(b)) = \begin{cases} 
\frac{1}{\sqrt 2}\left(u_{0, j'} + u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + 1) \leq j' \leq (\delta'''_0 + (\delta''_0 /2))$; }\\ \\
\frac{1}{\sqrt {-2}}\left(u_{0, j'} - u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + (\delta''_0/2) + 1) \leq j' \leq (\delta'''_0 + \delta''_0)$; }
\end{cases}
\]
when $\delta_0$ is even and 
\[
T_{{\mathbf c}, 0}(v_0^s(b)) = \begin{cases} 
\frac{1}{\sqrt 2}\left(u_{0, j'} + u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + 1) \leq j' < (\delta'''_0 + ((\delta''_0 + 1)/2))$; }\\ \\
u_{0, j'} &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$j' = (\delta'''_0 + (\delta''_0 + 1)/2)$; }\\ \\
\frac{1}{\sqrt {-2}}\left(u_{0, j'} - u_{0, (\delta_0 + 1 - j')}\right), &\text{if $b \in {\mathbf B}$, $\tau(b) = b$, $b = b''_r$ and }\\ &\text{$(\delta'''_0 + (\delta''_0 + 1)/2) < j' \leq (\delta'''_0 + \delta''_0)$; }
\end{cases}
\]
when $\delta_0$ is odd, where  the entry in the filled Young diagram  ${\mathcal Y}_2$ in the box at row $r$ and column $s$ is $j'$.
In this case we have that $(\delta'''_0 + 1) \leq j' \leq (\delta'''_0 + \delta''_0)$ and  $(\delta'''_0 + 1) \leq (\delta_0 + 1 - j') \leq (\delta'''_0 + \delta''_0)$.  Because of the above inequalities for $j$ and $j'$ and our hypothesis in  \ref{S:SetUpOdd}, we have for $b, {\overline b} \in {\mathbf B}$, $0 \in Supp(b) \cap Supp({\overline b})$, $1 \leq s \leq c(b)$ and $1 \leq {\overline s} \leq c({\overline b})$ that 
$\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle \ne 0$ only in the following cases:
\begin{itemize}
\item $b \in {\mathbf B}^+$, ${\overline b} \in {\mathbf B}^-$;
\item $b \in {\mathbf B}^-$, ${\overline b} \in {\mathbf B}^+$;
\item $b, {\overline b} \in {\mathbf B}$, $\tau(b) = b$, $\tau({\overline b}) = ({\overline b})$;   
\end{itemize}
and similarly we have that
$\langle v_0^s(b), v_0^{\overline s}({\overline b})\rangle_{\mathbf c} \ne 0$ only in the same cases as above:
\begin{itemize}
\item $b \in {\mathbf B}^+$, ${\overline b} \in {\mathbf B}^-$;
\item $b \in {\mathbf B}^-$, ${\overline b} \in {\mathbf B}^+$;
\item $b, {\overline b} \in {\mathbf B}$, $\tau(b) = b$, $\tau({\overline b}) = ({\overline b})$.   
\end{itemize}
We will now consider each of these cases. 


If $b \in {\mathbf B}^+$, $0 \in Supp(b)$, $b = b_r$, $1 \leq s \leq c(b_r)$, ${\overline b} \in {\mathbf B}^-$, $0 \in Supp({\overline b})$, ${\overline b} = b'_{\overline r}  = \tau(b_{\overline r})$, $1 \leq {\overline s} \leq c({\overline b})$ and $j$ (respectively ${\overline j}$) is the entry in the Young diagram ${\mathcal Y}_1$ in the box at row $r$ (respectively ${\overline r}$)  and column $s$ (respectively ${\overline s}$), then
\[
\begin{aligned}
\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle &= \langle u_{0, j}, u_{0, (\delta_0 + 1 - {\overline j})}\rangle = \begin{cases} 1, &\text{if $j = {\overline j}$;}\\ 0, &\text{otherwise} \end{cases}\\ &= \begin{cases} 1, &\text{if $r = {\overline r}$ and $s = {\overline s}$;}\\ 0, &\text{otherwise} \end{cases}
\end{aligned}
\] 
but we also have
\[
\langle v_0^s(b_r), v_0^{\overline s}(b'_{\overline r})\rangle_{\mathbf c} = \langle v_0^s(b_r), v_0^{\overline s}(\tau(b_{\overline r}))\rangle_{\mathbf c} = \begin{cases} 1, &\text{if $r = {\overline r}$ and $s = {\overline s}$;}\\ 0, &\text{otherwise} \end{cases}
\]
and consequently 
\[
\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle = \langle v_0^s(b), v_0^{\overline s}({\overline b})\rangle_{\mathbf c}. 
\] 


If $b \in {\mathbf B}^-$, $0 \in Supp(b)$, $b = b'_r = \tau(b_r)$, $1 \leq s \leq c(b'_r)$, ${\overline b} \in {\mathbf B}^+$, $0 \in Supp({\overline b})$, ${\overline b} = b_{\overline r}$, $1 \leq {\overline s} \leq c({\overline b})$ , then we just use  the previous case, as well as the symmetry of the bilinear forms $\langle\ , \ \rangle$ and $\langle\ , \ \rangle_{\mathbf c}$  to get that 
\[
\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle = \langle v_0^s(b), v_0^{\overline s}({\overline b})\rangle_{\mathbf c}.
\] 

We have now to consider the last case where $b, {\overline b} \in {\mathbf B}$, $0 \in Supp(b) \cap Supp({\overline b})$, $\tau(b) = b$ and $\tau({\overline b}) = {\overline b}$.  First note that if $\delta_0$ is even, $(\delta'''_0 + 1) \leq j'_1, j'_2 \leq (\delta'''_0 + (\delta''_0/2))$ and $(\delta'''_0 + (\delta''_0/2) + 1) \leq j''_1, j''_2 \leq (\delta'''_0 + \delta''_0)$,we get easily that
\[
\left\langle\frac{1}{\sqrt 2}\left(u_{0, j'_1} + u_{0, (\delta_0 + 1 - j'_1)}\right), \frac{1}{\sqrt 2}\left(u_{0, j'_2} + u_{0, (\delta_0 + 1 - j'_2)}\right) \right\rangle = \begin{cases} 1, &\text{if $j'_1 = j'_2$;} \\ 0, &\text{ otherwise;}\end{cases}
\]

\[
\left\langle\frac{1}{\sqrt 2}\left(u_{0, j'_1} + u_{0, (\delta_0 + 1 - j'_1)}\right), \frac{1}{\sqrt {-2}}\left(u_{0, j''_1} - u_{0, (\delta_0 + 1 - j''_1)}\right) \right\rangle = 0 
\]
 for all $j'_1$ and $j''_1$ as above;
\[
\left\langle\frac{1}{\sqrt {-2}}\left(u_{0, j''_1} - u_{0, (\delta_0 + 1 - j''_1)}\right), \frac{1}{\sqrt {-2}}\left(u_{0, j''_2} - u_{0, (\delta_0 + 1 - j''_2)}\right) \right\rangle =  \begin{cases} 1, &\text{if $j''_1 = j''_2$;} \\ 0, &\text{ otherwise;}\end{cases}
\]
while if $\delta_0$ is odd, $(\delta'''_0 + 1) \leq j'_1, j'_2 < (\delta'''_0 + (\delta''_0 + 1)/2)$,  $(\delta'''_0 + (\delta''_0 + 1)/2)) < j''_1, j''_2 \leq (\delta'''_0 + \delta''_0)$ and $j''' = (\delta'''_0 + (\delta''_0 + 1)/2)$, we also get easily that
\[
\left\langle\frac{1}{\sqrt 2}\left(u_{0, j'_1} + u_{0, (\delta_0 + 1 - j'_1)}\right), \frac{1}{\sqrt 2}\left(u_{0, j'_2} + u_{0, (\delta_0 + 1 - j'_2)}\right) \right\rangle = \begin{cases} 1, &\text{if $j'_1 = j'_2$;} \\ 0, &\text{ otherwise;}\end{cases}
\]

\[
\left\langle\frac{1}{\sqrt 2}\left(u_{0, j'_1} + u_{0, (\delta_0 + 1 - j'_1)}\right), \frac{1}{\sqrt {-2}}\left(u_{0, j''_1} - u_{0, (\delta_0 + 1 - j''_1)}\right) \right\rangle = 0 
\]
 for all $j'_1$ and $j''_1$ as above;
\[
\left\langle\frac{1}{\sqrt {-2}}\left(u_{0, j''_1} - u_{0, (\delta_0 + 1 - j''_1)}\right), \frac{1}{\sqrt {-2}}\left(u_{0, j''_2} - u_{0, (\delta_0 + 1 - j''_2)}\right) \right\rangle =  \begin{cases} 1, &\text{if $j''_1 = j''_2$;} \\ 0, &\text{ otherwise;}\end{cases}
\]
\[
\left\langle\frac{1}{\sqrt 2}\left(u_{0, j'_1} + u_{0, (\delta_0 + 1 - j'_1)}\right), u_{0, j'''} \right\rangle = \left\langle\frac{1}{\sqrt {-2}}\left(u_{0, j''_1} - u_{0, (\delta_0 + 1 - j''_1)}\right), u_{0, j'''} \right\rangle = 0 
\]
and $\langle u_{0, j'''}, u_{0, j'''} \rangle = 1$.

Consider now $b, {\overline b} \in {\mathbf B}$, $0 \in Supp(b) \cap Supp({\overline b})$, $\tau(b) = b$, $\tau({\overline b}) = {\overline b}$, $b = b''_r$, ${\overline b} = b''_{\overline r}$ and let $j$ (respectively ${\overline j}$) be the entry in the Young diagram ${\mathcal Y}_2$ in the box at row $r$ (respectively  ${\overline r}$) and column $s$ (respectively ${\overline s}$). In this case, $(\delta'''_0 + 1) \leq j, {\overline j} \leq (\delta'''_0 + \delta''_0)$. By our above computations, we get that 
\[
\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle  = \begin{cases} 1, &\text{if $j = {\overline j}$;}\\ 0, &\text{otherwise} \end{cases} = \begin{cases} 1, &\text{if $r = {\overline r}$ and $s = {\overline s}$;}\\ 0, &\text{otherwise} \end{cases}
\] 
but we also have
\[
\langle v_0^s(b), v_0^{\overline s}(\overline b)\rangle_{\mathbf c} = \langle v_0^s(b''_r), v_0^{\overline s}(b''_{\overline r})\rangle_{\mathbf c} = \begin{cases} 1, &\text{if $r = {\overline r}$ and $s = {\overline s}$;}\\ 0, &\text{otherwise} \end{cases}
\]
and consequently 
\[
\langle T_{{\mathbf c}, 0}(v_0^s(b)), T_{{\mathbf c}, 0}(v_0^{\overline s}({\overline b}))\rangle = \langle v_0^s(b), v_0^{\overline s}({\overline b})\rangle_{\mathbf c}. 
\] 

Thus we have proved that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$.

\end{proof}

%% proposition 4.12
\begin{proposition} \label{Prop_Indexation_Orbits_Odd}
Let $\delta = (\delta_i)_{i \in {\mathcal I}}$ be as in \ref{S:SetUpOdd}  and ${\mathfrak g}_2/G^{\iota}$ denotes the set of  $G^{\iota}$-orbits  in ${\mathfrak g}_2$. Then the map 
\[
\Upsilon:{\mathfrak g}_2/G^{\iota} \rightarrow  {\mathfrak C}_{\delta} \quad \text{ defined by } \quad G^{\iota} \cdot X \mapsto {\mathbf c}_X,
\]
is a well-defined bijection.
\end{proposition}
%proof
\begin{proof}
By our last observation in \ref{SS:coefficientOrbitOdd}, if $G^{\iota} \cdot X = G^{\iota} \cdot X'$, then  the corresponding $\epsilon$-representations for $X$ and $X'$ are isomorphic, we get  that ${\mathbf c}_X = {\mathbf c}_{X'}$ and the  function $\Upsilon$ is well-defined. 

To show that $\Upsilon$ is an injective function,  assume that ${\mathbf c}_X = {\mathbf c}_{X'}$, then this means that, by the Krull-Remak-Schmidt theorem, the  $\epsilon$-representations for $X$ and $X'$ are isomorphic. So $X$ and $X'$ are in the same $G^{\iota}$-orbit and $G^{\iota} \cdot X = G^{\iota} \cdot X'$.

To prove that $\Upsilon$ is surjective, we need to show that there is an element $X \in {\mathfrak g}_2$ such that ${\mathbf c}_X = {\mathbf c} \in {\mathfrak C}_{\delta}$.  Consider $X = T_{\mathbf c} E_{\mathbf c} T_{\mathbf c}^{-1}:V \rightarrow V$, where $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is the ${\mathcal I}$-graded isomorphism defined in \ref{SS:IsomorphismV(c)andVOddCase}.  Because $E_{\mathbf c} \in {\mathfrak g}_2(V({\mathbf c}))$ and lemma~\ref{L:TcIsomorphismIodd}, $X \in {\mathfrak g}_2$. From our construction of $E_{\mathbf c}: V({\mathbf c}) \rightarrow V({\mathbf c})$, it is isomorphic as ${\mathcal I}$-graded and $\epsilon$-representation  to the direct sum of ${\mathbf c}({\mathcal O})$ copies of the linear transformation $E_{\mathcal O}:V({\mathcal O}) \rightarrow V({\mathcal O})$. By carrying this direct sum using $T_{\mathbf c}$ to $V$, we do get that ${\mathbf c}_X = {\mathbf c}$ and the proof is complete. 

\end{proof}

%notation 4.13
\begin{notation}
Let $\delta = (\delta_i)_{i \in {\mathcal I}}$ be such that $\delta_i = \dim(V_i)$ for all $i \in {\mathcal I}$. If ${\mathbf c} \in {\mathfrak C}_{\delta}$, we will denote by ${\mathcal O}_{\mathbf c}$: the unique $G^{\iota}$-orbit in ${\mathfrak g}_2$ such that $\Upsilon({\mathcal O}_{\mathbf c}) = {\mathbf c}$.
\end{notation}

%remark 4.14
\begin{remark}\label{R:IsomoVVcSymplecticOdd}
Using the isomorphism $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$, we can transfer results about the orbit ${\mathcal O}_{\mathbf c}$ in the Lie algebra ${\mathfrak g}$ to the orbit of $E_{\mathbf c}$ in the Lie algebra 
${\mathfrak g}(V({\mathbf c}))$.
\end{remark}

% 4.15
\subsection{}\label{SS:ObservationDimensionOrthogonal}
To compute the dimension of the orbit ${\mathcal O}_{\mathbf c}$  corresponding to ${\mathbf c} \in {\mathfrak C}_{\delta}$, we will proceed as in the previous section by considering a parabolic subalgebra ${\mathfrak p}_X$ associated by Lusztig to an element $X \in {\mathcal O}_{\mathbf c} \subseteq {\mathfrak g}_2$ and then using the formula
\[
\dim({\mathcal O}_{\mathbf c}) = \dim({\mathfrak g}_0) - \dim({\mathfrak p}_0) + \dim({\mathfrak p}_2),
\]
where ${\mathfrak p}$ is the parabolic subalgebra ${\mathfrak p}_X$.

We now want to use this formula to compute the dimension $\dim({\mathcal O}_{\mathbf c})$ of the orbit ${\mathcal O}_{\mathbf c}$ in term of the coefficient function ${\mathbf c}$. This is done in the next proposition.

Note that we have to be careful in the orthogonal case, because the above formula for the dimension $\dim({\mathcal O}_{\mathbf c})$ of the orbit ${\mathcal O}_{\mathbf c}$ proved using 5.4 (a) and 5.9 of \cite{L1995} is under the hypothesis that the group $G$ is connected. In the orthogonal case, $G$ is the orthogonal group $O(V)$ and $G^{\iota}$ is not connected as we saw in lemma~\ref{G2AsRepresOdd} (a). From our definition of $\iota$, it is easy to see that the connected component of the identity $(G^{\iota})^0$ of $G^{\iota}$ is equal to $(G^0)^{\iota}$: the centralizer of $\iota$ in the connected component $G^0$ of $G$. Here $G^0$ is the special orthogonal group and is connected. Because of this observation, we can also used the above formula for the dimension of the orbit ${\mathcal O}_{\mathbf c}$.

%proposition 4.16
\begin{proposition}\label{DimensionFormulaSymplecticOdd}
Let ${\mathbf c}  \in  {\mathfrak C}_{\delta}$  and consider the symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$ corresponding to ${\mathbf c}$.  Then the dimension $\dim({\mathcal O}_{\mathbf c})$ of the orbit ${\mathcal O}_{\mathbf c}$ is equal to 
\[
\left[
\begin{aligned}
&\frac{\delta_0(\delta_0 - \epsilon)}{2} + \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 <  i\end{subarray}} \delta_i^2 + \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 \leq i < (2m - 2)\\ (b, b') \in {\mathbf B} \times {\mathbf  B}\\ i \in Supp(b)\\ (i + 2) \in Supp(b')\\ \lambda(b) \geq \lambda(b') \end{subarray}} c(b) c(b')   - \sum_{\begin{subarray}{c}i \in {\mathcal I}\\ i > 0\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b) \cap Supp(b')\\ \lambda(b) \geq \lambda(b')\end{subarray}} c(b) c(b') \\ \\ & - \frac {1}{2} \sum_{\begin{subarray}{c} (b, b') \in {\mathbf B} \times {\mathbf B}\\ 0 \in Supp(b) \cap Supp(b') \\ b \ne \tau(b')\\ \lambda(b)\geq \lambda(b') \end{subarray}} c(b) c(b')  - \frac{1}{2}
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b)\\\lambda(b)\geq \lambda(\tau(b)) \end{subarray}} c(b) (c(b) - \epsilon)
\end{aligned}
\right]
\]
\end{proposition}
%proof
\begin{proof}
Taking into account our observation in \ref{SS:ObservationDimensionOrthogonal} in the orthogonal case and our remark~\ref{R:IsomoVVcSymplecticOdd},  we will assume that $V = V({\mathbf c})$ and ${\mathfrak g}$ will be ${\mathfrak g}(V({\mathbf c}))$.  We have that $\dim(V_i) = \delta_i$ for all $i \in {\mathcal I}$ from the fact that $\delta({\mathbf c}) = \delta$.
We have constructed in~\ref{N:CCorrespondanceOdd}  a Jacobson-Morozov triple  $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ with $E_{\mathbf c} \in {\mathcal O}_{\mathbf c}$; in other words we have 
\[
[H_{\mathbf c}, E_{\mathbf c}] = 2 E_{\mathbf c}, \qquad [H_{\mathbf c}, F_{\mathbf c}] = -2 F_{\mathbf c}, \qquad [E_{\mathbf c}, F_{\mathbf c}] = H_{\mathbf c},
\]
where $E_{\mathbf c} \in {\mathfrak g}_2$, $H_{\mathbf c} \in {\mathfrak g}_0$ and $F_{\mathbf c} \in {\mathfrak g}_{-2}$  and such that $E_{\mathbf c} \in {\mathcal O}_{\mathbf c}$.   Thus we have a Lie algebra homomorphism $\phi: {\mathfrak sl}_2({\mathbf k}) \rightarrow {\mathfrak g}$ such that 
\[
\phi\begin{pmatrix}0 & 1\\ 0 & 0\end{pmatrix} = E_{\mathbf c}, \qquad \phi\begin{pmatrix}1 & \phantom{-}0\\ 0 & -1\end{pmatrix} = H_{\mathbf c}, \qquad \phi\begin{pmatrix}0 & 0\\ 1 & 0\end{pmatrix} = F_{\mathbf c}. 
\]
As in definition~\ref{D:LieHomo}, let $\widetilde{\phi}: SL_2({\mathbf k}) \rightarrow G$ be the homomorphism of algebraic groups whose differential is $\phi$ and by $\iota':{\mathbf k}^{\times} \rightarrow G$: the homomorphism defined by 
\[
\iota'(t) = \widetilde{\phi}\begin{pmatrix}t & 0\phantom{-} \\ 0 & t^{-1}\end{pmatrix} \qquad  \text{ for all $t \in {\mathbf k}^{\times}$.}
\]
We have the grading for the Lie algebra ${\mathfrak g} = \oplus_r  ({ }_r {\mathfrak g})$ where 
\[
({ }_r {\mathfrak g}) = \{ X \in {\mathfrak g} \mid Ad(\iota'(t))(X) = t^r X \quad \text{ for all $t \in {\mathbf k}^{\times}$}\}
\]
By taking the derivative, we get that 
\[
({ }_r {\mathfrak g}) = \{ X \in {\mathfrak g} \mid ad(H_{\mathbf c})(X) =r X \}.
\]

By lemma~\ref{G2AsRepresOdd} (c), we have that 
\[
\dim({\mathfrak g}_0) = \frac{\delta_0(\delta_0 - \epsilon)}{2} + \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ i > 0\end{subarray}} \delta_i^2.
\]

Let ${\mathfrak p}$ be the parabolic subalgebra associated to the nilpotent element $E_{\mathbf c}$. From the definition of ${\mathfrak p}$, we get that ${\mathfrak p}_0$ and  ${\mathfrak p}_2$ are such that
\[
{\mathfrak p}_0 = \bigoplus_{r \geq 0}  ({ }_r{\mathfrak g}_0) \qquad \text{ and } \qquad {\mathfrak p}_2 = \bigoplus_{r \geq 2}  ({ }_r{\mathfrak g}_2) 
\]
By our description of ${\mathfrak g}_0$ and ${\mathfrak g}_2$ in lemma~\ref{G2AsRepresOdd}, we get that ${\mathfrak p}_0 =  {\mathfrak p}'_0 \oplus {\mathfrak p}''_0$, where 
\[
 {\mathfrak p}'_0 = \bigoplus_{r \geq 0} \bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 < i  \end{subarray}} \{(Z_i : V_i \rightarrow V_i) \in Hom(V_i, V_i) \mid ad(H_{\mathbf c}\vert_{V_i}) Z_i = r Z_i \},
\]
\[
{\mathfrak p}''_0 = \bigoplus_{r \geq 0}\left\{ Z_0: V_0 \rightarrow V_0 \in Hom(V_0, V_0)  \left\vert\  \begin{aligned} &ad(H_{\mathbf c}\vert_{V_0}) Z_0 = r Z_0 \text{ and }\\ &\langle Z_0(v), v'\rangle_{\mathbf c} + \langle v, Z_0(v')\rangle_{\mathbf c}  = 0\\ &\text{ for all $v, v' \in V_0$.} \end{aligned} \right.\right\}, 
\]
and 
\[
{\mathfrak p}_2 = 
\bigoplus_{r \geq 2} \bigoplus_{\begin{subarray}{c} i \in {\mathcal I}\\ 0 \leq i < (2m - 2)\end{subarray}} \{(X_i : V_i \rightarrow V_{i + 2}) \in Hom(V_i, V_{i + 2}) \mid ad(H_{\mathbf c}\vert_{V_i}) X_i = r X_i  \}.
\]


We can give  bases for the spaces $Hom(V_i, V_i)$ and $Hom(V_i, V_{i + 2})$ that are eigenvectors for $ad(H_{\mathbf c}\vert_{V_i})$.  From our construction of the triple $\{E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c}\}$, we have for each $i \in {\mathcal I}$ a basis  
\[
{\mathcal B}_i = \{v_i^j(b)\in V_i  \mid b \in {\mathbf B}, i \in Supp(b), 1 \leq j \leq c(b)\}
\]
of $V_i$. 

Let now $i \in {\mathcal I}$ and $0 \leq i  < (2m - 2)$.  For each $b, b' \in {\mathbf B}$ with $i \in Supp(b)$, $(i + 2) \in Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, let $X_{(b, j)}^{(b', j')} \in Hom(V_i, V_{i + 2})$ be defined on the basis ${\mathcal B}_i $ by 
\[
X_{(b, j)}^{(b', j')}(v_i^{j''}(b'')) = \begin{cases} v_{i + 2}^{j'}(b'), &\text{if $b'' = b$ and $j'' = j$;}\\ 0, &\text{otherwise.}\end{cases}
\]
Clearly these linear transformations $X_{(b, j)}^{(b', j')}$ with  $b,  b' \in {\mathbf B}$,  $i \in Supp(b)$,  $(i + 2) \in Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ form a basis of $Hom(V_i, V_{i + 2})$. 

We have that  $H_{\mathbf c}(v_i^j(b)) = h_i(b) v_i^j(b)$ for all $b \in {\mathbf B}$, $i \in Supp(b)$ and $1 \leq j \leq c(b)$ and  $X_{(b, j)}^{(b', j')}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_i})$ with
\[
ad(H_{\mathbf c}\vert_{V_i}) (X_{(b, j)}^{(b', j')}) = (h_{(i + 2)}(b') - h_i(b)) X_{(b, j)}^{(b', j')}
\]
by computing both sides  on the basis vector $v_i^{j''}(b'')$. Consequently  we get that 
\[
\dim({\mathfrak p}_2) = 
\sum_{\begin{subarray}{c}i \in {\mathcal I}\\0 \leq i < (2m - 2)\\ (b, b') \in {\mathbf B} \times {\mathbf B}\\ i \in Supp(b)\\ (i + 2) \in  Supp(b')\\ \lambda(b) \geq \lambda(b')\end{subarray}} c(b) c(b')
\]
because $(h_{i + 2}(b') - h_i(b)) \geq 2$ is equivalent to $\lambda(b) \geq \lambda(b')$ as we saw in the proof of proposition~\ref{DimensionFormulaEven}

We can now consider the vector space ${\mathfrak p}'_0$. Let $i > 0$. For each $b, b' \in {\mathbf B}$ with $i \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, let $Z_{(b, j)}^{(b', j')} \in Hom(V_i, V_i)$ be defined on the basis ${\mathcal B}_i $ by 
\[
Z_{(b, j)}^{(b', j')}(v_i^{j''}(b'')) = \begin{cases} v_i^{j'}(b'), &\text{if $b'' = b$ and $j'' = j$;}\\ 0, &\text{otherwise.}\end{cases}
\]
These linear transformations $Z_{(b, j)}^{(b', j')}$ with  $b, b' \in {\mathbf B}$,  $i \in Supp(b) \cap Supp(b')$, $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ form a basis of $Hom(V_i, V_i)$. Moreover $Z_{(b, j)}^{(b', j')}$ is an eigenvector of $ad(H_{\mathbf c}\vert_{V_i})$ with
\[
ad(H_{\mathbf c}) (Z_{(b, j)}^{(b', j')}) = (h_i(b') - h_i(b)) Z_{(b, j)}^{(b', j')}
\]
by computing both sides  on the basis vector $v_i^{j''}(b'')$. Consequently
\[
\dim({\mathfrak p}'_0) = 
\sum_{\begin{subarray}{c}i \in {\mathcal I}\\ i > 0\\ (b, b') \in {\mathbf B} \times{\mathbf  B}\\ i \in Supp(b) \cap Supp(b')\\ \lambda(b)  \geq  \lambda(b') \end{subarray}} c(b)c(b')
\]
because $(h_i(b') - h_i(b)) \geq 0$ is equivalent to $\lambda(b) \geq \lambda(b')$ as we saw in the proof of proposition~\ref{DimensionFormulaEven}

We must now consider the dimension $\dim({\mathfrak p}''_0)$ and we will  prove that 
\[
\dim({\mathfrak p}''_0) =  \frac {1}{2} \left(\sum_{\begin{subarray}{c} (b, b') \in {\mathbf B} \times {\mathbf B}\\ 0 \in Supp(b) \cap Supp(b') \\ b \ne \tau(b')\\ \lambda(b)\geq \lambda(b') \end{subarray}} c(b) c(b')  +
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b)\\\lambda(b)\geq \lambda(\tau(b)) \end{subarray}} c(b) (c(b) - \epsilon)\right).
\]

Recall that $V_0$ has  a basis ${\mathcal B}_0 = \{v_0^j(b) \mid b \in {\mathbf B}, 0 \in Supp(b), 1 \leq j \leq c(b)\}$ such that 
\[
\langle v_0^s(b), v_{0}^{s'}(b')\rangle 
= \begin{cases} 1, &\text{if $s' = s$,  $b' = \tau(b)$ and $b$ is above the principal diagonal;}\\ 
\epsilon, &\text{if $s' = s$,  $b' = \tau(b)$ and $b$ is below the principal diagonal;}\\ 
\epsilon^{k_1}, &\text{if $s' = s$,  $b' = \tau(b)$ and $b = b(i_1, j_1, k_1)$ is on the}\\ &\text{principal diagonal; }\\ 
0, &\text{otherwise.}
\end{cases}
\]

Let  ${\mathcal E} = \{b \in {\mathbf B} \mid 0 \in Supp(b)\}$ and  $(Z_0:V_0 \rightarrow V_0) \in Hom(V_0, V_0)$ be such that 
\begin{equation}\label{E:LieCondition}
\langle Z_0(v), v' \rangle_{\mathbf c} + \langle v, Z_0(v')\rangle_{\mathbf c} = 0 \quad \text{for all $v, v' \in V_0$.}
\end{equation}

For $v_0^j(b), v_0^{j'}(b') \in {\mathcal B}_0$, then we can write
\[
Z_0(v_0^j(b)) = \sum_{(b'', j'')} \xi_{(b, j)}^{(b'', j'')} v_0^{j''}(\tau(b''))
\]
where the sum runs over all $(b'', j'')$ such that $b'' \in {\mathcal E}$ and $1 \leq j'' \leq c(b'')$ and 
\[
Z_0(v_0^{j'}(b')) = \sum_{(b''', j''')} \xi_{(b', j')}^{(b''', j''')} v_0^{j'''}(\tau(b'''))
\]
where the sum runs over all $(b''', j''')$ such that $b''' \in {\mathcal E}$ and $1 \leq j''' \leq c(b''')$, 

We will first consider the symplectic case. 
The set ${\mathcal E}$ can be partitionned as follows: ${\mathcal E} = {\mathcal E}^+ \coprod {\mathcal E}^-$ where
\[
\begin{aligned}
{\mathcal E}^+ &= \{b \in {\mathcal E} \mid  b(i, j, 0) \text{ where $i, j \in {\mathcal I}$, $i \geq j$ and $i + j \geq 0$} \} \quad \text{ and }\\
{\mathcal E}^- &= \{b \in {\mathcal E} \mid b(i, j, 0) \text{ where $i, j \in {\mathcal I}$, $i \geq j$ and $i + j < 0$} \}\\ &\quad \bigcup \{b \in {\mathcal E} \mid b(i, -i, 1) \text{ where $i \in {\mathcal I}$ and $i \geq 0$} \}.
\end{aligned}
\]

${\mathcal E}^+$ consists of the ${\mathcal I}$-boxes strictly above the principal diagonale and of half of the ${\mathcal I}$-boxes on the principal diagonale, while  ${\mathcal E}^-$ consists of the ${\mathcal I}$-boxes strictly below the principal diagonale and the other half of the ${\mathcal I}$-boxes on the principal diagonale. Note that if $b \in {\mathcal E}^+$, then $\langle v_0^s(b), v_0^s(\tau(b))\rangle_{\mathbf c} = 1$  for any $1 \leq s \leq c(b)$, while if $b \in {\mathcal E}^-$, then $\langle v_0^s(b), v_0^s(\tau(b))\rangle_{\mathbf c} = -1$  for any $1 \leq s \leq c(b)$. 

Setting $v = v_0^j(b)$ and $v' = v_0^{j'}(b')$ in the equation~(\ref{E:LieCondition}) and using the values of  $\langle \   ,  \  \rangle_{\mathbf c}$  in notation~\ref{N:CCorrespondanceOdd}, we get  the equations: 
\begin{equation}\label{CoordinateEquationSymplecticOdd}
\left\{
\begin{aligned}
-\xi_{(b, j)}^{(b', j')} + \xi_{(b', j')}^{(b, j)} &= 0, \quad \text{ if $b, b' \in {\mathcal E}^+$;}\\ \\
 \xi_{(b, j)}^{(b', j')} + \xi_{(b', j')}^{(b, j)} &= 0, \quad \text{ if $b \in {\mathcal E}^+$ and $b' \in {\mathcal E}^-$;}\\ \\
-\xi_{(b, j)}^{(b', j')} - \xi_{(b', j')}^{(b, j)} &= 0, \quad \text{ if $b \in {\mathcal E}^-$ and $b' \in {\mathcal E}^+$;}\\ \\
\xi_{(b, j)}^{(b', j')} - \xi_{(b', j')}^{(b, j)} &= 0, \quad \text{ if $b, b' \in {\mathcal E}^-$;}
\end{aligned}
\right.
\end{equation}
Reciprocally if the above equations are satisfied for all $b, b' \in {\mathcal  E}$,  $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$, then $Z_0$ defined above on the vectors $v_0^j(b)$ will be such that the equation~(\ref{E:LieCondition}) is satisfied.

We will now give a basis of the vector space 
\[
\{(Z_0:V_0 \rightarrow V_0) \in Hom(V_0, V_0) \mid \langle Z_0(v), v' \rangle_{\mathbf c} + \langle v, Z_0(v')\rangle_{\mathbf c} = 0 \text{ for all $v, v' \in V_0$}\}
\]
and each of its element will be an eigenvector of $ad(H_{\mathbf c}\vert_{V_0})$.

Order the basis ${\mathcal B}_0$ such that the first elements are the basis vectors of the form $v_0^j(b)$ with $b \in {\mathcal E}^+$ and $1 \leq j \leq c(b)$ and  the following elements are the basis vectors of the form $v_0^j(\tau(b))$  with $b \in {\mathcal E}^+$ and $1 \leq j \leq c(b)$ and if $b \in {\mathcal E}^+$, then  $v_0^j(b)$ and $v_0^j(\tau(b))$ are respectively in the $m_1^{th}$ and $m_2^{th}$ positions with $(m_2 - m_1) = \delta_0'$. Relative to this ordered basis, the linear transformation $Z_0$ as above has the form
\begin{equation}\label{MatrixZ0Symplect}
\begin{pmatrix}
A_{11} & A_{12}\\ A_{21} & A_{22}
\end{pmatrix} 
\quad \text{with} \quad A_{22} = -A^t_{11}, \quad A_{12} = A^t_{12}, \quad A_{21} = A^t_{21}
\end{equation}

We will define  linear transformations $Z_{(b, j)}^{(b', j')}:V_0 \rightarrow V_0$ when $b, b' \in {\mathcal E}$,  $1 \leq j \leq c(b)$ and $1 \leq j' \leq c(b')$ for three cases:
\begin{enumerate}[\upshape (i)]
%1
\item either $b, b' \in {\mathcal E}^+$ or $b, b' \in {\mathcal E}^-$;

%2
\item $(b, j) \ne (\tau(b'), j')$ and either  $b \in {\mathcal E}^+$, $b' \in {\mathcal E}^-$ or  $b \in {\mathcal E}^-$, $b' \in {\mathcal E}^+$;

%3
\item $(b, j) = (\tau(b'), j')$ and either  $b \in {\mathcal E}^+$, $b' \in {\mathcal E}^-$ or  $b \in {\mathcal E}^-$, $b' \in {\mathcal E}^+$.
\end{enumerate}

%case 1
Case (i): If either $b, b' \in {\mathcal E}^+$ or $b, b' \in {\mathcal E}^-$, we define
\[
Z_{(b, j)}^{(b', j')}(v_0^{j''}(b''))= \begin{cases} {\phantom -}v_0^{j'}(b'), &\text{ if $(b'', j'') = (b, j)$;}\\ -v_0^j(\tau(b)), &\text{ if $(b'', j'') = (\tau(b'), j')$;} \\ {\phantom -} 0, &\text{ otherwise.} \end{cases}
\]

This means
\[
\xi_{(b_1, j_1)}^{(b_2,  j_2)} = \begin{cases} {\phantom -}1, &\text{ if $(b_1, j_1) = ( b, j)$ and $(b_2, j_2) = (\tau(b'), j')$;}\\ -1, &\text{ if $(b_1, j_1) = ( \tau(b'), j')$ and $(b_2, j_2) = (b, j)$;}\\ {\phantom -}0, &\text{otherwise.} \end{cases}
\]

We get easily that  
\[
\langle Z_{(b, j)}^{(b', j')}(v), v' \rangle_{\mathbf c} + \langle v, Z_{(b, j)}^{(b', j')}(v')\rangle_{\mathbf c} = 0 
\]
 for all $v, v' \in V_0$ from the  equations~(\ref{CoordinateEquationSymplecticOdd}).  Note that  the pair $\tau(b'), \tau(b)$ falls also in the  case (i) and it is easy to see that $Z_{(\tau(b'), j')}^{(\tau(b), j)} = - Z_{(b, j)}^{(b', j')}$ by evaluating both sides on the basis vectors $v_0^{j''}(b'')$.

 By looking on the basis vectors $v_0^{j''}(b'')$, we have that 
\[
ad(H_{\mathbf c}\vert_{V_0}) Z_{(b, j)}^{(b', j')} = (h_0(b') - h_0(b)) Z_{(b, j)}^{(b', j')}.
\]
We have used lemma~\ref{L:RelationCoefficientsHandF} (a) in the proof of this formula.

