\[
Z_{(b, j)}^{(b', j')}(v_0^{j''}(b''))= \begin{cases} v_0^{j'}(b'), &\text{ if $(b'', j'') = (b, j)$;} \\  0, &\text{ otherwise.} \end{cases}
\]

