\[
\xi_{(b_1, j_1)}^{(b_2,  j_2)} = \begin{cases} 1, &\text{ if $(b_1, j_1) = ( b, j)$ and $(b_2, j_2) = (\tau(b), j)$;}\\  0, &\text{otherwise.} \end{cases}
