%proposition 4.17
\begin{proposition}\label{P:Height_Jordan_Type_Odd}
Let $X$ be an element of the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ where ${\mathbf c}  \in  {\mathfrak C}_{\delta}$ and let $c:{\mathbf B} \rightarrow {\mathbb N}$ the symmetric function corresponding to ${\mathbf c}$.  Then the partition corresponding to the Jordan type of $X$ is 
\[
\prod_{b \in {\mathbf B}} \vert Supp(b) \vert^{c(b)}.
\]
Here we have described the partition in multiplicative form.
\end{proposition}
%proof
\begin{proof}
The proof is identical to the one of proposition~\ref{P:Height_Jordan_Type} and is left to the reader.
\end{proof}

% 4.18
\subsection{}
As when $\vert {\mathcal I} \vert$ is even, we want to give now a compact way to describe the symmetric function $c: {\mathbf B} \rightarrow {\mathbb N}$ corresponding to the coefficient function ${\mathbf c} \in  {\mathfrak C}_{\delta}$ but this time when $\vert {\mathcal I} \vert$ is odd. In fact,  we will give two approachs to describe the symmetric function $c: {\mathbf B} \rightarrow {\mathbb N}$.

%definition 4.19
\begin{definition}
A   {\it  orthogonal symmetric ${\mathcal I}$-tableau} is the ${\mathcal I}$-diagram with its boxes filled with elements of ${\mathbb N}$ such that if $c_{i,j}$ denoted the entry in the row indexed by $i$ and in the column indexed by $j$,   then we have $c_{-j,-i} = c_{i, j}$ for all $i, j \in {\mathcal I}$ and $i \geq j$.  A   {\it  symplectic symmetric ${\mathcal I}$-tableau} is the ${\mathcal I}$-diagram with its boxes filled with elements of ${\mathbb N}$ such that if $c_{i,j}$ denoted the entry in the row indexed by $i$ and in the column indexed by $j$,   then we have $c_{-j,-i} = c_{i, j}$ for all $i, j \in {\mathcal I}$ and $i \geq j$ with the added condition that $c_{i, -i}$ is an even integer for all $i \in {\mathcal I}$, $i \geq 0$ (i.e. the entries on the principal diagonal are even). 

Note this is different from how we define orthogonal and symplectic symmetric tableau when $\vert {\mathcal I}\vert$ is even. The two notions are transposed here.
\end{definition}

%example 4.20
\begin{example} \label{ExampleYoungDiagramOddCase}
For the ${\mathcal I} = \{4, 2, 0, -2, -4\}$, then 
\begin{center}
${\mathcal T}$ = 
\ytableausetup{centertableaux}
\begin{ytableau}
\none & \none [-4] & \none [-2] & \none [0] & \none [2] & \none [4] \\ \none [{\phantom -}4] & 0 & 1 & 2 & 0 & 0\\ \none [{\phantom -}2] & 1 & 1 & 3 & 1\\  \none [{\phantom -}0] & 2 & 3 & 2 \\ \none [-2] & 0 & 1\\ \none [-4] & 0 \\
\end{ytableau}
\end{center}
is an orthogonal symmetric ${\mathcal I}$-tableau, but not a symplectic symmetric ${\mathcal I}$-tableau.  
\begin{center}
${\mathcal T}'$ = 
\ytableausetup{centertableaux}
\begin{ytableau}
\none & \none [-4] & \none [-2] & \none [0] & \none [2] & \none [4] \\ \none [{\phantom -}4] & 2 & 1 & 3 & 0 & 1\\ \none [{\phantom -}2] & 1 & 0 & 2 & 1\\  \none [{\phantom -}0] & 3 & 2 & 2 \\ \none [-2] & 0 & 1\\ \none [-4] & 1 \\
\end{ytableau}
\end{center}
is a symplectic symmetric ${\mathcal I}$-tableau. We have kept the indices for the rows and columns  inscribed in both cases.
\end{example}

%definition 4.21
\begin{definition}
Given the symplectic (respectively orthogonal) symmetric ${\mathcal I}$-tableau ${\mathcal T} = (c_{i, j})_{i, j \in {\mathcal I}, i \geq j}$, we define its {\it dimension vector} $\delta({\mathcal T}) = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$, where
\[
\delta_i = \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq v \end{subarray}} c_{u, v} \quad \text{for all $i \in {\mathcal I}$.}
\]
\end{definition}

%example 4.22
\begin{example} 
If ${\mathcal T}$ and ${\mathcal T}'$  are the symmetric ${\mathcal I}$-tableaux of example~\ref{ExampleYoungDiagramOddCase}, then their dimension vectors are  
\[
\begin{aligned}
\delta({\mathcal T}) &= (\delta_{4}, \delta_2, \delta_0, \delta_{-2}, \delta_{-4}) =  (3, 9, 15, 9, 3) \quad \text{ and }\\
\delta({\mathcal T}') &= (\delta_{4}, \delta_2, \delta_0, \delta_{-2}, \delta_{-4}) =  (7, 10, 16, 10, 7)
\end{aligned}
\]
\end{example}

%lemma 4.23
\begin{lemma}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$. Denote by ${\mathfrak T}_{\delta}$: the set of symplectic (respectively orthogonal) symmetric ${\mathcal I}$-tableaux ${\mathcal T}$ of dimension $\delta({\mathcal T}) = \delta = (\delta_i)_{i \in {\mathcal I}}$ and by ${\mathfrak R}_{\delta}$: the set of symplectic (respectively orthogonal) symmetric ${\mathcal I}$-tableaux ${\mathcal R} = (r_{i, j})_{i, j \in I, i \geq j}$ such that 
\[
r_{i, i} = \delta_i \quad \text{ and } \quad (r_{i, j} - r_{i + 2, j} - r_{i , j - 2} + r_{i + 2, j - 2}) \geq 0 \quad \text{ for all $i, j \in {\mathcal I}$ and $i \geq j$}
\]
where we set $r_{i, j} = 0$ if either $i \not\in {\mathcal I}$ or $j \not\in {\mathcal I}$ or both. Then the map $\varTheta:{\mathfrak T}_{\delta} \longrightarrow {\mathfrak R}_{\delta}$
\[
\varTheta({\mathcal T}) = \varTheta((c_{i, j})_{i, j \in {\mathcal I}, i \geq j}) = (r_{i, j})_{i, j \in I, i \geq j} \quad \text{where $r_{i, j} = \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq j \geq v\end{subarray}} c_{u, v}$}  
\]
for all $i , j \in {\mathcal I}$, $i \geq j$,  is a well-defined bijection.
\end{lemma}
\begin{proof}
The proof is similar to the proof of lemma~\ref{L:RankComponentTableau} and is left to the reader.
\end{proof}

