% definition 4.25
\begin{definition}\label{D:SymmetricTableauOddSymplectic}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and  the coefficient function ${\mathbf c} \in  {\mathfrak C}_{\delta}$.  To ${\mathbf c}$, denote the corresponding symmetric function by $c: {\mathbf B} \rightarrow {\mathbb N}$. We define the symmetric ${\mathcal I}$-tableau ${\mathcal T}({\mathbf c})$ as follows: if $c_{i, j}$ is the entry at the row $i$ and column $j$ with $i, j \in {\mathcal I}$ and $i \geq j$, then 
\[
c_{i, j} = \begin{cases} c(b(i, j, 0)), &\text{ if $i + j \ne 0$;}\\  c(b(i, j, 0)), &\text{ if $i + j = 0$ in the orthogonal case;}\\c(b(i, j, 0)) + c(b(i, j, 1)), &\text{ if $i + j = 0$ in the symplectic case.} \end{cases}
\]

Because $c: {\mathbf B} \rightarrow {\mathbb N}$ is symmetric,  ${\mathcal T}({\mathbf c})$ is clearly a symmetric ${\mathcal I}$-tableau. Moreover in the symplectic case, because  we have that $c(b(i, j, 0)) = c(b(i, j, 1))$ when $i + j = 0$, we get that $c_{i, -i}$ is even. Thus ${\mathcal T}({\mathbf c})$ is an  symplectic symmetric ${\mathcal I}$-tableau.  

We have 
\[
\begin{aligned}
 \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq v \end{subarray}} c_{u, v} &=  \sum_{\begin{subarray}{c} u, v \in {\mathcal I}\\ u \geq i \geq v \\ u + v \ne 0 \end{subarray}} c(b(u, v, 0))\\ & \quad\quad +  \begin{cases} \displaystyle\sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \geq -u \end{subarray}} (c(b(u, -u, 0)) + c(b(u, -u, 1))) \text{ in the symplectic case;} \\ \\ \displaystyle\sum_{\begin{subarray}{c} u \in {\mathcal I}\\ u \geq i \geq -u \end{subarray}} c(b(u, -u, 0))  \text{ in the orthogonal case;} \end{cases} \\ &= \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ i \in Supp(b) \end{subarray}} c(b) = \delta_i.
 \end{aligned}
 \] 
Consequently $\delta({\mathcal T}({\mathbf c})) = \delta$ and ${\mathcal T}({\mathbf c}) \in {\mathfrak T}_{\delta}$. 
\end{definition}

%lemma 4.26
\begin{lemma}\label{L:TableauOrbitOdd}
Let $\delta = (\delta_i)_{i \in {\mathcal I}} \in {\mathbb N}^{\mathcal I}$ with $\delta_{-i} = \delta_i$ for all $i \in {\mathcal I}$ and let ${\mathfrak g}_2/G^{\iota}$ denotes the set of  $G^{\iota}$-orbits  in ${\mathfrak g}_2$. Then
\begin{enumerate}[\upshape (a)]
\item the map ${\mathcal T}: {\mathfrak C}_{\delta} \rightarrow {\mathfrak T}_{\delta}$, where   ${\mathbf c} \mapsto {\mathcal T}({\mathbf c})$ is a bijection;
\item the map ${\mathfrak g}_2/G^{\iota} \rightarrow  {\mathfrak T}_{\delta} \quad \text{ defined by } \quad G^{\iota} \cdot X \mapsto {\mathcal T}({\mathbf c}_X)$ is a well-defined bijection. 
\end{enumerate}
\end{lemma}
\begin{proof}
(a) is obvious from the definition of ${\mathcal T}$ above and (b) is a corollary of proposition~\ref{Prop_Indexation_Orbits_Odd}
\end{proof}

%notation 4.27
\begin{notation}
We will denote the $G^{\iota}$-orbit  in ${\mathfrak g}_2$ corresponding to the ${\mathcal I}$-tableau ${\mathcal T}  \in {\mathfrak T}_{\delta}$ as defined in the bijection of lemma~\ref{L:TableauOrbitOdd} (b)  by ${\mathcal O}_{\mathcal T}$
\end{notation}

In \cite{BI2021},  M. Boos and G. Cerulli Irelli, were able to describe the partial order on the $G^{\iota}$-orbits in ${\frak g}_2$ for symmetric quivers in the orthogonal and symplectic cases for  symmetric quivers of type $A_m^{even}$ and $A_m^{odd}$. We will now describe their result in our case (i.e. $\vert {\mathcal I} \vert$ odd).


%proposition 4.28
\begin{proposition}[Boos and Cerulli Irelli]\label{P:PartialOrderIOddSymplectic}
(In the situation of \ref{S:SetUpOdd}) Let  ${\mathcal I}$-tableaux ${\mathcal T}$, ${\mathcal T}' \in  {\mathfrak T}_{\delta}$ and  the corresponding $G^{\iota}$-orbits ${\mathcal O}_{\mathcal T}$ , ${\mathcal O}_{{\mathcal T}'}$ in ${\frak g}_2$. Then the  $G^{\iota}$-orbit  ${\mathcal O}_{\mathcal T}$ is contained in the Zariski closure of the   $G^{\iota}$-orbit ${\mathcal O}_{{\mathcal T}'}$ if and only if
\[
(r_{i, j})_{i, j \in {\mathcal I}, i \geq j} = {\mathcal R} = \varTheta({\mathcal T}) \leq \varTheta({\mathcal T}') = {\mathcal R}' = (r'_{i, j})_{i, j \in {\mathcal I}, i \geq j}
\]
where the inequality here between the tableaux ${\mathcal R}$ and ${\mathcal R}'$ means $r_{i, j} \leq r'_{i, j}$ for all $i, j \in {\mathcal I}$, $i \geq j$. 
\end{proposition}
%proof
\begin{proof}
The proof is similar to the proof of the proposition~\ref{P:PartialOrderIEven} and is left to the reader.
\end{proof}

