%Section 5
\section{$G^{\iota}$-orbits in ${\mathfrak g}_2$ in the special orthogonal case when $\vert{\mathcal I}\vert$ is odd.}

%5.1
\subsection{}
In this section, we will restrict ourself to the special orthogonal case when $\vert {\mathcal I} \vert$ is odd.  The special orthogonal case is trickier. The reason being  that special orthogonal isomorphism is more restricted that orthogonal isomorphism as we saw in \ref{SS:ExampleIsomorphismSpecialOrtho}.



%subsection 5.2
\subsection{}\label{S:SetUpOddOrtho}
In this section,  
\begin{itemize}
\item $m$ is an integer $> 0$;
\item $\tilde G$ is  the group of automorphisms of a finite dimensional vector space $V$ over $k$ preserving a fixed non-degenerate symmetric form $\langle\ , \  \rangle: V \times V \rightarrow {\mathbf k}$;  in other words, $\tilde G = O(V)$; 
\item $G$ is the connected component of the identity element of the group $\tilde G$,  in other words, $G = SO(V)$;
\item $\epsilon = 1$;
\item $\mathfrak g$ is the Lie algebra of $G$, more precisely $X \in {\mathfrak g}$ if and only if $X:V \rightarrow V$ is an endomorphism of $V$ such that $\langle X(v_1), v_2\rangle + \langle v_1 , X(v_2)\rangle = 0$ for all $v_1, v_2 \in V$;
\item $V$ is identified to its dual $V^*$ by the isomorphism $\phi: V \rightarrow V^*$ defined by $v \mapsto \phi_v$, where $\phi_v: V \rightarrow {\mathbf k}$ is $\phi_v(x) = \langle v, x\rangle$ for all $x \in V$;  
\item ${\mathcal I} = \{n \in {\mathbb Z} \mid n \equiv 0 \pmod 2, -2m <  n  < 2m \}$;
\item $\oplus_{i \in {\mathcal I}} V_i$ is a direct sum decomposition of $V$ by  vector subspaces $V_i \ne 0$ such that 
\begin{itemize} \item $\langle v, v'\rangle = 0$ whenever $v \in V_i$, $v' \in V_j$ and $i + j \ne 0$;
			\item $V_{-i} = V_i^*$ for all $i \in {\mathcal I}$ under the identification given by $\phi$ above.
\end{itemize} 
Note that the restriction of the non-degenerate symmetric  form $\langle\ , \ \rangle$ to $V_0 \times V_0$ is a non-degenerate symmetric  form.
\item ${\mathcal B} = \coprod_{i \in {\mathcal I}} {\mathcal B}_i$ is a basis of $V$ such that each ${\mathcal B}_i = \{ u_{i, j} \mid  1 \leq j \leq \delta_i \}$  is a basis of $V_i$ for each $i \in {\mathcal I}$ and $i \ne 0$, where $\delta_i$ is the dimension of $V_i$, and ${\mathcal B}_0 = \{ u_{0, j} \mid 1 \leq j \leq \delta_0 \}$ is a basis of $V_0$, where $\delta_0$ is the dimension of $V_0$ and these bases are such that, for $i, j \in {\mathcal I}$, 
\[
\begin{aligned}
\langle u_{i, r}, u_{j, s}\rangle &= \begin{cases} 1, &\text{if $i , j \ne 0$, $i + j = 0$ and $r = s$;}\\ 0, &\text{otherwise;} \end{cases}
\\
\langle u_{0, r}, u_{0, s}\rangle &= \begin{cases} 1, &\text{if  $r + s = \delta_0 + 1$;}\\ 0, &\text{otherwise;}\\  \end{cases}
\\
\text{ and }
\\
\langle u_{0, r}, u_{i, s}\rangle &= \langle u_{i, s}, u_{0, r}\rangle = 0, \text{ if $i \ne 0$, $1 \leq s \leq \delta_i$, $1 \leq r \leq \delta_0$.}
\end{aligned}
\]


\item $\iota: {\mathbf k}^{\times} \rightarrow {\tilde G}$ is the homomorphism defined by $\iota(t) v = t^i v$ for all $i \in {\mathcal I}$, $v \in V_i$ and $t \in {\mathbf k}^{\times}$ and clearly $\iota(t) \in G$ for all $t \in {\mathbf k}^{\times}$;
\item ${\mathbf B}$ is the set of ${\mathcal I}$-boxes;
\item ${\mathbf B}/\tau$ denote the set of $\langle \tau\rangle$-orbits ${\mathcal O}$ in ${\mathbf B}$; 
\item $\nu = \vert {\mathbf B}/\tau \vert = m^2$.
\end{itemize}

% 5.3
\subsection{}
In proposition~ \ref{Prop_Indexation_Orbits_Odd}, we gave a parametrization of the set ${\mathfrak g}_2/{\tilde G}^{\iota}$ of ${\tilde G}^{\iota}$-orbits in ${\mathfrak g}_2$ by giving a bijection $\Upsilon: {\mathfrak g}_2/{\tilde G}^{\iota} \rightarrow {\mathfrak C}_{\delta}$. To ${\mathbf c} \in {\mathfrak C}_{\delta}$, we have denoted the corresponding ${\tilde G}^{\iota}$-orbit under $\Upsilon$ by ${\mathcal O}_{\mathbf c}$. From our observation in \ref{SS:ObservationDimensionOrthogonal} and lemma~\ref{G2AsRepresOdd} (a), we have that the indice $[ {\tilde G}^{\iota}: G^{\iota}] = [O(V_0): SO(V_0)] = 2$. Note here we used the fact that $\dim(V_0) \ne 0$.  Consequently the ${\tilde G}^{\iota}$-orbit  ${\mathcal O}_{\mathbf c}$ is either a $G^{\iota}$-orbit  or splits into two $G^{\iota}$-orbits. We need to give a criteria on  ${\mathbf c} \in  {\mathfrak C}_{\delta}$ for when the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ splits or not. 

% proposition 5.4
\begin{proposition}\label{P:OrbitSplittingSO}
Let ${\mathbf c} \in {\mathfrak C}_{\delta}$ and the  symmetric function  $c:{\mathbf B} \rightarrow {\mathbb N}$ associated to ${\mathbf  c}$. 
\begin{enumerate}[\upshape (a)]
\item There exists $i, j \in {\mathcal I}$, $i \geq 0 \geq j$ such that $c(b(i, j, 0)) > 0$.
\item If there is an element $i' \in {\mathcal I}$, $i' \geq 0$ such that $c(b(i', -i', 0)) > 0$, then the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ does not split and it is a unique $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$.
\item If $c(b(i, -i, 0)) = 0$ for all $i \in {\mathcal I}$, $i \geq 0$, then  the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ splits into two $G^{\iota}$-orbits: ${\ }'{\mathcal O}_{\mathbf c}$ and ${\ }''{\mathcal O}_{\mathbf c}$. Moreover we have that  $\dim({\mathcal O}_{\mathbf c}) = \dim({\ }'{\mathcal O}_{\mathbf c}) = \dim({\ }''{\mathcal O}_{\mathbf c})$
\end{enumerate}
\end{proposition}
%proof
\begin{proof}
(a) We have 
\[
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ 0 \in Supp(b) \end{subarray}} c(b) = \sum_{\begin{subarray}{c} i, j \in {\mathcal I}\\ i \geq 0 \geq j \end{subarray}} c(b(i, j, 0)) = \delta_0 > 0
\]
and the result follows easily, because $c(b) \geq 0$ for all $b \in {\mathbf B}$. 

(b) Let $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ be the ${\mathcal I}$-graded isomorphism such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v\rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$ constructed in proposition~\ref{Prop_Indexation_Orbits_Odd}. Using this isomorphism we saw that ${\mathcal O}_{\mathbf c}$ is the ${\tilde G}^{\iota}$-orbit of $T_{\mathbf c}E_{\mathbf c} T_{\mathbf c}^{-1}$. We will write this element $T_{\mathbf c}E_{\mathbf c}T_{\mathbf c}^{-1}$ as $X_{\mathbf c}: V \rightarrow V$. Thus $X_{\mathbf c}: V \rightarrow V$ is an ${\mathcal I}$-graded linear transformation of degree 2 such that $\langle X_{\mathbf c}(u), v\rangle + \langle u , X_{\mathbf c}(v)\rangle = 0$ for all $u, v \in V$. Let $X: V \rightarrow V$ be an ${\mathcal I}$-graded linear transformation of degree 2 such that $\langle X(v_1), v_2\rangle + \langle v_1 , X(v_2) \rangle = 0$ for all $v_1, v_2 \in V$ and $X \in {\mathcal O}_{\mathbf c}$.  Thus there exists ${\tilde g} \in {\tilde G}^{\iota}$ such that $Ad({\tilde g})(X_{\mathbf c}) = X$.

If we consider $X_{\mathbf c}$, $X$ and ${\tilde g}$ as in lemma~\ref{G2AsRepresOdd} (a) and (b);  in other words, if we write $X_{{\mathbf c}, i}: X_{\mathbf c}\vert_{V_i}: V_i \rightarrow V_{i + 2}$ and $X_{i}: X\vert_{V_i}: V_i \rightarrow V_{i + 2}$ for all $i \in {\mathcal I}$, $i \ne 2(m - 1)$ and ${\tilde g}_i = {\tilde g}\vert_{V_i}:V_i \rightarrow V_i$ for all $i \in {\mathcal I}$, we have $X_i \circ {\tilde g}_i = {\tilde g}_{i + 2} \circ X_{{\mathbf c}, i}$ for all $i \in {\mathcal I}$, $i \ne 2(m - 1)$. We have ${\tilde g}_i \in GL(V_i)$, $\det({\tilde g}_{-i}) = (\det({\tilde g}_i))^{-1}$ for all $i \in {\mathcal I}$, $i \ne 0$,  ${\tilde g}_0 \in O(V_0)$ and $\det({\tilde g}) = \det({\tilde g}_0)$. 

By hypothesis, there exists an ${\mathcal I}$-box $b' \in {\mathbf B}$ such that $b' = b(i', -i', 0)$ and $c(b') \ne 0$, where  $i' \in {\mathcal I}$, $i' \geq 0$.  The $\langle\tau\rangle$-orbit of $b'$ is ${\mathcal O}' = \{b'\}$. Consider the symmetric function $c':{\mathbf B} \rightarrow {\mathbb N}$ defined by
\[
c'(b) = \begin{cases} c(b), &\text{if $b \ne b'$;} \\ (c(b') - 1), &\text{if $b = b'$.}\end{cases}
\]
and the associated coefficient function ${\mathbf c}':{\mathbf B}/\tau \rightarrow {\mathbb N}$. From its definition in \ref{N:CCorrespondanceOdd}, we have that $V({\mathbf c})$ is the direct sum of $V({{\mathbf c}'})$ and one copy of $V({\mathcal O}')$. Moreover the orthogonal complement $V({\mathcal O}')^{\perp}$ of $V({\mathcal O}')$ is $V({{\mathbf c}'})$. Because $b'$ is on the principal diagonal and from our construction for the orthogonal representation of $V({\mathcal O}') = V(b')$, then we know that the ${\mathcal I}$-component $V_i(b')$ of $V(b')$ for $i \in {\mathcal I}$ are 1-dimensional for $i \in Supp(b')$ and 0-dimensional otherwise; in particular $\dim(V_0(b')) = 1$.   

Using the isomorphism $T_{\mathbf c}$, we get that $V$ is the direct sum of the ${\mathcal I}$-graded indecomposable orthogonal representation $U = T_{\mathbf c}(V(b'))$ and its orthogonal complement $U^{\perp} = T_{\mathbf c}(V({{\mathbf c}'}))$ such that $U_i$ is 1-dimensional exactly when $i \in Supp(b')$ and 0-dimensional otherwise.  We want to show that there exists an element $g$ of $G^{\iota}$ such that $Ad(g)(X_{\mathbf c}) = X$. If the element ${\tilde g}$ above is such that  ${\tilde g}$ of $G^{\iota}$, then we are done by taking ${\tilde g}$ for $g$. 

Assume now that  ${\tilde g} \not\in  G^{\iota}$, in other words, $\det({\tilde g}_0) = -1$. Consider the linear transformation $h:V \rightarrow V$ such that $h(v) = h(u + u^{\perp}) = -u + u^{\perp}$, where $v = u + u^{\perp}$, with $u \in U$ and $u^{\perp} \in U^{\perp}$. It is easy to see that $h$ preserve the bilinear form $\langle\ , \ \rangle$ and that $h \in {\tilde G}^{\iota}$. Also we have that $Ad(h)(X_{\mathbf c}) = X_{\mathbf c}$, because
\[
\begin{aligned}
Ad(h)X_{\mathbf c}(v) &= h X_{\mathbf c} h^{-1} (u + u^{\perp}) = h X_{\mathbf c}(-u + u^{\perp}) = h(-X_{\mathbf c}(u) + X_{\mathbf c}(u^{\perp}))\\ &= X_{\mathbf c}(u) + X_{\mathbf c}(u^{\perp}) = X_{\mathbf c}(v),
\end{aligned}
\]
where $v = u + u^{\perp}$, with $u \in U$ and $u^{\perp} \in U^{\perp}$. 

Consider now $g = {\tilde g}h \in {\tilde G}$. We have $Ad(g)(X_{\mathbf c}) = Ad({\tilde g} h)(X_{\mathbf c}) = Ad({\tilde g})(X_{\mathbf c}) = X$ and $\det(g) = \det({\tilde g}_0)\det(h_0) = 1$, because $\det({\tilde g}_0) = -1$ and $\det(h_0) = -1$ from the fact that  $\dim(U_0) = 1$ and the definition of $h$. So $g \in G^{\iota}$ and the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ is a unique $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$.

(c) We will prove this by contradiction.  Assume there exist a dimension vector $\delta = (\delta_i)_{i \in {\mathcal I}}$, a coefficient function  ${\mathbf c} \in {\mathfrak C}_{\delta}$ and the associated symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$ such that 
\begin{itemize}
\item $\delta_i > 0$ for all $i \in {\mathcal I}$;
\item $c(b(i, -i, 0)) = 0$ for all $i \in {\mathcal I}$, $i \geq 0$;
\item the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ is a $G^{\iota}$-orbit, in other words the  ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ does not split;
\item the sum
\[
\sum_{{\mathcal O} \in {\mathbf B}/\tau} {\mathbf c}({\mathcal O})
\]
is minimal among all of the  ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ as above.
\end{itemize}

Let ${\mathbf B}' = \{b \in {\mathbf B} \mid b = b(i, j, 0) \text{ for some $i, j \in {\mathcal I}$, $i \geq 0 \geq j$ and $i + j \ne 0$}\}$. By (a) and,  because of our hypothesis,  ${\mathbf B}' \ne \emptyset$ and  there exist  $i', j' \in {\mathcal I}$ with $i' \geq 0 \geq j'$, $i' + j' > 0$ such that $b' = b(i', j', 0) \in {\mathbf B}'$ and $c(b') > 0$.  Note that $0 \in Supp(b')$ and $0 \in Supp(\tau(b'))$. Denote by ${\mathcal O}'$ the $\langle \tau\rangle$-orbit of $b'$. So ${\mathcal O}' = \{b', \tau(b')\}$.

Consider the symmetric function $c':{\mathbf B} \rightarrow {\mathbb N}$ defined by
\[
c'(b) = \begin{cases} c(b), &\text{if $b \not\in \{ b', \tau(b')\}$;} \\ (c(b') - 1), &\text{if $b \in \{ b', \tau(b')\}$.}\end{cases}
\]
and the associated coefficient function ${\mathbf c}':{\mathbf B}/\tau \rightarrow {\mathbb N}$. From its definition in \ref{N:CCorrespondanceOdd}, we have that $V({\mathbf c})$ is the direct sum of $V({{\mathbf c}'})$ and one copy of $V({\mathcal O}')$.  More precise,  
$V({\mathbf c})$: the direct sum as ${\mathcal I}$-graded vector space and  as  $\epsilon$-representations of ${\mathbf c}({\mathcal O})$ copies of $V({\mathcal O})$ with a ${\mathcal I}$-basis 
\[
{\mathcal B}_{\mathbf c} = \coprod_{{\mathcal O} \in {\mathbf B}/\tau} \coprod_{b \in {\mathcal O}} \{v_i^j(b) \mid i \in Supp(b), 1 \leq j \leq {\mathbf c}({\mathcal O})\}.
\]
and the bilinear form $\langle \  , \  \rangle_{\mathbf c}$ is described in \ref{N:CCorrespondanceOdd} with $\epsilon = 1$.  But $V({\mathbf c}')$: the direct sum as ${\mathcal I}$-graded vector space and  as   orthogonal representations of ${\mathbf c}'({\mathcal O})$ copies of $V({\mathcal O})$ with a ${\mathcal I}$-basis 
\[
{\mathcal B}_{{\mathbf c}'} = \coprod_{{\mathcal O} \in {\mathbf B}/\tau} \coprod_{b \in {\mathcal O}} \{v_i^j(b) \mid i \in Supp(b), 1 \leq j \leq {\mathbf c}'({\mathcal O})\}.
\]
and the bilinear form $\langle \  , \  \rangle_{{\mathbf c}'}$ is obtained by restriction of $\langle \  , \  \rangle_{\mathbf c}$ to $V({{\mathbf c}'})$ and $V({\mathcal O}')$ as ${\mathcal I}$-graded vector space and  as orthogonal representation  with a ${\mathcal I}$-basis $\{v_i^{c(b')}(b'),\    v_i^{c(b')}(\tau(b')) \mid i \in Supp(b')\}$ and the bilinear form $\langle \  , \  \rangle_{{\mathcal O}'}$ is obtained by restriction of $\langle \  , \  \rangle_{\mathbf c}$ to $V({\mathcal O}')$.   Note that  the orthogonal complement $V({\mathcal O}')^{\perp}$ of $V({\mathcal O}')$ is $V({{\mathbf c}'})$. 

Let $S_{{\mathcal O}'}:V({\mathbf c}) \rightarrow V({\mathbf c})$ be the ${\mathcal I}$-graded linear transformation of degree $0$ defined by
\[
S_{{\mathcal O}'}(u) = \begin{cases} u, &\text{if $u \in V({\mathbf c}')$;}\\ u, &\text{if $u \in V_i({\mathcal O}')$ and $i \ne 0$;} \\ v_0^{c(b')}(\tau(b')), &\text{if $u = v_0^{c(b')}(b')$;}\\  v_0^{c(b')}(b'), &\text{if $u = v_0^{c(b')}(\tau(b'))$.}
\end{cases}
\]

Let $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ be the ${\mathcal I}$-graded isomorphism such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v\rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$ constructed in proposition~\ref{Prop_Indexation_Orbits_Odd}. 
We can now consider the two ${\mathcal I}$-graded linear transformations $E_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c})$ and $E'_{\mathbf c} = S_{{\mathcal O}'}E_{\mathbf c}S_{{\mathcal O}'}^{-1}:V({\mathbf c}) \rightarrow V({\mathbf c})$ and their corresponding elements $X_{\mathbf c}= T_{\mathbf c}E_{\mathbf c}T^{-1}_{\mathbf c}:V \rightarrow V$ and $X'_{\mathbf c}= T_{\mathbf c}E'_{\mathbf c}T^{-1}_{\mathbf c}:V \rightarrow V$. Using this isomorphism,  we saw that ${\mathcal O}_{\mathbf c}$ is the ${\tilde G}^{\iota}$-orbit of $X_{\mathbf c}$, but also the ${\tilde G}^{\iota}$-orbit of $X'_{\mathbf c}$. From our construction, both of these are in the same $G^{\iota}$-orbit. Thus by our assumption,  there exists a special orthogonal element $g \in G^{\iota}$ such that $Ad(g) X_{\mathbf c} = X'_{\mathbf c}$, i.e. $det(g) = 1$. 

By considering the ${\mathcal I}$-graded vector subspace $U = T_{\mathbf c}(V({\mathcal O}'))$ and its orthogonal complement  $U^{\perp}  = T_{\mathbf c}(V({\mathbf c}'))$, we get that both are $Ad(g)$-invariant subspaces. In this case,  $\det(g) = \det(g\vert_U) \det(g\vert_{U^{\perp}}) = 1$ and by the minimality of ${\mathbf c}$, we have that  $\det(g\vert_{U^{\perp}}) = 1$.  Thus $\det(g\vert_U) = 1$, but this contradicts the fact we saw in \ref{SS:SpecialOrthoRepresentationsInSameOrthoClass} and \ref{SS:ExampleIsomorphismSpecialOrtho}  that  $E_{{\mathcal O}'}$ and $S_{{\mathcal O}'}\vert_{V({\mathcal O}')} E_{{\mathcal O}'} S^{-1}_{{\mathcal O}'}\vert_{V({\mathcal O}')}$ are not isomorphic relative to the special orthogonal group.  This completes the proof that the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ splits into two $G^{\iota}$-orbits $'{\mathcal O}_{\mathbf c}$ and $''{\mathcal O}_{\mathbf c}$.  With the above notation, $'{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X_{\mathbf c}$ and $''{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X'_{\mathbf c}$ .
\end{proof}

%remark 5.5
\begin{remark}\label{R:DimensionForSplitting}
If there is at least one ${\tilde G}^{\iota}$-orbit ${\mathcal O}$ that splits into two $G^{\iota}$-orbits,  then the dimension $\dim(V)$ of $V$ (equivalently $\dim(V_0)$ of $V_0$) is even.  This follows easily from the fact that, if ${\mathcal O}_{\mathbf c}$ splits into two $G^{\iota}$-orbits, then $c(b(i, -i, 0)) = 0$ for all $i \in {\mathcal I}$, $i \geq 0$  for the symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$ corresponding  to ${\mathbf c}$ by proposition~\ref{P:OrbitSplittingSO} (c). Then
\[
\begin{aligned}
\delta_0 &= \dim(V_0) = \sum_{\begin{subarray}{c}  i, j \in {\mathcal I}\\ i \geq 0 \geq j \end{subarray}} c(b(i, j, 0)) = \sum_{\begin{subarray}{c} i, j \in {\mathcal I}\\ i \geq 0 \geq j\\ i + j \ne 0 \end{subarray}} c(b(i, j, 0)) + \sum_{\begin{subarray}{c} i \in {\mathcal I}\\ i \geq 0\end{subarray}} c(b(i, -i, 0)) \\ &= 2\sum_{\begin{subarray}{c}  i, j \in {\mathcal I}\\ i \geq 0 \geq j\\ i + j > 0 \end{subarray}} c(b(i, j, 0)) 
\end{aligned}
\]
because, if $i, j \in {\mathcal I}$, $i \geq 0 \geq j$ and $i + j > 0$, then  $c(b(i, j, 0)) = c(b(-j, -i, 0))$.  
\end{remark}

%notation 5.6
\begin{notation}\label{N:CCorrespondanceSpecialOrtho}
Using the same notation as in proposition~\ref{P:OrbitSplittingSO}, we can associated to each $G^{\iota}$-orbit: a Jacobson-Morozov triple. 
\begin{itemize}
%
\item If the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ does not split (case (b) in the proposition~\ref{P:OrbitSplittingSO}), then the Jacobson-Morozov triple  associated to the $G^{\iota}$-orbit  ${\mathcal O}_{\mathbf c}$ is $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ as in \ref{N:CCorrespondanceOdd}. 
%
\item If the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ does split (case (c) in proposition ~\ref{P:OrbitSplittingSO}) and the $G^{\iota}$-orbit is ${\ }'{\mathcal O}_{\mathbf c}$, then the Jacobson-Morozov triple associated to the  $G^{\iota}$-orbit ${\ }'{\mathcal O}_{\mathbf c}$ is $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ as in \ref{N:CCorrespondanceOdd}. We will denote this triple as $({\ }'E_{\mathbf c}, {\ }'H_{\mathbf c}, {\ }'F_{\mathbf c})$.
%
\item If the ${\tilde G}^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ does split (case (c) in proposition~\ref{P:OrbitSplittingSO}) and the $G^{\iota}$-orbit is ${\ }''{\mathcal O}_{\mathbf c}$, then the Jacobson-Morozov triple associated to the  $G^{\iota}$-orbit 
${\ }''{\mathcal O}_{\mathbf c}$ will be denoted as $({\ }''E_{\mathbf c}, {\ }''H_{\mathbf c}, {\ }''F_{\mathbf c})$.  If ${\mathcal O}' \in {\mathbf B}'/\tau$ is as in the proof of  proposition~\ref{P:OrbitSplittingSO} (c), where $''E_{\mathbf c} = S_{{\mathcal O}' } E_{\mathbf c} S^{-1}_{{\mathcal O}'}$, $''H_{\mathbf c} = S_{{\mathcal O}' } H_{\mathbf c} S^{-1}_{{\mathcal O}'}$ and $''F_{\mathbf c} = S_{{\mathcal O}' } F_{\mathbf c} S^{-1}_{{\mathcal O}'}$.  Note that if we had chosen another ${\mathcal O}' \in {\mathbf B}'/\tau$ is as in the proof of  proposition~\ref{P:OrbitSplittingSO} (c), then we get another Jacobson-Morozov triple, but it is in the same $G(V_{\mathbf c})^{\iota}$-orbit.
\end{itemize}

Using the isomorphism $T_{\mathbf c}:V_{\mathbf c} \rightarrow V$,  we can transport an associated Jacobson-Morozov triple to a $G^{\iota}$-orbit to the Lie algebra ${\mathfrak g}$.
\end{notation}

%example 5.7
\begin{example}\label{E:5.7}
If we reconsider the example~\ref{E:4.27}, then none of the fourteen ${\tilde G}^{\iota}$-orbits splits because the dimension $\dim(V_0) = 3$ of $V_0$ is odd. Consequently all fourteen ${\tilde G}^{\iota}$-orbits are $G^{\iota}$-orbits.
\end{example}

