%section 6
\section{Conditions for two $G^{\iota}$-orbits in ${\mathfrak g}_2$ to be in the same $G$-orbit.}

%6.1
\subsection{}
In this section, we want to answer the question of when two $G^{\iota}$-orbits ${\mathcal O}$, ${\mathcal O}'$ in ${\mathfrak g}_2$ are in the same $G$-orbit where $G$ is either the reductive group $Sp(V)$ (respectively $SO(V)$) as in \ref{S:SetUpAeven} when $\vert {\mathcal I} \vert$ is even or the reductive group $Sp(V)$ (respectively $O(V)$) as in \ref{S:SetUpOdd} when $\vert {\mathcal I} \vert$ is odd or finally the reductive group $SO(V)$ as in \ref{S:SetUpOddOrtho} when $\vert {\mathcal I} \vert$ is odd.

Let two $G^{\iota}$-orbits ${\mathcal O}$, ${\mathcal O}'$ in ${\mathfrak g}_2$ whose  partitions corresponding to their Jordan  type are respectively $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$  and $1^{a'(1)} 2^{a'(2)} 3^{a'(3)} \dots$. If these two orbits are in the same $G$-orbit, then these two partitions will be equal (i.e. $a(k) = a'(k)$ for all $k \in {\mathbb N}$). This follows easily from the fact that they are $GL(V)$-conjugate. 

Thus in this section,   we will consider  two $G^{\iota}$-orbits ${\mathcal O}$, ${\mathcal O}'$ in ${\mathfrak g}_2$ that have the same partition corresponding to their Jordan type $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ and  we will answer the question of when they are $G$-conjugate.

%6.2
\subsection{}\label{SS:ConjClassJordanPart}
By propositions \ref{P:Height_Jordan_Type} and \ref{P:Height_Jordan_Type_Odd}, we know the  partition corresponding to the Jordan type for the elements in a $G^{\iota}$-orbit ${\mathcal O}$ and consequently in their $G$-orbit.  It is known  when the characteristic $p$ is 0 or  is sufficiently large that the nilpotent class in the Lie algebra of $Sp(V)$(respectively $O(V)$)  is the intersection of the nilpotent class of the Lie algebra of $GL(V)$ with the Lie algebra of $Sp(V)$ (respectively $O(V)$). Moreover a nilpotent class of $O(V)$ in its Lie algebra is also a nilpotent class of $SO(V)$ in its Lie algebra except when the   partition $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ (in multiplicative form) corresponding to its Jordan  type is such that $a(k) = 0$ when $k \equiv 1 \pmod 2$ and  $a(k) \equiv 0 \pmod 2$ when $k \equiv 0 \pmod 2$.  We will say that these latter partitions  are {\it totally even}. See for example section 2.5 in \cite{S1982}. In this reference, it is quoted for unipotent classes, but it is also valid for the nilpotent classes when $p$ is $0$ or sufficiently large.

%6.3
\begin{proposition}
Let $G$ be the reductive group $Sp(V)$ (respectively $O(V)$) in the situation either as in \ref{S:SetUpAeven} when $\vert {\mathcal I} \vert$  is even or  as in \ref{S:SetUpOdd} when $\vert {\mathcal I} \vert$ is odd and let ${\mathcal O}$ and ${\mathcal O}'$ be two $G^{\iota}$-orbits in ${\mathfrak g}_2$ who both have the same partition $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ corresponding  to their Jordan type. Then these two $G^{\iota}$-orbits are in the same $G$-orbit. 
\end{proposition}
\begin{proof}
If their corresponding partitions are equal, then they are $GL(V)$-conjugate and by our observation in ~\ref{SS:ConjClassJordanPart} they are  $Sp(V)$-conjugate (resp.  $O(V)$-conjugate). 
\end{proof}

%6.4
\begin{proposition}\label{P:OrbitNotTotallyEven}
Let $G$ be the reductive group $SO(V)$ in the situation either as in \ref{S:SetUpAeven} when $\vert {\mathcal I} \vert$ is even or  as in \ref{S:SetUpOddOrtho} when $\vert {\mathcal I} \vert$ is odd and let ${\mathcal O}$ and ${\mathcal O}'$ be two $G^{\iota}$-orbits in ${\mathfrak g}_2$ who both have the same  partition $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ corresponding  to their Jordan type and this partition is not totally even. Then these two $G^{\iota}$-orbits are in the same $G$-orbit. 
\end{proposition}
\begin{proof}
If their corresponding partitions are equal, then they are $GL(V)$-conjugate and by our observation in ~\ref{SS:ConjClassJordanPart} and because the partition is not totally even, then they are  $SO(V)$-conjugate. 
\end{proof}

%6.5
\subsection{}
So we are left to study  the case of the reductive group $G = SO(V)$ and  two $G^{\iota}$-orbits ${\mathcal O}$ and ${\mathcal O}'$ in ${\mathfrak g}_2$,  that  have the same partition $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ corresponding  to their Jordan type  and this partition is totally even, i.e. the partition is of the form $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ with $a(k) \equiv 0 \pmod 2$ when $k \equiv 0 \pmod 2$. 

In the case where $\vert {\mathcal I}\vert$ is odd and  ${\tilde G}$ denotes  the group $O(V)$,  if  ${\mathcal O}_{\mathbf c}$ denotes a ${\tilde G}^{\iota}$-orbit in ${\mathfrak g}_2$,  where  ${\mathbf c} \in {\mathfrak C}_{\delta}$ is a coefficient  function ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ and $c:{\mathbf B} \rightarrow {\mathbb N}$ is the associated symmetric function to ${\mathbf c}$,  such that  $c(b(i, -i, 0)) > 0$ for at least one element $i \in {\mathcal I}$,  $i \geq 0$, then,  by  proposition~\ref{P:OrbitSplittingSO} (b), we know that this ${\tilde G}^{\iota}$-orbit  ${\mathcal O}_{\mathbf c}$  is a $G^{\iota}$-orbit, i.e. does not splits into two $G^{\iota}$-orbits:  ${}'{\mathcal O}_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$. Moreover the partition  $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ corresponding  to the Jordan type  of ${\mathcal O}_{\mathbf c}$ is not totally even.  This last fact follows because $\vert Supp(b(i,-i, 0)) \vert$ is odd for the ${\mathcal I}$-box $b(i, -i, 0)$ on the principal diagonal such that $c(b(i, -i, 0)) > 0$, where $i \in {\mathcal I}$, $i \geq  0$. 

In the case where $\vert {\mathcal I}\vert$ is odd, if  ${\tilde G}$ denotes  the group $O(V)$ and  ${\mathcal O}_{\mathbf c}$ denotes a ${\tilde G}^{\iota}$-orbit in ${\mathfrak g}_2$,  where  ${\mathbf c} \in {\mathfrak C}_{\delta}$ is a coefficient  function ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ and $c:{\mathbf B} \rightarrow {\mathbb N}$ is the associated symmetric function to ${\mathbf c}$,    such that  $c(b(i, -i, 0)) = 0$ for all $i \in {\mathcal I}$,  $i \geq 0$, then,  by  proposition~\ref{P:OrbitSplittingSO} (c), we know that this ${\tilde G}^{\iota}$-orbit  ${\mathcal O}_{\mathbf c}$  splits into two $G^{\iota}$-orbits:  ${}'{\mathcal O}_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$.  By the preceding paragraph, it is among these $G^{\iota}$-orbits that we must look for $G^{\iota}$-orbits whose partition  $1^{a(1)} 2^{a(2)} 3^{a(3)} \dots$ corresponding  to the Jordan type could be totally even. 

%lemma 6.6
\begin{lemma}\label{L:TotallyEvenCaseCoefficient}
Let $G$ be the reductive group $SO(V)$   in the situation  as in \ref{S:SetUpAeven} when $\vert {\mathcal I} \vert$ is even (respectively as in \ref{S:SetUpOddOrtho} when $\vert {\mathcal I} \vert$ is odd) and let ${\mathcal O} = {\mathcal O}_{\mathbf c}$  (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) be a $G^{\iota}$-orbit in ${\mathfrak g}_2$ whose partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ corresponding  to its Jordan type  is totally even, where ${\mathbf c} \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$: the symmetric function associated to ${\mathbf c}$.  If $b \in {\mathbf B}$ is such that  $\lambda(b) \not\equiv \vert {\mathcal I} \vert \pmod 2$, then $c(b) = 0$.  Recall  that $\lambda(b) = (i + j)/2$ for $b = b(i, j, k)$, with $i, j \in {\mathcal I}$,  $i \geq j$ and $0 \leq k \leq \mu(i, j)$ as defined in \ref{N:LambdaValue}. 
\end{lemma}
\begin{proof}
In both cases: $\vert {\mathcal I} \vert$ even or odd,  the result follows  easily from the fact that  if $b \in {\mathbf B}$, then $\vert Supp(b) \vert \equiv (\lambda(b) + \vert {\mathcal I} \vert) \pmod 2$ and  the partition corresponding to the  Jordan type is totally even. 
\end{proof}

%notation 6.7
\begin{notation}\label{N:SuppCardinality}
With the same notation and hypothesis as the above lemma, we get that if $c(b) \ne 0$ for a symmetric function $c:{\mathbf B} \rightarrow  {\mathbb N}$, then $\vert Supp(b) \vert$ is even.  For $b = b(i, j, k)$ with $i, j \in {\mathcal I}$, $i \ge j$ and $0 \leq k \leq \mu(i, j)$, we denote by 
\[
Supp^{top}(b) = \left\{ i' \in {\mathcal I}\  \left\vert\   i \geq i' \geq \left(\frac{i + j + 2}{2}\right)\right. \right\}
\]
This is the top-half of the elements in the support $Supp(b)$ of the ${\mathcal I}$-box $b \in {\mathbf B}$.
\end{notation}

We will consider separately the situation in \ref{S:SetUpAeven} when $\vert {\mathcal I} \vert$ is even  and the one in \ref{S:SetUpOddOrtho} when $\vert {\mathcal I} \vert$ is odd.

%lemma 6.8
\begin{lemma}\label{L:MaximalIsotropicV(c)}
Let $G$ be the reductive group $SO(V)$  as in \ref{S:SetUpAeven} where $\vert {\mathcal I} \vert$ is even and let ${\mathcal O} = {\mathcal O}_{\mathbf c}$  be a $G^{\iota}$-orbit in ${\mathfrak g}_2$,  whose partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ corresponding  to its Jordan type  is totally even, where ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ is a coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$: the symmetric function associated to ${\mathbf c}$.  We will now recall the notation of \ref{N:CCorrespondance}.  $V({\mathbf c})$ is a vector space with its ${\mathcal I}$-basis 
\[
{\mathcal B}_{\mathbf c} = \coprod_{{\mathcal O} \in {\mathbf B}/\tau} \coprod_{b \in {\mathcal O}} \{v_i^j(b) \mid i \in Supp(b), 1 \leq j \leq {\mathbf c}(b)\}
\]
and  the non-degenerate bilinear form $\langle \  ,\   \rangle_{\mathbf c}: V({\mathbf c}) \times V({\mathbf c}) \rightarrow {\mathbf k}$,   $E_{\mathbf c}: V({\mathbf c}) \rightarrow V({\mathbf c})$ is also defined in \ref{N:CCorrespondance}. It is a nilpotent element whose partition corresponding to the Jordan type is  the even partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$. Then  the vector subspace 
\[
L({\mathbf c}) = E_{\mathbf c} [\ker(E^2_{\mathbf c})] + E^2_{\mathbf c} [\ker(E^4_{\mathbf c})]  + \dots + E^k_{\mathbf c} [\ker(E^{2k}_{\mathbf c})]  + \dots
\]
is the vector subspace of $V({\mathbf c})$ spanned by the basis
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{v_i^j(b) \mid i \in Supp^{top}(b), 1 \leq j \leq c(b)\}
\]
and this is a maximal isotropic subspace of $V({\mathbf c})$. 
\end{lemma}
%proof
\begin{proof}
Recall that the linear transformation $E_{\mathbf c}$ on the elements of the basis ${\mathcal B}_{\mathbf c}$  was described in notation~\ref{N:CCorrespondance}. Let ${\mathcal O}$ denote the $\langle \tau \rangle$-orbit of $b$, then,  if the orbit ${\mathcal O}$ has no overlapping ${\mathcal I}$-box supports,  $1 \leq j \leq {\mathbf c}({\mathcal O})$ and $i \in Supp(b)$, we have
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i < 0$;} \end{cases}
\]
while if the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports,  $b = b(i_1, j_1, k_1) \in {\mathcal O}$, $1 \leq j \leq {\mathbf c}({\mathcal O})$  and $i \in Supp(b)$, then we have 
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{ if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{ if $i \ne \max(Supp(b))$ and $i \geq 1$;}\\  -v_{i + 2}^j(b), &\text{ if  $i < -1$;}\\ {\phantom -} v_1^j(b), &\text{ if  $i = -1$ and $b$ is below  the principal diagonal;}\\ - v_1^j(b), &\text{ if $i = -1$ and $b$ is above  the principal diagonal;}\\  (- 1)^{k_1} v_1^j(b), &\text{ if $i = -1$ and $b$ is on  the principal diagonal.}
\end{cases}
\]
Let $b \in {\mathbf B}$ be an ${\mathcal I}$-box such that $c(b) \ne 0$. As noted in \ref{N:SuppCardinality}, then $\vert Supp(b) \vert$ is even. Write this cardinality as $2s$. 

From our definition of $E_{\mathbf c}$, we get easily that 
\begin{enumerate}[\upshape (i)]
\item for $1 \leq k \leq s$ and $1 \leq j \leq c(b)$, then 
\[
E^{2k}_{\mathbf c}(v_i^j(b)) = 0 \iff i > (\max(Supp(b)) - 4k);
\]
\item for $k > s$ and $1 \leq j \leq c(b)$, then $E^{2k}_{\mathbf c}(v_i^j(b)) = 0$ for all $i  \in Supp(b)$.
\end{enumerate}
If $1 \leq k \leq s$, $1 \leq j \leq c(b)$ and $i > (\max(Supp(b)) - 4k)$, then $v_i^j(b) \in \ker(E^{2k}_{\mathbf c})$ and 
\[
E^k_{\mathbf c}(v_i^j(b)) \text{ is } \begin{cases} 0, &\text{if $(i + 2k) > \max(Supp(b))$;}\\  \gamma v_{i + 2k}^j(b),  &\text{if $(i + 2k) \leq \max(Supp(b))$;} \end{cases}
\]
where $\gamma \in \{1, -1\}$.  

In this second case, i.e. $(i + 2k) \leq \max(Supp(b))$, then $(i + 2k)  \in Supp^{top}(b)$, because $
Supp(b) = \{i' \in {\mathcal I} \mid \max(Supp(b)) \geq i' \geq \min(Supp(b)) \}$,  with $\min(Supp(b)) =  (\max(Supp(b)) - 4s + 2)$ and
\[
Supp^{top}(b) = \{i' \in {\mathcal I} \mid \max(Supp(b)) \geq i'  \geq (\max(Supp(b)) - 2s + 2) \}.
\]
So in this second case, we have $(i + 2k) \leq \max(Supp(b))$ and also the lower inequality $(i + 2k) > (\max(Supp(b)) - 2k) \geq (\max(Supp(b)) - 2s)$, because $1 \leq k \leq s$.  This show that $(i + 2k) \in Supp^{top}(b)$. 

If $k > s$, $1 \leq j \leq c(b)$ and $i \in Supp(b)$, then $v_i^j(b) \in \ker(E^{2k}_{\mathbf c})$ and 
\[
E^k_{\mathbf c}(v_i^j(b)) \text{ is } \begin{cases} 0, &\text{if $(i + 2k) > \max(Supp(b))$;}\\  \gamma v_{i + 2k}^j(b),  &\text{if $(i + 2k) \leq \max(Supp(b))$;} \end{cases}
\]
where $\gamma \in \{1, -1\}$.  

In this second case, i.e. $(i + 2k) \leq \max(Supp(b))$, then $(i + 2k)  \in Supp^{top}(b)$.  because we have $(i + 2k) \leq \max(Supp(b))$ and also the lower inequality $(i + 2k) \geq  (\max(Supp(b)) - 4s + 2 + 2k) > (\max(Supp(b)) - 2s + 2)$, because $k > s$.  This show that $(i + 2k) \in Supp^{top}(b)$. 

Thus $L({\mathbf c})$ is included in the subspace of $V({\mathbf c})$ spanned by 
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{v_i^j(b) \mid i \in Supp^{top}(b), 1 \leq j \leq c(b)\}.
\]

Reciprocally if $b \in {\mathbf B}$ with $c(b) > 0$, $1 \leq j \leq c(b)$ and $i \in Supp^{top}(b)$, then we want to prove that $v_i^j(b) \in L({\mathbf c})$. Write again  $\vert Supp(b) \vert = 2s$ and we have that $Supp(b) = \{i' \in {\mathcal I} \mid \max(Supp(b)) \geq i' \geq \min(Supp(b)) \}$,  with $\min(Supp(b)) =  (\max(Supp(b)) - 4s + 2)$ . Because $i \in Supp^{top}(b)$, this means that $\max(Supp(b)) \geq i \geq (\max(Supp(b)) - 2s + 2)$. Write $i = \max(Supp(b)) - 2r$ with $0 \leq r \leq (s - 1)$.  We have  that 
\[
\begin{aligned}
\max(Supp(b)) \geq (i - 2r - 2) &\geq (\max(Supp(b)) - 4r - 2)\\  &\geq (\max(Supp(b)) - 4(s - 1) - 2 = \min(Supp(b)).
\end{aligned}
\]
Thus $(i - 2r - 2)  \in Supp(b)$ and we have  $E^{(r + 1)}_{\mathbf c}(v_{(i - 2r - 2)}^j(b)) = \gamma v_i^j(b)$, where $\gamma \in \{1, -1\}$.  
Note that $v_{(i - 2r - 2)}^j(b) \in \ker E_{\mathbf c}^{2(r + 1)}$, because  $(i - 2r - 2) + 4(r + 1) = (\max(Supp(b)) - 4r - 2) + 4(r + 1) > \max(Supp(b))$.
From all of the above, $L({\mathbf c})$ is the vector subspace of $V({\mathbf c})$ spanned by the basis
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{v_i^j(b) \mid i \in Supp^{top}(b), 1 \leq j \leq c(b)\}.
\]

The dimension $\dim(L({\mathbf c}))$ of $L({\mathbf c})$ is 
\[
\dim(L({\mathbf c})) = \sum_{b \in {\mathbf B}} c(b) \vert Supp^{top}(b) \vert = \frac{1}{2} \sum_{b \in {\mathbf B}} c(b) \vert Supp(b) \vert = \frac{1}{2} \dim(V({\mathbf c})).
\]

We will now show that $L({\mathbf c})$ is an isotropic subspace. From our construction of the bilinear form $\langle\  , \  \rangle_{\mathbf c}$ in notation~\ref{N:CCorrespondance}, we have $\langle v_i^j(b), v_{i'}^{j'}(b')\rangle \ne 0$ only if $j' = j$, $b' = \tau(b)$ and $i + i' = 0$.   Let $b \in {\mathbf B}$ with $c(b) > 0$, $1 \leq j \leq c(b)$,  $i \in Supp^{top}(b)$, $b' = \tau(b)$, $j' = j$ and  $i' \in Supp^{top}(b')$.  Write $\vert Supp(b) \vert = 2s$.  As above 
\[
Supp(b) = \{i'' \in {\mathcal I} \mid (\max(Supp(b)) - 4s + 2) \leq i'' \leq \max(Supp(b))\}.
\]
Thus $\vert Supp(\tau(b)) \vert = 2s$ and 
\[
Supp(\tau(b)) = \{i''' \in {\mathcal I} \mid  -\max(Supp(b)) \leq i''' \leq -(\max(Supp(b)) - 4s + 2)\}.
\]
From this we get that 
\[
Supp^{top}(b) = \{ i'' \in {\mathcal I} \mid \max(Supp(b)) \geq i'' \geq (\max(Supp(b)) - 2s + 2) \}
\]
and 
\[
Supp^{top}(\tau(b)) = \{ i''' \in {\mathcal I} \mid -(\max(Supp(b)) - 4s + 2) \geq i''' \geq -(\max(Supp(b)) - 2s) \}
\]
Now if $i \in Supp^{top}(b)$ and $i' \in Supp^{top}(\tau(b))$, then 
\[
(\max(Supp(b)) - 2s + 2) \leq i \leq \max(Supp(b)) 
\]
and 
\[
(-\max(Supp(b)) + 2s) \leq i' \leq (-\max(Supp(b)) + 4s - 2).
\]
From this, we get that $(i+ i') \geq 2$ and consequently $(i + i') \ne 0$ and $L({\mathbf c})$ is an isotropic subspace. It is a maximal isotropic subspace,  because $2 \dim(L({\mathbf c})) = \dim(V({\mathbf c}))$. 
\end{proof}

The following lemma is probably well-known. Its proof is included for completeness. 

%Lemma 6.9
\begin{lemma}\label{L:ConditionSO(V)orbit}
 Let ${\mathcal I}$ be even and using the notation of  \ref{S:SetUpAeven}, consider the set ${\mathcal J}$ of subsets $J$ of  $\{(i, j) \in {\mathcal I} \times {\mathbb N} \mid 1 \leq j \leq \delta_i\}$ such that  if $(i, j), (i', j) \in J$, then $i + i' \ne 0$ and  $J$ is maximal among such subsets.
\begin{enumerate}[\upshape (a)]
\item If $J \in {\mathcal J}$, then $2 \vert J \vert = \dim(V)$.
\item If $J \in {\mathcal J}$, then the subspace $L_J$ of $V$ spanned by $\{u_{i, j} \mid  (i, j) \in J\}$ is a maximal isotropic subspace of $V$.
\item Let  $J, J' \in {\mathcal J}$. Then the two maximal isotropic subspaces $L_J$ and $L_{J'}$ of $V$ are in the same $SO(V)$-orbit if and only if 
\[
 \vert \{(i, j) \in J \mid i < 0\}\vert  \equiv  \vert \{(i, j) \in J' \mid i < 0\}\vert  \pmod 2.
\]
\end{enumerate}
\end{lemma}
\begin{proof}
(a) From our notation in  \ref{S:SetUpAeven}, we have that 
\[
\dim(V) = \sum_{i \in {\mathcal I}} \delta_i =  \sum_{i \in {\mathcal I}}\vert \{ (i, j) \in {\mathcal I} \times {\mathbb N} \mid 1 \leq j \leq \delta_i\}\vert
\]
If $(i , j) \in {\mathcal I} \times {\mathbb N}$ is such that $1 \leq j \leq \delta_i$, then,  by the maximality of $J$, exactly one and only one of $(i, j)$, $(-i, j)$ belongs to $J$. Consequently  $2 \vert J \vert = \dim(V)$. 

(b) First we will show that $L_J$ is isotropic. From our hypothesis on the basis as defined in \ref{S:SetUpAeven}, we have that $\langle u_{i, j}, u_{i', j'}\rangle \ne 0$ if and only if $j = j'$ and $i + i' = 0$ when $(i, j), (i', j') \in {\mathcal I} \times {\mathbb N}$ are such that $1 \leq j \leq \delta_i$ and $1 \leq j' \leq \delta_{i'}$. But by our hypothesis on $J$, when $(i, j), (i', j') \in J$, then  $\langle u_{i, j}, u_{i', j'} \rangle = 0$. Otherwise we would have $j = j'$ and $i + i' = 0$. But this is impossible for two elements of $J$.  So $L_J$ is isotropic. Because $2\dim(L_J) = \dim(V)$ by (a), we get that $L_J$ is maximal. 

(c) We first need to remind some facts. Let $J_+ = \{(i, j) \in {\mathcal I} \times {\mathbb N} \mid i > 0, 1 \leq j \leq \delta_i\}$. Clearly $J_+ \in {\mathcal J}$.  Note that if $g \in O(V)$ is such that $g(L_{J_+}) = L_{J_+}$, then $g \in SO(V)$.  In fact by considering the matrix of $g$ in the basis $\{u_{i, j} \mid i \in {\mathcal I},  1 \leq j \leq \delta_i\}$ ordered properly, we get that this matrix is of the form 
\[
\begin{bmatrix} A & B\\ 0 & D\end{bmatrix} \quad \text{ such that } \quad  \begin{bmatrix} A & B\\ 0 & D\end{bmatrix}^T \begin{bmatrix} 0 & I\\ I & 0\end{bmatrix} \begin{bmatrix} A & B\\ 0 & D\end{bmatrix} = \begin{bmatrix} 0 & I\\ I & 0\end{bmatrix}.
\]
Consequently $A^TD = I$ ,  $\det(D) = (\det(A))^{-1}$ and $g \in SO(V)$. 

Let $g_J: V \rightarrow V$ denote the unique linear transformation such that
\[
g_J(u_{i, j}) = \begin{cases} u_{i, j}, &\text{if $i > 0$ and $(i, j) \in J$:}\\  u_{-i, j}, &\text{if $i >0$ and $(i, j) \not \in J$;}\\ u_{-i, j}, &\text{if $i < 0$ and $(i, j) \in J$;} \\ u_{i, j}, &\text{if $i < 0$ and $(i, j) \not\in J$.}
\end{cases}
\]
We can now show that $g_J \in O(V)$.  For $i_1, i_2 \in {\mathcal I}$, $1 \leq j_1 \leq \delta_{i_1}$ and $1 \leq j_2 \leq \delta_{i_2}$,   we must consider $\langle u_{i_1, j_1}, u_{i_2,j_2}\rangle$ and $\langle g_J(u_{i_1, j_1}), g_J(u_{i_2,j_2)}\rangle$.  We have 
\[
\langle u_{i_1, j_1}, u_{i_2, j_2}\rangle = \begin{cases} 1, &\text{ if $j_1 = j_2$ and $i_1 + i_2 = 0$;}\\ 0, &\text{otherwise.} \end{cases}
\]

If $j_1 \ne j_2$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2}) \rangle = \langle u_{i'_1, j_1}, u_{i'_2, j_2}\rangle = 0, 
\]
where $i'_1 \in \{i_1, -i_1\}$ and $i'_2  \in \{i_2, -i_2\}$, because $j_1 \ne j_2$.  

If $j_1 = j_2$ and $i_1 + i_2 = 0$, then we can assume by symmetry  that $i_1 > 0$ and $i_2 = -i_1 < 0$. Moreover $(i_1, j_1) \in J$ if and only if $(i_2, j_2) \not\in J$. Thus 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle = \begin{cases} \langle u_{i_1, j_1}, u_{i_2, j_2} \rangle, &\text{if $(i_1, j_1) \in J$;}\\  \langle u_{-i_1, j_1}, u_{-i_2, j_2} \rangle, &\text{if $(i_1, j_1) \not\in J$;} \end{cases} \quad = 1.
\]

If $j_1 = j_2$, $i_1 + i_2 \ne 0$ and  $i _1 - i_2 \ne 0$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle = \langle u_{i'_1, j_1}, u_{i'_2, j_2}\rangle = 0
\]
because $i'_1 \in \{i_1, -i_1\}$, $i'_2 \in \{i_2, -i_2\}$ and $i'_1 + i'_2 \ne 0$ from our hypothesis.

Finally if $j_1 = j_2$, $i_1 + i_2 \ne 0$ and $i_1 = i_2$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle  =  \langle g_J(u_{i_1, j_1}), g_J(u_{i_1, j_1})\rangle = \langle u_{i'_1, j_1}, u_{i'_1, j_1}\rangle = 0
\]
where  $i'_1 \in \{i_1, -i_1\}$. 

This completes the proof that $g_J \in O(V)$.   Note also that we have $g_J(L_{J_+}) =L_J$, because we only have to consider the basis element $u_{i, j}$ for $i > 0$ and in that case we get if $(i, j) \not\in J$, that $(-i, j) \in J$ and 
\[
g_J(u_{i, j}) =  \begin{cases} u_{i, j} \in L_J, &\text{if $i > 0$ and $(i, j) \in J$:}\\  u_{-i, j} \in L_J, &\text{if $i >0$ and $(i, j) \not \in J$.}
\end{cases}
\]

We can now compute the determinant of the matrix of $g_J$ relative to the basis $\{u_{i, j} \mid i \in {\mathcal I}, 1 \leq j \leq \delta_i\}$ where we consider first the basis elements $u_{i, j}$ for $(i, j) \in J_+$  and then the basis element $u_{-i, j}$  for $(i, j) \in J_+$ using the same total order for $J_+$. Using the Laplace expansion of $\det(g_J)$ and using recursion, we get easily that 
\[
\det(g_J) = (-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert}
\]
If $g \in O(V)$ and $g(L_{J_+}) = L_J$, then $\det(g) = (-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert}$, because 
\[
g(L_{J_+}) = L_J = g_J(L_{J_+})  \quad \Rightarrow \quad g^{-1}_Jg(L_{J_+}) =L_{J_+} \quad \text{ and } \quad g^{-1}_Jg \in SO(V)
\]
and $\det(g) = \det(g_J)$. 

We  complete the proof of (c).  If $L_J$ and $L_{J'}$ are in the same $SO(V)$-orbit, then they are both in the $SO(V)$-orbit of $L_{J_+}$ or both are not in the $SO(V)$-orbit of $L_{J_+}$. Thus 
\[
(-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert} = (-1)^{\vert \{(i, j) \in J' \mid i < 0\}\vert},  
\]
 i.e.  $\vert \{(i, j) \in J \mid i < 0\}\vert  \equiv  \vert \{(i, j) \in J' \mid i < 0\}\vert  \pmod 2$.  

 Conversely if $\vert \{(i, j) \in J \mid i < 0\}\vert  \equiv  \vert \{(i, j) \in J' \mid i < 0\}\vert  \pmod 2$, then we get that $L_J$ and $L_{J'}$ are both in the $SO(V)$-orbit of $L_{J_+}$ or both are not in the $SO(V)$-orbit of $L_{J_+}$.  Because there are exactly two $SO(V)$-orbits on the set of maximal isotropic subspaces of $V$, we get that $L_J$ and $L_{J'}$ are in the same $SO(V)$-orbit. 
\end{proof}

%notation 6.10
\begin{notation}
Let $G$ be the reductive group $SO(V)$  as in \ref{S:SetUpAeven} where $\vert {\mathcal I} \vert$ is even and let ${\mathcal O} = {\mathcal O}_{\mathbf c}$ be a $G^{\iota}$-orbit  in ${\mathfrak g}_2$,  whose Jordan type is a  totally even partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$, where ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ is a coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$: the symmetric function associated respectively to ${\mathbf c}$.  We will denote  
\[
\varXi({\mathcal O}) = \varXi({\mathcal O}_{\mathbf c}) =  \sum_{b \in {\mathbf B}} c(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert 
\]
and call $\varXi({\mathcal O})$: the {\it parity of the orbit} ${\mathcal O}$.  We will say that the $G^{\iota}$-orbit ${\mathcal O}$ is {\it even}. (respectively {\it odd}) if $\varXi({\mathcal O})$ is even  (respectively odd). 
\end{notation}




%proposition 6.11
\begin{proposition}\label{P:TotallyEvenOrbitSOIEvenCase}
Let $G$ be the reductive group $SO(V)$  as in \ref{S:SetUpAeven} where $\vert {\mathcal I} \vert$ is even and let ${\mathcal O} = {\mathcal O}_{\mathbf c}$ and  ${\mathcal O}' = {\mathcal O}_{{\mathbf c}'}$  be two $G^{\iota}$-orbits in ${\mathfrak g}_2$,  who both have the same totally even partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ corresponding  to their Jordan type, where ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ and ${\mathbf c}':{\mathbf B}/\tau \rightarrow {\mathbb N}$ are both coefficient functions ${\mathbf c}, {\mathbf c}' \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$ and $c':{\mathbf B} \rightarrow {\mathbb N}$: the symmetric functions associated respectively to ${\mathbf c}$ and ${\mathbf c}'$.  Then these two $G^{\iota}$-orbits  ${\mathcal O}$ and  ${\mathcal O}' $ are in the same $G$-orbit if and only if   ${\mathcal O}$ and  ${\mathcal O}' $ have the same parity, i.e. they are both even or both odd.
\end{proposition}
\begin{proof}
Recall that ${\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of the element $X_{\mathbf c} = T_{\mathbf c} E_{\mathbf c} T^{-1}_{\mathbf c}: V \rightarrow V$ where $E_{\mathbf c}:V({\mathbf c}) \rightarrow V({\mathbf c})$ is defined in \ref{N:CCorrespondance}  and $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$ is the ${\mathcal I}$-graded isomorphism defined in \ref{SS:IsomorphismV(c)andV}. We have shown in lemma~\ref{L:TcIsomorphism} that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$.  Using the notation of the lemma~\ref{L:MaximalIsotropicV(c)}, we get easily that $T_{\mathbf c}(L({\mathbf c}))$ is the maximal isotropic subspace of $V$ equal to 
\[
X_{\mathbf c}[\ker(X^2_{\mathbf c})] + X^2_{\mathbf c}[\ker(X^4_{\mathbf c})] + \dots + X^k_{\mathbf c}[\ker(X^{2k}_{\mathbf c})] + \dots
\]
and it is spanned by  
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{ T_{\mathbf c}(v_i^s(b)) \mid  i \in Supp^{top}(b) \text{ and  } 1 \leq s \leq c(b)\}.
\]
From our definition of $T_{\mathbf c}$, we get that this set is 
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{u_{i, j} \mid i \in Supp^{top}(b) \text{ and }  j \in J_i(b)\}
\]
where $J_i(b) = \{1 \leq j \leq \delta_i \mid u_{i, j} = T_{\mathbf c}(v_i^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}$.   For all $i \in {\mathcal I}$ and $b, b' \in {\mathbf B}$,  note that $\vert J_i(b) \vert = c(b)$ and if $b \ne b'$  are two distinct ${\mathcal I}$-boxes such that $i \in Supp(b) \cap Supp(b')$, then $J_i(b) \cap J_i(b') = \emptyset $. Because $L({\mathbf c})$ is a maximal isotropic subspace of $V({\mathbf c})$, we get that 
\[
J({\mathbf c}) = \coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{(i, j) \in {\mathcal I} \times {\mathbb N} \mid   i \in Supp^{top}(b) \text{ and }  j \in J_i(b)\} \in {\mathcal J}
\]
and $T_{\mathbf c}(L({\mathbf c})) = L_{J({\mathbf c})}$ with the notation of lemma~\ref{L:ConditionSO(V)orbit}.

We can do the same thing for the second orbit ${\mathcal O}_{{\mathbf c}'}$.  Now if ${\mathcal O}_{\mathbf c}$  and ${\mathcal O}_{{\mathbf c}'}$ are in the same $SO(V)$-orbit, then the two maximal isotropic subspaces $T_{\mathbf c}(L({\mathbf c}))$ and $T_{{\mathbf c}'}(L({\mathbf c}'))$ are in the same $SO(V)$-orbit and by lemma~\ref{L:ConditionSO(V)orbit}, we get
\[
\sum_{b \in {\mathbf B}} c(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert \equiv \sum_{b \in {\mathbf B}} c'(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert  \pmod 2.
\]

Reciprocally assume that 
\[
\sum_{b \in {\mathbf B}} c(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert \equiv \sum_{b \in {\mathbf B}} c'(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert  \pmod 2.
\]
 and the two orbits ${\mathcal O}_{\mathbf c}$  and ${\mathcal O}_{{\mathbf c}'}$ are not in the same $SO(V)$-orbit, but they are in the same $O(V)$-orbit because they both have the same partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ corresponding  to their Jordan type.  This means that there exists $g_3X_{\mathbf c} g_3^{-1} = X_{{\mathbf c}'}$ with $g_3 \in O(V)$ and $\det(g_3) = -1$.  Consequently we have that $g_3 T_{\mathbf c}(L({\mathbf c})) g_3^{-1} = T_{{\mathbf c}'}(L({\mathbf c}')$ with $g_3 \in O(V)$ and $\det(g_3) = -1$.  One of these maximal isotropic subspaces, say $T_{\mathbf c}(L({\mathbf c}))$ is in the $SO(V)$-orbit of $L_{J_+}$ and the other $T_{{\mathbf c}'}(L({\mathbf c}'))$  is not in the $SO(V)$-orbit of $L_{J_+}$. By the proof of lemma~\ref{L:ConditionSO(V)orbit}, we must have
 \[
\sum_{b \in {\mathbf B}} c(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert \equiv 0 \pmod 2
\]
and 
\[
\sum_{b \in {\mathbf B}} c'(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert \equiv 1 \pmod 2.
\]
But this contradicts our hypothesis. So the two $G^{\iota}$-orbits ${\mathcal O}_{\mathbf c}$  and ${\mathcal O}_{{\mathbf c}'}$ are in the same $G$-orbit.

\end{proof}

