\]
while if the orbit ${\mathcal O}$ has overlapping ${\mathcal I}$-box supports,  $b = b(i_1, j_1, k_1) \in {\mathcal O}$, $1 \leq j \leq {\mathbf c}({\mathcal O})$  and $i \in Supp(b)$, then we have 
\[
E_{\mathbf c}(v_i^j(b)) = \begin{cases} {\phantom -} 0, &\text{if $i = \max(Supp(b))$;}\\ {\phantom -} v_{i + 2}^j(b), &\text{if $i \ne \max(Supp(b))$ and $i > 0$;}\\  -v_{i + 2}^j(b), &\text{if  $i < 0$;}\\   {\phantom -}  v_2^j(b), &\text{if $i = 0$, $\max(Supp(b)) > 0$ and $b$ is below the principal}\\ &\text{diagonal;}\\ {\phantom -}  v_2^j(b), &\text{if $i = 0$, $\max(Supp(b)) > 0$ and $b$ is above the principal}\\ &\text{diagonal;}  \end{cases}
\]
Note that if $b \in {\mathbf B}$ is such that $c(b) > 0$, then $b$ is not on the principal diagonal as noted in \ref{SS:IoddGGiotaConjugaisonTotallyEven}


(a) We have that $b' = b(i', j', 0)$ with $i', j' \in {\mathcal I}$, $i' \geq 0 \geq j'$ and $(i' + j') > 0$. Because the elements of  ${\mathcal I}$ are even integers, we have that $(i' + j') \geq 2$.  We have that $i'' \in Supp^{top}(b')$ if and only if 
\[
i' \geq i'' \geq \frac{(i' + j' + 2)}{2} \geq 2 \quad \text{ and } \quad 0 \not \in Supp^{top}(b').
\]
We have that $\tau(b') = b(-j', -i', 0)$. We have that $i'' \in Supp(\tau(b'))$ if and only if 
\[
-j' \geq i'' \geq \frac{(-j' - i' + 2)}{2}. 
\]
But $0 \geq j'$ implies that $-j' \geq 0$. $(i' + j') \geq 2$ implies that  $0 \geq (-j' - i' + 2)$ and $0 \in Supp^{top}(\tau(b'))$.

(b) The proof is similar to the proof in lemma~\ref{L:MaximalIsotropicV(c)} and is left to the reader.

(c) We have that $(E'_{\mathbf c})^{r} = S_{{\mathcal O}'} E_{\mathbf c}^{r} S_{{\mathcal O}'}^{-1}$ for all integers $r\in {\mathbb N}$.  From this,  we get easily that  
\[
\ker((E'_{\mathbf c})^{2k}) = \ker(S_{{\mathcal O}'}E_{\mathbf c}^{2k} S_{{\mathcal O}'}^{-1}) =  S_{{\mathcal O}'}(\ker(E_{\mathbf c}^{2k}))
\]
 and 
 \[
 (E'_{\mathbf c})^k [\ker((E'_{\mathbf c})^{2k})] = S_{{\mathcal O}'}E_{\mathbf c}^{k} S_{{\mathcal O}'}^{-1}[S_{{\mathcal O}'}(\ker(E_{\mathbf c}^{2k}))] = S_{{\mathcal O}'} (E_{\mathbf c}^k[\ker(E_{\mathbf c}^{2k})])
 \]
 Thus ${}''L({\mathbf c}) = S_{{\mathcal O}'}({}'L({\mathbf c}))$.  Because $S_{{\mathcal O}'}:V({\mathbf c}) \rightarrow V({\mathbf c})$ is an ${\mathcal I}$-graded isomorphism such that 
 $\langle S_{{\mathcal O}'}(u),  S_{{\mathcal O}'}(v)\rangle_{\mathbf c} = \langle u,  v\rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$, then ${}''L({\mathbf c}) $ is a maximal isotropic subspace of $V({\mathbf c})$ and 
 \[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{S_{{\mathcal O}'}(v_i^j(b)) \mid i \in Supp^{top}(b), 1 \leq j \leq c(b)\}
\]
is a basis of  ${}''L({\mathbf c})$.  

For the latter description of this basis, we need to note that $S_{{\mathcal O}'}$ is the identity on all the vectors except for $v_0^{c(b')}(b')$ and $v_0^{c(b')}(\tau(b'))$. By (a), $v_0^{c(b')}(b') \not\in {}'L({\mathbf c})$ and $v_0^{c(b')}(\tau(b')) \in {}'L({\mathbf c})$. Thus we get that $S_{{\mathcal O}'}(v_0^{c(b')}(b')) = v_0^{c(b')}(\tau(b')) \not\in {}''L({\mathbf c})$ and  $S_{{\mathcal O}'}(v_0^{c(b')}(\tau(b')) = v_0^{c(b')}(b') \in {}''L({\mathbf c})$. This concludes the proof of (c). 
\end{proof}

The following lemma is probably well-known. Its proof is included for completeness. 

%lemma 6.14
\begin{lemma}\label{L:ConditionSO(V)orbitOdd}
Let ${\mathcal I}$ be odd and using the notations of \ref{S:SetUpOddOrtho} and \ref{SS:IoddGGiotaConjugaisonTotallyEven}, consider the set ${\mathcal J}$ of subsets $J$ of $\{(i, j) \in {\mathcal I} \times {\mathbb N} \mid 1 \leq j \leq \delta_i\}$ such that 
\begin{itemize}
\item if $(i, j),  (i', j) \in J$ are such that $i, i' \ne 0$, then $i + i' \ne 0$ and
\item if $(0, j), (0, j') \in J$, then $j + j' \ne (\delta_0 + 1)$,
\end{itemize}
and moreover $J$ is maximal among such subsets.
\begin{enumerate}[\upshape (a)]
\item If $J \in {\mathcal J}$, then $2 \vert J \vert = \dim(V)$.
\item If $J \in {\mathcal J}$, then the subspace $L_J$ of $V$ spanned by $\{u_{i, j} \mid  (i, j) \in J\}$ is a maximal isotropic subspace of $V$.
\item Let  $J, J' \in {\mathcal J}$. Then the two maximal isotropic subspaces $L_J$ and $L_{J'}$ of $V$ are in the same $SO(V)$-orbit if and only if 
\begin{multline*}
 \vert \{(i, j) \in J \mid i < 0\} \cup \{(0, j) \in J \mid \delta'''_0 < j\} \vert  \equiv \\ \vert \{(i, j) \in J' \mid i < 0\}\cup \{(0, j) \in J' \mid \delta'''_0 < j\} \vert  \pmod 2.
\end{multline*}
Recall that $2\delta'''_0 = \delta_0$.
\end{enumerate}
\end{lemma}
\begin{proof}
(a) From our notation in \ref{S:SetUpOddOrtho}, we have that 
\[
\dim(V) = \sum_{i \in {\mathcal I}} \delta_i =  \sum_{i \in {\mathcal I}}\vert \{ (i, j) \in {\mathcal I} \times {\mathbb N} \mid 1 \leq j \leq \delta_i\}\vert
\]
If $(i , j) \in {\mathcal I} \times {\mathbb N}$ is such that $1 \leq j \leq \delta_i$, then,  by the maximality of $J$, we have if $i \ne 0$, that exactly one and only one of $(i, j)$, $(-i, j)$ belongs to $J$, while if $i = 0$,  exactly one and only one of $(0, j)$, $(0, (\delta_0 + 1 - j))$ belongs to $J$. Consequently  $2 \vert J \vert = \dim(V)$. 

(b) First we will show that $L_J$ is isotropic. From our hypothesis on the basis as defined in \ref{S:SetUpOddOrtho}, we have that $\langle u_{i, j}, u_{i', j'}\rangle \ne 0$ if and  only if either $i, i' \ne 0$, $j = j'$ and $i + i' = 0$ or $i = i' = 0$, $j + j' = (\delta_0 + 1)$ when $(i, j), (i', j') \in {\mathcal I} \times {\mathbb N}$ are such that $1 \leq j \leq \delta_i$ and $1 \leq j' \leq \delta_{i'}$. But by our hypothesis on $J$, when $(i, j), (i', j') \in J$, then  $\langle u_{i, j}, u_{i', j'} \rangle = 0$. Otherwise we would have either $i, i' \ne 0$, $j = j'$ and $i + i' = 0$ or $i = i' = 0$ and $j + j' = \delta_0$. But this is impossible for two elements of $J$.  So $L_J$ is isotropic. Because $2\dim(L_J) = \dim(V)$ by (a), we get that $L_J$ is maximal. 

(c) We first need to remind some facts. Let 
\[
J_+ = \{(i, j) \in {\mathcal I} \times {\mathbb N} \mid i > 0, 1 \leq j \leq \delta_i\} \cup \{(0, j) \in {\mathcal I} \times {\mathbb N} \mid  1 \leq j \leq \delta'''_0\}.
\]
Clearly $J_+ \in {\mathcal J}$.  Note that if $g \in O(V)$ is such that $g(L_{J_+}) = L_{J_+}$, then $g \in SO(V)$.  In fact by considering the matrix of $g$ in the basis $\{u_{i, j} \mid i \in {\mathcal I},  1 \leq j \leq \delta_i\}$ ordered properly, i.e. the basis elements corresponding to the indexes in $J_+$ and then the one  corresponding to the indexes in the complement of $J_+$ in   $\{(i, j) \in {\mathcal I} \times {\mathbb N} \mid 1 \leq j \leq \delta_i\} $ in the right  order, we get that this matrix is of the form 
\[
\begin{bmatrix} A & B\\ 0 & D\end{bmatrix} \quad \text{ such that } \quad  \begin{bmatrix} A & B\\ 0 & D\end{bmatrix}^T \begin{bmatrix} 0 & I\\ I & 0\end{bmatrix} \begin{bmatrix} A & B\\ 0 & D\end{bmatrix} = \begin{bmatrix} 0 & I\\ I & 0\end{bmatrix}.
\]
Consequently $A^TD = I$ ,  $\det(D) = (\det(A))^{-1}$ and $g \in SO(V)$. 

Let $g_J: V \rightarrow V$ denote the unique linear transformation such that
\[
g_J(u_{i, j}) = \begin{cases} u_{i, j}, &\text{if $i > 0$ and $(i, j) \in J$:}\\  u_{-i, j}, &\text{if $i >0$ and $(i, j) \not \in J$;}\\  u_{i, j}, &\text{if $i = 0$, $1 \leq j \leq \delta'''_0$ and $(i, j) \in J$;}\\  u_{i, (\delta_0 + 1 - j)}, &\text{if $i = 0$, $1 \leq j \leq \delta'''_0$ and $(i, j) \not \in J$;}\\  u_{-i, j}, &\text{if $i < 0$ and $(i, j) \in J$;} \\ u_{i, j}, &\text{if $i < 0$ and $(i, j) \not\in J$;}\\ u_{i, (\delta_0 + 1 - j)}, &\text{if $i = 0$, $(\delta'''_0 + 1) \leq j \leq \delta_0$ and $(i, j) \in J$;}\\  u_{i, j}, &\text{if $i = 0$, $(\delta'''_0 + 1) \leq j \leq \delta_0$ and $(i, j) \not\in J$.}
\end{cases}
\]
We can now show that $g_J \in O(V)$.  For this, we have to consider the following two situations:
\begin{itemize}
\item $\langle u_{i_1, j_1}, u_{i_2, j_2}\rangle$ and $\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2}) \rangle$ whenever $i_1, i_2 \in {\mathcal I}$, with $i_1, i_2 \ne 0$,  $1 \leq j_1 \leq \delta_{i_1}$ and $1 \leq j_2 \leq \delta_{i_2}$;
\item $\langle u_{0, j_1}, u_{0, j_2}\rangle$ and $\langle g_J(u_{0, j_1}), g_J(u_{0, j_2}) \rangle$ whenever  $1 \leq j_1 \leq \delta_0$ and $1 \leq j_2 \leq \delta_0$.
\end{itemize}

We will now consider the first case:  $i_1, i_2 \in {\mathcal I}$ with $i_1, i_2 \ne 0$,  $1 \leq j_1 \leq \delta_{i_1}$ and $1 \leq j_2 \leq \delta_{i_2}$,   we must consider $\langle u_{i_1, j_1}, u_{i_2,j_2}\rangle$ and $\langle g_J(u_{i_1, j_1}), g_J(u_{i_2,j_2)}\rangle$.  We have 
\[
\langle u_{i_1, j_1}, u_{i_2, j_2}\rangle = \begin{cases} 1, &\text{ if $j_1 = j_2$ and $i_1 + i_2 = 0$;}\\ 0, &\text{otherwise.} \end{cases}
\]

If $j_1 \ne j_2$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2}) \rangle = \langle u_{i'_1, j_1}, u_{i'_2, j_2}\rangle = 0, 
\]
where $i'_1 \in \{i_1, -i_1\}$ and $i'_2  \in \{i_2, -i_2\}$, because $j_1 \ne j_2$.  

If $j_1 = j_2$ and $i_1 + i_2 = 0$, then we can assume by symmetry  that $i_1 > 0$ and $i_2 = -i_1 < 0$. Moreover $(i_1, j_1) \in J$ if and only if $(i_2, j_2) \not\in J$. Thus 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle = \begin{cases} \langle u_{i_1, j_1}, u_{i_2, j_2} \rangle, &\text{if $(i_1, j_1) \in J$;}\\  \langle u_{-i_1, j_1}, u_{-i_2, j_2} \rangle, &\text{if $(i_1, j_1) \not\in J$;} \end{cases} \quad = 1.
\]

If $j_1 = j_2$, $i_1 + i_2 \ne 0$ and  $i _1 - i_2 \ne 0$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle = \langle u_{i'_1, j_1}, u_{i'_2, j_2}\rangle = 0
\]
because $i'_1 \in \{i_1, -i_1\}$, $i'_2 \in \{i_2, -i_2\}$ and $i'_1 + i'_2 \ne 0$ from our hypothesis.

Finally if $j_1 = j_2$, $i_1 + i_2 \ne 0$ and $i_1 = i_2$, then 
\[
\langle g_J(u_{i_1, j_1}), g_J(u_{i_2, j_2})\rangle  =  \langle g_J(u_{i_1, j_1}), g_J(u_{i_1, j_1})\rangle = \langle u_{i'_1, j_1}, u_{i'_1, j_1}\rangle = 0
\]
where  $i'_1 \in \{i_1, -i_1\}$. 

We will now consider the second case. If  $1 \leq j_1, j_2 \leq \delta_0$, then we must consider $\langle u_{0, j_1}, u_{0, j_2}\rangle$ and $\langle g_J(u_{0, j_1}), g_J(u_{0, j_2}) \rangle$. We have 
\[
\langle u_{0, j_1}, u_{0, j_2}\rangle = \begin{cases} 1, &\text{ if $j_1 + j_2 = (\delta_0 + 1)$;}\\ 0, &\text{otherwise;} \end{cases}
\]
If $\langle u_{0, j_1}, u_{0, j_2}\rangle = 1$,  we cannot have both $j_1 \geq (\delta'''_0 + 1)$ and $j_2 \geq  (\delta'''_0 + 1)$, because otherwise $(j_1 + j_2) \geq (\delta_0 + 2) > (\delta_0 + 1)$. Similarly we cannot have both $1 \leq j_1 \leq \delta'''_0$ and  $1 \leq j_2 \leq \delta'''_0$, because otherwise $(j_1 + j_2) \leq  2\delta'''_0 < (\delta_0 + 1)$.  Consequently we can assume, using symmetry,  that $1 \leq j_1 \leq \delta'''_0$ and $(\delta'''_0 + 1) \leq j_2 \leq \delta_0$ when  $\langle u_{0, j_1}, u_{0, j_2}\rangle = 1$. 

So when $\langle u_{0, j_1}, u_{0, j_2}\rangle = 1$, i.e $(j_1 +j_2) = (\delta_0 + 1)$, we have that $(0, j_1) \in J$ if and only if $(0, j_2) = (0, (\delta_0 + 1 - j_1)) \not \in J$
\[
g_J(u_{0, j_1}) = \begin{cases} u_{0, j_1}, &\text{if $(0, j_1) \in J$;}\\ u_{0, (\delta_0 + 1 - j_1)}, &\text{if $(0, j_1) \not\in J$;}\end{cases} 
\]
and
\[
g_J(u_{0, j_2}) = \begin{cases} u_{0, (\delta_0 + 1 - j_2)}, &\text{if $(0, j_2) \in J$;}\\ u_{0, j_2}, &\text{if $(0, j_2) \not\in J$.}\end{cases}
\]
Thus
\[
\langle g_J(u_{0, j_1}),  g_J(u_{0, j_2}) \rangle = \begin{cases} \langle u_{0, j_1}, u_{0, j_2} \rangle &\text{if $(0, j_1) \in J$;}\\   \langle u_{0, \delta_0 + 1 -  j_1}, u_{0,\delta_0 + 1 -  j_2} \rangle &\text{if $(0, j_1) \not\in J$;} \end{cases}\quad  = 1
\]
because $j_1 + j_2 = \delta_0 + 1$. 

If $\langle g_J(u_{0, j_1}),  g_J(u_{0, j_2}) \rangle  = \langle u_{0, j'_1}, u_{0, j'_2} \rangle = 1$, where $j'_1 \in \{j_1, (\delta_0 + 1 - j_1)\}$ and  $j'_2 \in \{j_2, (\delta_0 + 1 - j_2)\}$, then $j'_1 + j'_2 = (\delta_0 + 1)$. We thus have four cases to consider: either $j'_1 = j_1$, $j'_2 = j_2$ with $j_1 + j_2 = (\delta_0 + 1)$ or $j'_1 = (\delta_0 + 1 - j_1)$, $j'_2 = (\delta_0 + 1 - j_2)$ with $j_1 + j_2 = (\delta_0 + 1)$ or  $j'_1 =  j_1$, $j'_2 = (\delta_0 + 1 - j_2)$ with $j_1 =  j_2$ or $j'_1 = (\delta_0 + 1 - j_1)$, $j'_2 = j_2$ with $j_1 = j_2$.  

If $j_1 = j_2$, then we get that 
\[
\langle g_J(u_{0, j_1}), g_J(u_{0, j_2})\rangle = \begin{cases} \langle u_{0, j_1}, u_{0, j_1}\rangle, &\text{if $1 \leq j_1 \leq \delta'''_0$ and $(0, j_1) \in J$;} \\ \langle u_{0, (\delta_0 + 1 -  j_1)}, u_{0, (\delta_0 + 1 - j_1)}\rangle, &\text{if $1 \leq j_1 \leq \delta'''_0$ and $(0, j_1) \not \in J$;} \\
 \langle u_{0, (\delta_0 + 1 - j_1)}, u_{0, (\delta_0 + 1 - j_1)}\rangle, &\text{if $(\delta'''_0 + 1) \leq j_1 \leq \delta_0$}\\ &\text{and $(0, j_1) \in J$;} \\
 \langle u_{0,  j_1}, u_{0, j_1}\rangle, &\text{if $(\delta'''_0 + 1) \leq j_1 \leq \delta_0$}\\ &\text{and $(0, j_1) \not\in J$.} 
\end{cases}
\]
So if $j_1 = j_2$, we get that $\langle g_J(u_{0, j_1}), g_J(u_{0, j_2})\rangle = 0$ contrary to our hypothesis that $\langle g_J(u_{0, j_1}),  g_J(u_{0, j_2}) \rangle  = 1$.  

We are left with the two cases:  either $j'_1 = j_1$, $j'_2 = j_2$ with $j_1 + j_2 = (\delta_0 + 1)$ or $j'_1 = (\delta_0 + 1 - j_1)$, $j'_2 = (\delta_0 + 1 - j_2)$ with $j_1 + j_2 = (\delta_0 + 1)$. Thus we have that $\langle g_J(u_{0, j_1}), g_J(u_{0, j_2})\rangle = \langle u_{0, j_1}, u_{0, j_2}\rangle = 1$.


This completes the proof that $g_J \in O(V)$.   Note also that we have $g_J(L_{J_+}) =L_J$, because we only have to consider either the basis elements $u_{i, j}$ for $i > 0$ or the basis elements $u_{0, j}$ for $1 \leq j \leq \delta'''_0$. In the first  case,  if $(i, j) \not\in J$,  we get that $(-i, j) \in J$ and 
\[
g_J(u_{i, j}) =  \begin{cases} u_{i, j} \in L_J, &\text{if $i > 0$ and $(i, j) \in J$:}\\  u_{-i, j} \in L_J, &\text{if $i >0$ and $(i, j) \not \in J$;}
\end{cases}
\]
and, in the second case,  if  $(0, j) \not \in J$,  we get that $(0, (\delta_0 + 1 - j)) \in J$ and
\[
g_J(u_{0, j}) =  \begin{cases} u_{0, j} \in L_J, &\text{if $1 \leq j \leq \delta'''_0$ and $(0, j) \in J$;}\\  u_{0, (\delta_0 + 1 - j)} \in L_J, &\text{if $1 \leq j \leq \delta'''_0$ and $(i, j) \not \in J$.}
\end{cases}
\]

We can now compute the determinant of the matrix of $g_J$ relative to the basis $\{u_{i, j} \mid i \in {\mathcal I}, 1 \leq j \leq \delta_i\}$ where we consider first the basis elements $u_{i, j}$ for $i \in {\mathcal I}$, $i > 0$, $1 \leq j \leq \delta_i$,  secondly the basis elements $u_{0, j}$ for $1 \leq j \leq \delta'''_0$   and then thirdly the basis element $u_{-i, j}$   for $i \in {\mathcal I}$, $i > 0$, $1 \leq j \leq \delta_i$ and finally the basis elements $u_{0, (\delta_0 + 1 - j)}$ for $1 \leq j \leq \delta'''_0$.  Using the Laplace expansion of $\det(g_J)$ and using recursion, we get easily that 
\[
\det(g_J) = (-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert + \vert\{(0, j) \in J \mid \delta'''_0 < j\}\vert}
\]
If $g \in O(V)$ and $g(L_{J_+}) = L_J$, then $\det(g) = (-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert + \vert\{(0, j) \in J \mid \delta'''_0 < j\}\vert}$, because 
\[
g(L_{J_+}) = L_J = g_J(L_{J_+})  \quad \Rightarrow \quad g^{-1}_Jg(L_{J_+}) =L_{J_+} \quad \text{ and } \quad g^{-1}_Jg \in SO(V)
\]
and $\det(g) = \det(g_J)$. 

We  complete the proof of (c).  If $L_J$ and $L_{J'}$ are in the same $SO(V)$-orbit, then they are both in the $SO(V)$-orbit of $L_{J_+}$ or both are not in the $SO(V)$-orbit of $L_{J_+}$. Thus 
\[
(-1)^{\vert \{(i, j) \in J \mid i < 0\}\vert + \vert\{(0, j) \in J \mid \delta'''_0 < j\}\vert} = (-1)^{\vert \{(i, j) \in J' \mid i < 0\}\vert + \vert\{(0, j) \in J' \mid \delta'''_0 < j\}\vert},  
\]
 \begin{multline*}
 \vert \{(i, j) \in J \mid i < 0\}\vert +  \vert\{(0, j) \in J \mid \delta'''_0 < j\}\vert  \equiv\\  \vert \{(i, j) \in J' \mid i < 0\}\vert +  \vert\{(0, j) \in J' \mid \delta'''_0 < j\}\vert \pmod 2.
 \end{multline*}  

 Conversely if 
 \begin{multline*}
 \vert \{(i, j) \in J \mid i < 0\}\vert +  \vert\{(0, j) \in J \mid \delta'''_0 < j\}\vert  \equiv\\  \vert \{(i, j) \in J' \mid i < 0\}\vert +  \vert\{(0, j) \in J' \mid \delta'''_0 < j\}\vert \pmod 2,
 \end{multline*}  
then we get that $L_J$ and $L_{J'}$ are both in the $SO(V)$-orbit of $L_{J_+}$ or both are not in the $SO(V)$-orbit of $L_{J_+}$.  Because there are exactly two $SO(V)$-orbits on the set of maximal isotropic subspaces of $V$, we get that $L_J$ and $L_{J'}$ are in the same $SO(V)$-orbit. 

\end{proof}

%lemma 6.15
\begin{lemma}\label{L:SO(V)OrbitSplittingEvenConjugacyClass}
Using the notation of \ref{SS:IoddGGiotaConjugaisonTotallyEven},  of lemma~\ref{L:MaxIsotropicSubspaceOdd} and consider the ${\mathcal I}$-graded isomorphism $T_{\mathbf c}: V({\mathbf c}) \rightarrow V$ defined in \ref{SS:IsomorphismV(c)andVOddCase} such that $\langle T_{\mathbf c}(u), T_{\mathbf c}(v)\rangle = \langle u, v \rangle_{\mathbf c}$ for all $u, v \in V({\mathbf c})$.  Then both subspaces $T_{\mathbf c}({}'L({\mathbf c}))$ and $T_{\mathbf c}({}''L({\mathbf c}))$ of $V$ are maximal isotropic subspaces of $V$ and these subspaces are not in the same $SO(V)$-orbit. Consequently the $G^{\iota}$-orbits ${}'{\mathcal O}_{\mathbf c}$  and ${}''{\mathcal O}_{\mathbf c}$ are not in the same $G$-orbit. Here $G = SO(V)$. 
\end{lemma}
\begin{proof}
As we saw in lemma~\ref{L:MaxIsotropicSubspaceOdd}, both ${}'L({\mathbf c})$ and  ${}''L({\mathbf c})$ are maximal isotropic subspaces of $V({\mathbf c})$, we get easily that $T_{\mathbf c}({}'L({\mathbf c}))$ and $T_{\mathbf c}({}''L({\mathbf c}))$ of $V$ are maximal isotropic subspaces of $V$. 

Let $X_{\mathbf c} = T_{\mathbf c} E_{\mathbf c} T_{\mathbf c}^{-1}: V \rightarrow V$ and $X'_{\mathbf c} = T_{\mathbf c} S_{{\mathcal O}'} E_{\mathbf c} S^{-1}_{{\mathcal O}'}T_{\mathbf c}^{-1}: V \rightarrow V$ as in the proof of proposition~\ref{P:OrbitSplittingSO}  (c).  As we have shown ${}'{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X'_{\mathbf c}$.  We get easily that $T_{\mathbf c}({}'L({\mathbf c}))$ is equal to the subspace 
\[
X_{\mathbf c}[\ker(X^2_{\mathbf c})] + X^2_{\mathbf c}[\ker(X^4_{\mathbf c})] + \dots + X^k_{\mathbf c}[\ker(X^{2k}_{\mathbf c})] + \dots
\]
and it is spanned by  
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{ T_{\mathbf c}(v_i^s(b)) \mid   i \in Supp^{top}(b) \text{ and  } 1 \leq s \leq c(b)\}.
\]

From our definition of $T_{\mathbf c}$, we get that this set is 
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{u_{i, j} \mid i \in Supp^{top}(b) \text{ and } j \in J_i(b) \}
\]
where $J_i(b)$ is equal to
\[
 \begin{cases} \{1 \leq j \leq \delta_i \mid u_{i, j} = T_{\mathbf c}(v_i^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i \ne 0$;}\\ \\ \{1 \leq j \leq \delta'''_0 \mid  u_{0, j} = T_{\mathbf c}(v_0^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i = 0$ and $b \in {\mathbf B}^+$;}\\ \\ \{(\delta'''_0 + 1 )\leq j \leq \delta_0 \mid  u_{0, j} = T_{\mathbf c}(v_0^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i = 0$ and $b \in {\mathbf B}^-$.} \end{cases}
\]
For all $i \in {\mathcal I}$ and $b, b' \in {\mathbf B}$,   note that $\vert J_i(b) \vert = c(b)$ and if $b \ne b'$  are two distinct ${\mathcal I}$-boxes such that $i \in Supp(b) \cap Supp(b')$, then $J_i(b) \cap J_i(b') = \emptyset $. Because ${}'L({\mathbf c})$ is a maximal isotropic subspace of $V({\mathbf c})$, we get that 
\[
J({\mathbf c}) = \coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{(i, j) \in {\mathcal I} \times {\mathbb N} \mid   i \in Supp^{top}(b) \text{ and }  j \in J_i(b)\} \in {\mathcal J}
\]
and $T_{\mathbf c}({}'L({\mathbf c})) = L_{J({\mathbf c})}$ with the notation of lemma~\ref{L:ConditionSO(V)orbitOdd}. 


Similarly $T_{\mathbf c}({}''L({\mathbf c}))$ is equal to the subspace 
\[
X'_{\mathbf c}[\ker((X')^2_{\mathbf c})] + (X')^2_{\mathbf c}[\ker((X')^4_{\mathbf c})] + \dots + (X')^k_{\mathbf c}[\ker((X')^{2k}_{\mathbf c})] + \dots
\]
and it is spanned by  
\[
\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{ T_{\mathbf c}(S_{{\mathcal O}'}(v_i^s(b))) \mid   i \in Supp^{top}(b) \text{ and  } 1 \leq s \leq c(b)\}.
\]

Because of  lemma~\ref{L:MaxIsotropicSubspaceOdd} (c), we can be more precise about this last set.  It is equal to 
\begin{multline*}
\left[\left[\coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{ T_{\mathbf c}(v_i^s(b)) \mid  i \in Supp^{top}(b) \text{ and  } 1 \leq s \leq c(b)\}\right]  \setminus  \{T_{\mathbf c}(v_0^{c(b')}(\tau(b'))) \} \right]\\ \cup \{T_{\mathbf c}(v_0^{c(b')}(b'))\}
\end{multline*}

There is a unique ${\widehat {j}} \in [1, \delta'''_0]$ such that  $T_{\mathbf c}(v_0^{c(b')}(b')) = u_{0, {\widehat j}}$, because of our definition of $T_{\mathbf c}$ and the fact that $b' \in {\mathbf B}^+$.  Consequently $T_{\mathbf c}(v_0^{c(b')}(\tau(b'))) = u_{0, (\delta_0 + 1 - {\widehat  j}\, )}$ again from our definition of $T_{\mathbf c}$.  

Because of lemma~\ref{L:MaxIsotropicSubspaceOdd} (a), we have that $(0, (\delta_0 + 1 - {\widehat j}\,  ) ) \in J({\mathbf c})$,  $(0,  {\widehat j}\,  ) \not \in J({\mathbf c})$ and  
\[
{}'J({\mathbf c}) = \left[\left[J({\mathbf c}) \setminus \{(0, (\delta_0 + 1 - {\widehat j}\,   ) )\}\right] \cup \{(0, {\widehat j}\,  )\}\right]\in {\mathcal J}.
\]
We also have that  $T_{\mathbf c}({}''L({\mathbf c})) = L_{{}'J({\mathbf c})}$ with the notation of lemma~\ref{L:ConditionSO(V)orbitOdd}. 

Clearly we have that 
\begin{multline*}
\vert \{(i, j) \in J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in J({\mathbf c}) \mid \delta'''_0 < j\} \vert \\  \not \equiv \vert \{(i, j) \in {}'J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in {}'J({\mathbf c}) \mid \delta'''_0 < j\} \vert  \pmod 2
\end{multline*}
and  we get that the maximal isotropic subspaces  $T_{\mathbf c}({}'L({\mathbf c}))$ and $T_{\mathbf c}({}''L({\mathbf c}))$ are not in the same $SO(V)$-orbit because of lemma~\ref{L:ConditionSO(V)orbitOdd} (c).  One consequence of this is that the $G^{\iota}$-orbits  ${}'{\mathcal O}_{\mathbf c}$  and ${}''{\mathcal O}_{\mathbf c}$ are not in the same $G$-orbit. 

\end{proof}

%notation 6.16
\begin{notation}
Let $\vert {\mathcal I} \vert$ be odd and  $G$ be the reductive group $SO(V)$ as in \ref{S:SetUpOddOrtho}. Consider the $G^{\iota}$-orbits   ${}'{\mathcal O}_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$ as defined in proposition~\ref{P:OrbitSplittingSO} (c) and its proof,  whose partition corresponding to their Jordan type is the totally even partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$, where  ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ is a coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$: the symmetric function associated respectively to ${\mathbf c}$.  We will denote 
\[
 {}'\varXi({}'{\mathcal O}_{\mathbf c}) =  \sum_{b \in {\mathbf B}} c(b) \vert \{i \in Supp^{top}(b) \mid i < 0\}\vert  + \sum_{\substack{ b \in {\mathbf B}^-\\ 0 \in Supp^{top}(b)}} c(b)
\]
and is called the {\it parity of the orbit} ${}'{\mathcal O}_{\mathbf c}$.  Recall that ${\mathbf B}^-$ is the set of ${\mathcal I}$-boxes strictly below the principal diagonal.  We will say that the $G^{\iota}$-orbit ${}'{\mathcal O}_{\mathbf c}$ is even (respectively odd) if ${}'\varXi({}'{\mathcal O}_{\mathbf c})$ is even (respectively odd).

We will denote  ${}''\varXi({}''{\mathcal O}_{\mathbf c}) = {}'\varXi({}'{\mathcal O}_{\mathbf c})  - 1$ and it is called the {\it parity of the orbit} ${}''{\mathcal O}_{\mathbf c}$.   Similarly we will say that the $G^{\iota}$-orbit ${}''{\mathcal O}_{\mathbf c}$ is even (respectively odd) if ${}''\varXi({}''{\mathcal O}_{\mathbf c})$ is even (respectively odd).

By lemma~\ref{L:SO(V)OrbitSplittingEvenConjugacyClass}, we get that the $G^{\iota}$-orbit ${}'{\mathcal O}_{\mathbf c}$ is even (respectively odd) if and only if ${}''{\mathcal O}_{\mathbf c}$ is odd (respectively even).  We will denote by ${\mathcal O}^{even}_{\mathbf c}$ (respectively ${\mathcal O}^{odd}_{\mathbf c}$): the only $G^{\iota}$-orbit between ${}'{\mathcal O}_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$ that is even (respectively odd). 
\end{notation}

%proposition 6.17
\begin{proposition}
Let $G$ be the reductive group $SO(V)$  as in \ref{S:SetUpOddOrtho} where $\vert {\mathcal I} \vert$ is odd and let ${\mathcal O}$ and ${\mathcal O}'$  be two $G^{\iota}$-orbits such that ${\mathcal O} \in \{ {\mathcal O}^{even}_{\mathbf c}, {\mathcal O}^{odd}_{\mathbf c} \}$ and   ${\mathcal O}' \in \{ {\mathcal O}^{even}_{{\mathbf c}'}, {\mathcal O}^{odd}_{{\mathbf c}'} \}$,  who both have the same totally even partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots$ corresponding  to their Jordan type, where ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ and ${\mathbf c}':{\mathbf B}/\tau \rightarrow {\mathbb N}$ are both coefficient functions ${\mathbf c}, {\mathbf c}' \in {\mathfrak C}_{\delta}$. Denote by $c:{\mathbf B} \rightarrow {\mathbb N}$ and $c':{\mathbf B} \rightarrow {\mathbb N}$: the symmetric functions associated respectively to ${\mathbf c}$ and ${\mathbf c}'$.  Then these two $G^{\iota}$-orbits  ${\mathcal O}$ and  ${\mathcal O}' $ are in the same $G$-orbit if and only if they have the same parity.  In other words,  ${\mathcal O}$ and  ${\mathcal O}' $ are in the same $G$-orbit if and only if  either (${\mathcal O} = {\mathcal O}^{even}_{\mathbf c}$ and ${\mathcal O}' = {\mathcal O}^{even}_{{\mathbf c}'}$) or (${\mathcal O} = {\mathcal O}^{odd}_{\mathbf c}$ and ${\mathcal O}' = {\mathcal O}^{odd}_{{\mathbf c}'}$).
\end{proposition}
%proof
\begin{proof}
The proof is very similar to the one for proposition~\ref{P:TotallyEvenOrbitSOIEvenCase}. We will use the same notation as in the lemma~\ref{L:SO(V)OrbitSplittingEvenConjugacyClass} and its proof.  Let $X_{\mathbf c} = T_{\mathbf c} E_{\mathbf c} T_{\mathbf c}^{-1}: V \rightarrow V$ and $X'_{\mathbf c} = T_{\mathbf c} S_{{\mathcal O}'} E_{\mathbf c} S^{-1}_{{\mathcal O}'}T_{\mathbf c}^{-1}: V \rightarrow V$ as in the proof of proposition~\ref{P:OrbitSplittingSO}  (c).  As we have shown ${}'{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X_{\mathbf c}$ and ${}''{\mathcal O}_{\mathbf c}$ is the $G^{\iota}$-orbit of $X'_{\mathbf c}$. 

As we saw in the proof of lemma~\ref{L:SO(V)OrbitSplittingEvenConjugacyClass}, 
\[
X_{\mathbf c}[\ker(X^2_{\mathbf c})] + X^2_{\mathbf c}[\ker(X^4_{\mathbf c})] + \dots + X^k_{\mathbf c}[\ker(X^{2k}_{\mathbf c})] + \dots
\]
is a maximal isotropic subspace of $V$ and it is equal to $L_{J({\mathbf c})}$ with the notation of lemma~\ref{L:ConditionSO(V)orbitOdd}, where 
\[
J({\mathbf c}) = \coprod_{\substack { b \in {\mathbf B} \\ c(b) \ne 0}} \{(i, j) \in {\mathcal I} \times {\mathbb N} \mid   i \in Supp^{top}(b) \text{ and }  j \in J_i(b)\} \in {\mathcal J}
\]
with $J_i(b)$ being equal to
\[
 \begin{cases} \{1 \leq j \leq \delta_i \mid u_{i, j} = T_{\mathbf c}(v_i^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i \ne 0$;}\\ \\ \{1 \leq j \leq \delta'''_0 \mid  u_{0, j} = T_{\mathbf c}(v_0^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i = 0$ and $b \in {\mathbf B}^+$;}\\ \\ \{(\delta'''_0 + 1 )\leq j \leq \delta_0 \mid  u_{0, j} = T_{\mathbf c}(v_0^s(b)) \text{ for some $1 \leq s \leq c(b)$} \}, &\text{if $i = 0$ and $b \in {\mathbf B}^-$.} \end{cases}
\]

Similarly 
\[
X'_{\mathbf c}[\ker((X')^2_{\mathbf c})] + (X')^2_{\mathbf c}[\ker((X')^4_{\mathbf c})] + \dots + (X')^k_{\mathbf c}[\ker((X')^{2k}_{\mathbf c})] + \dots
\]
is a maximal isotropic subspace of $V$ and it is equal to $L_{{}'J({\mathbf c})}$ with the notation of lemma~\ref{L:ConditionSO(V)orbitOdd}, where 
\[
{}'J({\mathbf c}) = \left[\left[J({\mathbf c}) \setminus \{(0, (\delta_0 + 1 - {\widehat j}\,   ) )\}\right] \cup \{(0, {\widehat j}\,  )\}\right]\in {\mathcal J}.
\]
such that 	${\widehat j}$ being the  unique integer ${\widehat {j}} \in [1, \delta'''_0]$ such that  $T_{\mathbf c}(v_0^{c(b')}(b')) = u_{0, {\widehat j}}$, 


The same thing can done for ${\mathbf c}'$. Let $X_{{\mathbf c}'} = T_{{\mathbf c}'} E_{{\mathbf c}'} T_{{\mathbf c}'}^{-1}: V \rightarrow V$ and $X'_{{\mathbf c}'} = T_{{\mathbf c}'} S_{{\mathcal O}''} E_{{\mathbf c}'} S^{-1}_{{\mathcal O}''}T_{{\mathbf c}'}^{-1}: V \rightarrow V$ as in the proof of proposition~\ref{P:OrbitSplittingSO}  (c).  Note here ${\mathcal O}'' \in {\mathbf B}/\tau$ is defined in an  analoguous way to how  ${\mathcal  O}' \in {\mathbf B}/\tau$ was defined.  ${\mathcal O}''$  is not necessarily equal to ${\mathcal O}'$, because ${\mathbf c}'$ is not necessarily equal to  ${\mathbf c}$.   As we have shown ${}'{\mathcal O}_{{\mathbf c}'}$ is the $G^{\iota}$-orbit of $X_{{\mathbf c}'}$ and ${}''{\mathcal O}_{{\mathbf c}'}$ is the $G^{\iota}$-orbit of $X'_{{\mathbf c}'}$.  So we have $J({\mathbf c}')$ and  ${}'J({\mathbf c}')$. 

If $X_{\mathbf c}$ is in the same $G$-orbit with $X_{{\mathbf c}'}$ (respectively ${}'X_{{\mathbf c}'}$) , then  we have that  the parity of 
\[
\vert \{(i, j) \in J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in J({\mathbf c}) \mid \delta'''_0 < j\} \vert
\]
is equal to the parity of 
\[
\vert \{(i, j) \in J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert 
\]
(respectively 
\[
\vert \{(i, j) \in {}'J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert )
\] 
by lemma~\ref{L:ConditionSO(V)orbitOdd}.  Similarly ${}'X_{\mathbf c}$ is in the same $G$-orbit with $X_{{\mathbf c}'}$ (respectively ${}'X_{{\mathbf c}'}$) , then  we have that  the parity of 
\[
\vert \{(i, j) \in {}'J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in {}'J({\mathbf c}) \mid \delta'''_0 < j\} \vert
\]
is equal to the parity of 
\[
\vert \{(i, j) \in J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert 
\]
(respectively 
\[
\vert \{(i, j) \in {}'J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert )
\] 
Note that if  $X_{\mathbf c}$ is in the same $G$-orbit with $X_{{\mathbf c}'}$ , then ${}'X_{\mathbf c}$ is in the same $G$-orbit with ${}'X_{{\mathbf c}'}$, while  $X_{\mathbf c}$ is in the same $G$-orbit with ${}'X_{{\mathbf c}'}$ , then ${}'X_{\mathbf c}$ is in the same $G$-orbit with $X_{{\mathbf c}'}$ as a consequence of lemma~\ref{L:SO(V)OrbitSplittingEvenConjugacyClass}. Thus ${\mathcal O}^{even}_{\mathbf c}$  is in the same $G$-orbit as  ${\mathcal O}^{even}_{{\mathbf c}'}$ and ${\mathcal O}^{odd}_{\mathbf c}$  is in the same $G$-orbit as  ${\mathcal O}^{odd}_{{\mathbf c}'}$. 


Reciprocally assume that ${\mathcal O} = {\mathcal O}^{even}_{\mathbf c}$,  ${\mathcal O}' = {\mathcal O}^{even}_{{\mathbf c}'}$ and  ${\mathcal O}$ and ${\mathcal O}'$ are not in the same $G$-orbit. Note that they are in the same $O(V)$-orbit, because they both have the same partition $2^{a(2)} 4^{a(4)} 6^{a(6)} \dots $ corresponding to their Jordan type.  ${\mathcal O}$ is either the $G^{\iota}$-orbit of $X_{\mathbf c}$ or the $G^{\iota}$-orbit of ${}'X_{\mathbf c}$, but only one of these two possibilities prevails. We will denote this unique element by $Y_{\mathbf c}$.  Similarly  ${\mathcal O}'$ is either the $G^{\iota}$-orbit of $X_{{\mathbf c}'}$ or the $G^{\iota}$-orbit of ${}'X_{{\mathbf c}'}$, but only one of these two possibilities prevails. We will denote this unique element by $Y_{{\mathbf c}'}$.  Because the two orbits ${\mathcal O}$ and ${\mathcal O}'$ are not in the same $SO(V)$-orbit, but are in the same $O(V)$-orbit,   then there exists an element $g \in O(V)$ such that $\det(g) = -1$ and  $Y_{{\mathbf c}'} = g(Y_{\mathbf c})g^{-1}$.

The maximal isotropic subspace 
\[
Y_{\mathbf c}[\ker(Y^2_{\mathbf c})] + Y^2_{\mathbf c}[\ker(Y^4_{\mathbf c})] + \dots + Y^k_{\mathbf c}[\ker(Y^{2k}_{\mathbf c})] + \dots
\]
is equal to either  $L_{J({\mathbf c})}$  if $Y_{\mathbf c} = X_{\mathbf c}$ or $L_{{}'J({\mathbf c})}$  if $Y_{\mathbf c} = X'_{\mathbf c}$.  We will denote this unique maximal isotropic subspace by $L(Y_{\mathbf c})$. 

Similarly  the maximal isotropic subspace 
\[
Y_{{\mathbf c}'}[\ker(Y^2_{{\mathbf c}'})] + Y^2_{{\mathbf c}'}[\ker(Y^4_{{\mathbf c}'})] + \dots + Y^k_{{\mathbf c}'}[\ker(Y^{2k}_{{\mathbf c}'})] + \dots
\]
is equal to either  $L_{J({{\mathbf c}'})}$  if $Y_{{\mathbf c}'} = X_{{\mathbf c}'}$ or $L_{{}'J({{\mathbf c}'})}$  if $Y_{{\mathbf c}'} = X'_{{\mathbf c}'}$. We will denote this unique maximal isotropic subspace by $L(Y_{{\mathbf c}'})$. 

Consequently we have that $L(Y_{{\mathbf c}'}) = g(L(Y_{\mathbf c}))$,  where $g \in O(V)$ and $\det(g) = -1$ and these maximal isotropic subspaces are not in the same $SO(V)$-orbit. Thus only one of these maximal isotropic subspaces is in the $SO(V)$-orbit of $L_{J^+}$.  If $L(Y_{\mathbf c})$ is in the same $SO(V)$-orbit as $L_{J^+}$ and $L(Y_{{\mathbf c}'})$ is not in the same $SO(V)$-orbit as $L_{J^+}$, then  the parity of 
\[
\vert \{(i, j) \in J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in J({\mathbf c}) \mid \delta'''_0 < j\} \vert
\]
is equal to the parity of 
\[
\vert \{(i, j) \in J^+ \mid i < 0\} \cup \{(0, j) \in J^+ \mid \delta'''_0 < j\} \vert  = 0
\]
if $Y_{\mathbf c} = X_{\mathbf c}$, i.e. it is even, while either 
\[
\vert \{(i, j) \in J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert
\]
is odd if $Y_{{\mathbf c}'} = X_{{\mathbf c}'}$ or  
\[
\vert \{(i, j) \in {}'J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in {}'J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert
\]
is odd if $Y_{{\mathbf c}'} = X'_{{\mathbf c}'}$
and
\[
\vert \{(i, j) \in {}'J({\mathbf c}) \mid i < 0\} \cup \{(0, j) \in {}'J({\mathbf c}) \mid \delta'''_0 < j\} \vert
\]
is equal to the parity of 
\[
\vert \{(i, j) \in J^+ \mid i < 0\} \cup \{(0, j) \in J^+ \mid \delta'''_0 < j\} \vert  = 0
\]
if $Y_{\mathbf c} = X'_{\mathbf c}$, i.e. it is even, while either 
\[
\vert \{(i, j) \in J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert
\]
is odd if $Y_{{\mathbf c}'} = X_{{\mathbf c}'}$ or  
\[
\vert \{(i, j) \in {}'J({{\mathbf c}'}) \mid i < 0\} \cup \{(0, j) \in {}'J({{\mathbf c}'}) \mid \delta'''_0 < j\} \vert
\]
is odd if $Y_{{\mathbf c}'} = X'_{{\mathbf c}'}$. Thus ${\mathcal O}$ has even parity and ${\mathcal O}'$ has odd parity contradicting our hypothesis. 

We can proceed analogously if $L(Y_{\mathbf c})$ is not in the same $SO(V)$-orbit as $L_{J^+}$ and $L(Y_{{\mathbf c}'})$ is in the same $SO(V)$-orbit as $L_{J^+}$.  In this case, ${\mathcal O}$ has odd parity and ${\mathcal O}'$ has even parity contradicting our hypothesis. 
\end{proof}


%section 7
\section{Parabolic and Levi subgroups associated to $G^{\iota}$-orbits  in ${\mathfrak g}_2$.}

%7.1
\subsection{}
Let $m$, $G$, ${\mathfrak g}$, $V$, ${\mathcal I}$, $\oplus_{i \in {\mathcal I}} V_i$, $\delta = (\delta_i)_{i \in {\mathcal I}}$,  ${\mathcal B}$, $\iota$, ${\mathbf B}$ and ${\mathbf B}/\tau$ as in either \ref{S:SetUpAeven} or  \ref{S:SetUpOdd} or \ref{S:SetUpOddOrtho}. More precisely $G$ should be a connected  reductive group. Thus in the situation of  \ref{S:SetUpOdd}, we restrict ourself only to the group $Sp(V)$, while in the situation of  \ref{S:SetUpOddOrtho}, $G$ is  the group $SO(V)$. In the situation of \ref{S:SetUpAeven} , $G$ is already connected.

Using the isomorphism $T_{\mathbf c}:V({\mathbf c}) \rightarrow V$, we can transfer results about the orbit ${\mathcal O}_{\mathbf c}$ in the Lie algebra ${\mathfrak g}_2$ to the orbit of $E_{\mathbf c}$ in the Lie algebra 
\[
{\mathfrak g}(V({\mathbf c})) =  \{Y \in End(V({\mathbf c})) \mid \langle Y(u), v\rangle + \langle u, Y(v)\rangle = 0 \quad \text{ for all $u, v \in V({\mathbf c})$}\}.
\]
In this section and the next, we will describe everything in $V({\mathbf c})$ and in ${\mathfrak g}(V({\mathbf c}))$ rather than in $V$ and ${\mathfrak g}$. 

%7.2
\subsection{} 
In definition~\ref{D:LieHomo}, we have recalled the definition of Lusztig in 5.2 of \cite{L1995} for a parabolic subalgebra ${\mathfrak p}_X$ of ${\mathfrak g}$ and a Levi subalgebra ${\mathfrak l}_X$ of ${\mathfrak p}_X$ associated to an element $X \in {\mathfrak g}_2$. Using the same notation as in definition~\ref{D:LieHomo}, we have that 
\[
{\mathfrak p}_X = \bigoplus_{\begin{subarray}{c} r, r' \in {\mathbb Z} \\ r' \leq r \end{subarray}} {}_r{\mathfrak g}_{r'} \quad \text{ and }  \quad {\mathfrak l}_X = \bigoplus_{\begin{subarray}{c} r, r' \in {\mathbb Z} \\ r' = r \end{subarray}} {}_r{\mathfrak g}_{r'}.
\]

Denote by $P_X$: the parabolic subgroup of $G$ which has ${\mathfrak p}_X$  as Lie algebra, and by $L_X$: the Levi subgroup of $P_X$ whose Lie algebra is ${\mathfrak l}_X$.

%7.3
\subsection{}
For the coefficient function ${\mathbf c} \in {\mathfrak C}_{\delta}$, we have constructed for an $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ (respectively ${\  }'{\mathcal O}_{\mathbf c}$, ${\  }''{\mathcal O}_{\mathbf c}$)  in \ref{N:CCorrespondance}, \ref{N:CCorrespondanceOdd} and \ref{N:CCorrespondanceSpecialOrtho},  a Jacobson-Morozov  triple $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ (respectively $({\ }'E_{\mathbf c}, {\ }'H_{\mathbf c}, {\ }'F_{\mathbf c})$, $({\ }''E_{\mathbf c}, {\ }''H_{\mathbf c}, {\ }''F_{\mathbf c})$).  In this section, we will describe the parabolic subgroup $P_E$  and its Levi subgroup $L_E$ for the element $E = E_{\mathbf c} \in {\mathcal O}_{\mathbf c}$ (respectively $E = {\ }'E_{\mathbf c} \in {\ }'{\mathcal O}_{\mathbf c}$, $E = {\ }''E_{\mathbf c} \in {\ }''{\mathcal O}_{\mathbf c}$).

%Notation 7.4
\begin{notation}\label{N:Basis_Adapted_To_C}
Let ${\mathbf c} \in {\mathfrak C}_{\delta}$ and the associated symmetric function $c: {\mathbf B} \rightarrow {\mathbb N}$.
For each $i \in {\mathcal I}$, recall that $V_i({\mathbf c})$ has the basis 
\[
{\mathcal B}_i = \{ v_{i}^j(b) \in V_i({\mathbf c}) \mid b \in {\mathbf B}, i \in Supp(b), 1 \leq j \leq c(b) \}
\]
is the basis of $V_i({\mathbf c})$. We know how the elements of the  Jacobson-Morozov triple act on the elements of ${\mathcal B}_i$.  

Write 
\[
\Lambda({\mathbf c}) = \{\lambda(b) \in {\mathbb Z} \mid b \in {\mathbf B}, c(b) \ne 0\} = \{\lambda_1 < \lambda_2 < \dots < \lambda_{\ell}\}.
\]
Recall that 
\[
\lambda(b) = \frac{(i + j)}{2} \quad \text{ if $b = b(i, j, k)$ with $i, j \in {\mathcal I}$, $i \geq j$ and $0 \leq k \leq \mu(i, j)$.}
\]

By the symmetry of the function $c$, it is easy to see that $\lambda_s + \lambda_{\ell + 1 - s} = 0$ for all $1 \leq s \leq \ell$.

For $1 \leq r \leq \ell$, denote by $U_r$: the subspace of $V({\mathbf c})$ spanned by the set of basis vectors 
\[
\widehat{\mathcal B}_r = \{ v_i^j(b) \mid b \in {\mathbf B}, 1 \leq j \leq c(b), i \in Supp(b) \text{ and } \lambda(b) = \lambda_r\}
\]
This gives us a direct sum decomposition of $V({\mathbf c})$: $V({\mathbf c}) = U_1 \oplus U_2 \oplus \dots \oplus U_{\ell}$.
\end{notation}

%proposition 7.5
\begin{proposition}\label{P:ParabolicLeviAssociated}
Let $X \in {\mathfrak g}$ and $E = E_{\bf c}$ or ${\  }'E_{\mathbf c}$.  Then 
\begin{enumerate}[\upshape (a)]
\item $X \in {\mathfrak l}_{E}$ if and only if $X(U_r) \subseteq U_r$ for all $r = 1, 2, \dots, \ell$.
\item $X \in {\mathfrak p}_{E}$ if and only if $X(U_1 \oplus U_2 \dots \oplus U_r) \subseteq (U_1 \oplus U_2 \oplus \dots \oplus U_r)$ for all  $r = 1, 2, \dots, \ell$.
\end{enumerate}
\end{proposition}
\begin{proof}
(a) $\Rightarrow)$ Let $X \in {\mathfrak l}_E$ and consider the basis vector $v_i^j(b)$ with $b \in {\mathbf B}$, $1 \leq j \leq c(b)$, $i \in Supp(b)$ and $\lambda(b) = \lambda_r$. We want to prove that $X(v_i^j(b)) \in U_r$. We have that $X = \sum_s X_s$ with $X_s \in {}_s{\mathfrak g}_s$. It is enough to prove the result for $X = X_s$. 

Write 
\[
X(v_i^j(b)) = \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')
\]
where  $\xi_{(b', j', i')} \in {\mathbf k}$ for all $(b', j', i')$ such that  $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ and $i' \in Supp(b')$ and  the sum runs  over these $(b', j', i')$.  If $\xi_{(b', j', i')} \ne 0$, we want to prove that $\lambda(b') = \lambda_r$.

Because $X = X_s$, we have $Ad(\iota(t))X = t^s X$ and  $Ad(\iota'(t))X = t^s X$ for all $t \in {\mathbf k}^{\times}$. Recall that $\iota':{\mathbf k}^{\times} \rightarrow G$ is defined  in definition~\ref{D:LieHomo} and in the proof of proposition~\ref{DimensionFormulaSymplecticOdd}.  We have

\[
\begin{aligned}
Ad(\iota(t))X(v_i^j(b)) &= \iota(t) X( \iota(t^{-1})(v_i^j(b))) = \iota(t) X(t^{-i} v_i^j(b))\\
&= t^{-i} \iota(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(i' - i)} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]

and 

\[
\begin{aligned}
Ad(\iota'(t))X(v_i^j(b)) &= \iota'(t) X( \iota'(t^{-1})(v_i^j(b))) = \iota'(t) X(t^{-h_i(b)} v_i^j(b)) \\
&= t^{-h_i(b)} \iota'(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(h_{i'}(b') - h_i(b))} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]
where both sums  run over $(b', j', i')$ as above.

Because $Ad(\iota'(t))X = Ad(\iota(t)) X = t^sX$ for all $t \in {\mathbf k}^{\times}$, we get that 
\[
t^{(i' - i)} \xi_{(b', j', i')} = t^{(h_{i'}(b') - h_i(b))} \xi_{(b', j', i')} 
\]
for all $t \in {\mathbf k}^{\times}$ and all $(b', j', i')$ where $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ and $i' \in Supp(b')$ . If $\xi_{(b', j', i')} \ne 0$, then $t^{(i' - i)}  = t^{(h_{i'}(b') - h_i(b))}$ for all $t \in {\mathbf k}^{\times}$ and consequently $i' - h_{i'}(b') = i - h_i(b)$. Thus $\lambda(b') = \lambda(b) = \lambda_r$ and $X(U_r) \subseteq U_r$.

$\Leftarrow)$ If $X \in {\mathfrak g}$ is such that $X(U_r) \subseteq U_r$ for all $r = 1, 2, \dots, \ell$, we must show that $X \in {\mathfrak l}_E$. We will first prove that $Ad(\iota(t)) X = Ad(\iota'(t))X$ for all $t \in {\mathbf k}^{\times}$ by computing both sides on the basis vector  $v_i^j(b)$ with $b \in {\mathbf B}$, $1 \leq j \leq c(b)$, $i \in Supp(b)$ and $\lambda(b) = \lambda_r$.

Write 
\[
X(v_i^j(b)) = \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')
\]
where $\xi_{(b', j', i')} \in {\mathbf k}$ for all $(b', j', i')$ such that  $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ and $i' \in Supp(b')$  and the sum runs over these $(b', j', i')$ and $\lambda(b') = \lambda(b) = \lambda_r$. 

\[
\begin{aligned}
Ad(\iota(t))X(v_i^j(b)) &= \iota(t) X \iota(t^{-1})(v_i^j(b)) = \iota(t) X(t^{-i} v_i^j(b)) \\
&= t^{-i} \iota(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(i' - i)} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]

and 

\[
\begin{aligned}
Ad(\iota'(t))X(v_i^j(b)) &= \iota'(t) X \iota'(t^{-1})(v_i^j(b)) = \iota'(t) X(t^{-h_i(b)} v_i^j(b)) \\
&= t^{-h_i(b)} \iota'(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(h_{i'}(b') - h_i(b))} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]
where both sums run over $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ ,  $i' \in Supp(b')$ and $\lambda(b') = \lambda(b) = \lambda_r$. 
Thus if $\xi_{(b', j', i')} \ne 0$ in the above sums, we get that $(i' - h_{i'}(b')) = (i - h_i(b))= \lambda_r$ and $(i' - i) = (h_{i'}(b') - h_i(b))$. Thus we have $Ad(\iota(t))X(v_i^j(b)) = Ad(\iota'(t))X(v_i^j(b)) $ for all basis vectors $v_i^j(b)$.  So $Ad(\iota(t)) X = Ad(\iota'(t))X$ for all $t \in {\mathbf k}^{\times}$. 



We will now prove that $X \in {\mathfrak l}_E$. Write 
\[
X = \sum_{s, s'} {}_sX_{s'} \   \in \  \bigoplus_{s, s'} {}_s{\mathfrak g}_{s'}
\]
where ${}_sX_{s'} \in {}_s{\mathfrak g}_{s'}$ and the sum is over $s, s' \in {\mathbb Z}$ and there is a finite number of summands.  Then 
\[
Ad(\iota(t))X = \sum_{s, s'} Ad(\iota(t)) {}_sX_{s'} = \sum_{s, s'} t^{s'} {}_sX_{s'}
\]
and 
\[
Ad(\iota'(t))X = \sum_{s, s'} Ad(\iota'(t)) {}_sX_{s'} = \sum_{s, s'} t^{s} {}_sX_{s'}.
\]
By the above equality, we get that $t^{s'} = t^s$ for all $t \in {\mathbf k}^{\times}$ and $s' = s$ when ${}_sX_{s'} \ne 0$. Thus $X \in {\mathfrak l}_E$.


(b) $\Rightarrow)$ Let $X \in {\mathfrak p}_E$  and  the basis vector $v_i^j(b)$ with $b \in {\mathbf B}$, $1 \leq j \leq c(b)$, $i \in Supp(b)$ and $\lambda(b) = \lambda_r$, we want to prove that $X(v_i^j(b)) \in U_1 \oplus U_2 \oplus \dots  \oplus U_r$ for all $r = 1, 2, \dots, \ell$. We have 
\[
X = \sum_{\begin{subarray}{c} s, s'\\ s' \leq s\end{subarray}} {}_sX_{s'}  \   \in \  \bigoplus_{\begin{subarray}{c} s, s'\\ s' \leq s\end{subarray} } {}_s{\mathfrak g}_{s'}
\]
 with  ${}_sX_{s'} \in {}_s{\mathfrak g}_{s'}$. It is enough to prove the result for $X = {}_sX_{s'}$.

Write 
\[
X(v_i^j(b)) = \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')
\]
where $\xi_{(b', j', i')} \in {\mathbf k}$ for all $(b', j', i')$ such that  $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ and $i' \in Supp(b')$  and the sum runs over these $(b', j', i')$.   If $\xi_{(b', j', i')} \ne 0$, we want to show that   $\lambda(b')  \leq \lambda_r$. 

Because $X = {}_sX_{s'}$ with $s' \leq s$, then $Ad(\iota(t))X = t^{s'} X$ and $Ad(\iota'(t))X = t^s X$ for all $t \in {\mathbf k}^{\times}$, with $s' \leq s$.  Now 
\[
\begin{aligned}
Ad(\iota(t))X(v_i^j(b)) &= \iota(t) X \iota(t^{-1})(v_i^j(b)) = \iota(t) X(t^{-i} v_i^j(b)) \\
&= t^{-i} \iota(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(i' - i)} \xi_{(b', j', i')} v_{i'}^{j'}(b') =  \sum_{(b', j', i')}  t^{s'} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]

and 

\[
\begin{aligned}
Ad(\iota'(t))X(v_i^j(b)) &= \iota'(t) X \iota'(t^{-1})(v_i^j(b)) = \iota'(t) X(t^{-h_i(b)} v_i^j(b)) \\
&= t^{-h_i(b)} \iota'(t) \left( \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')\right) \\
&=  \sum_{(b', j', i')}  t^{(h_{i'}(b') - h_i(b))} \xi_{(b', j', i')} v_{i'}^{j'}(b') =  \sum_{(b', j', i')}  t^{s} \xi_{(b', j', i')} v_{i'}^{j'}(b')
\end{aligned}
\]
where both sums run over $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$ and  $i' \in Supp(b')$.

If $\xi_{(b', j', i')} \ne 0$ in the above equations, then $(i' - i) = s'$ in the first sum and $(h_{i'}(b') - h_{i}(b)) = s$ in the second sum. Because $s' \leq s$, we get that $(i' - i)\leq (h_{i'}(b') - h_i(b))$. Thus  $\lambda(b') = (i' - h_{i'}(b')) \leq (i - h_i(b)) = \lambda(b) = \lambda_r$ and we get easily that $X(U_1 \oplus U_2 \oplus \dots U_r) \subseteq (U_1 \oplus U_2 \oplus \dots \oplus U_r)$ for $r = 1, 2, \dots, \ell$.


$\Leftarrow)$  If $X \in {\mathfrak g}$ is such that $X(U_1 \oplus U_2 \oplus \dots \oplus U_r) \subseteq (U_1 \oplus U_2 \oplus \dots \oplus U_r)$ for all $r = 1, 2, \dots, \ell$, we must show that $X \in {\mathfrak p}_E$.  We can assume that $X \ne 0$.
If we write 
\[
X = \sum_{s, s'} {}_sX_{s'} \   \in \  \bigoplus_{s, s'} {}_s{\mathfrak g}_{s'}
\]
where the sum is finite and the summands are such that  ${}_sX_{s'} \in {}_s{\mathfrak g}_{s'}$ and ${}_sX_{s'} \ne 0$, then we must prove that $s' \leq s$.  

Note we have that 
\[
Ad(\iota(t))X = \sum_{s, s'} t^{s'} {}_sX_{s'} \quad \text{ and } \quad Ad(\iota'(t))X = \sum_{s, s'} t^{s} {}_sX_{s'}  
\]
for all $t \in {\mathbf k}^{\times}$.

Let $b \in {\mathbf B}$, $1 \leq j \leq c(b)$, $i \in Supp(b)$,  $\lambda(b) = \lambda_r$ for some $r = 1, 2, \dots, \ell$ such that $X(v_i^j(b)) \ne 0$. Such a basis vector exists because $X \ne 0$.  Write
\[
X(v_i^j(b)) = \sum_{(b', j', i')}  \xi_{(b', j', i')} v_{i'}^{j'}(b')
\]
where $\xi_{(b', j', i')} \in {\mathbf k}$ for all $(b', j', i')$ such that  $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$,  $i' \in Supp(b')$, $\lambda(b') \leq \lambda_r$  and the sum runs over these $(b', j', i')$, by our hypothesis.  

Write 
\[
{}_sX_{s'}(v_i^j(b)) = \sum_{(b', j', i')} \chi_{(b', j', i')}^{(s, s')} v_{i'}^{j'}(b')
\]
where  $\chi_{(b', j', i')}^{(s, s')} \in {\mathbf k}$ for all $(b', j', i')$ such that  $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$,  $i' \in Supp(b')$ and  the sum runs over these $(b', j', i')$. 


Note that 
\[
\begin{aligned}
Ad(\iota(t))X(v_i^j(b)) &= \iota(t) X(t^{-i} v_i^j(b)) = \sum_{(b', j', i')} t^{(i' - i)}  \xi_{(b', j', i')} v_{i'}^{j'}(b') \\
&= \sum_{s, s'} t^{s'} {}_sX_{s'}(v_i^j(b)) = \sum_{(b', j', i')}\left[\sum_{s'} t^{s'} \left(\sum_s \chi_{(b', j', i')}^{(s, s')}\right) \right] v_{i'}^{j'}(b')
\end{aligned}
\]
and
\[
\begin{aligned}
Ad(\iota'(t))X(v_i^j(b)) &= \iota'(t) X(t^{-h_i(b)} v_i^j(b)) = \sum_{(b', j', i')} t^{(h_{i'}(b') - h_i(b))}  \xi_{(b', j', i')} v_{i'}^{j'}(b') \\
&= \sum_{s, s'} t^{s} {}_sX_{s'}(v_i^j(b)) = \sum_{(b', j', i')}\left[\sum_{s} t^{s} \left(\sum_{s'} \chi_{(b', j', i')}^{(s, s')}\right) \right] v_{i'}^{j'}(b')
\end{aligned}
\]
where  both sums run over $b' \in {\mathbf B}$, $1 \leq j' \leq c(b')$,   $i' \in Supp(b')$ and $\lambda(b') \leq \lambda(b) = \lambda_r$. 

Because $X(v_i^j(b)) \ne 0$, there exists $b'' \in {\mathbf B}$, $1 \leq j'' \leq c(b'')$,   $i'' \in Supp(b'')$ and $\lambda(b'') \leq \lambda(b) = \lambda_r$ such that $\xi_{(b'', j'', i'')} \ne 0$. If we  consider the coefficient of $v_{i''}^{j''}(b'')$ in the above expressions, we get that 
\[
t^{(i'' - i)}  \xi_{(b'', j'', i'')} = t^{s'} \left(\sum_s \chi_{(b'', j'', i'')}^{(s, s')}\right)  \text{ and }  t^{(h_{i''}(b'') - h_i(b))}  \xi_{(b'', j'', i'')} =  t^{s} \left(\sum_{s'} \chi_{(b'', j'', i'')}^{(s, s')}\right).
\]
Because $\xi_{(b'', j'', i'')} \ne 0$,  then we have $s' = (i'' - i)$ and $s = (h_{i''}(b'') - h_i(b))$. Now we have that $\lambda(b'') = (i'' - h_{i''}(b'')) \leq (i - h_i(b)) = \lambda(b)$. So $s' = (i'' - i) \leq (h_{i''}(b'') - h_i(b)) = s$.  This concludes the proof of (b).

\end{proof}

%7.6
\subsection{}
We need to consider also the nilpotent element $E = {}''E_{\mathbf c}$ for the $G^{\iota}$-orbit ${}''{\mathcal O}_{\mathbf c}$ as described in notation~\ref{N:CCorrespondanceSpecialOrtho} for the  case (c) of proposition~\ref{P:OrbitSplittingSO}. From our hypothesis in case (c), we get that $0 \not\in \Lambda({\mathbf c})$. Let ${\mathcal O}'$ be the $\langle \tau \rangle$-orbit  defined in the proof of the proposition~\ref{P:OrbitSplittingSO}. We can write ${\mathcal O}' = \{b_1, b_2\}$ with $\tau(b_1) = b_2$ and $\lambda(b_1) < \lambda(b_2)$. This last inequality follows because both $\lambda(b_1)$ and $\lambda(b_2)$ are not zero. Write $\lambda(b_1) = \lambda_{r'}$ and thus $\lambda(b_2) = \lambda_{\ell + 1 - r'}$.

For $1 \leq r \leq \ell$, denote by ${}''U_r$: the subspace of $V$ spanned by the subset ${}''{\widehat {\mathcal B}}_r$, where 
\begin{itemize}
\item if $r \ne r', (\ell + 1 - r')$, then 
\[
{}''{\widehat {\mathcal B}}_r = \{v_i^j(b) \mid b \in {\mathbf B}, \lambda(b) = \lambda_r, i \in Supp(b), 1 \leq j \leq c(b)\};
\]
\item if $r = r'$, then
\[
\begin{aligned}
{}''{\widehat {\mathcal B}}_r &= \{v_i^j(b) \mid b \in {\mathbf B}, \lambda(b) = \lambda_r, i \in Supp(b), i \ne 0,  1 \leq j \leq c(b)\}\\
& \quad \bigcup \{v_0^j(b) \mid b \in {\mathbf B}, b \ne b_1, \lambda(b) = \lambda_r, 0 \in Supp(b), 1 \leq j \leq c(b) \}\\
& \quad \bigcup \{v_0^j(b_1) \mid 1 \leq j \leq (c(b_1) - 1)\} \bigcup \{v_0^{c(b_1)}(b_2)\}
\end{aligned}
\]
\item if $r = (\ell + 1 - r')$, then
\[
\begin{aligned}
{}''{\widehat {\mathcal B}}_r &= \{v_i^j(b) \mid b \in {\mathbf B}, \lambda(b) = \lambda_r, i \in Supp(b), i \ne 0,  1 \leq j \leq c(b)\}\\
& \quad \bigcup \{v_0^j(b) \mid b \in {\mathbf B}, b \ne b_2, \lambda(b) = \lambda_r, 0 \in Supp(b), 1 \leq j \leq c(b) \}\\
& \quad \bigcup \{v_0^j(b_2) \mid 1 \leq j \leq (c(b_2) - 1)\} \bigcup \{v_0^{c(b_2)}(b_1)\}
\end{aligned}
\]
\end{itemize}

%proposition 7.7
\begin{proposition}
Let $X \in {\mathfrak g}$ and $E = {}''E_{\bf c}$.  Then 
\begin{enumerate}[\upshape (a)]
\item $X \in {\mathfrak l}_{E}$ if and only if $X({}''U_r) \subseteq {}''U_r$ for all $r = 1, 2, \dots, \ell$.
\item $X \in {\mathfrak p}_{E}$ if and only if $X({}''U_1 \oplus {}''U_2 \dots \oplus {}''U_r) \subseteq ({}''U_1 \oplus {}''U_2 \oplus \dots \oplus {}''U_r)$ for all $r = 1, 2, \dots, \ell$.
\end{enumerate}
\end{proposition}
\begin{proof}
The proof is similar to the proof of proposition~\ref{P:ParabolicLeviAssociated} and is left to the reader. We just have to adapt the action of $Ad(\iota'(t))$ to this situation and this means transposing $v_0^{c(b_1)}(b_1)$ and $v_0^{c(b_2)}(b_2)$. Note that $c(b_1) = c(b_2)$.
\end{proof}

%Remark 7.8
\begin{remark}\label{R:Remarks6.9}
We can observed the following:
\begin{enumerate}[\upshape (a)]
%(a)
\item $\#\Lambda({\mathbf c}) = \ell$ is odd if and only if $0 \in \Lambda({\mathbf c})$. In that case, $\lambda_{\ell'} = 0$, where $\ell = 2\ell' - 1$. 
%(b)
\item If $b \in {\mathbf B}$ is such that  $\lambda(b) = 0$, then $b$ is on the principal diagonal. Thus $0 \in \Lambda({\mathbf c})$ if and only if there exists at least an ${\mathcal I}$-box $b$ on the principal diagonal such that $c(b) \ne 0$. This follows easily from our interpretation of the function $\lambda$ via the ${\mathcal I}$-diagram. See notation~\ref{N:LambdaValue}
%(c)
\item If $0 \in \Lambda({\mathbf c})$ and with the notation of (a) above, we have that $U_{\ell'} \ne 0$ and the bilinear form $\langle\ , \ \rangle$ of $V$ restricted to $U_{\ell'}$ is non-degenerate. Moreover if $X \in {\mathfrak g}$ is such that $X(U_{\ell'}) \subseteq U_{\ell'}$, then $X\vert_{U_{\ell'}}$ belongs to the Lie subalgebra of ${\mathfrak g}$ corresponding to the subspace $U_{\ell'}$. More precisely, we have 
\[
\langle X\vert_{U_{\ell'}}(u), v \rangle + \langle u, X\vert_{U_{\ell'}}(v) \rangle = 0 \quad \text{ for all } u, v \in U_{\ell'}
\]
%(d)
\item For $1 \leq r \leq \ell$, we have $v_i^j(b) \in \widehat{\mathcal B}_r$ (respectively ${}''  \widehat{\mathcal B}_r$)  if and only if $v_{-i}^j(\tau(b)) \in \widehat{\mathcal B}_{\ell + 1 - r}$ (respectively ${}''\widehat{\mathcal B}_{\ell + 1 - r}$). For $\widehat{\mathcal B}_r$ and $\widehat{\mathcal B}_{\ell + 1 - r}$, we just need to recall that $c(b) = c(\tau(b))$, also $i \in Supp(b)$ if and only if $-i \in Supp(\tau(b))$ and finally $\lambda(b) = \lambda_r$ if and only if $\lambda(\tau(b)) = \lambda_{\ell + 1 - r}$.   For ${}''\widehat{\mathcal B}_r$ and ${}''\widehat{\mathcal B}_{\ell + 1 - r}$, the proof is similar and we just need to consider $r = r'$ or $\ell + 1 - r'$. 
%(e)
 \item Let $X \in {\mathfrak l}_{E}$ where $E$ is either $E_{\mathbf c}$ or ${}'E_{\mathbf c}$ (respectively ${}''E_{\mathbf c}$)  and the basis vector $v_{i_1}^{j_1}(b_1) \in \widehat {\mathcal B}_r$ (respectively  ${}''\widehat{\mathcal B}_r$) of the subspace $U_r$ (respectively ${}''U_r$). Write 
 \[
 X(v_{i_1}^{j_1}(b_1)) = \sum_{(b_2, j_2, i_2)} \xi_{(b_1, j_1, i_1)}^{(b_2, j_2, i_2)} v_{i_2}^{j_2}(b_2)
 \]
 where $\xi_{(b_1, j_1, i_1)}^{(b_2, j_2, i_2)} \in {\mathbf k}$ and the sum runs over the triples $(b_2, j_2, i_2)$ where $v_{i_2}^{j_2}(b_2) \in \widehat {\mathcal B}_r$ (respectively ${}''\widehat{\mathcal B}_r$) and write for the basis vector $v_{-i_3}^{j_1}(\tau(b_3)) \in \widehat {\mathcal B}_{\ell + 1 - r}$ (respectively  ${}''\widehat{\mathcal B}_{\ell + 1 - r}$) of the subspace $U_{\ell + 1 - r}$ (respectively ${}''U_{\ell + 1 - r}$) 
 \[
 X(v_{-i_3}^{j_3}(\tau(b_3))) = \sum_{(b_4, j_4, i_4)} \psi_{(b_3, j_3, i_3)}^{(b_4, j_4, i_4)} v_{-i_4}^{j_4}(\tau(b_4))
 \]
where $ \psi_{(b_3, j_3, i_3)}^{(b_4, j_4, i_4)} \in {\mathbf k}$ and  the sum runs over the triples $(b_4, j_4, i_4)$ where $v_{-i_4}^{j_4}(\tau(b_4)) \in \widehat {\mathcal B}_{\ell + 1 - r}$ (respectively ${}''\widehat{\mathcal B}_r$). From 
\[
\langle X(v_{i_1}^{j_1}(b_1)) , v_{-i_3}^{j_3}(\tau(b_3))\rangle + \langle v_{i_1}^{j_1}(b_1) , X(v_{-i_3}^{j_3}(\tau(b_3)))\rangle = 0,
\]
we get that 
\[
\xi_{(b_1, j_1, i_1)}^{(b_3, j_3, i_3)} \langle v_{i_3}^{j_3}(b_3) , v_{-i_3}^{j_3}(\tau(b_3)\rangle  + 
\psi_{(b_3, j_3, i_3)}^{(b_1, j_1, i_1)} \langle v_{i_1}^{j_1}(b_1) , v_{-i_1}^{j_1}(\tau(b_3))\rangle
= 0
\]
Both $\langle v_{i_3}^{j_3}(b_3), v_{-i_3}^{j_3}(\tau(b_3))\rangle $ and $ \langle v_{i_1}^{j_1}(b_1), v_{-i_1}^{j_1}(\tau(b_1))\rangle$ are $\ne 0$. In fact they are equal to either $1$ or $\epsilon$. Thus 
\[
\psi_{(b_3, j_3, i_3)}^{(b_1, j_1, i_1)}  = - \frac{\langle v_{i_3}^{j_3}(b_3) , v_{-i_3}^{j_3}(\tau(b_3))\rangle} { \langle v_{i_1}^{j_1}(b_1), v_{-i_1}^{j_1}(\tau(b_1))\rangle} \xi_{(b_1, j_1, i_1)}^{b_3, j_3, i_3)}.
\]
In other words, $X\vert_{U_{\ell + 1 - r}}$ is obtained from $X\vert_{U_r}$.
%(f)
\item Let $E$ be  either the nilpotent element $E_{\mathbf c}$ or ${}'E_{\mathbf c}$ (respectively  ${}''E_{\mathbf c}$).   It is known that if $E \in {\mathfrak l}_E$ and consequently $E(U_r) \subseteq U_r$ (respectively $E({}''U_r) \subseteq {}''U_r$) for all $r = 1, 2, \dots, \ell$, then
\begin{itemize}
\item the dimension of $U_r$ (respectively  ${}''U_r$) is 
\[
\sum_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_r \end{subarray}} c(b) \vert Supp(b) \vert; 
\]
\item  the partition corresponding to the Jordan decomposition of the restriction $E\vert_{U_r}$ to $U_r$ (respectively $E\vert_{{}''U_r}$ to ${}''U_r$) is 
\[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_r \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
\end{itemize}
For the dimension of $U_r$, this follows by computing $\vert \widehat{\mathcal B}_r \vert$ or  $\vert {}''\widehat{\mathcal B}_r \vert$. Note that in the case of the dimension of ${}''U_r$ for $r = r'$ or $\ell + i - r'$, it follows from the fact that the function $c$ is symmetric and also $\vert Supp(\tau(b)) \vert = \vert Supp(b) \vert$.

As for the partition corresponding to the Jordan decomposition of the restriction $E\vert_{U_r}$ to $U_r$ (respectively $E\vert_{{}''U_r}$ to ${}''U_r$), it follows by the known action of the nilpotent element $E$ on the basis elements in $\widehat{\mathcal B}_r$ or  ${}''\widehat{\mathcal B}_r$. 

\end{enumerate}  

\end{remark}

We will now describe the isomorphism class of the Levi subalgebra ${\mathfrak l}_E$ and also the tuple of  partitions corresponding to the Jordan decomposition of $E\vert_{U_r}$.

%proposition 7.9
\begin{proposition}\label{P:LieSubgroupDescription}
Let $E$ be  either the nilpotent element $E_{\mathbf c}$ or ${}'E_{\mathbf c}$ (respectively ${}''E_{\mathbf c}$). Denote by $n_r = \dim(U_r)$ (respectively $n_r = \dim({}''U_r)$) for $1 \leq r \leq \ell$. As we saw in remark~\ref{R:Remarks6.9} (f), 
\[
n_r = \sum_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_r \end{subarray}} c(b) \vert Supp(b) \vert; 
\]
for $1 \leq r \leq \ell$.

\begin{itemize}
%item1
\item If $\# \Lambda({\mathbf c}) = \ell$ is even and write $\ell = 2\ell'$, then the map 
\[
{\mathfrak l}_{E} \rightarrow {\mathfrak {gl}}({n_1}) \oplus {\mathfrak {gl}}({n_2}) \oplus \dots \oplus {\mathfrak {gl}}({n_{\ell'}})
\] 
defined by  
\[
X \mapsto \begin{cases} ([X\vert_{U_1}]_{\widehat{\mathcal B}_1 }, [X\vert_{U_2}]_{\widehat{\mathcal B}_2 }, \dots, [X\vert_{U_{\ell'}}]_{\widehat{\mathcal B}_{\ell'} }), &\text{ if $E = E_{\mathbf c}$ or ${}'E_{\mathbf c}$;}\\  \\([X\vert_{{}''U_1}]_{{}''\widehat{\mathcal B}_1 }, [X\vert_{{}''U_2}]_{{}''\widehat{\mathcal B}_2 }, \dots, [X\vert_{{}''U_{\ell'}}]_{{}''\widehat{\mathcal B}_{\ell'} }), &\text{ if $E = {}''E_{\mathbf c}$;}
\end{cases}
\]
 is an isomorphism of Lie algebras and the tuple of  partitions corresponding to the Jordan decomposition of $E\vert_{U_r}$ as given in (f) of remark~\ref{R:Remarks6.9} is  
\[
\left(\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_r \end{subarray}}  \vert Supp(b) \vert^{c(b)}\right)_{1 \leq r \leq \ell'}.
\]
%item2
 \item If $\#  \Lambda({\mathbf c}) = \ell$ is odd and write $\ell = 2\ell' - 1$, then the map 
\[
{\mathfrak l}_{E} \rightarrow {\mathfrak {gl}}({n_1}) \oplus {\mathfrak {gl}}({n_2}) \oplus \dots \oplus {\mathfrak {gl}}({n_{\ell' - 1}}) \oplus {\mathfrak g'}
\]
defined by
\[
X \mapsto \begin{cases} ([X\vert_{U_1}]_{\widehat{\mathcal B}_1 }, [X\vert_{U_2}]_{\widehat{\mathcal B}_2 }, \dots, [X\vert_{U_{\ell'}}]_{\widehat{\mathcal B}_{\ell'} }), &\text{ if $E = E_{\mathbf c}$ or ${}'E_{\mathbf c}$;}\\  \\([X\vert_{{}''U_1}]_{{}''\widehat{\mathcal B}_1 }, [X\vert_{{}''U_2}]_{{}''\widehat{\mathcal B}_2 }, \dots, [X\vert_{{}''U_{\ell'}}]_{{}''\widehat{\mathcal B}_{\ell'} }), &\text{ if $E = {}''E_{\mathbf c}$;}
\end{cases}
\]
is an isomorphism of Lie algebras and the tuple of partitions corresponding to the Jordan decomposition of $E\vert_{U_r}$ as given in (f) in remark~\ref{R:Remarks6.9} is 
\[
\left(\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_r \end{subarray}}  \vert Supp(b) \vert^{c(b)}\right)_{1 \leq r \leq \ell'}.
\]
\end{itemize}
Here $[X\vert_{U_r}]_{\widehat{\mathcal B}_r }$ (respectively $[X\vert_{{}''U_r}]_{{}''\widehat{\mathcal B}_r }$)  is the matrix of $X\vert_{U_r}$ (respectively $X\vert_{{}''U_r}$) relative to the basis  $\widehat{\mathcal B}_r$ (respectively  ${}''\widehat{\mathcal B}_r$) of $U_r$ (respectively ${}''U_r$), ${\mathfrak {gl}}({n_r})$ is the general linear Lie algebra of $n_r \times n_r$-matrices  for $r = 1, 2, \dots, \ell'$ and ${\mathfrak g'}$ is the classical Lie algebra
\[
{\mathfrak g'} = 
\begin{cases} {\mathfrak {so}}({n_{\ell'}}), &\text{ if the bilinear form $\langle\  ,\   \rangle$ is symmetric;}\\  \\ {\mathfrak {sp}}({n_{\ell'}}), &\text{ if the bilinear form $\langle\  ,\   \rangle$ is skew-symmetric.}
\end{cases}
\]
\end{proposition}
\begin{proof}
We will only sketch this proof. Let $E$ be either the nilpotent element $E_{\mathbf c}$ or ${}'E_{\mathbf c}$.  It is clear that the map 
\[
X \mapsto ([X\vert_{U_1}]_{\widehat{\mathcal B}_1 }, [X\vert_{U_2}]_{\widehat{\mathcal B}_2 }, \dots, [X\vert_{U_{\ell'}}]_{\widehat{\mathcal B}_{\ell'} })
\]
is a linear Lie algebra homomorphism. If we consider its kernel, we get that $X$ is $0$ on $U_r$ for $r = 1, 2, \dots, \ell'$. By the equations in  remark~\ref{R:Remarks6.9} (e), we get also that $X$ is $0$ on $U_r$ for $r = \ell' + 1, \dots, \ell$. Because $V = U_1 \oplus U_2 \oplus \dots \oplus U_{\ell}$, we get that $X$ is $0$ and the kernel is trivial. So the map is injective. 

If we now consider $\ell'$-tuple $(A_1, A_2, \dots, A_{\ell'})$ of matrices such that $A_i \in {\mathfrak {gl}}_{n_i}$  for $i = 1, 2, \dots, (\ell' - 1)$ and $A_{\ell'}$ belongs to ${\mathfrak {gl}}_{n_{\ell'}}$
 in the case where $\# \Lambda({\mathbf c})$ is even and belongs to ${\mathfrak {g'}}$ in the case where $\# \Lambda({\mathbf c})$ is odd. We can define  the linear transformation $X$ by asking $[X\vert_{U_r}]_{\widehat{\mathcal B}_r }= A_r$ for $r = 1, 2, \dots, \ell'$. Then we can use the equations of remark~\ref{R:Remarks6.9} (e)  to define  $X$ on ${U_r}$ for $r = \ell' + 1, \dots, \ell$.  The equations of remark~\ref{R:Remarks6.9} (e) and the definition of ${\mathfrak g'}$ imply that $X \in {\mathfrak g}$. Because $X(U_r) \subseteq U_r$ for all $r = 0, 1, \dots, \ell$, then $X \in {\mathfrak l}_E$ and its image is the $\ell'$-tuple $(A_1, A_2, \dots, A_{\ell'})$.
 The proof when $E$ is  the nilpotent element ${}''E_{\mathbf c}$ is similar.
\end{proof}

%corollary 7.10
\begin{corollary}
With the same notation as in the above proposition, we have that 
\[
\dim({\mathfrak l}_E)= \sum_{i = 1}^{(\ell' - 1)} n_i^2 + \begin{cases} n_{\ell'}^2, &\text{if $\# \Lambda({\mathbf c}) = \ell$ is even and $\ell = 2\ell'$;}\\ \\n_{\ell'}(n_{\ell'} - 1)/2, &\text{if $\#  \Lambda({\mathbf c})  = \ell$ is odd, $\ell = (2\ell' - 1)$ and}\\ &\text{the bilinear form $\langle\  ,\   \rangle$ is symmetric;} \\ \\n_{\ell'}(n_{\ell'} + 1)/2, &\text{if $\#  \Lambda({\mathbf c}) = \ell$ is odd, $\ell = (2\ell' - 1)$ and}\\ &\text{the bilinear form $\langle\  ,\   \rangle$ is skew-symmetric.}\end{cases}
\]
\end{corollary}
\begin{proof}
This follows easily from the above isomorphism and the dimension of each Lie algebras.
\end{proof}

%corollary 7.11
\begin{corollary}\label{C:LeviSubgpAssociatedNilpotent}
With the same notation as in the above proposition, we have that  the Levi subgroup $L_E$ is isomorphic to
\[
 \begin{cases}GL_{n_1}({\mathbf k}) \times GL_{n_2}({\mathbf k}) \times \dots \times GL_{n_{\ell'}}({\mathbf k})&\text{if $\#  \Lambda({\mathbf c}) = \ell$ is even and $\ell = 2\ell'$;}\\ \\GL_{n_1}({\mathbf k})  \times \dots \times GL_{n_{\ell' - 1}}({\mathbf k}) \times SO_{n_{\ell'}}({\mathbf k})&\text{if $\#  \Lambda({\mathbf c})  = \ell$ is odd, $\ell = (2\ell' - 1)$ and}\\ &\text{the bilinear form $\langle\  ,\   \rangle$ is symmetric;} \\ \\GL_{n_1}({\mathbf k})  \times \dots \times GL_{n_{\ell' - 1}}({\mathbf k}) \times Sp_{n_{\ell'}}({\mathbf k}) &\text{if $\#  \Lambda({\mathbf c})  = \ell$ is odd, $\ell = (2\ell' - 1)$ and}\\ &\text{the bilinear form $\langle\  ,\   \rangle$ is skew-symmetric.}\end{cases}
\]
Note that in this last case: $\#  \Lambda({\mathbf c})  = \ell$ is odd, $\ell = (2\ell' - 1)$ and the bilinear form $\langle\  ,\   \rangle$ is skew-symmetric, it is easy to check that $n_{\ell'}$ is even.
\end{corollary}
\begin{proof}
This follows easily from the above isomorphism of Lie algebras.
\end{proof}

%section 8
\section{Irreducible   $G^{\iota}$-equivariant local systems on $G^{\iota}$-orbits in ${\mathfrak g}_2$.}

%8.1
\subsection{}
Let $m$, $G$, ${\mathfrak g}$, $V$, ${\mathcal I}$, $\oplus_{i \in {\mathcal I}} V_i$, $\delta = (\delta_i)_{i \in {\mathcal I}}$,  ${\mathcal B}$, $\iota$, ${\mathbf B}$ and ${\mathbf B}/\tau$ as in either \ref{S:SetUpAeven} or  \ref{S:SetUpOdd} or \ref{S:SetUpOddOrtho}. More precisely $G$ should be a connected  reductive group. Thus in the situation of  \ref{S:SetUpOdd}, we restrict ourself only to the group $Sp(V)$, while in the situation of  \ref{S:SetUpOddOrtho}, $G$ is to the group $SO(V)$. In the situation of \ref{S:SetUpAeven} , $G$ is already connected.

%8.2
\subsection{}
Let ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ be a coefficient function in ${\mathfrak C}_{\delta}$ and the associated symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$. Given a $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) in ${\mathfrak g}_2$, we want to enumerate the irreducible   $G^{\iota}$-equivariant local systems on this $G^{\iota}$-orbit. For this,  we will use the notion of symbols as defined and noted in sections 11 to 13 of Lusztig's article \cite{L1984}. We won't recall these notions, but we will use them as in Lusztig's article.  

We have constructed in \ref{N:CCorrespondance}, \ref{N:CCorrespondanceOdd} and \ref{N:CCorrespondanceSpecialOrtho} for such an $G^{\iota}$-orbit:  a Jacobson-Morozov  triple $(E_{\mathbf c}, H_{\mathbf c}, F_{\mathbf c})$ (respectively $({\ }'E_{\mathbf c}, {\ }'H_{\mathbf c}, {\ }'F_{\mathbf c})$, $({\ }''E_{\mathbf c}, {\ }''H_{\mathbf c}, {\ }''F_{\mathbf c})$). In proposition~\ref{P:LieSubgroupDescription} and corollary~\ref{C:LeviSubgpAssociatedNilpotent},  we have described the Levi subalgebra ${\mathfrak l}_E$  and its corresponding Levi subgroup $L_E$ for the element $E = E_{\mathbf c}$ (respectively $E = {\ }'E_{\mathbf c}$, $E = {\ }''E_{\mathbf c}$).  


%remark 8.3
\begin{remark}\label{R:CentralizerOverConnectedCentralizer}
Denote by $L_{E}$: the Levi subgroup associated to the nilpotent element $E$ as denoted in the previous section. From its definition, we have that $(L_{E}, \iota)$ is $2$-rigid and by proposition 4.2 in \cite{L1995}, we have that 
\[
Stab_{L^{\iota}_{E}}(E) / Stab_{L^{\iota}_{E}}^0(E) \rightarrow Stab_{L_{E}}(E) / Stab_{L_{E}}^0(E)
\]
is an isomorphism. By proposition 5.8 in \cite{L1995}, we also have that
\[
Stab_{L^{\iota}_{E}}(E) / Stab_{L^{\iota}_{E}}^0(E) \rightarrow Stab_{G^{\iota}}(E) / Stab_{G^{\iota}}^0(E)
\]
is an isomorphism.  So to enumerate the irreducible  $G^{\iota}$-equivariant local systems on $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) in ${\mathfrak g}_2$, it is enough to only consider $L_{E}$ rather that $G^{\iota}$. Because of our description of $L_{E}$ in corollary~\ref{C:LeviSubgpAssociatedNilpotent} above and the results in section 11 to 13 of \cite{L1984}, then the combinatorics is known. 

\end{remark}

%8.4
\subsection{}\label{SS:LocalSystemNumber}
For $GL_N({\mathbf k})$,  ($N \geq 1$),  it is known  that the unipotent classes  are in one-to-one correspondance with the partition of  $N = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, where $i_1, i_2, i_3, \dots \geq 0$. For a unipotent element $u \in GL_N({\mathbf k})$ in the unipotent class ${\mathcal Cl}(u)$, there is one and only one irreducible $GL_N({\mathbf k})$-equivariant local system (up to isomorphism) on ${\mathcal Cl}(u)$, because it is easy to verify that the centralizer $Z_{GL_N({\mathbf k})}(u)$ of $u$ is connected. 

For $Sp_{2n}({\mathbf k})$ with $char({\mathbf k}) \ne 2$, it is known that the unipotent classes are in one-to-one correspondance with the partition of $2n = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, where $i_1, i_2, i_3, \dots \geq 0$ and $i_1, i_3, i_5, \dots $ are even. ($i_a$ is the number of Jordan blocks of size $a$ of a unipotent element and, in the previous section, we have written this partition multiplicatively as $1^{i_1} 2^{i_2} 3^{i_3} \dots$.) For a unipotent element $u \in Sp_{2n}({\mathbf k})$ in the unipotent class ${\mathcal Cl}(u)$ corresponding to the partition $2n = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, then the number of irreducible $Sp_{2n}({\mathbf k})$-equivariant local systems (up to isomorphism) on ${\mathcal Cl}(u)$ is $2^{\vert\{\text{ $a$  even } \mid\  i_a \geq 1\}\vert}$. See 10.4 in \cite{L1984}. 

 For $SO_N({\mathbf k})$, ($N \geq 1$) with $char({\mathbf k}) \ne 2$, it is known that the unipotent classes correspond to partitions of $N = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, where $i_1, i_2, i_3, \dots \geq 0$ and $i_2, i_4, i_6, \dots $ are even. ($i_a$ is the number of Jordan blocks of size $a$ of a unipotent element and, in the previous section, we have written this partition multiplicatively as $1^{i_1} 2^{i_2} 3^{i_3} \dots$.) This correspondance is one-to-one except that there are two unipotent classes (said to be degenerate) corresponding to partitions such that $i_1 = i_3 = i_5 = \dots = 0$, i.e. the corresponding partition is totally even. For a non-degenerate unipotent element $u \in SO_N({\mathbf k})$ in the unipotent class ${\mathcal Cl}(u)$ corresponding to the partition $N = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, then the number of irreducible $SO_N({\mathbf k})$-equivariant local systems (up to isomorphism) on ${\mathcal Cl}(u)$ is $2^{(\vert \{\text{ $a$  odd } \mid\  i_a \geq 1\}\vert - 1)}$. For a degenerate unipotent element $u \in SO_N({\mathbf k})$ in the unipotent class ${\mathcal Cl}(u)$ corresponding to the partition $N = 1 \cdot i_1 + 2 \cdot i_2 + 3 \cdot i_3 + \dots$, then there is one and only one irreducible $SO_N({\mathbf k})$-equivariant local system (up to isomorphism) on ${\mathcal Cl}(u)$. See 10.6 in \cite{L1984}. 

 %proposition 8.5
 \begin{proposition}\label{P:LocalSystemCardinality}
 Let ${\mathbf c}:{\mathbf B}/\tau \rightarrow {\mathbb N}$ be a coefficient function in ${\mathfrak C}_{\delta}$ and the associated symmetric function $c:{\mathbf B} \rightarrow {\mathbb N}$. 
 \begin{enumerate}[\upshape (a)]
 %(a)
 \item If $0 \not\in \Lambda({\mathbf c})$, then there exits only one and only one  irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$  (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) in ${\mathfrak g}_2$. This local system is the constant  local system.
 %(b)
 \item If $0 \in \Lambda({\mathbf c})$ and either ($\vert {\mathcal I} \vert$ is even and $\epsilon = 1$) or ($\vert {\mathcal I} \vert$ is odd and $\epsilon = -1$), then there exits only one and only one  irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$  in ${\mathfrak g}_2$. This local system is the constant  local system.
 %(c)
 \item If $0 \in \Lambda({\mathbf c})$,  $\vert {\mathcal I} \vert$ is even and $\epsilon = -1$, then there are   
 \[
 2^{\vert \{b\  \in\   {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b)   > 0 \}\vert}
 \]
 irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ in ${\mathfrak g}_2$.  
 %(d)
  \item If $0 \in \Lambda({\mathbf c})$,  $\vert {\mathcal I} \vert$ is odd and $\epsilon = 1$, then there are   
 \[
 2^{(\vert \{b\  \in \  {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b) > 0 \}\vert - 1)}
 \]
 irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ in ${\mathfrak g}_2$.  
 \end{enumerate}
 \end{proposition}
 %proof
 \begin{proof}
 By remark~\ref{R:CentralizerOverConnectedCentralizer}, we get that the number of irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on the $G^{\iota}$-orbit ${\mathcal O}_{\mathbf c}$ (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) in ${\mathfrak g}_2$ is 
 \[
 \vert Stab_{G^{\iota}}(E)/Stab^0_{G^{\iota}}(E)\vert =  \vert Stab_{L_E}(E)/Stab^0_{L_E}(E)\vert 
 \]
 We have described $L_E$ in corollary~\ref{C:LeviSubgpAssociatedNilpotent}.  In each case of this corollary, $L_E$ is a product of connected reductive groups and using external tensor product, we get the local systems from the ones on each factor. The first $(\ell' - 1)$ factors in this product  are isomorphic to a general linear group and from~\ref{SS:LocalSystemNumber} there is one and only one irreducible $L_E\vert_{U_r}$-equivariant local system (up to isomorphism) on the class of the restriction of $E$ to $U_r$, where $1 \leq r \leq (\ell' - 1)$. So to compute the number of irreducible $G^{\iota}$-equivariant local systems (up to isomorphism), we just have to consider the last factor in the product of $L_E$.

 %(a)
 (a) If $0 \not\in \Lambda({\mathbf c})$, then $\vert \Lambda({\mathbf c})\vert = \ell$ is even as note remark~\ref{R:Remarks6.9} (a) and the last factor in the product of $L_E$ is $GL_{n_{\ell'}}({\mathbf k})$ as we saw in corollary~\ref{C:LeviSubgpAssociatedNilpotent}. Here $\ell = 2\ell'$. In this case we have to consider a unipotent element $u$ in the  unipotent class corresponding to the partition 
 \[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_{\ell'} \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
 From~\ref{SS:LocalSystemNumber}, we get that there is one and only  irreducible $GL_N({\mathbf k})$-equivariant local system (up to isomorphism) on ${\mathcal Cl}(u)$. Thus there is one and only one irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  (respectively ${}'{\mathcal O}_{\mathbf c}$ or ${}''{\mathcal O}_{\mathbf c}$) in ${\mathfrak g}_2$. This local system is the constant  local system.

 %(b)
 (b) If $0 \in \Lambda({\mathbf c})$,  $\vert {\mathcal I} \vert$ is even and $\epsilon = 1$, then $\vert \Lambda({\mathbf c}) \vert= \ell = (2\ell' - 1)$ is odd and and the last factor in the product of $L_E$ is $SO_{n_{\ell'}}({\mathbf k})$ as we saw in corollary~\ref{C:LeviSubgpAssociatedNilpotent}. In this case we have to consider a unipotent element $u$ in the  unipotent class corresponding to the partition 
 \[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_{\ell'} \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
Because $\vert {\mathcal I} \vert$ is even, then $\vert Supp(b) \vert$ is even for all ${\mathcal I}$-boxes $b$ on the principal diagonal. Note also if $b \in {\mathbf B}$ is on the principal diagonal, then $\tau(b)$ is also on the principal diagonal and the $\langle \tau \rangle$-orbit of $b$ is $\{b, \tau(b)\}$, where $\tau(b) \ne b$. Also $c(b) = c(\tau(b))$. So $u$ is a degenerate unipotent element of $L_E$ and then there is one and only one irreducible $SO_{n_{\ell'}}(k)$-equivariant local system (up to isomorphism) on ${\mathcal Cl}(u)$. Thus there is one and only one irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  in ${\mathfrak g}_2$. 

If $0 \in \Lambda({\mathbf c})$,  $\vert {\mathcal I} \vert$ is odd and $\epsilon = -1$, then  $\vert \Lambda({\mathbf c}) \vert = \ell = (2\ell' - 1)$ is odd and and the last factor in the product of $L_E$ is $Sp_{n_{\ell'}}(k)$ as we saw in corollary~\ref{C:LeviSubgpAssociatedNilpotent}. In this case we have to consider a unipotent element $u$ in the  unipotent class corresponding to the partition 
 \[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_{\ell'} \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
Because $\vert {\mathcal I} \vert$ is odd, then $\vert Supp(b) \vert$ is odd for all ${\mathcal I}$-boxes $b$ on the principal diagonal.  Note also if $b \in {\mathbf B}$ is on the principal diagonal, then $\tau(b)$ is also on the principal diagonal and the $\langle \tau \rangle$-orbit of $b$ is $\{b, \tau(b)\}$, where $\tau(b) \ne b$. Also $c(b) = c(\tau(b))$. So in this case, there are no even part in the partition for the class ${\mathcal Cl}(u)$. Consequently from~\ref{SS:LocalSystemNumber}, there  is one and only one irreducible $Sp_{n_{\ell'}}(k)$-equivariant local system (up to isomorphism) on ${\mathcal Cl}(u)$. Thus there is one and only one irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  in ${\mathfrak g}_2$. 

In case either ($\vert {\mathcal I} \vert$ is even and $\epsilon = 1$) or ($\vert {\mathcal I} \vert$ is odd and $\epsilon = -1$), then the unique irreducible $G^{\iota}$-equivariant local system (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  is the constant  local system.

%(c)
(c) If $0 \in \Lambda(c)$,  $\vert {\mathcal I} \vert$ is even and $\epsilon = -1$, then $\vert \Lambda({\mathbf c}) \vert = \ell = (2\ell' - 1)$ is odd and and the last factor in the product of $L_E$ is $Sp_{n_{\ell'}}(k)$ as we saw in corollary~\ref{C:LeviSubgpAssociatedNilpotent}. In this case we have to consider a unipotent element $u$ in the  unipotent class corresponding to the partition 
 \[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_{\ell'} \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
Because $\vert {\mathcal I} \vert$ is even, then $\vert Supp(b) \vert$ is even for all ${\mathcal I}$-boxes $b$ on the principal diagonal. Note also if $b \in {\mathbf B}$ is on the principal diagonal, then $\tau(b) = b$ and the $\langle \tau \rangle$-orbit of $b$ is $\{b\}$.  So all the parts of the partition corresponding to the class ${\mathcal Cl}(u)$ are even. From~\ref{SS:LocalSystemNumber}, there are 
 \[
 2^{\vert \{b\  \in\   {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b) > 0 \} \vert}
 \]
 irreducible $L_E$-equivariant local systems (up to isomorphism) on ${\mathcal Cl}(u)$. Consequently there are 
 \[
 2^{\vert \{b\  \in\   {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b) > 0 \} \vert}
 \]
 irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  in ${\mathfrak g}_2$. 

%(d)
(d) If  $0 \in \Lambda(c)$,  $\vert {\mathcal I} \vert$ is odd and $\epsilon = 1$,  then $\vert \Lambda({\mathbf c}) \vert = \ell = (2\ell' - 1)$ is odd and and the last factor in the product of $L_E$ is $SO_{n_{\ell'}}(k)$ as we saw in corollary~\ref{C:LeviSubgpAssociatedNilpotent}. In this case we have to consider a unipotent element $u$ in the  unipotent class corresponding to the partition 
 \[
\prod_{\begin{subarray}{c} b \in {\mathbf B}\\ \lambda(b) = \lambda_{\ell'} \end{subarray}}  \vert Supp(b) \vert^{c(b)}.
\]
Because $\vert {\mathcal I} \vert$ is odd, then $\vert Supp(b) \vert$ is odd for all ${\mathcal I}$-boxes $b$ on the principal diagonal. Note also if $b \in {\mathbf B}$ is on the principal diagonal, then $\tau(b) = b$ and the $\langle \tau \rangle$-orbit of $b$ is $\{b\}$.  So all the parts of the partition corresponding to the class ${\mathcal Cl}(u)$ are odd. $u$ is a non-degenerate unipotent element. From~\ref{SS:LocalSystemNumber}, there are 
 \[
 2^{\vert \{b\  \in\   {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b) > 0 \}\vert  - 1}
 \]
irreducible $L_E$-equivariant local systems (up to isomorphism) on ${\mathcal Cl}(u)$. Consequently there are 
 \[
 2^{\vert \{b\  \in\   {\mathbf B}\  \mid \  \lambda(b) = 0,\   c(b) > 0 \}\vert - 1}
 \]
 irreducible $G^{\iota}$-equivariant local systems (up to isomorphism) on the orbit ${\mathcal O}_{\mathbf c}$  in ${\mathfrak g}_2$. 

 \end{proof}

