	\begin{theorem} \label{theorem} Suppose assumptions A.1 through A.5 hold, and $p > 1$.  
	\begin{enumerate}
	\item[(i)] If $m(x)$ is a function with two continuous derivatives on $(a,b)$ and $\hat{m}(x)$ is the local constant $L_p$-norm estimator for $m(x)$, then
$\hat{m}(x)$ is asymptotically normal with mean \[m(x) +\mu_2(K)h^2\left(\frac{m'(x)f'(x)}{f(x)} + \frac{m''(x)}{2}\right) + o(h^2), \quad \forall x \in (a+h, b-h)\] and variance \[\frac{R(K)E[|\varepsilon_1|^{2p-2}]}{nh(p-1)^2 E^2[|\varepsilon_1|^{p-2}] f(x)}+  o\left(\frac{1}{nh}\right), \quad \forall x \in (a+h, b-h).\]

\item[(ii)] If $m(x)$ is a function with three continuous derivatives on $(a,b)$ and 
\begin{enumerate}
\item[(a)] if
$\hat{m}(x)$ is the local linear $L_p$-norm estimator for $m(x)$, then 
$\hat{m}(x)$ is asymptotically normal with mean  
\[m(x) + \frac{\mu_2(K)h^2m''(x)}{2} + o(h^2), \quad \forall x \in (a+h, b-h)\]
and variance 
\[\frac{R(K)E[|\varepsilon|^{2p-2}]}{nhf(x)(p-1)^2 E^2[|\varepsilon|^{p-2}]} + o\left(\frac{1}{nh}\right), \quad \forall x \in (a+h, b-h).\]
\item[(b)] if
$\hat{m'}(x)$ is the local linear $L_p$-norm estimator for $m'(x)$, then
$\hat{m'}(x)$ is asymptotically normal with mean 
\[m'(x)+\frac{\mu_4(K)h^2 m'''(x)}{3!\mu_2(K)} + o(h^2), \quad \forall x \in (a+h, b-h).\]
and variance \[\frac{\mu_2^2(K^2)E[|\varepsilon|^{2p-2}]}{nh^3f(x)\mu_2(K)(p-1)^2E^2[|\varepsilon|^{p-2}]} + o\left(\frac{1}{nh^3}\right), \quad \forall x \in (a+h, b-h).\]

\end{enumerate}
\item[(iii)] $\hat{m}(x)$ and $\hat{m'}(x)$ are asymptotically independent.  
\end{enumerate}
\end{theorem}

\begin{proof}
\begin{enumerate}
\item[(i)]
The local constant $L_p$-norm estimator for $\beta_0 = m(x)$ is the quantity $\widehat{\beta}_0$ which minimizes the expression 
	\[ \ell(\beta_0) = \sum_{i=1}^n |y_i - \beta_0|^p K_h(x_i - x). \]  
	Differentiating with respect to $\beta_0$ once, we have
	\begin{equation*}
	\ell'(\beta_0) = -p \sum_{i=1}^n |y_i - \beta_0|^{p-1} \mbox{sign}(y_i - \beta_0) K_h(x_i - x). \hspace{1cm} (*)
	\end{equation*}	
	Observe that since $\ell(.)$ is a convex function, it has a unique minimizer.  Furthermore, $\ell'(\beta_0) < 0$ if,  and only if $\beta_0< \widehat{\beta}_0$, and $\ell'(\beta_0) > 0$ if and only if $\beta_0 > \widehat{\beta}_0$.  Let $F_n(x)$ denote the distribution function of $\sqrt{nh}(\widehat{\beta}_0 - \beta_0)$.  Then
	\begin{equation*}
	 F_n(c) = P(\sqrt{nh} (\widehat{\beta}_0 - \beta_0) \leq c) = P(\widehat{\beta}_0 \leq \beta_0 + c/\sqrt{nh}) = P(\ell'(\beta_0 + c/\sqrt{nh}) \geq 0). \hspace{1cm} (**)
	\end{equation*}	

	Substituting (*) for (**), where $\beta_0$ replaced by $\beta_0+ c/\sqrt{nh}$, gives
\begin{small}
\begin{eqnarray} 
	F_n(c) &= & P\left(-p \sum_{i=1}^n |y_i - \beta_0 - c/\sqrt{nh}|^{p-1} \mbox{sign}(y_i - \beta_0 - c/\sqrt{nh}) K_h(x_i - x) \geq 0\right)
	\nonumber  \\
	&= & P\left(\sum_{i=1}^n |y_i - \beta_0 - c/\sqrt{nh}|^{p-1} \mbox{sign}(y_i - \beta_0 - c/\sqrt{nh}) K_h(x_i - x) \leq 0\right) \nonumber\\
	&=& P\left(\sqrt{\frac{h}{n}}\sum_{i=1}^n |(\varepsilon_i + m(x_i)) - m(x) - c/\sqrt{nh}|^{p-1} {\rm sign}\left(\varepsilon_i + m(x_i) - m(x) - c/\sqrt{nh}\right) \right. \nonumber \\  && \quad \quad \left. K_h(x_i - x) \leq 0 \right)\nonumber \\
	&= & P\left(V_{0n}  + (p-1) E[|\varepsilon_1|^{p-2}] \left\{\mu_2(K) \sqrt{nh^5} \left(f'(x) m'(x) + m''(x) f(x)/2\right) - c f(x)\right\} \right. \nonumber \\  && \quad \quad \left. + o(\sqrt{nh^5}) \leq 0\right) \nonumber \\
	&=& P \left(\frac{V_{0n} + (p-1)E[|\varepsilon_1|^{p-2}] (m''(x)f(x)/2 + m'(x)f'(x))\sqrt{nh^{5}}\mu_{2}(K)}{(p-1) E[|\varepsilon_1|^{p-2}] f(x)} + o(\sqrt{nh^5}) \leq c, \right) \nonumber 	
\end{eqnarray}
\end{small}
where we are using the definition of $V_{0n}$ given in Lemma \ref{lem:clt}. According to  that lemma,  
	$ \frac{V_{0n}}{\sqrt{f(x) R(K) E[|\varepsilon_1|^{2p-2}]}}$ converges in 
	distribution to the standard normal distribution, and the entire quantity on the left
	side of the inequality displayed directly above must 
	 converge to a normal distribution with mean
	$\mu_2(K)\left(\frac{f'(x)}{f(x)}m'(x) + \frac{m''(x)}{2}\right)\sqrt{nh^5}$ and variance $\frac{R(K)E[|\varepsilon_1|^{2p-2}]}{(p-1)^2 E^2[|\varepsilon_1|^{p-2}]f(x)}$. 
	By the definition of $F_n(c)$, we see that 
	$\sqrt{nh}(\widehat{\beta}_0 - \beta_0)$ converges to this same normal distribution limit and
	the result in (i) immediately follows.  

\item[(ii, iii)]
	Let $F_n(x)$ denote the joint distribution function of $[\sqrt{nh}(\widehat{\beta_0} - \beta_0), 
\sqrt{nh^{3}}(\widehat{\beta_1} - \beta_1)]$.  Then for any real $c_0$ and $c_1$, we have $F_n(c_0, c_1)$
\begin{small}
\begin{eqnarray}
		 &=& P( \sqrt{nh^{1+2j}}(\widehat{\beta_j} - \beta_j) \leq c_j; j = 0,1)  \nonumber \\
		&=& P\left(\frac{1}{h^j}\sqrt{\frac{h}{n}}\sum_{i=1}^n (x_i-x)^j \left|\varepsilon_i + \frac{m''(x)}{2}(x_i-x)^2 + \frac{m'''(x)}{3!}(x_i-x)^3 - \frac{c_0}{\sqrt{nh}}- \frac{c_1(x_i-x)}{\sqrt{nh^3}}\right|^{p-1} \right.  \nonumber \\
		 &&\times \left.  \mbox{sign}\left(\varepsilon_i + \frac{m''(x)}{2}(x_i-x)^2 + \frac{m'''(x)}{3!}(x_i-x)^3 - \frac{c_0}{\sqrt{nh}}- \frac{c_1(x_i-x)}{\sqrt{nh^3}}\right) K_h(x_i - x) \ge 0 \right)	 \nonumber \\
		&=& P \left(V_j +\frac{1}{h^j}\sqrt{\frac{h}{n}} \sum_{i = 1}^n (p-1)|\varepsilon_i|^{p-2}\left(\frac{m^{(2+j)}(x)}{(2+j)!}(x_i-x)^{2+2j} -\frac{c_j(x_i-x)^{2j}}{\sqrt{nh^{1+2j}}}\right) K_h(x_i - x) \ge 0 \right) \nonumber\\ %; j = 0, 1
	%	&& \quad V_1 +\frac{1}{\sqrt{nh}} \sum_{i = 1}^n (p-1)|\varepsilon_i|^{p-2}(\frac{m'''(x)}{3!}(x_i-%x)^4 -\frac{c_1(x_i-x)^2}{\sqrt{nh^3}}) K_h(x_i - x) \ge 0) \nonumber \\
		&=& P\left(V_j + (p-1)E[|\varepsilon_1|^{p-2}]\left(\frac{m^{(2+j)}(x)}{(2+j)!} \mu_{2 + 2j} f(x) \sqrt{nh^{5 + 2j}}-\mu_{2j}(K)f(x)c_j\right) \leq 0; j = 0, 1\right) \nonumber \\
%		&& \quad V_1 +(p-1)E[|\varepsilon_1|^{p-2}](\frac{m'''(x)}{3!}\mu_4f(x)\sqrt{nh^7}-f\mu_2c1)\le 0 %) \nonumber \\
		&=& P \left(\frac{V_j + (p-1)E[|\varepsilon_1|^{p-2}] m^{(2+j)}(x)\sqrt{nh^{5+2j}}\mu_{2+2j}(K)f(x)}{(p-1)(2+j)! E[|\varepsilon_1|^{p-2}]\mu_{2j}(K) f(x)} \leq c_j;  j = 0, 1\right)\nonumber 
		%\\
	%	&& \quad \frac{V_1+ (p-1)E[|\varepsilon_1|^{p-2}] m'''(x)/3! \sqrt{nh^7}\mu_4 f(x)}{(p-1)E[|\varepsilon_1|^{p-2}]f(x)\mu_2} \le c_1 ) \nonumber		
	\end{eqnarray}
\end{small}
Therefore,
$\sqrt{nh}(\widehat{\beta_0} -\beta_0)$ converges to the same limit as $\frac{V_0 + f(p-1)E[|\varepsilon_1|^{p-2}] m''(x)/2\sqrt{nh^5}\mu_2}{f(p-1)E[|\varepsilon_1|^{p-2}]}$ so $\widehat{\beta_0}$ is asymptotically normal with mean  $m(x) + \frac{h^2}{2} \mu_2(K)m''(x)$ and variance $\frac{R(K)\mu_{2p-2}(|\varepsilon|)}{f(x)(p-1)^2 \mu_{p-2}(|\varepsilon|)}$.

Also, 
$\sqrt{nh^3}(\widehat{\beta_1} - \beta_1)$ is asymptotically normal with the same limit distribution as $\frac{V_1}{(p-1)E[|\varepsilon|^{p-2}]f(x)\mu_2}+\frac{m'''(x)\sqrt{nh^7}\mu_4}{3!\mu_2}$, that is, $N\left(\frac{m'''(x)\sqrt{nh^7}\mu_4}{3!\mu_2}, \frac{\mu_2^2(K^2)E[|\varepsilon|^{2p-2}]}{f(x)\mu_2(K)(p-1)^2 \,u_{p-2}^2(|\varepsilon|)}\right)$ so $\widehat{\beta_1}$ is asymptotically normal with mean $m'(x)+m'''(x)/3!h^2\mu_4(K)/\mu_2(K)$ and variance $\frac{\mu_2^2(K^2)E[|\varepsilon|^{2p-2}]}{nh^3f(x)\mu_2(K)(p-1)^2 \mu_{p-2}^2(|\varepsilon|)}$.

Asymptotic independence of $\widehat{\beta}_0$ and $\widehat{\beta}_1$ then follows from Lemma
 \ref{lem:clt}.  
	\end{enumerate}
\end{proof}



\section{Bandwidth Selection}\label{sec:bw}
Our bandwidth selection method leverages the availability of good bandwidth choices for LLS regression ($h_2$).   Specifically, we obtain the value for $h_2$ from the method outlined by \citet{ruppert1995effective} which is  an effective approach for bandwidth selection in LLS regression. \par

Referring to the remarks made in Section \ref{theory}, we can establish that the relationship expressed in equation (\ref{eq:hp_eps}) remains valid for the optimal bandwidth in local polynomial $L_2$-norm and $L_p$-norm regression. Given that MSE combines the squared bias and variance of a model, we can find an MSE-optimal
bandwidth for local $L_p$-norm regression by differentiating the MSE with respect to $h$ and solving the resulting equation.   The optimal value $h_p$ satisfies
\begin{equation}
	h_p^5 = \frac{E[|\varepsilon_1|^{2p-2}]}{E[|\varepsilon_1|^{p-2}]^2 (p-1)^2 E[|\varepsilon_1|^2]} h_2^5.
	\label{eq:hp_eps}
	\end{equation}

Adapting moment properties derived by \citet{giacalone2020combined}, we can also demonstrate that the following holds  when errors follow the GED.
\begin{equation}
	h_p^5 = \frac{\Gamma(\frac{1}{p})^2 \Gamma(\frac{2p-1}{p})}{\Gamma(\frac{p-1}{p})^2\Gamma(\frac{3}{p}) (p-1)^2}h_2^5.
	\label{eq:hp_gamma}
	\end{equation}

\section{Estimating P}\label{sec:p}

Building upon the outcomes of a simulation study by \citet{mineo2003estimation} that highlights the most effective approach for estimating the shape parameter $p$ relies on the utilization of Generalized Kurtosis ($\kappa$), we initially employed the formula given by \citet{money1982linear} to gauge $p$ estimation. The authors of that work showed that if the kurtosis of an error distribution is known or can be estimated, then using formula (\ref{eq:p}) will yield good regression estimates for a wide variety of unknown error distributions.
\begin{equation}\label{eq:p}
	\hat{p} = \frac{9}{\kappa^2}+1 \hspace{1cm} 1\le p < \infty
\end{equation}
We refer to this method as the $K$ method. We conducted a simulation study involving a large range of $p$ values, from very heavy-tailed ($p = 1$) to thin-tailed distributions ($p = 20$). For each population,
1000 samples were generated and the corresponding $p$ values were estimated using $K$ method. We observed that as $p$ gets larger, 
 the estimated kurtosis ($\kappa$) stabilizes and fluctuates moderately at values slightly less than 2.0, leading to constrained and biased estimates of $p$, as shown in figure \ref{fig:comp_p}. This limitation is consistent with other moment-based methods, which become unreliable when the underlying error distribution deviates from their assumptions.

This leads us to consider another method for estimating $p$ which is expected to work better, especially when $p$ is supposed to be large. We will refer to this method as the $Q$ method. Our proposed $Q$ method completely removes the reliance on moments by estimating $p$ directly from residual distributions. It utilizes residuals from a fitted model coming from LLS. It determines $p$ by regressing various quantiles for candidate G.E.D, derived from a sequence of potential $p$'s, against the residuals, as expressed in the equation below:
\[q = \beta q_{p} +\varepsilon,\]
where $q$ are the quantiles of the residual, and $q_{p}$ are quantiles from GED with shape parameter $p$. The $p$ that minimizes the $L_2$-norm error, i.e.  \(\sum_{i=1}^{n}(q_i - \hat{\beta} q_{i(p)})^2\),  renders our selected value of $p$. Our method is detailed in Algorithm \ref{alg:estp} in the Appendix.\par
Using the same simulation study, we estimated $p$ by $Q$ method. The results illustrated in figure \ref{fig:comp_p} reveal the $Q$ method reduced systematic errors. These outcomes substantiate the assertion that the $Q$ method excels in comparison to $K$ method, particularly when handling larger $p$ values. 

\begin{figure}[h!]
	\begin{center}

		\includegraphics[scale=0.55]{figure/compare_p}
		\caption{Comparison of the estimated $p$ values by two methods. The results are obtained by averaging 1000 simulations for sample size 100, for varying $p \in [1,20]$.}
		\label{fig:comp_p}
	\end{center} 
\end{figure}

 In summary, our fitting method includes three steps:
\begin{enumerate}
\item We initially determine the optimal bandwidth $h_p$. 
\item Employing $p=2$ and $h_p$, we calculate $\hat{p}$ from the residuals using the $Q$ method.
\item We then estimate the local $L_p$-norm regression curve by minimizing (\ref{eq:lc}) or (\ref{eq:llp}). 
\end{enumerate}


\section{Simulation Studies and Examples}\label{sec:sim}
We evaluate the performance of our proposed method, particularly local linear $L_p$ norm estimator (LLP), on both simulated and real-life data. While the choice of kernel is known to be of less importance in classical kernel regression analysis, we employ Gaussian kernel function throughout our experiments.\par
\subsection{Simulation Studies}
For one-dimensional data, we evaluate the performance LLP regression under four different error distributions: uniform, triangular, symmetric bimodal, and GED with shape parameters $p \in [1,10]$. We systematically assess LLP across these distributions by simulating 1000 replicates for each of four target functions and three sample sizes ($n = 50, 100, 200$). The design points ($x$) are randomly drawn from a uniform distribution over $[0,1]$.\par 
To compare the performance of LLS and LLP estimators in terms of Mean Squared Error (MSE). We reported MSE values represent the average over 1000 simulations. To mitigate boundary effects from skewing the results, we restrict our evaluation on the interval $[0.05, 0.95]$. The target regression functions are as follows:
\begin{enumerate}
	\item $m(x) = \sin(x)$,
	\item $ m(x) = x+ 2^{-16x^2}$,
	\item $ m(x) =\sin(2x) + 2^{-16x^2}$,
	\item $ m(x) = 0.3e^{-4(x+1)^2} + 0.7e^{-16(x-1)^2}$
\end{enumerate}

\subsection{Results}

Figure \ref{fig:plots} represents a comparison of MSEs of LLS and LLP as per the simulation outcomes for all four target functions. As anticipated, the performance of nonparametric regression methods generally improves with increasing sample size. Our findings indicate that our method consistently outperforms the LLS  across three distinct sample sizes, particularly for higher values of $p$. Conversely, when the estimated value of $p$ is close to 2, our method performs similarly to LLS, as expected for data distributions that closely resemble the normal distribution. Refer to the Appendix B for results of other error distributions.
