\section{Algorithms} \label{App:algs}

We employed the \textit{nlm()} function from the \textit{stats} package \citep{stats}. In cases where the derivative of the function is desired,  we can modify the algorithm to return \textit{estimate[2]} which yields the first derivative of the function, represented by $\beta_1$. \\
\begin{algorithm}[h] 
	\scriptsize
	\begin{algorithmic}  \label{alg:loclp}
		\Require {$x, y$ : sample data , 	$h$:  bandwidth , $xpoints$ : equally spaced data points, $lp$ : power,
			$order$ : Local constant(0) or local linear (1) }
		\Ensure { xpoints, estimated ypoints }
		\Function{Loc\_lp}{$x, y, h, xpoints ,lp, order$}
		\newline
		\State $ypoints$ : An array of length of xpoints
		\State $starting\_value = 0$
		\State $obj\_func1 \gets |y -\beta_0|^p K_h(x - xpoint)$
		\State $obj\_func2 \gets |y -\beta_0 -\beta_1(x - xpoint)|^p K_h(x - xpoint)$
		\newline
		\For{$i \in 1 : length(xpoints)$}
		\State $ xpoint = xpoint[i]$
		\If{$order$ == 0}
		\State $starting\_value = mean(y[|x-xpoint|<2*h])$
		\State $ypoints[i] = nlm(obj\_func1,start\_value)\$estimate[1]$
		\ElsIf {$order$ == 1}
		\State $xx = x- xpoint$
		\State $b = lm( y ~ xx, weights = dnorm(xx, sd = h) )$
		\State $starting\_value = coef(b)$
		\State $ypoints[i] = nlm(obj\_func2, start\_value)\$estimate[1]$
		\EndIf
		\EndFor
		\State \Return { $xpoints, ypoints$}
		\EndFunction
	\end{algorithmic}
	\caption{Local Polynomial $L_p$ Norm Regression}
	\label{alg:llp}
\end{algorithm}

\begin{algorithm}
	\caption{Estimating P }\label{alg:estp}
	\scriptsize
	\begin{algorithmic}
		\Require{$resid$ :residuals of the fitted model by least-squares }
		\Ensure{$estimated$ $p$}
		\Statex
		\Function{EstimateP}{$resid$}
		\State $p$:  A list of potential p in range of [1,20]
		\State $n$ : size of $resid$ 
		\State $y.q$ : sorted residuals
		\State $e_{norm}$ : an empty numeric vector of length $p$ 

		\For{$i \in 1 : length(p)$}
		\State  $ normp.q = qnormp(ppoints(n), p = p[i]) $ 
		\State $ normp.QR = qr(normp.q)$
		\State $ Q = qr.Q(normp.QR, complete = TRUE)$
		\State $ eps = t(Q[,-1])\%*\% y.q $
		\State $e_{norm}[i]= norm(eps)$
		\EndFor
		\State \Return { $p[i]$ which gives the minimum $e_{norm}$}
		\EndFunction
	\end{algorithmic}
\end{algorithm}

\begin{algorithm}	
	\scriptsize
	\begin{algorithmic}
		\Require{$res$ : residuals from fitted LLS , $h_2$:  LLS bandwidth , $p$ : estimated shape parameter}
		\Ensure{$optimum$ $bandwidth$}
		\Statex
		\Function{FindBW}{$res, h_2, p$}
		\State $h_p = 0$
		\State $h_p= \left(\frac{mean(|res|)^{2p-2}}{(p-1)^2 mean(|res|^{p-2})^2 mean(res^2)}\right)^{1/5}\times h_2$

		\State \Return { $h_p$}
		\EndFunction
	\end{algorithmic}
	\caption{Bandwidth Selection Algorithm}
	\label{alg:bw}
\end{algorithm}

