\section{A model of ultra--sparse connected random graphs}\label{sec:graph}

Here, we introduce a model of sparse
random graphs on $n$ vertices. The intuition behind our choice of model is described in Section \ref{sec:overview}. 
For the remainder of this section, let $1\leq M\leq n/2$ be an integer parameter that will be chosen later.

\subsection{Matchings}
Recall that a matching $\calM$ on $[n]$ is a subset $\calM \subset \{\{i,j\} \subset [n]\}$ with $e \cap e' = \emptyset$ for all $e \neq e' \in \calM$. 
It will be very useful to take the equivalent, alternative view of matchings as functions $\calM:[n] \to [n] \cup \{\emptyset\}$, where $\calM(i) = j$ if $i$ is matched to $j$, and $\calM(i) = \emptyset$ if $i$ is not matched (so that $\calM$ acts as an involution on ${\rm Image}(\calM)\setminus\{\emptyset\}$). The purpose of this modified notation is to provide a rigorous framework for describing an edge--exposure filtration on a random matching. 

\begin{definition}[Matchings]
    Say that a function $\calM:[n] \to [n] \cup \{\emptyset\}$ is a \textit{matching} if, for all $i \in [n]$ with $\calM(i) \neq \emptyset$, it holds that $i = \calM(\calM(i))$. Note that this implies $|\calM^{-1}(j)| \le 1$ for all $j \in [n]$. We also define the \textit{size} of a matching $\calM$ is given by:
    \[
        |\calM| := \frac{1}{2}\,|\{i \in [n]\,:\, \calM(i) \neq \emptyset\}|\,.
    \]
    Moreover, the set of all matchings on $[n]$ of size $M$ will be denoted by $\Pi := \Pi([n],M)$. Finally, define the edge--set of a matching by $E(\calM) := \{\{i,j\} \subset [n]\,:\, \calM(i) = j\}$.
\end{definition}

The advantage of treating matchings as functions becomes apparent when dealing with partially revealed matchings. For any $I \subset [n]$, let $\calM|_I$ denote the restriction of $\calM$ to the domain $I$. 

\begin{definition}[Partially constructed matchings]
    Say that a function $\calM_0: I \to [n] \cup \{\emptyset\}$, with domain $I \subset [n]$, is a \textit{partially constructed matching} if there is some $\calM \in \Pi$ with $\calM_0 = \calM|_I$. Moreover, for any such $\calM \in \Pi$ satisfying this condition of $\calM_0 = \calM|_I$, we say that $\calM_0$ is a partial construction of $\calM$. The size of a partially constructed matching $\calM_0$ with domain $I$ is given by:
    \[
        |\calM_0| = \frac{1}{2}\,|\{i\in I\,:\, \calM_0(i) \neq \emptyset \}\cup \mathrm{Image}(\calM_0) \setminus \{\emptyset\}|\,.
    \]
    Finally, for any partially constructed matching $\calM_0$, define the set of partial completions of $\calM_0$ by:
    \[
        \Pi(\calM_0) := \{\calM' \in \Pi \,:\, \calM_0 \text{ is a partial construction of } \calM'\}\,.
    \]

\end{definition} 

Note that the formula supplied for $|\calM_0|$ is consistent with the standard notion of the size of a standard partial matching, which corresponds to counting the number of constructed edges. However, let us highlight the key difference between our definition of partially constructed matchings versus the standard notion of partial matchings. As we allow matchings to take on the value $\emptyset$, $\calM|_I$ can determine both edges as well as ``non--edges'' of $\calM$. 

Finally, we record some standard facts about uniformly random matchings, translated into our notation. 
\begin{lemma}[Partial completions of matchings]\label{prop:matching}
    Let $\calM_0$ be a partially constructed matching with domain $I \subset [n]$ and size $|\calM_0| = k \le M$. Let $\calM$ be a uniform random matching from $\Pi$. The following hold:
    \begin{enumerate}
        \item Conditioned on $\{\calM \in \Pi(\calM_0)\}$, it holds that $\calM$ is uniformly distributed on $\Pi(\calM_0)$.
        \item Let $!!$ denote odd factorial and define $J := \{w \in I^c\,:\, w \not \in \mathrm{Image}(\calM_0) \}$. Then,
        \[  
            |\Pi(\calM_0)| = \binom{|J|}{2(M-k)}(2(M-k))!!\,.
        \]
        \item Let $S \subset J$, where $J$ is defined above. 
        If $|S| \le M$ and $|J| > 4M$, then for every 
        $\mu \geq 2(M-k)|S|/|J|$, we have
        \[
            \PP{|\{w \in S\,:\, \calM(w) \neq \emptyset\}| \ge 12 \,\mu\,\big|\,\calM \in \Pi(\calM_0)} < \frac{2}{2^{\mu}}\,.
        \]
    \end{enumerate} 
\end{lemma}

\begin{remark}
Conditioned on $\{\calM \in \Pi(\calM_0)\}$,
it is natural to expect that the partial completion $\calM$
would typically ``choose'' $\Theta(|S|/|J|)\cdot (M-k)$ edges
incident to $S$.
The last assertion of the above statement provides
a (one-sided) quantification of that property.
\end{remark}

\begin{proof}
    We prove the claims in order. By construction of $\calM$ as a uniform matching, we have for any $A \subset \Pi(\calM_0)$,
    \begin{align*}
        \PP{\calM \in A\,\big|\, \calM \in \Pi(\calM_0)} = \frac{\PP{\calM \in A,\,\calM \in \Pi(\calM_0)}}{\PP{\calM \in \Pi(\calM_0)}} &= \frac{|A \cap \Pi(\calM_0)|}{|\Pi|} \times \frac{|\Pi|}{|\Pi(\calM_0)|} = \frac{|A|}{|\Pi(\calM_0)|}\,.
    \end{align*}
    In the last equality, we have used the assumption that $A\subset \Pi(\calM_0)$. This proves the first claim. 

    Towards developing the second claim, we use the standard view of matchings as collections of vertex--disjoint edges. The map $\calM \mapsto E(\calM)$ induces a bijection between $\Pi(\calM_0)$ and the set of possible ways to select $M-k$ vertex--disjoint edges from the complete graph on $[n]$, using only vertices from $J \subset [n]$ as endpoints. There $\binom{|J|}{2(M-k)}$ ways to choose the endpoints of the $M-k$ edges, and each such selection yields exactly 
    \[
        \frac{(2(M-k))!}{2^{M-k}(M-k)!}= (2(M-k))!!
    \]
    unique ways of pairing the $2(M-k)$ vertices. This establishes the second claim. 

    Finally, we turn to the third claim. Reusing the above bijection, the image of the set 
    \[
        \big\{\calM \in \Pi(\calM_0)\,:\,|\{w \in S\,:\, \calM(w) \neq \emptyset\}| \ge t \big\}
    \]
    is in bijection with the set of possible ways to select $M-k$ vertex--disjoint edges from the complete graph on $[n]$, using only vertices from $J \subset [n]$ as endpoints, with the additional constraint that at least $t$ endpoints are in $S$. 

    Consider choosing these $2(M-k)$ vertices one at a time. By the assumptions that $|J| > 4M$ and $|S| \leq M$, we have $|J| - 2(M-k) > |J|/2$. Thus, for any $i \in [2(M-k)]$, uniformly over all possible choices of  the first $i-1$ chosen vertices, the fraction of remaining vertices in $|S|$ to remaining vertices in $|J|$ is bounded above by $2|S|/|J|$. Thus, for any $y > 0$, combining the first two claims yields:
    \begin{align*}
        \PP{|\{w \in S\,:\, \calM(w) \neq \emptyset\}| \ge y \, \mu\,  \,\big|\,\calM \in \Pi(\calM_0)} 
        &\le \sum_{t \ge y \, \mu} \binom{2(M-k)}{t} \Big(\frac{2|S|}{|J|}\Big)^t \\ 
        &\le \sum_{t \ge y \, \mu} \Big( \frac{2(M-k)e}{t}\,\frac{2|S|}{|J|}\Big)^t\,.
    \end{align*}
   Note the trivial bounds $|S| \le |J|$ and $2(M-k) \le |J|$. The former holds since $S \subset J$, and the latter is an obvious necessary condition for $\Pi(\calM_0)$ to be non--empty, which is implied by $\calM_0$ being
    a valid partially constructed matching. Finally, set $y := 12 > 4e$ and recall $\mu \geq 2(M-k)|S|/|J|$. For all $t \ge \mu\, y$,
    \[
        \frac{2(M-k)e}{t} \frac{2|S|}{|J|} \le \frac{2e}{y} < \frac{1}{2}\,.
    \]
    Returning to the previous computation, the third claim is established: 
    \begin{align*}
        \PP{|\{w \in S\,:\, \calM(j) \neq \emptyset\}| \ge y \, \mu\,  \,\big|\,\calM \in \Pi(\calM_0)} 
        \le \sum_{t \ge y \, \mu} 2^{-t} \le \frac{2}{2^{\mu}}\,.
    \end{align*}
\end{proof}




\subsection{Graph model}
We are ready to introduce the graph model that will be considered for the rest of the article. 
\begin{definition}\label{def:graph}
Let $\calM$ be a matching of size $M$, drawn uniformly from $\Pi := \Pi([n],M)$. Let $\bm{\pi}$ be a uniform random permutation of $[n]$, independent of $\calM$, which generates a uniformly random Hamiltonian cycle $\calC = ([n],\big\{\{\bm{\pi}(i),\bm{\pi}({i\;\rm{mod}\;n}+1)\},
1\leq i\leq n\big\})$.
Define the $(\pi, \calM)$--measurable random {\it multigraph}
${\bf G}=([n],E(\bm{\pi},\calM; M))$ by 
$$
E(\bm{\pi},\calM; M):= E(\calM) \cup E(\calC),\,
$$
where $\cup$ denotes concatenation, i.e., a union in the sense of multisets.
\end{definition}


Observe that the multiset $E(\bm{\pi}, \calM; M)$
has size $n+M$ everywhere on the probability space,
and that the degrees of all vertices of ${\bf G}$ take values $2$ and $3$.
The principal difference between ${\bf G}$ and a 
random graph with a prescribed degree sequence (from either the configuration
or uniform model) is that ${\bf G}$ is connected
everywhere on the probability space, i.e, the graph distance
on ${\bf G}$ is a valid metric. The rest of the section is devoted towards developing the following claim:

\begin{proposition}[Slow volume growth for vertex neighborhoods]\label{lem:specialgraph}
For every $\varepsilon \in (0,\frac{1}{10}]$ there are $\te>0$
and $\tn\in\NN$ depending only on $\varepsilon$ with the following
property. Let $n\geq \tn$, and let $M$ satisfy 
$n^{1-\te}\leq M\leq n/100$.
Then with probability at least $1-\exp(-n^{\te})$, the graph
${\bf G}$ satisfies:
for every $v\in[n]$ and every $t \in [n^\varepsilon, n^{2\varepsilon}]$,
$$
\min\big\{x>0:\,|\{w\in[n]:\;d_{\bf G}(v,w)\leq x\}|\geq t\big\}
\geq \frac{\cgraph\,n\log t}{M},
$$
where $\cgraph\in(0,1/10]$ is a universal constant (independent of $\varepsilon$).
\end{proposition}

The requirements $t \le n^{2\varepsilon}$ and $\varepsilon < .1$ are purely for technical convenience and can easily be lifted. The proof idea is to conduct a breadth--first search of the neighborhood of a vertex $v$ with an appropriate edge--exposure filtration, and then inductively bound the growth of the neighborhood using martingale concentration bounds. In order to make this rigorous, we introduce some basic conventions:

\begin{definition}[Convention: vertex neighborhoods]\label{def:ball}
    For a graph $G$ on $[n]$, define:
    \begin{align*}
        B_G(v,\ell) &= \{w \in [n]\,:\, d_G(v,w) \le \ell\}\,, \\
        S_G(v,\ell) &= \{w \in [n]\,:\, d_G(v,w) = \ell\}\,.
    \end{align*}
    Additionally, set $B_G(v,0) = S_G(v,0) = \{v\}$.
\end{definition}
Note in particular that $B_G(v,\ell)$ is  defined as a set of vertices, \textit{not} as an induced subgraph.

\medskip

Without any attempt to optimize, we define the following parameters:
\begin{align*}
    C &= 50 \\
    \cgraph &= 1/(20 C) \\
    \te &= \varepsilon / 100 \\
    \tn &= \min\{n'\,:\, \forall\, n > n',~ \log(n) < n^{\eps/10^5}\}\,.
\end{align*}
As desired, $\tn$ and $\te$ depend only on $\eps$ and $\cgraph$ is universal. \\



For $v \in  [n]$, let $\calF_\ell(v)$, $\ell\geq 1$, be the filtration generated by $\calC$ and the radius $\ell-1$ vertex neighborhood of $v$
in $\bG$:
\[
    \calF_\ell(v) := \sigma\Big(\calM|_{ B_{\bG}(v,\ell-1)}, \, \bp \Big)\,.
\]
As a key feature of this definition, observe that $B_{\bG}(v,\ell)$ is $\calF_\ell(v)$--measurable for every $\ell\geq 1$. Indeed, $\calM|_{ B_{\bG}(v,\ell-1)}$ and $\bp$
together specify all edges of ${\bf G}$ incident to $B_{\bG}(v,\ell-1)$, and we have defined $B_{\bG}(v,\ell)$ as the set of vertices at distance at most
$\ell$ from $v$.\footnote{Note that the induced subgraph of ${\bf G}$ on 
$B_{\bG}(v,\ell)$ does not have to be $\calF_\ell(v)$--measurable.} 


For two vertices $v$ and $w$ of $\bG$, we write $v \sim_\calC w$ to denote that $v$ and $w$ are adjacent in the graph $([n],\calC)$, i.e., $v$ and $w$ are consecutive vertices in the cycle $\calC$. Similarly, for a subset $W \subset [n]$, write $v \sim_\calC W$ if $v \sim_\calC w$ for some $w \in W$. The negations of these properties are indicated by $\not \sim_\calC$. For each $\ell \ge 1$, define the following $\calF_\ell(v)$--measurable set of vertices $\bN_\ell(v) \subset B_{\bG}(v,\ell)$,
\[
    \bN_\ell(v) := \{v \in S_{\bG}(v,\ell)\,:\, v \not\sim_\calC B_{\bG}(v, \ell-1)\}\,.
\]
As a convention, let $\bN_0(v) := \{v\}$. We now isolate the main technical component of the proposition:
\begin{lemma}\label{prop:growth}
Let $1\leq M\leq n/100$.
    For any $v \in [n]$, for all $1 \le \ell \le \cgraph\,(n/M)\log t$, 
    \begin{equation}\label{eq:N-growth}
        \PP{\forall\, \ell' \le \ell\,:\,|\bN_{\ell'}(v)| \leq \max\Big(\trunc,\,  C\,\frac{M}{n}\sum_{j=0}^{\ell'-1} |\bN_j(v)| \Big) } \geq 1 - \ell \, \exp(-\tail)\,.
    \end{equation}
    Moreover, for any $\ell \ge 1$, 
    \begin{equation}\label{eq:B-growth}
        \PP{|B_{\bG}(v, \ell)| \le 2\sum_{j=0}^{\ell}|\bN_j(v)|(\ell-j+1)} = 1\,.
    \end{equation}
\end{lemma}
Let us check that \cref{prop:growth} implies \cref{lem:specialgraph}.

\begin{proof}[Proof of \cref{lem:specialgraph}]
Define the following events:
    \begin{align*}
        \calE_\ell &:= \bigcap_{v \in [n]} \calE_\ell(v),\quad \ell\geq 1; \\
        \calE_\ell(v) &:= \bigcap_{1\le \ell' \le \ell} \cb{|\bN_{\ell'}(v)| \le \max\Big(\trunc,\, C\,\frac{M}{n} \sum_{j=0}^{\ell'-1} |\bN_j(v)| \Big) }\,.
    \end{align*}
    We then have the following inclusions:
    \begin{align}
        \calE_\ell(v) &\subset \bigcap_{1\le \ell' \le \ell} \cb{\sum_{j=0}^{\ell'} |\bN_j(v)| \le \max\Big((\ell'+1)\,\trunc,\, \Big(1 + C\,\frac{M}{n}\Big) \sum_{j=0}^{\ell'-1} |\bN_j(v)| \Big)  } \nonumber \\
        &\subset \bigcap_{1\le \ell' \le \ell} \cb{
        \sum_{j=0}^{\ell'} |\bN_j(v)|  \le (\ell'+1)\,\trunc (1 + C\, M/n)^{\ell'} \le (\ell'+1)\,\trunc\,e^{C\, (M/n)\, \ell'} } \,. \label{eq:N-growth-total} 
    \end{align}
    Recall our choices for the parameters $C$, $\te$, $\tn$, and $\cgraph$. 
    As a consequence of \eqref{eq:B-growth}, for any $v \in [n]$ and for any $\ell' \le \ell$, it holds almost surely within the event $\calE_{\ell}(v)$: 
    \begin{equation}\label{eq:ball-UB}
        |B_\bG(v,\, \ell')| \le  2(\ell'+1)^2\,\,\trunc 
        \,e^{C\, (M/n)\, \ell'}
        \le 2\, (\ell+1)^2\, \trunc\,  \exp(\,C \, \cgraph\, \log t) \le n^{\eps/5},
    \end{equation}
    where we used the bounds $\ell\leq n^{\te}$ and $t\leq n^{2\eps}$
    given by the assumptions on parameters.
    In total, a union bound applied to \eqref{eq:N-growth} over $v \in [n]$ and $\ell \in [\lfloor \cgraph (n/M)\log t)\rfloor]$ yields:
    \begin{align*}
        \PP{\forall v \in [n],\, |B_\bG(v,\, \lfloor \cgraph (n/M)\log t)\rfloor| \le n^{\eps}} \ge \PP{\calE_{\lfloor \cgraph (n/M)\log t)\rfloor}} &\ge 1 -  n^2\,\exp(-\tail) \\
        &\ge 1 -  \exp(-n^{\te})\,.
    \end{align*}
    This completes the proof.

\end{proof}

\begin{proof}[Proof of \cref{prop:growth}]
    Denote graph distance with respect to the cycle graph $\calC$ by
    $d_\calC(\cdot,\cdot)$. We claim that the following inclusions hold almost surely, for all $\ell \ge 0$.
    \begin{enumerate}
        \item[H1.] 
        \[
            B_{\bG}(v,\ell) \subset \bigcup_{j = 0}^\ell B_\calC(\bN_j(v), \, \ell - j)\,,
        \]
        \item[H2.]
        \[
            |S_\bG(v,\ell) \setminus \bN_\ell(v)| \le 2 \sum_{j=0}^{\ell-1} |\bN_j(v)| \,.
        \]
    \end{enumerate}
    \textbf{Proofs of (H1) and (H2)}. Both hypotheses are immediate for $\ell = 0$ upon recalling the conventions in \cref{def:ball} and $\bN_0(v) := \{v\}$. So, assume for the sake of induction that both (H1) and (H2) hold for all $\ell'$ with $0 \le \ell'\le \ell$, for some  $\ell \ge 0$. Then:
    \begin{align*}
        B_\bG(v,\ell+1) &= \bN_{\ell+1}(v) \cup B_{\calC}(B_\bG(v,\ell),1) \\ 
        &\subset B_\bG(\bN_{\ell+1}(v),0) \cup B_{\calC}\Big(\bigcup_{j = 0}^\ell B_\calC(\bN_j(v), \, \ell - j) ,1 \Big) \\
        &\subset B_\bG(\bN_{\ell+1}(v),0) \cup \bigcup_{j = 0}^\ell B_\calC(\bN_j(v), \, \ell - j+1) \\
        &= \bigcup_{j = 0}^{\ell+1} B_\calC(\bN_j(v), \, (\ell+1) - j)\,.
    \end{align*}
    The second line uses the inductive hypothesis. This establishes (H1) for all $\ell \ge 0$. Towards developing (H2), consider the decomposition:
    \begin{align*}
        S_\bG(v,\ell+1) \setminus \bN_{\ell+1}(v) 
        &= \{v \in B_\bG(v,\ell)^c\,:\, v \sim_\calC \bN_\ell(v)\} \cup \{v \in B_\bG(v,\ell)^c\,:\, v \sim_\calC S_\bG(v,\ell)\setminus \bN_\ell(v)\} \,.
    \end{align*}
    A cycle is 2-regular. For each $w \in S_\bG(v,\ell)\setminus \bN_\ell(v)$, we have $w \sim_\calC B_\bG(v,\ell-1)$, hence there is at most one edge in $\calC$ connecting $w$ to $B_\bG(v,\ell)^c$. Similarly, for $w \in \bN_\ell(v)$, there are trivially at most two edges in $\calC$ connecting $w$ to $B_\bG(v,\ell)^c$. Combining these observations and then applying the inductive hypothesis yields:
    \begin{align*}
        |S_\bG(v,\ell+1) \setminus \bN_{\ell+1}(v)| 
        &\le 2|\bN_\ell(v)| + | S_\bG(v,\ell)\setminus \bN_\ell(v)| \le 2 |\bN_\ell(v)| + 2\sum_{j = 0}^{\ell-1} |\bN_j(v)|= 2\sum_{j = 0}^{\ell} |\bN_j(v)| \,.
    \end{align*}
    This establishes (H2). \\


    \textbf{Proof of \eqref{eq:N-growth} and \eqref{eq:B-growth}}. Begin by noting that (H1) implies \eqref{eq:B-growth}. Indeed, almost surely,
    \[
         |B_{\bG}(v,\ell)| \stackrel{\text{\tiny{(H1)}}}{\le}\big|\bigcup_{j = 0}^\ell B_\calC(\bN_j(v), \, \ell - j)\big| \le \sum_{j = 0}^\ell \sum_{w \in \bN_j(v)}\big| B_\calC( w, \, \ell - j)\big| \le \sum_{j = 0}^\ell \big|\bN_j(v)\big|\, \cdot 2\, (\ell-j+1) \,.
    \]




    Thus, it remains only to establish \eqref{eq:N-growth}. We proceed by way of induction. For $\ell = 1$, \eqref{eq:N-growth} holds with probability one, establishing the base case of this induction. 
    So, assume \eqref{eq:N-growth} holds for some $\ell \ge 1$. A crude bound on $|B_\bG(v,\ell)|$ will be needed. Letting $\calE_\ell(v)$ and $\calE_\ell$ be as in the proof of \cref{lem:specialgraph}, we claim:
    \begin{equation}\label{eq:ball-UB-restated}
        \calE_\ell(v) \subset \cb{|B_\bG(v, \ell)| < n^{\varepsilon/5}}\,.
    \end{equation}
   Using \eqref{eq:B-growth}, which we just established, this inclusion admits an identical proof to that of \eqref{eq:ball-UB}. We are ready to proceed with the inductive step. Define the following $\calF_\ell(v)$--measurable quantities: 
    \[
        \calM_{\ell} := \calM|_{B_\bG(v,\ell-1)}, \quad k := |\calM_{\ell}|,
    \]
    and note that $k\leq |B_\bG(v,\ell-1)|$ everywhere on the probability space.
    Towards matching the notation in Claim 3 of \cref{prop:matching}, define:
    \begin{align*}
        J &:= \{w \in B_\bG(v,\ell-1)^c\,:\, w \not \in \mathrm{Image}(\calM_{\ell})\} \,,\\
        S &:= \{w \in S_\bG(v,\ell)\,:\, w \not \in \mathrm{Image}(\calM_{\ell})\}\,.
    \end{align*}
    Both $J$ and $S$ are clearly $\calF_{\ell}(v)$--measurable. By construction, we have:
    \begin{equation}\label{eq:N-bound}
        |\bN_{\ell+1}(v)| \le |\{w \in S\,:\, \calM(w) \neq \emptyset\}|\,.
    \end{equation}
    We aim to bound the cardinality of the right--hand side via Claim 3 of \cref{prop:matching}. Using the trivial inclusion $S \subset S_\bG(v,\ell)$, we have 
    \begin{equation}\label{eq:S-bound}
        |S| \le |S_\bG(v,\ell)| \le |S_\bG(v,\ell) \setminus \bN_\ell(v)| + |\bN_\ell(v)| \stackrel{\text{\tiny{(H2)}}}{\le} 2 \sum_{j=0}^{\ell} |\bN_\ell(v)|\,.
    \end{equation}
    Consider the event partition
    $$
    \calE_\ell(v)=\calE_{\ell}'(v)\sqcup\calE_{\ell}''(v),
    $$
    where
    $$
    \calE_{\ell}'(v) := \Big\{\sum_{j=0}^{\ell} |\bN_j(v)| \le \trunc/2\Big\} \cap \calE_\ell(v);
    \quad
    \calE_{\ell}''(v) := \Big\{\sum_{j=0}^{\ell} |\bN_j(v)| > \trunc/2\Big\} \cap \calE_\ell(v),
    $$
    and note that both events are $\calF_{\ell}(v)$--measurable.
   Recalling the definition of $\calE_{\ell+1}(v)$, noting $|\bN_{\ell+1}(v)| \le |S|$ (since $\bN_{\ell+1}(v) \subset S$), and using \eqref{eq:S-bound}, we obtain
    \[
        \calE_{\ell}'(v) \subset \calE_{\ell+1}(v)\,. 
    \]
    Next, we treat the event $\calE_{\ell}''(v)$.
     The inclusion   
     \eqref{eq:ball-UB-restated} 
     implies the following crude bounds on $|J|$ and $|S|$ everywhere on $\calE_\ell(v)$:
    \[
        |J| \ge n - |B_\bG(v,\ell-1)|-|{\rm Image}(\calM_\ell)\setminus\{\emptyset\}| 
        \geq n-n^{\eps/5}-2M>\frac{24}{25}\,n>4M;
        \quad |S|\leq n^{\eps/5}<M.
    \]
    An application of Claim 3 of \cref{prop:matching} then yields almost surely for every $\calF_{\ell}(v)$--measurable parameter
    $\mu\geq \frac{2(M-k)}{|J|}|S|$:
    $$
    \ind_{\calE_\ell''(v)}\,\PP{|\{w \in S\,:\, \calM(w) \neq \emptyset) \}| \geq 12\mu \,\Big|\, \calF_{\ell}(v)} 
        \le  \ind_{\calE_\ell''(v)} \cdot 2\cdot 2^{-\mu}.
    $$
    Setting
    $$
    \mu:= \frac{2(M-k)}{|J|}\cdot 2 \sum_{j=0}^{\ell} |\bN_\ell(v)|\quad
    \mbox{everywhere on }\calE_\ell''(v)
    $$
    (relation \eqref{eq:S-bound} ensures
    that $\mu$ defined this way satisfies the above constraint)
    then yields
    \begin{equation}\label{eq:aux1}
    \ind_{\calE_\ell''(v)}\,\PP{|\{w \in S\,:\, \calM(w) \neq \emptyset) \}| \geq \frac{24(M-k)}{|J|}\cdot 2 \sum_{j=0}^{\ell} |\bN_\ell(v)| \,\Big|\, \calF_{\ell}(v)}
        \le  \ind_{\calE_\ell''(v)}\cdot \exp(-\tail),
    \end{equation}
    where we used that on the event $\calE_\ell''(v)$,
    $$
    \frac{2(M-k)}{|J|}\cdot 2 \sum_{j=0}^{\ell} |\bN_\ell(v)|
    \geq \frac{2(M-k)}{|J|}\cdot\trunc
    \geq \frac{2(M-n^{\eps/5})}{n}\cdot\trunc
    > n^{3\te}.
    $$
    Combining \eqref{eq:aux1} with \eqref{eq:N-bound} and the above estimate $|J|\geq \frac{24}{25}n$ yields that almost surely,
        \begin{align*}
        \ind_{\calE_\ell''(v)}\,\PP{|\bN_{\ell+1}(v)| >  \frac{25M}{n}\cdot 2\sum_{j=0}^{\ell} |\bN_j(v)|  \,\Big|\, \calF_{\ell}(v)} &\leq\ind_{\calE_\ell''(v)}\,\PP{|\bN_{\ell+1}(v)| \geq  \frac{24(M-k)}{|J|}\cdot 2\sum_{j=0}^{\ell} |\bN_j(v)|  \,\Big|\, \calF_{\ell}(v)} \\
        &\le \exp(-\tail).
    \end{align*}


    Finally, using the decomposition $\calE_\ell(v)=\calE_{\ell}'(v)\sqcup\calE_{\ell}''(v)$, we obtain:
    \begin{align*}
        &\PP{|\bN_{\ell'}(v)| >  \max\Big(\trunc,\,  C\,\frac{M}{n}\sum_{j=0}^{\ell'-1} |\bN_j(v)| \Big)\mbox{ for some $1\leq \ell'\leq \ell+1$} } \\
        &\le \PP{\calE_\ell(v)^c} + \PP{|\bN_{\ell+1}(v)| >  \max\Big(\trunc,\,  C\,\frac{M}{n}\sum_{j=0}^{\ell} |\bN_j(v)| \Big)\mbox{ and } \calE_\ell'(v)} \\
        &\quad + \PP{|\bN_{\ell+1}(v)| >  \max\Big(\trunc,\,  C\,\frac{M}{n}\sum_{j=0}^{\ell} |\bN_j(v)| \Big)\mbox{ and } \calE_\ell''(v)} \\
        &\le \ell \exp(-\tail) + 0 + \exp(-\tail) \\
        &= (\ell+1) \exp(-\tail)\,.
    \end{align*}
    The inductive hypothesis was used to bound $\PP{\calE_\ell(v)^c} \le \ell \exp(-\tail)$. This completes the induction step in verification of \eqref{eq:N-growth}, finishing the proof.
\end{proof}



\section{Construction of the discretization scheme}\label{sec:discretization}

The goal of this section is to produce a discretization $\hx:X^n \to \net$, where $X$ is a given finite-dimensional normed space and $\net$ is a discrete subset of the Cartesian product $X^n$ having both small cardinality and ``sufficient density.'' The construction presented below can be viewed as a  version of the classical net argument with advanced features provided through multiscaling and seeding. 
As we noted in the introduction, a related discretization scheme
first appeared in \cite{AT2024} to deal with {\it geometrical} embeddings of random graphs. Whereas the discretization presented here is not identical to the one in \cite{AT2024}, many similarities exist. For that reason, proofs of certain claims closely matching corresponding statements from \cite{AT2024} are moved to the appendix.

\medskip

{\bf Notation.}
For the remainder of this article, $\eps$ and $c_0$ are some fixed parameters, independent of $X$ and $n$, that are assumed to be sufficiently small. That is, $\eps \le \eps'$ and $c_0 \le c_{0}'$ for some positive universal constants $\eps'$ and $c_0'$ which do not depend on $X$ or $n$. Without making effort to optimize, the following choices suffice:
\begin{align*}
    \eps' &=  .1  \\
    c_0' &= .01 
\end{align*}
We also require an integer parameter $L\in [1,n^{1-\eps}]$, which will be fixed in \cref{thm:bilipschitz}. As $L$ and $X$ will only be varied in \cref{sec:bilipschitz}, one can view $L$ and $X$ as fixed parameters in \cref{sec:discretization};  dependencies on $L$ and $X$ will be suppressed wherever there is no ambiguity in order to lighten notation. 
Below, ``$n$ sufficiently large'' means $n \ge n_0$ for some function $n_0 := n_0(\eps, c_0)$. We emphasize that $n_0$ does not depend on the underlying normed space $X$.


A $d$--dimensional normed space $X$ will be always be viewed as the space $\RR^d$ endowed with a norm $\|\cdot\|_X$. The dimension $d$ of the space will always be assumed to satisfy
\begin{equation}\label{dcondition}
1\leq d\leq n^{\eps/4}.    
\end{equation}
The unit ball in $X$ will be denoted by $B_X$. More generally, a ball of radius $r$ centered at a point $y\in X$ will be denoted by $B_X(y,r)$.
Given a point $y\in X$ and a non-empty closed subset $A$ of $X$,
the $\|\cdot\|_X$--projection of $y$ onto $A$ is any point in $A$ with the minimal $\|\cdot\|_X$--distance to $y$.
Whenever projections of points onto subsets are not uniquely defined, a representative will be chosen arbitrarily. In what follows, $\vx$ will always denote an $n$-tuple of points $(x_1,\dots,x_n) \in (\RR^d)^n$. Occasionally, we will view $\vx$ as a multiset (i.e disregard the ordering).


\bigskip


\begin{definition}[Sparse $n$--tuples]\label{def:sparse}
    Let $\|\cdot\|_X$ be any norm in $\RR^d$, and let $\lambda>0$ be any parameter (possibly depending on $n$). Say
    that a tuple of points $\vx$ is {\it $\lambda$-sparse} if, for all $i\in[n]$, $\|x_i - x_j\|_X\le \lambda$ for less than $n^{\varepsilon}$ values of $j \in [n]\setminus \cb{i}$.
\end{definition}

As a rough interpretation of the above notion, an $n$--tuple is $\lambda$-sparse if for a vast majority of pairs of vectors, the distance between the vectors is greater than $\lambda$. In what follows, it will be crucial to us that the property is essentially preserved even if the threshold $\lambda$ is multiplied by a constant. Specifically, the parameter $L$ mentioned in passing above, is defined later in such a way that in any ball of radius $72\lambda$, there are at most $Ln^{\eps}$ other vectors (see 
\cref{def:scale} and \cref{lemma:scale-lb} below).


\begin{definition}[Domain]
Assume that $X$ is a normed space, and let $D,\lambda>0$ be parameters
satisfying
\begin{equation}\label{aksdjfnalkfnflks}
n^2\geq D\geq 2\lambda\geq 1.
\end{equation}
Let the domain $\tuples(D,\lambda)=\tuples(D,\lambda,X)$ of the discretization function be given by
\begin{equation}\label{eq:domain}
    \tuples(D,\lambda)=\tuples(D,\lambda,X) := \cb{\vx \in (B_{X}(0;\, D))^n\,:\, \vx \text{ is $\lambda$-sparse in $X$}}\,.
\end{equation}
\end{definition}

The discretization of $X$ will be based on a multiscale net-argument with
seeding.
Recall that an {\it $r$-net} on a set $A \subset \RR^{d}$ in $X=(\RR^{d},\|\cdot\|_X)$  is a collection of points $(y_i)_i$ so that for all $x \in A$, there exists $y_i$ with $\|x - y_i\|_X \le r$. We will always assume that the points $y_i$ are contained in $A$ for convenience. We introduce the following notation: 
\begin{definition}[Simple nets]
    Given $r>0$ and $y\in X$, define $\net(y, r; c_0r)$ as an (arbitrary) $c_0r$-net in $B_X(y; r)$ of minimum cardinality. Further, given a parameter $D>0$, let $\net_0=\net_0(D)$ denote an arbitrary $1$-net in $B_X(0; D)$ of minimum cardinality.
\end{definition}


\begin{definition}[Multiscale net]\label{def:mulitscale-net}
    For every integer $\ell$ we use the shorthand 
    \[
        r_\ell := 2^{\ell}\,.
    \]
    Let $X$ be a normed space, and let $D,\lambda>0$ be parameters satisfying \eqref{aksdjfnalkfnflks}. Define the {\it multiscale net} $\net=\net(D,\lambda)$ as:
    \[
        \net := \net_0(D) \cup \pa{ \bigcup_{y \in \net_0(D)}\; \bigcup_{\ell = \lfloor \log_2\lambda\rfloor+1}^{\lceil\log_2 (2D)\rceil} \net(y,\, r_\ell; c_0 r_\ell) } \,.
    \]
\end{definition}
In what follows, we will use points from $\net$ to approximate locations
of vertices in a graph embedding into $X$. A key technical idea is that it will suffice to roughly maintain the list of closest neighbors to each vertex under this approximate embedding, rather than attempting to maintain the actual pairwise distances between all vertices. This is a significant source of efficiency in the argument. Towards making this precise, we introduce the following definition.

\begin{definition}[Scale of separation]\label{def:scale}
    Given $\vx = (x_1,\dots,x_n) \in (\RR^{d})^n$ and a parameter
    $L\in [1,n^{1-\eps}]$,
    define the \textit{local scale of separation for $x_i$} by:
    \[
        \ell_i := \ell_i(\vx,X) = \min\cb{\ell \in \mathbb{Z}\,:\, \ba{\cb{j\in [n]\,:\, \|x_i-x_j\|_X \le r_\ell }} \ge L\,n^{\eps}}\,, \quad 
        1\leq i\leq n\,.
    \]
    Informally, for every $i$, the local scale of separation for $x_i$ is the logarithm of the radius of a ball in $X$ centered at $x_i$ containing about $n^{\eps}$ points $x_j$. We further write $\ell(\vx)=\ell(\vx,X)$ for the tuple $(\ell_i)_{i=1}^n$.
\end{definition}

\begin{remark}\label{boundsonell}
Note that whenever $\vx$ is $\lambda$-sparse then necessarily $2^{\ell_i}> \lambda$ for all $i \in [n]$.
Moreover, whenever $\vx\in (B_{X}(0,r))^n$ for some $r>0$, we must have $\ell_i\leq \lceil\log_2(2r)\rceil$ for all $i$.
In particular, for every $\vx=(x_i)_{i=1}^n\in\tuples(D,\lambda)$
    we have $\ell_i\in \{\lfloor \log_2\lambda\rfloor+1,\dots, \lceil\log_2(2D)\rceil\}$
    for all $i\leq n$.
\end{remark}



In the next proposition we define {\it seeds}, which are
small-cardinality subsets of $\vx$ that play a key role in the discretization scheme. A tuple $\vx$ will be embedded into simple (local) nets centered at the seeds.

\begin{proposition}[Existence of good seeds]\label{prop:seeds}
    Let $n$ be sufficiently large (independent of $X$). For any $n$--tuple $\vx$, and for each integer $\ell\geq 0$, there exists a multiset $\seeds_\ell := \seeds_\ell(\vx) \subset \vx$, with $|S_\ell| =\lfloor n^{1-\eps}\log^2 n\rfloor$ and the following property. For any component $x_i$ of $\vx$ with $\ell_i = \ell$, there exists $y \in \seeds_\ell$ with 
    \[
        \|y - x_i \|_X \le r_{\ell_i}\,.
    \]
\end{proposition}
\begin{proof}
    Fix $\vx$ and $\ell$. Let $\seeds_\ell$ be the collection of $\lfloor n^{1-\eps}\log^2 n\rfloor$ points selected independently uniformly at random from $\vx$ (viewed as a multiset). Let $z \sim \mathrm{unif}(\vx)$. For all $x_i \in \vx$, we have:   
    \begin{align*}
        \PP{\bigcap_{y \in S_\ell} \cb{\|y - x_i \|_X > r_\ell}} = \PP{\|z - x_i \|_X > r_\ell}^{\lfloor n^{1-\eps}\log^2 n\rfloor} \le \pa{1 - \frac{n^{\eps}}{n}}^{\lfloor n^{1-\eps}\log^2 n\rfloor} &= n^{-\omega(1)} \,.
    \end{align*}
    Taking a union bound over the $n$ possible values of $i$, it easily follows that with high probability (in particular, positive probability), our random selection of $\seeds_\ell$ has the desired property. Thus, by the probabilistic method, there must deterministically be some satisfactory realization of $\seeds_\ell$.
\end{proof}

\begin{definition}[Discretization]
    Let $D,\lambda>0$ be parameters satisfying \eqref{aksdjfnalkfnflks}, and let $L\in [1,n^{1-\eps}]$. The \textit{discretization scheme} is the map \[
        \hx := \hx(\vx): \tuples(D,\lambda,X) \to \net(D,\lambda)^n\,,
    \]
    constructed as follows. For each $\ell \in \{\lfloor \log_2\lambda\rfloor+1,\dots, \lceil\log_2(2D)\rceil\}$, construct $S_\ell$, as defined in \cref{prop:seeds}. Let $\hat \seeds_{\ell}$ denote a multiset which is the $\|\cdot\|_{X}$-projection of $\seeds_\ell$ onto $\net_0$. 
    Then, for each $i \in [n]$:
    \begin{enumerate}
        \item Let $\hat s_i$ be the $\|\cdot\|_{X}$-projection of $x_i$ onto $\hat \seeds_{\ell_i}$. 
        \item Let $\hat x_i$ be the $\|\cdot\|_{X}$-projection of $x_i$ onto $\net(\hat s_i, r_{\ell_i}; c_0 r_{\ell_i}) \subset \net$. 
    \end{enumerate}
    Define $\hx := (\hat x_1,\dots, \hat x_n) \in \net^{n}$. 
\end{definition}

\begin{remark}\label{distxitohatxi}
By definition of $S_{\ell_i}$, the distance
from $x_i$ to $S_{\ell_i}$ is at most $r_{\ell_i}$.
Since $\net_0$ is a $1$--net, the distance from $\hat \seeds_{\ell_i}$
to $x_i$ is at most $r_{\ell_i}+1$. Thus,
$\|x_i-\hat s_i\|_X\leq r_{\ell_i}+1$, $i\leq n$.
In turn, this implies $\|x_i-\hat x_i\|_X
\leq c_0 r_{\ell_i}+1$ for all $i\leq n$.
\end{remark}

Note that the above construction 
depends on the underlying normed space $X$. We collect some properties of this discretization.  

\begin{lemma}\label{lemma:discretization} Let $n$ be sufficiently large (independently of $X$), let $d$ satisfy \eqref{dcondition}, let the parameters $D,\lambda$ satisfy \eqref{aksdjfnalkfnflks}, and let $L\in [1,n^{1-\eps}]$.
Then
    \begin{enumerate}
        \item (Cardinality estimate)
        \[
            \ba{\cb{(\hx(\vx),\, \ell(\vx))\,:\, \vx \in \tuples(D,\lambda) }} \le 
    \big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^4 n\big)^n
    \cdot n^{n^{1-\eps/2}}.
        \]

        \item (Upper bound on expansion of distances)
        Let $\vx \in \tuples(D,\lambda,X)$ and $\hx := \hx(\vx)$. For all $t>0$ and all $(i,j) \in [n]^2$, 
        \[
            \|\hat x_i - \hat x_j\|_X \le (1+2c_0)\|x_i-x_j\|_X +3c_0 r_{\ell_i} + 2.
        \]  


        \item (Preservation of local scales) Let $\vx \in \tuples(D,\lambda)$ and $\hx := \hx(\vx)$. For all $i \in [n]$, 
        \[
            \ba{\cb{j \in [n]\,:\, \|\hat x_i - \hat x_j\|_X \le \frac{4}{9}\,r_{\ell_{i}}-2}} \le L\,n^{\eps}\,.
        \]
    \end{enumerate}
\end{lemma}

In view of strong similarities between the proof of the above lemma
and of the corresponding statement in \cite{AT2024},
the proof of Lemma~\ref{lemma:discretization} is presented in the appendix.



\begin{lemma}[Lower-bound on scales of separation]\label{lemma:scale-lb}
Let $D,\lambda>0$ be parameters satisfying \eqref{aksdjfnalkfnflks},
let $L\in[1,n^{1-\eps}]$,
and assume additionally that
$$
300^d\leq \frac{L}{2}.
$$
Then for all $\vx \in \tuples(D,\lambda,X)$ and all $i \in [n]$,
\[
    \ba{\cb{j \in [n] \,:\, \|x_i - x_j\|_X \le 72\lambda}  } < L\,n^{\eps}\,.
\]
In particular, $r_{\ell_i} \geq 72\lambda$ for all $i \in [n]$. 
\end{lemma}

\begin{remark}
The constant $72$ in the lower bound for $r_{\ell_i}$ can be replaced with arbitrary fixed number, by adjusting the assumption on $d$ accordingly.    
\end{remark}

The proof of the above lemma closely follows an argument from \cite{AT2024};
we provide the complete proof for an interested reader in the appendix.






\section{Bi-Lipschitz non-embedding}\label{sec:bilipschitz}


\subsection{The Banach--Mazur compactum}

Given a positive integer $d$, denote by $\mathcal{B}_d$
the collection of all $d$--dimensional normed spaces 
(identified up to isometry), endowed with a submultiplicative
metric
$$
d_{BM}(X,Y):=\inf\limits_{T:X\to Y}\|T\|_{X\to Y}
\,\|T^{-1}\|_{Y\to X},\quad X,Y\in \mathcal{B}_d,
$$
where the infimum is taken over all invertible linear operators $T$,
and where $\|T\|_{X\to Y}$ and $\|T^{-1}\|_{Y\to X}$ are standard operator
norms for $T:X\to Y$ and $T^{-1}:Y\to X$, respectively.
We refer to
\cite{NTJ} for a comprehensive discussion of the concept
and its fundamental role in the study of finite-dimensional
normed spaces.
In this note, we will use the following 
metric entropy estimate on the Banach-Mazur compactum: 
\begin{lemma}[\cite{pisier}]\label{lemma:BM-entropy}
    There is some positive universal constant $C_{\text{BM}}$ (satisfying $C_{\text{BM}} \le 10$) and a $2$-net $\netB(d)$ in $\mathcal{B}_d$ such that:
    \[
        |\netB(d)| \le \cE{e^{d\,C_{\text{BM}}}}\,.
    \]
\end{lemma}

\subsection{Robust non-embedding}

Given a normed space $X$, an $n$--tuple $\vx$ of elements of $X$,
a graph $G$ on $[n]$,
and a parameter $\alpha$, we will write $G \stackrel{\distortion}{\hookrightarrow} (X,\vx)$ whenever
the mapping $i\to x_i$, $i\leq n$, satisfies
\begin{equation}\label{bfGembeds}
d_G(i,j)\leq \|x_i-x_j\|_X
\leq \alpha\,d_G(i,j),\quad i,j\in[n],
\end{equation}
and, similarly,
$G \not \embeds (X,\vx)$ if \eqref{bfGembeds} does not hold.
By convention, we will assume that whenever the graph $G$
is not connected, \eqref{bfGembeds} fails for all choices
of $X,\alpha$, and $\vx=(x_i)_{i=1}^n$.

\medskip

The next proposition provides a non-embedding result
for our random graph model conditioned
on the requirement that the image of the embedding is
$\lambda$--sparse.

\begin{proposition}[Robust non-embedding]\label{prop:non-embedding}
There is a universal constant $C_{\text{\tiny{\ref{prop:non-embedding}}}}\geq 100$ with the following property.
Let $C_{\text{\tiny{\ref{prop:non-embedding}}}}\log\log n
\leq d\leq C_{\text{\tiny{\ref{prop:non-embedding}}}}^{-1}\log n$ and $\log n\leq \alpha\leq \frac{\log^2 n}{C_{\text{\tiny{\ref{prop:non-embedding}}}}d}$,
and define parameters
$$
\lambda:=\alpha,\quad M:= \Big\lceil
\frac{\cgraph\,\varepsilon\,n\log n}{\alpha}
\Big\rceil.
$$
Let $X$ be any $d$--dimensional normed space,
and let $B_{\text{BM}}(X;\,2)$ denote the set of $d$-dimensional normed spaces having (multiplicative) Banach--Mazur distance at most two from $X$.
Then, letting the random graph ${\bf G}=G({\bm\pi},M)$ be as in \cref{def:graph},
    \[
        \PP[{\bf G}]{\exists\, (X',\vx) \in B_{\text{BM}}(X;\,2) \times \domain(n^2\lambda,X) \,:\, {\bf G} \embeds (X',\vx)}
        \leq n^{-M/2}.
    \]
\end{proposition}

We recall for the reader's convenience that $\domain(n^2\lambda, X)$ is the set of $\lambda$--sparse $n$--tuples on $B_X(0,n^2\lambda)$. 

\begin{proof}
We will assume that the constant $C_{\text{\tiny{\ref{prop:non-embedding}}}} > 1000$
is sufficiently large (the numerical bound is not necessary for the current proof, but it will be used later in \cref{thm:bilipschitz}). Define
\[
    L:=2\cdot (300)^d.
\]
Fix any $d$--dimensional normed space $X=(\RR^d,\|\cdot\|_X)$.
    For $\vx \in \domain(n^2\lambda,X)$, let $\calL(\vx,X)$ be the set of ``long distances'' for $\vx$, defined as:
    \[
        \calL(\vx,X) := \cb{\{i,j\}\subset [n]\,:\,\|\hat x_i - \hat x_j\|_X > \frac{1}{3} \, \min(r_{\ell_i},\, r_{\ell_j})}
    \]  
    (where the discretization $\hx$ of $\vx$ is also constructed in the space $X$).
    Observe that $\calL(\vx,X)$ depends on $\vx$ only through $\hx$ and $\ell(\vx)$. Thus, the first assertion of \cref{lemma:discretization}, together with our assumptions on $d$, yields:
    \begin{align}
        \ba{\cb{\calL(\vx,X) \,:\, \vx \in \domain(n^2,\lambda,X)}} &\le  \ba{\cb{(\hx,\ell(\vx)) \,:\, \vx \in \domain(n^2,\lambda,X)}} \nonumber
        \\
        &\le \big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^4 n\big)^n \cdot n^{n^{1-\eps/2}} \,. \label{eq:cardinality-long}
    \end{align}
    Fix for a moment any $\vx\in\domain(n^2,\lambda,X)$.
    We claim that whenever the edge-set $E(G)$
    of a graph $G$ on $[n]$ has a non-empty intersection with $\calL(\vx,X)$, then for every $X' \in B_{\mathrm{BM}}(X,2)$,
    \[
        G \not \embeds (X', \vx)\,.
    \]
    Indeed, assume for contradiction there exists a pair $\{i,j\} \in
    \calL(\vx,X)$ with $\{i,j\}\in E(G)$, and a normed space $X' \in B_{\mathrm{BM}}(X,2)$
    such that $G \embeds (X',\vx)$. Then $\|x_i -x_j\|_{X'} \le \alpha$. As $X' \in B_{\mathrm{BM}}(X,2)$, it follows that $\|x_i - x_j\|_{X} \le 2\alpha $. By the second assertion of \cref{lemma:discretization} applied with $t:=2\alpha$, 
    \[
        \|\hat x_i -\hat x_j\|_{X} \leq 2\alpha+2 + 3c_0 \min(r_{\ell_i}, r_{\ell_j}) + 4c_0 \alpha< \frac{1}{3} \min(r_{\ell_i}, r_{\ell_j})\,,
    \]
    where in the last inequality we used 
    the bound $\min(r_{\ell_i}, r_{\ell_j})\geq 72\lambda= 72\alpha$ from Lemma~\ref{lemma:scale-lb}.
    This implies that $\{i,j\} \not \in \calL(\vx,X)$, which supplies the desired contradiction.

\medskip



    Utilizing the proven claim and then applying \eqref{eq:cardinality-long}, we compute:
    \begin{align*}
        &\PP[{\bf G}]{\exists\, (X',\vx) \in B_{\text{BM}}(X;\,2) \times \domain(n^2\lambda,X) \,:\, {\bf G} \embeds (X',\vx)}\\
        &\quad\quad\le \PP[{\bf G}]{\exists\, \vx \in  \domain(n^2\lambda,X) \,:\, E(\bp, \calM; M)\cap \calL( \vx,X)=\emptyset} \\
        &\quad\quad\le\big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^4 n\big)^n
        \cdot n^{n^{1-\eps/2}}\,
        \max\limits_{\vx \in  \domain(n^2,\lambda,X)}
        \PP[{\bf G}]{E({\bm\pi},\calM;M)\cap \calL ( \vx,X)=\emptyset}\,.
    \end{align*}
Fix any $\vx \in  \domain(n^2,\lambda,X)$.
Letting $\bp$, $\calM$, $\calC$, and $\bG$ be as in \cref{def:graph},
\begin{align*}
\PP[{\bf G}]{E({\bm\pi},\calM;M)\cap \calL( \vx,X)=\emptyset} &=
\PP[{\bf G}]{E(\calC) \cap \calL( \vx,X)=\emptyset}
\,\PP[{\bf G}]{E(\calM) \cap \calL( \vx,X)=\emptyset},
\end{align*}
As Lemma~\ref{lemma:scale-lb} implies $\frac{4}{9}\,r_{\ell_{i}}-2>\frac{1}{3}\,r_{\ell_i}$, observe that the third assertion of \cref{lemma:discretization} yields
\begin{equation}\label{calLuconstraints}
\big|\big\{j\in [n]\setminus\{i\}:\;\{i,j\}\notin\calL( \vx,X)\big\}\big|\leq L\,n^\eps,
\quad i\in[n].    
\end{equation}

In view of
\eqref{calLuconstraints}, since $\calC$ is a uniform $n$--cycle, it holds for some universal constant $C>0$,
\[
    \PP[{\bf G}]{\big\{\{\bm{\pi}(i),\bm{\pi}({i\;\rm{mod}\;n}+1)\},i\leq n\big\}\cap \calL( \vx,X)=\emptyset}
\leq \bigg(\frac{CL\,n^\eps}{n}\bigg)^n\,.
\]
Similarly, for some other universal constant $C'>0$
\[
    \PP[{\bf G}]{E(\calM) \cap \calL( \vx,X)=\emptyset} \leq \bigg(\frac{C'L\,n^\eps}{n}\bigg)^M\,.
\]
Combining the above estimates and letting $\tilde C=\max(C,C')$, we obtain
\[
\PP[{\bf G}]{\exists\, (X',\vx) \in B_{\text{BM}}(X;\,2) \times \domain(n^2\lambda,X) \,:\, {\bf G} \embeds (X',\vx)}
\leq 
\pa{3/c_0}^{dn}\, \big(n^{1-\eps}\log^4 n\big)^n
    \, n^{n^{1-\eps/2}}
    \bigg(\frac{\tilde CL\,n^\eps}{n}\bigg)^{n+M}.
\]
The result follows after some trivial arithmetical
manipulations of the right--hand side. 
\end{proof}

\subsection{Proof of the main results}

Observe that the proof of the above proposition
does not actually depend on the model of randomness of the graph
${\bf G}$, except for the number of edges it has and the condition
that the edges are ``well spread'' within ${[n]\choose 2}$.
In particular, replacing ${\bf G}$ with the Erdos--Renyi
model $G(n,n+M)$ would yield a similar result.
The crucial property of the graph ${\bf G}$
that enables us to pass from Proposition~\ref{prop:non-embedding} to the proof of the main result
is a ``non--expansion'' property about the slow volume growth of metric balls (which completely fails in the Erdos--Renyi setting) stated below
as an immediate corollary of~\cref{lem:specialgraph}:

\begin{corollary}\label{corbfG}
There is a universal constant $\cgraph$ and two positive constants $\te$ and
$\tn$ depending only on $\eps$, so that the following holds. Let $n\geq \tn$, and let $M$ satisfy 
$n^{1-\te}\leq M\leq n/2$.
Then with probability at least $1-\exp(-n^{\te})$, the graph
${\bf G}=G({\bm\pi},M)$ satisfies:
for every $v\in[n]$,
$$
\Big|\Big\{w\in[n]:\;d_{\bf G}(v,w)\leq 
\frac{\cgraph\,\varepsilon\,n\log n}{M}\Big\}\Big|< n^\varepsilon.
$$
\end{corollary}


Finally, we obtain the main technical estimate of the article:

\begin{theorem}[Bi-Lipschitz non-embedding]\label{thm:bilipschitz}
Let $C_{\text{\tiny{\ref{prop:non-embedding}}}}$ and $\cgraph$
be as in Proposition~\ref{prop:non-embedding}
and~\cref{lem:specialgraph}, respectively. Let $(\alpha, D)$ be parameters satisfying $C_{\text{\tiny{\ref{prop:non-embedding}}}}\log\log n
\leq d\leq C_{\text{\tiny{\ref{prop:non-embedding}}}}^{-1}\log n$ and $\log n\leq \alpha\leq \frac{\log^2 n}{C_{\text{\tiny{\ref{prop:non-embedding}}}}d}$. Let $\bG$ be as in \cref{def:graph} with the parameter choice:
\[
    M:= \Big\lceil \frac{\cgraph\,\varepsilon\,n\log n}{\alpha}\Big\rceil\,.
\]
Then,
\[
    \PP[{\bf G}]{\mbox{${\bf G}$
    embeds with bi-Lipschitz distortion at most
    $\alpha$ into a $d$--dimensional
    normed space}}
    \le 2\,\exp(-n^{\te}).
\]
\end{theorem}
\begin{proof}
In analogy with \cref{def:sparse}, say that a graph $G$ on $[n]$ is {\it $(\lambda, n^\eps)$-sparse}
if for every vertex $v\in[n]$, there are less than
$n^\eps$ vertices $w\neq v$ with $d_G(v,w)\leq \lambda$.
Define the corresponding event
\[
    \calD:=\big\{{\bf G}\mbox{ is $(\lambda, n^\eps)$-sparse}\big\},
\]
and observe that, in view of our choice of parameters
and Corollary~\ref{corbfG},
\[
    \PP{\calD}\geq 1-\exp(-n^{\te})
\]
Recall that $\mathcal B_d$ denotes the Banach--Mazur compactum , and $\netB(d)$ is the net in $\mathcal{B}_d$ defined in Lemma~\ref{lemma:BM-entropy}. Using translational invariance of the metric in a normed space, 
    \begin{align*}
        &\PP[{\bf G}]{
        \bigcup_{X \in \mathcal B_d}~\cb{\exists\,  \vx \in (\RR^d)^n\,:\, {\bf G} \embeds (X,\vx)} } \\
        &=\PP[{\bf G}]{ \bigcup_{X \in \mathcal B_d}~\cb{\exists\,  \vx \in (\RR^d)^n\,:\, x_1=0,\; {\bf G} \embeds (X,\vx)} } \\
        &= \exp(-n^{\te}) + \PP[{\bf G}]{ \bigcup_{X \in \mathcal B_d}~ \cb{\exists\,\vx \in (\RR^d)^n\,:\,x_1=0,\; {\bf G} \embeds (X,\vx) } \,\bigg|\, \calD} \\
        &\le \exp(-n^{\te}) +\sum_{X \in \mathcal \netB(d)} ~\PP[{\bf G}]{~ \bigcup_{X' \in B_{\mathrm{BM}}(X,\,2)}~ \cb{\exists\,\vx \in (\RR^d)^n\,:\,x_1=0,\; {\bf G} \embeds (X',\vx) } \,\bigg|\, \calD} \,.
    \end{align*}
Observe that almost surely within the event $\calD$, for any normed space $X'$,
the condition ${\bf G} \embeds (X',\vx)$
necessarily implies that the $n$--tuple $\vx$ is $\lambda$--sparse. Furthermore, the same condition together with the constraint $x_1=0$ gives $\{x_i\}_{i=1}^n\subset B_X(0;\alpha\,n)\subset B_X(0;n^2)$.
Therefore, 
\begin{multline*}
\PP[{\bf G}]{~ \bigcup_{X' \in B_{\mathrm{BM}}(X,\,2)}~ \cb{\exists\,\vx \in (\RR^d)^n\,:\,x_1=0,\; {\bf G} \embeds (X',\vx) } \,\bigg|\, \calD}\\
\leq
\PP[{\bf G}]{~ \bigcup_{X' \in B_{\mathrm{BM}}(X,\,2)}~ \cb{\exists\,\vx \in \domain(n^2,\lambda,X),\; {\bf G} \embeds (X',\vx) } \,\bigg|\, \calD}.
\end{multline*}
An unconditional estimate of the latter event probability
is given in Proposition~\ref{prop:non-embedding}.
Since the probability of $\calD$ asymptotically tends to one,
we obtain
\[
    \PP[{\bf G}]{~ \bigcup_{X' \in B_{\mathrm{BM}}(X,\,2)}~ \cb{\exists\,\vx \in \domain(n^2,\lambda,X),\; {\bf G} \embeds (X',\vx) } \,\bigg|\, \calD}
\leq (1+o_n(1))n^{-M/2}\,,
\]
and hence
\[
\PP[{\bf G}]{
        \bigcup_{X \in \mathcal B_d}~\cb{\exists\,  \vx \in (\RR^d)^n\,:\, {\bf G} \embeds (X,\vx)} }
        \leq \exp(-n^{\te})
        +(1+o_n(1))n^{-M/2}|\netB(d)|\,.
\]
Finally, applying Lemma~\ref{lemma:BM-entropy} and recalling that $C_{\text{\tiny{\ref{prop:non-embedding}}}} > 1000 > 100 \,C_{\text{BM}}$, we crudely compute 
\[
n^{-M/2}|\netB(d)| \le n^{-\sqrt{n}}\,.
\]
This completes the theorem. 
\end{proof}

\begin{remark}
Note that Theorem~\ref{thm:bilipschitz}
readily implies the main result of this article, \cref{thm:main}.
Moreover, a quick inspection of the statement of Theorem~\ref{thm:bilipschitz}
yields the bounds
$$
\alpha\,k_n^\alpha(\ell_\infty)
\geq c\,\log^2 n
$$
whenever $\log n\leq \alpha\leq c\log^2n/\log\log n$,
for an appropriate universal constant $c>0$.
Combined with the previously known lower bounds on $k_n^\alpha(\ell_\infty)$
in superlogarithmic regime for $\alpha$ (see \cite[Formula~(12)]{naor-snapshot}), it yields
$$
k_n^\alpha(\ell_\infty)
\geq c\max\bigg(\frac{\log^2 n}{\alpha},
\frac{\log n}{\log\big(\frac{\alpha\log\log n}{\log n}\big)}\bigg),
\quad
\alpha\geq \log n.
$$
It remains an important and challenging open problem 
to identify a sharp lower bound on $k_n^\alpha(\ell_\infty)$
for all $\alpha$.
\end{remark}





















