\section{Discretization scheme: details}

\begin{proof}[Proof of Lemma~\ref{lemma:discretization}]
    We prove the items in the statement of the lemma in order. \\

    \textbf{Proof of claim 1}. By definition, $|\net_0|$ is the covering number of $B_X(0, D)$ using translates of $B_X(0,1)$. 
    By elementary volumetric considerations, along with the standard duality between covering and packing, 
    \[
        |\net_0| \le \pa{3 \, D }^d \le (3n)^{2n^{\eps/4}}\,.
    \]
    Recalling the definition of $\net(y,r_\ell;c_0r_\ell)$, we similarly have:
    \[
        \max_{\substack{y \in \RR^d \\ \ell \ge 0}}|\net(y,r_\ell;c_0r_\ell)| \le \pa{3/c_0}^d\,.
    \]
    Recall further that for every
    $\ell\in\{\lfloor \log_2\lambda\rfloor+1,\dots, \lceil\log_2(2D)\rceil\}$,
    $\hat S_\ell$ is a submultiset of $\net_0$ of size $\lfloor n^{1-\eps}\log^2 n\rfloor$.
    Fix for a moment
    any multisets $S_{\ell}^*\subset \net_0$ of size $\lfloor
    n^{1-\eps}\log^2 n\rfloor$, $\lfloor \log_2\lambda\rfloor+1\leq \ell\leq
    \lceil\log_2(2D)\rceil$,
    arbitrary numbers $\ell_i^*\in \{\lfloor \log_2\lambda\rfloor+1,\dots, \lceil\log_2(2D)\rceil\}$,
    and arbitrary elements $s_i^*\in S_{\ell_i}^*$, $i\leq n$, and consider the set
    $$
    \big\{\hx(\vx)\,:\, \vx \in \tuples(D,\lambda),\,\ell_i(\vx)=\ell_i^*,\,
    \hat s_i(\vx)=s_i^*,\;i\leq n;\;\;\hat S_\ell=S_\ell^*,\,\lfloor \log_2\lambda\rfloor+1\leq \ell\leq
    \lceil\log_2(2D)\rceil\big\}.
    $$
    By definition, for every $\vx \in \tuples(D,\lambda)$ with $\ell_i(\vx)=\ell_i^*$
    and $\hat s_i(\vx)=s_i^*$, the $i$--th component of $\hx$
    is the projection of $x_i$ onto the net $\net(s_i^*, r_{\ell_i^*}; c_0 r_{\ell_i^*})$ of size at most $\pa{3/c_0}^d$. Thus, the cardinality of the above set is at most
    $$
    \big(\pa{3/c_0}^d\big)^n.
    $$
    Further, given $\vx \in \tuples(D,\lambda)$ with $\ell_i(\vx)=\ell_i^*$, $i\leq n$,
    and $\hat S_\ell=S_\ell^*$, $\lfloor \log_2\lambda\rfloor+1\leq \ell\leq
    \lceil\log_2(2D)\rceil$,
    there are at most $\big(n^{1-\eps}\log^2 n\big)^n$
    admissible values for the tuple $\big(\hat s_i(\vx)\big)_{i=1}^n$, and hence
    $$
    \big|\big\{\hx(\vx)\,:\, \vx \in \tuples(D,\lambda),\,\ell_i(\vx)=\ell_i^*,\,
    \;\hat S_\ell=S_\ell^*,\,\lfloor \log_2\lambda\rfloor+1\leq \ell\leq
    \lceil\log_2(2D)\rceil\big\}\big|
    \leq \big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^2 n\big)^n.
    $$
    The upper estimate on the cardinality of $\net_0$ allows for estimating
    the number of potential choices for sets $\hat S_\ell$, 
    leading to the bound
    \begin{align*}
    \big|\big\{\hx(\vx)\,:\, \vx \in \tuples(D,\lambda),\,\ell_i(\vx)=\ell_i^*,\;i\leq n
    \big\}\big|
    &\leq \big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^2 n\big)^n
    \cdot |\net_0|^{(1+\lceil\log_2(2D)\rceil)
    \lfloor n^{1-\eps}\log^2 n\rfloor}\\
    &\leq \big(\pa{3/c_0}^d\big)^n\cdot \big(n^{1-\eps}\log^2 n\big)^n
    \cdot \big((3n)^{2n^{\eps/4}}\big)^{n^{1-\eps}\log^4 n}.
    \end{align*}
    Finally, in view of Remark~\ref{boundsonell},
    there are at most $\big(1+\lceil\log_2(2n^2)\rceil\big)^n$ possible realizations of $\ell_i(\vx)$, $i\leq n$.
    Combining the bounds, we get the claim. \\

    \textbf{Proof of claim 2.} Pick any $i,j$ with $i\neq j$. By triangle inequality and the construction of $\ell_j$:
    \[
        \ba{\cb{i' \in [n]\,:\, \|x_j - x_{i'}\|_X \le \|x_i-x_j\|_X + r_{\ell_i}}} \ge L\,n^{\eps}\,.
    \]
    As we have assumed $\|x_i - x_j\|_X \le t$, it holds by definition of $\ell_j$ that $r_{\ell_j} \le 2(r_{\ell_i} + t)$. 
    Then, by construction of the discretization $\hx$ (see Remark~\ref{distxitohatxi}),
    \begin{align*}
        \|\hat x_i - \hat x_j\|_X \le \|x_i - x_j\|_X + \|x_i - \hat x_i\|_X + \|x_j - \hat x_j\|_X  \le   t+2 + c_0 (r_{\ell_i} + r_{\ell_j})
        \leq t+2 + 3c_0 r_{\ell_i} + 2c_0 t. \\
    \end{align*}

    \textbf{Proof of claim 3.} 
    We prove the claim by contradiction. Assume that
    there is $i\in[n]$ such that
    \[
        \ba{\cb{j \in [n]\,:\, \|\hat x_i - \hat x_j\|_X \le \frac{4}{9}\,r_{\ell_{i}}-2}} > L\,n^{\eps}\,.
    \]
    Recall that, by the definition of $r_{\ell_i}$,
    \[
        \ba{\cb{j \in [n]\,:\, \|x_i - x_j\|_X \le r_{\ell_{i}}/2}} < L\,n^{\eps}\,.
    \]
    Therefore, there exists $x_{j_0}$ with both
    $\|x_i - x_{j_0}\| > r_{\ell_i}/2$ and $\|\hat x_i - \hat x_{j_0}\| \le \frac{4}{9}r_{\ell_i}-2$.
    By triangle inequality, one of the following must hold:
    \[
        \|\hat x_i - x_i \| \ge r_{\ell_i}/90+1\,, \quad \text{or} \quad \|\hat x_{j_0} - x_{j_0} \| \ge r_{\ell_i}/30+1\,.
    \]
    By construction of $\hx$ (see Remark~\ref{distxitohatxi}), we have that $\|\hat x_i - x_i\| \le c_0 r_{\ell_i}+1$ and $\|\hat x_{j_0} - x_{j_0}\| \le c_0 r_{\ell_{j_0}}+1$. Since $c_0 = .01$, the first of the two options above is impossible. Then the second option must hold, which implies
    \begin{equation}\label{akjnfaskfjn}
    c_0 r_{\ell_{j_0}}+1 \ge r_{\ell_i}/30+1.
    \end{equation}
    On the other hand, the definition of $\ell_{j_0}$
    implies that
    $$
    \log_2 r_{\ell_{j_0}}= \ell_{j_0}\leq\lceil\log_2(\|x_i - x_{j_0}\|_X+r_{\ell_i})\rceil
    \leq \Big\lceil\log_2\Big(\frac{4}{9}r_{\ell_i}+c_0 (r_{\ell_i}+r_{\ell_{j_0}})+r_{\ell_i}\Big)\Big\rceil,
    $$
    and hence $r_{\ell_{j_0}}< 3r_{\ell_i}$.
    Combining the last assertion with \eqref{akjnfaskfjn}, we get
    $$
    3c_0r_{\ell_i}\geq r_{\ell_i}/30,
    $$
    which contradicts our choice of $c_0$. This proves the claim.
\end{proof}


\bigskip


\begin{proof}[Proof of Lemma~\ref{lemma:scale-lb}]
    Assume for the sake of contradiction there is a $\lambda$-sparse tuple $\vx$ in $(B_{X}(0;\, D))^n$ and an index $i \in [n]$ such that
    \[
        \ba{\cb{j \in [n] \,:\, \|x_i - x_j\|_X \le 72\lambda}  } \ge L\,n^{\eps}\,,
    \]
    that is, the ball $B_{X}(x_i, 72\lambda)$ contains at least $L\,n^{\eps}$
    points from $\vx$. By the definition of $\lambda$--sparsity,
    any of the balls $B_X(x_j,\lambda)$, $j\in[n]$, contains at most
    $n^{\eps}+1$
    points from $\vx$. Hence, any covering of $B_{X}(x_i, 72\lambda)$ using translates of $B_X(0,\, \lambda/2)$ must have cardinality at least 
    $L\,n^{\eps}/(n^{\eps}+1)$, since by the pigeonhole principle, any smaller covering would have a $\lambda/2$--ball with more than $n^{\eps}+1$ points from $\vx$.
    By the standard duality between packing and covering, this implies that $B_{X}(x_i, 73\lambda)$ contains as a subset at least $L\,n^{\eps}/(n^{\eps}+1)$ disjoint copies of $B_X(0, \lambda/4)$. By volumetric considerations, we obtain:
    \[
        \frac{L\,n^{\eps}}{n^{\eps}+1}\, (\lambda/4)^{d} \le (73\lambda)^d\,.
    \]
    However, by our choices of parameters, $300^d \le \frac{L\,n^{\eps}}{n^{\eps}+1}$, providing the desired contradiction. Finally, note that by construction of $\ell_i$, we have $\ell_i \geq \log_2(72\lambda)$, so that $r_{\ell_i} \geq 72\lambda$.
\end{proof}






