An alternating sequence $(u_1,v_1),\ldots,(u_p,v_p)$ is said to be \emph{good} if $p$ is even and the following two conditions hold.
\begin{itemize}
\item[(i)] $d^-_B(v_1) = 0$ and $d^-_B(v_p) \geq 2$,
\item[(ii)] $d^-_B(v_\ell) = 1$ whenever $2 \leq \ell \leq p-1$.
\end{itemize}

\begin{claim}
\label{clm:altseq}
If there exists a good alternating sequence $(u_1,v_1),\ldots,(u_p,v_p)$, then 
\[(B \setminus \{(u_i,v_i)\colon i \in [p] \text{ is even}\}) \cup \{(u_i,v_i)\colon i \in [p] \text{ is odd}\}\]
is a maximal optimal branching of $D_M$ with fewer leaves than $B$.
\end{claim}

\begin{claimproof}
Assume that $\sigma=(u_1,v_1),\ldots,(u_p,v_p)$ is a good alternating sequence and denote by $B^\sigma = (B \setminus \{(u_i,v_i)\colon i \in [p] \text{ is even}\}) \cup \{(u_i,v_i)\colon i \in [p] \text{ is odd}\}$. 
Clearly, $B^\sigma$ is a maximal branching of $D_M$.
Furthermore, since $v_1$ is a leaf in $B$ but not in $B^\sigma$, and every leaf in $B^\sigma$ is a leaf in $B$, the branching $B^\sigma$ has fewer leaves than $B$. 
It remains to show that $B^\sigma$ is optimal. 
To see this, observe that by condition (ii), any two vertices $v_i$ and $v_j$ with even indices $i\neq j$ are distinct, and therefore
\begin{equation*}
\begin{split}
\lvert U(B)\lvert & = \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_B(v) + \sum_{i \in [p]\colon
\text{$i$ even}} \nu_B(v_i) + \lvert v_1 \rvert,
%& = \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_{B^\sigma}(v) + \sum_{i \in [p-2]\colon
%\text{$i$ even}}\left(\lvert v_i \rvert - \lvert u_i\rvert\right) + \nu_B(v_p) + \lvert v_1 \rvert\\
%& = \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_{B^\sigma}(v) + \sum_{i \in [p-2]\colon
%\text{$i$ even}} \left(\lvert v_{i+1}\rvert - \lvert u_{i-1} \rvert \right)+ \nu_B(v_p) + \lvert v_1 \rvert \\
\end{split}
\end{equation*}
where
\begin{equation*}
\begin{split}
\sum_{i \in [p]\colon
\text{$i$ even}} \nu_B(v_i)
& = \sum_{i \in [p-2]\colon
\text{$i$ even}}\left(\lvert v_i \rvert - \lvert u_i\rvert\right) + \nu_B(v_p) \\
& = \sum_{i \in [p-2]\colon
\text{$i$ even}} \left(\lvert v_{i+1}\rvert - \lvert u_{i-1} \rvert \right)+ \nu_B(v_p)
\end{split}
\end{equation*}
as $v_i = v_{i+1}$ and $u_i = u_{i-1}$ for every $i \in [p-1]$ such that $i$ is even. Since
\begin{equation*}
\begin{split}
\nu_B(v_p) & = \lvert v_p \rvert - \Bigg\lvert \bigcup_{v \in N^-_B(v_p)} v\Bigg\rvert \geq \lvert v_p \rvert - \Bigg\lvert \bigcup_{v \in N^-_B(v_p) \setminus \{u_p\}} v\Bigg\rvert  - \lvert u_p \rvert\\
& = \lvert v_p\vert - \Bigg\lvert \bigcup_{v \in N^-_{B^\sigma}(v_p)} v\Bigg\rvert  - \lvert u_p \rvert = \nu_{B^\sigma}(v_p) - \lvert u_p \rvert
\end{split}
\end{equation*}
and $u_p = u_{p-1}$ by definition, it follows that
\begin{equation*}
\begin{split}
&\sum_{i \in [p-2]\colon
\text{$i$ even}} \left(\lvert v_{i+1}\rvert - \lvert u_{i-1} \rvert \right)+ \nu_B(v_p)
\geq  \sum_{i \in [p-2]\colon\text{$i$ even}} (\lvert  v_{i+1}\rvert   - \lvert  u_{i-1}\rvert)   + \nu_{B^\sigma}(v_p) - \lvert  u_{p-1}\rvert \\
= & \sum_{i \in [p-1]\colon \text{$i$ odd}} (\lvert  v_i\rvert   - \lvert  u_i\rvert)   + \nu_{B^\sigma}(v_p)  - \lvert v_1 \rvert
=  \sum_{i \in [p-1]\colon \text{$i$ odd}} \nu_{B^\sigma}(v_i) + \nu_{B^\sigma}(v_p)  - \lvert v_1 \rvert\,.
%\lvert  U(B)\rvert   & \geq  \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_{B^\sigma}(v) + \sum_{i \in [p-2]\colon\text{$i$ even}} \Bigg(\lvert  v_{i+1}\rvert   - \lvert  u_{i-1}\rvert\Bigg)   + \nu_{B^\sigma}(v_p) - \lvert  u_{p-1}\rvert   + \lvert  v_1\rvert  \\
%&= \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_{B^\sigma}(v) + \sum_{i \in [p-1]\colon \text{$i$ odd}} \Bigg(\lvert  v_i\rvert   - \lvert  u_i\rvert\Bigg)   + \nu_{B^\sigma}(v_p)\\
%&= \sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_{B^\sigma}(v) + \sum_{i \in [p-1]\colon \text{$i$ odd}} \nu_{B^\sigma}(v_i) + \nu_{B^\sigma}(v_p) \\
%&= \lvert  U(B^\sigma)\rvert\,.  
\end{split}
\end{equation*}
 Therefore, $\lvert U(B) \rvert$ is at least
\begin{equation*}
\begin{split}
&\sum_{v \in V(D_M) \setminus \{v_i\colon i \in [p]\}} \nu_B(v) + \sum_{i \in [p-1]\colon \text{$i$ odd}} \nu_{B^\sigma}(v_i) + \nu_{B^\sigma}(v_p)=  \lvert  U(B^\sigma)\rvert\,.
\end{split}
\end{equation*}
But $B$ is optimal and thus, $B^\sigma$ is optimal as well.
\end{claimproof}

Consider now a leaf $v \in V(D_M) \setminus \min D_M$ of $B$ (recall that by assumption, such a leaf exists) and denote by $\mathcal{S}_v$ the set of alternating sequences starting in $v$. 
Note that since $d^-_B(v) = 0$ and $v \notin \min D_M$, we infer that $\mathcal{S}_v \neq \emptyset$ (a single arc $e \in A(D_M) \setminus B$ with head $v$ indeed constitutes an alternating sequence). 
We will show that there exists a good alternating sequence in $\mathcal{S}_v$.
This will complete the proof, as by \Cref{clm:altseq}, we can then construct an optimal branching of $D_M$ with fewer leaves than $B$. 

Suppose for a contradiction that no good alternating sequence exists in $\mathcal{S}_v$. 
In the following, an alternating sequence $\sigma \in \mathcal{S}_v$ is said to be \emph{maximal} if $\sigma$ is not a proper subsequence of any alternating sequence in $\mathcal{S}_v$.
Let $\sigma=(u_1,v_1),\ldots,(u_p,v_p)$ be a maximal alternating sequence in $\mathcal{S}_v$ (note that $v_1 = v$). 

We claim that there exists no index $i \in [p]$ such that $d^-_B(v_i) \geq 2$. 
Indeed, suppose for a contradiction that such indices exist and let $i \in [p]$ be the smallest such index.
Then $i$ is even, for if $i$ is odd, then $i\ge 3$ and $v_i = v_{i-1}$ by definition, a contradiction to the minimality of $i$.
Furthermore, by minimality of $i$, $d^-_B(v_\ell) = 1$ for every $2 \leq \ell \leq i-1$. 
It follows that $(u_1,v_1),\ldots,(u_i,v_i)$ is a good alternating sequence in $\mathcal{S}_v$, a contradiction to our assumption. 
Thus, $d^-_B(v_i) \leq 1$ for every $i \in [p]$. 

We now claim that $p$ is odd. Indeed, suppose to the contrary that $p$ is even (note that in particular $p \geq 2$). 
Then $(u_p,v_p) \in B$ by definition and since $d^-_B(v_p) \leq 1$ by the above, it follows from \Cref{clm:inneighbors} that there exists a vertex $u \in N^-_{D_M}(v_p) \setminus \{u_p\}$. 
We claim that the arc $(u,v_p)$ is not contained in $\sigma$. 
Indeed, if there exists $\ell \in [p]$ such that $(u,v_p) = (u_\ell, v_\ell)$, then $\ell$ is odd, since $(u,v_p) \notin B$, and strictly larger than one, since $d^-_B(v_1) = 0$; but then, $(u_{\ell -1},v_{\ell -1}) = (u_p,v_p)$ as $d^-_B(v_p) \leq 1$, a contradiction to the fact that the arcs of $\sigma$ are pairwise distinct. 
Thus, $(u,v_p) \notin \sigma$ and so, $(u_1,v_1),\ldots,(u_p,v_p),(u,v_p)$ is an alternating sequence in $\mathcal{S}_v$, contradicting the maximality of $\sigma$. 
Therefore, $p$ is odd.

Since $p$ is odd, $(u_p,v_p) \notin B$. Now since $u_p \notin \max D_M$ and $B$ is maximal, there must exist a vertex $u \in N^+_{D_M}(u_p)$ such that $(u_p,u) \in B$; but $\sigma$ is maximal and so, the arc $(u_p,u)$ must be contained in $\sigma$. 
Thus, we have proven the following.

\begin{claim}
\label{obs:maxseq}
For every maximal alternating sequence $\sigma=(u_1,v_1),\ldots,(u_p,v_p)$ in $\mathcal{S}_v$, the following hold.
\begin{itemize}
\item[(i)]\label{item1} For every $i \in [p]$, $d^-_B(v_i) \leq 1$.
\item[(ii)]\label{item2} For every $i \in [p]$, $\sigma$ contains the arc $(u_i,u)$ where $u$ is the out-neighbor of $u_i$ in $B$.
\end{itemize}
\end{claim}

Now let $B_v \subseteq B$ be the set of arcs $(u,w) \in B$ such that there exists an alternating sequence in $\mathcal{S}_v$ containing the arc $(u,w)$ (note that if there exists an alternating sequence in $\mathcal{S}_v$ containing $(u,w)$ then, a fortiori, there exists a maximal alternating sequence in $\mathcal{S}_v$ containing $(u,w)$). 

We claim that $B_v$ is a linear branching. 
Indeed, suppose that there exists a vertex $w \in V(D_M)$ such that $d^-_{B_v}(w) \geq 2$ and let $u \in N^-_{B_v}(w)$ be an in-neighbor of $w$ in $B_v$ (that is, $(u,w) \in B_v$). 
Then, by construction, there exists a maximal alternating sequence in $\mathcal{S}_v$ containing the arc $(u,w)$; but $d^-_B(w) \geq d^-_{B_v}(w) \geq 2$, a contradiction to \Cref{obs:maxseq}(i). 

Now let $L_v \subseteq \min D_M$ be the set of vertices of out-degree one in $B_v$, that is, $u \in L_v$ if and only if $u$ is a minimal element of $D_M$ and there exists $w \in V(D_M)$ such that $(u,w) \in B_v$. 
Note that $L_v \neq \emptyset$ as it contains, in particular, every minimal element of $D_M$ comparable to $v$. 
For every vertex $u \in L_v$, let $m_u \in \max B_v$ be the maximal element reachable from $u$ in $B_v$, that is, there is a path from $u$ to $m_u$ using only arcs in $B_v$ and $m_u$ is the tail of no arcs in $B_v$. 
Note that $m_u \neq m_w$ for any two distinct vertices $u,w \in L_v$, as $B_v$ is a linear branching; in particular, $|\{m_u\colon u \in L_v\}| = |L_v|$. 
Denoting by $M_v = \{m_u\colon u \in L_v\}$, we will show that $(\min D_M \setminus L_v) \cup M_v$ is an antichain of $D_M$. 
Since this set has size $|\min D_M \setminus L_v| + |M_v| = |\min D_M \setminus L_v| + |L_v| = |\min D_M|$ as shown above, this contradicts the fact that $\min D_M$ is the unique maximum antichain of $D_M$ and thus concludes the proof.

Let us first show that the elements in $M_v$ are pairwise incomparable. 
Suppose to the contrary that there exist $m_u,m_w \in M_v$ such that $(m_u,m_w) \in A(D_M)$, and let $x \in V(D_M)$ be the in-neighbor of $m_w$ in $B_v$. 
Then $m_u \neq x$ for if $m_u = x$ then $m_u \notin \max B_v$, a contradiction to the definition of $m_u$. 
Furthermore, since the arc $(x,m_w)$ is contained in a maximal alternating sequence in $\mathcal{S}_v$ by construction, $(m_u,m_w) \notin B$ by \Cref{obs:maxseq}(i).
Now let $(u_1,v_1),\ldots,(u_p,v_p)$ be an alternating sequence in $\mathcal{S}_v$ ending with the arc $(x,m_w)$.
Note that $p$ is even as $(x,m_w) \in B$. 
Then $(u_1,v_1),\ldots,(u_p, v_p),(m_u,m_w)$ is an alternating sequence in $\mathcal{S}_v$; in particular, it is contained in some maximal alternating sequence $\sigma$ in $\mathcal{S}_v$. 
But then, by \Cref{obs:maxseq}(ii), $\sigma$ contains the arc $(m_u,y)$ where $y$ is the out-neighbor of $m_u$ in $B$, a contradiction to the fact that $m_u \in \max B_v$. Thus, the elements in $M_v$ are pairwise incomparable.

Second, let us show that every element in $\min D_M \setminus L_v$ is incomparable to every element in $M_v$. Suppose to the contrary that there exists $m \in \min D_M \setminus L_v$ and $m_u \in M_v$ such that $(m,m_u) \in A(D_M)$.
Note that $m_u\neq u$ by the definition of $L_v$ and hence $m_u$ has a (unique) in-neighbor in $B_v$. 
Let $x \in V(D_M)$ be the in-neighbor of $m_u$ in $B_v$ (note that since $m$ is the tail of no arc in $B_v$, necessarily $m \neq x$). 
By construction, there exists a maximal alternating sequence $(u_1,v_1),\ldots,(u_p,v_p)$ in $\mathcal{S}_v$ containing the arc $(x,m_u)$, say $(x,m_u) = (u_\ell, v_\ell)$ for some $\ell \in [p]$ (note that $\ell$ is even as $(x,m_u) \in B$). 
Since $(m,m_u) \notin B$ by \Cref{obs:maxseq}(i), it follows that $(u_1,v_1),\ldots,(u_\ell, v_\ell),(m,m_u)$ is an alternating sequence in $\mathcal{S}_v$; in particular, it is contained in some maximal alternating sequence $\sigma$ in $\mathcal{S}_v$. But then, by \Cref{obs:maxseq}(ii), $\sigma$ contains the arc $(m,y)$ where $y$ is the out-neighbor of $m$ in $B$, a contradiction to the fact that $m \notin L_v$, which concludes the proof.
\end{proof}

Given an integer $p\ge 2$, an \emph{in-star of size $p$}\label{page-in-star} in $D_M$ is a sequence $S = (c,x_1,\ldots,x_p)$ of $p+1$ pairwise distinct vertices of $D_M$ such that $(x_i,c) \in A(D_M)$ for every $i \in [p]$.
We say that two in-stars $(c_1,x^1_1,\ldots,x^1_{p_1})$ and $(c_2,x^2_1,\ldots,x^2_{p_2})$ are \emph{independent} if $c_1 \neq c_2$ and $\{x_1^1,\ldots,x_{p_1}^1\} \cap \{x_1^2,\ldots,x_{p_2}^2\} = \emptyset$. Note that it is possible that $c_1\in \{x_1^2,\ldots,x_{p_2}^2\}$ or $c_2\in \{x_1^1,\ldots,x_{p_1}^1\}$ (but not both).
See \Cref{fig:instars} for an example.


