 where \(f_N\left((\gamma_1,\beta_1),\frac{\sigma_n^2}{|h|^2}\right)\) denotes the PDF of a Gaussian distribution with mean \((\gamma_1,\beta_1)\) and covariance matrix $(\sigma_n^2/|h|^2)\mathbb{I}_2$, and $D_1$ is the decision region corresponding to $s_1$.
 %the Gaussian MAP decision region~\footnote{The Gaussian MAP decision regions for equiprobable signaling are defined by the Voronoi regions of the constellation points.} corresponding to $s_1$. %The SER given $s_1$ is then computed by averaging over \(h\),
 %\begin{equation}
  %  P_{e|s_1}=1-P_{c|s_1}=1-\iint_{D_1}  \mathbb{E}_h\left[f_N\left(\left(\gamma,\beta\right),\frac{\sigma_n^2}{|h|^2}\right)\right]dxdy. \label{equ:ex_pc}
%\end{equation}

When $\abs{h}$ and $\abs{n}$ are Rayleigh distributed with variances $\sigma_h^2$ and $\sigma_n^2$, respectively, the channel and noise PDFs are
\begin{equation}
    f_{|h|}(\psi) = \frac{\psi}{\sigma_h^2} \exp\left( -\frac{\psi^2}{2\sigma_h^2} \right),\ \ 
    f_{|n|}(\nu) = \frac{\nu}{\sigma_n^2} \exp\left( -\frac{\nu^2}{2\sigma_n^2} \right).\label{channel_and_noise}
\end{equation}
From~\cite[3.461.2b]{gradshteyn2014table}, 
\begin{align}  
\mathbb{E}_h&\left[f_N\left(\left(\gamma_1,\beta_1\right),\frac{\sigma_n^2}{|h|^2}\right)\right]=\nonumber\\ &= \int_0^\infty \hspace{-2.4mm}\frac{\psi^3}{2\pi\sigma^2}  \exp\left(-\psi^2\left(\frac{(x-\gamma_1)^2 \!+\! (y-\beta_1)^2\!+\!\sigma^2}{2\sigma^2} \right) \right)\! d\psi
%&=\int_0^\infty f_N\left(\left(\gamma,\beta\right),\frac{\sigma_n^2}{|h|^2}\right) f(h) dh \nonumber\\ 
\nonumber\\ &=\frac{1}{\pi} \frac{\sigma^2}{(\sigma^2 + (x-\gamma_1)^2 + (y-\beta_1)^2)^2},
\end{align}
where we assumed, without loss of generality (WLoG), \(\sigma_h^2 = 1\) and \(\sigma_n^2 = \sigma^2\). Therefore, the average SER given $s_1$ is
\begin{equation}
    P_{e|s_1}=1-\iint_{D_1} \frac{1}{\pi} \frac{\sigma^2}{(\sigma^2 + (x-\gamma_1)^2 + (y-\beta_1)^2)^2} dxdy. \label{Pc-eq ref}
\end{equation} 
The same procedure applies to other constellation symbols.
%allowing SER calculation under channel-noise independence.

\section{Proposed SER Analyses Framework}
\label{sec:stat-ana}
In this section, we present an alternative method for computing the SER, based on the statistics of the effective noise defined as the ratio between the additive noise and the channel fading, which are not necessarily statistically independent.  
%which  We model statistical dependence between the channel and the noise using two different methods: statistical correlation and the copula method. %%HERE JF

\subsection{Statistical Correlation Model}\label{sec3-1}
 In this setup, effective noise is the ratio between two correlated complex Gaussian terms, $Z = \frac{n}{h}$. 
 %expressed in polar form as
%\begin{equation}
 %   z=\frac{n}{h} =\frac{|n|}{|h|} e^{j (\theta_n-\theta_h)}  =\uprho e^{j \theta_z} =z_r+jz_i,\label{ratio}
%\end{equation}
%where $\abs{n}$ and $\abs{h}$ are both Rayleigh distributed~\eqref{channel_and_noise}, and the phase terms, \( \theta_n \) and \( \theta_h \), and their difference, \(\theta_z\), are all uniformly distributed over \([0, 2\pi]\) \cite{pewsey2013circular}. The PDF of the ratio magnitude, \( \uprho \), denoted as \( f_\uprho(\rho) \) is
%\begin{equation}
 %   f_\uprho(\rho) = \int_{0}^{+\infty} f_{|n|,|h|}(\rho
%\psi,\psi) d\psi,\label{integral}
%\end{equation}
%Because \(\rho\) and \(\theta_z\) are independent, the PDF of the ratio, \( z \), is
%\begin{equation}
%f_{\uprho, \theta_z}(\rho, \theta) = \frac{1}{2\pi}  f_\uprho(\rho).
%\end{equation}
The PDF of $Z$ is given by~\cite{8839853},
\begin{equation}
    f_{Z_r,Z_i}(z_r,z_i)=\frac{1 - \abs{\lambda}^2}{\pi \sigma_n^2\sigma_h^2} 
    \left( \frac{\abs{z}^2}{\sigma_n^2} + \frac{1}{\sigma_h^2} - 2\frac{\lambda_r z_r - \lambda_i z_i}{\sigma_h\sigma_n} \right)^{-2}, \label{pdf-corr}
\end{equation}
where \(\lambda \!=\! \lambda_r + j\lambda_i\) is the complex coefficient of correlation between $n$ and $h$. Setting \(\sigma_h^2 \!=\! 1\) and \(\sigma_n^2/\sigma_h^2\!=\!\sigma^2\), WLoG, we use~\eqref{eq:gen} and the expression in~\eqref{pdf-corr} to find the average SER given that symbol $s_1$ is transmitted,
\begin{align}
    P_{e|s_1} =&\left(\frac{1 - \abs{\lambda}^2}{\pi\sigma^2}\right)\sum_{k=2}^M \iint_{D_k}
    \left( \frac{(x-\gamma_1)^2 + (y-\beta_1)^2}{\sigma^2} + 1 \right. \notag \\
    &\left. \qquad \quad - 2\cdot\frac{\lambda_r(x-\gamma_1) - \lambda_i(y-\beta_1)}{\sigma} \right)^{-2} \, dx \, dy. \label{Pc-eq-corr}
\end{align}
%where %$\Lambda=\frac{1 - \abs{\lambda}^2}{\pi\sigma^2}$. 
Equation~\eqref{Pc-eq-corr} provides a semi-analytical expression of the probability of detection error under a potential noise-channel correlation. The independent case captured by~\eqref{Pc-eq ref} is recovered by inserting $\lambda = 0$. In fact, it can be shown that the proposed~\eqref{eq:gen} and reference~\eqref{eq:stan} methods are equivalent when $n$ and $h$ are independent, regardless of the probability distributions under study. 
