   \frac{3\pi}{2\sigma^2} \left(1 - \frac{\gamma_1}{\sqrt{\sigma^2+\gamma_1^2}} \right)
   + \frac{\pi/2 - \arctan(\gamma_1/\sigma)}{\beta_1\sigma} - \frac{1}{2\gamma_1\beta_1} \notag\\
   &\quad + \frac{\arctan\left( \frac{\gamma_1}{\sqrt{\sigma^2+\beta_1^2}} \right) - \pi/2}{\beta_1\sqrt{\sigma^2+\beta_1^2}}
    + \frac{\beta_1^2+\gamma_1^2}{2\beta_1^2} \arctan\left(\frac{\beta_1}{\gamma_1}\right)
\bigg]. \label{SER_unc}
\end{align}
Equation~\eqref{SER_unc} offers a better approximation than equation~\eqref{SER_corr} for the uncorrelated case as can be observed in Fig.~\ref{fig-ind}.
