\section{Parabolics of $D(2,1;a)$, gradations and prolongations}\label{S2}

%%%
\subsection{The construction of $D(2,1;a)$}

This Lie superalgebra is given by $\fg=\fg_{\bar0}\oplus\fg_{\bar1}$ , where 
 $$
\fg_{\bar0}=\fsl_2\oplus\fsl_2\oplus\fsl_2,\qquad \fg_{\bar{1}} = \CC^2\boxtimes\CC^2\boxtimes\CC^2.
 $$
Each $\fsl_2$ has the standard basis $X,H,Y$ with commutation relations $[H,X]=2X$, $[H,Y]=-2Y$, $[X,Y]=H$. 
Each standard representation $\CC^2$ has coordinates $x,y$ (also: a basis in the space of linear functions)
with the action of $\fsl_2$ given via the operators $x\partial_y$, $x\partial_x-y\partial_y$, $y\partial_x$; thus 
the corresponding basis $X_i,H_i,Y_i$ of the $i$-th copy of $\fsl_2\subset\fg_{\bar0}$ 
acts on $i$-th factor $\CC^2$ of $\fg_{\bar1}$. 

Denote by $\eta_i$ the invariant symplectic forms on the respective copies of $\CC^2$,
normalized by $\eta_i(x,y)=1$, and introduce the isomorphisms 
$\varphi_i:S^2\CC^2\to\fsl_2$ (the $i$-th copy) given by 
$x^2\mapsto X_i$, $-2xy\mapsto H_i$, $-y^2\mapsto Y_i$. 
The odd-odd bracket $[\fg_{\bar{1}},\fg_{\bar{1}}]\subset\fg_{\bar{0}}$ is defined by the formula
 \begin{multline*}
[v_1\otimes v_2\otimes v_3,w_1\otimes w_2\otimes w_3]= 
s_1 \varphi_1(v_1w_1)\eta_2(v_2,w_2)\eta_3(v_3,w_3)\\
+ s_2 \eta_1(v_1,w_1)\varphi_2(v_2w_2)\eta_3(v_3,w_3)
+ s_3 \eta_1(v_1,w_1)\eta_2(v_2,w_2)\varphi_3(v_3w_3)
\end{multline*}
for $v_i,w_i\in\CC^2$ and some $ s_1, s_2, s_3\in\CC$ with $s_1+s_2+s_3=0$ by the Jacobi identity.
(In what follows, we write $xyx$ instead of $x\otimes y\otimes x$, etc.)

This Lie superalgebra will be denoted $\Gamma(s_1,s_2,s_3)$.
It is simple if and only if $ s_1 s_2 s_3\neq0$, see e.g.\ \cite{Scheunert}.
In addition, the Lie superalgebras $\Gamma(s_1,s_2,s_3)$ and $\Gamma(s'_1,s'_2,s'_3)$ are isomorphic 
if and only if $s_i'=\lambda s_{\tau(i)}$, $1\leq i\leq3$, for some $\tau\in S_3$ and $\lambda\in\CC\setminus\{0\}$. 

 \begin{definition}\label{d21alpha} %$\Gamma(-1-a,1,a)$.
For $a\in\CC\setminus\{0,-1\}$, $D(2,1;a)$ is the simple Lie superalgebra $\Gamma( s_1, s_2, s_3)$ with 
\begin{equation}\label{normalization}
 s_1=-1-a,\qquad s_2=1,\qquad s_3=a.
\end{equation}
 \end{definition}

\begin{remark}
The symmetric group $S_3$ changes the parameter so: $a\mapsto\frac1a$ and $a\mapsto-1-a$.
Therefore we can regard $a$ as an element of $\PP^1\setminus\{0,-1,\infty\}$ modulo the action of $S_3$. 
 \end{remark}

The Lie superalgebra $D(2,1;a)$ is isomorphic to $D(2,1)=\mathfrak{osp}(4|2)$ when $a\in\{1,-2,-\frac12\}$.

%%%
\subsection{An analogue to the Killing form}

For $D(2,1;a)$, the Killing form $\op{str}(\op{ad}_x\op{ad}_Y)$ vanishes, however there exists a nondegenerate 
bilinear form $B$ on $\fg$ that is: 
(i) consistent $B(u,v)=0$ if $|u|\neq|v|$, (ii) supersymmetric $B(u,v)=(-1)^{|u||v|}B(v,u)$, 
(iii) invariant $B([u,v],w)=B(v,[u,w])$. It is unique, up to scale, see \cite[Proposition 5.3.]{Kac}.

To get the explicit form of $B$, denote by $K_i$ the Killing form on the $i$-th copy of $\fsl_2$ in $\fg_{\bar{0}}$ ($1\leq i\leq 3$) and let $A=\eta_1\eta_2\eta_3$. Since $S^2\fg_{\bar{0}}^*$ contains three trivial modules for
$\fg_{\bar0}$ while $\Lambda^2(\fg_{\bar{1}}^*)$ only one, this analog of the Killing form 
$B:\fg\otimes\fg\longrightarrow\CC$ should be a linear combination of $K_i$ and $A$, and indeed a computation gives
 \begin{equation}\label{KFB}
B=\frac{1}{4s_1}K_1+\frac{1}{4s_2}K_2+\frac{1}{4s_3}K_3-A.
 \end{equation}

