 \begin{proposition}
For the grading of $\fg=D(2,1;a)$ associated with $\fp_1^{\rm I}$: $\pr(\fm)=\pr(\fm,\fg_0)\neq\fg$.
In fact, $\dim\pr(\fm,\fg_0)=\infty$.
 \end{proposition} 

 \begin{proof}
The prolongation of the Heisenberg superalgebra $\fm$ is the contact algebra 
$\pr(\fm)=\mathfrak{cont}(\fm)$. The distribution $\fg_{-1}$ is odd, so its 
structure algebra is the conformal symplectic algebra
$\fg_0=\mathfrak{co}(4)$. Thus $\pr(\fm)=\pr(\fm,\fg_0)$ and the claim follows.
 \end{proof}

 \begin{proposition}\label{propp1I}
For the grading of $\fg=D(2,1;a)$ associated with $\fp_1^{\rm I}$: $\pr(\fg_{\leq1})=\fg$.
 \end{proposition}

 \begin{proof}
As $\fg_0^{ss}=\sl_2\oplus\sl_2$ modules, $\fg_{-1}=\UU_{1,1}=\fg_1$. 
We first claim that $\pr_2(\fg_{\leq1})=\fg_2$. The space
$\fg_{-1}$ has basis $\{e_1=yxx,e_2=yyx,e_3=yxy,e_4=yyy\}$ with the dual coframe 
$\{\omega^1,\omega^2,\omega^3,\omega^4\}$ and $\fg_1$ has basis $\{f_1=xxx,f_2=xyx,f_3=xxy,f_4=xyy\}$.

We have $\pr_2(\fg_{\leq1}) \hookrightarrow\fg_1\otimes\fg_{-1}^\ast=
\mathbb{V}_{2,2}\oplus\mathbb{V}_{2,0}\oplus\mathbb{V}_{0,2}\oplus\mathbb{V}_{0,0}$, 
and the summands have the following highest weight vectors:
 \begin{align*}
\VV_{2,2}:\, f_1\otimes\omega^4,\qquad
\VV_{0,2}:\, f_3\otimes\omega^4+f_1\otimes\omega^2,\qquad
\VV_{2,0}:\, f_2\otimes\omega^4+f_1\otimes\omega^3,\\
\VV_{0,0}:\, f_1\otimes\omega^1+f_2\otimes\omega^2+f_3\otimes\omega^3+f_4\otimes\omega^4.
 \end{align*}
By Schur's lemma, to determine $\pr_2(\fg_{\leq1})$, it suffices to test \eqref{conditionprolongation} 
on the highest weight vectors:
 \begin{itemize}
  \item If $A=f_1\otimes\omega^4\in\VV_{2,2}$ is in $\pr_2(\fg_{\leq1})$, then 
$0=A[e_2,e_4]=[A e_2,e_4]+[e_2,A e_4]=[e_2,f_1]=s_3X_3\neq0$, which is a contradiction. Therefore $\VV_{2,2}\not\subset\pr_2(\fg_{\leq1})$.
  \item If $B=f_3\otimes\omega^4+f_1\otimes\omega^2$ is in $\pr_2(\fg_{\leq1})$, then $0=B[e_2,e_4]=[Be_2,e_4]+[e_2,Be_4]=[f_1,e_4]+[e_2,f_3]=-s_3H_3\neq0$. 
Therefore $\VV_{0,2}\not\subset\pr_2(\fg_{\leq1})$.
  \item Similarly we can see that $\VV_{2,0}\not\subset\pr_2(\fg_{\leq1})$.
  \item Since $\fg_2\subset\pr_2(\fg_{\leq1})$, then $\pr_2(\fg_{\leq1})=\fg_2=\VV_{0,0}$.
 \end{itemize}
Finally, we have $\pr_3(\fg_{\leq1})\hookrightarrow\fg_2\otimes\fg_{-1}^\ast=\UU_{1,1}$ as a $\fg_0$-module. 
This has highest weight vector $C=X_1\otimes\omega^4\in\UU_{1,1}$. If $C\in\pr_3(\fg_{\leq1})$, then 
$0=C[e_2,e_4]=-[e_2,X_1]=f_2\neq 0$. Therefore $\pr_3(\fg_{\leq1})=0$. This proves that $\pr(\fg_{\leq1})=\fg$.
\end{proof}


