In fact, $\dim\pr(\fm,\fg_0)=\infty$.
 \end{proposition}

 \begin{proof}
It will be shown in Section \ref{TwSec} by geometric arguments that the Lie superalgebra $\pr(\fm)$ for $\fp_{12}^\I$ is
isomorphic to its counterpart for $\fp_1^\I$, namely the Lie superalgebra $\mathfrak{cont}(1|4)$,
though with a different grading. In this case $\fg_0=\gl_2\oplus\CC$ and $\fg_1=\CC^{1|0}\oplus\CC^{0|2}$,
while $\pr_1(\fm,\fg_0)=\CC^{0|2}\oplus\CC^{1|0}\oplus\CC^{0|2}$. Thus also
$\pr(\fm,\fg_0)=\mathfrak{cont}(1|4)$.
 \end{proof}

Let us note that the claim on infinite-dimensionality of $\pr(\fm)$ does not follow from Proposition \ref{inftype},
as the required vector $v\in\fg_{-1}$ does not exist. Consequently, this is an example where the
rigidity criterion for the Tanaka--Weisfeiler prolongation is not sufficient.

 \begin{proposition}
For the grading of $\fg=D(2,1;a)$ associated with $\fp_{12}^{\rm I}$: $\pr(\fg_{\leq1})=\fg$.
 \end{proposition}

 \begin{proof}
Let $\{e_1=Y_2, e_2=yxx, e_3=yxy\}$ be a basis of $\fg_{-1}$ and $\omega^1,\omega^2,\omega^3$
be the dual basis; let $\{e_4=yyx, e_5=yyy\}$ be a basis of $\g_{-2}$ and $\{e_6=Y_1\}$ that for $\g_{-3}$.

Next, let $\{f_1=X_2, f_2=xyx, f_3=xyy\}$ be a basis of $\fg_1=\VV_0\oplus\UU_1$. 
We have $\pr_2(\fg_{\leq1})\hookrightarrow \fg_1\otimes\fg_{-1}^\ast
=\VV_0\oplus\UU_1\oplus\UU_1\oplus\VV_2\oplus\VV_0$
with highest weight vectors of the isotypic components:
 \begin{eqnarray*}
  \VV_0\oplus\VV_0:\,f_1\otimes\omega^1,\,  f_3\otimes\omega^3+f_2\otimes\omega^2;\qquad
  \UU_1\oplus\UU_1:\, f_1\otimes\omega^3,\, f_2\otimes\omega^1;\qquad
  \VV_2:\, f_2\otimes\omega^3.
 \end{eqnarray*}
Let us test the highest weight vectors in $\fg_1\otimes\fg_{-1}^\ast$:
\begin{itemize}
  \item If $A=f_2\otimes\omega^3\in\VV_2$ is in $\pr_2(\fg_{\leq1})$, then $0=A[e_2,e_3]=[A e_2,e_3]+[e_2,Ae_3]=[e_2,f_2]=-s_3 X_3\neq0$, which is a contradiction. Therefore $\VV_2\not\subset\pr_2(\fg_{\leq1})$.
 \item If $B=af_1\otimes\omega^1+b(f_3\otimes\omega^3+ f_2\otimes\omega^2)$ is in $\pr_2(\fg_{\leq1})$, 
then $B e_4=B[e_1,e_2]=[af_1,e_2]+[e_1,bf_2]=0$. Thus $0=B[e_1,e_4]=[af_1,e_4]=ae_2$, so $a=0$.
Similarly, $B[e_2,e_3]=[bf_2,e_3]+[e_2,bf_3]=bs_3H_3$, so $b=0$. 
 \item If $C=cf_1\otimes\omega^3+d\,f_2\otimes\omega^1$ is in $\pr_2(\fg_{\leq1})$, then 
\begin{equation*}
 Ce_5=C[e_1,e_3]=[df_2,e_3]+[e_1,cf_1]=d\left(\frac{s_1}{2}H_1-\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)-cH_2, 
\end{equation*}
and $0=C[e_1,e_5]=[df_2,e_5]+[e_1,d\left(\frac{s_1}{2}H_1-\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)-cH_2]=(-2ds_2-2c) Y_2$, therefore $c=-ds_2$, and $\UU_1\oplus\UU_1\not\subset\pr_2(\fg_{\leq1})$. 
Since $\fg_2\subset\pr_2(\fg_{\leq1})$, so $\pr_2(\fg_{\leq1})=\fg_2=\UU_1$.
 \end{itemize}

Let $\{f_4=xxy,f_5=xxx\}$ be a basis of $\fg_2=\UU_1$.
We have $\pr_3(\fg_{\leq1})\hookrightarrow\fg_2\otimes\fg_{-1}^\ast=\UU_1\oplus\VV_2\oplus\VV_0$
with highest weight vectors of the irreducible components:
 \begin{align*}
  \UU_1:\, f_5\otimes\omega^1;\qquad
  \VV_2:\, f_5\otimes\omega^3;\qquad
  \VV_0:\, f_5\otimes\omega^2+f_4\otimes\omega^3.
\end{align*}
Let us test the highest weight vectors in $\fg_2\otimes\fg_{-1}^\ast$.
\begin{itemize}
  \item If $D=f_5\otimes\omega^1\in\UU_1$ is in $\pr_3(\fg_{\leq1})$, then 
  $D e_4=D[e_1,e_2]=[f_5,e_2]=0
  $ and $0=D[e_1,e_4]=[f_5,e_4]=s_3 X_3\neq 0$. Therefore $\UU_1\not\subset\pr_3(\fg_{\leq1})$.
\item If $E=f_5\otimes\omega^3\in\VV_2$ is in $\pr_3(\fg_{\leq1})$, then $Ee_5=E[e_1,e_3]=[e_1,Ee_3]=[e_1,f_5]=f_2$ and $0=E[e_3,e_5]=[f_5,e_5]+[e_3,f_2]=-s_2 H_2\neq0$. Therefore $\VV_2\not\subset\pr_3(\fg_{\leq1})$.
\item Since $\fg_3\subset\pr_3(\fg_{\leq1})$, we conclude $\pr_3(\fg_{\leq1})=\fg_3=\VV_0$.
 \end{itemize}

Finally, let $\{f_6=X_1\}$ be a basis of $\fg_3=\VV_0$.
We have $\pr_4(\fg_{\leq1})\hookrightarrow\fg_3\otimes\fg_{-1}^\ast=\VV_0\oplus\UU_1$,
and these isotypic components have highest weight vectors:
 \begin{align*}
  \VV_0:\, f_6\otimes\omega^1\qquad
  \UU_1:\, f_6\otimes\omega^3
\end{align*}
Let us test the highest weight vectors in $\fg_3\otimes\fg_{-1}^\ast$.
\begin{itemize}
  \item If $F=f_6\otimes\omega^1\in\VV_0$ is in $\pr_4(\fg_{\leq1})$, then
  $F e_4=F[e_1,e_2]=[f_6,e_2]=f_5
  $, and $0=F[e_1,e_4]=[f_6,e_4]+[e_1,f_5]=2f_2\neq 0$. Therefore $\VV_0\not\subset\pr_4(\fg_{\leq1})$.
\item If $G=f_6\otimes\omega^3\in\UU_1$ is in $\pr_4(\fg_{\leq1})$, then 
$0=G[e_2,e_3]=[e_2,f_6]=-f_5\neq0$. Therefore $\UU_1\not\subset\pr_4(\fg_{\leq1})$, and 
we conclude $\pr_4(\fg_{\leq1})=\fg_4=0$.
 \end{itemize} 
This proves that $\pr(\fg_{\leq1})=\fg$.
 \end{proof}


