\subsection{Superspace $M^{2|2}=G/P_2^\I$}\label{Gpi2}

This is a Hermitian supersymmetric space, since $\fg=\fg_{-1}\oplus\fg_0\oplus\fg_1$ is the grading of 
$\fg=D(2,1;a)$, according to Section \ref{pi2}. Here $\fg_0=\fgl(2|1)=\CC\oplus\fsl(2|1)$ has a basis
 \begin{align*}
Z=\frac{1}{2}H_1+\frac{1}{2}H_2,\quad X=X_3,\quad H=H_3,\quad Y=Y_3,\quad I=\frac{s_1}{s_3}H_1+\left(\frac{s_1}{s_3}+1\right)H_2,\\ F^+=-yxx,\quad F^-=yxy,\quad \overline{F}^+=\frac{1}{s_3}xyx,\quad \overline{F}^-=\frac{1}{s_3}xyy,
 \end{align*}
where $Z$ is the grading element and the rest generates $\ff=\fg_{0}^{ss}=\fsl(2|1)$.

This Lie superalgebra is represented in the linear spaces $\fg_{-1}$ and $\fg_{-1}^*$, with 
the bases and weights given in Table \ref{tab:g-1_weights}.
We refer to Appendix \ref{appendixsl21} for the basics of representation theory of $\ff$.

\begin{table}[h]\centering
    \begin{tabular}{|c|c||c|c|}\hline
Vector & Weight & Vector & Weight \\ \hline
$e_1=Y_2$ & $(b-1,0)$ & $\omega^1$ & $(-b+1,0)$ \\ \hline
$e_2=Y_1$ & $(b+1,0)$ & $\omega^2$ & $(-b-1,0)$\\ \hline
$e_3=yyx$ & $(b,1)$ & $\omega^3$ & $(-b,-1)$\\ \hline
$e_4=yyy$ & $(b,-1)$ & $\omega^4$ & $(-b,1)$\\ \hline
    \end{tabular}
\caption{Bases of $\fg_{-1}$ and $\fg_{-1}^\ast$ with $(I,H)$-weights, $b=-\frac{s_1}{s_3}+\frac{s_2}{s_3}$.}
    \label{tab:g-1_weights}
\end{table}

 \begin{lemma}\label{Le2}
There are precisely two Lie subalgebras $\fk$ with $\fg_0\subset\fk\subset\fgl(\fg_{-1})$, namely
 \begin{eqnarray*}
\fk_1&=&\fg_0+\langle \varphi_1=e_1\otimes\omega^2, \varphi_2=-s_1e_1\otimes\omega^4
   +e_3\otimes\omega^2, \varphi_3=-s_1e_1\otimes\omega^3-e_4\otimes\omega^2\rangle,\\
\fk_2&=&\fg_0+\langle\varphi_4=e_2\otimes\omega^1, \varphi_5=\frac{s_2}{s_3}e_2\otimes\omega^4
   -\frac{1}{s_3}e_3\otimes\omega^1, \varphi_6=-\frac{s_2}{s_3}e_2\otimes\omega^3
   -\frac{1}{s_3}e_4\otimes\omega^1\rangle.
 \end{eqnarray*}
 \end{lemma}

 \begin{proof}
Let us first describe how $\fg_0=\fgl(2|1)$ is embedded in $\fgl(2|2)=\fgl(\fg_{-1})$.

In terms of the representation theory of $\ff$ (Appendix \ref{appendixsl21}), we have $\fg_{-1}=\rho(b,1)$, 
i.e.\ it is an irreducible representation of dimension 4, with highest $H$-weight $1$ and corresponding $I$-weight 
$b=-2\frac{s_1}{s_3}-1=1+\frac2a$. Also, $\fg_{-1}^*=\rho(-b,1)$.
The tensor product $\fg_{-1}\otimes \fg_{-1}^*$ by \cite{Frappat} is equal to:
 \begin{equation*}
\rho(b,1)\otimes\rho(-b,1)=\rho(0,2)\oplus\rho(0;-1,1;0),
 \end{equation*}
where $\rho(0;-1,1;0)$ is a non-completely reducible $\fsl(2|1)$-representation that decomposes as 
semi-direct sums of $\fsl(2|1)$ irreducible representations:
\begin{equation*}
 \rho(0;-1,1;0)=\rho(0,0)\begin{array}{l}
                             \niplus \rho_+(1)\\
                             \niplus \rho_-(1)
                             \end{array}
                             \niplus\rho(0,0).
\end{equation*}
The semi-direct sum symbol $\niplus$ means that the space to the left is an $\ff$-submodule 
(and the space to the right is a quotient), while
 \begin{equation*}
\rho_+(1)=\pi_1(1)\oplus\pi_0(2),\qquad\rho_-(1)=\pi_1(-1)\oplus\pi_0(-2).
 \end{equation*}

We want to find all Lie superalgebras $\fk$ with $\fg_0\subset\fk\subset\fgl(\fg_{-1})$, and those define
$\fg_0$-submodules $V$ of $\fgl(\fg_{-1})/\fg_0$. Thus we proceed by identifying those submodules $V$.

Since the grading element $Z$ acts trivially on $\fgl(\fg_{-1})$, $Z$ generates the invariant $\rho(0,0)$ 
in $\rho(0;-1,1;0)$, and
  \begin{equation*}
\frac{\fgl(\fg_{-1})}{\fg_0}\cong\frac{\rho(0,2)\oplus\left(\rho(0,0)
\begin{array}{l}\niplus \rho_+(1)\\ \niplus \rho_-(1)\end{array}\niplus\rho(0,0)\right)}
{\rho(0,0)\oplus\rho(0,2)}\cong
\begin{array}{l}\rho_+(1)\\ \rho_-(1)\end{array}\niplus\rho(0,0)
  \end{equation*}
has precisely two non-trivial $\fg_0$-invariant subspaces. 
Up to scalar multiple, the only vector in $\fgl(\fg_{-1})$ with weight $(-2,0)$ 
is $\varphi_1=e_1\otimes\omega^2\in\pi_0(-2)\subset\rho_-(1)$, $\varphi_1\not\in\fg_0$. 
Recalling that the dual action is given via the negative of the super-transpose (cf.\ \cite{Frappat}), we compute
 \begin{equation*}
\varphi_2=F^+\cdot\varphi_1=-s_1e_1\otimes\omega^4+e_3\otimes\omega^2,\quad
\varphi_3=F^-\cdot\varphi_1=-s_1e_1\otimes\omega^3-e_4\otimes\omega^2, 
 \end{equation*}
and also $\overline{F}^+\cdot\varphi_1=\overline{F}^-\cdot\varphi_1=0$. The three vectors 
$\varphi_1,\varphi_2,\varphi_3$ generate a subspace $V_1$ with $[V_1,V_1]=0$, $[\fg_0,V_1]\subset V_1$. 
Therefore 
$\mathfrak{k}_1=\fg_0+V_1$ is a Lie superalgebra and $\fg_0\subset \mathfrak{k}_1\subset\fgl(\fg_{-1})$. 

Similarly, $\varphi_4=e_2\otimes\omega^1$, $\varphi_5=\overline{F}^+\cdot\varphi_4=\frac{s_2}{s_3}e_2\otimes\omega^4-\frac{1}{s_3}e_3\otimes\omega^1$ and
$\varphi_6=\overline{F}^-\cdot\varphi_4=-\frac{s_2}{s_3}e_2\otimes\omega^3-\frac{1}{s_3}e_4\otimes\omega^1$ generate an Abelian superalgebra and $\fg_0$-module $V_2$. Therefore
we obtain a Lie superalgebra $\mathfrak{k}_2=\fg_0+V_2$ and $\fg_0\subset\fk_2\subset\fgl(\fg_{-1})$.
 \end{proof}

 \begin{remark}
Geometrically, the reduction of the structure group to $G_0=COSp(2|2)\subset GL(2|2)$ is given 
by a $G_0=\exp\fg_0$ principal bundle $\mathfrak{F}_0\to M$, see \cite{KST2}.
The embedding of the corresponding Lie superalgebras $\fg_0\subset\fgl(\fg_{-1})$, or equivalently,
$\mathfrak{gl}(1|2)=\mathfrak{cosp}(2|2)\subset\mathfrak{gl}(2|2)$
is encoded by the following matrix:
 \begin{equation}\label{sl13=so22}
\begin{pmatrix}
  a_1 & 0 & -s_2b_4 & s_2b_3\\
  0 & a_2 & -s_1b_2 & s_1b_1\\
  b_1 & b_3 & a_1+a_3 & a_4\\
  b_2 & b_4 & a_5 & a_2-a_3
\end{pmatrix}.
 \end{equation}
where $a_1,\dots,a_5$ are even coordinates, $b_1,\dots,b_4$ are odd coordinates
(these describe the embedding through the functor of points as is customary in supergeometry \cite{Va,CCF},
see also \cite[\S2.2]{KST2}). 
For the parameters $s_1,s_2,s_3$ ($s_1+s_2+s_3=0$), only their combination $a=s_3/s_2\in\mathbb{P}^1/S_3$ 
is essential ($a\neq0,-1,\infty$).
 \end{remark}

