Now the space $\mathfrak{c}_1$ decomposes into $\C^{2|0}$ and $\C^{0|2}=\C^{0|1}\otimes\C^2$.
Our higher order structure reduction effects in reducing the latter to one 
$\C^{0|1}=\langle y\theta_1+a\theta_1\theta_2\nu_2\rangle$. 
The following reductions $\g_k\subset\mathfrak{c}_k$ for $k\ge1$ are given by the Tanaka--Weisfeiler prolongation, 
in particular they stop at the level $k=4$.
One may interpret the reduction via the same differential equation as in case 1.

We can also realize this algebra by vector fields locally in the chart 
$\C^{3|4}(x_1,x_2,x_3|\xi_1,\xi_2,\xi_3,\xi_4)\subset M^{3|4}$. The vector fields, corresponding to the
generators of $\m$, are the following ($u$ are even fields, $v$ are odd fields, minus superscript indicates negative
gradation; $\kappa$ is an inessential even parameter to be specified below; one may take $\kappa=1$ for simplicity).
 \begin{gather*}
u^-_1 = \p_{x_1} + \xi_1\p_{\xi_2} + \kappa\xi_1\xi_3\p_{x_3} + x_2\xi_1\p_{\xi_4},\
u^-_2 = \p_{x_2} + \xi_1\p_{\xi_3} + \xi_1\xi_2\p_{x_3} + x_1\xi_1\p_{\xi_4},\
u^-_3 = (\kappa+1)\p_{x_3}, \\
v^-_1 = \p_{\xi_1},\
v^-_2 = \p_{\xi_2} + \kappa\xi_3\p_{x_3} + x_2\p_{\xi_4},\
v^-_3 = \p_{\xi_3} + \xi_2\p_{x_3} + x_1\p_{\xi_4},\
v^-_4 = \p_{\xi_4} + (\kappa + 1)\xi_1\p_{x_3}.
 \end{gather*}
The structure equations are 
$[u^-_1,v^-_1]=v^-_2$, $[u^-_2,v^-_1]=v^-_3$, $[u^-_2,v^-_2]=v^-_4$, 
$[u^-_1,v^-_3]=v^-_4$, $[v^-_1,v^-_4]=-u^-_3$, $[v^-_2,v^-_3]=u^-_3$.
Next, $0^\text{th}$ Tanaka--Weisfeiler prolongation computed for these vector fields gives
 \begin{gather*}
u^0_1 = x_1\p_{x_1} + \xi_2\p_{\xi_2} + \xi_4\p_{\xi_4} + x_3\p_{x_3},\quad
u^0_2 = x_2\p_{x_2} + \xi_3\p_{\xi_3} + \xi_4\p_{\xi_4} + x_3\p_{x_3},\\
u^0_3 = \xi_1\p_{\xi_1} + \xi_2\p_{\xi_2} + \xi_3\p_{\xi_3} + \xi_4\p_{\xi_4} + 2x_3\p_{x_3},
 \end{gather*}
and $Z=u^0_1+u^0_2+u^0_3$ is the grading element.

The next prolongation yields the two-parameter even space
 \begin{gather*}
u^+_1 = x_1^2\p_{x_1} - \xi_2\p_{\xi_1} - (x_2\xi_2+x_1\xi_3-\xi_4)\p_{\xi_3} - x_1(x_2\xi_2-\xi_4)\p_{\xi_4} - \kappa\xi_2(x_1\xi_3-\xi_4)\p_{x_3},\\
u^+_2 = x_2^2\p_{x_2} - \xi_3\p_{\xi_1} - (x_2\xi_2+x_1\xi_3-\xi_4)\p_{\xi_2} - x_2(x_1\xi_3-\xi_4)\p_{\xi_4} - \xi_3(x_2\xi_2-\xi_4)\p_{x_3},
 \end{gather*}
and the two-parameter odd space, which we write in a linear combination with an even parameter:
 \begin{align*}
v^+_1 =&\ (a+1)(x_1\xi_1-\xi_2)\p_{x_1} + (a\kappa-1)(x_2\xi_1-\xi_3)\p_{x_2} + (a+1)\xi_1\xi_2\p_{\xi_2}\\
 &+ (a\kappa-1)\xi_1\xi_3\p_{\xi_3} + (ax_3+a(\kappa+1)\xi_1\xi_4-\xi_2\xi_3)\p_{\xi_4} + a(\kappa+1)x_3\xi_1\p_{x_3}.
 \end{align*}
Fixing this parameter we compute the further prolongations:
 \begin{align*}
v^+_2 =&\ -(a+1)x_1(x_1\xi_1-\xi_2)\p_{x_1} + (a\kappa-1)(x_1\xi_3-\xi_4)\p_{x_2} + (a+1)\xi_1\xi_2\p_{\xi_1}\\
 &+ ((a+1)\xi_1(x_2\xi_2+x_1\xi_3-\xi_4) - a(x_3+\xi_2\xi_3))\p_{\xi_3} 
 + x_1((a+1)\xi_1(x_2\xi_2-\xi_4)+\xi_2\xi_3-ax_3)\p_{\xi_4} \\
 &+ ((a+1)\kappa\xi_1(x_1\xi_2\xi_3-\xi_2\xi_4)-ax_3\xi_2)\p_{x_3},\\
v^+_3 =&\ (a+1)(x_2\xi_2-\xi_4)\p_{x_1} - (a\kappa-1)x_2(x_2\xi_1-\xi_3)\p_{x_2} + (a\kappa-1)\xi_1\xi_3\p_{\xi_1}\\
 &+ ((a\kappa-1)\xi_1(x_2\xi_2+x_1\xi_3-\xi_4) + a(\kappa\xi_2\xi_3-x_3))\p_{\xi_2} + x_2((a\kappa-1)\xi_1(x_1\xi_3-\xi_4)\\
 &+\xi_2\xi_3 -ax_3)\p_{\xi_4} - ((a\kappa-1)\xi_3(x_2\xi_1\xi_2-\xi_1\xi_4) + a\kappa x_3\xi_3)\p_{x_3},\\
v^+_4 =&\ -(a+1)x_1(x_2\xi_2-\xi_4)\p_{x_1} - (a\kappa-1)x_2(x_1\xi_3-\xi_4)\p_{x_2} + (\xi_2\xi_3-ax_3)\p_{\xi_1}
 - (a\kappa-1)\xi_2(x_1\xi_3-\xi_4)\p_{\xi_2} \\
 &- (a+1)\xi_3(x_2\xi_2-\xi_4)\p_{\xi_3} - (\kappa+1)\xi_2\xi_3\xi_4\p_{x_3},\\
u^+_3 =&\ a(a+1)(\kappa+1)(x_1x_2\xi_1\xi_2-x_1\xi_1\xi_4+\xi_2\xi_4)\p_{x_1} + a(a\kappa-1)(\kappa+1)(x_1x_2\xi_1\xi_3 - x_2\xi_1\xi_4+\xi_3\xi_4)\p_{x_2} \\
 &+ a(\kappa+1)\xi_1(ax_3-\xi_2\xi_3)\p_{\xi_1}
 + a(\kappa+1)((a\kappa-1)\xi_1\xi_2(x_1\xi_3-\xi_4)+ax_3\xi_2)\p_{\xi_2} \\
 &- a(\kappa+1)((a+1)\xi_1(x_2\xi_2\xi_3+\xi_3\xi_4) - ax_3\xi_3)\p_{\xi_3} \\
 &+ a(\kappa+1)\xi_4(ax_3-\xi_2\xi_3)\p_{\xi_4} + a(\kappa+1)((\kappa+1)\xi_1\xi_2\xi_3\xi_4+ax_3^2)\p_{x_3}.
 \end{align*}

 \begin{theorem}\label{Tpi123}
Vector fields $(u_i^-,u_j^0,u_k^+|v_i^-,v_j^0,v_k^+)$ realize the algebra $D\bigr(2,1;a(\kappa)\bigl)$
with the parameter $a(\kappa)=\frac{a\kappa-1}{a+1}$ in the space 
$M^{3|4}=\C^{3|4}(x_1,x_2,x_3|y_1,y_2,y_3,y_4)$ equipped with the distribution
 $$
\mathcal{D}=\langle\p_{x_1}+y_3\p_{y_4},\p_{x_2}+y_2\p_{y_4},
\p_{y_1}+x_1\p_{y_2}+x_2\p_{y_3}+x_1x_2\p_{y_3}+(\kappa x_1y_3+x_2y_2-(\kappa+1)y_4)\p_{y_4})\rangle
 $$
naturally split into the sum of two even and one odd lines as indicated by the generators.
 \end{theorem}

 \begin{proof}
The explicit form of the vector fields realizing $\fm$ follows from direct verification of the structure relations
(in other words, $M^{1|4}\simeq\exp\fm$).
Then the fields realizing $\fp$ are obtained by mimicking relations for the Tanaka--Weisfeiler prolongation,
including the higher order reduction. Comparing the brackets of $\fg_{\bar1}$ with those in $D(2,1;a)$
gives the parameters $s_l$. Finally, generators of the distribution $\mathcal{D}$ are obtained from the
condition of commutation with the generators of $\fm$: if the latter are right-invariant vector fields, the former
become left-invariant; we indicate only the basis of $\fg_{-1}$, and this basis is defined up to scale since $\fp$ is Borel.
 \end{proof}


