Next, under the assumption that $s_1,s_2,s_3$ are pairwise distinct, we observe that:
 \begin{enumerate}
\item the derived distribution $\mathcal{C}:= [\mathcal{D},\mathcal{D}]=\langle v_{ij}|v_k\rangle$ is a 
mixed contact distribution;
\item $\mathcal{D}\subset\mathcal{C}$ is a non-holonomic Legendrian distribution, i.e.\ $\mathcal{D}\neq
[\mathcal{D},\mathcal{D}]\subset\mathcal{C}$.
 \end{enumerate}
The contact 1-form $\sigma\in\op{Ann}(\mathcal{C})$ is given by:
 \begin{equation}\label{E:sigma}
\sigma = d\theta - s_2\xi_2\xi_3 d\xi_1 - s_3\xi_3\xi_1 d\xi_2 - s_1\xi_1\xi_2 d\xi_3
- (s_2-s_3)\xi_1 dx_{23} - (s_3-s_1)\xi_2 dx_{31} - (s_1-s_2)\xi_3 dx_{12}.
 \end{equation}

Let us change the variables
 \begin{gather*}
\psi = \theta - (s_2-s_3)x_{23}\xi_1 - (s_3-s_1)x_{31}\xi_2 - (s_1-s_2)x_{12}\xi_3,\\
\psi_1 = s_2\xi_2\xi_3 - (s_2-s_3)x_{23},\ \psi_2 = s_3\xi_3\xi_1 - (s_3-s_1)x_{31},\
\psi_3 = s_1\xi_1\xi_2 - (s_1-s_2)x_{12}.
 \end{gather*}
Note that $\psi$ is odd, while $\psi_i$ are even, thus $M^{3|4}_\diamond=
\C^{3|4}(\psi_1,\psi_2,\psi_2|\xi_1,\xi_2,\xi_3,\psi)$.  
In these coordinates, contact form \eqref{E:sigma} takes the canonical form
 \begin{equation*}
\sigma= d\psi - (d\xi_1)\psi_1 - (d\xi_2) \psi_2 - (d\xi_3) \psi_3.
 \end{equation*}
In the new coordinates our superdistributions have the following generators (indices vary over $1,2,3$):
 \[
\mathcal{D}= \langle v_i = \p_{\xi_i} + \psi_i\p_\psi + \sum_j\psi_{ij}\p_{\psi_j}\rangle\subset
\mathcal{C}= \langle \p_{\psi_i}| \p_{\xi_j} + \psi_j\p_\psi\rangle,
 \]
where $\psi_{ij} = -\psi_{ji}$.  Explicitly,
 \begin{equation}\label{nPDE}
\boxed{\psi_{12} = -s_3\xi_3, \quad \psi_{23} = -s_1\xi_1, \quad \psi_{31} = -s_2\xi_2}.
 \end{equation}
These equations describe a 2nd order PDE, but this is merely a short-hand notation for $\mathcal{D}$ above.  
(Note: This PDE has no solutions!)  More precisely, we have
 \begin{gather*}
v_1 = \p_{\xi_1} + \psi_1 \p_\psi - s_3 \xi_3 \p_{\psi_2} + s_2 \xi_2 \p_{\psi_3}\\
v_2 = \p_{\xi_2} + \psi_2 \p_\psi - s_1 \xi_1 \p_{\psi_3} + s_3 \xi_3 \p_{\psi_1}\\
v_3 = \p_{\xi_3} + \psi_3 \p_\psi - s_2 \xi_2 \p_{\psi_1} + s_1 \xi_1 \p_{\psi_2}
 \end{gather*}
and compare \eqref{v123a}-\eqref{v123b}:
 \begin{gather*}
v_{12}=[v_1,v_2] = (s_2-s_1) \p_{\psi_3}, \quad
v_{23}=[v_2,v_3] = (s_3-s_2) \p_{\psi_1}, \quad
v_{31}=[v_3,v_1] = (s_1-s_3) \p_{\psi_2};\\
[v_1,v_{23}]=(s_2-s_3)\p_\psi,\quad [v_2,v_{31}]=(s_3-s_1)\p_\psi,\quad [v_3,v_{12}]=(s_1-s_2)\p_\psi.
 \end{gather*}

By naturality, any infinitesimal symmetry $S$ of $\mathcal{D}$ is also a symmetry of $\mathcal{C} = 
[\mathcal{D},\mathcal{D}]$, so $S$ is a contact vector field. This corresponds to a generating function 
$f = \iota_{S}\sigma$ as follows:
 \begin{equation}\label{oddXf}
X_f = -\sum_{i=1}^3(\p_{\psi_i} f) D_{\xi_i} + f \p_{\psi} - (-1)^{|f|}\sum_{i=1}^3 (D_{\xi_i} f) \p_{\psi_i}.
 \end{equation}
The Lagrange--Jacobi bracket, given by $[X_f,X_g]=X_{\{f,g\}}$, has the formula
 \begin{equation}\label{LJBodd}
\{f,g\} = f(\p_\psi g) +(-1)^{|f|} (\p_\psi f) g - \sum_{i=1}^3 (\p_{\psi_i} f)(D_{\xi_i} g) 
- (-1)^{|f|} \sum_{i=1}^3 (D_{\xi_i} f)(\p_{\psi_i} g).
 \end{equation}

Now, contracting the symmetry fields given by Table \ref{F:sym} with $\sigma$ given by \eqref{E:sigma}
and rewriting in new coordinates, we obtain the generating functions in Table \ref{F:gf}. 

