\section{Irreducible representations of $\fsl(2|1)$}\label{appendixsl21}

The Lie superalgebra $\fsl(2|1)$ has four even generators $X,H,Y,I$, four odd generators 
$F^\pm$, $\overline{F}^\pm$ and (the only nontrivial) relations:
 \begin{align*}
[H,X]&=2X,  \quad& [H,F^\pm]&=\pm F^\pm\!\!, \quad& [H,\overline{F}^\pm]&=\pm\overline{F}^\pm\!\!,\\
[H,Y]&=-2Y, \quad& [I,F^\pm]&=F^\pm\!\!, \quad& [I,\overline{F}^\pm]&=-\overline{F}^\pm\!\!,\\
[X,Y]&=H,    \quad& [X,F^-]&=-F^+\!\!, \quad& [X,\overline{F}^-]&=\overline{F}^+\!\!,\\
[F^+,\overline{F}^-]&=\tfrac12\left(I-H\right), \quad& [Y,F^+]&=-F^-\!\!, \quad& 
[Y,\overline{F}^+]&=\overline{F}^-\!\!,\\
[F^-,\overline{F}^+]&=\tfrac12\left(I+H\right), \quad& [F^+,\overline{F}^+]&=X, \quad&
[F^-,\overline{F}^-]&=Y.
 \end{align*}

The irreducible representations of $\fsl(2|1)$ are characterized by a pair of labels $(b,m)$ where $b\in\mathbb{C}$ and $m\in\mathbb{N}\cup\{0\}$, cf.\ \cite{Frappat}. 
The representations $\rho(b,m)$ with $b\neq\pm m$ are typical and have dimension $4m$. 
The representations $\rho(\pm m,m)$ are atypical and have dimension $2m+1$. 

The $4m$-dimensional typical representation $\rho(b,m)$ of $\fsl(2|1)$ decomposes under the even part 
$\CC\oplus\fsl_2$ as
 \begin{equation}
\rho(b,m)=\pi_m(b)\oplus\pi_{m-1}(b+1)\oplus\pi_{m-1}(b-1)\oplus\pi_{m-2}(b),
 \end{equation}
where $m$ is the highest $H$-weight, and $b$ is the $I$-weight of the highest $H$-weight vector.

The case $m=1$ is special with the $4$-dimensional representation
 \begin{equation}
\rho(b,1)=\pi_1(b)\oplus\pi_0(b+1)\oplus\pi_0(b-1).
 \end{equation}

 \begin{example}
For the adjoint representation
$\fsl(2|1)=\rho(0,2)=\pi_2(0)\oplus\pi_1(1)\oplus\pi_1(-1)\oplus\pi_0(0)$: % we have
 \begin{itemize}
\item $\pi_2(0)$ is generated by $X,H,Y$; 
\item $\pi_1(1)$ is generated by $F^+,F^-$;
\item $\pi_1(-1)$ is generated by $\overline{F}^+,\overline{F}^-$;
\item $\pi_0(0)$ is generated by $I$.
 \end{itemize}
 \end{example}


