\subsection{Proof of Proposition \ref{propPi23prol} for $\fp_{23}^{\rm I}$}\label{B1}

Let $\{e_1=Y_2,e_2=Y_3,e_3=yxy, e_4=yyx\}$ be a basis of $g_{-1}=\CC^{2|2}$, 
and $\{e_5=Y_1, e_6=yyy\}$ be a basis of $\fg_{-2}$. Let $\omega^i$ be the dual of $e_i$ for $i=1,\dots,6$. 

The non-zero bracket relations in $\fm$ are (see Section \ref{pi23}):
\begin{equation*}
 [e_1,e_3]=e_6,\quad [e_2,e_4]=e_6,\quad [e_3,e_4]=s_1 e_5.
\end{equation*}

\smallskip

First, consider $\pr_1$.
We have $\fg_0\otimes\fg_{-1}^\ast=\CC^{3|2}\otimes\CC^{2|2}=\CC^{10|10}$. If 
$\varphi=(a_1H_1+a_2H_2+a_3H_3)\otimes\omega^1+(b_1H_1+b_2H_2+b_3H_3)\otimes\omega^2+(c_1xyy+c_2yxx)\otimes\omega^3+(d_1xyy+d_2yxx)\otimes\omega^4$ is an even vector in $\pr_1(\fg_{\leq0})\subset\fg_0\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[a_1H_1+a_2H_2+a_3H_3,Y_3]+[Y_2,b_1H_1+b_2H_2+b_3H_3]\\
&=&-2a_3Y_3+2b_2Y_2=0\Rightarrow \boxed{a_3=0},\,\boxed{b_2=0},\\
0&=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[b_1H_1+b_3H_3,yxy]+[Y_3,c_1xyy+c_2yxx]\\
&=& -(b_1+b_3)yxy+c_2yxy=-2b_1yxy\Rightarrow \boxed{b_1=0},\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[a_1H_1+a_2H_2,yyx]+[Y_2,d_1xyy+d_2yxx]\\
&=& -(a_1+a_2)yyx+d_2yyx=-2a_1yyx\Rightarrow \boxed{a_1=0},\\
0&=&\varphi[e_3,e_3]=2[\varphi e_3,e_3]=2[c_1xyy+c_2yxx,e_3]=2c_1s_3Y_3\Rightarrow\boxed{c_1=0},\\
0&=&\varphi[e_4,e_4]=2[\varphi e_4,e_4]=2[d_1xyy+d_2yxx,e_4]=2d_1s_2Y_2\Rightarrow\boxed{d_1=0}.
 \end{eqnarray*}
We compute
 \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[a_2H_2,yxy]+[Y_2,c_2yxx]=
a_2yxy+c_2yyx,\\
\varphi e_6&=&\varphi[e_2,e_4]=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[b_3H_3,yyx]+[Y_3,d_2yxx]=
b_3yyx+d_2yxy,\\
\varphi e_5&=&s_1^{-1}\varphi[e_3,e_4]=s_1^{-1}([\varphi e_3,e_4]+[e_3,\varphi e_4])=0,
 \end{eqnarray*}
whence $\boxed{a_2=d_2}$ and $\boxed{b_3=c_2}$. Then we verify
 \[
\varphi[e_1,e_5]=\varphi[e_1,e_6]=\varphi[e_2,e_5]=\varphi[e_2,e_6]=\varphi[e_3,e_5]=\varphi[e_3,e_6]
=\varphi[e_4,e_5]=0.
 \]
We conclude that $(\pr_1(\fg_{\leq0}))_{\bar0}=\langle H_2\otimes\omega^1+ yxx\otimes\omega^4, H_3\otimes\omega^2+yxx\otimes\omega^3\rangle$.

For the odd part, consider $\varphi=(a_1H_1+a_2H_2+a_3H_3)\otimes\omega^3 +(b_1H_1+b_2H_2+b_3H_3)\otimes\omega^4+(c_1xyy+c_2yxx)\otimes\omega^1+(d_1xyy+d_2yxx)\otimes\omega^2\in 
\pr_1(\fg_{\leq0})\subset\fg_0\otimes\fg_{-1}^\ast$, then:
  \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[c_1xyy+c_2yxx,Y_3]+[Y_2,d_1xyy+d_2yxx]\\
  &=&-c_2yxy+d_2yyx\Rightarrow\boxed{c_2=0},\,\boxed{d_2=0},\\
0&=&\varphi[e_2,e_5]=[\varphi e_2,e_5]+[e_2,\varphi e_5] =[d_1xyy,Y_1]\\
  &&{}+s_1^{-1}[Y_3,(a_3-a_1-a_2)yyx-(b_1-b_2+b_3)yxy]=-s_1^{-1}(a_1+a_2-a_3+s_1d_1)yyy,\\
0&=&\varphi[e_3,e_6]=[\varphi e_3,e_6]-[e_3,\varphi e_6]=[a_1H_1+a_2H_2+a_3H_3,yyy]
  -[yxy,d_1s_2  Y_2+2b_3Y_3]\\
  &=& -(a_1+a_2+a_3-s_2d_1)yyy,\\
0&=&\varphi[e_3,e_3]=2[\varphi e_3,e_3]=2[a_1H_1+a_2H_2+a_3H_3,yxy]=-2(a_1-a_2+a_3),\\
0&=&\varphi[e_1,e_5]=[\varphi e_1,e_5]+[e_1,\varphi e_5]=[c_1xyy,Y_1]\\
  &&+s_1^{-1}[Y_2,(-a_1-a_2+a_3)yyx-(b_1-b_2+b_3)yxy]= -s_1^{-1}(b_1-b_2+b_3+s_1c_1)yyy,\\
0&=&\varphi[e_4,e_6]=[\varphi e_4,e_6]-[e_4,\varphi e_6]=[b_1H_1+b_2H_2+b_3H_3,yyy]
  -[yyx,c_1s_3 Y_3+2a_2Y_2]\\
  &=& -(b_1+b_2+b_3-s_3c_1)yyy,\\
0&=&\varphi[e_4,e_4]=2[\varphi e_4,e_4]=2[b_1H_1+b_2H_2+b_3H_3,yyx]=-2(b_1+b_2-b_3),
\end{eqnarray*}
thus $\boxed{a_1=-\tfrac12s_1d_1},\,\boxed{a_2=\tfrac12s_2d_1},\,\boxed{a_3=-\tfrac12s_3d_1}$ and
$\boxed{b_1=-\tfrac12s_1c_1},\,\boxed{b_2=-\tfrac12s_2c_1},\,\boxed{b_3=\tfrac12s_3c_1}$. Further,
  \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]
 %=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[c_1xyy,yxy]+[Y_2,a_1H_1+a_2H_2+a_3H_3]
 =s_3c_1 Y_3+2a_2 Y_2,\\
\varphi e_6&=&\varphi[e_2,e_4]
 %=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[d_1xyy,yyx]+[Y_3,b_1H_1+b_2H_2+b_3H_3]
 =s_2d_1 Y_2+2b_3Y_3,\\
\varphi e_5&=& s_1^{-1}\varphi[e_3,e_4]
 %=[\varphi e_3,e_4]-[e_3,\varphi e_4]=[a_1H_1+a_2H_2+a_3H_3,yyx]-[yxy,b_1H_1+b_2H_2+b_3H_3]
 =d_1yyx+c_1yxy,
 \end{eqnarray*}
and so we get
 \[
\varphi[e_2,e_3]= \varphi[e_1,e_4]= \varphi[e_1,e_6]= \varphi[e_2,e_6]= \varphi[e_5,e_6]=0.
 \]
We conclude that $(\pr_1(\fg_{\leq0})_{\bar1}=\langle(-s_1H_1+s_2H_2-s_3H_3)\otimes\omega^3+2 xyy\otimes\omega^2,(-s_1H_1-s_2H_2+s_3H_3)\otimes\omega^4+2 xyy\otimes\omega^1\rangle$
and consequently $\pr_1(\fg_{\leq0})=\fg_1$.

\medskip

Next, consider $\pr_2$.
We have $\fg_1\otimes\fg_{-1}^\ast=\CC^{2|2}\otimes\CC^{2|2}=\CC^{8|8}$.   
If $\varphi=(a_1f_1+a_2f_2)\otimes\omega^1+(b_1f_1+b_2f_2)\otimes\omega^2+(c_1f_3+c_2f_4)\otimes\omega^3+(d_1f_3+d_2f_4)\otimes\omega^4$ is an even vector in 
$\pr_2(\fg_{\leq0})\subset\fg_1\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[a_1f_1+a_2f_2,e_2]+[e_1,b_1f_1+b_2f_2]\\
  &=& a_2H_3-b_1H_2 \Rightarrow\boxed{a_2=0},\,\boxed{b_1=0},\\
0 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[b_2f_2,e_3]+[e_2,c_1f_3+c_2f_4]\\
  &=&b_2yxx+c_1xyy\Rightarrow\boxed{b_2=0},\,\boxed{c_1=0},\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[a_1f_1,yyx]+[Y_2,d_1f_3+d_2f_4]\\
  &=&a_1yxx+d_2xyy\Rightarrow\boxed{a_1=0},\,\boxed{d_2=0}.
 \end{eqnarray*}
Then we compute:
 \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[e_1,c_2f_4]=c_2xyy,\\
\varphi e_6 &=&\varphi[e_2,e_4]=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[Y_3,d_1f_3]=d_1xyy    
   \Rightarrow\boxed{d_1=c_2},\\
\varphi e_5 &=&s_1^{-1}\varphi[e_3,e_4]=s_1^{-1}([\varphi e_3,e_4]+[e_3,\varphi e_4])
  =\frac{c_2}{s_1}[xxy,yyx]+\frac{d_1}{s_1}[yxy,xyx]\\
   &=& \frac{c_2}{2s_1}\left(s_1H_1+s_2H_2-s_3H_3\right)
   +\frac{d_1}{2s_1}\left(s_1H_1-s_2H_2+s_3H_3\right)=c_2H_1,\\
0 &=&\varphi[e_1,e_5]=[\varphi e_1,e_5]+[e_1,\varphi e_5]
   =\tfrac12[Y_2,c_2H_1]=0,\\
0 &=&\varphi[e_1,e_6]=[\varphi e_1,e_6]+[e_1,\varphi e_6]=[Y_2,c_2xyy]=0.
 \end{eqnarray*}
We conclude that $(\pr_2(\fg_{\leq0}))_{\bar0}=\langle f_4\otimes\omega^3+f_3\otimes\omega^4\rangle$.

For the odd part, consider $\varphi=(a_1f_3+a_2f_4)\otimes\omega^1+(b_1f_3+b_2f_4)\otimes\omega^2
+(c_1f_1+c_2f_2)\otimes\omega^3+(d_1f_1+d_2f_2)\otimes\omega^4\in\pr_2(\fg_{\leq0})\subset
\fg_1\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[b_1f_3+b_2f_4,e_3]+[e_2,c_1f_1+c_2f_2]\\
  &=&b_1\left(\frac{1}{s_1}H_1-\frac{1}{s_2}H_2+\frac{1}{s_3}H_3\right)-c_2H_3
  \Rightarrow\boxed{b_1=0},\,\boxed{c_2=0},\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[a_1f_3+a_2f_4,yyx]+[Y_2,d_1f_1+d_2f_2]\\
  &=&a_2\left(\frac{1}{s_1}H_1+\frac{1}{s_2}H_2-\frac{1}{s_3}H_3\right)-d_1H_2
 \Rightarrow\boxed{a_2=0},\,\boxed{d_1=0},\\
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[a_1f_3,e_2]+[e_1,b_2f_4]=(b_2-a_1)xyy \Rightarrow\boxed{b_2=a_1}.
  \end{eqnarray*}
Furthermore,
 \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]=[a_1f_3,e_3]+[e_1,c_1f_1]
=a_1\left(\frac{1}{s_1}H_1-\frac{1}{s_2}H_2+\frac{1}{s_3}H_3\right)-c_1H_2,\\
\varphi e_6&=&\varphi[e_2,e_4]=[b_2f_4,yyx]+[Y_3,d_2f_2]
=b_2\left(\frac{1}{s_1}H_1+\frac{1}{s_2}H_2-\frac{1}{s_3}H_3\right)-d_2H_3.
 \end{eqnarray*}
Therefore $\boxed{s_2c_1=-2a_1}$, $\boxed{s_3d_2=-2a_1}$. We conclude that 
$(\pr_2(\fg_{\leq0}))_{\bar1}=\langle f_3\otimes\omega^1+f_4\otimes\omega^2
-\frac{2}{s_2}f_1\otimes\omega^3-\frac{2}{s_3}f_2\otimes\omega^4\rangle$ and consequently
$\pr_2(\fg_{\leq0})=\fg_2$.

\medskip

Finally, consider $\pr_3$.
We have $\fg_2\otimes\fg_{-1}^\ast=\CC^{1|1}\otimes\CC^{2|2}=\CC^{4|4}$.  
If $\varphi=af_5\otimes\omega^1+b f_5\otimes\omega^2+c f_6\otimes\omega^3+d f_6\otimes\omega^4$ 
is an even vector in $\pr_3(\fg_{\leq0})\subset\fg_2\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[af_5,e_3]+[e_1,cf_6]=axxy+cxyx,\\
\varphi e_6&=&\varphi[e_2,e_4]=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[bf_5,e_4]+[e_2,df_6]=bxyx+dxxy.\\
 \end{eqnarray*}
Hence $\boxed{a=d}$, $\boxed{b=c}$. Furthermore,
 \begin{eqnarray*}
0 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[bf_5,e_3]+[e_2,cf_6]=bxxy+cxxy
   \Rightarrow\boxed{b=-c},\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[af_5,e_4]+[Y_2,df_6]=axyx+bxxy
   \Rightarrow\boxed{a=-b}.
  \end{eqnarray*}
Therefore $\pr_3(\fg_{\leq0})_{\bar0}=0$. For the odd part, consider 
$\varphi=a f_6\otimes\omega^1+b f_6\otimes\omega^2+c f_5\otimes\omega^3+d f_5\otimes\omega^4
\in\pr_3(\fg_{\leq0})\subset\fg_2\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_6 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[af_6,e_3]+[e_1,cf_5]=as_2f_1,\\
\varphi e_6&=&\varphi[e_2,e_4]=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[bf_6,e_4]+[Y_3,df_5]=bs_3f_2.\\
 \end{eqnarray*}
Hence $\boxed{a=0},\,\boxed{b=0}$. Furthermore,
 \begin{eqnarray*}
  s_1\varphi e_5&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]-[e_3,\varphi e_4]=[cf_5,e_4]-[e_3,df_5]=cf_3-df_4\\
 0 &=&\varphi[e_3,e_5]=[\varphi e_3,e_5]-[e_3,\varphi e_5]=[cf_5,e_5]-[e_3,\frac{1}{s_1}(cf_3-df_4)]=\\
 &=&cH_1-\frac{c}{s_1}(\frac{s_1}{2}H_1-\frac{s_2}{2}H_2+\frac{s_3}{2}H_3)\Rightarrow\boxed{c=0}\\
 0&=&\varphi[e_4,e_5]=[\varphi e_4,e_5]-[e_4,\varphi e_4]=[df_5,e_5]+[e_4,\frac{1}{s_1}(cf_3-df_4)]=\\
 &=&dH_1-\frac{c}{s_1}(\frac{s_1}{2}H_1+\frac{s_2}{2}H_2-\frac{s_3}{2}H_3)\Rightarrow\boxed{d=0}.
  \end{eqnarray*}
Therefore $\pr_3(\fg_{\leq0})_{\bar1}=0$ and we have finished the proof. \hfill\qed


