\subsection{Proof of Proposition \ref{propPi123prol} for $\fp_{123}^\I$}\label{B2}

Let $\{e_1=Y_2,e_2=Y_3,e_3=yxx\}$ be a basis of $\fg_{-1}$, $\{e_4=yyx,e_5=yxy\}$ be a basis of $\fg_{-2}$, 
$\{e_6=yyy\}$ be a basis of $\fg_{-3}$ and $\{e_7=Y_1\}$ be a basis of $\fg_{-4}$. 
Let $\omega^i$ be the dual of $e_i$ for $i=1,\dots,7$. 
The non-zero bracket relations in $\fm$ are (see Section \ref{pi123}):
 \begin{equation*}
[e_1,e_3]=e_4,\quad [e_2,e_3]=e_5,\quad [e_1,e_5]=e_6,\quad [e_2,e_4]=e_6,\quad [e_4,e_5]=s_1 e_7,\quad [e_3,e_6]=-s_1 e_7.
 \end{equation*}

\smallskip

First, consider $\pr_2$.
We have $\fg_1\otimes\fg_{-1}^\ast=\CC^{2|1}\otimes\CC^{2|1}=\CC^{5|4}$.
Let $\{f_1=X_2,f_2=X_3,f_3=xyy\}$ be a basis of $\fg_{1}$. 
If $\varphi=(a_1f_1+a_2f_2)\otimes\omega^1+(b_1f_1+b_2f_2)\otimes\omega^2+c f_3\otimes\omega^3$ 
is an even vector in $\pr_2(\fg_{\leq1})\subset\fg_1\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[a_1f_1+a_2f_2,e_2]+[e_1,b_1f_1+b_2f_2]=\\
   &=&a_2H_3+b_1H_2\Rightarrow\boxed{a_2=0},\,\boxed{b_1=0},\\
\varphi e_4&=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[a_1f_1,e_3]+[e_1,cf_3]=0,\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[a_1f_1,e_4]=a_1e_3\Rightarrow\boxed{a_1=0},\\
\varphi e_5&=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[b_2f_2,e_3]+[e_2,cf_3]=0,\\
0&=&\varphi[e_2,e_5]=[\varphi e_2,e_5]+[e_2,\varphi e_5]=[b_2f_2,e_5]=b_2e_3\Rightarrow\boxed{b_2=0},\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]+[e_3,\varphi e_4]=[cf_3,e_4]=cs_2e_1\Rightarrow\boxed{c=0}.
 \end{eqnarray*}
Thus $(\fg_2)_{\bar0}=0$.
For the odd part, consider $\varphi=a f_3\otimes\omega^1+b f_3\otimes\omega^2+ (cf_1+df_2)\otimes\omega^3\in\pr_2(\fg_{\leq1})\subset\fg_1\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_4&=&\varphi[e_1,e_3]=[af_3,e_3]+[e_1,cf_1+df_2]
   =a\left(-\frac{s_1}{2}H_1+\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)-cH_2,\\
0&=&\varphi[e_1,e_4]=[af_3,e_4]+[e_1,a\left(-\frac{s_1}{2}H_1+\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)
   -cH_2]=2(as_2-c)e_1,\\
\varphi e_5&=&\varphi[e_2,e_3]=[bf_3,e_3]+[e_2,cf_1+df_2]
   =b\left(-\frac{s_1}{2}H_1+\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)-bH_3,\\
0&=&\varphi[e_2,e_5]=[bf_3,e_5]+[e_1,b\left(-\frac{s_1}{2}H_1+\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)
   -dH_3]=2(bs_3-d)e_2.
 \end{eqnarray*}
Hence $\boxed{c=s_2a}$, $\boxed{d=s_3b}$. Since $(\fg_2)_{\bar1}\subset\pr_2(\fg_{\leq1})$, we conclude
$\pr_2(\fg_{\leq1})=\CC^{0|2}=\fg_2$.

\medskip

Next, consider $\pr_3$.
We have $\fg_2\otimes\fg_{-1}^\ast=\CC^{0|2}\otimes\CC^{2|1}=\CC^{2|4}$.
Let $\{f_4=xxy,f_5=xyx\}$ be a basis of $g_2$. 
If $\varphi=(af_4+bf_5)\otimes \omega^3$ is an even vector in 
$\pr_3(\fg_{\leq1})\subset\fg_2\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_4&=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[e_1,af_4+bf_5]=af_3,\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]+[e_3,\varphi e_4]=[af_4+bf_5,e_4]+[e_3,af_3]=\\
   &=&a\left(\frac{s_1}{2}H_1+\frac{s_2}{2}H_2-\frac{s_3}{2}H_3\right)+a\left(-\frac{s_1}{2}H_1
   +\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)=as_2 H_2\Rightarrow\boxed{a=0},\\
\varphi e_5&=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[e_2,af_4+bf_5]=bf_3,\\
0&=&\varphi[e_3,e_5]=[\varphi e_3,e_5]+[e_3,\varphi e_5]=[af_4+bf_5,e_5]+[e_3,bf_3]=\\
   &=&b\left(\frac{s_1}{2}H_1-\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)+b\left(-\frac{s_1}{2}H_1
   +\frac{s_2}{2}H_2+\frac{s_3}{2}H_3\right)=bs_3 H_3\Rightarrow\boxed{b=0}.
\end{eqnarray*}
Therefore $\pr_3(\fg_{\leq1})_{\bar0}=0$. For the odd part, consider 
$\varphi=(af_4+bf_5)\otimes\omega^1+ (cf_4+df_5)\otimes\omega^2\in
\pr_3(\fg_{\leq1})\subset\fg_2\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[af_4+bf_5,e_3]+[e_1,cf_4+df_5]=-(b+c)f_3,\\
\varphi e_4&=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[af_4+bf_5,e_3]=-as_2 f_1-bs_3 f_2,\\
0&=&\varphi[e_1,e_4]=[af_4+bf_5,e_4]+[e_1,-as_2 f_1-bs_3 f_2]=\tfrac12a(s_1H_1+3s_2H_2-s_3H_3),\\
\varphi e_5&=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[cf_4+df_5,e_3]=-cs_2 f_1-ds_3 f_2,\\
0&=&\varphi[e_2,e_5]=[cf_4+df_5,e_5]+[e_2,-cs_2 f_1-ds_3 f_2]=\tfrac12d(s_1H_1-s_2H_2+3s_3H_3).
\end{eqnarray*}
Hence $\boxed{a=0}$, $\boxed{d=0}$ and $\boxed{b=-c}$. We conclude 
$\pr_3(\fg_{\leq1})=\CC^{0|1}=\fg_3$.

\medskip

Next, consider $\pr_4$. We have $\fg_3\otimes\fg_{-1}^\ast=\CC^{0|1}\otimes\CC^{2|1}\CC^{1|2}$.
Let $\{f_6=xxx\}$ be a basis of $\fg_3$. 
If $\varphi=af_6\otimes\omega^1+b f_6\otimes\omega^2$ is an even vector in 
$\pr_4(\fg_{\leq1})\subset\fg_3\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[af_6,e_2]+[e_1,bf_6]=-af_4+bf_5,
 \end{eqnarray*}
therefore $\boxed{a=0}$, $\boxed{b=0}$. 
For the odd part, only $\varphi=cf_6\otimes\omega^3$ is the candidate. However, since 
$\fg_4\subset\pr_4(\fg_{\leq1})$, $c$ is un-restricted, and we conclude $\pr_4(\fg_{\leq1})=\CC^{1|0}=\fg_4$.

\medskip

Finally, consider $\pr_5$. Let $\{f_7=X_1\}$ be a basis of $\fg_4$. 
We have $\fg_4\otimes\fg_{-1}^\ast=\CC^{1|0}\otimes\CC^{2|1}=\CC^{2|1}$.
If $\varphi=af_7\otimes\omega^1+b f_7\otimes\omega^2$ is an even vector in
$\pr_5(\fg_{\leq1})\subset\fg_4\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_4&=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[af_7,e_3]=af_6,\\
0&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[af_7,e_4]+[e_1,af_6]=2af_5,\\
\varphi e_5&=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[bf_7,e_3]=bf_6,\\
 0&=&\varphi[e_2,e_5]=[\varphi e_2,e_5]+[e_2,\varphi e_5]=[bf_7,e_5]+[e_2,bf_6]=2bf_4.
 \end{eqnarray*}
Hence $\boxed{a=0}$, $\boxed{b=0}$, and $\pr_5(\fg_{\leq1})_{\bar0}=0$. For the odd part, 
consider $\varphi= c f_7\otimes\omega^3\in\pr_5(\fg_{\leq1})\subset\fg_4\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
\varphi e_4&=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[e_1,cf_7]=0,\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]+[e_3,\varphi e_4]=[cf_7,e_4]=ce_5\neq0.
 \end{eqnarray*}
Hence $\boxed{c=0}$, and we conclude $\pr_5(\fg_{\leq1})_{\bar1}=0$. \hfill\qed


