\subsection{Proof of Proposition \ref{propPiv123prol} for $\fp_{123}^\IV$}\label{B3}

Let $\{e_1=xyy,e_2=yxy,e_3=yyx\}$ be a basis of $\fg_{-1}$, $\{e_4=Y_1,e_5=Y_2,e_6=Y_3\}$ be a basis of 
$\fg_{-2}$, and $\{e_7=yyy\}$ be a basis of $\fg_{-3}$. Let $\omega^i$ be the dual of $e_i$ for $i=1,\dots,7$.
Note that the gradation is parity consistent, so the prolongations will be parity consistent as well. 

The non-zero bracket relations in $\fm$ are the following (see Section \ref{piv123}):
 \begin{equation*}
[e_1,e_2]=s_3 e_6,\enspace [e_1,e_3]=s_2 e_5,\enspace [e_2,e_3]=s_1 e_4,\enspace
[e_1,e_4]=-e_7,\enspace [e_2,e_5]=- e_7, \enspace [e_3,e_6]=-e_7.
 \end{equation*}

\smallskip

First, consider $\pr_0$. We have $\fg_{-1}\otimes\fg_{-1}^\ast=\CC^{0|3}\otimes\CC^{0|3}=\CC^{9|0}$.
If $\varphi=(a_1e_1+a_2e_2+a_3e_3)\otimes\omega^1+(b_1e_1+b_2e_2+b_3e_3)\otimes\omega^2+(c_1e_1+c_2e_2+c_3e_3)\otimes\omega^3\in\pr_0(\fm)\subset\fg_{-1}\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
s_3\varphi e_6 &=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=
   a_3s_1e_4+b_3s_2e_5+s_3(a_1+b_2)e_6,\\
s_2\varphi e_5 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=
   a_2s_1e_4+s_2(a_1+c_3)e_5+c_2s_3e_6,\\
s_1\varphi e_4 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=
   s_1(b_2+c_3)e_4+b_1s_2e_5+c_1s_3e_6.
 \end{eqnarray*}
This yields 
 \begin{eqnarray*}
0&=&\varphi[e_1,e_5]=[\varphi e_1,e_5]+[e_1,\varphi e_5]=[a_1e_1+a_2e_2+a_3e_3,e_5]\\
   && {}+[e_1,s_2^{-1}(a_2s_1e_4+c_2s_3e_6)+(a_1+c_3)e_5]=a_2\frac{s_3}{s_2}e_7 
   \Rightarrow\boxed{a_2=0},\\
0&=&\varphi[e_1,e_6]=[\varphi e_1,e_6]+[e_1,\varphi e_6]=[a_1e_1+a_2e_2+a_3e_3,e_6]\\ 
   && {}+[e_1,s_3^{-1}(a_3s_1e_4+b_3s_2e_5)+(a_1+b_2)e_6]=a_3\frac{s_2}{s_3}e_7
   \Rightarrow\boxed{a_3=0},\\
0&=&\varphi[e_2,e_4]=[\varphi e_2,e_4]+[e_2,\varphi e_4]=[b_1e_1+b_2e_2+b_3e_3,e_4]\\
   && {}+[e_2,s_1^{-1}(b_1s_2e_5+c_1s_3e_6)+(b_2+c_3)e_4]=b_1\frac{s_3}{s_1}e_7
   \Rightarrow\boxed{b_1=0},\\
0&=&\varphi[e_2,e_6]=[\varphi e_2,e_6]-[e_2,\varphi e_6]=[b_1e_1+b_2e_2+b_3e_3,e_6]\\
   && {}+[e_2,s_3^{-1}(a_3s_1e_4+b_3s_2e_5)+(a_1+b_2)e_6]=b_3\frac{s_1}{s_3}e_7
   \Rightarrow\boxed{b_3=0},\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]+[e_3,\varphi e_4]=[c_1e_1+c_2e_2+c_3e_3,e_4]\\
   && {}+[e_3,s_1^{-1}(b_1s_2e_5+c_1s_3e_6)+(b_2+c_3)e_4]=c_1\frac{s_2}{s_1}e_7
   \Rightarrow\boxed{c_1=0},\\
0&=&\varphi[e_3,e_5]=[\varphi e_3,e_5]+[e_3,\varphi e_5]=[c_1e_1+c_2e_2+c_3e_3,e_5]\\
   && {}+[e_3,s_2^{-1}(a_2s_1e_4+c_2s_3e_6)+(a_1+c_3)e_5]=c_2\frac{s_1}{s_2}e_7
   \Rightarrow\boxed{c_2=0}.
 \end{eqnarray*}
Furthermore,
 \begin{eqnarray*}
-\varphi e_7&=&\varphi[e_1,e_4]=[\varphi e_1,e_4]+[e_1,\varphi e_4]=[a_1e_1,e_4]+[e_1,(b_2+c_3)e_4]=-(a_1+b_2+c_3)e_7,\\
-\varphi e_7&=&\varphi[e_2,e_5]=[\varphi e_2,e_5]+[e_2,\varphi e_5]=[b_2e_2,e_5]+[e_2,(a_1+c_3)e_5]=-(a_1+b_2+c_3)e_7,\\
-\varphi e_7&=&\varphi[e_3,e_6]=[\varphi e_3,e_6]+[e_3,\varphi e_6]=[c_3e_3,e_6]+[e_3,(a_1+b_2)e_6]=-(a_1+b_2+c_3)e_7,
 \end{eqnarray*}
which implies
 \[
\varphi[e_1,e_7]=\varphi[e_1,e_1]=\varphi[e_2,e_2]=\varphi[e_3,e_3]=\varphi[e_7,e_7]=0.
 \]
We conclude that $\pr_0(\fm)=\langle  e_1\otimes\omega^1, e_2\otimes\omega^2, e_3\otimes\omega^3\rangle
=\fg_0$.

\medskip

Next, consider $\pr_1$. We have $\fg_0\otimes\fg_{-1}^\ast=\CC^{3|0}\otimes\CC^{0|3}=\CC^{0|9}$.
If $\varphi=(a_1H_1+a_2H_2+a_3H_3)\otimes\omega^1+(b_1H_1+b_2H_2+b_3H_3)\otimes\omega^2+(c_1H_1+c_2H_2+c_3H_3)\otimes\omega^3\in\pr_1(\fm)\subset\fg_0\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
s_3\varphi e_6 &=&\varphi[e_1,e_2]=[\varphi e_1,e_2]-[e_1,\varphi e_2]=(a_2-a_1-a_3)e_2+(b_1-b_2-b_3)e_1,\\
s_2\varphi e_5 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]-[e_1,\varphi e_3]=(a_3-a_1-a_2)e_3+(c_1-c_2-c_3)e_1,\\
s_1\varphi e_4 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]-[e_2,\varphi e_3]=(b_3-b_1-b_2)e_3+(c_2-c_1-c_3)e_2.
 \end{eqnarray*}
Furthermore, 
 \begin{eqnarray*}
0&=&\varphi[e_1,e_5]=[\varphi e_1,e_5]-[e_1,\varphi e_5]=-2a_2e_5-[e_1,s_2^{-1}
   \bigl((c_1-c_2-c_3)e_1+(a_3-a_1-a_2)e_3\bigr)]\\
   &=& (a_1-a_2-a_3)e_5\Rightarrow\boxed{a_1-a_2-a_3=0},\\
0&=&\varphi[e_2,e_6]=[\varphi e_2,e_6]-[e_2,\varphi e_6]=-2b_3e_6-[e_2,s_3^{-1}
   \bigl((b_1-b_2-b_3)e_1+(a_2-a_1-a_3)e_2\bigr)]\\
  &=& (b_2-b_1-b_3)e_6\Rightarrow\boxed{b_2-b_1-b_3=0},\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]-[e_3,\varphi e_4]=-2c_1e_4-[e_3,s_1^{-1}
   \bigl((c_2-c_1-c_3)e_2+(b_3-b_1-b_2)e_3\bigr)]\\
   &=& (c_3-c_1-c_2)e_4\Rightarrow\boxed{c_3-c_1-c_2=0}
 \end{eqnarray*}
and this implies $\varphi[e_1,e_6]=\varphi[e_2,e_4]=\varphi[e_3,e_5]=0$. In addition, 
 \begin{eqnarray*} 
-\varphi e_7&=&\varphi[e_1,e_4]=-2a_1e_4-[e_1,s_1^{-1}
   \bigl((c_2-c_1-c_3)e_2+(b_3-b_1-b_2)e_3\bigr)]=\\
  &=& -2a_1e_4-\frac{s_2}{s_1}(b_3-b_1-b_2)e_5-\frac{s_3}{s_1}(c_2-c_1-c_3)e_6,\\
-\varphi e_7&=&\varphi[e_2,e_5]=-2b_2e_5-[e_2,s_2^{-1}
   \bigl((c_1-c_2-c_3)e_1+(a_3-a_1-a_2)e_3\bigr)]=\\
  &=& -2b_2e_5-\frac{s_1}{s_2}(a_3-a_1-a_2)e_4-\frac{s_3}{s_2}(c_1-c_2-c_3)e_6,\\
-\varphi e_7&=&\varphi[e_3,e_6]=-2c_3e_6-[e_3,s_3^{-1}
   \bigl((b_1-b_2-b_3)e_1+(a_2-a_1-a_3)e_2\bigr)]=\\
   &=& -2c_3e_6-\frac{s_1}{s_3}(a_2-a_1-a_3)e_4-\frac{s_2}{s_3}(b_1-b_2-b_3)e_5.
   \end{eqnarray*}
Consequently, 
$\boxed{\frac{a_2}{s_2}=\frac{a_3}{s_3}=-\frac{a_1}{s_1}}$, 
$\boxed{\frac{b_1}{s_1}=\frac{b_3}{s_3}=-\frac{b_2}{s_2}}$, 
$\boxed{\frac{c_1}{s_1}=\frac{c_2}{s_2}=-\frac{c_3}{s_3}}$, and we conclude that
$\pr_1(\fm)=\langle(-s_1H_1+s_2H_2+s_3H_3)\otimes\omega^1,(s_1H_1-s_2H_2+s_3H_3)\otimes\omega^2,(s_1H_1+s_2H_2-s_3H_3)\otimes\omega^3\rangle=\fg_1$.

\medskip

Next,  consider $\pr_2$. We have $\fg_1\otimes\fg_{-1}^\ast=\CC^{0|3}\otimes\CC^{0|3}=\CC^{9|0}$.
If $\varphi=(a_1f_1+a_2f_2+a_3f_3)\otimes\omega^1+(b_1f_1+b_2f_2+b_3f_3)\otimes\omega^2+(c_1f_1+c_2f_2+c_3f_3)\otimes\omega^3\in\pr_2(\fm)\subset\fg_1\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
 s_3\varphi e_6 &=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=
 \frac{a_2-b_1}{2}s_1H_1+\frac{b_1-a_2}{2}s_2H_2+\frac{a_2+b_1}{2}s_3H_3,\\
 s_2\varphi e_5 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=
 \frac{a_3-c_1}{2}s_1H_1+\frac{a_3+c_1}{2}s_2H_2+\frac{c_1-a_3}{2}s_3H_3,\\
 s_1\varphi e_4 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=
 \frac{b_3+c_2}{2}s_1H_1+\frac{b_3-c_2}{2}s_2H_2+\frac{c_2-b_3}{2}s_3H_3,
 \end{eqnarray*}
whence
 \begin{eqnarray*}
-\varphi e_7&=&\varphi[e_1,e_4]=[a_1f_1+a_2f_2+a_3f_3,e_4]+\left[e_1,
  \frac{b_3+c_2}{2}H_1+\frac{b_3-c_2}{2}\frac{s_2}{s_1}H_2+\frac{c_2-b_3}{2}\frac{s_3}{s_1}H_3\right]\\
  &=& \left(-\frac{b_3+c_2}{2}+\frac{b_3-c_2}{2}\frac{s_2}{s_1}+\frac{c_2-b_3}{2}\frac{s_3}{s_1}\right)e_1
  -a_3e_2-a_2e_3,\\
-\varphi e_7&=&\varphi[e_2,e_5]=[b_1f_1+b_2f_2+b_3f_3,e_5]+\left[e_2,
   \frac{a_3-c_1}{2}\frac{s_1}{s_2}H_1+\frac{a_3+c_1}{2}H_2+\frac{c_1-a_3}{2}\frac{s_3}{s_2}H_3\right]\\
  &=& -b_3e_1
  +\left(\frac{a_3-c_1}{2}\frac{s_1}{s_2}-\frac{a_3+c_1}{2}+\frac{c_1-a_3}{2}\frac{s_3}{s_2}\right)e_2-b_1e_3,\\
-\varphi e_7&=&\varphi[e_3,e_6]=[c_1f_1+c_2f_2+c_3f_3,e_6]+\left[e_3,
   \frac{a_2-b_1}{2}\frac{s_1}{s_3}H_1+\frac{b_1-a_2}{2}\frac{s_2}{s_3}H_2+\frac{a_2+b_1}{2}H_3\right]\\
  &=& -c_2e_1-c_1e_2
  +\left(\frac{a_2-b_1}{2}\frac{s_1}{s_3}+\frac{b_1-a_2}{2}\frac{s_2}{s_3}-\frac{a_2+b_1}{2}\right)e_3.
 \end{eqnarray*}
Thus $\boxed{b_1=a_2}$, $\boxed{c_2=b_3}$, $\boxed{a_3=c_1}$, and
$\varphi e_4=b_3H_1$, $\varphi e_5=c_1H_2$, $\varphi e_6=a_2H_3$. Furthermore,
 \begin{eqnarray*}
0&=&\varphi[e_1,e_5]=[\varphi e_1,e_5]+[e_1,\varphi e_5]=-a_1e_3\Rightarrow\boxed{a_1=0},\\
0&=&\varphi[e_2,e_6]=[\varphi e_2,e_6]+[e_2,\varphi e_6]=-b_2e_1\Rightarrow\boxed{b_2=0},\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]+[e_3,\varphi e_4]=-c_3e_2\Rightarrow\boxed{c_3=0},
 \end{eqnarray*}
and we also compute $\varphi[e_1,e_6]=\varphi[e_2,e_4]=\varphi[e_3,e_5]=0$. 
We conclude $\pr_2(\fm)=\langle f_2\otimes\omega^1+ f_1\otimes\omega^2, f_3\otimes\omega^1+ f_1\otimes\omega^3,f_3\otimes\omega^2+ f_2\otimes\omega^3\rangle=\fg_2$.

\medskip

Next, consider $\pr_3$.
We have $\fg_2\otimes\fg_{-1}^\ast=\CC^{3|0}\otimes\CC^{0|3}=\CC^{0|9}$.
If $\varphi=(a_1f_4+a_2f_5+a_3f_6)\otimes\omega^1+(b_1f_4+b_2f_5+b_3f_6)\otimes\omega^2+(c_1f_4+c_2f_5+c_3f_6)\otimes\omega^3\in\pr_3(\fm)\subset\fg_2\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
s_3\varphi e_6 &=&\varphi[e_1,e_2]=[\varphi e_1,e_2]-[e_1,\varphi e_2]=a_3f_1+b_3f_2+(a_1+b_2)f_3,\\
s_2\varphi e_5 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]-[e_1,\varphi e_3]=a_2f_1+(a_1+c_3)f_2+c_2f_3,\\
s_1\varphi e_4 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]-[e_2,\varphi e_3]=(b_2+c_3)f_1+b_1f_2+c_1f_3,
 \end{eqnarray*}
and so
 \begin{eqnarray*}
-\varphi e_7&=&\varphi[e_1,e_4]=[a_1f_4+a_2f_5+a_3f_6,e_4]
   -\Bigr[e_1,s_1^{-1}\bigl((b_2+c_3)f_1+b_1f_2+c_1f_3\bigr)\Bigl]\\
  &=& \left(a_1+\frac{b_2+c_3}2\right)H_1-\frac{b_2+c_3}2\frac{s_2}{s_1}H_2
  -\frac{b_2+c_3}2\frac{s_3}{s_1}H_3,\\
-\varphi e_7&=&\varphi[e_2,e_5]=[b_1f_4+b_2f_5+b_3f_6,e_5]
   -\Bigr[e_2,s_2^{-1}\bigl(a_2f_1+(a_1+c_3)f_2+c_2f_3\bigr)\Bigr]\\
  &=& -\frac{a_1+c_3}2\frac{s_1}{s_2}H_1+\left(b_2+\frac{a_1+c_3}2\right)H_2
  -\frac{a_1+c_3}2\frac{s_3}{s_2}H_3,\\
-\varphi e_7&=&\varphi[e_3,e_6]=[c_1f_4+c_2f_5+c_3f_6,e_6]
   -\Bigl[e_3,s_3^{-1}\bigl(a_3f_1+b_3f_2+(a_1+b_2)f_3\bigr)\Bigr]\\
  &=& -\frac{a_1+b_2}2\frac{s_1}{s_3}H_1-\frac{a_1+b_2}2\frac{s_2}{s_3}H_2
  +\left(c_3+\frac{a_1+b_2}2\right)H_3.
 \end{eqnarray*}
This implies $\boxed{\frac{a_1}{s_1}=\frac{b_2}{s_2}=\frac{c_3}{s_3}}$ and we continue:
 \begin{eqnarray*}
0&=&\varphi[e_1,e_5]=[\varphi e_1,e_5]-[e_1,\varphi e_5]=
   \frac{a_2}{2s_2}\left(s_1H_1+s_2H_2-s_3H_3\right)\Rightarrow\boxed{a_2=0},\\
0&=&\varphi[e_1,e_6]=[\varphi e_1,e_6]-[e_1,\varphi e_6]=
   \frac{a_3}{2s_3}\left(s_1H_1-s_2H_2+s_3H_3\right)\Rightarrow\boxed{a_3=0},\\
0&=&\varphi[e_2,e_4]=[\varphi e_2,e_4]-[e_2,\varphi e_4]=
   \frac{b_1}{2s_1}\left(s_1H_1+s_2H_2-s_3H_3\right)\Rightarrow\boxed{b_1=0},\\
0&=&\varphi[e_2,e_6]=[\varphi e_2,e_6]-[e_2,\varphi e_6]=
   \frac{b_3}{2s_3}\left(-s_1H_1+s_2H_2+s_3H_3\right)\Rightarrow\boxed{b_3=0},\\
0&=&\varphi[e_3,e_4]=[\varphi e_3,e_4]-[e_3,\varphi e_4]=
   \frac{c_1}{2s_1}\left(s_1H_1-s_2H_2+s_3H_3\right)\Rightarrow\boxed{c_1=0},\\
0&=&\varphi[e_3,e_5]=[\varphi e_3,e_5]-[e_3,\varphi e_5]=
   \frac{c_2}{2s_2}\left(-s_1H_1+s_2H_2+s_3H_3\right)\Rightarrow\boxed{c_2=0}.
\end{eqnarray*}
We conclude that $\pr_3(\fm)=\langle s_1 f_4\otimes\omega^1+s_2 f_5\otimes \omega^2+s_3 f_6\otimes\omega^3\rangle=\fg_3$.

\medskip

Finally, consider $\pr_4$.
We have $\fg_3\otimes\fg_{-1}^\ast=\CC^{0|1}\otimes\CC^{0|3}=\CC^{3|0}$.
If $\varphi=f_7\otimes(a\omega^1+b\omega^2+c\omega^3)\in\pr_4(\fm)\subset\fg_3\otimes\fg_{-1}^\ast$, then:
 \begin{eqnarray*}
s_3\varphi e_6 &=&\varphi[e_1,e_2]=[\varphi e_1,e_2]+[e_1,\varphi e_2]=[af_7,e_2]+[e_1,bf_7]=as_2f_5+bs_1f_4,\\
s_2\varphi e_5 &=&\varphi[e_1,e_3]=[\varphi e_1,e_3]+[e_1,\varphi e_3]=[af_7,e_3]+[e_1,cf_7]=as_3f_6+cs_1f_4, \\
s_1\varphi e_4 &=&\varphi[e_2,e_3]=[\varphi e_2,e_3]+[e_2,\varphi e_3]=[bf_7,e_3]+[e_2,cf_7]=bs_3f_6+cs_2f_5,
 \end{eqnarray*}
whence
 \begin{eqnarray*}
0&=&\varphi[e_1,e_5]=[af_7,e_5]+[e_1,s_2^{-1}(as_3f_6+cs_1f_4)]=a\frac{s_1}{s_2}f_2\Rightarrow\boxed{a=0}, \\
0&=&\varphi[e_2,e_4]=[bf_7,e_4]+[e_2,s_1^{-1}(bs_3f_6+cs_2f_5)]=b\frac{s_2}{s_1}f_1\Rightarrow\boxed{b=0}, \\
0&=&\varphi[e_3,e_4]=[cf_7,e_4]+[e_3,s_1^{-1}(bs_3f_6+cs_2f_5)]=c\frac{s_3}{s_1}f_1\Rightarrow\boxed{c=0}.
 \end{eqnarray*}
We conclude that $\pr_4(\fm)=\fg_4=0$, which finishes the proof. \hfill\qed



