 \begin{proposition}
For the contact grading of $\fg=D(2,1;a)$ associated with $\fp_1^\I$:
 \begin{equation*}
H^{d,1}(\mathfrak{m},\mathfrak{g}) = 
\Big\{\begin{array}{lr} 0 & d\neq 1,\\
\UU_{1,1}[1] & d=1. \end{array}
 \end{equation*}
\end{proposition}

 \begin{proof}
By Proposition \ref{H0H1H2}, $H^1(\fm,\fg)=E_2^{1,0}\oplus E_3^{0,1}$. From the previous computations we get
$E_2^{1,0}=\UU_{1,1}[1]$, $E_3^{0,1}\subset\VV_{2,0}[2]\oplus\VV_{0,2}[2]$. Thus, we need to compute 
the differential $\partial:E_2^{0,1}\longrightarrow E_2^{2,0}$ on $\VV_{2,0}[2]$ and $\VV_{0,2}[2]$.

A lowest weight vector of $\VV_{2,0}[2]$ is $\varphi=[Y_2\otimes\omega^5]$. 
Since $\partial\varphi= \partial Y_2\wedge\omega^5+[Y_2]\otimes\partial\omega^5$ and 
$\partial\omega^5=s_1\omega^1\wedge\omega^4-s_1\omega^2\wedge\omega^3$, we have
 \[
\partial\varphi(e_1,e_4)=s_1[Y_2]\neq0,
 \]
and therefore $\VV_{2,0}[2]\not\subset E_3^{0,1}$ and $\VV_{2,0}[2]\not\subset E_3^{2,0}$ by 
Lemma \ref{Arep} with $s=2$.

Similarly, a lowest weight vector of $\VV_{0,2}[0]$ is $\psi=[Y_3\otimes\omega^5]$, so we have
 \[
\partial\psi(e_1,e_4)=s_1[Y_3]\neq0\\
 \]
and therefore $\VV_{0,2}[2]\not\subset E_3^{0,1}$ and $\VV_{0,2}[2]\not\subset E_3^{0,2}$.

Lastly, by Proposition \ref{H0H1H2}, we get $H^1(\fm,\fg)=E_2^{1,0}\oplus E_3^{0,1}=\UU_{1,1}[1]$.
 \end{proof}

 \begin{proposition}
For the contact grading of $\fg=D(2,1;a)$ associated with $\fp_1^\I$:
 \begin{equation*}
H^{d,2}(\mathfrak{m},\mathfrak{g}) = 
\Big\{ \begin{array}{lr} 0 & d\neq 2,\\ \VV_{2,2}[2] & d=2. \end{array}
 \end{equation*}
 \end{proposition}

 \begin{proof}
By lemma \ref{H1H2}, $H^2(\fm,\fg)=E_3^{2,0}\oplus E_3^{1,1}\oplus E_4^{0,2}$. 
The previous computations tell us $E_2^{0,2}=0$, $E_3^{1,1}\subset\UU_{3,1}[3]\oplus\UU_{1,3}[3]\oplus\UU_{1,1}[3]$, $E_3^{0,2}\subset\VV_{2,2}[2]$.
 \begin{itemize}
\item The lowest weight vector of $\UU_{3,1}[3]$ is $\varphi=[Y_2\otimes\omega^5]\otimes\omega^1$, so
 \[
\partial \varphi(e_1,e_4,e_1)= s_1[Y_2]\neq0
 \]
and therefore $\UU_{3,1}[3]\not\subset E_3^{1,1}$.
\item Similarly, $\UU_{1,3}[3]\not\subset E_3^{1,1}$
\item The highest weight vectors of $\UU_{1,1}[3]$ are of the form
 \[
\phi=a\left([H_2\otimes\omega^5]\otimes\omega^1+2[ Y_2\otimes\omega^5]\otimes\omega^2\right)+b\left([H_3\otimes\omega^5]\otimes+2[ Y_3\otimes\omega^5]\otimes\omega^3\right),
 \]
so we compute $\partial\phi(e_1,e_4,e_1)= a[H_2]+b[H_3]$.
 \end{itemize}

We can obtain the $E_3$-page in Table \ref{table:DE3}:
 \begin{table}[h!]\[
\begin{array}{|c|c|c|c|}\hline
0 & 0 &  &\\ \hline 
0 & 0 & * & \\ \hline
0 & \UU_{1,1}[1] & \VV_{2,2}[2] & * \\ \hline
 \end{array}\]
\caption{The $E_3$-page: the modules $E_3^{p,q}$ for $p+q\leq3$ and $0\leq d\leq5$.}\label{table:DE3}
 \end{table}

Lastly, since $H^2(\fm,\fg)=E_3^{2,0}\oplus E_3^{1,1}\oplus E_4^{0,2}$ by \eqref{H1H2}, 
so $H^2(\fm,\fg)=\VV_{2,2}[2]$.
 \end{proof}

This finishes the computation of generalized Spencer cohomology $H^d(\fm,\fg)$ in degrees $d\leq2$ for the 
$\fp_1^\I$ grading of $\fg=D(2,1;a)$. The other five gradings, displayed in Table \ref{SpH} of the Introduction, 
are obtained by similar but longer computations (though $H^0=\fg_{-\nu}$ is straightforward). 
We made an independent computer verification in each case.


