\section{Proofs}
\label{sec:appendix}

We build on \cite{casarin2018uncertainty} and apply their results to our proposed PRUMIDAS model.


We denote $\by_{g,t+h-1}\equal(y_{g,t+h-1}\comma\ldots\comma y_{g,t+h-A})^{\prime}$ as the vector of lagged values of the high-frequency dependent variable, $\bx_{gj,t+h_j} = (x_{gj,t+h_j},\ldots,x_{gj,t+h_j-B_jH_j}\rightbr^{\prime}$ as the vector of lagged values of either high- or low-frequency covariates, depending on the value of $H_j$ and $h_j$, as defined in Section~\ref{sec:Notation}.
We define $\bz_{g,t+h} = \leftbr1,\by_{g,t+h-1}^{\prime}\comma\bx_{g1,t+h_1}^{\prime}\comma\ldots\comma\bx_{gN,t+h_N}^{\prime}\rightbr^{\prime}$ as the vector including both the autoregressive high-frequency and lagged covariates at both frequency. 

Moreover, let $L = \bigl(1+A+\sum_{j=1}^{N}(1+B_j)\bigr)$ be the size relative to the number of covariates included in the model. Then, denote as $\bgamma = \leftbr \mu,\balpha^{\prime},\bbeta_{1}^{\prime}\comma\ldots\comma\bbeta_{N}^{\prime})^{\prime}$ the $L-$vector of common effects, including the common intercept and common coefficients, $\balpha = (\alpha_{1}\comma\ldots\comma\alpha_{A})^{\prime}$ and $\bbeta_{j} = \leftbr \beta_{j0}, \beta_{j1}\comma\ldots\comma\beta_{jB_j}\rightbr^{\prime}$. 
Let $\bpsi_{h} = (\psi_{\mu,h}\comma\bpsi_{\alpha,h}^{\prime}\comma\bpsi_{\beta,1h}^{\prime}\comma\ldots\comma\bpsi_{\beta,Nh}^{\prime}\rightbr^{\prime}$ be the $L-$vector of hourly random effects, with $\bpsi_{\alpha,h} = \leftbr\psi_{\alpha,h1}\comma\ldots\comma\psi_{\alpha,hA}\rightbr^{\prime}$ be a $A$-vector and $\bpsi_{\beta,jh} = \leftbr\psi_{\beta,jh0}\comma\ldots\comma\psi_{\beta,jhB_j}\rightbr^{\prime}$ a $(1+B_j)$-vector for $j=1,\ldots,N$. 
Then, let $\bzeta_{g} = (\zeta_{\mu,g},\bzeta_{\alpha,g}^{\prime},\bzeta_{\beta,g1}^{\prime},\ldots,\bzeta_{\beta,gN}^{\prime}\rightbr^{\prime}$ the $L-$vector of country random effects, where $\bzeta_{\alpha,g} = \leftbr\zeta_{\alpha,g1},\ldots,\zeta_{\alpha,gA}\rightbr^{\prime}$ is $A$--vector and $\bzeta_{\beta,gj} = \leftbr\zeta_{\beta,gj0}\comma\ldots\comma\zeta_{\beta,gjB_j}\rightbr^{\prime}$ is $(1+B_j)$--vector for $j=1,\ldots,N$.

\begin{proposition}
\label{sec:appendix:propA1}
Based on the previous definitions, the model in Eq.~\eqref{sec:method:second-eq} can be expressed in stacked form as
\begin{equation}
    \label{sec:appendix:eqA1}
    y_{g,t+h} = \bz_{g,t+h}^{\prime}(\bgamma+\bzeta_{g}+\bpsi_{h}) + e_{g,t+h}.
\end{equation}
where $\bgamma$, $\bzeta_{g}$, and $\bpsi_h$ are the vectors of common, country, and hourly random effects, respectively.
\end{proposition}

\begin{proof}
Substitute the coefficients in Eq.~\eqref{sec:method:first-eq} with their specifications in Eq.~\eqref{sec:method:cere}:
\begin{align*}
    y_{g,t+h} 
    &= \bigl(\mu+\psi_{\mu,h}+\zeta_{\mu,g}\bigl)
    +\sum_{a=1}^{A}\bigl(\alpha_{a}+\psi_{\alpha,ha}+\zeta_{\alpha,ga}\bigl)y_{g,t+h-a} \\
    &+\sum_{j=1}^{N}\sum_{b=0}^{B_j}\bigl(\beta_{jb}+\psi_{\beta,jhb}+\zeta_{\beta,gjb}\bigl)x_{gj,t+h_j-bH_j}+e_{g,t+h}.
\end{align*}
Finally, re-write the summations in vector form, as introduced in the preamble:
\begin{align*}
    y_{g,t+h}
    &= \bigl(\mu+\psi_{\mu,h}+\zeta_{\mu,g}\bigl)
    +\bigl(\balpha+\bpsi_{\alpha,h}+\bzeta_{\alpha,g}\bigl)\by_{g,t+h-1}  \\
    &+\sum_{j=1}^{N}\bigl(\bbeta_{j}+\bpsi_{\beta,jh}+\zeta_{\bbeta,gh}\bigl)x_{gj,t+h_j}+e_{g,t+h} \\
    &= \bz_{g,t+h}^{\prime}\bigl(\bgamma+\bpsi_{h}+\bzeta_{g}\bigl)+e_{g,t+h}.
\end{align*}
\end{proof}

\begin{proposition}
\label{sec:appendix:propA2}
The stack-form model in Eq.~\eqref{sec:appendix:eqA1} admits a ``low-frequency'' panel vector autoregressive representation as
\begin{equation}
\label{sec:appendix:eqA2}
    \by_{gt} = Z_{gt}\bigl(\bgamma+\bzeta_{g}\bigl)+\diag\bigl(Z_{gt}\Psi^{\prime}\bigl)+\be_{gt},
\end{equation}
where $Z_{gt} = \leftbr\bz_{g,t+0}\comma,\ldots,\comma\bz_{g,t+H-1}\rightbr^{\prime}$ and $\Psi = \leftbr\bpsi_0\comma,\ldots\comma\bpsi_{H-1}\rightbr^{\prime}$ are matrices of size $H\times L$, $\by_{gt} = \leftbr y_{g,t+0},\ldots,y_{g,t+H-1}\rightbr$, and $\be_{gt} \sim \mathcal{N}_H(0,\Sigma_g)$ with $\Sigma_g = \diag(\sigma_{g,0}^2,\ldots, \sigma_{g,H-1}^2)$.
\end{proposition}

\begin{proof}
Let us stack Eq.~\eqref{sec:appendix:eqA1} for $h=1,\ldots,H-1$ to obtain a system of equations. 
Then, let $\Psi$ be such that $( \bz_{g,t+0}^{\prime}\bpsi_0,\ldots,\bz_{g,t+H-1}^{\prime}\bpsi_{H-1}\rightbr = \leftbr Z_{gt}\Psi^{\prime}\rightbr\odot I_{H} = \diag\leftbr Z_{gt}\Psi^{\prime}\rightbr$ is a $H\times 1$ vector.
Please refer to \cite{magnus2019matrix}, page 52, for the properties of the Hadamard product, denoted by $\odot$.
Therefore, from Eq.~\eqref{sec:appendix:eqA1} it follows that
\begin{equation*}
    \by_{gt} = Z_{gt}\bigl(\bgamma+\bzeta_{g}\bigl)+\diag\bigl(Z_{gt}\Psi^{\prime}\bigl)+\be_{gt},
\end{equation*}
where $\be_{gt}=\leftbr e_{g,t+0},\ldots,e_{g,t+H-1})^{\prime}$ and $\be_{gt}\sim\mathcal{N}_{H}\leftbr 0,\Sigma_{g})$ with $\Sigma_{g} = \diag(\sigma_{g,0}^2\comma\ldots,\sigma_{g,H-1}^2)$, where $\mathcal{N}_{H}$ denotes the $H$-dimensional multivariate normal distribution.
\end{proof}


Following Section~\ref{sec:model:common-random-effects}, we assume that $\bpsi_{h}\sim\mathcal{N}_{L}\leftbr \mathbf{0}_{L},Q)$ and $\bzeta_{g}\sim\mathcal{N}_{L}\leftbr \mathbf{0}_{L},R)$, where $Q = \diag\{\bigl\leftbr q_{\mu},\biota_{A}^{\prime}\otimes q_{\alpha},\biota_{N\sum_j(1+B_j)}^{\prime}\otimes q_{\beta}\bigr\rightbr^{\prime}\}$, 
$R = \diag\{\bigl\leftbr r_{\mu},\biota_{A}^{\prime}\otimes r_{\alpha},\biota_{N\sum_j(1+B_j)}^{\prime}\otimes r_{\beta}\bigr\rightbr^{\prime}\}$, and $\biota_A^{\prime}$ and $\biota_N^{\prime}$ are the vector of ones of size $A$ and $N$, respectively.
\begin{proposition}
\label{sec:appendix:propA3}
By marginalizing the random effects in Eq.~\eqref{sec:appendix:eqA1}, the model simplifies to
\begin{equation}
\label{sec:appendix:eqA3}
    y_{g,t+h}= \bz_{g,t+h}^{\prime}\bgamma+\Tilde{e}_{g,t+h},
\end{equation}
where $\Tilde{e}_{g,t+h}\sim\mathcal{N}(0,\sigma_{ght}^{2})$, $\sigma_{ght}^{2} = \sigma_{gh}^{2}+ \bz_{g,t+h}^{\prime}(R+Q)\bz_{g,t+h}$.
\end{proposition}

\begin{proof}
Since $e_{g,t+h}$ is normally distributed and conditionally on the coefficients in Eq.~\eqref{sec:appendix:eqA1} it follows that $( y_{g,t+h}|\bgamma,\bpsi_{h},\bzeta_{g}\rightbr\sim\mathcal{N}\bigl\leftbr\bz_{g,t+h}^{\prime}(\bgamma+\bzeta_{g}+\bpsi_{h}),\sigma_{gh}^{2}\bigr\rightbr$. Thus, using the moment generating function, we can integrate out the random effects and obtain the marginal density of $y_{g,t+h}|\bgamma$ as follows:
\begin{align*}
    \Ev\bigl(\exp\{\theta y\}\bigl) &= \int \exp\{\theta y\} f(y|\bgamma)\,dy \\
    &= \int \exp\{\theta y\} f\bigl(y|\bgamma,\bpsi_{h},\bzeta_{g}\bigl)f(\bzeta_{g})f(\bpsi_{h})\,dy\,d\bpsi_{h}\,d\bzeta_{g} \\    
    &= \int \exp\Bigl\{\theta\bigl[\bz_{g,t+h}^{\prime}\bigl(\bgamma+\bpsi_{h}+\bzeta_{g}\bigl)\bigl]+\frac{1}{2}\theta^{2}\sigma_{gh}^{2}\Bigl\} f(\bpsi_{h})\,f(\bzeta_{g})\,d\bpsi_{h}\,d\bzeta_{g} \\
    &= \exp\Bigl\{\theta\bz_{g,t+h}^{\prime}\bgamma\Bigl\}\exp\Bigl\{\theta\bigl[\bz_{g,t+h}^{\prime}(\bpsi_{h}+\bzeta_{g}\bigl]+\frac{1}{2}\theta^2\sigma_{gh}^{2}\Bigl\} \\
    &= \exp\Bigl\{\theta\bz_{g,t+h}^{\prime}\bgamma\Bigl\}\exp\Bigl\{\frac{1}{2}\theta^{2}\bigl(\sigma_{gh}^{2}+\bz_{g,t+h}^{\prime}(Q+R)\bz_{g,t+h}\bigl)\Bigl\}
\end{align*}
which is the moment generating function of normal random variable with mean $\bz_{g,t+h}^{\prime}\bgamma$ and variance $\sigma_{ght}^{2} = \sigma_{gh}^{2}+ \bz_{g,t+h}^{\prime}(R+Q)\bz_{g,t+h}$. 

Additionally, this result can be applied to Eq.~\eqref{sec:appendix:eqA3} since it is a stacked version of Eq.~\eqref{sec:appendix:eqA2}. Hence, it follows that $\by_{gt}|\bgamma$ is normally distributed with mean $\bm{z}'_{g,t+h}\bgamma$ and variance $\Sigma_{gt} = \diag(\sigma_{g0t}^2\comma\ldots,\sigma_{g(H-1)t}^2)$.
\end{proof}

