\section{Prof of Proposition 1 \label{A}}
Before presenting the proof, we provide a formula for describing the dynamic evolution of the $m$-th moment. To achieve this, we use the master equation and define \(\eta_j^r = (S_{j}^r - \braket{S_{j}^r})\), leading to the following expression only for reactions:  

{\tiny
\begin{align}
    &\frac{\partial M^m_{j_1^{r_1}, j_2^{r_2}, \dots , j_m^{r_m}}}{\partial t}= \frac{\Omega}{\Omega^m} \sum_i \sum_r \langle \left( (\eta_{j_1}^{r_1} + \Gamma_{j_1i}^{r_1} ) (\eta_{j_2}^{r_2} + \Gamma_{j_2i}^{r_2} ) \dots (\eta_{j_m}^{r_m} + \Gamma_{j_m i}^{r_m} ) - (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_m}^{r_m} )  \right) a_i^r(\mathbf{S})   \rangle \nonumber \\
    =& \frac{\Omega}{\Omega^m} J^m \left(\sum_i \sum_r \langle \left( (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-1}}^{r_{m-1}} ) \Gamma_{j_mi}^{r_m} \delta_{r_m,r}  +  (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-2}}^{r_{m-2}} ) \Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m} \delta_{r_{m-1},r_m,r}  +...+ \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \right) a_i^r(\mathbf{S})   \rangle \right), \label{a.1}
\end{align}}

where $J^m$ represents the permutation of all $m$ free indices. If all of the reactions that have the system are until order one, then the propensity rates are 
\begin{align}
    a_i^r(\mathbf{S})= k_i^{r} \prod_j \left( \frac{S_j^r}{\Omega} \right)^{\alpha_{ij}}, 
\end{align}
from which we obtain the deterministic rates exactly as
\begin{align}     
R_i^r(\mathbf{s})= \frac{a_i^r(\braket{\mathbf{S}})}{k_i^{r}}=  \prod_{j=1}^{N} (s_j^r)^{\alpha_{ij}}, 
\end{align} 
then, making a Taylor expansion of it around the mean, we get

{\footnotesize
\begin{align}
    a_i^r(\mathbf{S}^r)= a_i^r(\braket{\mathbf{S}^r}) + \sum_j \eta_j^r \frac{\partial a_i^r(\braket{\mathbf{S}^r})}{\partial S_j^r} = k_i^{r} \left( R_i^r(\mathbf{s}^r) + \sum_j  \frac{\eta_j^r}{\Omega} \frac{\partial R_i^r(\mathbf{s}^r)}{\partial s_j^r} \right),
\end{align}}
note, that this expansion is exact because $R_i^r(\mathbf{s})$ is linear. Now we use this result in Equation (\ref{a.1}), then we get 


{\tiny
\begin{align}
   & \frac{\partial M^m_{j_1^{r_1}, j_2^{r_2}, \dots , j_m^{r_m}}}{\partial t}= \frac{\Omega}{\Omega^m} J^m \left(\sum_i \sum_r \langle \left( (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-1}}^{r_{m-1}} ) \Gamma_{j_mi}^{r_m} \delta_{r_m,r}  +   (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-2}}^{r_{m-2}} ) \Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m} \delta_{r_{m-1},r_m,r}  +...+ \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \right) a_i^r(\mathbf{S})   \rangle \right)\nonumber \\
    =& \frac{\Omega}{\Omega^m} J^m \left(\sum_i \sum_r \langle \left( (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-1}}^{r_{m-1}} ) \Gamma_{j_mi}^{r_m}\delta_{r_m,r}  +  (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-2}}^{r_{m-2}} ) \Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m} \delta_{r_{m-1},r_m,r} + \dots + \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \right) k_i^{r} \left( R_i^r(\mathbf{s})  + \sum_j  \frac{\eta_j^r}{\Omega} \frac{\partial R_i^r(\mathbf{s})}{\partial s_j^r} \right)   \rangle  \right) \nonumber \\
    =& \frac{\Omega}{\Omega^m} J^m \left(\sum_i \sum_r \langle \left( (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-1}}^{r_{m-1}} ) \Gamma_{j_mi}^{r_m}\delta_{r_m,r}  +  (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-2}}^{r_{m-2}} ) \Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m} \delta_{r_{m-1},r_m,r} + \dots + \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \right) \left( k_i^{r} R_i^r(\mathbf{s}) \right)   \rangle  \right) \nonumber \\ 
    +& \frac{1}{\Omega^m} J^m \left(\sum_i \sum_j \sum_r \langle \left( (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-1}}^{r_{m-1}}\eta_j^r ) \Gamma_{j_mi}^{r_m}\delta_{r_m,r} +  (\eta_{j_1}^{r_1} \eta_{j_2}^{r_2} \dots \eta_{j_{m-2}}^{r_{m-2}} \eta_j^r ) \Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m}\delta_{r_{m-1},r_m,r} + \dots + \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \eta_j^r \right) \left( k_i^{r}  \frac{\partial R_i^r(\mathbf{s})}{\partial s_j^r} \right)   \rangle  \right) \nonumber \\ 
    =&    J^m \left(\sum_i \sum_r \left( M^{m-1}_{j_1^{r_1}, j_2^{r_2}, \dots j_{m-1}^{r_{m-1}}} {\Gamma_{j_mi}^{r_m}\delta_{r_m,r}}  +  M^{m-2}_{j_1^{r_1}, j_2^{r_2}, \dots j_{m-2}^{r_{m-2}}} \frac{\Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m} \delta_{r_{m-1},r_m,r}}{\Omega}  + \dots + \frac{\delta_{r_1, r_2, \dots,r_m,r}}{m \Omega^{m-1}} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_mi}^{r_1} \right) \left( k_i^{r} R_i^r(\mathbf{s}) \right)    \right) \nonumber \\  
    +&  J^m \left(\sum_i \sum_j \sum_r  \left( M^{m}_{j_1^{r_1}, j_2^{r_2}, \dots j_{m-1}^{r_{m-1}},j^r} {\Gamma_{j_mi}^{r_m}\delta_{r_m,r}} +  M^{m-1}_{j_1^{r_1}, j_2^{r_2}, \dots j_{m-2}^{r_{m-2}},j^r} \frac{\Gamma_{j_{m-1}i}^{r_m} \Gamma_{j_mi}^{r_m}\delta_{r_{m-1},r_m,r}}{\Omega}  + \dots + \frac{\delta_{r_1, r_2, \dots,r_m,r}}{\Omega^{m-1}} \Gamma_{j_1i}^{r_1} \Gamma_{j_2i}^{r_1} \dots \Gamma_{j_{m-1}i}^{r_1} M^2_{j_m^{r_1}, j^r}  \right) \left( k_i^{r}   \frac{\partial R_i^r(\mathbf{s})}{\partial s_j^r} \right)  \right), 
\end{align}}

this result demonstrates that until first-order reactions occur, the temporal derivation of the $m$-th moment depends only on the $m$-th moment. Following a method similar to the diffusion part, Proposition 1 is proved.   

\section{Prof of Proposition 5 \label{B}} 
\textbf{Proof.:}\\    
First, we have $\alpha_{ij}^r \leq 1$, yielding the next propensity rates  
\begin{align}  
a_i^r(\mathbf{S}^r) &= k_i^{r} \prod_{j=1}^{N} \frac{S_j^r !}{\Omega^{\alpha_{ij}}(S_j^r - \alpha_{ij})!} = k_i^{r}  \prod_{j=1}^{N} \left( \frac{S_j^r}{\Omega} \right)^{\alpha_{ij}^r},
\end{align}  
from which we obtain the deterministic rates exactly as 
\begin{align}     
R_i^{r}(\mathbf{s}^r)= \frac{a_i^r(\braket{\mathbf{S}^r})}{k_i^{r}}= \prod_{j=1}^{N} (s_j^r)^{\alpha_{ij}^r}.  
\end{align} 
It is important to observe that each mean concentration $s_j^r$ appears up to exponent 1 because $\alpha_{ij}^r \leq 1$, and the second derivations according to the following conditions are 
\begin{align}  
\frac{\partial^m R_i^{r}(\mathbf{s}^r)}{ \partial s_{j_1}^{r} \partial s_{j_2}^{r}... \partial s_{j_m}^{r}} =  
\begin{cases}         
\neq  0 & \text{if } m=1 \text{ or }j_1 \neq j_2 \neq ... \neq j_m  \\         0 & \text{other cases}    
\end{cases}  , \label{b.3} 
\end{align} 
However, because all variables are independent, the covariance between the chemical species in the stationary state follows the following conditions uncorrelated:
\begin{itemize}
    \item  In the same voxel $r$: \\
      \begin{align}     
      M^{m}_{j_1^{r},j_2^{r}, ... , j_m^{r} }=   
      \begin{cases}         
       \neq 0 & \text{if } m \geq 2 \text{ and } j_1 = j_2= ...=j_m \\
       0 & \text{other cases}    \label{b.4}  
\end{cases} . 
\end{align}
    \item For two arbitrates voxels $r_1$ and $r_2$:\\
    {\small
    \begin{align}     
     M^{m+1}_{j_1^{r_1},j_2^{r_1}, ... , j_m^{r_1},l_2^{r_2} }=      
     \begin{cases}         
      \neq 0 & \text{if } m \geq 1 \text{ and } j_1 = j_2= ...=j_m=l_2 \\ 
        0 & \text{other cases}      
     \end{cases} . \label{b.5}
\end{align}} \\ 
\end{itemize}
now considering Equations (\ref{b.3})-(\ref{b.5}), we get 
\begin{align}
    M^m_{j_1^{r},j_2^{r}, ... , j_m^{r}}  \frac{\partial^m R_i^{r}(\mathbf{s}^r)}{ \partial s_{j_1}^{r} \partial s_{j_2}^{r}... \partial s_{j_m}^{r}}  &= 0 \text{ for any } m, \nonumber \\
    M^{m+1}_{j_1^{r_1},j_2^{r_1}, ... , j_m^{r_1},l_2^{r_2}}  \frac{\partial^m R_i^{r}(\mathbf{s}^r)}{ \partial s_{j_1}^{r_1} \partial s_{j_2}^{r_1}... \partial s_{j_m}^{r_1}}   &= 0 \text{ if } m\geq 2, \label{b.6}
\end{align}

Because the reaction network is a steady state, then the temporal derivatives in Equations (\ref{13}) and (\ref{14}) are zero, and considering Equations (\ref{b.6}), we get


\begin{align}     
\frac{\partial s_l^r }{\partial{t}}= 0 & =  \sum_{i} \Gamma_{li}^r  k_i^{r} R_i^{r}(\mathbf{s}^r)  +  \sum_q  \left(  d_{qr}^{l} {s_l^q} - d_{rq}^{l} {s_l^r} \right), \nonumber \\
\frac{\partial M^2_{{l}^{r_1}, {l}^{r_2}}}{\partial{t}}= 0  & = \sum_{i} \left( \delta_{r_1,r_2} \frac{\Gamma_{l i}^{r_1} \Gamma_{l i}^{r_1}}{\Omega} k_i^{r_1}R_i^{r_1}(\mathbf{s}^{r_1})  \right. \nonumber \\ 
& +  \left.  \left( M^2_{{l}^{r_1}, {l}^{r_2}} \Gamma_{l i}^{r_2}  k_i^{r_2} \frac{\partial R_i^{r_2}(\mathbf{s}^{r_2})}   {\partial {s_{l}^{r_2}}}  + M^2_{{l}^{r_1}, {l}^{r_2}} \Gamma_{l i}^{r_1}k_i^{r_1} \frac{\partial R_i^{r_1}(\mathbf{s}^{r_1})}{\partial {s_{l}^{r_1}}} \right)  \right) \nonumber \\
&+  \frac{1}{\Omega} \left( \delta_{r_1,r_2} \sum_q \left( d_{q r_1}^{l} s_{l}^{q} + d_{r_1 q}^{l} s_{l}^{r_1} \right) -(d_{r_1 r_2}^{l} s_{l}^{r_1} + d_{r_2 r_1}^{l} s_{l}^{r_2}) \right) \nonumber \\
&+  \sum_q \left( d_{q{r_1}}^{l} M^2_{l^{q},l^{r_2}}  - d_{{r_1}q}^{l} M^2_{l^{r_1},l^{r_2}} \right) +  \sum_q \left( d_{sr_2}^{l} M^2_{l^{r_1},l^{q}}  -d_{r_2s}^{l} M^2_{l^{r_1},l^{r_2}}  \right),  
\end{align}

where $R_i^{r}(\mathbf{s}^{r})= \prod_j (s_j^r)^{\alpha_{ij}^r}$. $\qed $

This result confirms Proposition 5.


\section{Hill Function \label{C}}
In this section, we derive the Hill function, and we base this derivation on \cite{Manuel, Decimal}. For this, we suppose that we have the following reactions 
\begin{eqnarray}
    R+nL \stackbin[k_{-}]{k_{+}}{\rightleftarrows} RL_n, \nonumber \\
    0 \stackbin[k_1]{k_2}{\rightleftarrows} L,
\end{eqnarray}
The first reaction is the binding of $n$ ligands $L$ to receptor $R$ in a reversible process to form complex $RL_n$. We purposely wrote the last reaction because $L$ may be subject to other reactions, and this reaction is a birth-death process that synthesizes and degrades ligands. The stoichiometric coefficients and the stoichiometric matrix are, 

\begin{align}
 \alpha_{ij}&= \begin{pmatrix}
		n& 1 & 0 \\
            0& 0 & 1  \\
            0& 0 & 0  \\
            1& 0 & 0
	\end{pmatrix} ,    &
 \beta_{ij}&=  \begin{pmatrix}
		0& 0 & 1 \\
            n& 1 & 0  \\
            1& 0 & 0  \\
            0& 0 & 0 
	\end{pmatrix}, \nonumber \\
 \Gamma_{ij}&= \begin{pmatrix}
		-n & n & 1 & -1 \\
		-1 & 1 & 0 & 0 \\
		1  & -1 & 0 & 0 
	\end{pmatrix}. \label{c.1}
\end{align}
Let $L, R, S$ be the number of molecules of $L, R, RL_n$ respectively. Thus, the propensity rates for getting the Hill functions are
\begin{align}
    a_1= k_{+} R \frac{L!}{(L-n)!} \frac{1}{\Omega^{n+1}}, & a_2=& k_{-} S\frac{1}{\Omega},     \label{c.2}
\end{align}
there is a conservative quantity $R+S=R_0$, the number of initial receptors, then the previous equations are reduced to 
\begin{align}
    a_1&= k_{+} (R_0-S) \frac{L!}{(L-n)!} \frac{1}{\Omega^{n+1}}, & a_2=& k_{-} S\frac{1}{\Omega},     \label{c.3}
\end{align}
and 
\begin{align}
     \Gamma'_{ij}&= \begin{pmatrix}
		-n & n & 1 & -1 \\
		1  & -1 & 0 & 0 
	\end{pmatrix},  
\end{align}
if we suppose that the first reactions in (\ref{c.1}) are in the stationary state, $S$ and $L$ are independent, then we can use Proposition 3, where the central moments between $S$ and $L$ are zero, then we get the next equation


\begin{align}
    \frac{\partial s}{\partial t}=0 = -k_{-} s + k_{+}(r_0 - s) \frac{1}{\Omega^{n}} \left \langle   \frac{L!}{(L-n)!}  \right \rangle,
\end{align}
where $K^n= \frac{k_{-}}{k_{+}}$,  $r_0=R_0/\Omega$, $s=\braket{S}/\Omega$ and $r=\braket{R}/\Omega$ are the mean concentrations of  $S$ and $R$, from this we get 
\begin{align}
    s= r_0 \frac{\frac{1}{\Omega^{n}}\left \langle   \frac{L!}{(L-n)!}  \right \rangle}{K^n+ \frac{1}{ \Omega^{n}}\left \langle   \frac{L!}{(L-n)!}  \right \rangle}.
\end{align}
If we define the Hill function as follows and substitute $r+s=r_0$ and the value of $s$, we have
\begin{align}
    H=\frac{s}{r+s}= \frac{s}{r_0} = \frac{\frac{1}{\Omega^{n}}\left \langle   \frac{L!}{(L-n)!}  \right \rangle}{K^n+ \frac{1}{ \Omega^{n}}\left \langle   \frac{L!}{(L-n)!}  \right \rangle}, \label{c.5}
\end{align}
now we show some forms of this for some specific cases, we used $l= \braket{L}/\Omega$ and $M^m_{l, l,...,l}= \braket{(L-\braket{L})^m}/\Omega^m$, 
\begin{itemize}
    \item If $n=1$: 
    \begin{align}
        H= \frac{l}{K+ l}.
    \end{align}
    \item If $n=2$:
    \begin{align}
        H= \frac{l^2 + M^2_{l,l} - \frac{l}{\Omega}  }{{K^2} + l^2 + M^2_{l,l} - \frac{l}{\Omega} }.
    \end{align}
    \item If $n=3$:
    \begin{align}
        H= \frac{ (l^3 + 3l M^2_{l,l} + M^3_{l,l,l}) - \frac{3}{\Omega}(l^2 + M^2_{l,l} ) + \frac{2 l }{\Omega^2}}{K^3+ (l^3 + 3l M^2_{l,l} + M^3_{l,l,l}) - \frac{3}{\Omega}(l^2 + M^2_{l,l} ) + \frac{2 l }{\Omega^2} }.
    \end{align}
\end{itemize}
These expressions are exact because we did not make any approximations. All of these equations are for activators, but we can do some similar ones for repressors or only use the relation $D=1-H$.

If, in the stationary state, the distribution of $L$ follows a Poisson distribution given by  
\begin{align}  
P_{ss}(L) = e^{-\braket{L}_{ss}} \frac{\braket{L}_{ss}^L}{L!}, 
\end{align}  
where $\braket{L}_{ss}$ is the mean in the stationary state, and evaluating the Hill function (\ref{c.5}) in the stationary state yields  
\begin{align}    
H = \frac{\frac{\braket{L}_{ss}^n}{\Omega^n}}{K^n + \frac{\braket{L}_{ss}^n}{\Omega^n}} = \frac{l_{ss}^n}{K^n + l_{ss}^n}. 
\end{align}   
This result demonstrates that, in the stationary state, the Hill function with stochastic corrections is identical to the deterministic Hill function.

\section{Non Converge for Oscillations \label{F}}

We repeated the same analysis for the antithetic system and quantified the error at each time point by using Equation (\ref{20}). The parameters were selected such that the system exhibited oscillatory behavior (see Table \ref{tabla20}). The analysis revealed that the error increases, resulting in poor approximation, as shown in Figure \ref{fig.f1}. This is because the oscillations are lost in the stochastic simulations owing to variations in the amplitude and period across individual realizations. Consequently, the moment-closure approach is unsuitable for systems with high-order reactions that oscillate. Further investigation is required to address this limitation.


